def _note_lean_rejected(line: str) -> None:
    """File a post-generation cull and pay the FULL pacing window — a drop means
    the material pool is thin right now; re-rolling it in 20 s is pure spend."""
    global _last_lean_impulse_at
    text = str(line or "").strip()
    if text:
        _lean_rejected_lines.append(text)
    _last_lean_impulse_at = time.monotonic()
# Consecutive lean-impulse lines Rex has spoken into the CURRENT silence with no user reply. Widens
# the required gap each time and caps the run (LEAN_IMPULSE_MAX_UNANSWERED) so he doesn't monologue
# into the void. Reset the instant the user speaks (_begin_user_turn) — a fresh lull gets a fresh run.
_consecutive_lean_impulses: int = 0
_lean_news_mentioned_this_session: bool = False   # one story per session, like the musing
# The story Rex most recently OFFERED in a lull ("did you hear ...?"), kept so a
# follow-up ("tell me more about that") can be answered with the story's actual
# content instead of the bare pronoun (field 2026-08-04 23:09: the follow-up
# turn had no story context, the model hallucinated a text tool tag, and the
# turn died silent). {"headline", "summary", "topic", "at": time.monotonic()}.
_last_news_story_offered: Optional[dict] = None
# Cue-kind cooldowns after a DROPPED generated line (field 2026-08-02 12:38: the
# open-thread cue about "what you and JT do together" won the ladder five times
# in a row, every line was rejected as a re-ask of a recent question, and the
# unspent cue starved news/interest cues for the whole session — no lull line
# ever played). A dropped cue kind sits out LEAN_CUE_DROP_COOLDOWN_SECS.
_lean_cue_cooldowns: dict = {}


def _lean_cue_blocked(kind: str) -> bool:
    return time.monotonic() < float(_lean_cue_cooldowns.get(kind, 0.0))


def _strike_lean_cue(kind: "Optional[str]") -> None:
    if not kind:
        return
    cooldown = float(getattr(config, "LEAN_CUE_DROP_COOLDOWN_SECS", 600.0))
    _lean_cue_cooldowns[kind] = time.monotonic() + cooldown
    _log.info("[lean] cue %r benched for %.0fs after a dropped line", kind, cooldown)


# Cross-day bit cooldown (intelligence/bit_ledger.py). Follow-up-shaped cues are
# exempt from ENFORCEMENT — a remembered "how did the interview go?" is
# attentiveness, not a bit — but everything spoken still gets RECORDED.
_BIT_LEDGER_EXEMPT_CUES = {
    "celebration", "holiday_plan", "event_followup", "open_thread",
    "place_question", "room_question", "workday_checkin",
}


def _bit_ledger_blocks(person_id: "Optional[int]", line: str) -> bool:
    try:
        from intelligence import bit_ledger
        return bit_ledger.is_repeat(person_id, line)
    except Exception as exc:
        _log.debug("[lean] bit ledger check failed: %s", exc)
        return False


