# ─────────────────────────────────────────────────────────────────────────────
# Wake word callback (called from wake_word's background daemon thread)
# ─────────────────────────────────────────────────────────────────────────────

def _on_wake_word(model_name: str) -> None:
    global _last_wake_word
    try:
        current_state = state_module.get_state()
    except Exception:
        current_state = State.IDLE

    # Dedicated "shut down" wake word → immediate shutdown, skipping the VAD/STT path
    # (where "shut down" is often clipped to "down" or dropped) and the LLM farewell.
    # main.py runs the normal shutdown sequence (audio + animation) on the state change.
    shutdown_model = str(getattr(config, "WAKE_WORD_SHUTDOWN_MODEL", "") or "").strip()
    if shutdown_model and model_name == shutdown_model:
        if current_state == State.SHUTDOWN:
            return
        # Confirm the utterance really was a shutdown command before powering off.
        # The acoustic model alone confuses "look down" with "shut down" (it fires
        # at ~0.5-0.8 for both), and unlike every other shutdown route this one was
        # NOT lexically gated. Transcribe ~2s of the rolling buffer (the whole
        # phrase, not a VAD fragment that clips "shut down" to "down") and only shut
        # down if it's an actual standalone shutdown command. Fails safe: an empty
        # or failed transcript is rejected, so an STT outage never powers Rex off.
        if bool(getattr(config, "WAKE_WORD_SHUTDOWN_CONFIRM_ENABLED", True)):
            try:
                secs = float(getattr(config, "WAKE_WORD_SHUTDOWN_CONFIRM_AUDIO_SECS", 2.0))
                recent = stream.get_audio_chunk(secs)
                text = transcription.transcribe(recent) if len(recent) else ""
            except Exception as exc:
                text = ""
                _log.warning("[wake_word] shutdown confirm transcription failed: %s", exc)
            # Homophone-tolerant: the acoustic model already heard the phrase, so
            # a transcript of "Cut down." / "Shot down." confirms rather than
            # vetoes (live 2026-07-30: wake at 0.945, Whisper wrote "Cut down.",
            # Rex quipped instead of powering off). "look down" still rejects.
            if not command_parser.is_shutdown_wake_confirmation(text):
                _log.info(
                    "[wake_word] shut_down wake hit NOT confirmed by transcript %r — "
                    "ignoring (likely 'look down')", text,
                )
                return
            _log.info(
                "[wake_word] shutdown wake word %r confirmed by transcript %r — initiating shutdown",
                model_name, text,
            )
        else:
            _log.info(
                "[wake_word] shutdown wake word %r detected (confirm disabled) — initiating shutdown",
                model_name,
            )
        with _wake_lock:
            _last_wake_word = model_name
        try:
            _interrupted.set()  # cut off any in-progress speech immediately
        except Exception:
            pass
        state_module.set_state(State.SHUTDOWN)
        return

    if current_state == State.SLEEP and model_name != "wakeuprex":
        _log.info(
            "[wake_word] ignored non-sleep wake model while asleep: %s", model_name
        )
        return

    if current_state != State.SLEEP and model_name == "wakeuprex":
        _log.info("[wake_word] ignored sleep-only wake word while not asleep: %s", model_name)
        return

    with _wake_lock:
        _last_wake_word = model_name

    _wake_word_recognition_gesture(model_name)

    if speech_queue.is_speaking():
        if _response_wait_active():
            _log.info(
                "[wake_word] ignored mid-question wake interruption while waiting for response"
            )
        else:
            _interrupted.set()

    _wake_word_fired.set()


def _wake_word_recognition_gesture(model_name: str) -> bool:
    """Trigger a short physical wake-word recognition wave when appropriate."""
    if not bool(getattr(config, "WAKE_WORD_RECOGNITION_GESTURE_ENABLED", True)):
        return False

    allowed = {
        str(item).strip()
        for item in getattr(config, "WAKE_WORD_RECOGNITION_GESTURE_MODELS", [])
        if str(item).strip()
    }
    if allowed and str(model_name).strip() not in allowed:
        return False

    try:
        if state_module.get_state() in (State.QUIET, State.SLEEP, State.SHUTDOWN):
            return False
    except Exception:
        return False

    global _last_wake_word_gesture_at
    cooldown = max(
        0.0,
        float(getattr(config, "WAKE_WORD_RECOGNITION_GESTURE_COOLDOWN_SECS", 1.25) or 0.0),
    )
    now = time.monotonic()
    with _wake_word_gesture_lock:
        if cooldown > 0.0 and now - _last_wake_word_gesture_at < cooldown:
            return False
        _last_wake_word_gesture_at = now

    try:
        from sequences import animations
        return bool(animations.wake_word_ack_wave())
    except Exception as exc:
        _log.debug("[wake_word] recognition gesture failed: %s", exc)
        return False


# ─────────────────────────────────────────────────────────────────────────────
# Speech helpers
# ─────────────────────────────────────────────────────────────────────────────

def _can_speak() -> bool:
    return state_module.get_state() not in (State.QUIET, State.SLEEP, State.SHUTDOWN)


def _dj_is_playing() -> bool:
    try:
        from features import dj as dj_mod
        return bool(dj_mod.is_playing())
    except Exception:
        return False


def _dj_suppresses_conversation() -> bool:
    return (
        bool(getattr(config, "DJ_SUPPRESS_CONVERSATION_DURING_PLAYBACK", True))
        and _dj_is_playing()
    )


def _stop_dj_for_wake() -> bool:
    """Stop DJ playback in response to a wake word so Rex can take a command.

    During playback the conversation loop and the VAD mic feed are intentionally
    suppressed (the music would otherwise self-trigger), which also strands the
    wake word — the user's only recourse was killing the process. The wake word
    is the deliberate override, so stop the track, clear the post-playback
    suppression tail, and let the normal listen loop resume cleanly.

    Returns True if a track was actually stopped.
    """
    stopped = False
    try:
        from features import dj as dj_mod
        if dj_mod.is_playing():
            dj_mod.stop()
            stopped = True
            _log.info("[wake_word] stopped DJ playback for wake-word barge-in")
    except Exception as exc:
        _log.debug("[wake_word] DJ barge-in stop failed: %s", exc)
    if stopped:
        # dj.stop() arms a short post-playback suppression tail; drop it so the
        # wake ack and the user's follow-up command are heard immediately.
        try:
            echo_cancel.clear_suppression_tail()
        except Exception:
            pass
    return stopped


# Commands the restricted during-music listener may execute. Everything else a
# transcript yields during playback (radio announcers, singing along, ordinary
# chatter) is logged and DROPPED — never routed to conversation, memory, or any
# other action.
_DJ_LISTEN_COMMAND_KEYS = {
    "dj_stop", "dj_skip", "volume_up", "volume_down", "shutdown",
}


def _dj_command_listen_available() -> bool:
    """True when Rex can safely keep listening for music commands DURING playback.

    Requires the ReSpeaker's hardware AEC (music routed out the same device is
    cancelled from the mic before we ever see it). Without it, the mic hears
    the speakers directly and VAD would chase the track itself — there the old
    behavior (deaf + wake-word barge-in) remains the safe fallback.
    """
    if not bool(getattr(config, "DJ_COMMAND_LISTEN_ENABLED", True)):
        return False
    try:
        from audio import hardware_aec
        return bool(hardware_aec.is_active())
    except Exception:
        return False


def _dj_command_listen_step(*, allowed_states: tuple[State, ...]) -> None:
    """One restricted listen poll while DJ/radio playback owns the room.

    Live failure 2026-07-30: during radio playback the conversation loop was
    fully suppressed and the only override was a wake word at a RAISED
    threshold — "stop the music", repeated at a turned-down amp, did nothing
    and the owner had to kill the process. This keeps a narrow ear open: VAD on
    the hardware-AEC-cleaned mic, transcribe the segment, and act ONLY on
    music-control/shutdown commands (_DJ_LISTEN_COMMAND_KEYS) — and only when
    the parser matched them EXACTly, since this is the one execution path that
    never reaches _legacy_command_execution_block_reason. Anything else —
    including whatever the radio station says — is dropped with a log line.
    """
    chunk = stream.get_audio_chunk(_CHUNK_SECS)
    if len(chunk) == 0 or not vad.is_speech(chunk):
        _stop_event.wait(_CHUNK_SECS)
        return

    restore_volume = _duck_dj_for_speech()
    try:
        segment = _accumulate_speech(
            time.monotonic(), allowed_states=allowed_states, raw_vad=True
        )
        if segment is None or len(segment) == 0:
            return
        try:
            text = (transcription.transcribe(segment) or "").strip()
        except Exception as exc:
            _log.debug("[dj_listen] transcription failed: %s", exc)
            return
        if not text:
            return
        try:
            match = command_parser.parse(text)
        except Exception:
            match = None
        key = match.command_key if match is not None else None
        if key not in _DJ_LISTEN_COMMAND_KEYS:
            _log.info(
                "[dj_listen] dropped non-command speech during playback: %r (key=%s)",
                text, key,
            )
            return

        # This listener is the ONLY execution path that never reaches
        # _legacy_command_execution_block_reason, so it has to enforce that
        # gate's legacy_fuzzy_disabled rule itself. Fuzzy is whole-utterance edit
        # distance, and a room with a radio playing in it is exactly where near
        # misses arrive: "shot down" (0.89 vs "shut down"), "sun down" (0.82),
        # "powder down" (0.95 vs "power down"), "sit down" (0.82) and "turn it
        # off" (0.84 vs "turn off") ALL resolve to shutdown, which here kills the
        # process with no confirmation. Note "sit down" — the wake-confirm path
        # deliberately excludes that homophone because it may be aimed at a pet
        # (_SHUTDOWN_WAKE_HOMOPHONE_CORES), and the fuzzy lane was handing it back.
        # Real music commands ("stop the music", "skip this song", "turn it down")
        # all match EXACTly, so nothing usable is lost.
        if match.match_type == "fuzzy":
            _log.info(
                "[dj_listen] dropped fuzzy command during playback: %r (key=%s)",
                text, key,
            )
            return

        # Belt-and-braces on the one destructive key in the set: re-verify
        # shutdown against the strict clause-aware matcher before powering off
        # over a track. Every EXACT shutdown phrase in the table passes this
        # ("shut down rex", "turn yourself off", "power off"), so it only ever
        # costs a near-miss.
        if key == "shutdown" and not command_parser.is_shutdown_request(text):
            _log.info(
                "[dj_listen] dropped unverified shutdown during playback: %r", text,
            )
            return

        from features import dj as dj_mod
        _log.info("[dj_listen] executing %s during playback text=%r", key, text)
        if key == "dj_stop":
            dj_mod.stop()
            echo_cancel.clear_suppression_tail()
            _speak_blocking("Music stopped.", emotion="neutral")
        elif key == "dj_skip":
            dj_mod.skip()
        elif key == "volume_up":
            dj_mod.volume_up()
        elif key == "volume_down":
            dj_mod.volume_down()
        elif key == "shutdown":
            dj_mod.stop()
            echo_cancel.clear_suppression_tail()
            # No _interrupted.set() here: the ack just finished speaking and
            # playback is already stopped — nothing is in flight to cut off.
            _speak_blocking("Powering off. Don't have too much fun without me.",
                            emotion="neutral")
            state_module.set_state(State.SHUTDOWN)
    finally:
        _restore_dj_volume(restore_volume)


def _start_dj_after_response(track) -> None:
    """Start DJ playback just after the current spoken response sequence closes."""
    def _play() -> None:
        try:
            from features import dj as dj_mod
            dj_mod.play(track)
        except Exception as exc:
            _log.debug("deferred DJ playback failed: %s", exc)

    delay = max(
        0.05,
        float(getattr(config, "DJ_START_AFTER_TTS_DELAY_SECS", 0.25) or 0.0),
    )
    threading.Timer(delay, _play).start()


def _game_suppresses_conversation() -> bool:
    try:
        from features import games as games_mod
        if hasattr(games_mod, "suppresses_conversation_interruptions"):
            return bool(games_mod.suppresses_conversation_interruptions())
        return bool(games_mod.is_active())
    except Exception:
        return False


def _game_active_for_router() -> bool:
    try:
        from features import games as games_mod
        return bool(games_mod.is_active())
    except Exception:
        return False


# Command keys that ESCAPE an active game instead of being graded as a move, plus
# the bare words that mean "stop this game" only because a game is running.
#
# ONE definition for BOTH active-game claim sites in _handle_speech_segment. They
# carried duplicated literals with DIFFERENT bare-word sets above them and had
# already drifted: the EARLY site (which returns first, so it is the one that
# decides) omitted "stop game", and command_parser.parse("stop game") is None — so
# mid-game "stop game" was handed to the grader as an ANSWER while the later site,
# which never runs, would have caught it (measured 2026-08-13).
#
# The start_* keys are new here (2026-08-13): asking for a different game mid-game
# was graded as a move, even though games.start_game already stops the running game
# first. They are safe to escape because no game ANSWER looks like "let's play
# jeopardy". The query keys (time/date/vision/who-am-I) are deliberately NOT here:
# a Jeopardy response is phrased "What is X?", the same shape as those queries,
# which is exactly why action_router._deterministic_self_query_intent refuses to
# skip routing while a game is active.
_GAME_ESCAPE_COMMAND_KEYS = frozenset({
    "stop_game", "sleep", "shutdown", "quiet_mode", "wake_up",
    "dj_stop", "dj_skip", "volume_up", "volume_down",
    "start_game", "start_trivia", "start_i_spy", "start_20_questions",
    "start_jeopardy", "start_word_association",
})
_GAME_BARE_STOP_WORDS = frozenset({
    "stop", "quit", "end", "stop game", "end game", "quit game",
    "stop the game", "end the game", "quit the game", "stop playing",
})


def _game_escape_command(text: str) -> Optional[command_parser.CommandMatch]:
    """The escape command an in-game utterance carries, or None to grade it."""
    try:
        match = command_parser.parse(text)
    except Exception:
        match = None
    key = match.command_key if match is not None else None
    normalized = " ".join((text or "").lower().split()).strip(" .!?")
    if normalized in _GAME_BARE_STOP_WORDS and key in (None, "dj_stop"):
        # A bare "stop"/"quit" parses as dj_stop (or as nothing at all); inside a
        # game it means THIS game, not the music.
        return command_parser.CommandMatch("stop_game", "active_game_stop", {})
    if key == "dj_skip" and normalized == "skip":
        # "skip" mid-game means skip the question — a MOVE, not an escape.
        return None
    return match if key in _GAME_ESCAPE_COMMAND_KEYS else None


def _action_router_context(
    text: str,
    *,
    person_id: Optional[int],
    person_name: Optional[str],
    raw_best_id: Optional[int],
    raw_best_name: Optional[str],
    speaker_score: float,
    recent_engagement: Optional[dict],
    off_camera_unknown: bool,
    identity_prompt_active: bool,
) -> dict:
    """Build compact turn context for the shadow action router."""
    visible_people = []
    try:
        for p in world_state.get("people") or []:
            visible_people.append({
                "person_id": p.get("person_db_id"),
                "face_id": p.get("face_id"),
                "voice_id": p.get("voice_id"),
                "age_estimate": p.get("age_estimate"),
                "is_unknown": p.get("person_db_id") is None,
            })
    except Exception:
        visible_people = []

    active_game = False
    try:
        from features import games as games_mod
        active_game = bool(games_mod.is_active())
    except Exception:
        active_game = False

    legacy_command = None
    try:
        match = command_parser.parse(text)
        if match is not None:
            legacy_command = {
                "command_key": match.command_key,
                "match_type": match.match_type,
                "args": match.args,
            }
    except Exception:
        legacy_command = None

    pending_event = None
    if _awaiting_followup_event is not None:
        pending_event = {
            "event_id": _awaiting_followup_event.get("event_id"),
            "event_name": _awaiting_followup_event.get("event_name"),
            "person_id": _awaiting_followup_event.get("person_id"),
        }

    pending_question = None
    if person_id is not None:
        try:
            pending = rel_memory.get_latest_pending_question(person_id)
            if pending:
                pending_question = {
                    "question_key": pending.get("question_key"),
                    "question_text": pending.get("question_text"),
                    "depth": pending.get("depth"),
                    "asked_at": pending.get("asked_at"),
                }
        except Exception:
            pending_question = None

    return {
        "speaker": {
            "person_id": person_id,
            "name": person_name,
            "raw_best_id": raw_best_id,
            "raw_best_name": raw_best_name,
            "voice_score": round(float(speaker_score or 0.0), 3),
            "off_camera_unknown": off_camera_unknown,
        },
        "visible_people": visible_people[:6],
        "recent_engagement": recent_engagement,
        "active_game": active_game,
        "active_music": _dj_is_playing(),
        "pending": {
            "identity_prompt_active": identity_prompt_active,
            "pending_question": pending_question,
            "awaiting_followup_event": pending_event,
            "offscreen_identify": _pending_offscreen_identify is not None,
            "introduction": _pending_introduction is not None,
            "intro_followup": _pending_intro_followup is not None,
            "tell_about": _pending_tell_about is not None,
            "prompted_name_confirmation": _pending_prompted_name_confirmation is not None,
            "exploration": exploration_flow_active(),
        },
        "legacy": {
            "command_key": (legacy_command or {}).get("command_key"),
            "command_match": legacy_command,
        },
        "last_rex_frame": dialogue_act.active_frame_context(person_id),
    }


def _router_decision_executable(
    decision: Optional[action_router.ActionDecision],
    *,
    text: Optional[str] = None,
    context: Optional[dict[str, Any]] = None,
    dialogue_decision: Optional[dialogue_act.DialogueActDecision] = None,
) -> bool:
    return _router_execution_block_reason(
        decision,
        text=text,
        context=context,
        dialogue_decision=dialogue_decision,
    ) is None


def _router_execute_allowlist() -> Optional[set[str]]:
    configured = getattr(config, "ACTION_ROUTER_EXECUTE_ACTIONS", None)
    if configured is None:
        return None
    if isinstance(configured, str):
        return {
            item.strip()
            for item in configured.split(",")
            if item.strip()
        }
    try:
        return {str(item).strip() for item in configured if str(item).strip()}
    except TypeError:
        return set()


def _router_execution_block_reason(
    decision: Optional[action_router.ActionDecision],
    *,
    text: Optional[str] = None,
    context: Optional[dict[str, Any]] = None,
    dialogue_decision: Optional[dialogue_act.DialogueActDecision] = None,
) -> Optional[str]:
    if decision is None:
        return "no_decision"
    if bool(decision.requires_confirmation):
        return "requires_confirmation"
    if decision.action not in action_router.EXECUTABLE_ACTIONS:
        return "not_executable"
    if decision.action == "performance.body_beat":
        args = decision.args or {}
        beat = (
            args.get("body_beat")
            or args.get("beat")
            or args.get("gesture")
            or args.get("pose")
            or ""
        )
        if performance_plan.canonical_body_beat(str(beat)) is None:
            return "unknown_body_beat"
    if decision.action == "performance.mood_pose":
        args = decision.args or {}
        mood = (
            args.get("mood")
            or args.get("emotion")
            or args.get("pose")
            or ""
        )
        if performance_plan.canonical_mood_pose(str(mood)) is None:
            return "unknown_mood_pose"
    if decision.action == "game.answer" and not _game_active_for_router():
        return "game_inactive"
    if (
        dialogue_decision is not None
        and dialogue_act.action_blocked_by_dialogue(decision.action, dialogue_decision)
        and not _dialogue_allows_action_breakout(
            decision.action,
            text or "",
            dialogue_decision,
        )
    ):
        return "blocked_by_dialogue_act"
    if text is not None:
        evidence_reason = action_router.missing_required_evidence_reason(
            text,
            decision,
            context=context,
        )
        if evidence_reason:
            return evidence_reason
    allowlist = _router_execute_allowlist()
    if allowlist is not None and decision.action not in allowlist:
        return "not_in_execute_allowlist"
    threshold = float(getattr(config, "ACTION_ROUTER_EXECUTE_MIN_CONFIDENCE", 0.85))
    if float(decision.confidence or 0.0) < threshold:
        return "below_confidence_threshold"
    return None


def _new_router_audit(text: str, context: Optional[dict[str, Any]]) -> _RouterDecisionAudit:
    legacy = ((context or {}).get("legacy") or {}).get("command_match") or {}
    return _RouterDecisionAudit(
        utterance=str(text or ""),
        legacy_command=legacy.get("command_key"),
        legacy_match_type=legacy.get("match_type"),
    )


def _router_audit_note_decision(
    audit: Optional[_RouterDecisionAudit],
    decision: Optional[action_router.ActionDecision],
    *,
    text: Optional[str] = None,
    context: Optional[dict[str, Any]] = None,
    dialogue_decision: Optional[dialogue_act.DialogueActDecision] = None,
) -> None:
    if audit is None:
        return
    audit.router_action = decision.action if decision is not None else None
    audit.router_confidence = (
        round(float(decision.confidence or 0.0), 3)
        if decision is not None
        else None
    )
    audit.router_requires_confirmation = (
        bool(decision.requires_confirmation)
        if decision is not None
        else None
    )
    block_reason = _router_execution_block_reason(
        decision,
        text=text,
        context=context,
        dialogue_decision=dialogue_decision,
    )
    audit.allowlist_result = "allowed" if block_reason is None else block_reason


def _router_audit_note_fast_local_action(
    audit: Optional[_RouterDecisionAudit],
    action: str,
    *,
    args: Optional[dict[str, Any]] = None,
    reason: str = "deterministic fast local command",
) -> None:
    """Record the stable action represented by a deterministic fast lane."""
    if audit is None:
        return
    decision = action_router.ActionDecision(
        action=action,
        confidence=1.0,
        args=args or {},
        requires_confirmation=False,
        reason=reason,
    )
    _router_audit_note_decision(audit, decision)


def _router_audit_note_execute_disabled(audit: Optional[_RouterDecisionAudit]) -> None:
    if audit is not None and audit.allowlist_result == "not_run":
        audit.allowlist_result = "execute_disabled_shadow"


def _router_blocked_confirmation_response(
    decision: Optional[action_router.ActionDecision],
    block_reason: Optional[str],
    person_id: Optional[int] = None,
) -> Optional[str]:
    """Return a short spoken response for blocked actions that need consent.
    For vision.snapshot this also ARMS the pending confirmation slot, so the
    user's "yes, remember this scene" actually completes the capture."""
    if decision is None or block_reason != "requires_confirmation":
        return None
    if decision.action == "vision.snapshot":
        return _offer_scene_snapshot(person_id)
    return None


_GENERAL_KNOWLEDGE_REPLY_RE = re.compile(
    r"\b(?:what\s+do\s+you\s+know|tell\s+me|explain|teach\s+me)"
    r"(?:\s+(?:about|regarding|on))?\s+(?P<topic>[^?.!]+)",
    re.IGNORECASE,
)
_PERSONAL_MEMORY_TOPIC_RE = re.compile(
    r"\b(?:me|my|mine|myself|you\s+remember|remember\s+about|"
    r"know\s+about\s+me|know\s+about\s+my)\b",
    re.IGNORECASE,
)
_MEMORY_LEARNING_CLOSURE_RE = re.compile(
    r"\b("
    r"bye|goodbye|good-bye|see you|see ya|talk to you later|talk later|"
    r"catch you later|later|nice speaking|nice talking|nice chatting|"
    r"i'?m\s+going\s+to\s+go|i\s+am\s+going\s+to\s+go|i\s+have\s+to\s+go|"
    r"gotta\s+go"
    r")\b",
    re.IGNORECASE,
)


def _conversation_reply_should_skip_memory_learning(
    text: str,
    decision: Optional[action_router.ActionDecision],
) -> bool:
    """Avoid saving Rex's own general-knowledge answer as a personal fact."""
    if decision is None or decision.action != "conversation.reply":
        return False
    text_clean = str(text or "").strip()
    if not text_clean:
        return False
    if _MEMORY_LEARNING_CLOSURE_RE.search(text_clean):
        return True
    match = _GENERAL_KNOWLEDGE_REPLY_RE.search(text_clean)
    if not match:
        return False
    topic = str(match.group("topic") or "")
    return not _PERSONAL_MEMORY_TOPIC_RE.search(topic)


def _router_nonexecuted_should_suppress_memory_learning(
    decision: Optional[action_router.ActionDecision],
) -> bool:
    """Control/tool routes should not be learned when they fail open to chat."""
    if decision is None or decision.action == "conversation.reply":
        return False
    if decision.action == "identity.introduce_person":
        return False
    return True


def _router_audit_note_legacy_command(
    audit: Optional[_RouterDecisionAudit],
    match: Optional[command_parser.CommandMatch],
) -> None:
    if audit is None or match is None:
        return
    audit.legacy_command = match.command_key
    audit.legacy_match_type = match.match_type


def _router_audit_clear_legacy_command(audit: Optional[_RouterDecisionAudit]) -> None:
    if audit is None:
        return
    audit.legacy_command = None
    audit.legacy_match_type = None


def _legacy_command_blocked_by_dialogue(
    match: Optional[command_parser.CommandMatch],
    dialogue_decision: Optional[dialogue_act.DialogueActDecision],
    text: str = "",
) -> bool:
    """Keep contextual replies from falling through to older command parsers."""
    if match is None or dialogue_decision is None:
        return False
    if dialogue_decision.label != "answer_to_rex":
        return False
    decision = _legacy_command_action_decision(match)
    if decision is not None:
        # Mapped command (sleep/music/vision/game/...): break out only with clear,
        # action-shaped evidence (the central policy bar). Otherwise treat the turn
        # as a contextual reply and block the command.
        if _dialogue_allows_action_breakout(decision.action, text, dialogue_decision):
            return False
        return True
    # UNMAPPED command_key: most have no action to evidence-check. A small set are
    # genuine EXPLICIT commands (a wave gag, a volume nudge, a personality dial, a
    # deliberate "remember X") that should still run mid-frame — route them normally
    # (on a high-precision match) instead of swallowing them for the whole answer_to_rex
    # window. The live failure: "remember I'm vegetarian" / "wave at them" right after a
    # Rex question were silently dropped to conversation. Everything else stays blocked —
    # notably memory_correct_fact, which a SENSITIVE contextual reply ("my partner is in
    # the hospital") pattern-matches and must NOT be promoted to a memory command.
    if (
        getattr(match, "command_key", None) in _LEGACY_ANSWER_FRAME_BREAKOUT_KEYS
        and str(getattr(match, "match_type", "")) in {"exact", "prefix", "pattern", "action_router"}
    ):
        return False
    return True


# Unmapped legacy command_keys explicit enough to break out of an answer_to_rex frame
# (NOT memory_correct_fact — that pattern-matches sensitive contextual replies).
# memory_remember_fact is the one DURABLE, unconfirmed write in this set — it can
# even mint a new person row — and it stays only because it is now backstopped:
# _legacy_unmapped_memory_write_block_reason runs AFTER this breakout, so a real
# "remember that Dana is allergic to shellfish" still routes mid-frame while
# narration does not. Do not add another durable key here without a bar there.
_LEGACY_ANSWER_FRAME_BREAKOUT_KEYS = frozenset({
    "wave_to", "volume_up", "volume_down",
    "set_personality", "query_personality", "memory_remember_fact",
})


_LEGACY_COMMAND_ACTION_MAP: dict[str, str] = {
    "time_query": "time.query",
    "date_query": "date.query",
    "status_uptime": "status.uptime",
    "status_climate": "status.climate",
    "vision_describe": "vision.describe_scene",
    # Physical gaze commands ("look to your right", "look at this"). Mapping
    # them here gives the turn-policy gate a real ActionDecision, so a clear
    # look imperative can break out of a stale answer_to_rex binding via
    # _dialogue_allows_action_breakout + the central directed-look evidence
    # check, instead of being silently dropped to conversation (the live
    # failure: "look to your right" → blocked_by_dialogue_act → Rex
    # hallucinated "nothing to my right except a wall" without moving).
    "directed_look": "vision.directed_look",
    "vision_who_am_i": "identity.who_is_speaking",
    "whats_my_name": "identity.who_is_speaking",
    "rename_me": "identity.name_correction",
    "memory_review": "memory.query",
    "memory_forget_fact": "memory.forget_specific",
    "memory_boundary": "memory.recent_discard",
    "forget_specific": "memory.forget_specific",
    "query_play_options": "music.options",
    "dj_stop": "music.stop",
    "dj_skip": "music.skip",
    "dj_play_vibe": "music.play",
    "start_trivia": "game.start",
    "start_i_spy": "game.start",
    "start_20_questions": "game.start",
    "start_jeopardy": "game.start",
    "start_word_association": "game.start",
    "start_game": "game.start",
    "stop_game": "game.stop",
    "sleep": "system.sleep",
    "wake_up": "system.sleep",
    "quiet_mode": "system.sleep",
    "shutdown": "system.shutdown",
}


# Unmapped command_keys that still WRITE people.db. The rest of the unmapped set is
# safe to run unchecked and deliberately so: forget_me / forget_everyone /
# volume_up / volume_down only ever reach us from the whole-utterance EXACT table,
# set_personality / query_personality from anchored "^set <param> to <n>" and
# "^what's your <param>" regexes, wave_to from an anchored "^wave (to|at) X$" — for
# those the parser match IS the evidence, and the effect is a canned readout, a
# volume nudge, a personality dial, one gesture, or an ARMED confirmation the user
# still has to say back. These two are open-ended tails whose executors write a
# durable fact with no confirmation turn, so they need a bar of their own.
_LEGACY_UNMAPPED_MEMORY_WRITE_KEYS = frozenset({
    "memory_remember_fact",
    "memory_correct_fact",
})

# A stored attribute is short; a story is not. Measured on the parser 2026-08-13:
# real writes run 2-8 words ("Sarah is a vegetarian", "last name is Bender") while
# the narration that produced the junk rows runs 15-17 ("my mom is coming over on
# Sunday and she really does not like loud music"). Same 12-word line dialogue_act
# uses to call a turn a contextual reply — and the reason that guard never saw
# these: over 12 words the turn is general_chat, so BOTH gates passed it.
_LEGACY_MEMORY_WRITE_MAX_WORDS = 12


def _legacy_unmapped_memory_write_block_reason(
    match: command_parser.CommandMatch,
) -> Optional[str]:
    """Evidence bar for the unmapped legacy keys that write people.db.

    Field 2026-08-13: "Remember that my mom is coming over on Sunday and she
    really does not like loud music" parsed as memory_remember_fact, and at 17
    words dialogue_act never bound it as answer_to_rex either (that label only
    claims replies of <=12 words), so BOTH gates passed it and the executor filed
    the whole sentence as a fact.

    Length is the discriminator on purpose. The obvious alternative — reusing
    command_parser._correction_carries_fact_evidence for the correction twin —
    also rejects "that's wrong, last name is Bender", a self-surname correction
    the executor genuinely handles and that the live garbled-surname work depends
    on. A stored attribute is short whoever it belongs to; a story is not.
    """
    key = getattr(match, "command_key", "")
    if key not in _LEGACY_UNMAPPED_MEMORY_WRITE_KEYS:
        return None
    args = match.args or {}
    field = "statement" if key == "memory_remember_fact" else "correction"
    value = " ".join(str(args.get(field) or "").split()).strip(" .!?")
    if not value:
        return f"missing_memory_write_{field}"
    if len(value.split()) > _LEGACY_MEMORY_WRITE_MAX_WORDS:
        return "memory_write_is_narrative"
    return None


_INTENT_ACTION_MAP: dict[str, str] = {
    "query_time": "time.query",
    "query_date": "date.query",
    "query_weather": "weather.query",
    "query_capabilities": "status.capabilities",
    "query_uptime": "status.uptime",
    "query_battery": "status.battery",
    "query_what_do_you_see": "vision.describe_scene",
    "query_who_is_speaking": "identity.who_is_speaking",
    "query_memory": "memory.query",
    "play_music": "music.play",
    "query_music_options": "music.options",
}


def _legacy_command_confidence(match: command_parser.CommandMatch) -> float:
    if match.match_type == "exact":
        return 0.99
    if match.match_type in {"prefix", "pattern", "action_router", "active_game_stop"}:
        return 0.96
    if match.match_type == "fuzzy":
        return 0.74
    return 0.90


def _legacy_command_action_decision(
    match: Optional[command_parser.CommandMatch],
) -> Optional[action_router.ActionDecision]:
    if match is None:
        return None
    action = _LEGACY_COMMAND_ACTION_MAP.get(match.command_key)
    if not action:
        return None
    args = dict(match.args or {})
    if match.command_key == "dj_play_vibe":
        args = {"music_query": args.get("vibe") or ""}
    elif match.command_key == "start_game":
        args = {"game": args.get("game") or ""}
    elif match.command_key.startswith("start_"):
        args = {"game": match.command_key.removeprefix("start_")}
    elif match.command_key == "memory_forget_fact":
        args = {"target": args.get("statement") or ""}
    return action_router.ActionDecision(
        action=action,
        confidence=_legacy_command_confidence(match),
        args=args,
        reason=f"legacy command parser claim: {match.command_key}",
    )


def _dialogue_allows_action_breakout(
    action: Optional[str],
    text: str,
    dialogue_decision: Optional[dialogue_act.DialogueActDecision],
) -> bool:
    """Let clear commands win over a stale conversational reply frame."""
    if not action or dialogue_decision is None:
        return False
    if dialogue_decision.label != "answer_to_rex":
        return False
    cleaned = (text or "").strip()
    if not cleaned:
        return False
    if action == "system.sleep":
        return command_parser.is_standalone_sleep_command(cleaned)
    if action == "system.shutdown":
        # Request form (not standalone-only): the parser still owns the safety
        # guards, and "I would like you to shut down" mid-answer is a command.
        return command_parser.is_shutdown_request(cleaned)
    if action == "status.battery":
        # A direct question about Rex's OWN battery mid-chat is a query, not an
        # answer to his last line (field 2026-08-03 17:59: "No, I mean, what
        # percentage is your battery at?" bound as answer_to_rex, the intent was
        # blocked, and the conversational LLM invented "52%"). Reuses the same
        # evidence regex as the central policy — not a new bypass.
        from intelligence.intent_classifier import _BATTERY_QUERY_RE
        return bool(_BATTERY_QUERY_RE.search(cleaned))
    if action == "music.play":
        return bool(_IDLE_DIRECT_MUSIC_RE.search(cleaned))
    if action in {"music.stop", "music.skip"}:
        return bool(re.search(r"^\s*(?:stop|pause|skip)\b", cleaned, re.IGNORECASE))
    # Camera requests are aimed at Rex's eyes, not at his last conversational
    # turn — "look to your right" or "can you see what I'm holding" mid-chat
    # is still a command/query. Both reuse the action router's deterministic
    # evidence checks (the same bar the central policy applies), so this is
    # not a new bypass: a turn only breaks out if it would also pass
    # missing_required_evidence_reason for the same action.
    if action == "vision.directed_look":
        return action_router.has_directed_look_evidence(cleaned)
    if action == "vision.describe_scene":
        return action_router.has_vision_query_evidence(cleaned)
    return False


def _legacy_command_execution_block_reason(
    match: Optional[command_parser.CommandMatch],
    *,
    text: str,
    context: Optional[dict[str, Any]] = None,
    dialogue_decision: Optional[dialogue_act.DialogueActDecision] = None,
) -> Optional[str]:
    """Central turn-policy gate for legacy command parser claims."""
    if match is None:
        return None
    if _legacy_command_blocked_by_dialogue(match, dialogue_decision, text):
        return "blocked_by_dialogue_act"
    if (
        match.match_type == "fuzzy"
        and not bool(getattr(config, "LEGACY_COMMAND_FUZZY_EXECUTE_ENABLED", False))
    ):
        return "legacy_fuzzy_disabled"
    decision = _legacy_command_action_decision(match)
    if decision is None:
        # No mapped action means no ActionDecision to evidence-check, which used
        # to mean "allow, unchecked" — the one silent hole in this gate (routing
        # audit 2026-08-13). Benign unmapped keys still pass; the keys that write
        # people.db now answer for themselves.
        return _legacy_unmapped_memory_write_block_reason(match)
    owned_context = None
    if decision.action == "game.stop":
        # Only game.stop's ownership depends on live state, so only it pays the
        # is_active() read. Read LIVE rather than trusting `context`: this gate is
        # also called with context=None, and a missing key would read as "no game
        # running" and hand the player's only escape hatch to the model.
        owned_context = {"active_game": _game_active_for_router()}
    if action_router.tool_router_owns_turn(decision.action, owned_context):
        # Phase 2b handoff for the command_parser lanes, in ONE place: this gate is
        # the only thing BOTH legacy call sites pass through — the fast lane
        # (_handle_fast_local_takeover, which claims forget_specific and
        # memory_boundary before the router call even happens) and the main legacy
        # dispatch after the router. Demoting here rather than inside
        # command_parser.parse keeps parse()'s contract — and its offline behavior —
        # byte-identical, which matters because offline these regexes are the ONLY
        # thing that still forgets anything (docs/tool_router_scope.md 2.4).
        #
        # The classifier is not wasted: its match is still the DETECTOR, and the
        # turn falls through to the reply call that was going to happen anyway, so
        # the handoff costs zero round trips.
        #
        # Note this also covers the memory_forget_fact key, which maps to
        # memory.forget_specific — same action, same delete, so the same handoff.
        _log.info(
            "[turn_policy] legacy command=%s handed to the tool router (action=%s)",
            match.command_key, decision.action,
        )
        return "tool_router_owns_action"
    return action_router.missing_required_evidence_reason(
        text,
        decision,
        context=context,
    )


def _intent_action_decision(intent: str) -> Optional[action_router.ActionDecision]:
    action = _INTENT_ACTION_MAP.get(intent)
    if not action:
        return None
    return action_router.ActionDecision(
        action=action,
        confidence=0.94,
        args={},
        reason=f"deterministic intent claim: {intent}",
    )


def _intent_execution_block_reason(
    intent: str,
    *,
    text: str,
    context: Optional[dict[str, Any]] = None,
    dialogue_decision: Optional[dialogue_act.DialogueActDecision] = None,
    router_action: Optional[str] = None,
) -> Optional[str]:
    """Central turn-policy gate for deterministic intent-classifier claims."""
    if not intent or intent == "general":
        return None
    if intent == "query_games" and action_router.tool_router_owns("game.start"):
        # query_games is the ONE deterministic intent with no action mapping and no
        # evidence rule (action_router._SELF_QUERY_SKIP_INTENTS says exactly that),
        # so it reaches _handle_classified_intent unchecked — and
        # intent_classifier._GAMES_QUERY_RE claims "play a game" and "start a game"
        # outright, answering a LAUNCH with the canned games menu. That was masked
        # while command_parser executed start_game first; demoting start_game to the
        # tool router unmasks it, and without this "play a game of jeopardy" would
        # regress from starting Jeopardy to reading a list (measured 2026-08-13:
        # classify_deterministic("play a game of jeopardy") == "query_games").
        # Fails SAFE in both directions: when the start pattern misses, query_games
        # keeps the turn exactly as today, and offline / kill-switch-off
        # tool_router_owns is False so nothing changes at all.
        if action_router.has_game_start_request_evidence(text):
            return "tool_router_owned_game_start"
        return None
    decision = _intent_action_decision(intent)
    if decision is None:
        return None
    # The LLM router already judged this turn a conversational REPAIR (a
    # correction or complaint like "you didn't give me time to answer"). A
    # repair is never a clock/date/weather/data query — so don't let a keyword
    # match in the deterministic fallback hijack it into a tool answer (this is
    # what produced "It's 8:33 PM." in response to a pacing complaint).
    if (router_action or "") == "conversation.repair":
        return "router_classified_repair"
    # Stage 1 of the tool-router migration: for the actions the LIVE tool router
    # owns, this lane is a DETECTOR, not a claim. Returning a reason here IS the
    # demotion — the caller sets intent="general", the turn falls through to
    # conversation, and the lean reply call that was going to happen anyway picks
    # the tool from the model's own reading of the utterance. That is what
    # unblocks the phrasings the keyword nets get WRONG: measured on this
    # checkout, "did you see the game last night" claimed vision.describe_scene
    # and "I've been running a lot lately" claimed status.uptime, and BOTH passed
    # the evidence gate below, so nothing else was ever going to stop them.
    #
    # Deliberately BEFORE the evidence call. That gate is the ceiling on this
    # lane, not a safety property — it can only narrow the loose net back down to
    # action_router's stricter regexes, which is exactly the set of phrasings the
    # tool router was migrated off. It still runs offline and with the kill switch
    # off, where tool_router_owns is False and this lane claims as before
    # (docs/tool_router_scope.md 2.4 — the local reply model gets no tools).
    if action_router.tool_router_owns(decision.action):
        return "tool_router_owns_action"
    evidence_reason = action_router.missing_required_evidence_reason(
        text,
        decision,
        context=context,
    )
    if evidence_reason:
        return evidence_reason
    if (
        dialogue_decision is not None
        and dialogue_decision.label == "answer_to_rex"
        and not _dialogue_allows_action_breakout(
            decision.action,
            text,
            dialogue_decision,
        )
    ):
        return "blocked_by_dialogue_act"
    return None


def _router_audit_note_result(
    audit: Optional[_RouterDecisionAudit],
    *,
    completed: Optional[bool] = None,
    handler_error: Optional[str] = None,
    spoken_text: Optional[str] = None,
    spoken_text_present: Optional[bool] = None,
) -> None:
    if audit is None:
        return
    if completed is not None and audit.completed is None:
        audit.completed = bool(completed)
    if handler_error and audit.handler_error is None:
        text = " ".join(str(handler_error).strip().split())
        audit.handler_error = text[:240] if text else None
    if spoken_text_present is not None and audit.spoken_text_present is None:
        audit.spoken_text_present = bool(spoken_text_present)
    elif spoken_text is not None and audit.spoken_text_present is None:
        audit.spoken_text_present = bool(str(spoken_text).strip())
    if audit.completed is None and audit.spoken_text_present is not None:
        audit.completed = audit.spoken_text_present


def _log_router_audit(
    audit: Optional[_RouterDecisionAudit],
    final_executed_path: str,
    *,
    completed: Optional[bool] = None,
    handler_error: Optional[str] = None,
    spoken_text: Optional[str] = None,
    spoken_text_present: Optional[bool] = None,
) -> None:
    if audit is None or audit.emitted:
        return
    if not bool(getattr(config, "ACTION_ROUTER_AUDIT_LOG_ENABLED", True)):
        return
    _router_audit_note_result(
        audit,
        completed=completed,
        handler_error=handler_error,
        spoken_text=spoken_text,
        spoken_text_present=spoken_text_present,
    )
    audit.final_executed_path = final_executed_path
    audit.emitted = True
    payload = {
        "utterance": audit.utterance,
        "router_action": audit.router_action,
        "router_confidence": audit.router_confidence,
        "router_requires_confirmation": audit.router_requires_confirmation,
        "allowlist_result": audit.allowlist_result,
        "legacy_command": audit.legacy_command,
        "legacy_match_type": audit.legacy_match_type,
        "final_executed_path": audit.final_executed_path,
        "completed": audit.completed,
        "handler_error": audit.handler_error,
        "spoken_text_present": audit.spoken_text_present,
    }
    _log.info("[action_router_audit] %s", json.dumps(payload, sort_keys=True))


def _safe_round_score(value: Any) -> Optional[float]:
    try:
        return round(float(value), 3)
    except (TypeError, ValueError):
        return None


def _safe_int(value: Any) -> Optional[int]:
    try:
        return int(value) if value is not None else None
    except (TypeError, ValueError):
        return None


def _clean_trace_error(error: Any) -> Optional[str]:
    text = " ".join(str(error or "").strip().split())
    return text[:240] if text else None


def _new_character_loop_trace(
    text: str,
    *,
    from_idle_activation: bool,
    turn_start: float,
    raw_best_id: Optional[int],
    raw_best_name: Optional[str],
    speaker_score: Optional[float],
) -> Optional[_CharacterLoopTrace]:
    if not bool(getattr(config, "CHARACTER_LOOP_TRACE_ENABLED", True)):
        return None
    return _CharacterLoopTrace(
        turn_id=next(_character_loop_turn_ids),
        utterance=str(text or ""),
        heard_text=str(text or ""),
        from_idle_activation=bool(from_idle_activation),
        turn_start=turn_start,
        raw_best_id=_safe_int(raw_best_id),
        raw_best_name=raw_best_name,
        speaker_score=_safe_round_score(speaker_score),
    )


def _infer_identity_resolution_strategy(
    *,
    person_id: Optional[int],
    raw_best_id: Optional[int],
    speaker_score: Optional[float],
    hard_threshold: float,
    soft_threshold: float,
    sticky_accepted: bool,
    ws_identified: Optional[list[Any]],
    recent_engagement: Optional[dict],
    off_camera_unknown: bool,
) -> str:
    if person_id is None:
        return "off_camera_unknown" if off_camera_unknown else "unresolved"
    if sticky_accepted:
        return "voice_session_sticky"

    resolved_id = _safe_int(person_id)
    raw_id = _safe_int(raw_best_id)
    score = float(speaker_score or 0.0)
    confident_threshold = float(getattr(config, "SPEAKER_ID_CONFIDENT_THRESHOLD", 0.70))
    if raw_id is not None and resolved_id == raw_id:
        # Voice's own best candidate IS the resolved person — a voice-led match.
        # Tiers by descending score (confident > hard accept > corroborated).
        if score >= confident_threshold:
            return "voice_confident"  # wins regardless of camera
        if score >= hard_threshold:
            return "voice_match"
        # Below the accept threshold: voice still leans toward this person and a
        # visible face corroborated it (the weak-voice-corroborated branch).
        return "voice_corroborated_by_face"

    # Resolved to someone the voice did NOT point at — only reachable via the
    # face-only 1:1 continuity fallback (no voice signal at all).
    try:
        visible_ids = {
            int(p.get("person_db_id"))
            for p in (ws_identified or [])
            if getattr(p, "get", None) and p.get("person_db_id") is not None
        }
    except Exception:
        visible_ids = set()
    if resolved_id in visible_ids:
        return "face_only_continuity"

    recent_id = _safe_int((recent_engagement or {}).get("person_id"))
    if recent_id is not None and recent_id == resolved_id:
        return "recent_engagement_context"
    return "resolved"


def _visual_corroborated_speaker(
    *,
    raw_best_id: Optional[int],
    speaker_score: float,
    visible_known_ids,
    visual_speaker_pid: Optional[int],
    floor: float,
) -> Optional[int]:
    """Multi-visible tie-breaker (voice + visual active-speaker). Returns the
    person_id to attribute, or None.

    Fires only when the weak voice candidate IS a visible known person AND the
    camera saw exactly that person speaking near end-of-turn
    (``active_speaker.recent_visual_speaker``). Vision only CONFIRMS the person the
    voice already leans toward — it never promotes someone the voice doesn't point
    at, and a confident voice never reaches this path (caller gates on
    ``person_id is None``). Pure, so it is directly unit-testable.
    """
    raw_id = _safe_int(raw_best_id)
    vis_pid = _safe_int(visual_speaker_pid)
    if raw_id is None or vis_pid is None:
        return None
    if raw_id not in (visible_known_ids or set()):
        return None
    if vis_pid != raw_id:  # the one visual speaker must be the voice-leaned-to person
        return None
    if float(speaker_score or 0.0) < float(floor):
        return None
    return raw_id


def _ecapa_genuine_band(speaker_score: float, floor: float) -> bool:
    """True when the ACTIVE embedder is ECAPA and the mapped score sits in the
    genuine band (>= floor). Under ECAPA an impostor cross-match lands at
    ~0.25-0.45 mapped — below the accept threshold — so an accepted match is
    already genuine-band evidence, while genuine SHORT utterances land ~0.55-0.65:
    structurally below the 0.75 confident bar. This lets the who's-that challenges
    stand down for genuine-band ECAPA scores without weakening the Resemblyzer
    fallback (where impostors land 0.55-0.66 and the strict guards must hold)."""
    if not bool(getattr(config, "SPEAKER_ID_ECAPA_TRUST_ENABLED", True)):
        return False
    try:
        from audio import voice_score
        if voice_score.active_backend() != "ecapa":
            return False
    except Exception:
        return False
    return float(speaker_score or 0.0) >= float(floor)


def _voice_primary_face_decision(
    *,
    person_id: Optional[int],
    raw_best_id: Optional[int],
    speaker_score: float,
    ws_pid: Optional[int],
    single_visible: bool,
    engaged_is_visible: bool,
    unknown_visible: bool,
    other_known_recently: bool,
    visual_speaker_pid: Optional[int] = None,
    visual_mouth_still: bool = False,
    voice_continuity: bool = False,
    score_genuine_band: bool = False,
    short_utterance: bool = False,
    non_speech_vocalization: bool = False,
) -> str:
    """Voice-primary attribution decision when exactly one known face (``ws_pid``)
    is visible. Pure (no side effects) so it is directly unit-testable.

    WHO is speaking is decided by the VOICE — the camera never upgrades a marginal
    voice into an identity (owner architecture call 2026-07-05, after JT's
    "happy 4th" at 0.628 on Bret's print was credited to silently-on-camera Bret
    via the old unconditional voice_agrees). A marginal match on the VISIBLE face
    passes only when the voice itself has recent credibility (``voice_continuity``:
    a confident match on that same person within the continuity window) or the
    camera positively confirms that face is the talker; otherwise Rex challenges
    ("...who's speaking? I don't recognize the voice"). ``visual_speaker_pid`` is
    the latched recent visual active-speaker (``person_db_id`` or ``None`` when
    the detector is disabled / its latch is empty or expired).

    Returns one of:
      ``voice_agrees``            confident voice matched the visible face (or the
                                  camera confirms they're talking) — attribute + refresh
      ``voice_agrees_no_refresh`` MARGINAL match on the visible face backed by voice
                                  continuity or an ECAPA genuine-band score —
                                  attribute, do NOT touch the print
      ``challenge_identity``      marginal match on the visible face with NO voice
                                  credibility — reply to content + ask who's speaking
      ``voice_over_face``         voice CONFIDENTLY matched someone else, or the camera
                                  shows the visible face is not the talker — keep voice
      ``voice_weak_face_wins``    voice marginally matched someone else while a known
                                  face is visible and the camera does not contradict it
                                  — the present face anchors identity, no refresh
      ``corroborate``             voice weakly leans toward the visible face — attribute + refresh
      ``face_only_continuity``    no voice signal at all in a clean 1:1 — attribute, no refresh
      ``short_face_wins``         clip too short for the embedder to score reliably and the
                                  voice doesn't point at someone else — the sole visible known
                                  face resolves identity; never touch the print
      ``unknown_intro_path``      voice unrecognized while an unknown face is present — leave
                                  person unresolved for the intro/identify path (not off-screen)
      ``off_screen_unknown``      voice points away / scene ambiguous — off-screen unknown voice
    """
    pid = _safe_int(person_id)
    raw_id = _safe_int(raw_best_id)
    ws = _safe_int(ws_pid)
    vis = _safe_int(visual_speaker_pid)
    if pid is not None and pid == ws:
        confident = float(getattr(config, "SPEAKER_ID_CONFIDENT_THRESHOLD", 0.70))
        if speaker_score >= confident:
            return "voice_agrees"            # the voice stands on its own
        if vis is not None and vis == ws:
            return "voice_agrees"            # camera positively confirms they're talking
        if visual_mouth_still and not score_genuine_band and not non_speech_vocalization:
            # POSITIVE mouth-still evidence: the active-speaker detector was
            # running and nobody visible articulated near end-of-turn — the
            # visible face was NOT the talker (field 2026-08-02 12:37: JT at
            # ~20ft scored 0.455 on Bret's print; Bret was silently on camera
            # with voice continuity from his own earlier turn, and got the
            # credit). SCOPE (recalibrated 2026-08-02 13:04 after the veto
            # challenged genuine Bret at 0.660 and 0.742 in one session —
            # the detector misses real jaw motion on short utterances at
            # room distance): the veto only overrules SUB-genuine-band
            # scores, where ECAPA impostor cross-matches live. A band-level
            # score plus the face is stronger evidence than an empty latch.
            return "challenge_identity"
        if voice_continuity:
            return "voice_agrees_no_refresh"  # marginal but consistent with recent confident voice
        if score_genuine_band:
            # ECAPA genuine band: an impostor can't land an accepted match under
            # ECAPA (~0.25-0.45 mapped), so an accepted score agreeing with the
            # visible face IS credible even without continuity — this is what
            # stops the first short turn of every session being challenged
            # (live-logged 2026-07-07: "yup, I'm back" at 0.597, face on camera,
            # answered with "who's speaking?"). Attribute, never touch the print.
            return "voice_agrees_no_refresh"
        if non_speech_vocalization and (raw_id is None or raw_id == ws) and (
            vis is None or vis == ws
        ):
            # A LAUGH is not speech, and every identity signal here assumes it is:
            # ECAPA embeds speech, so laughter lands ~0.4 on the laugher's own print,
            # and the active-speaker detector measures VAD-gated jaw articulation, so
            # it reports "mouth still" through a laugh. Both fail for the SAME reason,
            # then compound into "who are you?" — field 2026-08-06 16:24:46: Bret
            # laughed at Rex's own joke, face recognized and on camera, confident voice
            # 16 s earlier, and was answered "Nice laugh, mystery voice—who are you,
            # exactly?". Same shape as the short_utterance branch below: an unscoreable
            # clip is not evidence of a stranger. Fires only when the voice's own best
            # candidate IS the visible face (or there is no candidate) and the camera
            # doesn't contradict it; never refreshes the print, since folding laughter
            # into a speech voiceprint would corrupt it.
            return "voice_agrees_no_refresh"
        return "challenge_identity"           # marginal + no credibility: never assume the face
    if pid is not None:
        # Accepted voice match points at someone OTHER than the visible known face.
        confident = float(getattr(config, "SPEAKER_ID_CONFIDENT_THRESHOLD", 0.70))
        if speaker_score >= confident:
            return "voice_over_face"            # confident → a real off-camera speaker
        if vis is not None and vis != ws:
            # The camera's recent on-camera talker is NOT the visible known face
            # (it is the matched person, or a third person who was just on camera)
            # — so the visible face is not the source; trust the off-camera voice.
            return "voice_over_face"
        # Marginal (<confident) off-camera match while a known face is visible and
        # the camera either confirms that face is talking (vis == ws) or gives no
        # usable speaker signal (disabled / empty / expired latch → vis is None).
        # The present known face anchors identity; the near-neighbor match is most
        # likely an absent/poor-print artifact, not a genuine off-camera speaker.
        # ...unless the camera POSITIVELY watched that face's mouth stay still —
        # then the face may not absorb the voice: leave it off-screen unknown.
        if visual_mouth_still:
            return "off_screen_unknown"
        return "voice_weak_face_wins"
    # person_id is None — the voice was uninformative (below the known floor or
    # ambiguous). Corroborate, don't override.
    if unknown_visible:
        return "unknown_intro_path"
    eng_visible_floor = float(getattr(config, "SPEAKER_ID_ENGAGED_VISIBLE_FLOOR", 0.50))
    match_floor = float(getattr(config, "SPEAKER_ID_SINGLE_VISIBLE_MATCH_FLOOR", 0.35))
    voice_leans_visible = (
        raw_id is not None
        and raw_id == ws
        and (
            (engaged_is_visible and speaker_score >= match_floor)
            or speaker_score >= eng_visible_floor
        )
    )
    if voice_leans_visible and single_visible and not other_known_recently:
        if visual_mouth_still:
            # Weak lean toward a face whose mouth demonstrably wasn't moving:
            # never corroborate (a corroborate REFRESHES the print — exactly how
            # a distant stranger's audio would poison it). Ask instead.
            return "challenge_identity"
        return "corroborate"
    if (
        raw_id is None
        and single_visible
        and not other_known_recently
        and (engaged_is_visible or (vis is not None and vis == ws))
    ):
        # No voice candidate AT ALL (no comparable enrolled prints — e.g. right
        # after an embedder migration — or the clip was too short to score) in a
        # clean 1:1. Attribute to the face when EITHER engagement continuity backs
        # it or the camera positively confirms this face is the one talking
        # (vis == ws). The camera check matters at session start: engagement
        # hasn't formed yet, and without this the person can never be attributed,
        # so engagement NEVER forms — live-logged 2026-07-06-21-15, Bret (face
        # recognized, all voice prints stale) stayed Guest 1 all session.
        # No mouth-still veto here (recalibrated 2026-08-02 13:04): with NO
        # voice pointing anywhere else, engagement continuity outweighs an
        # empty detector latch — the detector misses short real utterances.
        return "face_only_continuity"
    if (
        short_utterance
        and single_visible
        and not other_known_recently
        and (raw_id is None or raw_id == ws)
        and (vis is None or vis == ws)
    ):
        # The clip is too short for the embedder to score reliably (a genuine
        # one-word turn lands ~0.3 on the speaker's own print), so the low score
        # is NOT evidence of an off-screen stranger. Voice stays the arbiter —
        # this fires only when the voice's own best candidate IS the visible
        # face (or there is no candidate) and the camera doesn't contradict it.
        # Field 2026-07-18: Bret's "Yep" at 0.332, face locked, became
        # unknown_voice_1 and de-personed the whole session.
        # Deliberately NO mouth-still veto here: a one-word turn can slip
        # between the detector's 0.25s samples, and de-personing genuine
        # short replies is the exact regression this branch exists to stop.
        return "short_face_wins"
    return "off_screen_unknown"


def _single_visible_face_voice_override(
    *,
    resolved_person_id: Optional[int],
    ws_person: Optional[dict],
    visible_known_by_id: dict,
    has_unknown_visible_or_recent: bool,
    speaker_score: float = 0.0,
    hard_threshold: Optional[float] = None,
) -> Optional[tuple[int, Optional[str]]]:
    """
    Resolve voice/face disagreement in favor of the only visible known face.

    Speaker ID is useful, but short commands can false-match. When the camera has
    exactly one known face and no other visible/recent unknown, that face is the
    most reliable identity signal for the current turn.
    """
    resolved_id = _safe_int(resolved_person_id)
    if resolved_id is None:
        return None
    if not isinstance(ws_person, dict):
        return None
    ws_pid = _safe_int(ws_person.get("person_db_id"))
    if ws_pid is None or resolved_id == ws_pid:
        return None
    if len(visible_known_by_id or {}) != 1:
        return None
    if ws_pid not in (visible_known_by_id or {}):
        return None
    if bool(has_unknown_visible_or_recent):
        return None
    threshold = float(
        hard_threshold
        if hard_threshold is not None
        else getattr(config, "SPEAKER_ID_SIMILARITY_THRESHOLD", 0.75)
    )
    if float(speaker_score or 0.0) >= threshold:
        return None
    return ws_pid, (ws_person.get("face_id") or ws_person.get("voice_id"))


def _character_loop_note_speaker(
    trace: Optional[_CharacterLoopTrace],
    *,
    person_id: Optional[int],
    person_name: Optional[str],
    speaker_label: Optional[str],
    identity_resolution: str,
    off_camera_unknown: bool,
    visible_known_count: Optional[int],
    has_unknown_visible_or_recent: Optional[bool],
    anonymous_speaker_label: Optional[str] = None,
    anonymous_speaker_match_score: Optional[float] = None,
) -> None:
    if trace is None:
        return
    trace.person_id = _safe_int(person_id)
    trace.person_name = person_name
    trace.speaker_label = speaker_label
    trace.anonymous_speaker_label = anonymous_speaker_label
    trace.anonymous_speaker_match_score = _safe_round_score(anonymous_speaker_match_score)
    trace.identity_resolution = identity_resolution
    trace.off_camera_unknown = bool(off_camera_unknown)
    trace.visible_known_count = (
        _safe_int(visible_known_count) if visible_known_count is not None else None
    )
    trace.has_unknown_visible_or_recent = (
        bool(has_unknown_visible_or_recent)
        if has_unknown_visible_or_recent is not None
        else None
    )


def _character_loop_note_router_audit(
    trace: Optional[_CharacterLoopTrace],
    audit: Optional[_RouterDecisionAudit],
) -> None:
    if trace is None or audit is None:
        return
    trace.router_action = audit.router_action
    trace.router_confidence = audit.router_confidence
    trace.router_requires_confirmation = audit.router_requires_confirmation
    trace.allowlist_result = audit.allowlist_result
    trace.legacy_command = audit.legacy_command
    trace.legacy_match_type = audit.legacy_match_type
    if audit.final_executed_path:
        trace.final_executed_path = audit.final_executed_path
    if audit.completed is not None:
        trace.completed = audit.completed
    if audit.handler_error:
        trace.handler_error = audit.handler_error
    if audit.spoken_text_present is not None:
        trace.spoken_text_present = audit.spoken_text_present


def _log_character_loop_trace(
    trace: Optional[_CharacterLoopTrace],
    *,
    router_audit: Optional[_RouterDecisionAudit] = None,
    final_executed_path: Optional[str] = None,
    completed: Optional[bool] = None,
    handler_error: Optional[str] = None,
    spoken_text: Optional[str] = None,
    spoken_text_present: Optional[bool] = None,
    assistant_asked_question: Optional[bool] = None,
    suppress_memory_learning: Optional[bool] = None,
    repair_move: Optional[dict] = None,
    intent: Optional[str] = None,
) -> None:
    if trace is None or trace.emitted:
        return
    if not bool(getattr(config, "CHARACTER_LOOP_TRACE_ENABLED", True)):
        return

    _character_loop_note_router_audit(trace, router_audit)
    if final_executed_path:
        trace.final_executed_path = final_executed_path
    if completed is not None:
        trace.completed = bool(completed)
    if handler_error:
        trace.handler_error = _clean_trace_error(handler_error)
    if spoken_text_present is not None:
        trace.spoken_text_present = bool(spoken_text_present)
    elif spoken_text is not None:
        trace.spoken_text_present = bool(str(spoken_text).strip())
    if assistant_asked_question is not None:
        trace.assistant_asked_question = bool(assistant_asked_question)
    if suppress_memory_learning is not None:
        trace.suppress_memory_learning = bool(suppress_memory_learning)
    if intent:
        trace.intent = str(intent)
    if repair_move:
        trace.repair_kind = str(repair_move.get("kind") or "unknown")
    if trace.completed is None and trace.spoken_text_present is not None:
        trace.completed = trace.spoken_text_present

    payload = {
        "turn_id": trace.turn_id,
        "utterance": trace.utterance,
        "heard_text": trace.heard_text,
        "duration_ms": int(max(0.0, time.monotonic() - trace.turn_start) * 1000),
        "speaker": {
            "person_id": trace.person_id,
            "name": trace.person_name,
            "label": trace.speaker_label,
            "identity_resolution": trace.identity_resolution,
            "from_idle_activation": trace.from_idle_activation,
            "off_camera_unknown": trace.off_camera_unknown,
            "visible_known_count": trace.visible_known_count,
            "has_unknown_visible_or_recent": trace.has_unknown_visible_or_recent,
            "raw_candidate": {
                "person_id": trace.raw_best_id,
                "name": trace.raw_best_name,
                "score": trace.speaker_score,
            },
            "anonymous_speaker": {
                "label": trace.anonymous_speaker_label,
                "match_score": trace.anonymous_speaker_match_score,
            },
        },
        "interpretation": {
            "router_action": trace.router_action,
            "router_confidence": trace.router_confidence,
            "router_requires_confirmation": trace.router_requires_confirmation,
            "allowlist_result": trace.allowlist_result,
            "legacy_command": trace.legacy_command,
            "legacy_match_type": trace.legacy_match_type,
            "intent": trace.intent,
            "repair_kind": trace.repair_kind,
        },
        "execution": {
            "final_executed_path": trace.final_executed_path,
            "completed": trace.completed,
            "handler_error": trace.handler_error,
            "spoken_text_present": trace.spoken_text_present,
            "assistant_asked_question": trace.assistant_asked_question,
            "suppress_memory_learning": trace.suppress_memory_learning,
        },
        "timing": _ttfs_timing_payload(trace),
    }
    trace.emitted = True
    _log.info("[character_loop] %s", json.dumps(payload, sort_keys=True))


def _router_audit_fast_local_final_path(audit: Optional[_RouterDecisionAudit]) -> str:
    if audit is None:
        return "fast_local_takeover.unknown"
    if audit.router_action and audit.allowlist_result == "allowed":
        return f"fast_local_takeover.{audit.router_action}"
    if audit.legacy_command:
        return f"legacy_command.{audit.legacy_command}"
    if audit.router_action:
        return f"fast_local_takeover.{audit.router_action}"
    return "fast_local_takeover.unknown"


def _chunk_for_vad(audio_chunk: np.ndarray) -> np.ndarray:
    """Apply playback suppression before VAD so background audio does not self-trigger."""
    try:
        return echo_cancel.filter(audio_chunk)
    except Exception:
        return audio_chunk


def _duck_dj_for_speech() -> Optional[float]:
    if not bool(getattr(config, "DJ_DUCK_DURING_SPEECH", True)):
        return None
    try:
        from features import dj as dj_mod
        if not dj_mod.is_playing():
            return None
        original = float(dj_mod.get_volume())
        ducked = min(original, float(getattr(config, "DJ_LISTEN_DUCK_VOLUME", 0.18)))
        if ducked < original:
            dj_mod.set_volume(ducked)
            return original
    except Exception as exc:
        _log.debug("DJ duck failed: %s", exc)
    return None


def _restore_dj_volume(volume: Optional[float]) -> None:
    if volume is None:
        return
    try:
        from features import dj as dj_mod
        if dj_mod.is_playing():
            dj_mod.set_volume(volume)
    except Exception as exc:
        _log.debug("DJ volume restore failed: %s", exc)


def _speak_blocking(
    text: str,
    emotion: str = "neutral",
    priority: int = 1,
    pre_beat_ms: int = 0,
    post_beat_ms_override: int = 0,
    voice_settings: Optional[dict] = None,
    log_text: bool = True,
    on_audio_end=None,
    comedy_mode: Optional[str] = None,
) -> bool:
    """
    Enqueue text for speech and block until playback finishes, monitoring for
    wake-word interruption.  Returns True on normal completion, False if cut short.

    priority 1 = normal response; priority 2 = urgent acknowledgment.
    Enqueueing drops all waiting items of lower priority and preempts any
    currently-playing item of lower priority.

    `post_beat_ms_override` is used by the empathy delivery layer to extend
    the post-punchline beat for sympathetic modes (listen/support/etc.) where
    we want the line to settle rather than snap into the next exchange. The
    override takes precedence over the default punchline beat when larger.
    """
    if not _can_speak() or not text or not text.strip():
        return True
    text = llm.clean_response_text(text)
    if not text:
        return True

    # Post-punchline beat: a brief silence after a normal-priority response so
    # the line lands. Skipped for urgent acks (priority >= 2), filler, etc.
    post_beat_ms = 0
    if priority == 1:
        beat_min = getattr(config, "POST_PUNCHLINE_BEAT_MS_MIN", 0)
        beat_max = getattr(config, "POST_PUNCHLINE_BEAT_MS_MAX", 0)
        if beat_max > 0 and beat_max >= beat_min:
            post_beat_ms = random.randint(beat_min, beat_max)
    if post_beat_ms_override > 0:
        post_beat_ms = max(post_beat_ms, post_beat_ms_override)
    asked_question = _assistant_asked_question(text)
    if asked_question:
        post_beat_ms = 0

    trace = _current_character_loop_trace.get()
    _mark_first_response_queued(trace, text=text, priority=priority)

    def _on_playback_start() -> None:
        _mark_first_response_audio_started(trace)

    done = speech_queue.enqueue(
        text, emotion, priority=priority,
        pre_beat_ms=pre_beat_ms, post_beat_ms=post_beat_ms,
        voice_settings=voice_settings,
        on_start=_on_playback_start if trace is not None else None,
        log_text=log_text,
        on_audio_end=on_audio_end,
        comedy_mode=comedy_mode,
    )

    while not done.wait(timeout=0.05):
        if _interrupted.is_set():
            try:
                import sounddevice as sd
                echo_cancel.request_cancel()
                sd.stop()
            except Exception:
                pass
            # Drop our queued item in case it hasn't played yet, then wait for
            # whatever was playing (or our item if it just started) to finish.
            speech_queue.clear_below_priority(priority + 1)
            done.wait(timeout=0.5)
            return False

    # Normal completion — arm the post-TTS handoff. Any spoken Rex line may
    # receive an immediate human reply, so preserve the rolling mic buffer.
    _apply_post_tts_handoff(text, source="blocking")
    return True


def _speak_proactive(
    text: str,
    *,
    emotion: str = "neutral",
    priority: int = 1,
    voice_settings: Optional[dict] = None,
    pre_beat_ms: int = 0,
    post_beat_ms_override: int = 0,
    label: str = "proactive",
    decided_at: Optional[float] = None,
    why: str = "",
) -> bool:
    """Speak a self-initiated line, but yield the floor if the user has started.

    `why` is the caller's plain-words reason, recorded in the decision ledger
    when the line actually plays (so "why did you say that?" has a true answer);
    it defaults to the label.

    Unlike a direct reply (where the user just spoke), a proactive line is decided
    on a silence timer and then spends ~1-2s in LLM + TTS generation before any
    sound — long enough for the user to begin talking unseen, after which Rex used
    to play right over them. This pre-caches the audio so playback is instant, then
    re-checks the mic immediately before the sound: if the user is already
    speaking, it returns False WITHOUT speaking and the normal loop captures their
    turn from the (un-attenuated) rolling buffer. Falls back to plain blocking
    speech when the guard is disabled or in text-only mode.
    """
    if not text or not text.strip():
        return False
    # Speak-time re-validation: if a user turn began AFTER this line was decided
    # (during the LLM+TTS generation gap), the line is stale — drop it instead of
    # talking over the turn the user just took. The audio-level check below only
    # catches the user speaking at this exact instant, not a turn that already
    # arrived and finished transcribing while Rex was generating.
    if decided_at is not None and _last_user_turn_started_at > decided_at:
        _log.info(
            "[interaction] proactive line dropped — user turn started after it was "
            "decided (%s): %r",
            label,
            text,
        )
        return False
    if bool(getattr(config, "PROACTIVE_SPEECH_YIELD_ENABLED", True)) and not _text_only_mode:
        # Collapse the check->sound gap: get the audio ready first so the mic
        # check below happens right before playback, not ~1s before it.
        try:
            from audio import tts
            tts.ensure_cached(text, voice_settings=voice_settings, emotion=emotion)
        except Exception as exc:
            _log.debug("[interaction] proactive pre-cache failed: %s", exc)
        try:
            if barge_guard.user_speaking_now():
                # The user started talking during the ~1-2s we spent generating this line, and Rex
                # was NOT playing through that gap (a lull), so the buffer holds their clean onset.
                # Record where to reach the next capture back to so their opening words aren't clipped.
                if bool(getattr(config, "PROACTIVE_YIELD_RECOVER_ONSET_ENABLED", True)):
                    global _barge_yield_onset_at
                    _barge_yield_onset_at = (
                        float(decided_at) if decided_at
                        else time.monotonic() - float(
                            getattr(config, "PROACTIVE_YIELD_ONSET_LOOKBACK_SECS", 1.5)
                        )
                    )
                _log.info(
                    "[interaction] proactive line yielded — user already speaking (%s): %r",
                    label,
                    text,
                )
                return False
        except Exception as exc:
            _log.debug("[interaction] proactive yield check failed: %s", exc)
    # NEVER talk over Rex's OWN in-flight line. The consciousness proactive path is already
    # gated by speech_engine.can_proactive_speak (which drops a line while speech_queue is
    # playing), but the idle path reaches _speak_blocking directly — so without this an idle
    # line PREEMPTS a visual-curiosity / celebration line that's still playing (field
    # 2026-06-30: the "Strawberry pillows…" line was cut off mid-sentence). Drop the ambient
    # line (one line, then wait) rather than enqueuing it at a priority that preempts.
    if bool(getattr(config, "PROACTIVE_NO_SELF_OVERLAP_ENABLED", True)):
        try:
            from audio import output_gate as _output_gate
            if speech_queue.is_speaking() or _output_gate.is_busy():
                _log.info(
                    "[interaction] proactive line dropped — Rex is still speaking (%s): %r",
                    label, text,
                )
                return False
        except Exception as exc:
            _log.debug("[interaction] self-overlap guard failed: %s", exc)
    completed = _speak_blocking(
        text,
        emotion=emotion,
        priority=priority,
        pre_beat_ms=pre_beat_ms,
        post_beat_ms_override=post_beat_ms_override,
        voice_settings=voice_settings,
    )
    if completed:
        global _last_proactive_line_at
        _last_proactive_line_at = time.monotonic()
        try:
            from intelligence import decision_ledger
            decision_ledger.record(
                "proactive_line",
                why or _PROACTIVE_LABEL_WHY.get(label, f"a {label.replace('_', ' ')} impulse"),
                said=text, detail={"label": label},
            )
        except Exception:
            pass
    return completed


# Plain-words reasons for the interaction-side proactive labels (the ledger pastes
# these into Rex's prompt when someone asks "why did you say that?").
_PROACTIVE_LABEL_WHY = {
    "lean_impulse": "the room had gone quiet and I filled the silence",
    "engagement_probe": "they'd gone quiet on me and I checked whether I was bothering them",
    "idle_banter": "the room was quiet and I made idle banter",
    "idle_outro": "the conversation had wound down and I signed off",
    "room_question": "I noticed something in the room I didn't know and asked",
    "interest_idle_followup": "a lull, so I followed up on one of their interests",
    "low_memory_idle_question": "I barely know them, so I asked a getting-to-know-you question",
    "onboarding_question": "they're new to me and I was getting the basics",
    "onboarding_timeout": "the getting-to-know-you flow timed out",
    "no_response_recovery": "I asked something and got no answer, so I let it go",
}


def _proactive_line_recently_fired(min_gap: Optional[float] = None) -> bool:
    """True if any proactive line played within the last ``min_gap`` seconds, so
    a second one should hold off instead of stacking (one line, then wait)."""
    if min_gap is None:
        min_gap = float(getattr(config, "PROACTIVE_LINE_MIN_GAP_SECS", 6.0) or 0.0)
    if min_gap <= 0 or _last_proactive_line_at <= 0:
        return False
    return (time.monotonic() - _last_proactive_line_at) < min_gap


# AMBIENT proactive purposes whose lines are low-stakes chit-chat — variety matters more
# than the specific line, so an opener that repeats a recent one is dropped. Salient
# reactions (animal arrival, wave-back), greetings, and replies are NOT in this set and are
# never dropped by the opener-diversity guard.
_OPENER_DIVERSITY_PURPOSES = {
    "idle_monologue", "celebration_checkin", "emotional_checkin",
}


def _proactive_opener_repeats(text: str, purpose: Optional[str] = None) -> bool:
    """True when a low-stakes AMBIENT proactive line opens with the same leading word as one
    of Rex's last few lines — the deterministic guard against the 'Good… Good… Good…' stack
    the soft prompt rule failed to stop. Scoped to chit-chat purposes (never salient
    reactions / greetings / replies); config-gated kill switch."""
    if not bool(getattr(config, "PROACTIVE_OPENER_DIVERSITY_GUARD", True)):
        return False
    if purpose is not None and str(purpose) not in _OPENER_DIVERSITY_PURPOSES:
        return False
    try:
        from intelligence import comedy_modes
        lookback = int(getattr(config, "PROACTIVE_OPENER_DIVERSITY_LOOKBACK", 3))
        return comedy_modes.opens_like_recent(text, lookback=lookback)
    except Exception:
        return False


def _post_tts_handoff_policy(text: Optional[str]) -> _PostTtsHandoffPolicy:
    asked_question = _assistant_asked_question(text or "")
    fast_response_expected = _fast_response_handoff_expected(text)
    delay_secs = float(getattr(config, "POST_SPEECH_LISTEN_DELAY_SECS", 0.35))
    # Statements no longer flush by default: a reply that began as Rex finished a
    # statement sits (un-attenuated) in the rolling buffer, and flushing deleted it.
    flush_buffer = bool(getattr(config, "POST_SPEECH_FLUSH_AUDIO_BUFFER", False))
    if fast_response_expected:
        delay_secs = float(
            getattr(config, "POST_QUESTION_LISTEN_DELAY_SECS", delay_secs)
        )
        flush_buffer = bool(
            getattr(config, "POST_QUESTION_FLUSH_AUDIO_BUFFER", False)
        )
    return _PostTtsHandoffPolicy(
        asked_question=asked_question,
        fast_response_expected=fast_response_expected,
        listen_delay_secs=max(0.0, delay_secs),
        flush_buffer=flush_buffer,
    )


def _apply_post_tts_handoff(
    text: Optional[str],
    *,
    source: str = "speech_queue",
) -> _PostTtsHandoffPolicy:
    global _listen_resume_at, _listen_capture_floor_at, _post_tts_flush_needed, _last_speech_at
    global _last_fast_handoff_at, _post_question_retro_scan_at
    policy = _post_tts_handoff_policy(text)
    now = time.monotonic()
    _note_rex_spoke(text)   # own-echo rejection reference (covers every source)

    # Sticky responsiveness: a streamed reply fires this handoff per sentence and
    # again for the whole reply. If Rex asked a question but his trailing sentence
    # is a statement, that last handoff would flip back to the long flush window
    # and delete the human's immediate answer. Keep the responsive (short,
    # no-flush) window for a brief sticky window after any question handoff,
    # regardless of which handoff lands last.
    sticky_secs = float(getattr(config, "POST_QUESTION_HANDOFF_STICKY_SECS", 0.0) or 0.0)
    if policy.fast_response_expected:
        _last_fast_handoff_at = now
    elif sticky_secs > 0.0 and (now - _last_fast_handoff_at) <= sticky_secs:
        policy = _PostTtsHandoffPolicy(
            asked_question=policy.asked_question,
            fast_response_expected=True,
            listen_delay_secs=min(
                policy.listen_delay_secs,
                float(getattr(config, "POST_QUESTION_LISTEN_DELAY_SECS", 0.12)),
            ),
            flush_buffer=bool(getattr(config, "POST_QUESTION_FLUSH_AUDIO_BUFFER", False)),
        )
        _log.debug(
            "[aec] post-tts handoff kept responsive (sticky question window, source=%s)",
            source,
        )

    _last_speech_at = now
    aec_on = hardware_aec.is_active()
    listen_delay = policy.listen_delay_secs
    if aec_on:
        # Hardware AEC removed Rex's voice from the mic — resume listening almost
        # immediately so a reply landing as he finishes is not missed.
        listen_delay = min(
            listen_delay,
            float(getattr(config, "POST_TTS_LISTEN_DELAY_SECS_AEC", 0.05)),
        )
    _listen_resume_at = now + listen_delay
    if policy.fast_response_expected:
        grace = max(
            0.0,
            float(
                getattr(
                    config,
                    "POST_QUESTION_CAPTURE_PREROLL_GRACE_SECS",
                    getattr(config, "POST_TTS_CAPTURE_PREROLL_GRACE_SECS", 0.0),
                )
                or 0.0
            ),
        )
    else:
        grace = max(
            0.0,
            float(getattr(config, "POST_TTS_CAPTURE_PREROLL_GRACE_SECS", 0.0) or 0.0),
        )
    if aec_on:
        # Safe to reach further back past the handoff to recover an overlapping
        # reply: that audio is hardware-AEC'd, so Rex's tail in it is ~16 dB down.
        grace = max(grace, float(getattr(config, "POST_TTS_CAPTURE_PREROLL_GRACE_SECS_AEC", 0.5)))
    # Anchor the floor on when the SOUND stopped, not on when this callback ran
    # (field 2026-08-06 00:10: "I know, am I right?" → HEARD "Am I right?"). This
    # handoff fires from the queue's done-callback, 0.5-1.5s after the audio
    # actually ended (streamed-take cache save, sequence bookkeeping) — and on the
    # fast dev Mac the human's reply starts inside that lag. Those words are in
    # the rolling buffer, CLEAN (playback was already over), but a now-anchored
    # floor lands after them and clips them out of the capture.
    #   hardware AEC: keep the grace reach-back past the real end (residual is
    #     ~17dB down; the 0.12 grace was tuned for exactly that).
    #   software suppression (dev Mac): floor AT the real end — no reach into
    #     playback, where Rex's voice sits at full volume and self-transcribes.
    # Only trust the stamp when it plausibly belongs to THIS handoff: the callback
    # lag is sub-second, so anything older than the bound is a leftover from an
    # earlier line (or, in the suite, an earlier test) and anchoring on it would
    # drag the floor seconds into the past and let capture reach back over
    # unrelated audio. Stale or missing -> the original now-anchored behavior.
    real_end = 0.0
    try:
        real_end = float(echo_cancel.last_playback_ended_at() or 0.0)
    except Exception:
        real_end = 0.0
    max_lag = float(getattr(config, "CAPTURE_FLOOR_PLAYBACK_END_MAX_LAG_SECS", 3.0) or 0.0)
    if 0.0 < real_end <= now and (now - real_end) <= max_lag:
        _listen_capture_floor_at = max(0.0, real_end - (grace if aec_on else 0.0))
    else:
        _listen_capture_floor_at = max(0.0, now - grace)
    # A question invites an IMMEDIATE answer — arm the one-shot retro scan so a
    # short reply spoken in the dead window before the loop's first live read is
    # recovered from the rolling buffer instead of silently lost.
    if policy.fast_response_expected and bool(
        getattr(config, "POST_QUESTION_RETRO_SCAN_ENABLED", True)
    ):
        _post_question_retro_scan_at = now
    else:
        _post_question_retro_scan_at = 0.0
    if policy.flush_buffer:
        stream.flush()
        _post_tts_flush_needed = True
    else:
        _post_tts_flush_needed = False
    try:
        vad.reset_state()
    except Exception as exc:
        _log.debug("[aec] VAD reset after post-TTS handoff failed: %s", exc)
    _log.debug(
        "[aec] post-tts handoff source=%s asked_question=%s fast_response=%s delay=%.3fs flush=%s",
        source,
        policy.asked_question,
        policy.fast_response_expected,
        policy.listen_delay_secs,
        policy.flush_buffer,
    )
    return policy


def _reply_playback_tail_secs(asked_question: bool) -> float:
    """Mic-attenuation tail to hold after a spoken reply ends.

    Questions and statements both invite immediate replies, so both use a short
    tail — long enough to let room echo of Rex's own voice decay, short enough that
    a human reply starting as Rex finishes is detected promptly. Falls back to the
    general post-playback tail if the specific knob is unset.

    When the ReSpeaker Lite's hardware AEC is active it has already removed Rex's
    voice from the mic, so the tail only needs to cover the speaker's mechanical
    settle — shrink it so a reply landing as Rex finishes is not attenuated away.
    """
    if hardware_aec.is_active():
        return float(getattr(config, "POST_PLAYBACK_SUPPRESSION_SECS_AEC", 0.05))
    general = float(getattr(config, "POST_PLAYBACK_SUPPRESSION_SECS", 0.5))
    if asked_question:
        return float(getattr(config, "POST_QUESTION_PLAYBACK_SUPPRESSION_SECS", general))
    return float(getattr(config, "POST_SPEECH_PLAYBACK_SUPPRESSION_SECS", general))


def _end_response_sequence_for_text(text: Optional[str]) -> None:
    policy = _post_tts_handoff_policy(text)
    tail_secs = _reply_playback_tail_secs(policy.fast_response_expected)
    echo_cancel.end_sequence(flush=policy.flush_buffer, tail_secs=tail_secs)


def _arm_post_tts_window(item=None) -> None:
    """Arm the post-TTS deaf window. Registered with speech_queue so it fires
    after every queue item — not just items played via _speak_blocking.

    ALSO releases the AEC sequence hold once the queue is genuinely drained.
    THE FIX for "I pause a second after he speaks and he doesn't hear my first
    line" (field 2026-08-05, three marked repeats in one run): start_sequence()
    defers every per-segment set_playing(False) until end_sequence(), and
    end_sequence lived at the END of the reply path — behind the post-greet
    relationship ask, the curiosity routine, and pool-topic recording. So the
    mic stayed attenuated for 1-5s AFTER Rex's last audio (measured across five
    runs), `_chunk_for_vad` flattened the human's reply, VAD never fired, and the
    turn left NO trace anywhere — not even in the capture telemetry, which
    reported captured=6 / dropped=0 for a run containing three lost utterances.
    Suppression must end when the SOUND ends, not when the bookkeeping does.

    Gated on is_drained() rather than `not is_speaking()`: the latter is briefly
    true between the sentences of one streamed reply, and releasing there would
    re-open the mic into Rex's own next sentence. A later line re-suppresses on
    its own playback, so releasing early costs nothing.
    """
    text = getattr(item, "text", None)
    _apply_post_tts_handoff(text, source="speech_queue")
    try:
        if bool(getattr(config, "AEC_RELEASE_ON_QUEUE_DRAIN", True)) and \
                speech_queue.is_drained():
            _end_response_sequence_for_text(text)
    except Exception as exc:
        _log.debug("[aec] drain-release skipped: %s", exc)


# ── Own-echo (reference-text) rejection ───────────────────────────────────────
# With hardware AEC the mic stays live while Rex plays (barge-in, commands over
# music). The XU316 cancels ~17 dB, but his residual can still cross the VAD and
# transcribe VERBATIM — field 2026-07-23 19:56: the "Something's in my way" blocked
# announce came back 4 s later as unknown_voice_2 saying the same words, spawned an
# anonymous speaker, and got a full LLM reply. Every line Rex speaks is noted here
# (at playback start AND at the post-TTS handoff), and a fresh transcript that
# near-matches one of his own recent lines is dropped as self-echo.
_recent_rex_lines: "deque[tuple[str, float]]" = deque(maxlen=24)
_recent_rex_lines_lock = threading.Lock()


def _normalize_echo_text(text: Optional[str]) -> str:
    cleaned = re.sub(r"\[[^\]]{1,32}\]", " ", str(text or ""))   # strip [emotion] tags
    cleaned = re.sub(r"[^a-z0-9' ]+", " ", cleaned.lower())
    return " ".join(cleaned.split())


def _note_rex_spoke(text: Optional[str]) -> None:
    norm = _normalize_echo_text(text)
    if not norm:
        return
    now = time.monotonic()
    with _recent_rex_lines_lock:
        _recent_rex_lines.append((norm, now))


def _note_rex_spoke_item(item=None) -> None:
    _note_rex_spoke(getattr(item, "text", None))


def note_external_tts(text: Optional[str]) -> None:
    """Register a line spoken OUTSIDE the speech queue (startup boot/ready lines
    in main.py play via tts.speak directly) so own-echo rejection covers it.
    Field 2026-08-01 17:00: the startup ready line was never noted here, its
    echo transcribed as unknown_voice_1, and Rex greeted his own voice."""
    _note_rex_spoke(text)


# Short words that really are far likelier to be the human than an echo, even verbatim.
# Backchannels and answers carry no information about WHO said them, so they keep the
# original min-words protection; a distinctive word like "naturally" does not.
_ECHO_SHORT_COMMON_WORDS = frozenset({
    "yeah", "yes", "yep", "no", "nope", "okay", "ok", "sure", "right", "hmm", "huh",
    "oh", "ah", "uh", "um", "well", "hi", "hey", "hello", "bye", "thanks", "please",
    "what", "why", "how", "who", "when", "where", "stop", "wait", "sorry", "cool",
    "nice", "good", "great", "true", "exactly", "maybe", "nothing", "everything",
})


def _looks_like_short_own_echo(norm: str) -> bool:
    """A 1-2 word transcript that is verbatim the opening of a line Rex JUST spoke.

    Deliberately narrow: inside the post-TTS capture seam only, whole-word prefix match
    only, and never for a common backchannel. See the caller for the field case.
    """
    if not bool(getattr(config, "OWN_ECHO_SHORT_PREFIX_ENABLED", True)):
        return False
    words = norm.split()
    if not words or len(words) > 2:
        return False
    if any(w in _ECHO_SHORT_COMMON_WORDS for w in words):
        return False
    seam_secs = float(getattr(config, "OWN_ECHO_SEAM_SECS", 8.0))
    now = time.monotonic()
    with _recent_rex_lines_lock:
        recent = [(line, now - at) for line, at in _recent_rex_lines]
    for line, age in recent:
        if not line or age > seam_secs:
            continue
        line_words = line.split()
        if line_words[:len(words)] == words:
            return True
    return False


def _looks_like_own_echo(text: str) -> bool:
    """True when a transcript near-matches something Rex himself just said."""
    if not bool(getattr(config, "OWN_ECHO_REJECT_ENABLED", True)):
        return False
    norm = _normalize_echo_text(text)
    min_words = int(getattr(config, "OWN_ECHO_MIN_WORDS", 3))
    if not norm or len(norm.split()) < min_words:
        # 1-2 word overlaps ("yeah", "okay") are far likelier to be the human — EXCEPT
        # a distinctive word that is verbatim how Rex just opened a line. Field
        # 2026-08-06: his own "Naturally. The outage got a vote of no confidence…" came
        # back as a bare "Naturally." from the capture seam, sailed under this floor,
        # and was answered as a mystery voice ("who are you?"). A confident voiceprint
        # match to a real human still overrides this at the call site
        # (OWN_ECHO_VOICE_OVERRIDE_SCORE), so a person genuinely saying it is safe.
        return _looks_like_short_own_echo(norm)
    window = float(getattr(config, "OWN_ECHO_WINDOW_SECS", 12.0))
    ratio_floor = float(getattr(config, "OWN_ECHO_SIMILARITY", 0.85))
    # Inside the capture seam right after a line played, the AEC residual garbles
    # the echo into homophones ("my circuits are hot" → "my tickets are hot"), so
    # a looser floor applies to freshly spoken lines only.
    seam_secs = float(getattr(config, "OWN_ECHO_SEAM_SECS", 8.0))
    seam_floor = float(getattr(config, "OWN_ECHO_SEAM_SIMILARITY", 0.65))
    now = time.monotonic()
    with _recent_rex_lines_lock:
        recent = [
            (line, now - at) for line, at in _recent_rex_lines if (now - at) <= window
        ]
    for line, age in recent:
        if not line:
            continue
        # Verbatim containment (echo captures are often a clean prefix/suffix of
        # the line) or high overall similarity.
        if norm == line or (len(norm) >= 10 and norm in line):
            return True
        floor = seam_floor if age <= seam_secs else ratio_floor
        if difflib.SequenceMatcher(None, norm, line).ratio() >= floor:
            return True
    # Coverage: an echo transcript can CONCATENATE several of Rex's lines
    # (field 2026-08-02 12:36: boot filler + ready line came back as one
    # 44-word "utterance" — each single line only ratio-matched ~0.5, under
    # even the seam floor). Strip every recent line out; if the remainder is
    # a small fraction, the transcript was composed of his own lines.
    # Wider window than the per-line ratio check: a concatenated echo can
    # splice a 20s-old line onto a fresh one (field 2026-08-02 13:56).
    coverage_window = float(getattr(config, "OWN_ECHO_COVERAGE_WINDOW_SECS", 45.0))
    with _recent_rex_lines_lock:
        coverage_lines = [
            line for line, at in _recent_rex_lines
            if (now - at) <= coverage_window
        ]
    residue = norm
    matched_any = False
    for line in coverage_lines:
        if line and len(line) >= 12 and line in residue:
            residue = residue.replace(line, " ")
            matched_any = True
    if matched_any:
        residue = re.sub(r"\s+", " ", residue).strip()
        max_frac = float(getattr(config, "OWN_ECHO_MAX_RESIDUE_FRAC", 0.2))
        if len(residue) <= max(12, int(len(norm) * max_frac)):
            return True
    return False


def _speak_async(text: str, emotion: str = "neutral") -> None:
    if not _can_speak() or not text:
        return
    text = llm.clean_response_text(text)
    if not text:
        return
    if speech_queue.is_speaking():
        return
    speech_queue.enqueue(text, emotion, priority=0)


# ── Pet-directed speech (field 2026-08-02 13:55: "Come here, Max. Max, come
# here." fired motion_agency.request_come — the robot DROVE at the speaker off
# a command aimed at the dog; "Lay down. Lay down." got answered as if Rex were
# being told to lie down). Two shapes:
#   1. A known pet name + an imperative in the same utterance — the imperative
#      belongs to the pet, whatever it is.
#   2. Bare pet-only commands (lay down / sit / stay / fetch...) that make no
#      sense addressed to a droid with no lie-down pose — always pet/child-
#      directed. "come here" / "turn around" are NOT in this set (real Rex
#      commands); they are only gated when a pet name appears alongside.
_PET_IMPERATIVE_RE = re.compile(
    r"\b(?:come(?:\s+(?:here|on))?|sit|stay|down|off|no|heel|fetch|drop\s+it|"
    r"leave\s+it|lay|lie|go(?:\s+(?:lay|lie|home|outside))?|get\s+(?:down|up|off|over)|"
    r"good\s+(?:boy|girl)|bad\s+(?:boy|girl)|treat|walkies?)\b",
    re.IGNORECASE,
)
_PET_ONLY_COMMAND_RE = re.compile(
    r"^\s*(?:(?:go\s+)?(?:lay|lie)(?:\s+down)?|sit(?:\s+down)?|stay|heel|fetch|"
    r"drop\s+it|leave\s+it|roll\s+over|shake|paw|speak|off|get\s+down|get\s+off|"
    r"go\s+(?:home|outside|potty)|good\s+(?:boy|girl)|bad\s+(?:boy|girl)|"
    r"no+|uh\s*huh|come\s+on)"
    r"(?:\s*[.!,]\s*(?:(?:go\s+)?(?:lay|lie)(?:\s+down)?|sit(?:\s+down)?|stay|"
    r"heel|fetch|drop\s+it|leave\s+it|roll\s+over|off|get\s+down|no+|uh\s*huh|"
    r"come\s+on|good\s+(?:boy|girl)))*\s*[.!,]?\s*$",
    re.IGNORECASE,
)


_REX_NAME_ADDRESS_RE = re.compile(r"\b(?:rex|r3x|r3\s*-?\s*x|dj\s*r3x)\b", re.IGNORECASE)
_SECOND_PERSON_ASK_RE = re.compile(
    r"\b(?:can|could|would|will|do|did|are|were|have|should)\s+you\b|"
    r"\bwhat(?:'s| is| are| do)?\s+you\b|\byour\s+(?:thoughts|opinion|take)\b",
    re.IGNORECASE,
)


def _group_chatter_directed_evidence(text: str) -> Optional[str]:
    """Why this turn counts as aimed at Rex during group chatter, else None.

    Deterministic on purpose (runs before any LLM work): name/wake mention, a
    parsed command, an answer Rex is explicitly waiting on, the query shapes
    the router recognizes (weather/vision/look), or a second-person ask."""
    cleaned = (text or "").strip()
    if not cleaned:
        return None
    if _REX_NAME_ADDRESS_RE.search(cleaned):
        return "name_mention"
    try:
        if command_parser.parse(cleaned) is not None:
            return "command"
    except Exception:
        pass
    try:
        if consciousness.is_waiting_for_response():
            return "awaiting_answer"
    except Exception:
        pass
    try:
        if action_router._WEATHER_QUERY_RE.search(cleaned):
            return "weather_query"
        if action_router.has_vision_query_evidence(cleaned):
            return "vision_query"
        if action_router.has_directed_look_evidence(cleaned):
            return "directed_look"
        # Drive commands ("turn to your left", "back up four feet", "come
        # here") — nobody says these to another human across the room.
        if (
            action_router._MOTION_TURN_RE.search(cleaned)
            or action_router._MOTION_FWD_RE.search(cleaned)
            or action_router._MOTION_BACK_RE.search(cleaned)
            or action_router._MOTION_COME_RE.search(cleaned)
        ):
            return "motion_command"
    except Exception:
        pass
    if _SECOND_PERSON_ASK_RE.search(cleaned):
        return "second_person_ask"
    return None


def _pet_directed_speech(text: str) -> Optional[str]:
    """Return a reason string when the utterance is aimed at a pet, else None."""
    if not bool(getattr(config, "PET_DIRECTED_SPEECH_GUARD_ENABLED", True)):
        return None
    cleaned = (text or "").strip()
    if not cleaned:
        return None
    lowered = cleaned.lower()
    for raw_name in getattr(config, "PET_NAMES", ()) or ():
        name = str(raw_name).strip().lower()
        if not name:
            continue
        if re.search(rf"\b{re.escape(name)}\b", lowered) and (
            _PET_IMPERATIVE_RE.search(lowered)
        ):
            return f"pet_name:{name}"
    if _PET_ONLY_COMMAND_RE.match(cleaned):
        # Rex just asked a question and the reply window is open — a bare "No."
        # is almost certainly the ANSWER, not someone scolding the dog (field
        # 2026-08-07 18:20: "did you land on one?" → "No." was eaten as
        # pet_only_command and Bret had to repeat himself). The pet-name branch
        # above still fires — "Max, no" stays ignored even mid-question.
        try:
            if consciousness.is_waiting_for_response():
                return None
        except Exception:
            pass
        return "pet_only_command"
    return None


def _audio_group_chatter_active() -> bool:
    if not bool(getattr(config, "GROUP_CHATTER_ENABLED", True)):
        return False
    try:
        scene = world_state.get("audio_scene") or {}
    except Exception:
        return False
    until = scene.get("group_chatter_until")
    if until is not None:
        try:
            if time.time() <= float(until):
                return True
            scene["group_chatter_detected"] = False
            scene["group_chatter_until"] = None
            scene["group_chatter_reason"] = None
            world_state.update("audio_scene", scene)
            return False
        except (TypeError, ValueError):
            pass
    return bool(scene.get("group_chatter_detected"))


def _set_audio_group_chatter(reason: str) -> None:
    if not bool(getattr(config, "GROUP_CHATTER_ENABLED", True)):
        return
    try:
        scene = world_state.get("audio_scene") or {}
        hold = float(getattr(config, "GROUP_CHATTER_HOLD_SECS", 6.0))
        scene["group_chatter_detected"] = True
        scene["group_chatter_until"] = time.time() + max(0.0, hold)
        scene["group_chatter_reason"] = reason
        world_state.update("audio_scene", scene)
    except Exception as exc:
        _log.debug("group chatter world_state update failed: %s", exc)


def _voice_turn_label(
    *,
    person_id: Optional[int],
    raw_best_id: Optional[int],
    raw_best_score: float,
) -> str:
    if person_id is not None:
        return f"known:{person_id}"
    candidate_floor = float(getattr(config, "GROUP_CHATTER_VOICE_CANDIDATE_FLOOR", 0.30))
    if raw_best_id is not None and raw_best_score >= candidate_floor:
        return f"candidate:{raw_best_id}"
    return "unknown"


def _note_voice_turn_for_group_chatter(
    *,
    person_id: Optional[int],
    raw_best_id: Optional[int],
    raw_best_score: float,
) -> bool:
    """
    Mark group chatter when the raw voice candidate changes repeatedly.

    Resemblyzer only compares against known prints, so unknown adults may appear
    as low-confidence swings between known candidates. Those swings are exactly
    the useful signal here: not "who is this?", but "there are multiple voices."
    """
    if not bool(getattr(config, "GROUP_CHATTER_ENABLED", True)):
        return False

    now = time.time()
    window = float(getattr(config, "GROUP_CHATTER_VOICE_WINDOW_SECS", 10.0))
    low_conf_max = float(getattr(config, "GROUP_CHATTER_VOICE_LOW_CONF_MAX", 0.62))
    label = _voice_turn_label(
        person_id=person_id,
        raw_best_id=raw_best_id,
        raw_best_score=raw_best_score,
    )
    low_confidence = person_id is None or raw_best_score <= low_conf_max

    _recent_voice_turns.append((now, label, low_confidence))
    cutoff = now - max(0.0, window)
    while _recent_voice_turns and _recent_voice_turns[0][0] < cutoff:
        _recent_voice_turns.popleft()

    labels = [entry[1] for entry in _recent_voice_turns]
    low_conf_count = sum(1 for entry in _recent_voice_turns if entry[2])
    changes = sum(1 for a, b in zip(labels, labels[1:]) if a != b)
    if (
        len(labels) >= int(getattr(config, "GROUP_CHATTER_VOICE_MIN_TURNS", 3))
        and changes >= int(getattr(config, "GROUP_CHATTER_VOICE_MIN_CHANGES", 2))
        and low_conf_count >= 2
    ):
        _set_audio_group_chatter("rapid_voice_changes")
        _log.info(
            "[interaction] group chatter detected from voice changes "
            "(turns=%d changes=%d labels=%s raw_score=%.3f)",
            len(labels), changes, labels[-6:], raw_best_score,
        )
        return True
    return False


def _normalize_voice_embedding(embedding: Any) -> Optional[np.ndarray]:
    try:
        arr = np.asarray(embedding, dtype=np.float32).reshape(-1)
    except Exception:
        return None
    if arr.size == 0:
        return None
    norm = float(np.linalg.norm(arr))
    if norm <= 1e-10:
        return None
    return (arr / norm).astype(np.float32)


def _clear_anonymous_speaker_slots() -> None:
    global _anonymous_speaker_next_id, _last_speaker_turn
    _last_speaker_turn = None
    _anonymous_speaker_slots.clear()
    _anonymous_speaker_next_id = 1


def _retire_anonymous_speaker_slot(
    label: Optional[str],
    *,
    person_id: Optional[int] = None,
    person_name: Optional[str] = None,
) -> None:
    if not label:
        return
    # Promotion: when this anonymous voice is finally identified, link its
    # persisted signature to the now-known person so the cross-session voice
    # memory belongs to them (their next-session match goes straight to the
    # person; the caller also enrolls the audio as a real voice biometric).
    retired = [slot for slot in _anonymous_speaker_slots if slot.label == label]
    if person_id is not None:
        for slot in retired:
            if slot.signature_id is not None:
                try:
                    voice_signatures.attach_person(slot.signature_id, int(person_id))
                except Exception as exc:
                    _log.debug("[anonymous_speaker] signature promotion failed: %s", exc)
    before = len(_anonymous_speaker_slots)
    _anonymous_speaker_slots[:] = [
        slot for slot in _anonymous_speaker_slots if slot.label != label
    ]
    if len(_anonymous_speaker_slots) != before:
        _log.info(
            "[anonymous_speaker] retired label=%s person_id=%s name=%r",
            label,
            person_id,
            person_name,
        )


def _resolve_anonymous_speaker_slot(
    audio_array: np.ndarray,
    *,
    person_id: Optional[int],
    raw_best_id: Optional[int],
    raw_best_name: Optional[str],
    raw_best_score: float,
    short_clip: bool = False,
) -> tuple[Optional[str], Optional[float], Optional[dict]]:
    """Resolve an unresolved recurring voice.

    ``short_clip``: the clip is too brief to trust as a NEW voice — an existing
    slot or a person-linked signature may still claim it, but no slot is minted.

    Returns ``(label, match_score, resolved_person)``:
      * ``label`` — a session-only anonymous slot label (``unknown_voice_N``) when
        the voice is unknown, else None.
      * ``resolved_person`` — ``{"person_id", "person_name"}`` when the voice
        confidently matches a CROSS-SESSION signature that was already linked to a
        known person (named-then-departed in an earlier session); the caller should
        then treat the turn as that known speaker. None otherwise.
    """
    global _anonymous_speaker_next_id
    if person_id is not None:
        return None, None, None
    if not bool(getattr(config, "ANONYMOUS_SPEAKER_SLOTS_ENABLED", True)):
        return None, None, None

    try:
        embedding = _normalize_voice_embedding(speaker_id.get_embedding(audio_array))
    except Exception as exc:
        _log.debug("[anonymous_speaker] embedding failed: %s", exc)
        return None, None, None
    if embedding is None:
        return None, None, None

    now = time.time()
    threshold = float(getattr(config, "ANONYMOUS_SPEAKER_SLOT_MATCH_THRESHOLD", 0.74))
    sticky_threshold = float(
        getattr(config, "ANONYMOUS_SPEAKER_SLOT_STICKY_THRESHOLD", 0.70)
    )
    best_slot: Optional[_AnonymousSpeakerSlot] = None
    best_score: Optional[float] = None
    for slot in _anonymous_speaker_slots:
        if slot.embedding.shape != embedding.shape:
            continue
        # Mapped onto the Resemblyzer-calibrated threshold scale (see voice_score).
        score = _voice_score.map_similarity(float(np.dot(slot.embedding, embedding)))
        if best_score is None or score > best_score:
            best_score = score
            best_slot = slot

    raw_id = _safe_int(raw_best_id)
    raw_candidate_sticky = (
        best_slot is not None
        and best_score is not None
        and raw_id is not None
        and best_slot.raw_best_id is not None
        and raw_id == best_slot.raw_best_id
        and best_score >= sticky_threshold
    )
    # RECENT sticky: a slot active moments ago matching at a modest bar is the same
    # person still talking. The raw-candidate condition above breaks exactly when two
    # enrolled prints overlap — the top candidate flip-flops between them per
    # utterance (field log 2026-07-05-21-22: JT's turns matched his prior slot at
    # 0.702/0.698/0.609 but raw flipped JT→Bret→Bret, so every line minted a fresh
    # Guest slot). Same-conversation continuity doesn't need the raw label to agree.
    recent_secs = float(getattr(config, "ANONYMOUS_SPEAKER_RECENT_STICKY_SECS", 180.0))
    recent_bar = float(getattr(config, "ANONYMOUS_SPEAKER_RECENT_STICKY_THRESHOLD", 0.62))
    recent_sticky = (
        best_slot is not None
        and best_score is not None
        and (now - float(best_slot.last_seen_at or 0.0)) <= recent_secs
        and best_score >= recent_bar
    )
    if (
        best_slot is not None
        and best_score is not None
        and (best_score >= threshold or raw_candidate_sticky or recent_sticky)
    ):
        blend_weight = float(min(max(best_slot.turns, 1), 5))
        blended = _normalize_voice_embedding(
            (best_slot.embedding * blend_weight) + embedding
        )
        if blended is not None:
            best_slot.embedding = blended
        best_slot.turns += 1
        best_slot.last_seen_at = now
        best_slot.raw_best_id = _safe_int(raw_best_id)
        best_slot.raw_best_name = raw_best_name
        best_slot.raw_best_score = _safe_round_score(raw_best_score)
        # Cross-session persistence: keep this voice's signature fresh once it has
        # recurred enough to be worth remembering across sessions.
        try:
            persist_min = int(getattr(config, "VOICE_SIGNATURE_PERSIST_MIN_TURNS", 2))
            if best_slot.signature_id is not None:
                voice_signatures.bump(best_slot.signature_id, embedding)
            elif best_slot.turns >= persist_min:
                best_slot.signature_id = voice_signatures.record(
                    embedding, label=best_slot.label
                )
        except Exception as exc:
            _log.debug("[anonymous_speaker] signature persist (match) failed: %s", exc)
        score_out = _safe_round_score(best_score)
        _log.info(
            "[anonymous_speaker] matched label=%s score=%.3f turns=%d raw_candidate=%s/%r raw_score=%.3f reason=%s",
            best_slot.label,
            float(best_score),
            best_slot.turns,
            raw_best_id,
            raw_best_name,
            float(raw_best_score or 0.0),
            "raw_candidate_sticky" if raw_candidate_sticky else "threshold",
        )
        return best_slot.label, score_out, None

    # Cross-session recognition: does this voice match one Rex persisted in a
    # PRIOR session? Computed once — used both to RESOLVE a known person (below)
    # and to carry the signature onto a fresh anonymous slot.
    prior = None
    try:
        prior = voice_signatures.match(embedding)
    except Exception as exc:
        _log.debug("[anonymous_speaker] signature match (new) failed: %s", exc)

    # If that signature was already linked to a known person (named-then-departed
    # in an earlier session via voice_signatures.attach_person), resolve STRAIGHT to
    # them when the match is confident — this is the READ side the write side was
    # built for. Previously such a person came back as a fresh unknown_voice_N and
    # Rex said "familiar voice, never got a name" when the name was on file.
    if prior is not None:
        prior_pid = _safe_int(prior.get("person_id"))
        prior_score = float(prior.get("score") or 0.0)
        if (
            prior_pid is not None
            and bool(getattr(config, "VOICE_SIGNATURE_RESOLVE_PERSON_ENABLED", True))
            and _signature_resolves_to_person(
                prior_score, prior.get("last_seen_at"), person_id=prior_pid
            )
        ):
            prow = None
            try:
                prow = people_memory.get_person(prior_pid)
            except Exception as exc:
                _log.debug("[anonymous_speaker] resolve get_person failed: %s", exc)
            if prow is not None:
                try:
                    voice_signatures.bump(prior.get("id"), embedding)
                except Exception:
                    pass
                _log.info(
                    "[anonymous_speaker] cross-session voice RESOLVED to known "
                    "person_id=%s name=%r (signature id=%s score=%.3f) — no slot minted",
                    prior_pid, prow.get("name"), prior.get("id"), prior_score,
                )
                return None, _safe_round_score(prior_score), {
                    "person_id": prior_pid,
                    "person_name": prow.get("name"),
                }

    if short_clip:
        _log.info(
            "[anonymous_speaker] short clip — not minting a slot (best_existing=%s "
            "raw_candidate=%s/%r raw_score=%.3f)",
            f"{best_score:.3f}" if best_score is not None else None,
            raw_best_id, raw_best_name, float(raw_best_score or 0.0),
        )
        return None, _safe_round_score(best_score), None

    max_slots = int(getattr(config, "ANONYMOUS_SPEAKER_SLOT_MAX", 8) or 0)
    if max_slots <= 0 or len(_anonymous_speaker_slots) >= max_slots:
        _log.info(
            "[anonymous_speaker] no slot available max=%d best_score=%s raw_candidate=%s/%r",
            max_slots,
            f"{best_score:.3f}" if best_score is not None else None,
            raw_best_id,
            raw_best_name,
        )
        return None, _safe_round_score(best_score), None

    label = f"unknown_voice_{_anonymous_speaker_next_id}"
    _anonymous_speaker_next_id += 1
    signature_id: Optional[int] = None
    recognized = False
    if prior is not None:
        signature_id = prior.get("id")
        recognized = True
        try:
            voice_signatures.bump(signature_id, embedding)
        except Exception as exc:
            _log.debug("[anonymous_speaker] signature bump (new) failed: %s", exc)
        _log.info(
            "[anonymous_speaker] %s matches a voice from a previous session "
            "(signature id=%s score=%.3f turns=%s person_id=%s)",
            label, signature_id, float(prior.get("score") or 0.0),
            prior.get("turns"), prior.get("person_id"),
        )
    _anonymous_speaker_slots.append(
        _AnonymousSpeakerSlot(
            label=label,
            embedding=embedding,
            first_seen_at=now,
            last_seen_at=now,
            raw_best_id=_safe_int(raw_best_id),
            raw_best_name=raw_best_name,
            raw_best_score=_safe_round_score(raw_best_score),
            signature_id=signature_id,
            recognized_across_sessions=recognized,
        )
    )
    _log.info(
        "[anonymous_speaker] created label=%s raw_candidate=%s/%r raw_score=%.3f best_existing=%s recognized=%s",
        label,
        raw_best_id,
        raw_best_name,
        float(raw_best_score or 0.0),
        f"{best_score:.3f}" if best_score is not None else None,
        recognized,
    )
    return label, None, None


def _format_current_time_response(now: Optional[datetime] = None) -> str:
    """Return a deterministic clock answer without an LLM round trip."""
    now = now or datetime.now()
    h12 = now.hour % 12 or 12
    ampm = "AM" if now.hour < 12 else "PM"
    return f"It's {h12}:{now.minute:02d} {ampm}."


def _format_current_date_response(now: Optional[datetime] = None) -> str:
    """Return a deterministic date answer without an LLM round trip."""
    now = now or datetime.now()
    return f"Today is {now.strftime('%A, %B')} {now.day}, {now.year}."


_DATE_QUERY_PAT = re.compile(
    # date-vs-time tiebreaker: explicit date words only (no bare "today", which
    # also appears in time questions like "what time is it today").
    r"\b(?:date|weekday|day\s+of\s+(?:the\s+)?week)\b|"
    r"\bwhat(?:'s| is)?\s+today'?s\s+date\b|"
    r"^\s*what\s+day\b",
    re.IGNORECASE,
)


def _looks_like_date_query(text: str) -> bool:
    return bool(_DATE_QUERY_PAT.search(text or ""))


def _wake_ack() -> None:
    global _last_wake_ack
    pool = list(getattr(config, "WAKE_ACKNOWLEDGMENTS", []) or [])
    if not pool:
        return
    candidates = [line for line in pool if line != _last_wake_ack] or pool
    chosen = random.choice(candidates)
    if getattr(config, "WAKE_ACK_REQUIRE_CACHE", True):
        try:
            from audio import tts
            if not tts.is_cached(chosen):
                _log.warning(
                    "[wake_word] wake ack skipped because TTS is not cached: %r",
                    chosen,
                )
                return
        except Exception as exc:
            _log.debug("[wake_word] wake ack cache check failed: %s", exc)
            return
    _last_wake_ack = chosen
    _speak_blocking(chosen, priority=2)


def _choose_transition_line(config_name: str, fallback: str, last_line: Optional[str]) -> str:
    pool = [
        str(line).strip()
        for line in getattr(config, config_name, []) or []
        if str(line).strip()
    ]
    if not pool:
        return fallback
    candidates = [line for line in pool if line != last_line] or pool
    return random.choice(candidates)


def _sleep_mode_line() -> str:
    global _last_sleep_mode_ack
    line = _choose_transition_line(
        "SLEEP_MODE_ACKNOWLEDGMENTS",
        "Fine. Power nap mode. Wake me when the galaxy gets less weird.",
        _last_sleep_mode_ack,
    )
    _last_sleep_mode_ack = line
    return line


def _wake_from_sleep_line() -> str:
    global _last_wake_from_sleep_ack
    line = _choose_transition_line(
        "WAKE_FROM_SLEEP_ACKNOWLEDGMENTS",
        "I'm up. I was dreaming in binary and somehow still got interrupted.",
        _last_wake_from_sleep_ack,
    )
    _last_wake_from_sleep_ack = line
    return line


def _clear_listening_state_for_sleep() -> None:
    global _listen_resume_at, _listen_capture_floor_at, _post_tts_flush_needed
    global _post_question_retro_scan_at
    try:
        speech_queue.clear_below_priority(999)
    except Exception as exc:
        _log.debug("[sleep_mode] speech queue cleanup failed: %s", exc)
    try:
        stream.flush()
    except Exception as exc:
        _log.debug("[sleep_mode] stream flush failed: %s", exc)
    try:
        vad.reset_state()
    except Exception as exc:
        _log.debug("[sleep_mode] VAD reset failed: %s", exc)
    try:
        _situation_assessor.set_vad_active(False)
    except Exception:
        pass
    try:
        consciousness.clear_response_wait()
    except Exception:
        pass
    _wake_word_fired.clear()
    _interrupted.clear()
    _listen_resume_at = 0.0
    _listen_capture_floor_at = 0.0
    _post_tts_flush_needed = False
    _post_question_retro_scan_at = 0.0


def _run_sleep_animation() -> None:
    try:
        from sequences import animations
        animations.sleep()
    except Exception as exc:
        _log.warning("[sleep_mode] sleep animation failed: %s", exc)


def _run_wake_animation() -> None:
    try:
        from sequences import animations
        animations.wake()
    except Exception as exc:
        _log.warning("[sleep_mode] wake animation failed: %s", exc)


def _enter_sleep_mode(*, transition_line: Optional[str] = None) -> str:
    resp = (transition_line or "").strip() or _sleep_mode_line()
    _speak_blocking(resp, emotion="sleepy")
    _clear_listening_state_for_sleep()
    state_module.set_state(State.SLEEP)
    # Sleep is a hard autonomy boundary. Stop any finite command that was already
    # in flight, then the central motion gate rejects every new autonomous command
    # until the dedicated wake transition restores ACTIVE.
    try:
        motion_controller.stop()
    except Exception:
        _log.debug("[sleep_mode] motion stop failed", exc_info=True)
    _run_sleep_animation()
    return resp


def _wake_from_sleep() -> str:
    _clear_listening_state_for_sleep()
    state_module.set_state(State.ACTIVE)
    _run_wake_animation()
    resp = _wake_from_sleep_line()
    _speak_blocking(resp, emotion="happy", priority=2, pre_beat_ms=80, post_beat_ms_override=150)
    return resp


def _wake_from_quiet() -> None:
    """Exit quiet mode when an explicit wake word gets Rex's attention."""
    state_module.set_state(State.ACTIVE)
    _wake_ack()


def _vad_barge_in_enabled() -> bool:
    return bool(getattr(config, "VAD_BARGE_IN_ENABLED", False))


def _effect_allows_listening() -> bool:
    """Keep reading the mic when the only thing playing is a NON-muting sound effect.

    `sound_effects._suppresses_mic` already decided (field 2026-07-25, "the move sound
    effects and motor whine are cutting me off from being heard") that motion/servo/
    headlift whirs are Rex's own machinery and must NOT mute the mic — a motor whine
    transcribes to junk the hallucination filters drop anyway. But that decision only
    reached `echo_cancel`; the capture loop skipped the mic for ANY output-gate holder,
    so a whir still deafened him for its full ~1.5 s.

    Field 2026-08-06: Rex asked what room he was in, a `servo` chirp fired one second
    after he stopped, and the entire answer ("This is the workshop room") landed inside
    that window and was never captured — no VAD, no segment, no transcript. The session
    counter read `mic_skip_output_busy_sfx=148` against `captured=6`.

    Speech-family chirps are voice-like and still mute (they'd be transcribed as words),
    and real speech playback is unaffected — this only relaxes the gate for effects
    that were already exempt. `SOUND_EFFECTS_DRIVE_SUPPRESSES_MIC=True` restores the
    old deafening behavior for the whole class.
    """
    try:
        if speech_queue.is_speaking():
            return False                    # Rex's voice always owns the mic gate
        from audio import output_gate, sound_effects
        if output_gate.active_source() != "sound-effects":
            return False
        return not sound_effects.gated_effect_mutes_mic()
    except Exception:
        return False                        # fail CLOSED: keep the old skip


def _is_interruptible_game_audio_path(path: Optional[str]) -> bool:
    if not path:
        return False
    try:
        from features import games as games_mod
        if not games_mod.is_active():
            return False
    except Exception:
        return False
    try:
        path_obj = Path(str(path))
    except Exception:
        return False
    return path_obj.parent.name == "jeopardy"


def _response_wait_active() -> bool:
    try:
        return bool(consciousness.is_waiting_for_response())
    except Exception as exc:
        _log.debug("[wake_word] response-wait check failed: %s", exc)
        return False


def _rex_frame_expects_reply(
    person_id: Optional[int], *, max_age_secs: float = 30.0
) -> bool:
    """True when Rex has a recent open turn-frame still awaiting a reply.

    The dialogue_act frame is the DURABLE "Rex is waiting for an answer" signal:
    unlike the short consciousness response-wait window (~7s, which expires while
    ElevenLabs is still speaking and the human is still thinking), the frame
    persists with the question. This is the robust gate that keeps a name-shaped
    answer to Rex's own question ("This is leaf" = the user's mistranscribed
    "sleep") from being promoted into an introduction.

    Only consulted for an IDENTIFIED speaker: an unidentified (person_id=None)
    speaker must keep the normal introduction path, and shouldn't be matched
    against a generic untargeted frame.
    """
    if person_id is None:
        return False
    try:
        frame = dialogue_act.active_frame(
            person_id=person_id, max_age_secs=max_age_secs
        )
        return bool(frame is not None and frame.expected_reply_types)
    except Exception as exc:
        _log.debug("[identity] rex-frame expects-reply check failed: %s", exc)
        return False


def _intro_is_answer_to_rex_question(
    has_unknown_newcomer: bool, *, person_id: Optional[int] = None
) -> bool:
    """True when a 'this is X' line is really the ANSWER to a question Rex just
    asked, not an introduction.

    Live-logged misfire: Rex asked "What's your favorite movie?", the reply
    "Mrs. Doubtfire" was transcribed "This is Doubtfire", and that name-bearing
    "this is X" was promoted to introducing a person named Doubtfire — even
    though nobody new was present. A second live failure (2026-06-18): an
    idle-banter question's answer "sleep" transcribed "This is leaf" minted a
    phantom person AFTER the 7s response-wait expired — so we also consult the
    durable dialogue_act frame, not just the short wait window. A name/
    relationship-only introduction with NO visible newcomer, arriving while Rex
    is awaiting a reply to his own question, is the answer. (A genuinely present
    newcomer still introduces fine.)
    """
    return (not has_unknown_newcomer) and (
        _response_wait_active() or _rex_frame_expects_reply(person_id)
    )


def _intro_would_mint_unknown_name(
    parsed_intro,
    *,
    person_id: Optional[int],
    off_camera_unknown: bool,
    has_unknown_for_intro: bool,
) -> bool:
    """Belt-and-suspenders: a bare NAME-ONLY 'this is X' from a confidently
    identified known speaker, with nobody new present and X matching no known
    person, would MINT a brand-new person from one short utterance — the exact
    'normal reply becomes a durable action' failure. Treat it as an answer
    instead. A relationship intro ('this is my brother Wade') still opens a slot
    off-camera, and a genuine visible/off-screen newcomer still introduces.
    """
    if has_unknown_for_intro or off_camera_unknown:
        return False
    if getattr(parsed_intro, "subject_kind", "person") == "pet":
        return False
    if getattr(parsed_intro, "relationship", None):
        return False
    name = (getattr(parsed_intro, "name", "") or "").strip()
    if not name:
        return False
    # Only fire for a confident on-camera/known live speaker (not an unknown voice).
    if person_id is None:
        return False
    try:
        if people_memory.find_person_by_name(name):
            return False  # links to an existing person — that path is fine
    except Exception as exc:
        _log.debug("[identity] mint-guard name lookup failed: %s", exc)
        return False
    return True


def _challenged_voice_is_answering_whos_that(
    text: str,
    anonymous_speaker_label: Optional[str],
) -> bool:
    """True when an unresolved voice that Rex has just asked "who's speaking?" is
    replying with its own name (no relationship word — "this is my brother Wade"
    is still a third-party introduction)."""
    pending = _pending_offscreen_identify
    if not isinstance(pending, dict):
        return False
    ttl = float(getattr(config, "OFFSCREEN_IDENTIFY_WINDOW_SECS", 30.0))
    try:
        if (time.monotonic() - float(pending.get("asked_at") or 0.0)) > ttl:
            return False
    except (TypeError, ValueError):
        return False
    asked_label = pending.get("anonymous_speaker_label")
    if asked_label and anonymous_speaker_label and asked_label != anonymous_speaker_label:
        return False
    if not _challenged_self_identified_name(text):
        return False
    parsed = introductions.detect(_split_aka_alias(text)[0], has_unknown_face=False)
    if getattr(parsed, "relationship", None) or getattr(parsed, "subject_kind", "person") == "pet":
        return False
    return True


def _should_play_active_wake_ack() -> bool:
    if speech_queue.is_speaking() or output_gate.is_busy() or echo_cancel.is_suppressed():
        return False
    if _response_wait_active():
        return False
    return True


_BARE_WAKE_ADDRESS_PAT = re.compile(
    r"^\s*(?:"
    r"hey\s+(?:dj[\s-]*)?r(?:ex|3x)|"
    r"hi\s+(?:dj[\s-]*)?r(?:ex|3x)|"
    r"hello\s+(?:dj[\s-]*)?r(?:ex|3x)|"
    r"yo\s+(?:robot|(?:dj[\s-]*)?r(?:ex|3x))|"
    r"(?:dj[\s-]*)?r(?:ex|3x)"
    r")\s*[.!?]*\s*$",
    re.IGNORECASE,
)

_PLAIN_IDLE_GREETING_PAT = re.compile(
    r"^\s*(?:hello|hi|hey|yo|you there)\s*[.!?]*\s*$",
    re.IGNORECASE,
)


def _is_bare_wake_address(text: str) -> bool:
    return bool(_BARE_WAKE_ADDRESS_PAT.match(text or ""))


def _is_sleep_wake_transcript(text: str) -> bool:
    """Return True for explicit transcribed phrases that should exit sleep."""
    raw = str(text or "").strip().lower()
    if not raw:
        return False
    cleaned = re.sub(r"[^a-z0-9]+", " ", raw).strip()
    compact = re.sub(r"[^a-z0-9]", "", raw)
    if compact in {
        "wakeuprex",
        "wakeupr3x",
        "wakeuprx",
        "rexwakeup",
        "r3xwakeup",
        "rxwakeup",
    }:
        return True
    rex_name = r"(?:d\s*j\s+)?(?:rex|r\s*3\s*x|r3x|rx)"
    wake_prefix = r"(?:(?:hey|yo|ok|okay|alright)\s+)*(?:please\s+)?"
    # A trailing address or particle is not content — "Rex, wake up buddy" and
    # "wake up rex, come on" left him ASLEEP under the old bare fullmatch, and a
    # missed wake is the expensive direction of this error (he cannot be woken by
    # voice at all until someone says the exact phrase). A false wake just makes
    # him listen, so tolerating filler here is the safe asymmetry.
    wake_suffix = (
        r"(?:\s+(?:please|now|already|buddy|bud|pal|dude|man|boy|"
        r"friend|come\s+on|will\s+you))*"
    )
    # Rex's NAME stays mandatory: a bare "wake up" is ambient speech in a room he
    # is asleep in, not an address to him (pinned by
    # test_sleep_wake_transcript_requires_explicit_rex_wake_phrase).
    return bool(
        re.fullmatch(rf"{wake_prefix}wake\s+up\s+{rex_name}{wake_suffix}", cleaned)
        or re.fullmatch(rf"{wake_prefix}{rex_name}\s+wake\s+up{wake_suffix}", cleaned)
    )


def _shutdown_requested() -> bool:
    try:
        if _stop_event.is_set():
            return True
    except Exception:
        pass
    try:
        return state_module.get_state() == State.SHUTDOWN
    except Exception:
        return False


def _prefill_wake_ack_cache() -> None:
    """Warm the tiny wake-ack TTS set so wake feedback is instant."""
    if bool(
        getattr(config, "NO_AUDIO_MODE", False)
        or getattr(config, "AUDIO_OUTPUT_SUPPRESSED", False)
    ):
        return
    if not getattr(config, "WAKE_ACK_REQUIRE_CACHE", True):
        return
    pool = (
        list(getattr(config, "WAKE_ACKNOWLEDGMENTS", []) or [])
        + list(getattr(config, "SLEEP_MODE_ACKNOWLEDGMENTS", []) or [])
        + list(getattr(config, "WAKE_FROM_SLEEP_ACKNOWLEDGMENTS", []) or [])
    )
    if not pool:
        return
    try:
        from audio import tts
        for line in pool:
            try:
                tts.ensure_cached(line)
            except Exception as exc:
                _log.debug("[wake_word] wake ack cache prefill failed for %r: %s", line, exc)
    except Exception as exc:
        _log.debug("[wake_word] wake ack cache prefill unavailable: %s", exc)


def _prefill_slow_path_ack_cache() -> None:
    """Warm slow-path acknowledgment TTS so live turns never fetch it."""
    if bool(
        getattr(config, "NO_AUDIO_MODE", False)
        or getattr(config, "AUDIO_OUTPUT_SUPPRESSED", False)
    ):
        return
    if not bool(getattr(config, "SLOW_PATH_ACK_ENABLED", True)):
        return
    if not bool(getattr(config, "SLOW_PATH_ACK_REQUIRE_CACHE", True)):
        return
    pool = _all_slow_path_ack_lines()
    if not pool:
        return
    try:
        from audio import tts
        for line in pool:
            try:
                tts.ensure_cached(line)
            except Exception as exc:
                _log.debug(
                    "[slow_path_ack] cache prefill failed for %r: %s",
                    line,
                    exc,
                )
    except Exception as exc:
        _log.debug("[slow_path_ack] cache prefill unavailable: %s", exc)


def _prefill_motion_route_ack_cache() -> None:
    """Warm the 'plotting that out' lines so the rescue ack costs no TTS latency.

    The whole point of the ack is that it lands BEFORE the ~1 s interpreter call;
    fetching its audio at speak time would put the latency back."""
    if bool(
        getattr(config, "NO_AUDIO_MODE", False)
        or getattr(config, "AUDIO_OUTPUT_SUPPRESSED", False)
    ):
        return
    if not bool(getattr(config, "MOTION_ROUTE_ENABLED", True)):
        return
    lines = [str(line).strip() for line in
             (getattr(config, "MOTION_ROUTE_ACK_LINES", []) or []) if str(line).strip()]
    denial = str(getattr(config, "MOTION_ROUTE_SPIN_DENIAL_LINE", "") or "").strip()
    if denial:
        lines.append(denial)
    if not lines:
        return
    try:
        from audio import tts
        for line in lines:
            try:
                tts.ensure_cached(line)
            except Exception as exc:
                _log.debug("[motion_route] cache prefill failed for %r: %s", line, exc)
    except Exception as exc:
        _log.debug("[motion_route] cache prefill unavailable: %s", exc)


def _interrupt_ack() -> None:
    _speak_blocking(random.choice(config.INTERRUPT_ACKNOWLEDGMENTS), priority=2)


def _speak_filler() -> None:
    """Speak a latency filler line asynchronously, never repeating back-to-back."""
    global _last_filler
    if not getattr(config, "LATENCY_FILLER_ENABLED", True):
        return
    pool = config.LATENCY_FILLER_LINES
    candidates = [l for l in pool if l != _last_filler] or pool
    chosen = random.choice(candidates)
    if getattr(config, "LATENCY_FILLER_REQUIRE_CACHE", True):
        try:
            from audio import tts
            if not tts.is_cached(chosen):
                _log.debug("[interaction] latency filler skipped — not cached: %r", chosen)
                return
        except Exception as exc:
            _log.debug("[interaction] latency filler cache check failed: %s", exc)
            return
    _last_filler = chosen
    speech_queue.enqueue(chosen, "neutral", priority=1, tag="latency_filler")


def _configured_slow_path_ack_lines(kind: str) -> list[str]:
    raw = getattr(config, "SLOW_PATH_ACK_LINES", {}) or {}
    lines: list[str] = []
    if isinstance(raw, dict):
        value = raw.get(kind) or raw.get("default") or []
        if isinstance(value, str):
            lines = [value]
        else:
            lines = [str(line) for line in value if str(line).strip()]
    elif isinstance(raw, str):
        lines = [raw]
    else:
        lines = [str(line) for line in raw if str(line).strip()]
    return [line.strip() for line in lines if line.strip()]


def _all_slow_path_ack_lines() -> list[str]:
    raw = getattr(config, "SLOW_PATH_ACK_LINES", {}) or {}
    lines: list[str] = []
    if isinstance(raw, dict):
        for value in raw.values():
            if isinstance(value, str):
                lines.append(value)
            else:
                lines.extend(str(line) for line in value if str(line).strip())
    elif isinstance(raw, str):
        lines.append(raw)
    else:
        lines.extend(str(line) for line in raw if str(line).strip())
    seen: set[str] = set()
    result: list[str] = []
    for line in lines:
        cleaned = str(line).strip()
        if cleaned and cleaned not in seen:
            seen.add(cleaned)
            result.append(cleaned)
    return result


def _word_count(text: str) -> int:
    return len(re.findall(r"[A-Za-z0-9']+", text or ""))


def _simple_question(text: str) -> bool:
    cleaned = (text or "").strip()
    if "?" not in cleaned:
        return False
    return _word_count(cleaned) <= 8


def _slow_path_ack_expected_slow(kind: str) -> bool:
    try:
        minimum = float(getattr(config, "SLOW_PATH_ACK_MIN_EXPECTED_SECS", 1.5))
    except (TypeError, ValueError):
        minimum = 1.5
    raw = getattr(config, "SLOW_PATH_ACK_EXPECTED_SECS", {}) or {}
    expected = None
    if isinstance(raw, dict):
        expected = raw.get(kind, raw.get("default"))
    else:
        expected = raw
    try:
        return float(expected) >= minimum
    except (TypeError, ValueError):
        return True


def _slow_path_ack_allowed_for_turn(
    kind: str,
    text: str = "",
    dialogue_decision: Optional[dialogue_act.DialogueActDecision] = None,
) -> bool:
    if kind != "general":
        return True
    try:
        min_words = int(getattr(config, "SLOW_PATH_ACK_GENERAL_MIN_WORDS", 9) or 0)
    except (TypeError, ValueError):
        min_words = 9
    if min_words > 0 and _word_count(text) < min_words:
        return False
    if (
        not bool(getattr(config, "SLOW_PATH_ACK_GENERAL_ALLOW_SIMPLE_QUESTIONS", False))
        and _simple_question(text)
    ):
        return False
    if dialogue_decision is not None and dialogue_decision.label == "answer_to_rex":
        return False
    return True


def _try_slow_path_ack(
    kind: str,
    *,
    text: str = "",
    dialogue_decision: Optional[dialogue_act.DialogueActDecision] = None,
) -> bool:
    """Queue a cached, non-blocking acknowledgment for a known slow path."""
    global _last_slow_path_ack
    if not bool(getattr(config, "SLOW_PATH_ACK_ENABLED", True)):
        return False
    if not _slow_path_ack_allowed_for_turn(kind, text, dialogue_decision):
        return False
    if not _slow_path_ack_expected_slow(kind):
        return False
    trace = _current_character_loop_trace.get()
    if trace is not None and trace.first_response_queued_at is not None:
        return False
    if speech_queue.is_speaking() or output_gate.is_busy() or _interrupted.is_set():
        return False

    pool = _configured_slow_path_ack_lines(kind)
    if not pool:
        return False
    candidates = [line for line in pool if line != _last_slow_path_ack] or pool
    chosen = random.choice(candidates)

    audio_suppressed = bool(
        getattr(config, "NO_AUDIO_MODE", False)
        or getattr(config, "AUDIO_OUTPUT_SUPPRESSED", False)
    )
    if audio_suppressed and not bool(getattr(config, "SLOW_PATH_ACK_IN_TEXT_ONLY", False)):
        return False
    if bool(getattr(config, "SLOW_PATH_ACK_REQUIRE_CACHE", True)) and not audio_suppressed:
        try:
            from audio import tts
            if not tts.is_cached(chosen):
                _log.debug(
                    "[slow_path_ack] skipped kind=%s because TTS is not cached: %r",
                    kind,
                    chosen,
                )
                return False
        except Exception as exc:
            _log.debug("[slow_path_ack] cache check failed kind=%s: %s", kind, exc)
            return False

    queued = _mark_first_response_queued(trace, text=chosen, priority=1)

    def _on_playback_start() -> None:
        _mark_first_response_audio_started(trace)

    try:
        speech_queue.enqueue(
            chosen,
            "neutral",
            priority=1,
            tag="slow_path_ack",
            on_start=_on_playback_start if trace is not None else None,
        )
        _last_slow_path_ack = chosen
        _log.info("[slow_path_ack] queued kind=%s text=%r", kind, chosen)
        return True
    except Exception as exc:
        _log.debug("[slow_path_ack] enqueue failed kind=%s: %s", kind, exc)
        return queued


def _start_latency_filler_timer() -> threading.Event:
    """Start a delayed filler timer and return an event that cancels it.

    Filler used to fire immediately for every utterance, including short grief
    flow replies. Delaying it keeps normal turns quiet while still covering
    genuinely slow LLM calls.
    """
    stop = threading.Event()
    if not getattr(config, "LATENCY_FILLER_ENABLED", True):
        stop.set()
        return stop

    delay = float(getattr(config, "LATENCY_FILLER_DELAY_SECS", 1.4))
    if delay <= 0:
        _speak_filler()
        stop.set()
        return stop

    trace = _current_character_loop_trace.get()

    def _timer() -> None:
        if stop.wait(delay):
            return
        if trace is not None and trace.first_response_queued_at is not None:
            return
        if (
            state_module.get_state() == State.ACTIVE
            and not speech_queue.is_speaking()
            and not output_gate.is_busy()
            and not _interrupted.is_set()
        ):
            _speak_filler()

    threading.Thread(target=_timer, daemon=True, name="latency-filler").start()
    return stop


_QUOTED_QUESTION_RE = re.compile(
    r"(?:“[^”]*\?[^”]*”|\"[^\"]*\?[^\"]*\")"
)
_RESPONSE_QUESTION_START_RE = re.compile(
    r"^\s*(who|what|when|where|why|how|can|could|would|will|do|does|did|"
    r"is|are|am|should|want|wanna|need|got|any|care\s+to)\b",
    re.IGNORECASE,
)
_SHORT_SLOT_QUESTION_RE = re.compile(
    r"\b(?:last\s+name|surname)\b",
    re.IGNORECASE,
)
_IMPERATIVE_RESPONSE_PROMPT_RE = re.compile(
    r"\b(?:give|tell|toss|send|share)\s+(?:me\s+)?(?:your\s+|a\s+)?"
    r"(?:last\s+name|surname)\b|"
    r"\b(?:last\s+name|surname)\s+(?:too|please)\b",
    re.IGNORECASE,
)
def _strip_quoted_questions(text: str) -> str:
    return _QUOTED_QUESTION_RE.sub(
        lambda match: match.group(0).replace("?", ""),
        text or "",
    )


def _assistant_asked_question(text: str) -> bool:
    return _question_expects_response(text)


def _fast_response_handoff_expected(text: Optional[str]) -> bool:
    cleaned = _strip_quoted_questions(str(text or "")).strip()
    if not cleaned:
        return False
    return _question_expects_response(cleaned)


def _question_expects_response(text: str) -> bool:
    cleaned = _strip_quoted_questions(text).strip()
    if not cleaned:
        return False
    if "?" not in cleaned:
        return bool(_IMPERATIVE_RESPONSE_PROMPT_RE.search(cleaned))
    for part in re.split(r"(?<=[.!?])\s+", cleaned):
        if "?" in part and _question_sentence_expects_response(part):
            return True
    return False


def _question_sentence_expects_response(sentence: str) -> bool:
    lowered = (sentence or "").strip().lower()
    if not lowered or "?" not in lowered:
        return False
    if re.search(r"\b(right|okay|ok|huh|yeah)\?\s*$", lowered):
        return False
    if re.search(r"\bwhy\s+(?:risk|bother|would|not)\b.+\bwhen\b", lowered):
        return False
    # Rhetorical "who doesn't / who wouldn't / who hasn't ... ?" — Rex's own
    # flourish, not a real question. Don't arm the no-response quip on these
    # (it fired awkwardly after lines like "who doesn't appreciate a droid...?").
    if re.search(
        r"\bwho\s+(?:doesn'?t|does\s+not|wouldn'?t|would\s+not|hasn'?t|has\s+not|"
        r"isn'?t|ain'?t|can'?t)\b",
        lowered,
    ):
        return False
    # Rhetorical reformulations ("So what you're saying is …?", "So you're
    # telling me …?") restate the human's point for comic effect — they don't
    # expect a literal answer, so they must not arm the no-response quip (the
    # live "No answer. Bold strategy." misfire fired off exactly this shape).
    if re.search(
        r"\bso[, ]+(?:what\s+you'?re\s+saying|you'?re\s+(?:saying|telling)|"
        r"that\s+means|i\s+(?:guess|take\s+it))\b",
        lowered,
    ):
        return False
    if _SHORT_SLOT_QUESTION_RE.search(lowered):
        return True
    words = re.findall(r"[a-z0-9']+", lowered)
    if (
        len(words) <= 4
        and not _RESPONSE_QUESTION_START_RE.search(lowered)
        and not any(word in {"you", "your", "we", "they", "it", "this", "that"} for word in words)
    ):
        return False
    return True


def _question_recovery_cooldown_secs() -> float:
    return max(
        0.0,
        float(getattr(config, "CONVERSATION_NO_RESPONSE_QUIP_SECS", 7.0) or 0.0),
    )


def _should_no_response_recovery_fire(
    *,
    asked_at: float,
    now: Optional[float] = None,
    last_speech_at: Optional[float] = None,
) -> bool:
    if _game_suppresses_conversation():
        return False
    cooldown = _question_recovery_cooldown_secs()
    if cooldown <= 0:
        return False
    current = time.monotonic() if now is None else now
    latest_speech = _last_speech_at if last_speech_at is None else last_speech_at
    return current - asked_at >= cooldown and latest_speech <= asked_at


def _arm_no_response_recovery(
    question_text: str,
    person_id: Optional[int],
) -> None:
    """After Rex asks a question, recover with one quip if nobody answers."""
    global _no_response_recovery_token

    if _game_suppresses_conversation():
        return
    if not _question_expects_response(question_text):
        return
    cooldown = _question_recovery_cooldown_secs()
    if cooldown <= 0:
        return

    asked_at = time.monotonic()
    # Hold the floor: Rex asked a real question, so give the user an actual window
    # to answer before idle banter jumps in with a new prompt.
    global _floor_held_until
    # max() so a longer hold already armed by _register_rex_utterance
    # (POST_REPLY_QUESTION_WAIT_SECS) for a question-bearing reply is not
    # shortened back down to the 10s recovery floor.
    _floor_held_until = max(
        _floor_held_until,
        asked_at + float(getattr(config, "POST_QUESTION_FLOOR_HOLD_SECS", 10.0) or 0.0),
    )
    with _no_response_recovery_lock:
        _no_response_recovery_token += 1
        token = _no_response_recovery_token

    def _timer() -> None:
        _stop_event.wait(cooldown)
        if _stop_event.is_set():
            return
        with _no_response_recovery_lock:
            if token != _no_response_recovery_token:
                return
        if not _should_no_response_recovery_fire(asked_at=asked_at):
            return
        if state_module.get_state() != State.ACTIVE:
            return
        if _game_suppresses_conversation():
            return
        if (
            speech_queue.is_speaking()
            or output_gate.is_busy()
            or echo_cancel.is_suppressed()
            or _interrupted.is_set()
        ):
            return
        # Defer to a more useful proactive beat (e.g. an idle-banter question that
        # asks about the user) — don't stack the snarky quip on top of it so the
        # user gets one re-engagement and then real silence to answer into.
        if _proactive_line_recently_fired():
            return

        quips = getattr(config, "CONVERSATION_NO_RESPONSE_QUIPS", None) or [
            "Guess that question landed in the cargo bay."
        ]
        quip = random.choice(list(quips))
        _log.info("[interaction] no-response recovery quip after question=%r", question_text)
        completed = _speak_proactive(
            quip, emotion="neutral", priority=1, label="no_response_recovery"
        )
        if completed:
            # Only treat the question as unanswered once the quip actually plays.
            # If it was aborted because the user just started answering, leave the
            # pending question open so their reply still matches it.
            try:
                if person_id is not None:
                    rel_memory.decline_latest_pending_question(
                        person_id,
                        reason="no response after Rex question",
                    )
            except Exception as exc:
                _log.debug("no-response pending question close failed: %s", exc)
            conv_memory.add_to_transcript("Rex", quip)
            conv_log.log_rex(quip)
            _register_rex_utterance(quip)

    threading.Thread(
        target=_timer,
        daemon=True,
        name="question-no-response-recovery",
    ).start()


def _note_rex_question(text: str) -> None:
    """Record a question Rex asked so idle banter doesn't re-ask it later."""
    if "?" not in (text or ""):
        return
    toks = _topic_ban_tokens(text)
    if not toks:
        return
    _recent_rex_questions.append({"tokens": toks, "at": time.monotonic()})
    # Keep it bounded.
    if len(_recent_rex_questions) > 24:
        del _recent_rex_questions[:-24]


def _line_duplicates_recent_question(line: str) -> bool:
    """True when a proposed proactive question substantially re-asks a question
    Rex already asked within IDLE_BANTER_RECENT_QUESTION_DEDUP_SECS."""
    if "?" not in (line or ""):
        return False
    toks = _topic_ban_tokens(line)
    if not toks:
        return False
    window = float(getattr(config, "IDLE_BANTER_RECENT_QUESTION_DEDUP_SECS", 120.0) or 0.0)
    if window <= 0.0:
        return False
    now = time.monotonic()
    for q in _recent_rex_questions:
        if (now - q.get("at", 0.0)) > window:
            continue
        prior = q.get("tokens") or set()
        if not prior:
            continue
        overlap = toks & prior
        # A near-duplicate re-ask: two+ shared content words, OR (for questions
        # with at least 3 content words each) the shared words cover at least half
        # the smaller set. The min-length-3 guard stops a single incidental shared
        # word between two 2-token questions ("favorite movie" vs "favorite food")
        # from false-flagging.
        if not overlap:
            continue
        if len(overlap) >= 2:
            return True
        if min(len(toks), len(prior)) >= 3 and 2 * len(overlap) >= min(len(toks), len(prior)):
            return True
    return False


def _note_day_mood(kind: str) -> None:
    """Nudge Rex's mood for the day (intelligence/rex_mood.py). Best-effort — a mood
    that fails to shift must never cost a turn. See config.REX_MOOD_DRIFT for the
    per-event deltas; unknown kinds are no-ops."""
    try:
        from intelligence import rex_mood
        rex_mood.note(kind)
    except Exception as exc:
        _log.debug("[interaction] day-mood note %r skipped: %s", kind, exc)


def _register_rex_utterance(
    text: str,
    wait_secs: Optional[float] = None,
    *,
    source: Optional[str] = None,
    topic: Optional[str] = None,
    target_person_id: Optional[int] = None,
    target_name: Optional[str] = None,
    expected_reply_types: Optional[list[str]] = None,
    blocked_actions: Optional[list[str]] = None,
) -> None:
    global _floor_held_until, _last_rex_line_was_question
    if not text or not text.strip():
        return
    try:
        _note_rex_question(text)
        # Track whether this line handed the user a clear turn — a question or an
        # imperative prompt ("tell me about it"). A closed quip did not, so the
        # adaptive re-engage wait shortens (the conversation stalled on Rex).
        _last_rex_line_was_question = _assistant_asked_question(text)
        # When Rex's line asks a question, hard-hold the floor so idle filler
        # doesn't pile a fresh prompt on top before the user can answer — even
        # when the text has no literal '?'-punctuated proactive arming. Fixes the
        # duplicate camping question that re-asked ~39s later.
        if "?" in text:
            hold = float(getattr(config, "POST_REPLY_QUESTION_WAIT_SECS", 18.0) or 0.0)
            if hold > 0.0:
                _floor_held_until = max(_floor_held_until, time.monotonic() + hold)
    except Exception:
        pass
    try:
        repair_moves.note_assistant_turn(text)
    except Exception:
        pass
    try:
        comedy_modes.note_spoken_line(text)
    except Exception:
        pass
    try:
        premise_memory.note_line(text)
    except Exception:
        pass
    try:
        # If this line voiced Rex's current preoccupation, arm the POV spoken-cooldown
        # so the next reply doesn't re-inject the "volunteer it" directive (the
        # near-verbatim repeat). Covers ALL reply paths — the only prior caller was the
        # dead idle-banter branch, so the guard never armed.
        rex_pov.note_pov_spoken_if_voiced(text)
    except Exception:
        pass
    try:
        # If this line VOICED today's mood, lock its framing — the background enrich
        # pass must not go back and attach a different reason to a mood he has already
        # explained out loud. Persist on a match (once/day at most) so a crash before
        # session end doesn't lose the spend and re-arm the unprompted share.
        from intelligence import rex_mood
        if rex_mood.note_spoken_if_voiced(text):
            rex_mood.persist()
    except Exception:
        pass
    try:
        # One-shot spend of the "they smiled at my last line" awareness: this line's
        # prompt had its beat to use it (or not) — either way the moment has passed.
        from intelligence import reaction_awareness
        reaction_awareness.note_rex_spoke()
    except Exception:
        pass
    try:
        # Same idea for the wellbeing ritual: if this line asked them how they are,
        # spend it so he doesn't ask again in twenty minutes. Only ~7 of the ~25
        # callers pass target_person_id, so fall back to whoever he's engaged with.
        from intelligence import greeting_cadence
        _ask_target = target_person_id
        if _ask_target is None:
            _engaged = consciousness.get_recent_engagement()
            _ask_target = (_engaged or {}).get("person_id")
        greeting_cadence.note_wellbeing_ask(_ask_target, text)
    except Exception:
        pass
    try:
        end_thread.note_assistant_turn(text)
    except Exception:
        pass
    try:
        topic_thread.note_assistant_turn(text)
    except Exception:
        pass
    try:
        consciousness.note_rex_utterance(
            text,
            wait_secs=wait_secs,
            source=source,
            topic=topic,
            target_person_id=target_person_id,
            target_name=target_name,
            expected_reply_types=expected_reply_types,
            blocked_actions=blocked_actions,
        )
    except Exception:
        pass


def _primary_session_person_id() -> Optional[int]:
    if len(_session_person_ids) == 1:
        return next(iter(_session_person_ids))
    try:
        people = world_state.get("people", []) or []
    except Exception:
        people = []
    known_visible = [
        p.get("person_db_id")
        for p in people
        if p.get("person_db_id") is not None
    ]
    unique = {int(pid) for pid in known_visible if pid is not None}
    if len(unique) == 1:
        return next(iter(unique))
    return None


def _profile_fact_count(person_id: int) -> int:
    return profile_questions.profile_fact_count(person_id)


def _next_profile_question(person_id: int) -> Optional[dict]:
    return profile_questions.next_profile_question(person_id)


def _format_low_memory_question(person_id: int, question_text: str) -> str:
    text = (question_text or "").strip()
    if not text:
        return ""
    try:
        person = people_memory.get_person(person_id) or {}
    except Exception:
        person = {}
    full_name = str(person.get("name") or "").strip()
    first_name = _first_name_or(full_name, "there")
    template = str(
        getattr(
            config,
            "LOW_MEMORY_IDLE_QUESTION_PREFIX",
            "I don't know you well yet, {name}, {question}",
        )
        or "{question}"
    )
    try:
        formatted = template.format(name=first_name, question=text)
    except Exception:
        formatted = f"I don't know you well yet, {first_name}, {text}"
    return llm.clean_response_text(formatted)


def _maybe_interest_idle_followup(
    *,
    idle_for: float,
    effective_idle_timeout: float,
) -> bool:
    """Give one topic-aware nudge before an active interest thread goes idle."""
    global _session_exchange_count
    if _game_suppresses_conversation():
        return False
    if _directed_context_fresh():
        return False
    if not bool(getattr(config, "INTEREST_IDLE_FOLLOWUP_ENABLED", True)):
        return False
    threshold = float(getattr(config, "INTEREST_IDLE_FOLLOWUP_SECS", 12.0) or 0.0)
    if threshold <= 0 or idle_for < threshold:
        return False
    # Leave at least a little room between the nudge and the hard idle cutoff.
    if idle_for >= max(0.0, effective_idle_timeout - 1.0):
        return False
    if speech_queue.is_speaking() or output_gate.is_busy() or echo_cancel.is_suppressed():
        return False
    if _interrupted.is_set():
        return False
    try:
        if end_thread.is_grace_active():
            return False
    except Exception:
        pass

    person_id = _primary_session_person_id()
    if person_id is None:
        return False
    try:
        steering = conversation_steering.build_context(person_id)
    except Exception as exc:
        _log.debug("interest idle follow-up steering context failed: %s", exc)
        return False
    if not steering:
        return False

    key = (person_id, steering.fact_key)
    if key in _interest_idle_followups_spoken:
        return False

    allow_question = True
    try:
        allow_question = question_budget.can_ask("interest_idle_followup")
    except Exception:
        allow_question = True

    max_words = int(getattr(config, "INTEREST_IDLE_FOLLOWUP_MAX_WORDS", 22) or 22)
    question_rule = (
        "Ask one simple, low-pressure question that deepens this topic."
        if allow_question else
        "Do not ask a question; offer one specific opinion or curious observation."
    )
    try:
        line = llm.get_response(
            "Generate ONE short DJ-R3X line to re-engage a person after a quiet "
            f"pause. Active interest: {steering.topic!r}. {question_rule} "
            "Sound genuinely interested in what they told Rex they like. "
            "Use one sentence only. Do not add a second sentence, self-reference, "
            "flight jokes, roasts, or 'I bet...' riffs. "
            "Do not mention the silence, the camera, the room, or the idle timer. "
            f"Maximum {max_words} words. Return only the line.",
            person_id,
        )
    except Exception as exc:
        _log.debug("interest idle follow-up LLM failed: %s", exc)
        return False

    line = llm.clean_response_text(line or "")
    if not line:
        return False
    frame = social_frame.build_frame(
        f"I like {steering.topic}",
        person_id,
        agenda_directive=(
            steering.directive
            + " Primary purpose: after a quiet pause, keep the active interest "
            "thread alive with one compact, topic-aware follow-up."
        ),
    )
    if not allow_question:
        frame.allow_question = False
    frame.max_words = min(frame.max_words, max_words)
    frame.max_sentences = 2 if frame.allow_question else 1
    governed = social_frame.govern_response(line, frame)
    line = governed.text
    if not line:
        return False

    _log.info(
        "[interaction] interest idle follow-up — person_id=%s topic=%r text=%r",
        person_id,
        steering.topic,
        line,
    )
    completed = _speak_proactive(
        line, emotion="curious", priority=1, label="interest_idle_followup"
    )
    if completed:
        _interest_idle_followups_spoken.add(key)
        conv_memory.add_to_transcript("Rex", line)
        conv_log.log_rex(line)
        _register_rex_utterance(line)
        _session_exchange_count += 1
        if "?" in line:
            try:
                rel_memory.save_question_asked(
                    person_id,
                    f"{steering.fact_key}_idle_followup",
                    line,
                    1,
                )
            except Exception as exc:
                _log.debug("interest idle follow-up save_qa failed: %s", exc)
    return completed


def _maybe_low_memory_idle_question(
    *,
    idle_for: float,
    effective_idle_timeout: float,
) -> bool:
    """Ask one profile-building question during a lull for known sparse profiles."""
    if _game_suppresses_conversation():
        return False
    if _directed_context_fresh():
        return False
    if not bool(getattr(config, "LOW_MEMORY_IDLE_QUESTION_ENABLED", True)):
        return False
    threshold = float(getattr(config, "LOW_MEMORY_IDLE_QUESTION_SECS", 10.0) or 0.0)
    if threshold <= 0 or idle_for < threshold:
        return False
    if idle_for >= max(0.0, effective_idle_timeout - 1.0):
        return False
    if speech_queue.is_speaking() or output_gate.is_busy() or echo_cancel.is_suppressed():
        return False
    if _interrupted.is_set():
        return False
    try:
        if end_thread.is_grace_active():
            return False
    except Exception:
        pass

    person_id = _primary_session_person_id()
    if person_id is None or person_id in _low_memory_idle_questions_spoken:
        return False
    # Never run the generic "I want to get to know you better" profile question on the
    # creator or a known VIP — Rex knows them on sight, so it reads as treating a
    # well-known person like a stranger (live-logged 2026-06-20: it fired on the creator
    # right after reminiscing about his festival, and kicked off an interview). Mirrors
    # onboarding.py's VIP exclusion (person_specials.is_special_person).
    try:
        _person_row = people_memory.get_person(person_id) or {}
        _person_name = _person_row.get("name")
        if _person_name and person_specials.is_special_person(_person_name):
            return False
    except Exception:
        pass
    # Don't cold-open a get-to-know-you interview on a disengaged / quiet speaker
    # (Tier 2 — a shy person giving one-word answers). The child case is handled by
    # _next_profile_question() returning None, but back off on low energy too.
    try:
        _energy = user_energy.snapshot() or {}
        if (
            str(_energy.get("engagement") or "").lower() == "low"
            or str(_energy.get("mode") or "").lower() == "quiet"
            or str(_energy.get("question_appetite") or "").lower() == "low"
        ):
            return False
    except Exception:
        pass
    max_facts = int(getattr(config, "LOW_MEMORY_PROFILE_MAX_FACTS", 4) or 4)
    if _profile_fact_count(person_id) > max_facts:
        return False
    try:
        if not question_budget.can_ask("low_memory_idle_question"):
            return False
    except Exception:
        pass

    # STARVATION RULE (curiosity Phase 1, owner direction 2026-07-17): a pending
    # ROOM question — a genuinely-new object Rex hasn't asked about — outranks
    # the personal profile pool. When the room is stale this returns None and
    # personal curiosity resumes. Shares the same budget/pacing gates above.
    try:
        from intelligence import room_questions
        room_q = room_questions.next_room_question()
    except Exception:
        room_q = None
    if room_q:
        if _proactive_line_recently_fired():
            return False
        _log.info("[interaction] room curiosity question — label=%r text=%r",
                  room_q["label"], room_q["text"])
        completed = _speak_proactive(
            room_q["text"], emotion="curious", priority=1, label="room_question"
        )
        if completed:
            room_questions.note_asked(room_q["label"])
            conv_memory.add_to_transcript("Rex", room_q["text"])
            conv_log.log_rex(room_q["text"])
            _register_rex_utterance(room_q["text"])
        return completed

    question = _next_profile_question(person_id)
    if not question:
        return False
    question_text = str(question.get("text") or "").strip()
    if not question_text:
        return False
    spoken_text = _format_low_memory_question(person_id, question_text)
    if not spoken_text:
        return False

    # One proactive line at a time — don't ask a profile question right on top of
    # another proactive line (idle banter / interest follow-up) that just fired.
    if _proactive_line_recently_fired():
        return False

    _log.info(
        "[interaction] low-memory idle profile question — person_id=%s fact_count=%d key=%r text=%r",
        person_id,
        _profile_fact_count(person_id),
        question.get("key"),
        spoken_text,
    )
    completed = _speak_proactive(
        spoken_text, emotion="curious", priority=1, label="low_memory_idle_question"
    )
    if completed:
        _low_memory_idle_questions_spoken.add(person_id)
        conv_memory.add_to_transcript("Rex", spoken_text)
        conv_log.log_rex(spoken_text)
        _register_rex_utterance(spoken_text)
        try:
            rel_memory.save_question_asked(
                person_id,
                question["key"],
                spoken_text,
                question.get("depth", 1),
            )
        except Exception as exc:
            _log.debug("low-memory idle question save_qa failed: %s", exc)
    return completed


_IDLE_BANTER_DIRECTIVES = (
    # Even attempts: turn the spotlight on the user.
    "The conversation just went quiet — the user didn't say goodbye, they simply "
    "stopped talking. DRIVE it forward, in character: ask ONE short, specific "
    "question rooted in what you actually KNOW about them. If their 'Interest profile' "
    "above names a hobby or interest, LEAD WITH THAT — a real, curious follow-up ('still "
    "wrangling those time-of-flight sensors?', 'how's the astrophotography coming?'), never "
    "a generic 'what are you up to?'. Otherwise riff a question off their work, their dog, "
    "or something you can see. Light and inviting, one or two sentences. Do not sign off "
    "and do not announce the silence.",
    # Odd attempts: Rex volunteers a take — but ON the live topic, not a generic bit.
    "Still quiet, but you two were mid-conversation. Stay ON the subject you were just "
    "discussing (see 'Session so far' and the conversation arc above) and VOLUNTEER a "
    "specific opinion, hot take, reaction, or observation about THAT — a real angle "
    "they'll want to push back on or laugh at. Do NOT change the subject to a generic "
    "music/DJ/silence/dead-air bit or an unrelated 'thing on your mind'; react to what "
    "was actually being said. Do NOT ask a question this time, and do not sign off or "
    "announce the silence.",
)

# ask_user slot, but the user already opened a real topic this session. Do NOT fall
# back to the generic "what are you up to?" interview — that re-asks what they just
# told you and reads as Rex not listening. Field log 2026-06-16: the user said "I'm
# working on your time-of-flight sensors" and ~50s later idle banter asked "What's the
# latest project you're diving into?" → "I just told you." Deepen the SAME thread with
# a genuinely new follow-up, or stay a volunteer.
_IDLE_BANTER_LIVE_TOPIC_ASK = (
    "Still quiet, but you two were mid-conversation. STAY ON the exact thing you were "
    "just discussing (see 'Session so far' and the conversation arc above). If you have "
    "a genuinely NEW, specific follow-up question that builds on what they just told "
    "you, ask that ONE question. NEVER re-ask something they already answered — do NOT "
    "ask what they're working on, what they're up to, or what their latest project is; "
    "they just told you, and asking again breaks the conversation. If you don't have a "
    "real new question, EITHER volunteer a short, specific take on that same topic, OR — if "
    "that exact thread is genuinely spent — PIVOT to something else you know they're into "
    "(their 'Interest profile' above: a hobby, a project, an upcoming plan) and ask a real "
    "follow-up about that. Do not sign off or announce the silence."
)

# A LATER idle attempt, after an earnest re-engagement has already gone unanswered: the ONE
# mode allowed to call out the dead air — but only the way you'd needle a friend you're fond
# of. Selected when tease=True (idle_count >= IDLE_BANTER_TEASE_SILENCE_AT); the tuple gives the
# model varied seeds, and the opener-diversity guard stops two teases stacking the same opener.
_IDLE_BANTER_TEASE_SILENCE = (
    "They've gone properly quiet on you — no goodbye, just dead air. THIS time you ARE allowed "
    "to call out the silence, but do it the way you'd needle a friend you're fond of: ONE short, "
    "warm, teasing jab that pokes at the quiet and dares them back in ('cat got your tongue?', "
    "'are you trying to stump me, or just gone full mute?', 'I can hear you thinking — out loud, "
    "coward'). The ribbing obviously comes from affection and it MUST invite a reply — never sad, "
    "never a sign-off, never 'I'll be here'. One line, ~8-14 words; land it like a grin.",
    "Still nothing — the silence is getting comically long. Break it IN CHARACTER by gently "
    "roasting the quiet itself: a fond, teasing dare that makes them want to fire back ('you do "
    "remember how talking works, right?', 'this dramatic pause is doing real numbers'). Warm under "
    "the snark, an obvious invitation to re-engage, never a goodbye, never melancholy. One short line.",
)


def _idle_plans_already_asked_holiday(person_id: Optional[int], holiday: dict) -> bool:
    """True if this holiday was already raised this session — by the idle pivot OR the
    consciousness holiday-plans step (shared dedup so the two paths don't double-ask)."""
    if holiday.get("name") in _idle_plans_asked:
        return True
    if person_id is None:
        return False
    date = holiday.get("date", "")
    # Persistent cross-run dedupe: don't re-raise a holiday already asked in a PRIOR run.
    try:
        from memory import relationships as rel_memory
        if date and rel_memory.was_proactive_asked(int(person_id), f"holiday_plans:{date}"):
            return True
    except Exception:
        pass
    try:
        from intelligence import consciousness as _c
        return (int(person_id), date) in _c._holiday_plans_asked
    except Exception:
        return False


def _mark_idle_plans_asked(marker: Optional[dict]) -> None:
    """Record (on actual speak) that a plans/holiday question was asked, so it isn't
    repeated. Records into the consciousness holiday set too for cross-path dedup."""
    if not marker:
        return
    name = marker.get("holiday_name")
    if name:
        _idle_plans_asked.add(name)
        person_id = marker.get("person_id")
        date = marker.get("holiday_date")
        if person_id is not None and date:
            try:
                from intelligence import consciousness as _c
                _c._holiday_plans_asked.add((int(person_id), date))
            except Exception:
                pass
            # Persist so the holiday isn't re-asked in a future run.
            try:
                from memory import relationships as rel_memory
                rel_memory.mark_proactive_asked(int(person_id), f"holiday_plans:{date}")
            except Exception:
                pass
    elif marker.get("generic"):
        _idle_plans_asked.add("generic")


def _idle_plans_directive(person_id: Optional[int] = None) -> tuple[str, Optional[dict]]:
    """An idle re-engagement that pivots OFF the current topic to ask about the user's
    upcoming plans — an approaching holiday if one is in window and NOT already raised
    this session, otherwise the weekend / what they've got coming up (also once-only).

    Returns (directive, marker). The marker is recorded by the caller ONLY when the line
    actually speaks (_mark_idle_plans_asked), so a candidate that loses the governor tick
    doesn't burn the topic. Returns ("", None) when there's nothing fresh to ask — the
    caller then keeps the normal topic-deepening directive instead of repeating itself."""
    holiday = None
    try:
        from awareness import holidays as _holidays
        holiday = _holidays.next_relevant_holiday()
    except Exception:
        holiday = None
    if holiday and not _idle_plans_already_asked_holiday(person_id, holiday):
        directive = (
            f"The conversation has gone quiet. {holiday['name']} is coming up "
            f"({holiday['when']}). Ask, in ONE short curious in-character line, whether "
            "they've got any plans for it. Don't lecture about the holiday — just ask. "
            "Do not sign off or announce the silence."
        )
        return directive, {
            "holiday_name": holiday.get("name"),
            "holiday_date": holiday.get("date"),
            "person_id": person_id,
        }
    if "generic" in _idle_plans_asked:
        # Already asked about upcoming plans this session — don't loop it; let idle
        # banter go back to deepening the live topic instead.
        return "", None
    directive = (
        "The conversation has gone quiet. Pivot off the current topic and ask, in ONE "
        "short curious in-character line, what they've got coming up — plans this weekend, "
        "a trip, anything they're looking forward to. Do not sign off or announce the silence."
    )
    return directive, {"generic": True}


def _governor_enforcing() -> bool:
    """True when the action governor is the single decider for proactive speech
    (ACTION_GOVERNOR_ENFORCE). Interaction-thread proactive paths then SUBMIT a
    candidate (governor.submit_external) instead of speaking inline."""
    try:
        from intelligence.action_governor import governor
        return bool(governor.enforcing)
    except Exception:
        return False


def _idle_has_live_topic() -> bool:
    """True when the USER has actually contributed something to riff on — so an idle
    re-engagement deepens that thread. Requires a real USER turn, NOT just Rex talking:
    a present-but-silent person Rex only greeted has no live topic, so re-engaging them
    should ask a getting-to-know-you question, not 'follow up' on a thread they never
    started."""
    try:
        entries = [
            t for t in conv_memory.get_session_transcript()
            if (t.get("text") or "").strip()
        ]
        if len(entries) < 2:
            return False
        return any(
            str(t.get("speaker") or "").strip().lower() not in ("rex", "dj-r3x", "dj rex")
            for t in entries
        )
    except Exception:
        return False


def _last_user_turn_text() -> str:
    """The most recent USER (non-Rex) transcript line's text, or '' — used to tell
    whether the thing an idle nudge would 'riff on' is actually a content-free answer."""
    try:
        for t in reversed(conv_memory.get_session_transcript() or []):
            if str(t.get("speaker") or "").strip().lower() in ("rex", "dj-r3x", "dj rex"):
                continue
            text = (t.get("text") or "").strip()
            if text:
                return text
    except Exception:
        pass
    return ""


def _last_user_turn_was_low_content() -> bool:
    """True when the user's last real turn was a curt, content-free answer ('not much',
    'nothing', 'Hello') — a legitimate reply Rex should let breathe, NOT keep mining as a
    topic. Gated on word count (IDLE_BANTER_LOW_CONTENT_MAX_WORDS)."""
    text = _last_user_turn_text()
    if not text:
        return False
    return _word_count(text) <= int(getattr(config, "IDLE_BANTER_LOW_CONTENT_MAX_WORDS", 3))


def _idle_should_volunteer_take(idle_count: int, has_live_topic: bool) -> bool:
    """Volunteer an ON-topic take instead of asking yet another question.

    Only once the room is TRULY dead — the first re-engagement question already went
    unanswered (idle_count >= 1) — and only when there's a live thread to react to, so the
    take stays on the subject they were discussing (idle directive [1]: a real angle to
    push back on or laugh at), never the off-topic 'thing on my mind' preoccupation. The
    first nudge still draws the user out with a question. Kill switch: IDLE_BANTER_VOLUNTEER_TAKE.
    """
    if not bool(getattr(config, "IDLE_BANTER_VOLUNTEER_TAKE", True)):
        return False
    return bool(has_live_topic) and idle_count >= 1


def _idle_banter_directive(
    ask_user: bool, has_live_topic: bool, pov_text: str, tease: bool = False
) -> tuple[str, bool]:
    """Choose the idle-banter directive and whether Rex's preoccupation was volunteered.

    - ask_user → turn the spotlight on the user (a question). But once the user has
      opened a real topic this session (has_live_topic), the question must DEEPEN that
      thread, never reset to a generic "what are you up to?" interview — that re-asks
      what they just said.
    - otherwise VOLUNTEER a take, but ON the live topic — the assembled prompt already
      carries the recent transcript + arc, so the model can react to what was actually
      said. Rex's own preoccupation (rex_pov) is a deliberately OFF-topic "thing on his
      mind"; mid-conversation it reads as a non-sequitur ("ranking organic snacks" while
      the user talks camping), so it's used ONLY as a cold-open fallback when there's no
      real exchange yet. The POV still surfaces in the reply path regardless.
    """
    # Later in a silent stretch the earnest re-engagement(s) went unanswered → escalate to a
    # playful tease of the dead air. The only directive permitted to announce the silence.
    if tease:
        return random.choice(_IDLE_BANTER_TEASE_SILENCE), False
    if ask_user:
        if has_live_topic:
            return _IDLE_BANTER_LIVE_TOPIC_ASK, False
        return _IDLE_BANTER_DIRECTIVES[0], False
    if not has_live_topic and pov_text:
        return (
            "It's quiet and nothing's really been said yet. Keep the room alive by "
            "VOLUNTEERING what's on your mind right now — " + pov_text + " Say it like a "
            "passing thought you want them to react to. Do NOT ask a question this time, "
            "and do not sign off or announce the silence."
        ), True
    return _IDLE_BANTER_DIRECTIVES[1], False


def _lean_visual_riff_cue(person_id: Optional[int], world: Optional[dict]) -> Optional[dict]:
    """Return one safe visual-riff cue for Lean, or ``None``.

    This deliberately does not revive ``appearance_riff`` / ``people_roast`` as
    independent timer behaviors. It gives the already-paced Lean impulse a
    grounded option only when the present person is known to be an adult and has
    not asked Rex to avoid appearance, clothing, or roasting comments.
    """
    if person_id is None or not bool(getattr(config, "LEAN_VISUAL_RIFF_ENABLED", True)):
        return None
    if random.random() >= float(getattr(config, "LEAN_VISUAL_RIFF_PROBABILITY", 0.25)):
        return None

    target = None
    for person in (world or {}).get("people", []) or []:
        if not isinstance(person, dict):
            continue
        try:
            if int(person.get("person_db_id")) == int(person_id):
                target = person
                break
        except (TypeError, ValueError):
            continue
    if target is None:
        return None                         # only comment on someone actually present

    # Fail closed unless enrollment/profile data says adult. A known name alone
    # is not enough license for unprompted physical commentary.
    age_values = [target.get("age_category"), target.get("age_estimate")]
    try:
        profile = people_memory.get_person(int(person_id)) or {}
        age_values.extend([profile.get("age_category"), profile.get("age_estimate")])
        age_values.extend(
            fact.get("value") for fact in facts_memory.get_facts(int(person_id))
            if str(fact.get("key") or "").strip().lower() == "age_category"
        )
    except Exception:
        return None
    normalized_ages = {str(value or "").strip().lower() for value in age_values}
    if normalized_ages & {"child", "teen", "minor"}:
        return None
    adult_values = {"young_adult", "adult", "middle_aged", "senior"}
    if not normalized_ages & adult_values:
        return None

    try:
        blocked_topics = ("anything", "appearance", "clothing", "body", "identity")
        if any(
            boundary_memory.is_blocked(int(person_id), behavior, topic)
            for behavior in ("mention", "roast")
            for topic in blocked_topics
        ):
            return None
    except Exception:
        return None

    # Familiar visual facts are intentionally narrow (the shared helper excludes
    # build/height/age). If none are available, a present non-sensitive posture
    # still permits a people-roast style line grounded in this exact moment.
    hint = consciousness._pick_appearance_hint(int(person_id))
    if hint:
        return {"cue": f"a familiar visual detail: {hint}"}
    cues = []
    for key, label in (
        ("distance_zone", "distance"),
        ("approach_vector", "movement"),
        ("pose", "pose"),
        ("gesture", "gesture"),
        ("engagement", "engagement"),
        ("position", "position"),
    ):
        value = str(target.get(key) or "").strip()
        if value and value.lower() != "neutral":
            cues.append(f"{label}={value}")
    if cues:
        return {"cue": "current non-sensitive vibe: " + ", ".join(cues[:3])}
    return None


def _lean_callback_lull_cue(
    person_id: Optional[int], transcript: list[dict], *, long_silence: bool
) -> Optional[dict]:
    """Offer one already-vetted callback premise to Lean's single lull speaker.

    The callback engine retains ownership of consent, sensitivity, relationship,
    crowd, cooldown, and per-session limits. This seam adds only conversational
    timing: callbacks need an actual exchange earlier in this session and belong
    in a natural short lull, not a 40-second re-engagement from cold silence.
    """
    if person_id is None or long_silence:
        return None
    human_turns = sum(
        1 for turn in (transcript or [])
        if str(turn.get("speaker") or "").strip().lower()
        not in {"rex", "dj-r3x", "dj rex", "djr3x", "r3x", "dj r3x"}
        and str(turn.get("text") or "").strip()
    )
    if human_turns < 2:
        return None
    try:
        from intelligence import callback_engine
        if not callback_engine.lull_gates_clear(int(person_id)):
            return None
        return callback_engine.pick_lull_premise(int(person_id))
    except Exception as exc:
        _log.debug("[lean] callback lull cue unavailable: %s", exc)
        return None


def _current_crowd_count() -> int:
    """Best-effort count of people (known AND unknown bodies) currently in view, for the
    celebration crowd-discretion guard. Defaults to 1 (just the engaged person) when the
    count is unknown, matching the legacy emotional-check-in snapshot semantics."""
    try:
        crowd = world_state.get("crowd") or {}
        count = crowd.get("count")
        if count is not None:
            return int(count or 0)
        people = world_state.get("people") or []
        return len(people) or 1
    except Exception:
        return 1


def _lean_celebration_cue(person_id: Optional[int]) -> Optional[dict]:
    """Offer ONE remembered piece of good news to Lean's single lull speaker, or ``None``.

    The old proactive celebration check-in ("that promotion — how's it going?") rode the
    suppressed ``celebration_checkin`` purpose and went dark under the lean brain, while the
    HARD-event / negative-affect check-ins (``emotional_checkin``, NOT suppressed) kept
    firing — so Rex would console bad news but silently drop good news. This revives the
    positive branch as the TOP lull cue.

    Faithful to the legacy ``_step_emotional_checkin`` Trigger A2 (same master switches;
    sourced from ``emotional_events.get_due_celebrations`` — valence>0, unmuted, not decayed,
    not acknowledged within the ack-gap), with two guards:

      * CROWD DISCRETION — good news can be private (a pregnancy, an engagement). Mirror the
        bad-news console path, which stays silent in a group (``EMPATHY_DISCRETION_IN_CROWD``):
        don't announce someone's personal milestone in front of others who may not know.
        (Legacy Trigger A2 lacked this; A2's exposure was masked only because the whole
        purpose was suppressed under lean — reviving it here without the guard would make good
        news LESS discreet than bad news.)
      * DIRECTIONAL session gate — skip when a console already fired this session
        (``consciousness._emotional_checkin_fired``), so a celebration never piles on right
        after a console. A celebration does NOT set that gate, so a later console about a
        DIFFERENT event can still follow it (matching the legacy path).

    Per-event de-dup is the ``mark_acknowledged`` write done on speak (not here); the
    ``_celebration_unvoiced_attempts`` cap keeps a persistently-unvoiced celebration from
    starving the lower cues. Fail-safe to ``None`` so a missing DB never breaks the impulse.
    """
    if person_id is None or not bool(getattr(config, "LEAN_CELEBRATION_CHECKIN_ENABLED", True)):
        return None
    if not bool(getattr(config, "EMPATHY_ENABLED", True)):
        return None
    if not bool(getattr(config, "EMPATHY_PROACTIVE_CHECKIN_ENABLED", True)):
        return None
    # Crowd discretion: don't reveal private good news in front of others.
    if bool(getattr(config, "EMPATHY_DISCRETION_IN_CROWD", True)) and _current_crowd_count() > 1:
        return None
    # Don't stack a celebration on top of a console: mirrors the legacy step's early return
    # on the shared once-per-session emotional-check-in gate.
    try:
        if int(person_id) in consciousness._emotional_checkin_fired:
            return None
    except Exception:
        pass
    try:
        celebrations = emotional_events.get_due_celebrations(int(person_id), limit=2) or []
    except Exception as exc:
        _log.debug("[lean] celebration cue lookup failed: %s", exc)
        return None
    attempt_cap = int(getattr(config, "LEAN_CELEBRATION_MAX_UNVOICED_ATTEMPTS", 2) or 0)
    for ev in celebrations:
        try:
            eid = int(ev.get("id"))
        except (TypeError, ValueError):
            continue
        # Model kept declining to voice this one this stretch → step aside for lower cues.
        if attempt_cap and _celebration_unvoiced_attempts.get(eid, 0) >= attempt_cap:
            continue
        desc = str(ev.get("description") or "").strip()
        if not desc:
            continue
        person_name = None
        first_name = ""
        try:
            person = people_memory.get_person(int(person_id)) or {}
            person_name = str(person.get("name") or "").strip() or None
            first_name = _first_name_or(person_name or "", "them")
        except Exception:
            pass
        return {
            "event_id": eid,
            "description": desc,
            "category": str(ev.get("category") or "").strip(),
            "person_name": person_name,
            "first_name": first_name,
        }
    return None


def _lean_memory_musing_cue(person_id: Optional[int]) -> Optional[dict]:
    """Offer ONE rex.db diary recap to Lean's lull speaker as an occasional 'since I was last
    on' musing, or ``None``.

    The old idle `do_memory_musing` behavior (purpose `memory_musing`) went dark under the lean
    brain — its governor candidate is suppressed and the lean impulse never consulted the diary.
    This revives it as the LOWEST-priority lull cue (only reached when no celebration / holiday /
    event / callback / visual-riff fires), so a low-stakes nostalgia beat never crowds out the
    higher-value cues. Source is the same person-agnostic `episodic_recall.session_recap` the
    legacy path used (a scene vibe + a couple of experiential highlights, sensitive kinds
    excluded). Capped at one musing per session (`_lean_memory_mused_this_session`) because the
    recap content is stable within a session; probability-gated like the legacy beat. Fail-safe
    to ``None`` so a missing/empty diary never breaks the impulse.
    """
    if person_id is None or not bool(getattr(config, "LEAN_MEMORY_MUSING_ENABLED", True)):
        return None
    if not bool(getattr(config, "EPISODIC_RECALL_ENABLED", False)):
        return None
    if _lean_memory_mused_this_session:
        return None
    if random.random() >= float(getattr(config, "EPISODIC_RECALL_SESSION_RECAP_PROBABILITY", 0.5) or 0.0):
        return None
    try:
        from memory import episodic_recall
        recap = episodic_recall.session_recap()
    except Exception as exc:
        _log.debug("[lean] memory-musing cue lookup failed: %s", exc)
        return None
    recap = str(recap or "").strip()
    if not recap:
        return None
    return {"recap": recap}


def _lean_mood_share_cue(person_id: Optional[int]) -> Optional[dict]:
    """Offer Rex's OWN day mood to the lull speaker as an unprompted aside, or ``None``.

    Owner 2026-08-05: a droid who only reveals his state under interrogation reads as
    a lookup table — real people mention their day unasked. This is the volunteering
    half of intelligence/rex_mood.py.

    Pacing and social fit live HERE (rex_mood.share_cue owns only "is there something
    worth saying"), matching how every other lull cue splits the work:

      * a random roll, so it is never a scheduled broadcast,
      * FRIEND tier or better — you don't unload your day on an acquaintance,
      * once per session (`_lean_mood_shared_this_session`), and beneath that the
        persisted per-DAY `spoken` flag inside rex_mood, so answering "how are you?"
        this morning also spends the unprompted share for the rest of the day.

    Fail-safe to ``None``: a missing mood must never break the impulse.
    """
    if person_id is None or not bool(getattr(config, "REX_MOOD_SHARE_ENABLED", True)):
        return None
    if _lean_mood_shared_this_session:
        return None
    # Honor the drop-bench: if a generated share was dropped (near-duplicate, banned
    # topic), don't re-offer the same cue for the cooldown — _strike_lean_cue records
    # the bench, but it only works if the builder actually consults it.
    if _lean_cue_blocked("mood_share"):
        return None
    if random.random() >= float(getattr(config, "REX_MOOD_SHARE_PROBABILITY", 0.3) or 0.0):
        return None
    # Relationship gate BEFORE the mood lookup — cheaper, and it's the harder rule.
    try:
        tiers = tuple(getattr(config, "REX_MOOD_SHARE_MIN_TIERS", None)
                      or ("friend", "close_friend", "best_friend"))
        row = people_memory.get_person(int(person_id)) or {}
        tier = str(row.get("friendship_tier") or "").strip().lower()
        if tier not in {str(t).strip().lower() for t in tiers}:
            # Rex's creator counts regardless of the computed tier.
            name = str(row.get("name") or "")
            if not (name and person_specials.is_rex_creator(name)):
                return None
    except Exception as exc:
        _log.debug("[lean] mood-share tier check failed: %s", exc)
        return None
    try:
        from intelligence import rex_mood
        return rex_mood.share_cue()
    except Exception as exc:
        _log.debug("[lean] mood-share cue lookup failed: %s", exc)
        return None


def _lean_event_followup_cue(person_id: Optional[int]) -> Optional[dict]:
    """Offer ONE remembered event whose date has passed ("how did the interview go?") to
    Lean's single lull speaker, or ``None``.

    The old silence-fill ``memory_followup`` behavior went dark under the lean brain; this
    revives it as a Lean cue instead of a competing speaker. Source is the SAME data the
    reactive ``_post_response`` follow-up reads — ``events.get_pending_followups`` — but read
    NON-destructively here (the consciousness in-memory queue getter POPS, so we must not use
    it). Coordination with the other follow-up paths is via shared session state:

      * ``_memory_followup_cadence_allows()`` — the moderate gap/cooldown/flat-room clamp,
        shared with ``_post_response`` (so a lull follow-up and a reactive one can't stack).
      * ``_fired_followup_event_ids`` — the per-session anti-repeat set every follow-up path
        (reactive, startup greeting, this cue) honors, so the same event is never asked twice.

    UPCOMING events are intentionally excluded — anticipation is owned by the greeting-time
    ``_pick_anticipated_event`` path. Fail-safe to ``None`` so a missing DB never breaks the
    impulse.
    """
    if person_id is None or not bool(getattr(config, "LEAN_EVENT_FOLLOWUP_ENABLED", True)):
        return None
    if not _memory_followup_cadence_allows():
        return None
    try:
        pending = events_memory.get_pending_followups(int(person_id)) or []
    except Exception as exc:
        _log.debug("[lean] event-followup cue lookup failed: %s", exc)
        return None
    for ev in pending:
        try:
            eid = int(ev.get("id"))
        except (TypeError, ValueError):
            continue
        if eid in _fired_followup_event_ids:
            continue
        name = str(ev.get("event_name") or "").strip()
        if not name:
            continue
        # get_pending_followups returns BOTH dated-past events AND undated aspirations
        # older than FOLLOWUP_UNDATED_DAYS. For a dated plan whose date has passed we can
        # assert it happened ("how did it go?"); for a dateless "I should do X sometime" we
        # must NOT — it may never have occurred — so carry the distinction to the clause.
        dated = bool(str(ev.get("event_date") or "").strip())
        return {"event_id": eid, "event_name": name, "kind": "past", "dated": dated}
    return None


def _lean_topic_blocked(person_id: Optional[int], text: str) -> bool:
    """True when a lean cue's subject collides with a live topic ban (they JUST
    asked to drop it) or a durable mention-boundary ("don't bring up X"). The gate
    that stops the diary's open threads from resurrecting a topic the person shut
    down (field 2026-08-03 20:03: the website open-thread kept coming back across
    sessions until Bret had to say stop twice — and it still wasn't banned)."""
    t = str(text or "")
    if not t:
        return False
    if _topic_is_recently_banned(t):
        return True
    if person_id is None:
        return False
    try:
        # proactive_block_terms, NOT muted_topic_terms: the muted set folds in
        # preference rows whose etiquette wording ("back up a few feet", "do not
        # talk too much") would turn common words into banned topics and silence
        # half the proactive vocabulary. Blocking a whole line needs a real
        # topical boundary (mention/ask on a named subject).
        terms = boundary_memory.proactive_block_terms(int(person_id))
        if not terms:
            return False
        from memory import text_match
        stems = text_match.stems(t)
        return any(text_match.stem(term) in stems for term in terms)
    except Exception as exc:
        _log.debug("[lean] boundary topic gate failed: %s", exc)
        return False


def _lean_open_thread_cue(person_id: Optional[int]) -> Optional[dict]:
    """Offer ONE diary open thread ("whether the motor swap happened") to Lean's
    lull speaker. The consciousness-side _step_open_thread_followup is suppressed
    under the lean brain (lean owns silence-fill), so this cue is the LIVE path.
    Freshness/once-ever rules live in intelligence/open_threads. Threads whose
    subject the person banned or set a boundary on are skipped, not just delayed."""
    if person_id is None or not bool(getattr(config, "OPEN_THREAD_FOLLOWUP_ENABLED", True)):
        return None
    try:
        from intelligence import open_threads
        candidates = open_threads.pending_for_person(int(person_id))
        for pick in candidates:
            if _lean_topic_blocked(person_id, str(pick.get("thread") or "")):
                _log.info("[lean] open thread skipped — banned/bounded topic: %r",
                          pick.get("thread"))
                continue
            return {
                "episode_id": pick["episode_id"],
                "thread": pick["thread"],
                "when": open_threads.describe_age(pick["age_days"]),
            }
        return None
    except Exception as exc:
        _log.debug("[lean] open-thread cue lookup failed: %s", exc)
        return None


