def _person_interest_topics(person_id: Optional[int]) -> list[str]:
    """The person's top stored interest names for tailored news ([] unknown)."""
    if person_id is None:
        return []
    try:
        from memory import interests as interests_memory
        rows = interests_memory.get_interests_for_prompt(
            int(person_id),
            limit=int(getattr(config, "INTEREST_NEWS_TOPICS_PER_PERSON", 3)),
        ) or []
        return [str(r.get("name") or "").strip() for r in rows
                if len(str(r.get("name") or "").strip()) >= 3]
    except Exception as exc:
        _log.debug("[lean] interest topics lookup failed: %s", exc)
        return []


def _lean_news_cue(person_id: Optional[int] = None) -> Optional[dict]:
    """Offer ONE cached story ("did you hear about ...?"). One per session;
    each story offered at most once ever (spent on-spoke).

    Interest-tailored first: when Rex knows the person's interests, their
    topics get a per-topic daily news fetch (background, budget-capped) and an
    unspent interest story beats the generic headline pool — "seen the new
    Strange New Worlds episode?" instead of world news."""
    global _lean_news_mentioned_this_session
    if _lean_news_mentioned_this_session:
        return None
    if not bool(getattr(config, "CURRENT_EVENTS_ENABLED", True)):
        return None
    try:
        from awareness import current_events
        if bool(getattr(config, "INTEREST_NEWS_ENABLED", True)):
            topics = _person_interest_topics(person_id)
            if topics:
                current_events.start_interest_refresh(topics)
                picked = current_events.pick_interest_story(topics)
                if picked:
                    topic, story = picked
                    return {"headline": story["headline"],
                            "summary": story["summary"],
                            "topic": story.get("topic") or "",
                            "interest_topic": topic}
        story = current_events.pick_story()
        if not story:
            return None
        return {"headline": story["headline"], "summary": story["summary"],
                "topic": story.get("topic") or ""}
    except Exception as exc:
        _log.debug("[lean] news cue lookup failed: %s", exc)
        return None


# Elaboration shapes that count as "asked to hear more" about the story Rex just
# offered. The explicit-more branch matches on wording alone; the looser
# referential branch ("when is that?", "is it in Vegas?") additionally requires
# the news offer to still be the ACTIVE reply frame, so an unrelated question a
# few minutes later can't hijack the turn into a story search.
_NEWS_FOLLOWUP_MORE_RE = re.compile(
    r"\b(?:tell\s+(?:me|us)\s+more|say\s+more|more\s+about|go\s+on|keep\s+going|"
    r"elaborate|what\s+else|what\s+happened|fill\s+(?:me|us)\s+in|"
    r"what(?:'s|\s+is)\s+(?:that|it|this)\s+about)\b",
    re.IGNORECASE,
)
_NEWS_FOLLOWUP_REF_RE = re.compile(
    r"\b(?:that|it|this|the\s+story|the\s+news)\b", re.IGNORECASE
)
_NEWS_HEADLINE_STOPWORDS = {
    "with", "from", "that", "this", "their", "there", "about", "after",
    "into", "over", "gets", "sets", "says", "will", "have", "been", "more",
}


def _news_followup_story(text: str) -> Optional[dict]:
    """The just-offered news story when `text` asks to hear more about it, else
    None. Drives the grounded elaboration: forced web search on the story (or a
    summary-grounded reply) instead of a context-free 'tell me more' turn."""
    if not bool(getattr(config, "NEWS_FOLLOWUP_ELABORATION_ENABLED", True)):
        return None
    story = _last_news_story_offered
    headline = str((story or {}).get("headline") or "").strip()
    if not story or not headline:
        return None
    window = float(getattr(config, "NEWS_FOLLOWUP_WINDOW_SECS", 240.0))
    if (time.monotonic() - float(story.get("at") or 0.0)) > window:
        return None
    cleaned = " ".join((text or "").strip().split())
    if not cleaned:
        return None
    if _NEWS_FOLLOWUP_MORE_RE.search(cleaned):
        return dict(story)
    # Looser referential/topic matches only bind while the news offer is still
    # the latest active Rex turn frame (its topic carries the headline).
    try:
        from intelligence import dialogue_act
        frame = dialogue_act.active_frame()
        frame_is_news = bool(frame is not None and frame.topic == headline)
    except Exception:
        frame_is_news = False
    if not frame_is_news or "?" not in cleaned:
        return None
    if _NEWS_FOLLOWUP_REF_RE.search(cleaned):
        return dict(story)
    low = cleaned.lower()
    for word in re.findall(r"[a-z0-9']+", headline.lower()):
        if len(word) >= 4 and word not in _NEWS_HEADLINE_STOPWORDS and word in low:
            return dict(story)
    return None


def _lean_interest_discovery_cue(person_id: Optional[int]) -> Optional[dict]:
    """Offer the "so, what are you into that you haven't told me?" discovery
    ask — the catalogue-builder behind interest-tailored news. Fires only for
    a KNOWN person whose stored interests are still sparse
    (< INTEREST_DISCOVERY_MAX_KNOWN), at most once per
    INTEREST_DISCOVERY_REASK_DAYS per person (durable mark, so restarts don't
    re-ask). The ANSWER is harvested by the normal post-turn interest
    extractor — this cue only asks."""
    if person_id is None or not bool(getattr(config, "INTEREST_DISCOVERY_ENABLED", True)):
        return None
    try:
        from memory import interests as interests_memory
        max_known = int(getattr(config, "INTEREST_DISCOVERY_MAX_KNOWN", 5))
        known = interests_memory.get_interests_for_prompt(
            int(person_id), limit=max_known
        ) or []
        if len(known) >= max_known:
            return None
        from datetime import date as _date
        period_days = max(1, int(getattr(config, "INTEREST_DISCOVERY_REASK_DAYS", 10)))
        topic_key = f"interest_discovery:{_date.today().toordinal() // period_days}"
        if rel_memory.was_proactive_asked(int(person_id), topic_key):
            return None
        known_names = ", ".join(
            str(r.get("name") or "").strip() for r in known if r.get("name")
        )
        return {"topic_key": topic_key, "known": known_names}
    except Exception as exc:
        _log.debug("[lean] interest-discovery cue lookup failed: %s", exc)
        return None


# One probability roll per (person, day) for the workday check-in — memoized so
# a failed roll doesn't get re-rolled every lull until it passes (which would
# make the "doesn't always trigger" knob meaningless).
_workday_checkin_rolls: dict = {}

# Work/day talk already happened this session → the evening check-in would be a
# re-ask. Matches either party's turns: the human volunteering ("got home from
# work") or Rex having already asked about their day.
_WORKDAY_TOPIC_RE = re.compile(
    r"\b(?:work|worked|working|job|office|shift|meetings?|workday|"
    r"how\s+was\s+your\s+day|how'?s\s+your\s+day)\b",
    re.IGNORECASE,
)


def _person_profession(person_id: int) -> str:
    """The person's stored job/profession ('trainer'), or ''. Facts with
    category job/work/career win; job-shaped keys anywhere else back them up."""
    try:
        rows = facts_memory.get_facts(int(person_id)) or []
    except Exception:
        return ""
    job_keys = {"job_title", "job", "profession", "occupation", "career", "works_as"}
    # A shaky inferred guess must not become how Rex ADDRESSES someone — the
    # job_title='trainer' fact (conf 0.55, inferred from Bret training the
    # robot) produced "How was work today, trainer?" (field 2026-08-07).
    # Below the floor the cue quietly falls back to the plain "how was your
    # day?" variant, which is always safe.
    min_conf = float(getattr(config, "WORKDAY_CHECKIN_PROFESSION_MIN_CONFIDENCE", 0.75))

    def _usable(row: dict) -> str:
        value = str(row.get("value") or "").strip()
        if not value:
            return ""
        conf = row.get("confidence")
        if conf is not None:
            try:
                if float(conf) < min_conf:
                    return ""
            except (TypeError, ValueError):
                pass
        return value

    for row in rows:
        if str(row.get("category") or "").lower() in ("job", "work", "career"):
            value = _usable(row)
            if value:
                return value
    for row in rows:
        if str(row.get("key") or "").lower() in job_keys:
            value = _usable(row)
            if value:
                return value
    return ""


def _lean_workday_checkin_cue(
    person_id: Optional[int], now: Optional["datetime"] = None
) -> Optional[dict]:
    """Offer the evening "how was work today?" / "how was your day?" check-in
    (owner 2026-08-03: a conversation sparker for repeat visitors).

    Gates: weekday evening (WORKDAY_CHECKIN_START_HOUR..END_HOUR, Mon-Fri),
    known person, not already asked today (durable via mark_proactive_asked, so
    restarts can't re-ask), and one probability roll per day so it deliberately
    does NOT fire every evening. The work variant fires when Rex knows a
    profession (person_facts category='job'); otherwise the plain day variant.
    The mark is written only when the line is actually SPOKEN (the on-spoke
    bookkeeping below), so losing the cue ladder to a richer cue retries at a
    later lull the same evening."""
    if person_id is None or not bool(getattr(config, "WORKDAY_CHECKIN_ENABLED", True)):
        return None
    from datetime import datetime as _dt
    moment = now or _dt.now()
    weekdays = set(getattr(config, "WORKDAY_CHECKIN_WEEKDAYS", (0, 1, 2, 3, 4)))
    if moment.weekday() not in weekdays:
        return None
    start = int(getattr(config, "WORKDAY_CHECKIN_START_HOUR", 17))
    end = int(getattr(config, "WORKDAY_CHECKIN_END_HOUR", 23))
    if not (start <= moment.hour < end):
        return None
    day_key = moment.date().isoformat()
    topic_key = f"workday_checkin:{day_key}"
    try:
        if rel_memory.was_proactive_asked(int(person_id), topic_key):
            return None
    except Exception:
        return None
    # Already talked about work/their day this session? Then the check-in is a
    # re-ask, not a sparker (field 2026-08-07: "I just got home from work" →
    # "How bad was it?" → two minutes later the cue asked "How was work
    # today?"). Session-scoped on purpose — the durable mark stays reserved
    # for a check-in Rex actually spoke.
    try:
        if any(
            _WORKDAY_TOPIC_RE.search(str(turn.get("text") or ""))
            for turn in conv_memory.get_session_transcript() or []
        ):
            return None
    except Exception:
        pass
    roll_key = (int(person_id), day_key)
    if roll_key not in _workday_checkin_rolls:
        _workday_checkin_rolls[roll_key] = (
            random.random() < float(getattr(config, "WORKDAY_CHECKIN_PROBABILITY", 0.8))
        )
        if not _workday_checkin_rolls[roll_key]:
            _log.info(
                "[lean] workday check-in sitting out today for person_id=%s "
                "(probability roll)", person_id,
            )
    if not _workday_checkin_rolls[roll_key]:
        return None
    profession = _person_profession(int(person_id))
    return {
        "topic_key": topic_key,
        "kind": "work" if profession else "day",
        "profession": profession,
    }


def _lean_weekend_plans_cue(person_id: Optional[int]) -> Optional[dict]:
    """Offer the "got anything going this weekend?" discovery ask (owner
    2026-07-18: the river-float weekend came and went unasked — the legacy
    plans curiosity never made it into lean). Gates: it's Thursday-Sunday,
    Rex knows the person, he hasn't asked about THIS weekend yet (durable
    per-ISO-week key in proactive_topics_asked), and no stored upcoming event
    is imminent (then he should reference THAT, not fish). The ANSWER is
    captured by the normal post-turn extractor into person_events, which the
    follow-up machinery then closes next week ("how was the float?")."""
    if person_id is None or not bool(getattr(config, "WEEKEND_PLANS_ASK_ENABLED", True)):
        return None
    from datetime import date as _date
    today = _date.today()
    ask_days = set(getattr(config, "WEEKEND_PLANS_ASK_WEEKDAYS", (3, 4, 5, 6)))  # Thu-Sun
    if today.weekday() not in ask_days:
        return None
    iso = today.isocalendar()
    topic_key = f"weekend_plans:{iso[0]}-W{iso[1]:02d}"
    try:
        if rel_memory.was_proactive_asked(int(person_id), topic_key):
            return None
    except Exception:
        return None
    try:
        upcoming = events_memory.get_upcoming_events(int(person_id)) or []
        if upcoming:
            return None      # he already knows a plan — anticipation owns that
    except Exception:
        pass
    when = "already here — it's the weekend" if today.weekday() >= 5 else "coming up"
    return {"topic_key": topic_key, "when": when}


# ── Lull-gauntlet telemetry (owner 2026-08-05: "he sits there quiet so much") ──
# Every consult of _maybe_lean_impulse ends in exactly one outcome: spoken, a model
# PASS, a dropped line, or one of ~15 gates. Nothing recorded WHICH, so tuning the
# quietness meant guessing. This counts outcomes per session and logs gate
# TRANSITIONS at INFO (the consult loop ticks ~1/s, so logging every repeat of the
# same gate would flood — a transition is the informative event). Summary line at
# session end: grep `[lean] impulse session summary`.
_impulse_outcome_counts: dict = {}
_last_impulse_block_reason: str = ""


def _impulse_outcome(reason: str) -> None:
    _impulse_outcome_counts[reason] = _impulse_outcome_counts.get(reason, 0) + 1


def _impulse_blocked(reason: str) -> bool:
    """Count a gate outcome; log at INFO only when the blocking gate CHANGES."""
    global _last_impulse_block_reason
    _impulse_outcome(reason)
    if reason != _last_impulse_block_reason:
        _last_impulse_block_reason = reason
        _log.info("[lean] impulse blocked: %s", reason)
    return False


def _log_impulse_session_summary() -> None:
    """One line per session answering "why was he quiet?" — logged then reset."""
    global _last_impulse_block_reason
    if not _impulse_outcome_counts:
        return
    total = sum(_impulse_outcome_counts.values())
    parts = ", ".join(
        f"{k}={v}" for k, v in
        sorted(_impulse_outcome_counts.items(), key=lambda kv: -kv[1])
    )
    _log.info("[lean] impulse session summary: consults=%d — %s", total, parts)
    _impulse_outcome_counts.clear()
    _last_impulse_block_reason = ""


# ── Capture telemetry (owner 2026-08-05: "he's not hearing my first line") ────
# A turn that VAD detected can die with ZERO logging: _accumulate_speech returns
# None (state left ACTIVE / shutdown) or an EMPTY array (the capture window
# computed to ~0s), and the listen loop's `if audio_segment is None or len(...)==0:
# continue` drops it silently. So a dropped utterance is indistinguishable in the
# logs from the user never having spoken — which is exactly why the field report
# ("I pause a second, he doesn't hear me, I repeat myself") could not be diagnosed
# from a full-debug run. Same shape as the lull-impulse telemetry: count every
# outcome, log TRANSITIONS at INFO, dump a summary at session end.
_capture_outcome_counts: dict = {}
_last_capture_drop_reason: str = ""


def _capture_outcome(reason: str) -> None:
    _capture_outcome_counts[reason] = _capture_outcome_counts.get(reason, 0) + 1


def _capture_dropped(reason: str, **detail) -> None:
    """Record + log a turn that VAD accepted but that never reached transcription."""
    global _last_capture_drop_reason
    _capture_outcome(reason)
    bits = " ".join(f"{k}={v}" for k, v in detail.items())
    if reason != _last_capture_drop_reason:
        _last_capture_drop_reason = reason
        _log.warning(
            "[capture] utterance DROPPED before transcription — %s %s", reason, bits,
        )
    else:
        _log.info("[capture] utterance dropped again — %s %s", reason, bits)


def _log_capture_session_summary() -> None:
    """One line per session: heard vs dropped, and why. Grep `[capture] session`."""
    global _last_capture_drop_reason
    if not _capture_outcome_counts:
        return
    parts = ", ".join(
        f"{k}={v}" for k, v in
        sorted(_capture_outcome_counts.items(), key=lambda kv: -kv[1])
    )
    _log.info("[capture] session summary: %s", parts)
    _capture_outcome_counts.clear()
    _last_capture_drop_reason = ""


def _person_visible_now(person_id: Optional[int]) -> bool:
    """Is this person on CAMERA right now (stricter than _lean_impulse_person_present,
    which also accepts heard-recently)? Fail-closed — this only grants a bonus."""
    try:
        for p in world_state.get("people") or []:
            if p.get("person_db_id") == person_id:
                return True
    except Exception:
        pass
    return False


def _lean_impulse_addressee() -> tuple[Optional[int], str]:
    """Who the lull impulse should address, and why. (person_id, reason).

    _primary_session_person_id answers a DIFFERENT question — "is there exactly ONE
    person here" — and returns None as soon as a second person speaks. The lean
    brain now owns proactivity outright (the governor hard-rejects the whole legacy
    silence-fill taxonomy as lean_brain_silence_fill_suppressed), so that None means
    a room with two known humans in it gets no lull filler from either system.

    Field 2026-08-20: JT's first turn at 20:12:05 killed it for the rest of the
    session — ~11 minutes of unbroken `no_known_person`, and 2300 of 3271 consults
    (70%) died on this one gate. Rex's proactive speech for the remaining ~21
    minutes was animal remarks and one identity prompt.

    Addressing does not require exclusivity: in a group, the person who spoke last
    is the right person to talk to. Order of preference:
      1. the strict single-person answer, when there is one;
      2. the currently/recently engaged partner (consciousness tracks this);
      3. the session person with the most turns, if any are visible or heard;
    Returns None only when nobody known has spoken or been seen — an empty room.
    """
    primary = _primary_session_person_id()
    if primary is not None:
        return primary, "primary"
    try:
        engaged = consciousness.get_recent_engagement()
        if engaged and engaged.get("person_id") is not None:
            return int(engaged["person_id"]), "engaged"
    except Exception:
        _log.debug("[lean] engaged-addressee lookup failed", exc_info=True)
    # Most talkative known person this session, provided they are still around.
    try:
        ranked = sorted(
            ((pid, n) for pid, n in _session_person_turn_counts.items() if pid is not None),
            key=lambda kv: kv[1], reverse=True,
        )
        for pid, _turns in ranked:
            if _lean_impulse_person_present(int(pid)):
                return int(pid), "most_turns"
    except Exception:
        _log.debug("[lean] turn-count addressee lookup failed", exc_info=True)
    return None, ("ambiguous_addressee" if _session_person_ids else "empty_room")


def _lean_impulse_person_present(person_id: int) -> bool:
    """Is the impulse's target plausibly HERE — on camera now, or heard recently?

    _primary_session_person_id() is session CONTINUITY, not presence: after the user
    walks out, it keeps returning them, and the lull impulse kept addressing questions
    to an empty room for 2+ minutes (field-logged 2026-07-11, "I'm gonna leave the
    room now"). Voice-led off-camera conversation stays legitimate via the
    heard-recently clause; fail-open on state errors so a hiccup can't mute Rex."""
    heard_secs = float(getattr(config, "LEAN_IMPULSE_PRESENCE_HEARD_SECS", 120.0))
    if _last_user_content_at > 0.0 and (time.monotonic() - _last_user_content_at) <= heard_secs:
        return True
    try:
        for p in world_state.get("people") or []:
            if p.get("person_db_id") == person_id:
                return True
    except Exception:
        return True
    return False


# ── Disengagement probe (owner 2026-07-18) ──────────────────────────────────
# Canned Rex-voice check-ins — deliberately NOT LLM-generated: the probe must
# fire reliably even when the lean brain would PASS, and the owner supplied the
# register. {name}-bearing lines are only used when a first name is known.
_ENGAGEMENT_PROBE_LINES = (
    "Am I bothering you, {name}?",
    "You busy? You've got that preoccupied look.",
    "Don't be shy — I can see you sitting right there.",
    "You seem busy. Say the word and I'll pipe down.",
    "I'm getting a lot of silence for someone in plain view.",
)
_ENGAGEMENT_PROBE_SHY_LINES = (
    "I don't bite, {name}. Couldn't if I wanted to — no teeth.",
    "You can talk to me, {name}. I'm told I'm charming in small doses.",
    "First conversations are the awkward ones, {name}. Say anything — I'll carry the rest.",
)

# Verbal deferrals — "give me a few minutes", "hold on", "can't talk right now".
# Whisper drops punctuation/apostrophes, so shapes are apostrophe-tolerant.
_ENGAGEMENT_DEFERRAL_RE = re.compile(
    r"\b(?:"
    r"give me (?:a|a few|a couple(?: of)?|one|two|\d+) (?:minute|minutes|min|mins|sec|secs|second|seconds|moment|moments)"
    r"|gimme a (?:minute|min|sec|second|few|moment)"
    r"|in a (?:minute|bit|sec|second|moment|few)"
    r"|hold on|hang on|one sec|just a (?:sec|second|minute|moment)"
    r"|not (?:right )?now|can'?t talk(?: right now)?"
    r"|i'?m (?:kinda |a little |really )?busy|busy right now"
    r"|later,? (?:rex|r3x|r3-x)"
    r")\b",
    re.I,
)


def _note_user_speech_for_engagement() -> None:
    """Any real accepted user turn = they're talking again: clear a pending
    probe, the probed-this-silence latch, and any impulse snooze."""
    global _engagement_probe_at, _engagement_probed_this_silence
    global _impulse_snooze_until, _impulse_snooze_reason, _impulse_snooze_person
    _engagement_probe_at = 0.0
    _engagement_probed_this_silence = False
    if _impulse_snooze_until > 0.0:
        _log.info("[lean] user spoke — engagement snooze (%s) lifted", _impulse_snooze_reason)
    _impulse_snooze_until = 0.0
    _impulse_snooze_reason = ""
    _impulse_snooze_person = None


def _maybe_capture_engagement_deferral(text: str) -> bool:
    """Passive watcher on every human turn: a deferral ("give me a few minutes",
    "busy right now") snoozes the impulse machinery briefly — Rex lets the reply
    LLM answer naturally ("take your time"), goes quiet, and checks back in a
    minute or two. Never consumes the turn."""
    global _impulse_snooze_until, _impulse_snooze_reason, _impulse_snooze_person
    if not bool(getattr(config, "ENGAGEMENT_PROBE_ENABLED", True)):
        return False
    cleaned = " ".join(str(text or "").split())
    if not cleaned or not _ENGAGEMENT_DEFERRAL_RE.search(cleaned):
        return False
    snooze = float(getattr(config, "ENGAGEMENT_DEFER_SNOOZE_SECS", 100.0))
    _impulse_snooze_until = time.monotonic() + snooze
    _impulse_snooze_reason = "deferred"
    _impulse_snooze_person = _primary_session_person_id()
    _log.info(
        "[lean] deferral heard (%r) — impulses snoozed %.0fs, Rex will check back",
        cleaned[:60], snooze,
    )
    return True


def _clear_engagement_state(reason: str = "") -> None:
    """Person left the frame (or session reset): forget the probe AND the snooze
    so the normal idle/boredom/sleep path owns the empty room, and a fresh
    arrival starts clean at the greeting."""
    global _engagement_probe_at, _engagement_probed_this_silence
    global _impulse_snooze_until, _impulse_snooze_reason, _impulse_snooze_person
    if _engagement_probe_at > 0.0 or _impulse_snooze_until > 0.0:
        _log.info("[lean] engagement probe/snooze state cleared (%s)", reason or "reset")
    _engagement_probe_at = 0.0
    _engagement_probed_this_silence = False
    _impulse_snooze_until = 0.0
    _impulse_snooze_reason = ""
    _impulse_snooze_person = None


def _speak_engagement_probe(person_id: int) -> bool:
    """Speak the direct 'Am I bothering you?' check-in and arm the answer window.
    Shy variant for someone Rex barely knows (sparse profile — a newly greeted
    person going silent reads as shyness, not disinterest)."""
    global _engagement_probe_at, _engagement_probed_this_silence
    global _last_proactive_line_at, _consecutive_lean_impulses
    name = ""
    try:
        from memory import people as _people_mod
        row = _people_mod.get_person(person_id) or {}
        name = _first_name_or(row.get("name"), "")
    except Exception:
        pass
    shy = False
    try:
        shy = profile_questions.profile_fact_count(person_id) <= int(
            getattr(config, "LOW_MEMORY_PROFILE_MAX_FACTS", 4) or 4
        )
    except Exception:
        pass
    pool = _ENGAGEMENT_PROBE_SHY_LINES if (shy and name) else _ENGAGEMENT_PROBE_LINES
    candidates = [l for l in pool if name or "{name}" not in l]
    if not candidates:
        candidates = ["You busy? You've got that preoccupied look."]
    line = random.choice(candidates).format(name=name)
    completed = _speak_proactive(
        line, emotion="curious", priority=1, label="engagement_probe"
    )
    if completed:
        now = time.monotonic()
        _engagement_probe_at = now
        _engagement_probed_this_silence = True
        _last_proactive_line_at = now
        _lean_impulse_spoken_times.append(now)   # counts against the rolling rate cap
        _consecutive_lean_impulses += 1
        conv_memory.add_to_transcript("Rex", line)
        conv_log.log_rex(line)
        _register_rex_utterance(
            line,
            source="lean_impulse",
            target_person_id=person_id,
            expected_reply_types=["answer", "statement"],
        )
        try:
            question_budget.note_rex_utterance(line)
        except Exception:
            pass
        _log.info("[lean] engagement probe — person_id=%s shy=%s text=%r", person_id, shy, line)
    return completed


_LEAN_CUE_WHY = {
    "celebration": "a remembered occasion of theirs came due",
    "holiday_plan": "a holiday is coming up and I asked about plans",
    "event_followup": "I remembered an event they'd mentioned and followed up",
    "open_thread": "an open thread from an earlier conversation",
    "callback_premise": "I called back to an earlier joke",
    "workday_checkin": "the time of day — I checked in on their work day",
    "place_question": "I wasn't sure which room this is and asked",
    "room_question": "I noticed something in the room I didn't know and asked",
    "visual_riff": "something I saw caught my eye and I riffed on it",
    "weekend_plans": "the weekend, so I asked about plans",
    "interest_discovery": "I was fishing for a new interest of theirs",
    "mood_share": "I shared how my day was going",
    "news_story": "a news story I'd picked up that fit their interests",
    "memory_musing": "a memory of ours drifted up",
}


def _lean_impulse_why(kind: Optional[str], quiet: float, long_silence: bool) -> str:
    cue = _LEAN_CUE_WHY.get(str(kind or ""), "")
    quiet_txt = f"the room had been quiet about {int(quiet)} seconds" if quiet else "a lull"
    if cue:
        return f"{quiet_txt}, and {cue}"
    if long_silence:
        return f"{quiet_txt} — a long silence — and I tried to re-engage"
    return f"{quiet_txt} and I filled the silence with whatever came to mind"


def _maybe_lean_impulse(*, idle_for: float, effective_idle_timeout: float) -> bool:
    """Lean AGENCY (Phase 1): when a known person is PRESENT but quiet, let Rex DECIDE — via the
    lean brain, grounded in perception + memory + mood — to say ONE motivated thing or just watch
    (the default). Replaces the old silence-fill taxonomy (idle banter / interview questions).

    Restraint is spacing, not a chatty prompt: a quiet threshold + a cooldown (armed even on a
    pass, so the model isn't hammered) + a config 'in the mood' probability. Frequency lives in
    config (LEAN_IMPULSE_*), tuned live — the model reliably produces a good line OR passes."""
    global _last_lean_impulse_at, _last_proactive_line_at, _consecutive_lean_impulses
    global _awaiting_followup_event, _lean_memory_mused_this_session
    global _lean_mood_shared_this_session
    global _lean_news_mentioned_this_session, _last_news_story_offered
    global _engagement_probe_at, _impulse_snooze_until, _impulse_snooze_reason
    global _impulse_snooze_person
    if not (
        bool(getattr(config, "LEAN_BRAIN_ENABLED", False))
        and bool(getattr(config, "LEAN_IMPULSE_ENABLED", True))
    ):
        return False
    if _game_suppresses_conversation() or _directed_context_fresh():
        return _impulse_blocked("game_or_directed_context")
    try:
        if end_thread.is_grace_active():
            return _impulse_blocked("end_thread_grace")
    except Exception:
        pass
    # An active come-here errand owns the body AND the floor: a lull line's
    # speech gestures wobble the neck/tilt mid-search, wrecking face detection
    # and the alignment read ("the head tilt kept changing", field 2026-08-11
    # 19:37) — and chatting away while hunting for the person reads wrong anyway.
    try:
        from intelligence import motion_agency
        if motion_agency.requested_come_active():
            return _impulse_blocked("come_errand_active")
    except Exception:
        pass
    # Not _primary_session_person_id: that answers "is there exactly ONE person
    # here" and goes None the moment a second person speaks, which silenced the
    # lull impulse for 70% of the 2026-08-20 run. See _lean_impulse_addressee.
    person_id, why = _lean_impulse_addressee()
    if person_id is None:                       # nobody known present → never nudge an empty room
        # Split reason: "empty room" and "known people here but I can't pick one"
        # were both logged as no_known_person, which is why this hid for so long.
        return _impulse_blocked(why)
    if not _lean_impulse_person_present(person_id):
        # Target left (or went silent + off-camera): forget any probe/snooze so
        # the normal idle/boredom/sleep path owns the room from here.
        _clear_engagement_state("person left")
        return _impulse_blocked("person_absent")
    # ── Disengagement protocol (owner 2026-07-18) ────────────────────────────
    # An unanswered probe past its window = they don't want to talk right now:
    # go quiet for a long while (presence-gated; speaking clears it instantly).
    _now_eng = time.monotonic()
    if _engagement_probe_at > 0.0 and (
        _now_eng - _engagement_probe_at
    ) >= float(getattr(config, "ENGAGEMENT_PROBE_ANSWER_WINDOW_SECS", 30.0)):
        _no_ans = float(getattr(config, "ENGAGEMENT_PROBE_NO_ANSWER_SNOOZE_SECS", 600.0))
        _engagement_probe_at = 0.0
        _impulse_snooze_until = _now_eng + _no_ans
        _impulse_snooze_reason = "no_answer"
        _impulse_snooze_person = person_id
        _log.info(
            "[lean] engagement probe unanswered — assuming they don't want to talk; "
            "impulses snoozed %.0fs (speaking resumes immediately)", _no_ans,
        )
    if _engagement_probe_at > 0.0:
        return _impulse_blocked("probe_outstanding")  # wait out the window quietly
    if _now_eng < _impulse_snooze_until:
        if _impulse_snooze_person in (None, person_id):
            return _impulse_blocked(f"probe_snoozed_{_impulse_snooze_reason or 'unknown'}")
        # A DIFFERENT known person is now the target — their arrival isn't
        # muted by someone else's snooze.
        _clear_engagement_state("new person arrived")
    # "Quiet" = seconds since REX last spoke (his reply or a prior impulse), NOT since the user
    # spoke — a short natural pause after Rex FINISHES is the trigger, so the reply's own
    # generation + playback time doesn't count against it. 0.0 while he's still speaking (blocked
    # below), inf before he's ever spoken (the greeting leads, not the impulse).
    try:
        quiet = speech_queue.seconds_since_last_speech()
    except Exception:
        quiet = idle_for
    if quiet == float("inf") or quiet < float(getattr(config, "LEAN_IMPULSE_QUIET_SECS", 5.0)):
        return _impulse_blocked("too_soon_after_rex_spoke")
    # A conversation that is actively FLOWING is not a lull. If the user spoke within
    # the flow window, the reply thread owns the floor — a new self-initiated thread
    # needs a genuinely long mutual silence first. (Field bug: 7 impulse questions in
    # 2.5 minutes of active back-and-forth read as random question spam, drowning the
    # actual conversation.)
    _flow_window = float(getattr(config, "LEAN_IMPULSE_FLOW_WINDOW_SECS", 120.0))
    _flow_quiet = float(getattr(config, "LEAN_IMPULSE_FLOW_QUIET_SECS", 30.0))
    # ADAPTIVE re-engage wait (owner 2026-07-08: "estimate a good time to wait —
    # humans don't like dead silence"). After Rex asked a question, the floor-hold
    # above already makes him wait for the answer. So reaching here with his last
    # line a CLOSED statement means the exchange stalled on him ("good" → "Try not
    # to make it a personality." → silence) — bridge it sooner than a full 14s.
    if not _last_rex_line_was_question:
        _flow_quiet = min(
            _flow_quiet,
            float(getattr(config, "LEAN_IMPULSE_FLOW_QUIET_AFTER_STATEMENT_SECS", 7.0)),
        )
    if (
        _last_user_content_at > 0.0
        and (time.monotonic() - _last_user_content_at) <= _flow_window
        and quiet < _flow_quiet
    ):
        return _impulse_blocked("conversation_flowing")
    if idle_for >= max(0.0, effective_idle_timeout - 1.0):   # leave room for the outro
        return _impulse_blocked("outro_imminent")
    if time.monotonic() < _floor_held_until:    # Rex just asked something — let them answer
        return _impulse_blocked("awaiting_answer_floor_hold")
    if _proactive_line_recently_fired():
        return _impulse_blocked("proactive_line_gap")
    now = time.monotonic()
    # Two tempos for a quiet room:
    #  FAST lull-break — within a few seconds of Rex finishing, up to MAX_UNANSWERED escalating lines,
    #    then he yields the floor (no piling quips into the void). Counter + anchor reset when the user
    #    speaks (_begin_user_turn), so a fresh silence gets its full allowance.
    #  SLOW re-engagement — once the fast run has yielded and it's gone truly quiet for REENGAGE_SECS
    #    (since Rex last spoke) with the person STILL here, take one PATIENT swing on a genuinely NEW
    #    topic so the conversation doesn't just die (owner: "after 40s of silence, bring up a new
    #    topic"). It bypasses the fast cap/gap but is itself spaced by REENGAGE_SECS (the anchor arms
    #    on every consult, so it can't hammer) and ultimately bounded by the present give-up outro.
    _reengage_secs = float(getattr(config, "LEAN_IMPULSE_REENGAGE_SECS", 0.0))
    long_silence = (
        _reengage_secs > 0.0
        and quiet >= _reengage_secs
        and (now - _last_lean_impulse_at) >= _reengage_secs
    )
    if not long_silence:
        # +1 allowance when they're visibly ON CAMERA (owner 2026-08-05 quietness
        # tuning): sitting in plain view is soft permission for one more try; the
        # base cap stands for voice-only, where silence more plausibly means gone.
        _allowance = int(getattr(config, "LEAN_IMPULSE_MAX_UNANSWERED", 2))
        if _person_visible_now(person_id):
            _allowance += max(0, int(getattr(
                config, "LEAN_IMPULSE_MAX_UNANSWERED_VISIBLE_BONUS", 1)))
        if _consecutive_lean_impulses >= _allowance:
            return _impulse_blocked("unanswered_cap")
        _base_cooldown = float(getattr(config, "LEAN_IMPULSE_COOLDOWN_SECS", 50.0))
        _escalation = float(getattr(config, "LEAN_IMPULSE_ESCALATION", 1.0))
        _required_gap = _base_cooldown * (1.0 + _escalation * _consecutive_lean_impulses)
        if now - _last_lean_impulse_at < _required_gap:
            return _impulse_blocked("cooldown")
    try:
        if consciousness.is_waiting_for_response():
            return _impulse_blocked("awaiting_response")
    except Exception:
        pass
    if _interrupted.is_set():
        return _impulse_blocked("interrupted")
    if speech_queue.is_speaking() or output_gate.is_busy() or echo_cancel.is_suppressed():
        return _impulse_blocked("audio_busy")
    try:
        if _suppress_proactive_after_heavy(person_id):
            return _impulse_blocked("post_heavy_grace")
    except Exception:
        pass

    # ── Impulse discipline (Phase B, field report 2026-07-18) ────────────────
    # Rolling rate cap: the per-run counters reset every time the user replies,
    # so a polite user re-arms the machine gun (six lines in three minutes at a
    # tired owner). This cap doesn't reset on replies.
    _cap_window = float(getattr(config, "LEAN_IMPULSE_RATE_WINDOW_SECS", 600.0))
    _cap_n = int(getattr(config, "LEAN_IMPULSE_MAX_PER_WINDOW", 5))
    _lean_impulse_spoken_times[:] = [t for t in _lean_impulse_spoken_times if now - t < _cap_window]
    if len(_lean_impulse_spoken_times) >= _cap_n:
        return _impulse_blocked("rate_cap")
    # ── Disengagement probe trigger ──────────────────────────────────────────
    # The unanswered run has maxed out and it's gone truly quiet: instead of yet
    # another topic swing, ask DIRECTLY whether they want to talk ("Am I
    # bothering you?" / shy-goad for someone new). One probe per silence-run;
    # deliberately BEFORE the low-energy gate — checking in is the polite move
    # at a quiet person, another trivia question is not.
    if (
        bool(getattr(config, "ENGAGEMENT_PROBE_ENABLED", True))
        and long_silence
        and _consecutive_lean_impulses >= int(getattr(config, "LEAN_IMPULSE_MAX_UNANSWERED", 2))
        and not _engagement_probed_this_silence
    ):
        return _speak_engagement_probe(person_id)
    # Low-energy read: tired / disengaged / question-averse people get FEWER,
    # gentler impulses — statements only, longer gaps, and no patient re-engage
    # pestering (let the night end).
    low_energy = False
    try:
        _energy = user_energy.snapshot() or {}
        low_energy = (
            str(_energy.get("engagement") or "").lower() == "low"
            or str(_energy.get("mode") or "").lower() == "quiet"
            or str(_energy.get("question_appetite") or "").lower() == "low"
        )
    except Exception:
        pass
    # Present-and-FACING overrides the text-derived low-energy read (owner
    # 2026-08-03: he sat looking straight at Rex for a minute deliberately
    # waiting for him to strike up conversation; a terse reply had flipped the
    # energy read to quiet and Rex mirrored the silence). Someone whose face
    # stays turned toward Rex during a lull is WAITING, not withdrawing — keep
    # normal cadence and let the unanswered-run discipline (engagement probe)
    # judge disengagement from actual ignores, escalating only when it's
    # obvious they're not engaged.
    if low_energy and bool(
        getattr(config, "LEAN_LOW_ENERGY_FACING_OVERRIDE_ENABLED", True)
    ):
        try:
            if consciousness.person_visibly_facing(
                person_id,
                max_age_secs=float(
                    getattr(config, "LEAN_LOW_ENERGY_FACING_OVERRIDE_SECS", 6.0)
                ),
            ):
                _log.info(
                    "[lean] low-energy read overridden — person is facing Rex "
                    "(fresh face lock); treating them as engaged"
                )
                low_energy = False
        except Exception as exc:
            _log.debug("[lean] facing override check failed: %s", exc)
    if low_energy:
        if long_silence:
            return _impulse_blocked("low_energy_no_reengage")
        # Content is the guard (statement-or-PASS via the lean addendum), NOT a
        # silence wall: the old quiet >= 60s requirement meant lean could never
        # beat the ~35s idle-wander re-greet, so a tired user got "Oh—still
        # here" instead of anything real (field 2026-07-18 01:10 session).
        _low_gap = float(getattr(config, "LEAN_IMPULSE_LOW_ENERGY_GAP_SECS", 120.0))
        if (now - _last_lean_impulse_at) < _low_gap:
            return _impulse_blocked("low_energy_cooldown")
        _log.info("[lean] impulse consult in LOW-ENERGY mode (statements only)")
    # Question budget: an exhausted budget doesn't silence the impulse, it
    # converts it to statement-or-pass (the addendum in lean_brain).
    no_questions = False
    try:
        no_questions = not question_budget.can_ask("lean_impulse")
    except Exception:
        pass

    # Consult the lean brain: does Rex genuinely feel like saying one thing, or does he watch?
    # Arm the cooldown NOW (whether he speaks OR passes) so we consult at most once per window,
    # not every tick — but never burn a window on a coin-flip skip (the bug that made him mute).
    _last_lean_impulse_at = now
    if long_silence:
        # A long dead stretch takes a little energy out of him for the rest of the day.
        # Placed AFTER the cooldown anchor above, not next to the long_silence
        # computation: several gates between here and there `return False`, so an
        # earlier hook would re-fire on every tick of the same silence and slam the
        # drift to its clamp in seconds. (rex_mood paces per-kind as a second belt.)
        _note_day_mood("long_quiet")
    decided_at = now
    try:
        mood = body_mood.current_mood()[0]
    except Exception:
        mood = None
    celebration = None
    holiday_plan = None
    event_followup = None
    visual_riff = None
    callback_premise = None
    memory_musing = None
    open_thread = None
    place_question = None
    room_question = None
    workday_checkin = None
    weekend_plans = None
    interest_discovery = None
    mood_share = None
    news_story = None
    world = _lean_world()
    transcript = _lean_recent_transcript("")
    # Remembered GOOD NEWS is the most meaningful thing Rex can open a lull with, so it
    # outranks every other cue. Restores the symmetry the lean rework broke — console
    # check-ins kept firing while celebrations went dark. Shares the emotional-check-in
    # session gate so it never stacks on a console.
    try:
        celebration = _lean_celebration_cue(person_id)
        if celebration and _lean_cue_blocked("celebration"):
            celebration = None
    except Exception as exc:
        _log.debug("celebration Lean cue lookup failed: %s", exc)
    if celebration:
        # Count this offer; if the model never voices it, the cap in _lean_celebration_cue
        # eventually steps aside so lower cues aren't starved. Cleared on the next user turn
        # and popped below on a successful voicing.
        try:
            _cid = int(celebration.get("event_id"))
            _celebration_unvoiced_attempts[_cid] = _celebration_unvoiced_attempts.get(_cid, 0) + 1
        except (TypeError, ValueError):
            pass
    if not celebration:
        try:
            # Calendar questions are a one-shot Lean cue, not a second proactive
            # speaker. The helper owns per-person/per-date de-dupe shared with the
            # classic consciousness fallback.
            holiday_plan = consciousness._next_holiday_plan_for_person(person_id)
            if holiday_plan and _lean_cue_blocked("holiday_plan"):
                holiday_plan = None
        except Exception as exc:
            _log.debug("holiday-plan Lean cue lookup failed: %s", exc)
    # A remembered plan that has come due ("how did the interview go?") beats a callback
    # or visual riff — it's time-sensitive and specifically attentive. Allowed in both the
    # quick lull and the long-silence re-engagement (a real follow-up is a great restart).
    if not celebration and not holiday_plan:
        try:
            event_followup = _lean_event_followup_cue(person_id)
            if event_followup and _lean_cue_blocked("event_followup"):
                event_followup = None
        except Exception as exc:
            _log.debug("event-followup Lean cue lookup failed: %s", exc)
    # Diary open threads sit right after event follow-ups: same "friend who
    # remembered" register, sourced from the session-summary extractor.
    if not celebration and not holiday_plan and not event_followup:
        open_thread = _lean_open_thread_cue(person_id)
        if open_thread and _lean_cue_blocked("open_thread"):
            open_thread = None
    if not celebration and not holiday_plan and not event_followup and not open_thread:
        callback_premise = _lean_callback_lull_cue(
            person_id, transcript, long_silence=long_silence
        )
        if callback_premise and _lean_cue_blocked("callback_premise"):
            callback_premise = None
    _no_higher = not (celebration or holiday_plan or event_followup or open_thread
                      or callback_premise)
    # Evening workday check-in ("how was work today?" / "how was your day?") is
    # PERSONAL and time-bound, so it outranks the environment cues below —
    # but a real memory follow-up above still beats it.
    if _no_higher and not low_energy and not no_questions:
        try:
            workday_checkin = _lean_workday_checkin_cue(person_id)
            if workday_checkin and _lean_cue_blocked("workday_checkin"):
                workday_checkin = None
        except Exception as exc:
            _log.debug("[lean] workday check-in cue failed: %s", exc)
    # Lower-tier cues honor the drop-bench too (review find 2026-08-05: only the
    # top-tier cues consulted _lean_cue_blocked, so _strike_lean_cue recorded a bench
    # for these kinds that nothing read, and the ladder could regenerate the same
    # doomed line on the very next consult). Checked BEFORE the builder runs — unlike
    # the top-tier lookup-then-discard shape — because some of these builders arm
    # their own pacing/probability state at lookup time, and a benched lookup would
    # silently spend it.
    # Not recognizing the ROOM outranks object curiosity — knowing where he is comes
    # first. place_questions gates itself (only when the belief is unknown + paced).
    if _no_higher and not workday_checkin and not low_energy and not no_questions:
        if not _lean_cue_blocked("place_question"):
            place_question = _lean_place_question_cue()
    # Room curiosity beats a generic visual riff (it LEARNS something), but only
    # when the person has energy for a question.
    if _no_higher and not workday_checkin and not place_question and not low_energy and not no_questions:
        if not _lean_cue_blocked("room_question"):
            room_question = _lean_room_question_cue()
    if _no_higher and not workday_checkin and not place_question and not room_question:
        try:
            if not _lean_cue_blocked("visual_riff"):
                visual_riff = _lean_visual_riff_cue(person_id, world)
        except Exception as exc:
            _log.debug("visual-riff Lean cue lookup failed: %s", exc)
    # LOWEST-priority cue: a low-stakes "since I was last on" diary musing, only when nothing
    # richer fires. Data-driven (the model can't invent a memory it wasn't given), once/session.
    # Weekend-plans discovery beats news (it's personal and time-bound), but
    # never fires at a tired user or with the question budget spent.
    if _no_higher and not workday_checkin and not place_question and not room_question and not visual_riff and not low_energy and not no_questions:
        try:
            if not _lean_cue_blocked("weekend_plans"):
                weekend_plans = _lean_weekend_plans_cue(person_id)
        except Exception as exc:
            _log.debug("weekend-plans Lean cue lookup failed: %s", exc)
    # Interest discovery ("what are you into that you haven't told me?") is
    # personal like weekend plans — it beats news, loses to everything richer,
    # and never fires at a tired user or with the question budget spent.
    if _no_higher and not workday_checkin and not place_question and not room_question and not visual_riff and not weekend_plans and not low_energy and not no_questions:
        try:
            if not _lean_cue_blocked("interest_discovery"):
                interest_discovery = _lean_interest_discovery_cue(person_id)
        except Exception as exc:
            _log.debug("[lean] interest-discovery cue failed: %s", exc)
    # Rex volunteering his OWN day ("ugh, what a day") beats generic news — it's the
    # more human thing to reach for in a lull — but loses to everything about THEM,
    # because asking after someone's weekend always beats talking about yourself.
    # It's a STATEMENT, so unlike the question cues above it stays available at a
    # low-energy user; own-day-in-passing is exactly what fits a winding-down room.
    if _no_higher and not workday_checkin and not place_question and not room_question and not visual_riff and not weekend_plans and not interest_discovery:
        try:
            mood_share = _lean_mood_share_cue(person_id)
        except Exception as exc:
            _log.debug("[lean] mood-share cue lookup failed: %s", exc)
    # News beats the diary musing (fresher material) but loses to everything
    # personal. Its own session cap + spend-once live in the cue/bookkeeping.
    if _no_higher and not workday_checkin and not place_question and not room_question and not visual_riff and not weekend_plans and not interest_discovery and not mood_share:
        if not _lean_cue_blocked("news_story"):
            news_story = _lean_news_cue(person_id)
    if _no_higher and not workday_checkin and not place_question and not room_question and not visual_riff and not weekend_plans and not interest_discovery and not mood_share and not news_story:
        try:
            if not _lean_cue_blocked("memory_musing"):
                memory_musing = _lean_memory_musing_cue(person_id)
        except Exception as exc:
            _log.debug("memory-musing Lean cue lookup failed: %s", exc)
    try:
        from intelligence import lean_brain
        line = lean_brain.consider_initiating(
            person_id,
            transcript=transcript,
            world=world,
            quiet_secs=quiet,
            mood=mood,
            long_silence=long_silence,
            holiday_plan=holiday_plan,
            visual_riff=visual_riff,
            callback_premise=callback_premise,
            event_followup=event_followup,
            celebration=celebration,
            memory_musing=memory_musing,
            open_thread=open_thread,
            place_question=place_question,
            room_question=room_question,
            workday_checkin=workday_checkin,
            weekend_plans=weekend_plans,
            interest_discovery=interest_discovery,
            mood_share=mood_share,
            news_story=news_story,
            low_energy=low_energy,
            no_questions=no_questions,
            rejected_lines=list(_lean_rejected_lines),
        )
    except Exception as exc:
        _log.debug("[lean] impulse generation failed: %s", exc)
        _impulse_outcome("generation_failed")
        return False
    _mode = "reengage" if long_silence else "lull"
    # Which cue fed the instruction (mirrors lean_brain's dispatch priority) —
    # a dropped line benches ITS cue so the next consult reaches lower cues
    # instead of regenerating the same doomed line forever.
    _winning_kind = next(
        (kind for kind, cue in (
            ("celebration", celebration), ("holiday_plan", holiday_plan),
            ("event_followup", event_followup), ("open_thread", open_thread),
            ("callback_premise", callback_premise),
            ("workday_checkin", workday_checkin),
            ("place_question", place_question),
            ("room_question", room_question), ("visual_riff", visual_riff),
            ("weekend_plans", weekend_plans), ("interest_discovery", interest_discovery),
            ("mood_share", mood_share),
            ("news_story", news_story), ("memory_musing", memory_musing),
        ) if cue),
        None,
    )
    if not line:
        _impulse_outcome("watched_pass")
        # A PASS must not buy a FULL pacing window (owner 2026-08-05: chained
        # PASSes on the 40s re-engage path meant minutes of dead air with the
        # person sitting right there). Re-arm only a fraction of the window so
        # the next consult comes sooner; the model still isn't hammered.
        _frac = float(getattr(config, "LEAN_IMPULSE_PASS_REARM_FRACTION", 0.5))
        if 0.0 < _frac < 1.0:
            _gap = float(getattr(config, "LEAN_IMPULSE_COOLDOWN_SECS", 50.0)) * (
                1.0 + float(getattr(config, "LEAN_IMPULSE_ESCALATION", 1.0))
                * _consecutive_lean_impulses)
            _window = _reengage_secs if (long_silence and _reengage_secs > 0.0) else _gap
            _last_lean_impulse_at = now - _window * (1.0 - _frac)
        _log.info("[lean] impulse — watched (person_id=%s, quiet=%.0fs, mode=%s)", person_id, quiet, _mode)
        return False                            # Rex chose to just watch
    if holiday_plan and not _assistant_asked_question(line):
        _log.info("[lean] holiday cue dropped — generated line was not a question: %r", line)
        _impulse_outcome("dropped_holiday_shape")
        _strike_lean_cue(_winning_kind)
        _note_lean_rejected(line)
        return False
    # Content-based anti-repeat (NOT the first-word opener guard — that killed every 'What…?'
    # question, so Rex generated lines and spoke none, and the conversation died). This only
    # drops a near-duplicate of a recent question, so distinct curious questions still get through.
    if _line_duplicates_recent_question(line):
        _log.info("[lean] impulse dropped — re-asks a recent question: %r", line)
        _impulse_outcome("dropped_duplicate_question")
        _strike_lean_cue(_winning_kind)
        _note_lean_rejected(line)
        return False

    # Cross-DAY bit cooldown: session anti-repeat can't see yesterday (the
    # haircut bit ran Jul 31 AND Aug 2). Follow-up-shaped cues are exempt — a
    # remembered "how did it go?" is attentiveness, not a bit.
    if _winning_kind not in _BIT_LEDGER_EXEMPT_CUES and _bit_ledger_blocks(person_id, line):
        _log.info("[lean] impulse dropped — repeats a recent bit: %r", line)
        _impulse_outcome("dropped_bit_repeat")
        _strike_lean_cue(_winning_kind)
        _note_lean_rejected(line)
        return False

    # Banned/bounded-topic backstop: whatever cue won, a generated line that lands
    # on a topic the person banned ("we can change the subject") or set a durable
    # boundary on ("don't bring up the website anymore") is dropped, not spoken.
    # NO cue is exempt — a remembered follow-up about a shut-down topic is exactly
    # the resurrection being stopped.
    if _lean_topic_blocked(person_id, line):
        _log.info("[lean] impulse dropped — banned/bounded topic: %r", line)
        _impulse_outcome("dropped_banned_topic")
        _strike_lean_cue(_winning_kind)
        _note_lean_rejected(line)
        return False

    # Enforcement backstop: a low-energy or budget-exhausted impulse that still
    # came back as a question gets dropped, not spoken.
    if (low_energy or no_questions) and _assistant_asked_question(line):
        _log.info("[lean] impulse dropped — question while %s: %r",
                  "low-energy" if low_energy else "budget-exhausted", line)
        _strike_lean_cue(_winning_kind)
        _note_lean_rejected(line)
        return False

    completed = _speak_proactive(
        line, emotion="curious", priority=1, label="lean_impulse", decided_at=decided_at,
        why=_lean_impulse_why(_winning_kind, quiet, long_silence),
    )
    if completed:
        _last_proactive_line_at = time.monotonic()
        _lean_impulse_spoken_times.append(time.monotonic())   # rolling rate cap (Phase B)
        try:
            question_budget.note_rex_utterance(line)          # questions count against the budget
        except Exception:
            pass
        _consecutive_lean_impulses += 1   # count it against the into-the-void run (reset when the user speaks)
        conv_memory.add_to_transcript("Rex", line)
        conv_log.log_rex(line)
        # File the spoken bit in the cross-day ledger (ALL cues record — a
        # follow-up about paddleboarding also blocks a later freeform
        # paddleboarding bit; only ENFORCEMENT exempts the follow-up cues).
        try:
            from intelligence import bit_ledger
            bit_ledger.record(person_id, line, source=_winning_kind or "impulse")
        except Exception as exc:
            _log.debug("[lean] bit ledger record failed: %s", exc)
        if celebration:
            # A celebration line carries the celebration_checkin FRAME so the person's reply
            # ("it's going great") binds as a status update, not a stray command. dialogue_act
            # infers the reply/blocked types from this source.
            _register_rex_utterance(
                line,
                source="celebration_checkin",
                topic=celebration.get("category") or "their good news",
                target_person_id=person_id,
            )
        elif event_followup:
            # A remembered-event follow-up needs the memory_followup FRAME (not the generic
            # lean_impulse one) so the person's next reply is bound as the OUTCOME — a status
            # update / cancellation / dismissal — and can't be misread as an identity command.
            # Mirrors the reactive _post_response follow-up's frame.
            _register_rex_utterance(
                line,
                source="memory_followup",
                topic=event_followup.get("event_name") or "",
                target_person_id=person_id,
                expected_reply_types=["status_update", "cancel_event", "dismissal"],
                blocked_actions=[
                    "identity.name_correction",
                    "identity.introduce_person",
                ],
            )
        elif news_story:
            # A news offer ("did you hear ...?") invites a follow-up whether or
            # not the generated line carries a literal '?': always expect a
            # reply so "tell me more about that" binds to THIS frame, and put
            # the headline in the topic for the logs.
            _register_rex_utterance(
                line,
                source="lean_impulse",
                topic=str(news_story.get("headline") or ""),
                target_person_id=person_id,
                expected_reply_types=["answer", "statement"],
            )
        else:
            _register_rex_utterance(
                line,
                source="lean_impulse",
                target_person_id=person_id,
                expected_reply_types=(["answer", "statement"] if "?" in line else None),
            )
        if not event_followup and _awaiting_followup_event is not None:
            # This line opened a NEW thread (celebration / holiday / callback / riff / generic),
            # NOT an event follow-up. An earlier armed event follow-up (from this cue, the
            # reactive _post_response path, or the startup greeting) must not now capture the
            # user's reply to THIS line and mis-close that event with an unrelated outcome —
            # _resolve_awaiting_followup keys only off the global slot, frame-independent.
            # Opening a fresh topic supersedes the stale follow-up, so drop it (adversarial
            # review 2026-07-10). The event stays open in the DB and can resurface later.
            _awaiting_followup_event = None
        if holiday_plan:
            try:
                consciousness._mark_holiday_plan_asked(person_id, holiday_plan)
            except Exception as exc:
                _log.debug("holiday-plan Lean cue mark failed: %s", exc)
        if celebration:
            # Mark the event acknowledged (per-event 7-day dedup, shared with the legacy
            # emotional-check-in path so neither re-celebrates it) and log the same rex.db
            # "I celebrated their good news" episode the legacy Trigger A2 wrote.
            try:
                emotional_events.mark_acknowledged(int(celebration["event_id"]))
                _celebration_unvoiced_attempts.pop(int(celebration["event_id"]), None)
            except Exception as exc:
                _log.debug("[lean] celebration mark_acknowledged failed: %s", exc)
            try:
                from intelligence import episodic_hooks
                fn = celebration.get("first_name") or ""
                who_poss = f"{fn}'s" if fn and fn != "them" else "their"
                episodic_hooks.celebration(
                    person_id,
                    celebration.get("person_name"),
                    f"I celebrated {who_poss} good news with them.",
                    detail={"category": celebration.get("category"), "trigger": "lean_celebration_cue"},
                )
            except Exception as exc:
                _log.debug("[lean] celebration episodic hook failed: %s", exc)
        if event_followup:
            # Arm the awaiting-resolution loop (the person's next reply closes the event in
            # memory via _resolve_awaiting_followup) AND mark it fired for the shared
            # per-session anti-repeat — set_awaiting_followup_event does both (it calls
            # _note_memory_followup_fired → _fired_followup_event_ids). Then purge it from the
            # consciousness in-memory queue so the reactive _post_response path can't re-ask.
            try:
                eid = event_followup.get("event_id")
                set_awaiting_followup_event(
                    person_id, eid, event_followup.get("event_name") or ""
                )
                try:
                    consciousness._pending_followups_lock_remove(person_id, eid)
                except Exception as exc:
                    _log.debug("[lean] event-followup queue purge failed: %s", exc)
            except Exception as exc:
                _log.debug("[lean] event-followup mark failed: %s", exc)
        if callback_premise:
            try:
                from intelligence import callback_engine
                callback_engine.spend_lull_premise(callback_premise)
            except Exception as exc:
                _log.debug("[lean] callback lull spend failed: %s", exc)
        if open_thread:
            # Spend the thread permanently (asked at most once, ever) and register
            # the follow-up frame so the reply binds as an outcome.
            try:
                from intelligence import open_threads
                open_threads.mark_asked(open_thread["episode_id"], open_thread["thread"])
            except Exception as exc:
                _log.debug("[lean] open-thread spend failed: %s", exc)
            # Remember WHAT was just referenced so a baffled "I don't remember
            # saying that" can be answered with the actual source (episode
            # summary + when) instead of a stock discard line — see
            # _last_thread_reference in _execute_memory_boundary_command.
            global _last_thread_reference
            _last_thread_reference = {
                "episode_id": int(open_thread.get("episode_id") or 0),
                "thread": str(open_thread.get("thread") or ""),
                "when": str(open_thread.get("when") or "recently"),
                "at": time.monotonic(),
            }
        if place_question:
            # Mark asked + arm the answer-capture latch so the person's next reply
            # ("the living room") names + enrolls the room. The lean_impulse frame
            # already expects a reply (line has "?"), which shields that answer from
            # the person-introduction path.
            try:
                from intelligence import place_questions
                place_questions.note_asked(line)
            except Exception as exc:
                _log.debug("[lean] place-question latch failed: %s", exc)
        if room_question:
            # Mark asked + arm the answer-capture latch (the person's next reply
            # can teach the room model what the object actually is).
            try:
                from intelligence import room_questions
                room_questions.note_asked(room_question["label"])
            except Exception as exc:
                _log.debug("[lean] room-question latch failed: %s", exc)
        if workday_checkin:
            # Durable once-per-day mark, so the check-in can't repeat across runs.
            try:
                rel_memory.mark_proactive_asked(person_id, workday_checkin["topic_key"])
            except Exception as exc:
                _log.debug("[lean] workday check-in mark failed: %s", exc)
        if weekend_plans:
            # Durable once-per-ISO-week mark, so the ask can't repeat across runs.
            try:
                rel_memory.mark_proactive_asked(person_id, weekend_plans["topic_key"])
            except Exception as exc:
                _log.debug("[lean] weekend-plans mark failed: %s", exc)
        if interest_discovery:
            # Durable per-period mark so the discovery ask can't repeat across runs.
            try:
                rel_memory.mark_proactive_asked(person_id, interest_discovery["topic_key"])
            except Exception as exc:
                _log.debug("[lean] interest-discovery mark failed: %s", exc)
        if news_story:
            _lean_news_mentioned_this_session = True
            # Keep the offered story at hand: the person's "tell me more about
            # that" is answered from THIS content (forced grounded search, or
            # the cached summary), not from the bare pronoun.
            _last_news_story_offered = {
                "headline": str(news_story.get("headline") or ""),
                "summary": str(news_story.get("summary") or ""),
                "topic": str(
                    news_story.get("interest_topic") or news_story.get("topic") or ""
                ),
                "at": time.monotonic(),
            }
            try:
                from awareness import current_events
                if news_story.get("interest_topic"):
                    current_events.mark_interest_story_mentioned(
                        news_story["interest_topic"], news_story
                    )
                else:
                    current_events.mark_mentioned(news_story)
            except Exception as exc:
                _log.debug("[lean] news spend failed: %s", exc)
        if mood_share:
            # Spend BOTH clocks. The session flag stops a second share this sitting;
            # rex_mood.note_spoken() is the per-DAY one and is persisted, so he won't
            # re-announce the same mood after a reboot this afternoon. Marked
            # explicitly here rather than leaning on the text-matching detector in
            # _register_rex_utterance — we KNOW this line was the mood.
            _lean_mood_shared_this_session = True
            try:
                from intelligence import rex_mood
                rex_mood.note_spoken()
                # Persist NOW, not just at session end: a crash or hard power-off
                # before _end_session would lose the spend, and the next boot would
                # cheerfully re-announce the same mood. The write is a tiny atomic
                # tmp+replace — cheap enough to pay per share (once a day at most).
                rex_mood.persist()
            except Exception as exc:
                _log.debug("[lean] mood-share spend failed: %s", exc)
        if memory_musing:
            # One "since I was last on" musing per session — session_recap is stable within a
            # session, so a second would repeat. Reset in _end_session.
            _lean_memory_mused_this_session = True
        _impulse_outcome("spoken")
        _log.info("[lean] impulse — person_id=%s mode=%s text=%r", person_id, _mode, line)
    return completed


def _maybe_idle_banter(
    *,
    idle_for: float,
    effective_idle_timeout: float,
) -> bool:
    """General proactive filler: when the user simply goes quiet (no goodbye),
    Rex re-engages instead of waiting out the timeout and signing off. Alternates
    between asking about the user and volunteering his own opinion/preference, up
    to IDLE_BANTER_MAX_PER_STRETCH times per silent stretch. Unlike the interest /
    low-memory idle paths, this also fires for well-known, fully-profiled people."""
    global _last_idle_banter_at, _idle_banter_count, _session_exchange_count
    global _idle_banter_threshold, _last_proactive_line_at
    if not bool(getattr(config, "IDLE_BANTER_ENABLED", True)):
        return False
    if _game_suppresses_conversation():
        return False
    if _directed_context_fresh():
        return False
    # Roll a fresh random nudge delay once per silent stretch (reset on re-engagement),
    # so the first re-engagement lands at a natural, non-metronomic moment in [MIN, MAX].
    # MID-CONVERSATION use a slightly longer floor than the cold-room 5-8s (an engaged
    # human pauses a beat longer while composing, and Rex's own reply latency eats into
    # that) — but only ~8-12s, not the old 22-30s that read as abandoned. Over-talk is
    # now held off by the short single-line nudge + cooldown + per-stretch cap.
    try:
        _profile = _situation_assessor.evaluate()
        _conv_active = bool(_profile.conversation_active or _profile.rapid_exchange)
    except Exception:
        _conv_active = False
    if _idle_banter_threshold is None:
        if _conv_active:
            lo = float(getattr(config, "IDLE_BANTER_ACTIVE_MIN_SECS", 22.0) or 22.0)
            hi = float(getattr(config, "IDLE_BANTER_ACTIVE_MAX_SECS", 30.0) or 30.0)
        else:
            lo = float(getattr(config, "IDLE_BANTER_MIN_SECS", 6.0) or 6.0)
            hi = float(getattr(config, "IDLE_BANTER_MAX_SECS", 10.0) or 10.0)
        if hi < lo:
            lo, hi = hi, lo
        _idle_banter_threshold = random.uniform(lo, hi)
    threshold = max(2.0, _idle_banter_threshold)
    if idle_for < threshold:
        return False
    # Rex just asked a real question — hold the floor so the user can actually
    # answer instead of getting a fresh prompt piled on top.
    if time.monotonic() < _floor_held_until:
        return False
    # One proactive line at a time. The proactive QUESTION paths (low-memory /
    # interest follow-up) speak inline and never arm _floor_held_until, so without
    # this a profile question and this banter can commit back-to-back in the same
    # lull — Rex talking over his own question. PROACTIVE_LINE_MIN_GAP_SECS spaces
    # them so it's "one line, then wait."
    if _proactive_line_recently_fired():
        return False
    # Belt-and-suspenders for the still-open-question case: if Rex is awaiting an
    # answer to ANY question (including a proactive one that didn't arm the floor
    # hold), don't volunteer over it.
    try:
        if consciousness.is_waiting_for_response():
            return False
    except Exception:
        pass
    # Leave room before the hard idle cutoff so the outro can still land.
    if idle_for >= max(0.0, effective_idle_timeout - 1.0):
        return False
    if _idle_banter_count >= int(getattr(config, "IDLE_BANTER_MAX_PER_STRETCH", 2) or 0):
        return False
    # A curt, content-free answer ("not much") is a legitimate reply, NOT a topic to keep
    # mining. Allow at most ONE gentle re-engagement after it, then wait for a real user
    # turn — don't pile a second chime-in onto the same non-answer (live-logged 2026-06-26:
    # "not much" was editorialized twice, ~18s apart).
    if (
        bool(getattr(config, "IDLE_BANTER_LOW_CONTENT_GATE_ENABLED", True))
        and _idle_banter_count >= int(getattr(config, "IDLE_BANTER_LOW_CONTENT_MAX_PER_STRETCH", 1) or 0)
        and _last_user_turn_was_low_content()
    ):
        return False
    now = time.monotonic()
    if now - _last_idle_banter_at < float(getattr(config, "IDLE_BANTER_COOLDOWN_SECS", 12.0) or 0.0):
        return False
    if speech_queue.is_speaking() or output_gate.is_busy() or echo_cancel.is_suppressed():
        return False
    if _interrupted.is_set():
        return False
    try:
        if end_thread.is_grace_active():
            return False
    except Exception:
        pass

    person_id = _primary_session_person_id()
    if person_id is None:
        return False

    # GIVE SPACE after a heavy/grief moment. A user going quiet after sharing something
    # heavy — or after DECLINING to — is not an invitation to fill the silence. Proactive
    # re-engagement here risks re-probing the very topic they stepped back from
    # (live-logged 2026-06-18: after the user named a late parent and declined, idle
    # banter piped up ~30s later with "what's one thing about your mother you still
    # hear?", violating the just-set boundary). Rex still RESPONDS when spoken to; he
    # just doesn't proactively pipe up during the sober window or an open grief flow.
    if _suppress_proactive_after_heavy(person_id):
        _log.debug("[interaction] idle banter suppressed — giving space after heavy/grief moment")
        return False

    # Lead with SUBSTANCE, not an interview: the first re-engagement after a pause
    # VOLUNTEERS Rex's own current preoccupation (rex_pov); only a later banter in
    # the same silent stretch turns the spotlight back on the user. This is the
    # design intent ("volunteer, don't just interview"), and because a silent
    # stretch usually gets only ONE banter before the user replies, the old
    # ask-first default buried the POV every turn (it never surfaced live). The
    # reply path already carries curiosity about the user; idle banter is the slot
    # where Rex brings his own thing.
    # Mid-conversation, a re-engagement should ENGAGE THE SPEAKER about what you were
    # just discussing (a genuine new follow-up) — NOT volunteer an unprompted Rex opinion.
    # A surprise "hot take" dropped into a lull reads as barging in with a random idea,
    # even when it's on-topic; what keeps the conversation alive is drawing the person
    # back out about the thing THEY were talking about. So whenever there's a live thread,
    # turn the spotlight on the user. Rex only brings his own (possibly off-topic)
    # observation when there's no real exchange to build on yet — a cold open / near-empty
    # room — where alternating keeps it from being a wall of questions. (Truly long idle
    # is owned by the session timeout + outro, not by piling on more banter.)
    live_topic = _idle_has_live_topic()
    # A curt, content-free last answer ("not much") is not a thread to riff on — forcing
    # live_topic False makes this nudge a fresh getting-to-know-you question instead of
    # editorializing the non-answer, and (a volunteered take requires a live topic) blocks
    # the "here's my take on your 'not much'" pile-on.
    if (
        bool(getattr(config, "IDLE_BANTER_LOW_CONTENT_GATE_ENABLED", True))
        and live_topic
        and _last_user_turn_was_low_content()
    ):
        live_topic = False
    # If the human just asked to change the subject, the live thread is BANNED —
    # don't deepen it. Pivot OFF it (a getting-to-know-you / plans question) so the
    # boundary acknowledgment isn't undone by an idle line revisiting the topic
    # (live-logged 2026-06-18: "Festival people-watching, then…" fired ~20s after
    # the user declined it). The LLM prompt also carries an explicit ban.
    if live_topic and bool(getattr(config, "TOPIC_BAN_PROACTIVE_SUPPRESS", True)):
        try:
            # Match the ban against the actual live-topic LABEL, not the whole
            # session transcript (which still contains the banned word and would
            # over-suppress).
            _live_label = _boundary_fallback_topic() or ""
        except Exception:
            _live_label = ""
        if _live_label and _topic_is_recently_banned(_live_label):
            _log.info("[topic_ban] idle banter pivoting OFF a recently-banned topic")
            live_topic = False
    # The FIRST re-engagement always draws the user out with a question — deepen the live
    # thread if they started one, else a getting-to-know-you question. But if that first
    # question ALSO goes unanswered (truly dead) and there's a live thread to react to,
    # the next nudge VOLUNTEERS a short ON-topic take instead of asking again — a real
    # angle to push back on or laugh at (directive [1]) — rather than monologuing an
    # off-topic preoccupation. (User ask 2026-06-24: offer opinions when it's truly dead,
    # but keep them fun and on-topic.) pov_text stays empty so the off-topic 'thing on my
    # mind' never fires here.
    ask_user = not _idle_should_volunteer_take(_idle_banter_count, live_topic)
    pov_text = ""
    # Escalate a LATER attempt to a playful silence-tease ("cat got your tongue?") once the
    # earnest re-engagement(s) have gone unanswered — only on a genuine silence, never on a curt
    # non-answer (the low-content gate above already capped that case).
    tease_silence = (
        bool(getattr(config, "IDLE_BANTER_TEASE_SILENCE_ENABLED", True))
        and not _last_user_turn_was_low_content()
        and _idle_banter_count >= int(getattr(config, "IDLE_BANTER_TEASE_SILENCE_AT", 2))
    )
    directive, pov_volunteered = _idle_banter_directive(
        ask_user, live_topic, pov_text, tease=tease_silence)
    # True only when we're turning the spotlight on the user MID-topic — the agenda
    # below then anchors the question to the live thread instead of a fresh interview.
    ask_on_topic = ask_user and live_topic
    # Sometimes, instead of deepening the current thread, pivot to the user's life
    # OUTSIDE this conversation — upcoming plans, the weekend, or an approaching holiday.
    # A real conversationalist doesn't loop one topic to death; "any plans this weekend?"
    # is how a lull turns into genuine connection (and is what the user asked for).
    plans_marker = None  # recorded only if a plans pivot actually speaks (no repeats)
    if ask_user and random.random() < float(
        getattr(config, "IDLE_PLANS_QUESTION_PROBABILITY", 0.35)
    ):
        plans_directive, plans_marker = _idle_plans_directive(person_id)
        if plans_directive:
            directive = plans_directive
            pov_volunteered = False
            ask_on_topic = False  # deliberately off the current topic
    # The generate + govern + speak + on-spoken bookkeeping, deferred so the action
    # governor can run it ONLY if idle banter wins the tick (enforce mode). Captures
    # `directive`/`ask_user`/`person_id` decided above.
    banter_decided_at = time.monotonic()
    def _deliver() -> bool:
        global _session_exchange_count
        try:
            line = llm.get_response(
                "You are re-engaging after a quiet pause in an ongoing conversation. "
                + directive
                + " CRITICAL: keep it to ONE short, casual line — a quick natural nudge "
                "like a friend breaking a brief silence, about 8 to 14 words. NOT a "
                "monologue, not a clever multi-clause paragraph, no 'Counterpoint:'-style "
                "framing. Vary your opener — never open with 'Ah,', 'Oh,', 'Well, well', "
                "or 'You know,'. Return only the line.",
                person_id,
            )
        except Exception as exc:
            _log.debug("idle banter LLM failed: %s", exc)
            return False

        line = llm.clean_response_text(line or "")
        if not line:
            return False
        # Never re-ask a question Rex already asked recently (the duplicate camping
        # question, ~39s apart). Drop and yield the tick.
        if _line_duplicates_recent_question(line):
            _log.info(
                "[interaction] idle banter dropped — re-asks a recent Rex question: %r",
                line,
            )
            return False
        try:
            if tease_silence:
                _purpose = (
                    "Playfully call out the dead air with ONE short, fond teasing jab that "
                    "dares them back into talking — a goad, never a sign-off."
                )
            elif ask_on_topic:
                _purpose = (
                    "Ask ONE genuinely new, specific follow-up question that builds on "
                    "the topic you were just discussing; never re-ask what they already "
                    "told you (not 'what are you working on'). If you have no real new "
                    "question, volunteer a short take on that same topic instead."
                )
            elif ask_user:
                _purpose = "Ask one short, genuine question about the user."
            else:
                _purpose = (
                    "Volunteer one specific Rex opinion or reaction about what you were "
                    "JUST talking about; stay on that topic; do not ask a question."
                )
            frame = social_frame.build_frame(
                "(the user has gone quiet)",
                person_id,
                agenda_directive=(
                    "Primary purpose: after a quiet pause, proactively keep the "
                    "conversation alive. " + _purpose
                ),
            )
            # Asking IS the point of an "ask the user" nudge — force the question through
            # (otherwise the quiet-energy frame strips it and Rex dead-acks). The silence-tease
            # is a rhetorical goad ("cat got your tongue?"), so it also needs the question slot.
            frame.allow_question = bool(ask_user or tease_silence)
            if ask_user:
                frame.max_sentences = max(frame.max_sentences, 2)
                frame.max_words = max(frame.max_words, 24)
            governed = social_frame.govern_response(line, frame)
            if governed.text:
                line = governed.text
        except Exception as exc:
            _log.debug("idle banter govern failed: %s", exc)

        # Opener-diversity backstop: don't fire an idle line that opens with the same word as
        # a recent line (the "Good… Good…" stack). Drop → the idle loop just yields this tick;
        # no canned fallback, so silence is the (better) outcome.
        if _proactive_opener_repeats(line, "idle_monologue"):
            _log.info("[interaction] idle banter dropped — opener repeats a recent line: %r", line)
            return False

        completed = _speak_proactive(
            line, emotion="curious", priority=1, label="idle_banter",
            decided_at=banter_decided_at,
        )
        if completed:
            _log.info(
                "[interaction] idle banter — person_id=%s ask_user=%s text=%r",
                person_id, ask_user, line,
            )
            conv_memory.add_to_transcript("Rex", line)
            conv_log.log_rex(line)
            # Anchor the dialogue frame to the engaged person with an explicit
            # expected-reply type (not bare '?'-inference) so a name-shaped answer
            # to this question ("This is leaf" = "sleep") binds as an answer and is
            # not promoted into an introduction (BUG-2).
            _register_rex_utterance(
                line,
                source="idle_banter",
                target_person_id=person_id,
                expected_reply_types=(
                    ["answer", "statement"] if (ask_user or ask_on_topic) else None
                ),
            )
            _mark_idle_plans_asked(plans_marker)
            if pov_volunteered:
                # Mark the preoccupation as spoken so it isn't re-volunteered (idle
                # banter OR reply path) until the cooldown elapses.
                try:
                    rex_pov.note_pov_spoken()
                except Exception:
                    pass
            _session_exchange_count += 1
        return completed

    if _governor_enforcing():
        # ENFORCE: the governor is the single decider. Arm the idle-banter cooldown
        # NOW so the idle loop doesn't re-submit every tick, then submit a candidate
        # carrying the deferred speak work — only the tick's winner runs; if a
        # higher-priority proactive wins, idle banter quietly yields.
        _last_idle_banter_at = time.monotonic()
        # Also arm the SHARED proactive-line gap on COMMIT, not just on speak. The
        # idle-banter line is LLM-generated, so it doesn't actually speak for several
        # seconds — and in that window an inline proactive path (the low-memory profile
        # question / interest follow-up) checked _proactive_line_recently_fired(), saw
        # nothing fired yet, and stacked a SECOND question on top (live 2026-06-17: the
        # profile question + the idle dog-followup, 4s apart). Marking the gap at submit
        # makes those inline paths back off the moment a proactive line is in flight.
        _last_proactive_line_at = time.monotonic()
        _idle_banter_count += 1
        try:
            from intelligence.action_governor import CandidateMove, governor
            governor.submit_external(CandidateMove(
                source="interaction._maybe_idle_banter",
                purpose="idle_monologue",
                priority=int(getattr(config, "IDLE_BANTER_GOVERNOR_PRIORITY", 50)),
                label="idle_banter",
                speak_fn=_deliver,
                metadata={"topic_key": f"idle_banter:{person_id}"},
            ))
        except Exception as exc:
            _log.debug("idle banter governor submit failed: %s", exc)
        return True

    # LEGACY: speak inline; arm the cooldown only on an actual spoken line.
    completed = _deliver()
    if completed:
        _last_idle_banter_at = time.monotonic()
        _idle_banter_count += 1
    return completed


def _maybe_idle_outro() -> bool:
    """Say one tiny silence-aware line before an active session returns to IDLE."""
    global _idle_outro_spoken
    if _game_suppresses_conversation():
        return False
    if _idle_outro_spoken:
        return False
    if not bool(getattr(config, "IDLE_OUTRO_ENABLED", True)):
        return False
    # Don't say a goodbye to an empty room: with STARTUP_STATE_ACTIVE, an empty-room
    # boot starts ACTIVE and times out here with no conversation ever having happened.
    # Only outro if there was a real exchange OR someone is still present.
    if _session_exchange_count <= 0 and _primary_session_person_id() is None:
        return False
    if speech_queue.is_speaking() or output_gate.is_busy() or echo_cancel.is_suppressed():
        return False
    if _interrupted.is_set():
        return False
    pool = list(getattr(config, "IDLE_OUTRO_LINES", []) or [])
    if not pool:
        return False
    line = random.choice(pool)
    line = llm.clean_response_text(line or "")
    if not line:
        return False

    _log.info("[interaction] idle outro before IDLE: %r", line)
    completed = _speak_proactive(line, emotion="neutral", priority=1, label="idle_outro")
    if completed:
        _idle_outro_spoken = True
        conv_memory.add_to_transcript("Rex", line)
        conv_log.log_rex(line)
        _register_rex_utterance(line)
    return completed


def _record_being_discussed(
    *,
    text: str,
    label: str,
    sentiment: str,
    speaker_id: Optional[int],
    speaker_name: Optional[str],
) -> None:
    """Update world_state.social.being_discussed with this overheard mention.

    Increments mentions_in_window when the previous mention was within
    BEING_DISCUSSED_ACTIVE_WINDOW_SECS, otherwise resets the count.
    """
    try:
        social = world_state.get("social") or {}
        bd = social.get("being_discussed") or {}
        now_epoch = time.time()
        last_at = bd.get("last_mention_at")
        window = float(getattr(config, "BEING_DISCUSSED_ACTIVE_WINDOW_SECS", 30.0))
        rolling_window = float(
            getattr(config, "BEING_DISCUSSED_ROLLING_WINDOW_SECS", 60.0)
        )
        if last_at is not None and (now_epoch - float(last_at)) <= rolling_window:
            count = int(bd.get("mentions_in_window") or 0) + 1
        else:
            count = 1

        new_bd = {
            "last_mention_at": now_epoch,
            "last_snippet": text,
            "speaker_id": speaker_id,
            "speaker_name": speaker_name,
            "addressee_id": None,
            "label": label,
            "sentiment": sentiment,
            "mentions_in_window": count,
            # Reset chimed_in flag; it's per-active-window so a fresh discussion
            # earns its own chance for a chime-in.
            "chimed_in": False if (now_epoch - float(last_at or 0)) > window else bd.get("chimed_in", False),
        }
        social["being_discussed"] = new_bd
        world_state.update("social", social)
        _log.info(
            "[interaction] being_discussed updated — label=%s sentiment=%s mentions=%d snippet=%r",
            label, sentiment, count, text[:120],
        )
        # Log to conversation transcript so future turns have context.
        try:
            conv_memory.add_to_transcript(
                speaker_name or "Someone",
                f"(overheard, {label}) {text}",
            )
        except Exception:
            pass
    except Exception as exc:
        _log.debug("_record_being_discussed failed: %s", exc)


# ─────────────────────────────────────────────────────────────────────────────
# Identity enrollment helpers
# ─────────────────────────────────────────────────────────────────────────────


def _normalized_name_tokens(candidate: str) -> list[str]:
    return normalized_name_key(candidate).split()


def _is_non_name_candidate(candidate: str) -> bool:
    return normalize_person_name(candidate, allow_single=True) is None


def _normalize_name(candidate: str) -> Optional[str]:
    """
    Normalize a spoken/self-reported name candidate.
    Returns None when the candidate does not look like a usable name.
    """
    return normalize_person_name(candidate, allow_single=True)


def _first_name_or(value: Optional[str], fallback: str = "") -> str:
    parts = str(value or "").strip().split()
    return parts[0] if parts else fallback


def _identity_enrollment_ack(name: str) -> str:
    special = person_specials.special_intro_ack(name)
    if special:
        return special
    return f"Got it, {name}. Nice to meet you."


def _identity_reask_line() -> str:
    """A short in-character 'didn't catch the name, say it again' line."""
    lines = list(getattr(config, "IDENTITY_PROMPT_REASK_LINES", []) or [])
    if not lines:
        lines = ["Didn't catch that — just your name, one more time?"]
    return random.choice(lines)


def _special_intro_prompt(name: str) -> Optional[str]:
    special_context = person_specials.special_prompt_context(name)
    if not special_context:
        return None
    if person_specials.is_jt_volleyball_celebrity(name):
        special_instruction = (
            "acknowledge them by name as a major volleyball celebrity. Include "
            "one affectionate joke about getting old as a volleyball athlete, "
            "with bones or muscles as the absurd target."
        )
    elif person_specials.is_rex_creator(name):
        special_instruction = (
            "acknowledge Bret Benziger by name as Rex's creator and maker. Be "
            "warm, reverent, loyal, and still dryly Rex about being Bret's "
            "high-maintenance droid creation."
        )
    elif person_specials.is_pj_kings_celebrity(name):
        special_instruction = (
            "acknowledge PJ by name as Sacramento Kings royalty. Include one "
            "affectionate joke orbiting his Kings devotion, with the beam, a "
            "cowbell, or the color purple as the absurd target."
        )
    elif person_specials.is_galactic_hair_stylist(name):
        special_instruction = (
            "acknowledge them by name as one of the greatest hair stylists in "
            "the galactic quadrant. Include one affectionate joke about elite "
            "styling skills, legendary blowouts, emergency bang repair, or "
            "frizz surrendering."
        )
    else:
        special_instruction = "acknowledge them by name with the special hook."
    return (
        f"{special_context} You just learned this person's name is {name}. "
        f"In ONE short in-character Rex line, {special_instruction} "
        "No follow-up question."
    )


def _same_person_name(left: Optional[str], right: Optional[str]) -> bool:
    left_norm = _normalize_name(left or "")
    right_norm = _normalize_name(right or "")
    if not left_norm or not right_norm:
        return False
    return left_norm.lower() == right_norm.lower()


def _name_supported_by_user_text(name: Optional[str], text: str) -> bool:
    normalized_name = _normalize_name(name or "")
    if not normalized_name:
        return False
    text_key = normalized_name_key(text or "")
    name_key = normalized_name_key(normalized_name)
    if not text_key or not name_key:
        return False
    if re.search(rf"(?<!\w){re.escape(name_key)}(?!\w)", text_key):
        return True
    if looks_like_initials(normalized_name):
        return name_key.replace(" ", "") in text_key.replace(" ", "")
    return False


def _relationship_supported_by_user_text(
    relationship: Optional[str],
    text: str,
) -> bool:
    rel = _normalize_relationship_word(relationship)
    if not rel:
        return False
    text_plain = _plain_confirmation_text(text)
    if not text_plain:
        return False
    aliases = {
        rel,
        rel.replace("_", " "),
        rel.replace("_", "-"),
        rel.replace("_", ""),
    }
    for raw, normalized in _RELATIONSHIP_WORD_NORMALIZE.items():
        if normalized == rel:
            aliases.add(raw)
    for alias in aliases:
        alias_plain = _plain_confirmation_text(alias)
        if alias_plain and re.search(
            rf"(?<!\w){re.escape(alias_plain)}(?!\w)",
            text_plain,
        ):
            return True
    return False


def _filter_relationship_introduction_evidence(
    parsed: dict,
    user_text: str,
    speaker_name: Optional[str],
    *,
    source: str,
) -> tuple[Optional[str], Optional[str]]:
    name = parsed.get("name")
    relationship = parsed.get("relationship")
    name = name.strip() if isinstance(name, str) else None
    relationship = relationship.strip().lower() if isinstance(relationship, str) else None

    if name and not _name_supported_by_user_text(name, user_text):
        _log.warning(
            "[identity] rejected extracted newcomer name without transcript evidence "
            "source=%s name=%r text=%r parsed=%r",
            source,
            name,
            user_text,
            parsed,
        )
        name = None
    if name and speaker_name and (
        _same_person_name(name, speaker_name)
        or names_are_similar(name, speaker_name)
    ):
        _log.warning(
            "[identity] rejected extracted newcomer name matching speaker "
            "source=%s name=%r speaker=%r text=%r",
            source,
            name,
            speaker_name,
            user_text,
        )
        name = None
    if relationship and not _relationship_supported_by_user_text(
        relationship,
        user_text,
    ):
        _log.warning(
            "[identity] rejected extracted relationship without transcript evidence "
            "source=%s relationship=%r text=%r parsed=%r",
            source,
            relationship,
            user_text,
            parsed,
        )
        relationship = None
    return name, relationship


def _extract_self_identified_name(text: str) -> Optional[str]:
    normalized = (text or "").strip()
    if not normalized:
        return None
    for pattern in _SELF_NAME_PATTERNS:
        match = pattern.search(normalized)
        if match:
            candidate = (match.group(1) or "").strip()
            if _SELF_INTRO_NON_NAME_RE.search(candidate):
                return None
            return _normalize_name(candidate)
    return None


_IDENTITY_PROMPT_ECHO_RE = re.compile(
    r"\bwhat\s+name\s+should\s+i\s+(?:save|say|use|call|file)\s+for\s+you\b",
    re.IGNORECASE,
)

# "this is X" / "it's X" self-identification — ONLY trusted for a voice that is
# already being challenged as unknown (the global _SELF_NAME_PATTERNS deliberately
# exclude these: "this is amazing" would false-fire in open conversation). Extra
# guards here because a false hit would name a person row after an interjection.
_CHALLENGED_SELF_ID_RE = re.compile(r"\b(?:this is|it'?s)\s+(.+)$", re.IGNORECASE)
_CHALLENGED_SELF_ID_STOPWORDS = {
    "ridiculous", "amazing", "awesome", "great", "cool", "crazy", "insane", "wild",
    "hilarious", "perfect", "fine", "nice", "fun", "weird", "bad", "good", "stupid",
    "me", "us", "it", "true", "false", "wrong", "right", "over", "done", "nothing",
    "important", "urgent", "serious", "sarcasm", "a", "the", "so",
}


# "This is Exudica, A.K.A. Joy." / "I'm Joy, also known as Exudica" — the alias tail
# is not name-shaped ("A.K.A." fails the alphabetic-token check), so the whole
# self-introduction used to be rejected and the turn fell through to the
# third-party introduction flow (field log 2026-08-22-20-12: Joy answered the
# who's-that ask this way and Rex filed it as "JT introduced Exudica"). Split the
# tail off: the text before it is the self-introduction, the tail is an alias.
_AKA_ALIAS_RE = re.compile(
    r"\s*,?\s*(?:\(?\s*)?(?:a\.?\s?k\.?\s?a\.?|also\s+known\s+as|otherwise\s+known\s+as)"
    r"\s+([A-Za-z][A-Za-z'\-]*(?:\s+[A-Za-z][A-Za-z'\-]*){0,2})\s*\)?\s*[.!?]*\s*$",
    re.IGNORECASE,
)


def _split_aka_alias(text: str) -> tuple[str, Optional[str]]:
    """Return ``(text_without_alias_tail, alias)`` for "X, a.k.a. Y" phrasings.

    Only a trailing alias is recognized; the returned alias is normalized like a
    name. Texts without an alias tail come back unchanged with ``None``."""
    raw = (text or "").strip()
    if not raw:
        return raw, None
    m = _AKA_ALIAS_RE.search(raw)
    if not m:
        return raw, None
    alias = _normalize_name(m.group(1).strip())
    head = raw[: m.start()].strip()
    if not head or not alias:
        return raw, None
    if not head.endswith((".", "!", "?")):
        head += "."
    return head, alias


def _challenged_self_identified_name(text: str) -> Optional[str]:
    """Name from a self-identifying utterance by an ALREADY-CHALLENGED unknown voice
    ('This is JT', "it's Joy", 'I'm JT'). Field bug 2026-07-05-02-51: 'This is JT'
    armed the who's-that ask and Rex answered a self-introduction with
    'Nice to meet you, JT — who's speaking?'."""
    text, _alias = _split_aka_alias(text)
    name = _extract_self_identified_name(text)
    if name:
        return name
    m = _CHALLENGED_SELF_ID_RE.search((text or "").strip())
    if not m:
        return None
    candidate = m.group(1).strip().rstrip(".!?,")
    candidate = re.sub(r"\s+(?:speaking|talking)$", "", candidate, flags=re.IGNORECASE)
    if not candidate or _SELF_INTRO_NON_NAME_RE.search(candidate):
        return None
    if not _looks_like_name_chunk(candidate):
        return None
    tokens = candidate.split()
    if tokens[0].lower() in _CHALLENGED_SELF_ID_STOPWORDS:
        return None
    # Names arrive capitalized from ASR mid-utterance ("This is JT"); a lowercase
    # word after "this is" is almost always an adjective, not a name.
    if not tokens[0][0].isupper():
        return None
    return _normalize_name(candidate)


def _looks_like_name_chunk(chunk: str) -> bool:
    """True when chunk is 1-3 plain alphabetic name tokens (after trimming punct)."""
    tokens = (chunk or "").strip(" .!?").split()
    return bool(tokens) and len(tokens) <= 3 and all(
        re.fullmatch(r"[A-Za-z][A-Za-z'\-]*", t) for t in tokens
    )


def _prompted_bare_name_text(text: str) -> str:
    """
    Clean a bare reply to Rex's identity prompt.

    Whisper can capture the tail of Rex's own question before the user's answer.
    It also sometimes inserts commas inside a two-token name. In the prompted
    identity path, preserving both name-like chunks is safer than truncating at
    the first punctuation mark.
    """
    cleaned = " ".join((text or "").strip().split())
    if not cleaned:
        return ""
    if _IDENTITY_PROMPT_ECHO_RE.search(cleaned) and "?" in cleaned:
        tail = cleaned.rsplit("?", 1)[-1].strip()
        if tail:
            cleaned = tail
    if "," in cleaned:
        parts = [p.strip(" .!?") for p in cleaned.split(",") if p.strip(" .!?")]
        name_token = re.compile(r"[A-Za-z][A-Za-z'\-]*")
        if 1 < len(parts) <= 3 and all(name_token.fullmatch(p) for p in parts):
            # Comma split inside a multi-token name (e.g. "Mary, Jane").
            cleaned = " ".join(parts)
        elif len(parts) >= 2 and _looks_like_name_chunk(parts[-1]):
            # Leading echo/filler ahead of the real answer — e.g. Rex's own
            # "...save for you?" question tail bleeding into the mic as
            # "for you, Bret." Keep just the trailing name chunk.
            cleaned = parts[-1]
    return cleaned


_RELATIONSHIP_WORD_NORMALIZE = {
    "best friend": "best_friend",
    "co-worker": "coworker",
    "co worker": "coworker",
    "colleague": "coworker",
    "dad": "father",
    "mom": "mother",
    "brother": "sibling",
    "sister": "sibling",
}


def _normalize_relationship_word(value: Optional[str]) -> Optional[str]:
    rel = re.sub(r"\s+", " ", (value or "").strip().lower().replace("-", " "))
    if not rel:
        return None
    return _RELATIONSHIP_WORD_NORMALIZE.get(rel, rel).replace(" ", "_")


def _extract_self_relationship_to_engaged(
    text: str,
    engaged_name: Optional[str],
) -> Optional[str]:
    """
    Parse a self-intro aside like "my name is Jennifer, this is my brother Bret".

    The relationship is from the speaker toward the already-engaged person.
    Gendered sibling labels collapse to "sibling" so Jennifer is not stored as
    Bret's "brother" when she says Bret is her brother.
    """
    if not text or not engaged_name:
        return None
    engaged_first = _first_name_or(engaged_name).lower()
    if not engaged_first:
        return None
    engaged_full = str(engaged_name or "").strip().lower()
    rel_words = (
        "best friend|friend|father|dad|mother|mom|parent|coworker|co-worker|"
        "colleague|boss|supervisor|manager|aunt|uncle|partner|girlfriend|"
        "boyfriend|fiancee|fiance|wife|husband|spouse|sister|brother|sibling|"
        "cousin|roommate|neighbor|neighbour|son|daughter|child"
    )
    patterns = [
        rf"\b(?:this is|that'?s|that is)\s+my\s+(?P<rel>{rel_words})\s+(?P<name>[A-Za-z][A-Za-z'\-]*(?:\s+[A-Za-z][A-Za-z'\-]*){{0,2}})\b",
        rf"\b(?P<name>[A-Za-z][A-Za-z'\-]*(?:\s+[A-Za-z][A-Za-z'\-]*){{0,2}})\s+is\s+my\s+(?P<rel>{rel_words})\b",
    ]
    for pattern in patterns:
        match = re.search(pattern, text, re.IGNORECASE)
        if not match:
            continue
        candidate = _normalize_name(match.group("name") or "")
        candidate_lower = (candidate or "").lower()
        if not candidate_lower:
            continue
        if candidate_lower == engaged_full or _first_name_or(candidate_lower) == engaged_first:
            return _normalize_relationship_word(match.group("rel"))
    return None


def _extract_introduced_name(text: str, allow_bare_name: bool = False) -> Optional[str]:
    """Extract a self-introduced name from speech text."""
    normalized = text.strip()
    if not normalized:
        return None

    for pattern in _NAME_PATTERNS:
        m = pattern.search(normalized)
        if not m:
            continue
        return _normalize_name(m.group(1))

    # After Rex explicitly asks "who are you?", many people reply with only a name.
    if allow_bare_name:
        return _normalize_name(_prompted_bare_name_text(normalized))

    return None


def _prompted_name_reply_needs_confirmation(raw_text: str, name: str) -> bool:
    """Only suspicious prompted-name replies get a yes/no save confirmation."""
    if not name:
        return False
    text = (raw_text or "").strip()
    if not text:
        return False
    if "," in text:
        return True
    if "?" in text and _IDENTITY_PROMPT_ECHO_RE.search(text):
        return True
    return False


def _name_word_count(name: str) -> int:
    return len([part for part in (name or "").split() if part.strip()])


def _is_common_first_name_only(name: str) -> bool:
    if not bool(getattr(config, "COMMON_FIRST_NAME_LAST_NAME_DISAMBIGUATION_ENABLED", True)):
        return False
    normalized = _normalize_name(name or "")
    if not normalized or _name_word_count(normalized) != 1:
        return False
    common = {
        str(item).strip().lower()
        for item in getattr(config, "COMMON_FIRST_NAMES_REQUIRE_LAST_NAME", [])
        if str(item).strip()
    }
    return normalized.lower() in common


def _format_common_first_name_last_name_prompt(first_name: str) -> str:
    prompts = list(getattr(config, "COMMON_FIRST_NAME_LAST_NAME_PROMPTS", []) or [])
    if not prompts:
        prompts = [
            "{first}, huh? Last name too, please, so I keep you straight."
        ]
    try:
        template = random.choice(prompts)
        return template.format(first=first_name)
    except Exception:
        return f"{first_name}, how original. Last name too, please."


def _extract_last_name_reply(text: str, first_name: str) -> Optional[str]:
    normalized = (text or "").strip()
    if not normalized:
        return None

    patterns = [
        re.compile(r"\bmy\s+last\s+name\s+is\s+(.+)$", re.IGNORECASE),
        re.compile(r"\blast\s+name(?:'s| is)?\s+(.+)$", re.IGNORECASE),
        re.compile(r"\bsurname(?:'s| is)?\s+(.+)$", re.IGNORECASE),
        re.compile(r"\bit'?s\s+(.+)$", re.IGNORECASE),
    ]
    candidate = normalized
    for pattern in patterns:
        match = pattern.search(normalized)
        if match:
            candidate = match.group(1)
            break

    parsed = _normalize_name(candidate)
    if not parsed:
        return None

    parts = parsed.split()
    if len(parts) >= 2 and parts[0].lower() == first_name.lower():
        return " ".join(parts[1:])
    if len(parts) == 1 and parts[0].lower() != first_name.lower():
        return parts[0]
    return None


_EXPLICIT_LAST_NAME_LEADIN_RE = re.compile(
    r"\b(?:my\s+(?:last\s+name|surname)\s+is|last\s+name(?:'s| is)|"
    r"surname(?:'s| is))\b",
    re.IGNORECASE,
)


def _last_name_reply_was_explicit(text: str, first_name: str) -> bool:
    """True when the human clearly phrased the surname ('my last name is X',
    'Bret Benziger') rather than dropping a single bare token."""
    t = (text or "").strip()
    if _EXPLICIT_LAST_NAME_LEADIN_RE.search(t):
        return True
    parts = (_normalize_name(t) or "").split()
    return len(parts) >= 2 and parts[0].lower() == (first_name or "").lower()


def _last_name_token_is_unusual(token: str) -> bool:
    """A low-confidence-looking surname token — likely an ASR mangling
    ('Bat-tigger') that should be confirmed before a durable rename. A normal
    double-barrelled surname ('Smith-Jones') is NOT flagged; only a malformed
    hyphenation (a part that is too short or vowel-less, like 'Bat-tigger' whose
    'tigger' is fine but the join is implausible) or a vowel-less/too-short token
    is. 'y' counts as a vowel so 'Wynn'/'Lynch' pass."""
    t = (token or "").strip()
    if not t:
        return False
    vowels = "aeiouyAEIOUY"
    if len(t) < 2:
        return True
    if "-" in t.strip("-"):
        # Double-barrelled is fine only if every part is a plausible name part.
        parts = [p for p in t.split("-") if p]
        for p in parts:
            if len(p) < 2 or not any(c in vowels for c in p):
                return True
        # Two well-formed parts ("Smith-Jones") — not unusual; but ASR manglings
        # like "Bat-tigger" pass this check too, so also confirm any hyphenated
        # surname that wasn't explicitly phrased. Keep flagging hyphenated tokens
        # as worth a quick confirm (a one-beat check on a hyphen is harmless).
        return True
    if not any(c in vowels for c in t):
        return True
    return False


_LAST_NAME_REFUSAL_RE = re.compile(
    r"\b(?:"
    r"(?:i\s+)?(?:would\s+)?rather\s+not\s+(?:say|tell|share)|"
    r"(?:i\s+)?(?:do\s+not|don't|won't|will\s+not|am\s+not|ain't)\s+"
    r"(?:want\s+to\s+)?(?:say|tell|share|give)\s+(?:you\s+)?(?:my\s+)?(?:last\s+name|surname)|"
    r"(?:i'?m\s+)?not\s+(?:telling|sharing|giving)\s+(?:you\s+)?(?:my\s+)?(?:last\s+name|surname)|"
    r"you\s+(?:do\s+not|don't)\s+need\s+(?:to\s+know\s+)?(?:my\s+)?(?:last\s+name|surname)|"
    r"(?:my\s+)?(?:last\s+name|surname)\s+is\s+(?:private|personal|classified|none\s+of\s+your\s+business)|"
    r"(?:none\s+of\s+your\s+business|that'?s\s+private|that\s+is\s+private|classified)|"
    r"(?:first\s+name\s+only|no\s+last\s+name|skip\s+(?:it|the\s+last\s+name))|"
    r"(?:just|only)\s+{first}\b|"
    r"(?:call\s+me|you\s+can\s+call\s+me)\s+{first}\b"
    r")\b",
    re.IGNORECASE,
)
_LAST_NAME_IMPLICIT_REFUSAL_RE = re.compile(
    r"^\s*(?:"
    r"(?:no+|nope|nah|naw)(?:\s*[,!.]?\s*(?:thanks|thank\s+you)?)?$|"
    r"(?:(?:no+|nope|nah|naw)\s*[,!.]?\s*)?"
    r"(?:(?:i\s+)?(?:am\s+not|ain['’]?t)|i['’]?m\s+not)\s+"
    r"(?:going|gonna)\s+to\b|"
    r"(?:(?:no+|nope|nah|naw)\s*[,!.]?\s*)?"
    r"(?:i\s+)?(?:won['’]?t|will\s+not|do\s+not|don['’]?t)\s+"
    r"(?:(?:want|wanna)\s+to\s+)?(?:say|tell|share|give|do\s+that)\b"
    r")",
    re.IGNORECASE,
)


def _is_last_name_refusal(text: str, first_name: str) -> bool:
    cleaned = (text or "").strip()
    first = re.escape((first_name or "").strip())
    if not cleaned or not first:
        return False
    pattern = _LAST_NAME_REFUSAL_RE.pattern.format(first=first)
    return bool(
        re.search(pattern, cleaned, re.IGNORECASE)
        or _LAST_NAME_IMPLICIT_REFUSAL_RE.search(cleaned)
    )


def _common_first_name_context_fresh(ctx: Optional[dict]) -> bool:
    if not ctx:
        return False
    ttl = float(getattr(config, "COMMON_FIRST_NAME_LAST_NAME_WINDOW_SECS", 30.0))
    return (time.monotonic() - float(ctx.get("asked_at", 0.0))) <= max(1.0, ttl)


def _pending_existing_common_first_name_reply_target(
    text: str,
) -> Optional[tuple[int, str]]:
    """Return the pending known person when a short reply answers their prompt."""
    ctx = _pending_existing_common_first_name
    if not _common_first_name_context_fresh(ctx):
        return None

    first_name = str((ctx or {}).get("first_name") or "").strip()
    person_id = _safe_int((ctx or {}).get("person_id"))
    if person_id is None or not first_name:
        return None

    if _is_last_name_refusal(text, first_name):
        return person_id, first_name
    if _extract_last_name_reply(text, first_name):
        return person_id, first_name
    return None


_LAST_NAME_DECLINED_FACT_KEY = "last_name_declined"


def _remember_last_name_declined(person_id: Optional[int], first_name: str) -> None:
    if person_id is None:
        return
    try:
        facts_memory.add_fact(
            int(person_id),
            "identity",
            _LAST_NAME_DECLINED_FACT_KEY,
            f"{first_name} declined to share a last name",
            "identity_boundary",
            confidence=1.0,
        )
    except Exception as exc:
        _log.debug("last-name decline fact save failed: %s", exc)


def _has_declined_last_name(person_id: Optional[int]) -> bool:
    if person_id is None:
        return False
    try:
        facts = facts_memory.get_facts_by_category(int(person_id), "identity")
    except Exception as exc:
        _log.debug("last-name decline fact check failed: %s", exc)
        return False
    for fact in facts:
        if fact.get("key") != _LAST_NAME_DECLINED_FACT_KEY:
            continue
        value = str(fact.get("value") or "").strip().lower()
        if value:
            return True
    return False


def _known_person_needs_last_name(person_id: Optional[int], person_name: Optional[str]) -> bool:
    if person_id is None:
        return False
    if int(person_id) in _common_first_name_prompted_this_session:
        return False
    normalized = _normalize_name(person_name or "")
    if not normalized or _name_word_count(normalized) != 1:
        return False
    if looks_like_initials(normalized):
        return False
    return not _has_declined_last_name(int(person_id))


def _rename_candidate_is_name_cased(raw_text: str, name: str) -> bool:
    """True when the candidate actually appeared capitalized in the transcript.

    ASR writes a real claim with a capital ("Call me Bret.", "My name is Bret
    Benziger.") and an idiom in lowercase ("Call me later.", "Call me crazy, but
    I think it'll work.", "My name is on the list."). _normalize_name title-cases
    an all-lowercase tail, so by the time there IS a candidate the tell is gone —
    check the raw line instead. Same casing bar action_router
    ._plausible_thats_not_name_candidate applies to a "that's not X" tail (field
    2026-08-13), here on the branch that can DURABLY rename a person row or arm a
    person MERGE. An uncased transcript loses the rename on this fast path, but
    _handle_router_identity_name_correction re-enters with a normalized
    "call me <Name>" and still lands it — the smarter layer keeps the escape hatch.
    """
    first = next(iter((name or "").split()), "")
    if not first:
        return False
    match = re.search(rf"\b{re.escape(first)}\b", raw_text or "", re.IGNORECASE)
    return bool(match and match.group(0)[:1].isupper())


def _extract_name_update(text: str) -> Optional[str]:
    """Extract an explicit request/correction to rename the current person."""
    normalized = (text or "").strip()
    if not normalized or not _NAME_CORRECTION_RE.search(normalized):
        return None

    # When a preferred short name is supplied, use it over the formal name.
    name = None
    call_match = _CALL_ME_NAME_RE.search(normalized)
    if call_match:
        name = _normalize_name(call_match.group(1))
    if not name:
        name = _extract_introduced_name(normalized, allow_bare_name=False)
    if not name:
        return None

    if not _rename_candidate_is_name_cased(normalized, name):
        _log.info(
            "[identity] refusing uncapitalized rename candidate %r from %r",
            name,
            text,
        )
        return None
    return name


def _single_visible_person_identity() -> tuple[Optional[int], Optional[str]]:
    """Return the only visible known person identity, when unambiguous."""
    try:
        people = world_state.get("people") or []
    except Exception:
        return None, None

    identities: dict[int, Optional[str]] = {}
    for person in people:
        pid = person.get("person_db_id")
        if pid is None:
            continue
        try:
            pid_int = int(pid)
        except (TypeError, ValueError):
            continue
        identities[pid_int] = (
            person.get("face_id")
            or person.get("voice_id")
            or identities.get(pid_int)
        )

    if len(identities) != 1:
        return None, None
    pid, name = next(iter(identities.items()))
    return pid, name


def _resolve_name_update_target(
    person_id: Optional[int],
    person_name: Optional[str],
) -> tuple[Optional[int], Optional[str]]:
    """Resolve which known person row an explicit name correction should edit."""
    if person_id is not None:
        return int(person_id), person_name
    return _single_visible_person_identity()


def _refresh_world_state_person_name(person_id: int, name: str) -> None:
    """Keep live face/voice labels in sync after a memory rename."""
    try:
        def _apply_rename(people):
            changed = False
            for person in people:
                try:
                    pid = int(person.get("person_db_id"))
                except (TypeError, ValueError):
                    continue
                if pid != int(person_id):
                    continue
                person["face_id"] = name
                person["voice_id"] = name
                changed = True
            return people if changed else None

        world_state.mutate("people", _apply_rename)

        crowd = world_state.get("crowd") or {}
        if crowd.get("dominant_speaker"):
            crowd["dominant_speaker"] = name
            world_state.update("crowd", crowd)
    except Exception as exc:
        _log.debug("world_state name refresh failed: %s", exc)


def _plain_confirmation_text(text: str) -> str:
    return " ".join(re.sub(r"[^a-z0-9\s]", " ", (text or "").lower()).split())


def _memory_wipe_confirm_ttl() -> float:
    return float(getattr(config, "MEMORY_WIPE_CONFIRM_WINDOW_SECS", 30.0))


def _clear_pending_memory_wipe() -> None:
    global _pending_memory_wipe
    _pending_memory_wipe = None


def _pending_memory_wipe_expired(now: Optional[float] = None) -> bool:
    if _pending_memory_wipe is None:
        return True
    now = time.monotonic() if now is None else now
    asked_at = float(_pending_memory_wipe.get("asked_at") or 0.0)
    if (now - asked_at) <= _memory_wipe_confirm_ttl():
        return False
    _log.info("[memory] pending wipe confirmation expired: %s", _pending_memory_wipe)
    _clear_pending_memory_wipe()
    return True


def _memory_wipe_confirmation_phrase(scope: str) -> str:
    if scope != "all":
        return "yes forget me"
    code = str(getattr(config, "FULL_MEMORY_WIPE_ACCESS_CODE", "") or "").strip()
    return f"confirm full wipe {code}" if code else "confirm full wipe"


def _memory_wipe_confirmation_hint(scope: str) -> str:
    if scope != "all":
        return '"yes forget me"'
    code = str(getattr(config, "FULL_MEMORY_WIPE_ACCESS_CODE", "") or "").strip()
    if code:
        return '"confirm full wipe" followed by the full-wipe access code'
    return '"confirm full wipe"'


def _memory_wipe_confirmation_prefix(scope: str) -> str:
    return "confirm full wipe" if scope == "all" else "yes forget me"


def _arm_memory_wipe_confirmation(
    *,
    scope: str,
    person_id: Optional[int] = None,
    person_name: Optional[str] = None,
    requester_id: Optional[int] = None,
) -> None:
    global _pending_memory_wipe
    _pending_memory_wipe = {
        "scope": scope,
        "person_id": int(person_id) if person_id is not None else None,
        "person_name": person_name,
        "requester_id": int(requester_id) if requester_id is not None else None,
        "asked_at": time.monotonic(),
    }


def _resolve_forget_me_target(
    person_id: Optional[int],
    person_name: Optional[str],
) -> tuple[Optional[int], Optional[str]]:
    if person_id is not None:
        return int(person_id), person_name
    target_id, target_name = _single_visible_person_identity()
    if target_id is not None:
        return int(target_id), target_name
    return None, None


def _scrub_world_state_after_memory_wipe(
    *,
    person_id: Optional[int] = None,
    all_people: bool = False,
) -> None:
    """Drop deleted DB identity labels from the live WorldState snapshot."""
    try:
        def _apply_clear(people):
            changed = False
            for person in people:
                if all_people:
                    should_clear = True
                else:
                    try:
                        should_clear = int(person.get("person_db_id")) == int(person_id)
                    except (TypeError, ValueError):
                        should_clear = False
                if not should_clear:
                    continue
                person["person_db_id"] = None
                person["face_id"] = None
                person["voice_id"] = None
                changed = True
            return people if changed else None

        world_state.mutate("people", _apply_clear)

        crowd = world_state.get("crowd") or {}
        if all_people or crowd.get("dominant_speaker"):
            crowd["dominant_speaker"] = None
            world_state.update("crowd", crowd)

        social = world_state.get("social") or {}
        discussed = social.get("being_discussed")
        if isinstance(discussed, dict) and (
            all_people or discussed.get("speaker_id") == person_id
        ):
            discussed["speaker_id"] = None
            discussed["speaker_name"] = None
            discussed["addressee_id"] = None
            social["being_discussed"] = discussed
            world_state.update("social", social)
    except Exception as exc:
        _log.debug("world_state memory-wipe scrub failed: %s", exc)


def _clear_deleted_person_session_state(person_id: int) -> None:
    pid = int(person_id)
    _session_person_ids.discard(pid)
    _session_person_turn_counts.pop(pid, None)
    _session_warmth_signals.pop(pid, None)
    _session_forget_terms.pop(pid, None)
    _session_router_control_topics.pop(pid, None)
    _grief_flow_state.pop(pid, None)
    _voice_refreshed_this_session.discard(pid)
    _face_reveal_declined.discard(pid)
    _common_first_name_prompted_this_session.discard(pid)


def _clear_memory_related_pending_state() -> None:
    global _awaiting_followup_event, _pending_offscreen_identify
    global _pending_face_reveal_confirm, _pending_introduction
    global _pending_intro_followup, _pending_intro_voice_capture
    global _pending_common_first_name_identity, _pending_common_first_name_introduction
    global _pending_existing_common_first_name, _pending_identity_match_confirmation
    global _pending_last_name_confirm
    global _pending_prompted_name_confirmation
    global _identity_prompt_until

    _awaiting_followup_event = None
    _pending_post_greet_relationship[0] = None
    _pending_offscreen_identify = None
    _pending_face_reveal_confirm = None
    global _pending_dual_intro
    _pending_dual_intro = None
    _pending_introduction = None
    _pending_intro_followup = None
    _pending_intro_voice_capture = None
    _pending_common_first_name_identity = None
    _pending_common_first_name_introduction = None
    _pending_existing_common_first_name = None
    _pending_last_name_confirm = None
    _pending_identity_match_confirmation = None
    _pending_prompted_name_confirmation = None
    _identity_prompt_until = 0.0


def _confirmation_speaker_mismatch(
    pending: dict,
    person_id: Optional[int],
) -> bool:
    requester_id = pending.get("requester_id")
    target_id = pending.get("person_id")
    if person_id is None:
        return False
    try:
        current = int(person_id)
    except (TypeError, ValueError):
        return True
    if requester_id is not None and current != int(requester_id):
        return True
    if pending.get("scope") == "person" and target_id is not None and current != int(target_id):
        return True
    return False


def _handle_pending_memory_wipe_confirmation(
    text: str,
    person_id: Optional[int],
) -> Optional[str]:
    """Execute or cancel a pending destructive memory wipe confirmation."""
    if _pending_memory_wipe is None or _pending_memory_wipe_expired():
        return None

    pending = dict(_pending_memory_wipe)
    plain = _plain_confirmation_text(text)
    scope = str(pending.get("scope") or "")
    expected = _plain_confirmation_text(_memory_wipe_confirmation_phrase(scope))
    cancel_phrases = {
        "no",
        "nope",
        "cancel",
        "cancel that",
        "never mind",
        "nevermind",
        "abort",
        "stop",
        "do not",
        "dont",
    }

    if plain in cancel_phrases:
        _clear_pending_memory_wipe()
        resp = "Memory wipe canceled. My memory banks remain annoyingly intact."
        _speak_blocking(resp, emotion="neutral")
        return resp

    if plain != expected:
        _clear_pending_memory_wipe()
        if scope == "all" and plain.startswith(_memory_wipe_confirmation_prefix(scope)):
            resp = "Full memory wipe rejected. Access code missing or incorrect."
            _speak_blocking(resp, emotion="neutral")
            return resp
        return None

    if _confirmation_speaker_mismatch(pending, person_id):
        _clear_pending_memory_wipe()
        resp = (
            "Confirmation rejected. That did not come from the same identity. "
            "Destructive memory wipe canceled."
        )
        _speak_blocking(resp, emotion="neutral")
        return resp

    try:
        if scope == "person":
            target_id = pending.get("person_id")
            if target_id is None:
                raise RuntimeError("missing target person_id for memory wipe")
            people_memory.delete_person(int(target_id))
            _clear_deleted_person_session_state(int(target_id))
            _clear_memory_related_pending_state()
            _clear_anonymous_speaker_slots()
            _scrub_world_state_after_memory_wipe(person_id=int(target_id))
            try:
                consciousness.clear_engagement()
            except Exception:
                pass
            conv_memory.clear_transcript()
            name = _first_name_or(pending.get("person_name"))
            address = f"{name}. " if name else ""
            resp = (
                f"{address}Confirmed. I deleted your name, face, voice print, "
                "memories, and conversation records. Clean slate. Very dramatic."
            )
            _log.info("[memory] confirmed person wipe person_id=%s", target_id)
        elif scope == "all":
            people_memory.delete_all_people()
            _session_person_ids.clear()
            _session_person_turn_counts.clear()
            _session_warmth_signals.clear()
            _session_forget_terms.clear()
            _session_router_control_topics.clear()
            _clear_anonymous_speaker_slots()
            _grief_flow_state.clear()
            _voice_refreshed_this_session.clear()
            _face_reveal_declined.clear()
            _common_first_name_prompted_this_session.clear()
            _clear_memory_related_pending_state()
            _scrub_world_state_after_memory_wipe(all_people=True)
            try:
                consciousness.clear_engagement()
            except Exception:
                pass
            conv_memory.clear_transcript()
            resp = (
                "Confirmed. Every person record, face, voice print, relationship, "
                "and conversation memory is gone. My social life has been factory-reset."
            )
            _log.info("[memory] confirmed full people-memory wipe")
        else:
            raise RuntimeError(f"unknown memory wipe scope: {scope!r}")
    except Exception as exc:
        _log.error("[memory] memory wipe failed: %s", exc, exc_info=True)
        resp = "Memory wipe failed. Annoying, but safer than a half-erased brain."

    _clear_pending_memory_wipe()
    _speak_blocking(resp, emotion="neutral")
    return resp


# Slang vocatives / non-names a joking speaker offers as a "name" ("call me bro",
# "my last name is Broski"). Renaming the canonical record to these churns identity.
_NON_NAME_TOKENS = {
    "bro", "broski", "bruh", "brah", "dude", "man", "dawg", "fam", "homie",
    "homeboy", "bud", "buddy", "pal", "mate", "chief", "boss", "captain", "cap",
    "king", "queen", "legend", "sir", "maam", "madam", "yo", "hey", "nope",
    "nah", "idk", "dunno", "nobody", "nothing", "robot", "droid", "dj", "rex",
}

# Per-person time of the last CANONICAL rename — gate rapid churn (Wade->Bro->Broski).
_canonical_rename_at: dict[int, float] = {}


def _looks_like_non_name(name: str) -> bool:
    cleaned = (name or "").strip().lower()
    if not cleaned:
        return True
    tokens = re.findall(r"[a-z']+", cleaned)
    return bool(tokens) and all(t in _NON_NAME_TOKENS for t in tokens)


def _rename_recently(person_id: Optional[int]) -> bool:
    if person_id is None:
        return False
    cooldown = float(getattr(config, "IDENTITY_RENAME_COOLDOWN_SECS", 120.0) or 0.0)
    if cooldown <= 0:
        return False
    ts = _canonical_rename_at.get(int(person_id))
    return ts is not None and (time.monotonic() - ts) < cooldown


def _handle_name_update_request(
    text: str,
    person_id: Optional[int],
    person_name: Optional[str],
) -> Optional[str]:
    """Apply an explicit "call me / my name is / you got my name wrong" update."""
    new_name = _extract_name_update(text)
    if not new_name:
        return None

    # Tier 2: resist identity churn. A joking child renamed himself Wade->Bro->Broski
    # with each obeyed instantly. Reject obvious non-names, and require a cooldown
    # between canonical renames so a rapid joke chain can't keep mutating the record.
    if _looks_like_non_name(new_name):
        response = f"Nice try — '{new_name}' isn't going in the name field. What's your actual name?"
        _speak_blocking(response)
        return response

    target_id, old_name = _resolve_name_update_target(person_id, person_name)
    old_clean = (old_name or "").strip()
    try:
        existing = people_memory.find_person_by_name(new_name)
    except Exception:
        existing = None
    if existing is not None:
        existing_id = int(existing["id"])
        existing_name_clean = str(existing.get("name") or "").strip()
        if target_id is None:
            # No resolved speaker — fall back to the existing named row.
            target_id = existing_id
            old_name = existing.get("name")
            old_clean = (old_name or "").strip()
        elif existing_id != int(target_id):
            # The current voice/face-matched speaker is claiming to BE an existing
            # person. They are almost certainly the same human split across two rows
            # (e.g. a mis-registered duplicate that grabbed their voiceprint). Confirm
            # first, then MERGE the current row into the existing one on a "yes" —
            # never silently rename the wrong row or refuse outright.
            _log.info(
                "[identity] name correction implies merge: speaker target_id=%s "
                "claims existing_id=%s (%r) new=%r — asking to confirm merge text=%r",
                target_id, existing_id, existing_name_clean, new_name, text,
            )
            return _ask_name_merge_confirmation(
                survivor_id=existing_id,
                survivor_name=existing_name_clean or new_name,
                victim_id=int(target_id),
                victim_name=old_clean,
            )
        # else existing_id == target_id: the name already belongs to this speaker;
        # fall through to the normal rename path below.

    if target_id is None:
        _log.info("[identity] name update had no clear target text=%r", text)
        return None

    if old_clean.lower() == new_name.lower():
        response = f"Already got you as {new_name}."
        _speak_blocking(response)
        return response

    if _rename_recently(target_id):
        response = (
            f"Easy — you just changed your name. I'll keep you as "
            f"{old_clean or 'you are'} for now; tell me again in a bit if you mean it."
        )
        _speak_blocking(response)
        return response

    if not people_memory.rename_person(target_id, new_name):
        response = f"I couldn't safely rename that memory to {new_name}."
        _speak_blocking(response)
        return response

    try:
        _canonical_rename_at[int(target_id)] = time.monotonic()
    except Exception:
        pass
    _refresh_world_state_person_name(target_id, new_name)
    _log.info(
        "[identity] renamed person_id=%s old=%r new=%r text=%r",
        target_id,
        old_name,
        new_name,
        text,
    )
    response = _identity_enrollment_ack(new_name)
    if not person_specials.special_intro_ack(new_name):
        response = repair_moves.add_better_luck_line(f"Got it. I'll call you {new_name}.")
    _speak_blocking(response, emotion="happy")
    return response


def _ask_name_merge_confirmation(
    *,
    survivor_id: int,
    survivor_name: str,
    victim_id: int,
    victim_name: str,
) -> str:
    """Ask the speaker to confirm they ARE an existing person, then merge on "yes".

    Triggered when a voice/face-matched speaker (``victim_id`` — often a mis-labeled
    duplicate row) states a name that already belongs to a different person
    (``survivor_id``). They're almost certainly the same human, so on confirmation we
    merge the current row into the existing one and the voiceprints consolidate.
    """
    global _pending_name_merge_confirmation, _session_exchange_count
    _pending_name_merge_confirmation = {
        "survivor_id": int(survivor_id),
        "survivor_name": survivor_name,
        "victim_id": int(victim_id),
        "victim_name": victim_name,
        "asked_at": time.monotonic(),
    }
    prompt = (
        f"You mean to tell me you're the {survivor_name} I already know? "
        f"My circuits must be misfiring tonight. I'll update my silicon wafers."
    )
    _speak_blocking(prompt, emotion="curious", pre_beat_ms=100, post_beat_ms_override=200)
    conv_memory.add_to_transcript("Rex", prompt)
    conv_log.log_rex(prompt)
    _session_exchange_count += 1
    _register_rex_utterance(prompt)
    return prompt


def _handle_pending_name_merge_confirmation(
    text: str,
) -> tuple[Optional[str], Optional[int], Optional[str]]:
    """Consume yes/no after Rex asks whether the speaker is an existing person.

    On "yes" merge the current (mislabeled) row into the existing person so the
    voiceprint/history consolidate, returning (ack, survivor_id, survivor_name) so
    the turn loop re-points the live speaker. On "no" keep them separate. Returns
    (None, None, None) when there's no fresh pending merge or the reply is ambiguous.
    """
    global _pending_name_merge_confirmation

    ctx = _pending_name_merge_confirmation
    if not ctx:
        return None, None, None
    ttl = max(1.0, float(getattr(config, "COMMON_FIRST_NAME_LAST_NAME_WINDOW_SECS", 30.0)))
    if (time.monotonic() - float(ctx.get("asked_at", 0.0))) > ttl:
        _pending_name_merge_confirmation = None
        return None, None, None

    survivor_id = int(ctx.get("survivor_id"))
    survivor_name = str(ctx.get("survivor_name") or "").strip()
    victim_id = int(ctx.get("victim_id"))

    if _identity_confirmation_affirms(text):
        _pending_name_merge_confirmation = None
        try:
            merged = people_memory.merge_person(survivor_id, victim_id)
        except Exception as exc:
            _log.error(
                "[identity] merge_person failed survivor=%s victim=%s: %s",
                survivor_id, victim_id, exc,
            )
            merged = False
        if not merged:
            return (
                f"Hmm, my circuits jammed mid-merge — but you're still {survivor_name} in my book.",
                survivor_id,
                survivor_name,
            )
        _refresh_world_state_person_name(survivor_id, survivor_name)
        _log.info(
            "[identity] name-merge confirmed: merged victim=%s into survivor=%s(%r)",
            victim_id, survivor_id, survivor_name,
        )
        return (
            f"Re-synced. One {survivor_name}, the way it should be — wafers updated.",
            survivor_id,
            survivor_name,
        )

    if _identity_confirmation_declines(text):
        _pending_name_merge_confirmation = None
        return ("Huh — my mistake. Keeping you two as separate humans, then.", None, None)

    # Ambiguous (not a clear yes/no) — leave the question pending for this window.
    return None, None, None


_IDLE_DIRECT_MUSIC_RE = re.compile(
    r"\b(?:play|start\s+playing|put\s+on|throw\s+on|spin|queue|cue)\b"
    r".{0,60}\b(?:music|song|track|station|playlist|jazz|country|rock|pop|"
    r"classical|lo-fi|lofi|hip\s*hop)\b",
    re.IGNORECASE,
)
_BACKGROUND_CROSSTALK_RE = re.compile(
    r"\b(?:"
    # NOTE: 'came out' was here but is a false-positive magnet — "it came out so good"
    # (about a photo, said TO Rex) is normal conversation, not crosstalk. Removed.
    r"powered\s+off|channels?|camera|the\s+other\s+one|"
    r"when\s+you(?:'re|\s+are)\s+talking\s+to\s+it|"
    r"he\s+(?:is|was|has|had|knows)|she\s+(?:is|was|has|had|knows)|"
    r"they\s+(?:are|were|have|had|know)|"
    r"it\s+(?:is|was|has|had|knows)"
    r")\b",
    re.IGNORECASE,
)

# Device / UI / tech readouts someone reads aloud near the mic ("that's definitely
# 30 FPS", "1080p", "frame rate", "the latency") — not conversation aimed at Rex.
_DEVICE_READOUT_RE = re.compile(
    r"\b\d+\s*(?:fps|hz|hertz|ms|mhz|ghz|gb|mb|kb|fps|frames?|pixels?|nits|"
    r"degrees?|percent|dpi|ppi)\b"
    r"|\b\d{3,4}\s*[pk]\b"  # 1080p, 4k, 720p
    r"|\b(?:fps|resolution|frame\s?rate|refresh\s?rate|firmware|render(?:ing)?|"
    r"latency|buffer|codec|bitrate|aspect\s?ratio)\b",
    re.IGNORECASE,
)
# First/second-person pronouns — their presence means the line is plausibly a
# personal statement TO Rex, so a device-term match should NOT mark it as chatter.
_PERSONAL_PRONOUN_RE = re.compile(
    r"\b(?:i|i'?m|me|my|mine|myself|you|your|yours|we|our|rex|r3x|dj|droid)\b",
    re.IGNORECASE,
)


def _speech_is_directed_to_rex(text: str) -> bool:
    cleaned = (text or "").strip()
    if not cleaned:
        return False
    if _is_bare_wake_address(cleaned):
        return True
    try:
        if address_mode.contains_rex_keyword(cleaned):
            return True
    except Exception:
        pass
    if command_parser.parse(cleaned) is not None:
        return True
    if _IDLE_DIRECT_MUSIC_RE.search(cleaned):
        return True
    if _MUSIC_PLAY_REQUEST_PAT.search(cleaned) and re.search(
        r"\b(?:music|song|track|station|playlist)\b",
        cleaned,
        re.IGNORECASE,
    ):
        return True
    return False


def _looks_like_background_crosstalk(text: str) -> bool:
    cleaned = " ".join((text or "").strip().split())
    if not cleaned:
        return False
    if _speech_is_directed_to_rex(cleaned):
        return False
    if _extract_self_identified_name(cleaned):
        return False
    if _extract_introduced_name(cleaned, allow_bare_name=False):
        return False
    # Device / UI / tech readout with no first/second-person address — someone
    # narrating the screen ("that's definitely 30 FPS"), not talking to Rex.
    if _DEVICE_READOUT_RE.search(cleaned) and not _PERSONAL_PRONOUN_RE.search(cleaned):
        return True
    if "?" in cleaned:
        # Questions can be addressed to Rex without a wake word in an active
        # exchange. Keep them in the conversation path unless they are strongly
        # third-person/meta chatter about the system.
        return bool(_BACKGROUND_CROSSTALK_RE.search(cleaned))
    words = re.findall(r"[A-Za-z0-9']+", cleaned)
    if len(words) >= 5 and _BACKGROUND_CROSSTALK_RE.search(cleaned):
        return True
    if len(words) >= 10 and not re.search(r"\b(?:i|me|my|you|your|rex|r3x)\b", cleaned, re.I):
        return True
    return False


def _is_engaged_partner_turn(person_id: Optional[int], speaker_score: float) -> bool:
    """True when this utterance is from the confidently voice-matched person Rex is
    ALREADY in a 1-on-1 conversation with. Their lines must not be discarded as
    'background crosstalk' mid-exchange — that's how a real on-topic continuation
    ("it came out so good") got dropped. Crosstalk filtering still applies to
    unattributed / low-confidence / non-partner voices."""
    if person_id is None:
        return False
    try:
        if person_id != _primary_session_person_id():
            return False
    except Exception:
        return False
    if _session_exchange_count < 1:
        return False  # no active conversation yet — keep the crosstalk guard strict
    try:
        threshold = float(getattr(config, "SPEAKER_ID_SIMILARITY_THRESHOLD", 0.50))
    except (TypeError, ValueError):
        threshold = 0.50
    return float(speaker_score or 0.0) >= threshold


def _looks_like_direct_question_to_rex(text: str) -> bool:
    cleaned = (text or "").strip()
    if not cleaned or "?" not in cleaned:
        return False
    if _extract_self_identified_name(cleaned):
        return False
    if _extract_introduced_name(cleaned, allow_bare_name=False):
        return False
    return True


def _turn_should_defer_identity_prompts(text: str) -> bool:
    if not bool(getattr(config, "IDENTITY_PROMPT_DEFER_ON_DIRECT_TURN", True)):
        return False
    cleaned = (text or "").strip()
    if not cleaned:
        return False
    if _is_bare_wake_address(cleaned):
        return False
    if _extract_self_identified_name(cleaned):
        return False
    if _extract_introduced_name(cleaned, allow_bare_name=False):
        return False
    if command_parser.parse(cleaned) is not None:
        return True
    if _speech_is_directed_to_rex(cleaned):
        return True
    if _looks_like_direct_question_to_rex(cleaned):
        return True
    return False


def _utterance_invites_identity_question(text: str) -> bool:
    cleaned = (text or "").strip()
    if not cleaned:
        return False
    if _is_bare_wake_address(cleaned):
        return True
    if _extract_self_identified_name(cleaned):
        return True
    if _extract_introduced_name(cleaned, allow_bare_name=False):
        return True
    if _looks_like_direct_question_to_rex(cleaned):
        return False
    words = _word_count(cleaned)
    return bool(
        words <= 5
        and re.search(
            r"\b(?:hi|hello|hey|yo|rex|r3x|dee\s*jay|dj)\b",
            cleaned,
            re.IGNORECASE,
        )
    )


def _clear_pending_identity_prompts(reason: str) -> bool:
    global _identity_prompt_until, _pending_offscreen_identify, _pending_face_reveal_confirm
    global _pending_common_first_name_identity, _pending_common_first_name_introduction
    global _pending_existing_common_first_name, _pending_identity_match_confirmation
    global _pending_last_name_confirm
    global _pending_prompted_name_confirmation, _pending_introduction
    global _pending_intro_followup, _pending_intro_voice_capture
    global _pending_name_merge_confirmation, _identity_reask_count

    # A fresh intro voice-capture window is a passive listening slot, not a
    # question being deferred. When Rex just said "say hi so I can learn your
    # voice," the newcomer's first reply ("hi, what's your name?") looks like a
    # direct turn to Rex — but that reply IS the voice sample we want to enroll.
    # Preserve the window across the direct-turn deferral so the downstream
    # _handle_intro_voice_capture can still grab the print; it has its own TTL
    # and newcomer-vs-introducer gating and releases the turn if it isn't them.
    # Without this, a newcomer introduced off-camera never got a voice print and
    # their hello was misattributed to the introducer (live-logged 2026-06-15).
    preserve_intro_voice = reason == "direct_turn" and _intro_voice_capture_fresh(
        _pending_intro_voice_capture
    )

    changed = any(
        item is not None
        for item in (
            _pending_offscreen_identify,
            _pending_face_reveal_confirm,
            _pending_common_first_name_identity,
            _pending_common_first_name_introduction,
            _pending_existing_common_first_name,
            _pending_identity_match_confirmation,
            _pending_prompted_name_confirmation,
            _pending_introduction,
            _pending_intro_followup,
            None if preserve_intro_voice else _pending_intro_voice_capture,
        )
    ) or _identity_prompt_until > 0.0

    _identity_prompt_until = 0.0
    _identity_reask_count = 0
    _pending_offscreen_identify = None
    _pending_face_reveal_confirm = None
    _pending_common_first_name_identity = None
    _pending_common_first_name_introduction = None
    _pending_existing_common_first_name = None
    _pending_last_name_confirm = None
    _pending_identity_match_confirmation = None
    _pending_name_merge_confirmation = None
    _pending_prompted_name_confirmation = None
    _pending_introduction = None
    _pending_intro_followup = None
    if not preserve_intro_voice:
        _pending_intro_voice_capture = None
    try:
        changed = consciousness.clear_pending_identity_prompts(reason=reason) or changed
    except Exception as exc:
        _log.debug("clear pending consciousness identity prompts failed: %s", exc)
    if changed:
        _log.info("[identity] cleared pending identity prompts reason=%s", reason)
    return changed


def _should_ignore_idle_background_speech(
    *,
    from_idle_activation: bool,
    person_id: Optional[int],
    has_unknown_visible: bool,
    identity_prompt_active: bool,
    text_input: bool = False,
    text: str,
) -> bool:
    """Ignore no-wake IDLE activations that sound like off-camera background speech."""
    if not from_idle_activation:
        return False
    if text_input:
        return False
    if has_unknown_visible or identity_prompt_active:
        return False
    cleaned = (text or "").strip()
    if not cleaned:
        return False
    if _speech_is_directed_to_rex(cleaned):
        return False
    if person_id is not None:
        if _known_person_visible_recently(person_id):
            return False
        if _looks_like_background_crosstalk(cleaned):
            return True
        words = re.findall(r"[A-Za-z0-9']+", cleaned)
        return len(words) >= 5
    try:
        wake_ready = bool(wake_word.is_ready())
    except Exception:
        wake_ready = True
    if not wake_ready and _PLAIN_IDLE_GREETING_PAT.match(cleaned):
        return False
    return True


def _pending_question_recent_attribution(
    *,
    person_id: Optional[int],
    person_name: Optional[str],
    recent_engagement: Optional[dict],
    raw_best_id: Optional[int],
    speaker_score: float,
    text: str,
) -> tuple[Optional[int], Optional[str], bool]:
    """
    Attribute the next answer to the recently engaged person Rex just questioned.

    This prevents a panned-away camera or weak voice score from derailing a direct
    answer into the off-camera-unknown identity flow.
    """
    if person_id is not None:
        return person_id, person_name, False
    if not recent_engagement:
        return person_id, person_name, False
    if command_parser.parse(text) is not None:
        return person_id, person_name, False

    recent_id = _safe_int(recent_engagement.get("person_id"))
    if recent_id is None:
        return person_id, person_name, False
    pending = _latest_pending_question(recent_id)
    thread_question = ""
    try:
        thread_question = str(
            (topic_thread.snapshot() or {}).get("unresolved_question") or ""
        ).strip()
    except Exception:
        thread_question = ""
    if not pending and not thread_question:
        return person_id, person_name, False

    floor = float(getattr(config, "SPEAKER_ID_PENDING_QA_RECENT_FLOOR", 0.35))
    raw_id = _safe_int(raw_best_id)
    raw_matches_recent = raw_id == recent_id
    no_voice_candidate = raw_id is None
    # A brief false-positive unknown face should not steal the answer to a
    # question Rex just asked the engaged person. If the voice model's top
    # candidate is the asked person above the low pending-QA floor, direct
    # question continuity wins. Without matching voice evidence, unknown faces
    # still block attribution so real newcomers can answer for themselves.
    try:
        unknown_present = _has_unknown_visible_or_recent()
    except Exception:
        unknown_present = True
    if unknown_present and not (raw_matches_recent and speaker_score >= floor):
        return person_id, person_name, False

    if not no_voice_candidate and not (raw_matches_recent and speaker_score >= floor):
        return person_id, person_name, False

    resolved_name = str(
        recent_engagement.get("name")
        or recent_engagement.get("face_id")
        or recent_engagement.get("voice_id")
        or ""
    ).strip() or person_name
    _log.info(
        "[interaction] person resolution: pending-question continuity — "
        "person_id=%s name=%r voice_score=%.3f raw_best=%s source=%s",
        recent_id,
        resolved_name,
        speaker_score,
        raw_best_id,
        "durable_qa" if pending else "topic_thread",
    )
    return recent_id, resolved_name, True


def _single_visible_engaged_continuity_floor(
    *,
    ws_pid: Optional[int],
    raw_best_id: Optional[int],
) -> float:
    broad_floor = float(
        getattr(config, "SPEAKER_ID_SINGLE_VISIBLE_CONTINUITY_FLOOR", 0.45)
    )
    if _safe_int(raw_best_id) == _safe_int(ws_pid):
        match_floor = float(
            getattr(
                config,
                "SPEAKER_ID_SINGLE_VISIBLE_MATCH_FLOOR",
                broad_floor,
            )
        )
        return min(broad_floor, match_floor)
    return broad_floor


def _extract_offscreen_identify_reply(
    text: str,
    speaker_name: str,
) -> tuple[Optional[str], Optional[str]]:
    """
    Parse the engaged person's answer to "who just chimed in?"

    In this slot a bare one-word reply is usually a name. Trust that context
    before letting words like "Joy" drift into ordinary sentiment/content.
    """
    # "This is Exudica, A.K.A. Joy." — parse the primary name; the alias is filed
    # separately by the caller (the extractor otherwise answered "Joy", which
    # matched no person row while "Exudica" was already on file).
    text, _alias = _split_aka_alias(text)
    try:
        parsed = llm.extract_relationship_introduction(text, speaker_name)
    except Exception as exc:
        _log.debug("offscreen identify extract error: %s", exc)
        parsed = {"name": None, "relationship": None}

    intro_name = parsed.get("name")
    rel_label = parsed.get("relationship")
    if not intro_name:
        if "?" in (text or ""):
            return None, rel_label
        intro_name = _extract_introduced_name(text, allow_bare_name=True)
    if intro_name and _is_non_name_candidate(intro_name):
        intro_name = None
    return intro_name, rel_label


_THIRD_PERSON_PRESENCE_ANNOUNCEMENT_RE = re.compile(
    r"^\s*[A-Za-z][A-Za-z'\-]*(?:\s+[A-Za-z][A-Za-z'\-]*){0,2}\s*,?\s+"
    r"(?:(?:is|are|was|were)\s+(?:here|there|around|with\b|talking\b)|"
    r"(?:'s|’s)\s+(?:here|there|around|with\b|talking\b))",
    re.IGNORECASE,
)


def _looks_like_direct_offscreen_identity_answer(
    text: str,
    intro_name: Optional[str],
) -> bool:
    """
    True when an off-camera unknown appears to answer Rex's "who was that?"
    prompt directly with their own name.

    The engaged person may answer with a fuller phrase, but the unknown speaker
    commonly replies with just "JT" or "I'm Joy." Keep this narrow so an
    unrelated off-camera sentence does not get silently enrolled as a person.
    """
    if not intro_name:
        return False
    cleaned = (text or "").strip()
    if not cleaned or "?" in cleaned:
        return False
    if _THIRD_PERSON_PRESENCE_ANNOUNCEMENT_RE.match(cleaned):
        return False
    if _extract_introduced_name(cleaned, allow_bare_name=False):
        return True
    named_phrase = re.search(
        r"\b(?:it(?:'|’)?s|it\s+is|that(?:'|’)?s|that\s+is|"
        r"(?:his|her|their)\s+name\s+is|name(?:'|’)?s)\s+(.+)$",
        cleaned,
        re.IGNORECASE,
    )
    if named_phrase and _same_person_name(named_phrase.group(1), intro_name):
        return True
    return (
        _same_person_name(cleaned, intro_name)
        and _name_word_count(intro_name) <= _NAME_MAX_WORDS
    )


def _is_offscreen_identify_cancel_reply(text: str) -> bool:
    plain = _plain_confirmation_text(text)
    return plain in {
        "cancel",
        "cancel that",
        "drop it",
        "forget it",
        "forget that",
        "ignore it",
        "ignore that",
        "never mind",
        "never mind that",
        "nevermind",
        "nevermind that",
        "skip it",
        "stop",
    }


def _offscreen_identity_enrollment_audio(
    pending_audio: object,
    reply_audio: Optional[np.ndarray],
    *,
    include_reply_audio: bool,
) -> np.ndarray:
    arrays: list[np.ndarray] = []
    if isinstance(pending_audio, np.ndarray) and len(pending_audio) > 0:
        arrays.append(pending_audio)
    if (
        include_reply_audio
        and isinstance(reply_audio, np.ndarray)
        and len(reply_audio) > 0
    ):
        arrays.append(reply_audio)
    if len(arrays) > 1:
        return np.concatenate(arrays)
    if arrays:
        return arrays[0]
    return np.zeros(1, dtype=np.float32)


def _audio_duration_secs(audio_array: Optional[np.ndarray]) -> float:
    if not isinstance(audio_array, np.ndarray) or len(audio_array) <= 0:
        return 0.0
    try:
        rate = float(getattr(config, "AUDIO_SAMPLE_RATE", 16000) or 16000)
    except Exception:
        rate = 16000.0
    if rate <= 0:
        return 0.0
    return float(len(audio_array)) / rate


# A transcript made ENTIRELY of laughter tokens. Whisper/Qwen render a laugh as runs of
# ha/he/ah plus the odd "lol"; anything with real words in it is a normal turn and must
# not qualify (a laugh followed by speech is speech the embedder CAN score).
_LAUGH_TOKEN_RE = re.compile(
    r"^(?:h[aeu](?:h?[aeu])*h?|(?:ah)+|(?:eh)+|lol|lmao|hehe|haha|heh|hah|ha)$",
    re.IGNORECASE,
)


def _is_non_speech_vocalization(transcript_text: Optional[str]) -> bool:
    """Whether the whole turn is laughter rather than speech.

    Laughter is acoustically unlike the speech an ECAPA print is built from, so its
    score carries no identity information — see the decision branch that consumes this.
    """
    if not bool(getattr(config, "LAUGH_NOT_A_STRANGER_ENABLED", True)):
        return False
    cleaned = re.sub(r"[^\w\s]", " ", str(transcript_text or "")).strip()
    if not cleaned:
        return False
    tokens = cleaned.split()
    if not tokens or len(tokens) > 6:
        return False
    return all(_LAUGH_TOKEN_RE.match(tok) for tok in tokens)


def _is_short_utterance(
    audio_array: Optional[np.ndarray],
    transcript_text: Optional[str] = None,
) -> bool:
    """Whether a turn is too short for the embedder to score reliably.

    Duration alone is unreliable: the captured buffer carries VAD pre/post-roll
    silence, so a genuine 2-word reply ("It's wine", ~0.8s of speech) can measure
    >2s of buffer and slip past the seconds threshold. Word count reflects actual
    SPEECH content and is padding-proof, so a few-word turn is always treated as
    short — that's exactly the case where a low voice score is uninformative and
    the sole visible known face should anchor identity. Either signal qualifies.
    Field 2026-07-23: Bret's "It's wine" scored 0.301, buffer measured >2s, so it
    was NOT flagged short and the robot gaze-searched a phantom off-camera speaker.
    """
    if _audio_duration_secs(audio_array) < float(
        getattr(config, "SPEAKER_ID_SHORT_UTTERANCE_SECS", 2.0)
    ):
        return True
    max_words = int(getattr(config, "SPEAKER_ID_SHORT_UTTERANCE_WORDS", 3) or 0)
    if max_words > 0 and transcript_text and _word_count(transcript_text) <= max_words:
        return True
    return False


def _voice_enrollment_sample_allowed(
    audio_array: Optional[np.ndarray],
    *,
    transcript_text: str = "",
    confirmed: bool = False,
) -> tuple[bool, str]:
    min_secs = float(getattr(config, "IDENTITY_VOICE_ENROLL_MIN_AUDIO_SECS", 1.2) or 0.0)
    min_words = int(getattr(config, "IDENTITY_VOICE_ENROLL_MIN_WORDS", 2) or 0)
    duration = _audio_duration_secs(audio_array)
    if duration < min_secs:
        return False, f"audio_too_short:{duration:.2f}s<{min_secs:.2f}s"
    if not confirmed and min_words > 0 and transcript_text:
        words = _word_count(transcript_text)
        if words < min_words:
            return False, f"too_few_words:{words}<{min_words}"
    return True, "ok"


def _safe_enroll_voice(
    person_id: int,
    audio_array: Optional[np.ndarray],
    *,
    transcript_text: str = "",
    source: str,
    confirmed: bool = False,
) -> bool:
    allowed, reason = _voice_enrollment_sample_allowed(
        audio_array,
        transcript_text=transcript_text,
        confirmed=confirmed,
    )
    if not allowed:
        _log.info(
            "[identity] skipped voice enrollment person_id=%s source=%s reason=%s",
            person_id,
            source,
            reason,
        )
        return False
    try:
        enrolled = bool(speaker_id.enroll_voice(person_id, audio_array))
    except Exception as exc:
        _log.warning("voice enrollment failed for person_id=%s source=%s: %s", person_id, source, exc)
        return False
    if enrolled:
        # Enrollment is ground truth: this exact audio was just saved as the
        # person's print, so their voice has live credibility NOW. Without this
        # anchor, a fresh single-sample print scores marginal (~0.5) on the very
        # next turn and the who's-that challenge fires seconds after the person
        # said who they are (live-logged 2026-07-07: enrolled at 10:55:17,
        # challenged "who's talking?" at 10:56:05).
        pid = _safe_int(person_id)
        if pid is not None:
            _last_confident_voice_at[pid] = time.monotonic()
    return enrolled


def _handle_pending_offscreen_identify_reply(
    text: str,
    *,
    person_id: Optional[int],
    person_name: Optional[str],
    audio_array: Optional[np.ndarray],
    anonymous_speaker_label: Optional[str],
) -> tuple[bool, Optional[str]]:
    """
    Consume a reply to Rex's off-camera "who was that?" question.

    Returns (consumed, response_text). response_text is present when Rex spoke
    an acknowledgement. The answer may come from the engaged person or directly
    from the off-camera unknown with a short self-name reply.
    """
    global _pending_offscreen_identify, _session_exchange_count

    pending = _pending_offscreen_identify
    if pending is None:
        return False, None

    now_mono = time.monotonic()
    ttl = float(getattr(config, "OFFSCREEN_IDENTIFY_WINDOW_SECS", 30.0))
    if (now_mono - pending["asked_at"]) > ttl:
        _log.info("[interaction] off-camera identify window expired — clearing")
        _pending_offscreen_identify = None
        return False, None

    prior_engaged_id = pending.get("prior_engaged_id")
    prior_engaged_name = pending.get("prior_engaged_name") or "friend"
    from_engaged_person = (
        person_id is not None
        and prior_engaged_id is not None
        and int(person_id) == int(prior_engaged_id)
    )

    if _is_offscreen_identify_cancel_reply(text):
        _pending_offscreen_identify = None
        ack_text = "Never mind. Bad sensor read on my end."
        if from_engaged_person:
            completed = _speak_blocking(
                ack_text,
                emotion="neutral",
                pre_beat_ms=100,
                post_beat_ms_override=200,
            )
            conv_memory.add_to_transcript("Rex", ack_text)
            conv_log.log_rex(ack_text)
            _session_exchange_count += 1
            _register_rex_utterance(ack_text)
            repair_moves.mark_handled("misunderstood")
            _log.info(
                "[interaction] off-camera identify cancelled by engaged person "
                "completed=%s text=%r",
                completed,
                text,
            )
            return True, ack_text
        _log.info("[interaction] off-camera identify cancelled text=%r", text)
        return True, None

    intro_name, rel_label = _extract_offscreen_identify_reply(
        text,
        person_name or prior_engaged_name,
    )
    intro_name, rel_label = _filter_relationship_introduction_evidence(
        {"name": intro_name, "relationship": rel_label},
        text,
        person_name or prior_engaged_name,
        source="offscreen_identify",
    )
    from_unknown_self_answer = (
        person_id is None
        and _looks_like_direct_offscreen_identity_answer(text, intro_name)
    )
    if not from_engaged_person and not from_unknown_self_answer:
        return False, None

    if not intro_name:
        # No name in this reply. Drop the pending state so Rex doesn't badger;
        # if the off-camera voice speaks again we'll re-ask.
        _log.info(
            "[interaction] off-camera reply had no name — clearing pending: %r",
            text,
        )
        _pending_offscreen_identify = None
        repair = repair_moves.detect(text) if from_engaged_person else None
        repair_kind = str((repair or {}).get("kind") or "")
        if repair_kind in {
            "clarify",
            "misunderstood",
            "wrong_person",
            "factual",
            "bare_negation",
        }:
            ack_text = "Never mind. Bad sensor read on my end."
            completed = _speak_blocking(
                ack_text,
                emotion="neutral",
                pre_beat_ms=100,
                post_beat_ms_override=200,
            )
            conv_memory.add_to_transcript("Rex", ack_text)
            conv_log.log_rex(ack_text)
            _session_exchange_count += 1
            _register_rex_utterance(ack_text)
            repair_moves.mark_handled(repair_kind)
            _log.info(
                "[interaction] off-camera identify repaired after confused reply "
                "kind=%s completed=%s",
                repair_kind,
                completed,
            )
            return True, ack_text
        return True, None

    # A name that is a near-miss of someone Rex already knows ("Bret Bender"
    # for Bret Benziger, garbled by an eating-voice ASR turn) must not silently
    # fail enrollment — ask the did-you-mean question instead. The existing
    # confirmation flow then aliases + re-enrolls on "yes" or forks a genuinely
    # new person on "no". first_name matches stay frictionless (reused below).
    try:
        near_miss = people_memory.find_potential_person_match(intro_name)
    except Exception:
        near_miss = None
    if (
        near_miss
        and near_miss.get("match_type") in {"fuzzy", "fuzzy_first_name"}
        and isinstance(audio_array, np.ndarray)
        and _maybe_ask_identity_match_confirmation(
            intro_name,
            audio_array,
            anonymous_speaker_label=(
                pending.get("anonymous_speaker_label") or anonymous_speaker_label
            ),
            source="offscreen_identify",
        )
    ):
        _pending_offscreen_identify = None
        return True, None

    new_pid = None
    try:
        new_pid, created = people_memory.find_or_create_person(intro_name)
        if new_pid is not None:
            # A human just CONFIRMED who this voice is — the strongest credibility
            # signal there is. Anchor voice continuity so their next marginal-scoring
            # turns aren't immediately re-challenged.
            _last_confident_voice_at[int(new_pid)] = time.monotonic()
            enroll_audio = _offscreen_identity_enrollment_audio(
                pending.get("audio"),
                audio_array,
                include_reply_audio=from_unknown_self_answer,
            )
            # The words check must see everything the AUDIO contains: the held
            # overheard utterance + the reply. Passing only the reply ("JT", one
            # word) rejected the enrollment as too_few_words while the audio was
            # actually "This is JT" + "JT" (field log 2026-07-05-02-51 — JT ended
            # the session with 0 voice rows despite answering the ask).
            enroll_text = " ".join(
                part for part in (str(pending.get("overheard_text") or ""), text)
                if part
            ).strip()
            # CLAIM VERIFICATION: when the answered name is an EXISTING person with
            # established voice prints, the held clip must actually SOUND like them
            # before it may touch their prints. A claimed name is social testimony,
            # not biometric proof — field 2026-07-23 20:12: a guest joked "obviously
            # me, Bret" to the who's-that ask and HER voice clip (0.516 vs Bret's
            # real prints) was enrolled onto Bret, poisoning his print set. A brand
            # new person (created=True) or a print-less record still bootstraps.
            claim_ok = True
            if not created and enroll_audio is not None:
                try:
                    floor = float(getattr(
                        config, "OFFSCREEN_IDENTIFY_CLAIM_VERIFY_FLOOR", 0.55))
                    ranked = speaker_id.rank_speakers(enroll_audio)
                    claimed = next(
                        (r for r in ranked if int(r[0]) == int(new_pid)), None)
                    if claimed is not None and float(claimed[2]) < floor:
                        claim_ok = False
                        _log.info(
                            "[interaction] off-camera identify: claimed name %r is an "
                            "existing person but the held clip scores %.3f against "
                            "their prints (< %.2f) — NOT enrolling (attribution only)",
                            intro_name, float(claimed[2]), floor,
                        )
                except Exception as exc:
                    _log.debug("offscreen claim verification failed open: %s", exc)
            if claim_ok:
                _safe_enroll_voice(
                    new_pid,
                    enroll_audio,
                    transcript_text=enroll_text,
                    source="offscreen_identify",
                    confirmed=from_engaged_person,
                )
            first_inc = config.FAMILIARITY_INCREMENTS.get("first_enrollment", 0.0)
            if created and first_inc > 0:
                people_memory.update_familiarity(new_pid, first_inc)

            if _has_unknown_visible_person():
                try:
                    from vision import camera as _cam_mod
                    from vision import face as _face_mod
                    frame = _cam_mod.capture_still()
                    if frame is not None:
                        if _face_mod.enroll_unknown_face(new_pid, frame):
                            threading.Thread(
                                target=_face_mod.update_appearance,
                                args=(new_pid, frame.copy()),
                                daemon=True,
                                name=f"appearance-enroll-{new_pid}",
                            ).start()
                except Exception as exc:
                    _log.warning(
                        "off-camera visible face enroll failed: %s",
                        exc,
                    )
            _bind_world_state_identity(new_pid, intro_name)
            _, aka_alias = _split_aka_alias(text)
            if aka_alias and not _same_person_name(aka_alias, intro_name):
                try:
                    if people_memory.add_alias(new_pid, aka_alias, source="self_introduction"):
                        _log.info(
                            "[interaction] off-camera speaker %r also known as %r — alias filed",
                            intro_name, aka_alias,
                        )
                except Exception as exc:
                    _log.debug("off-camera alias save failed: %s", exc)
            retired_labels = {
                pending.get("anonymous_speaker_label"),
                anonymous_speaker_label,
            }
            for label in retired_labels:
                _retire_anonymous_speaker_slot(
                    label,
                    person_id=new_pid,
                    person_name=intro_name,
                )

            if rel_label and prior_engaged_id:
                try:
                    from memory import social as _social
                    _social.save_relationship(
                        from_person_id=prior_engaged_id,
                        to_person_id=new_pid,
                        relationship=rel_label,
                        described_by=prior_engaged_id,
                    )
                except Exception as exc:
                    _log.warning("off-camera relationship save failed: %s", exc)

            _log.info(
                "[interaction] off-camera speaker enrolled as %s (person_id=%s)%s",
                intro_name, new_pid,
                f" with relationship {rel_label!r}" if rel_label else "",
            )
            _episodic_person_enrolled(new_pid, intro_name, created=created)
    except Exception as exc:
        _log.error("off-camera identify enrollment failed: %s", exc)

    # Consume whether or not we succeeded — don't retry on the next turn.
    _pending_offscreen_identify = None
    if new_pid is None:
        return True, None

    ack_text = f"Got it: {intro_name}. Welcome to the frequency."
    # Celebrity personas (JT the volleyball legend, Joy/Exudica, the creator) get
    # their authored intro bit — identifying via the who's-that ask must land the
    # same routine a face-recognized arrival would (field gap 2026-07-05: JT was
    # named through this flow and got a generic "welcome aboard" instead).
    special_ack = None
    try:
        from intelligence import person_specials as _specials
        special_ack = _specials.special_intro_ack(intro_name)
    except Exception:
        special_ack = None
    if special_ack:
        ack_text = special_ack
        try:
            if _specials.is_jt_volleyball_celebrity(intro_name) and new_pid is not None:
                consciousness.mark_jt_volleyball_greeted(int(new_pid))
            if _specials.is_pj_kings_celebrity(intro_name) and new_pid is not None:
                consciousness.mark_pj_kings_greeted(int(new_pid))
        except Exception:
            pass
    else:
        try:
            introducer_name = _first_name_or(person_name or prior_engaged_name, "friend")
            ack_text = llm.get_response(
                f"You just learned the nearby/off-camera person's "
                f"name is {intro_name}. {introducer_name} introduced "
                f"or named them. In ONE very short in-character Rex line, "
                f"acknowledge {intro_name} by name and welcome "
                f"them. Address {intro_name}, not {introducer_name}. "
                f"Do not ask another question."
            ) or ack_text
        except Exception as exc:
            _log.debug("off-camera identify ack generation failed: %s", exc)
    _speak_blocking(ack_text)
    conv_memory.add_to_transcript("Rex", ack_text)
    conv_log.log_rex(ack_text)
    _session_exchange_count += 1
    _register_rex_utterance(ack_text)
    return True, ack_text


def _capture_unknown_face_candidates() -> list[dict]:
    """Snapshot the camera and return currently-visible UNKNOWN faces as
    [{"encoding", "x"}] (x = face-box center; Rex's left = smaller x). Same capture
    the face-reveal lateral ask uses. Empty list on any failure."""
    try:
        from vision import camera as _cam_mod
        from vision import face as _face_mod
        frame = _cam_mod.get_frame()
        if frame is None:
            return []
        out: list[dict] = []
        for det in _face_mod.detect_faces(frame):
            if _face_mod.identify_face(det["encoding"]) is None:
                x, _y, w, _h = det["bounding_box"]
                out.append({"encoding": det["encoding"], "x": x + w // 2})
        return out
    except Exception as exc:
        _log.debug("dual-intro face capture error: %s", exc)
        return []


def _ask_dual_unknown_intro(text: str, faces: list[dict]) -> bool:
    """TWO unknown faces + an unrecognized voice: ask positionally, left first.
    Returns True when the ask was spoken and the pending state armed."""
    global _pending_dual_intro, _dual_intro_cooldown_until, _session_exchange_count
    now = time.monotonic()
    if now < _dual_intro_cooldown_until:
        return False
    ordered = sorted(faces, key=lambda f: f["x"])   # Rex's left first (smaller x)
    ask_text = None
    try:
        ask_text = llm.get_response(
            f"TWO people you don't recognize are on camera and one of them just "
            f"said: '{text}'. In ONE short in-character Rex line: say you don't "
            f"know either of them yet, and ask the person on YOUR LEFT for their "
            f"name FIRST (you'll get to the other one next). Warm, curious. "
            f"Example: 'Two mystery organics at once — I love it. You on my left, "
            f"what do I call you?' One line ending in a question mark."
        )
    except Exception as exc:
        _log.debug("dual-intro ask generation failed: %s", exc)
    if not ask_text:
        ask_text = "Two faces I don't know yet! You on my left first — what's your name?"
    _pending_dual_intro = {
        "faces": ordered,
        "stage": "left",
        "left_name": "",
        "asked_at": now,
    }
    _dual_intro_cooldown_until = now + float(
        getattr(config, "DUAL_INTRO_COOLDOWN_SECS", 120.0)
    )
    _speak_blocking(ask_text)
    conv_memory.add_to_transcript("Rex", ask_text)
    conv_log.log_rex(ask_text)
    _session_exchange_count += 1
    _register_rex_utterance(ask_text)
    _log.info("[interaction] dual-unknown intro ask (2 unknown faces): %r", ask_text)
    return True


def _dual_intro_name_from_reply(text: str) -> Optional[str]:
    """Name from a reply to the dual-intro ask: a self-intro phrasing or a bare name."""
    name = _challenged_self_identified_name(text)
    if name:
        return name
    bare = _prompted_bare_name_text(text)
    if bare and _looks_like_name_chunk(bare):
        return _normalize_name(bare)
    return None


def _dual_intro_enroll(name: str, face: dict, audio_array, reply_text: str) -> Optional[int]:
    """Bind one dual-intro answer: person row + face at that position + the answer's
    voice. Returns the person_id (None on failure)."""
    try:
        pid, created = people_memory.find_or_create_person(name)
    except Exception as exc:
        _log.warning("dual-intro person create failed for %r: %s", name, exc)
        return None
    if pid is None:
        return None
    try:
        people_memory.add_biometric(pid, "face", face["encoding"])
    except Exception as exc:
        _log.warning("dual-intro face bind failed for %r: %s", name, exc)
    _safe_enroll_voice(
        pid,
        audio_array,
        transcript_text=reply_text,
        source="dual_intro",
        confirmed=True,
    )
    _last_confident_voice_at[int(pid)] = time.monotonic()
    if created:
        first_inc = config.FAMILIARITY_INCREMENTS.get("first_enrollment", 0.0)
        if first_inc > 0:
            try:
                people_memory.update_familiarity(pid, first_inc)
            except Exception:
                pass
    _bind_world_state_identity(pid, name)
    _episodic_person_enrolled(pid, name, created=created)
    _log.info("[interaction] dual-intro enrolled %r (person_id=%s, face+voice)", name, pid)
    return int(pid)


def _handle_pending_dual_intro_reply(
    text: str, audio_array, anonymous_speaker_label: Optional[str]
) -> tuple[bool, Optional[str]]:
    """Consume a reply to the dual-unknown intro ask. Returns (consumed, spoken)."""
    global _pending_dual_intro, _session_exchange_count
    pending = _pending_dual_intro
    if pending is None:
        return False, None
    ttl = float(getattr(config, "DUAL_INTRO_WINDOW_SECS", 45.0))
    if (time.monotonic() - pending["asked_at"]) > ttl:
        _log.info("[interaction] dual-intro window expired — clearing")
        _pending_dual_intro = None
        return False, None
    if _is_offscreen_identify_cancel_reply(text):
        _pending_dual_intro = None
        return True, None
    name = _dual_intro_name_from_reply(text)
    if not name:
        # Don't badger: one nameless reply drops the flow; normal handling resumes.
        _log.info("[interaction] dual-intro reply had no name — clearing: %r", text)
        _pending_dual_intro = None
        return False, None

    stage = pending.get("stage")
    faces = pending.get("faces") or []
    if stage == "left" and len(faces) >= 2:
        pid = _dual_intro_enroll(name, faces[0], audio_array, text)
        if pid is not None and anonymous_speaker_label:
            _retire_anonymous_speaker_slot(
                anonymous_speaker_label, person_id=pid, person_name=name
            )
        pending["stage"] = "right"
        pending["left_name"] = name
        pending["asked_at"] = time.monotonic()   # fresh window for the second answer
        first = name.split()[0]
        special = None
        try:
            from intelligence import person_specials as _specials
            special = _specials.special_intro_ack(name)
        except Exception:
            special = None
        lead = special or f"{first} — logged and locked in."
        spoken = f"{lead} And you on my right — what's your name?"
        _speak_blocking(spoken)
        conv_memory.add_to_transcript("Rex", spoken)
        conv_log.log_rex(spoken)
        _session_exchange_count += 1
        _register_rex_utterance(spoken)
        return True, spoken

    # stage == "right" (or degraded face list): bind the remaining face.
    face = faces[-1] if faces else None
    pid = _dual_intro_enroll(name, face, audio_array, text) if face else None
    if pid is not None and anonymous_speaker_label:
        _retire_anonymous_speaker_slot(
            anonymous_speaker_label, person_id=pid, person_name=name
        )
    _pending_dual_intro = None
    left_name = pending.get("left_name") or "your friend"
    first = name.split()[0]
    special = None
    try:
        from intelligence import person_specials as _specials
        special = _specials.special_intro_ack(name)
    except Exception:
        special = None
    if special:
        spoken = special
    else:
        spoken = (
            f"{first} on my right, {_first_name_or(left_name, 'you')} on my left — "
            f"got you both. Welcome to the frequency."
        )
    _speak_blocking(spoken)
    conv_memory.add_to_transcript("Rex", spoken)
    conv_log.log_rex(spoken)
    _session_exchange_count += 1
    _register_rex_utterance(spoken)
    return True, spoken


def _ask_visible_unknown_identity_question(
    text: str,
    *,
    recent_engagement: Optional[dict],
    group_chatter_active: bool,
    source: str,
) -> Optional[str]:
    """Ask a visible unknown speaker for their name and open enrollment window."""
    global _identity_prompt_until, _session_exchange_count

    if group_chatter_active:
        _log.info(
            "[interaction] suppressing visible-unknown identity ask during "
            "group chatter source=%s text=%r",
            source,
            text,
        )
        return None

    prior_first = ""
    if recent_engagement and recent_engagement.get("name"):
        prior_first = _first_name_or(recent_engagement.get("name"))
    if prior_first:
        ask_prompt = (
            f"A new face just appeared on camera and an unfamiliar voice "
            f"said: '{text}'. You don't recognize them. You were just "
            f"talking with '{prior_first}'. In ONE short in-character Rex "
            f"line, greet the newcomer, ask their name, AND ask how they "
            f"know {prior_first}. Warm, curious. One line ending in a "
            f"question mark."
        )
    else:
        ask_prompt = (
            f"A new face just appeared on camera and an unfamiliar voice "
            f"said: '{text}'. You don't recognize them. In ONE short "
            f"in-character Rex line, greet them and ask who they are / "
            f"what name to call them. One line ending in a question mark."
        )
    try:
        q_text = llm.get_response(ask_prompt)
    except Exception as exc:
        _log.debug("visible-unknown identity ask error source=%s: %s", source, exc)
        return None
    if not q_text:
        return None

    _speak_blocking(q_text)
    conv_memory.add_to_transcript("Rex", q_text)
    conv_log.log_rex(q_text)
    _session_exchange_count += 1
    _register_rex_utterance(q_text)
    _identity_prompt_until = time.monotonic() + _IDENTITY_REPLY_WINDOW_SECS
    _log.info(
        "[interaction] visible-unknown identity ask source=%s prior=%r: %r",
        source,
        prior_first or None,
        q_text,
    )
    return q_text


def _bare_wake_should_ask_visible_unknown_identity(
    *,
    person_id: Optional[int],
    identity_prompt_active: bool,
    has_unknown_visible_or_recent: bool,
    game_conversation_lock: bool,
) -> bool:
    return (
        person_id is None
        and not identity_prompt_active
        and has_unknown_visible_or_recent
        and not game_conversation_lock
        and _pending_face_reveal_confirm is None
    )


_last_voice_challenge_at: float = 0.0


def _voice_ambiguous_between_knowns(
    score: float, margin: float, required_margin: Optional[float] = None,
) -> bool:
    """True when the voice cleared the accept threshold but two ENROLLED people are
    within the ambiguity margin of each other (field log 2026-07-05-21-22: JT 0.563
    vs Bret 0.529, margin 0.034 < 0.07). That is not background chatter — a real,
    enrolled-adjacent person is talking and the prints can't split them. It must
    escalate to the who's-that ask, not churn anonymous Guest-N slots.

    required_margin, when given, is the scoreboard-specific bar from
    speaker_id.required_ambiguity_margin (thin-challenger relief); the config
    base is only the fallback."""
    thr = float(getattr(config, "SPEAKER_ID_SIMILARITY_THRESHOLD", 0.50))
    known_margin = (float(required_margin) if required_margin is not None
                    else float(getattr(config, "SPEAKER_ID_KNOWN_MARGIN", 0.07)))
    return float(score or 0.0) >= thr and 0.0 <= float(margin or 0.0) < known_margin


def _signature_resolves_to_person(score: float, last_seen_at, person_id=None) -> bool:
    """Should a person-linked voice signature resolve the speaker outright?

    Cold signatures (from an earlier session) need the strict bar. But a WARM one —
    bumped/linked within the warm window — resolves at a lower bar: field log
    2026-07-05-02-51, JT was confirmed by name and his very next utterance matched
    his just-linked signature at 0.758 < the 0.80 cold bar, so he became
    unknown_voice_2 fifteen seconds after Rex said 'welcome aboard'. A signature
    seen seconds ago is the same person still talking."""
    cold_bar = float(getattr(config, "VOICE_SIGNATURE_RESOLVE_PERSON_MIN_SCORE", 0.80))
    if float(score or 0.0) >= cold_bar:
        return True
    warm_bar = float(getattr(config, "VOICE_SIGNATURE_RESOLVE_WARM_MIN_SCORE", 0.70))
    if float(score or 0.0) < warm_bar:
        return False
    warm_secs = float(getattr(config, "VOICE_SIGNATURE_WARM_WINDOW_SECS", 900.0))
    # Warm by PERSON, not just by signature: the linked person was confidently
    # matched on their real prints minutes ago, so a short clip that scores low
    # on the prints but lands on their linked signature is them still talking
    # (field log 2026-08-22-20-12: Bret's 3-word "Yeah, that's Max" scored 0.444
    # on his prints, 0.760 on his linked signature, and minted unknown_voice_2
    # five minutes after he was matched at 0.89).
    pid = _safe_int(person_id)
    if pid is not None:
        anchor = _last_confident_voice_at.get(pid)
        if anchor is not None and 0.0 <= (time.monotonic() - anchor) <= warm_secs:
            return True
    try:
        from datetime import datetime, timezone
        seen = datetime.fromisoformat(str(last_seen_at))
        if seen.tzinfo is None:
            seen = seen.replace(tzinfo=timezone.utc)
        age = (datetime.now(timezone.utc) - seen).total_seconds()
        return 0.0 <= age <= warm_secs
    except (TypeError, ValueError):
        return False


# Voice continuity anchor: person_id -> monotonic time of their last CONFIDENT
# (>= SPEAKER_ID_CONFIDENT_THRESHOLD) voice match. A marginal match on a person is
# only trusted silently while their voice has this recent credibility — the camera
# never supplies it (voice is the primary identity channel; owner call 2026-07-05).
_last_confident_voice_at: dict[int, float] = {}


def _note_confident_voice(person_id, speaker_score: float) -> None:
    """Record a confident voice match as the person's continuity anchor."""
    pid = _safe_int(person_id)
    if pid is None:
        return
    confident = float(getattr(config, "SPEAKER_ID_CONFIDENT_THRESHOLD", 0.70))
    if float(speaker_score or 0.0) >= confident:
        _last_confident_voice_at[pid] = time.monotonic()


def _voice_continuity_active(person_id) -> bool:
    """True while the person's last CONFIDENT voice match is recent enough that a
    marginal follow-up match is plausibly the same voice trailing off (short
    commands, mumbles) rather than a different person cross-matching their print."""
    pid = _safe_int(person_id)
    if pid is None:
        return False
    anchor = _last_confident_voice_at.get(pid)
    if anchor is None:
        return False
    window = float(getattr(config, "SPEAKER_ID_CONTINUITY_WINDOW_SECS", 240.0))
    return (time.monotonic() - anchor) <= window


def _someone_visible_who_isnt(person_id) -> bool:
    """True if the camera currently shows ANY person (known-other, unknown face, or a
    real pose-only body) who is not `person_id`. Pose-only entries COUNT here — unlike
    the unknown-count curiosity (which requires a face_box, per the phantom-pose fix),
    this feeds the who's-that-speaking challenge, where an unidentifiable body in frame
    is exactly the evidence that matters (vision.pose already drops phantoms)."""
    try:
        people = world_state.get("people") or []
    except Exception:
        return False
    target = _safe_int(person_id)
    for person in people:
        if not isinstance(person, dict):
            continue
        pid = _safe_int(person.get("person_db_id"))
        if target is not None and pid == target:
            continue
        return True
    return False


def _voice_only_attribution_suspect(person_id, speaker_score: float) -> bool:
    """The single-print cross-match trap (field log 2026-07-05): with only ONE
    voiceprint enrolled, a DIFFERENT person's voice can land a marginal match on it
    (JT read as Bret at 0.660) while the camera plainly shows a body that is NOT the
    matched person. On the voice-only resolution path (no identified faces), don't
    silently attribute when ALL of:
      - the match is marginal (below SPEAKER_ID_CONFIDENT_THRESHOLD), and
      - the matched person hasn't been on camera recently (grace covers camera pans), and
      - someone ELSE is visible right now (face or real pose).
    The caller then routes to the who's-that-speaking ask instead. Cooldown-limited so
    a chatty second voice doesn't get challenged every single turn."""
    global _last_voice_challenge_at
    if not bool(getattr(config, "SPEAKER_ID_UNSEEN_CHALLENGE_ENABLED", True)):
        return False
    confident = float(getattr(config, "SPEAKER_ID_CONFIDENT_THRESHOLD", 0.70))
    if float(speaker_score or 0.0) >= confident:
        return False                      # genuinely confident voice: trust it
    # Credibility comes from the VOICE, never the camera. The first version used
    # person_visible_recently() here — and field log 2026-07-05-02-37 showed why
    # that's wrong: Bret's face at session start suppressed every challenge while
    # JT talked ("this is JT" soft-accepted as Bret at 0.483). Being in the room
    # is not evidence of being the one talking. A marginal match passes only when
    # this person's OWN voice matched confidently within the continuity window.
    if _voice_continuity_active(person_id):
        return False
    # ECAPA genuine band: the JT cross-matches above were Resemblyzer-scale scores;
    # under ECAPA an impostor lands ~0.25-0.45 mapped, so a score at/above the
    # voice-only trust floor is this person's own voice on a short/quiet turn —
    # don't challenge a genuine speaker at every session start.
    if _ecapa_genuine_band(
        speaker_score,
        float(getattr(config, "SPEAKER_ID_ECAPA_TRUST_FLOOR_VOICE_ONLY", 0.55)),
    ):
        return False
    if not _someone_visible_who_isnt(person_id):
        # EMPTY frame: no visual contradiction, but also no corroboration — a marginal
        # match on an unseen person is still the cross-match shape. Owner's call
        # (2026-07-05): prefer asking "who's that?" over silently crediting the match;
        # an unenrolled housemate gets named-and-enrolled on the answer instead of
        # impersonating the print owner. Disable via config if it gets chatty.
        if not bool(getattr(config, "SPEAKER_ID_CHALLENGE_EMPTY_FRAME", True)):
            return False
    now = time.monotonic()
    cooldown = float(getattr(config, "SPEAKER_ID_CHALLENGE_COOLDOWN_SECS", 45.0))
    if (now - _last_voice_challenge_at) < cooldown:
        return False
    _last_voice_challenge_at = now
    return True


def _has_unknown_visible_person() -> bool:
    """True if WorldState currently includes at least one person without a face match."""
    try:
        people = world_state.get("people")
    except Exception:
        return False
    for person in people:
        if person.get("person_db_id") is not None:
            continue
        if person.get("face_visible") is False or person.get("face_missing"):
            continue
        if person.get("face_box") or person.get("bounding_box") or person.get("bbox"):
            return True
    return False


def _has_unknown_visible_or_recent() -> bool:
    """True if an unknown face is visible now or within the configured grace window."""
    if _has_unknown_visible_person():
        return True
    try:
        return bool(
            consciousness.unknown_visible_recently(
                float(getattr(config, "UNKNOWN_FACE_RECENT_GRACE_SECS", 6.0))
            )
        )
    except Exception:
        return False


def _other_known_visible_recently(person_id: Optional[int]) -> bool:
    """True if another known participant is visible now or just flickered out."""
    try:
        return bool(
            consciousness.known_visible_recently_except(
                person_id,
                float(getattr(config, "UNKNOWN_FACE_RECENT_GRACE_SECS", 6.0)),
            )
        )
    except Exception:
        return False


def _known_person_visible_recently(person_id: Optional[int]) -> bool:
    try:
        return bool(
            consciousness.person_visible_recently(
                person_id,
                float(getattr(config, "UNKNOWN_FACE_RECENT_GRACE_SECS", 6.0)),
            )
        )
    except Exception:
        return False


def _episodic_person_enrolled(person_id, name, *, created: bool) -> None:
    """Log "I met <name>" to rex.db — only on a genuinely NEW enrollment (created=True),
    so re-binding an existing person doesn't re-log a first meeting. Gated + failure-safe
    (episodes.* no-ops under the test runner / when episodic memory is disabled)."""
    if not created:
        return
    try:
        episodes_memory.record_person_enrolled(
            person_id if isinstance(person_id, int) else None, name,
        )
    except Exception as exc:
        _log.debug("episodic person_enrolled failed: %s", exc)


def _bind_world_state_identity(person_id: int, name: str) -> None:
    """
    Attach the newly enrolled identity to the first unknown world-state person slot.
    """
    try:
        def _apply_bind(people):
            for person in people:
                if person.get("person_db_id") is None or person.get("face_id") is None:
                    person["person_db_id"] = person_id
                    person["face_id"] = name
                    person["voice_id"] = name
                    return people
            return None

        world_state.mutate("people", _apply_bind)

        crowd = world_state.get("crowd")
        crowd["dominant_speaker"] = name
        world_state.update("crowd", crowd)
    except Exception as exc:
        _log.debug("world_state identity bind failed: %s", exc)


def _handle_relationship_reply(
    rel_ctx: dict,
    user_text: str,
    speaker_person_id: Optional[int],
    speaker_person_name: Optional[str],
) -> Optional[str]:
    """
    Process a reply to one of two relationship-flow questions:

    Mode A — "who's this?" asked of the ENGAGED person.
        ctx has engaged_person_id but no newcomer_person_id. The speaker is
        expected to be the engaged person; their reply is parsed for BOTH a
        {name, relationship} and we enroll a brand-new person for the newcomer.

    Mode B — "how do you know <engaged>?" asked of the NEWCOMER after identity
        enrollment.
        ctx has both engaged_person_id AND newcomer_person_id. The speaker is
        expected to be the newcomer (already enrolled). Reply is parsed for a
        {relationship} (the name is already known); the edge is saved from the
        newcomer to the engaged person (speaker's perspective).

    In either mode, if the speaker is plausibly correct and the parse produces
    a relationship label, an edge is stored and the slot is marked handled.
    """
    global _pending_introduction

    engaged_id = rel_ctx.get("engaged_person_id")
    engaged_name = rel_ctx.get("engaged_name") or "friend"
    newcomer_pid_pre = rel_ctx.get("newcomer_person_id")  # Mode B only
    slot_id = rel_ctx.get("slot_id") or ""

    mode_b = newcomer_pid_pre is not None

    # Speaker validity check. If this reply clearly came from a different
    # person than the one Rex asked, don't consume the prompt.
    expected_speaker = newcomer_pid_pre if mode_b else engaged_id
    if (
        speaker_person_id is not None
        and expected_speaker is not None
        and speaker_person_id != expected_speaker
    ):
        _log.info(
            "[interaction] relationship reply came from person_id=%s but Rex asked "
            "person_id=%s (mode_%s) — ignoring",
            speaker_person_id, expected_speaker, "B" if mode_b else "A",
        )
        return None

    # Extract. In both modes the LLM call returns {name, relationship}; in mode
    # B we ignore the name because we already know the speaker.
    try:
        parsed = llm.extract_relationship_introduction(
            user_text,
            speaker_person_name or (engaged_name if not mode_b else "newcomer"),
        )
    except Exception as exc:
        _log.debug("relationship extraction error: %s", exc)
        parsed = {"name": None, "relationship": None}

    name, relationship = _filter_relationship_introduction_evidence(
        parsed,
        user_text,
        speaker_person_name or (engaged_name if not mode_b else "newcomer"),
        source="relationship_prompt_mode_b" if mode_b else "relationship_prompt_mode_a",
    )

    # ── Mode B: just save the edge, no enrollment needed ──────────────────────
    if mode_b:
        if not relationship:
            _log.info(
                "[interaction] mode-B relationship reply had no label — user_text=%r parsed=%r",
                user_text, parsed,
            )
            consciousness.note_relationship_slot_handled(slot_id)
            return None
        try:
            from memory import social as social_memory
            # Speaker (newcomer) is describing their relationship to the engaged
            # person. from_id = newcomer (speaker), to_id = engaged.
            social_memory.save_relationship(
                from_person_id=newcomer_pid_pre,
                to_person_id=engaged_id,
                relationship=relationship,
                described_by=newcomer_pid_pre,
            )
            _log.info(
                "[interaction] mode-B saved edge: person_id=%s --[%s]--> person_id=%s (%s)",
                newcomer_pid_pre, relationship, engaged_id, engaged_name,
            )
        except Exception as exc:
            _log.warning("social.save_relationship failed (mode B): %s", exc)
        consciousness.note_relationship_slot_handled(slot_id)
        return None

    # ── Mode A: enroll newcomer + save edge ────────────────────────────────────
    if not name:
        if relationship:
            introducer_for_pending = engaged_id or speaker_person_id
            if introducer_for_pending is None:
                consciousness.note_relationship_slot_handled(slot_id)
                return None
            _pending_introduction = {
                "introducer_id": introducer_for_pending,
                "introducer_name": engaged_name,
                "relationship": relationship,
                "visible_newcomer": True,
                "created_at": time.monotonic(),
                "asked_at": time.monotonic(),
            }
            introductions.note_introduction()  # stand down the mystery-guest agenda
            consciousness.note_relationship_slot_handled(slot_id)
            try:
                first = _first_name_or(engaged_name, "friend")
                return llm.get_response(
                    f"{first} said the visible newcomer is their {relationship}, "
                    f"but did not give the person's name yet. In ONE short "
                    f"in-character Rex line, ask {first} ONLY for the newcomer's "
                    f"name. Do NOT ask how they are related. Do NOT imply the "
                    f"newcomer is related to Rex."
                )
            except Exception:
                return f"Got the {relationship} part. What name am I filing for them?"

        # Deflection or no name given. Don't badger — mark slot handled so Rex
        # moves on.
        _log.info(
            "[interaction] mode-A relationship reply had no name — user_text=%r parsed=%r",
            user_text, parsed,
        )
        consciousness.note_relationship_slot_handled(slot_id)
        return None

    # Enroll the newcomer. Use enroll_unknown_face so we don't rebind the
    # engaged person's face to the new name.
    new_id = None
    try:
        from vision import camera as camera_mod
        from vision import face as face_mod

        new_id, created = people_memory.find_or_create_person(name)
        if new_id is None:
            _log.error("[interaction] failed to create DB row for newcomer %r", name)
            consciousness.note_relationship_slot_handled(slot_id)
            return None
        if engaged_id is not None and int(new_id) == int(engaged_id):
            _log.warning(
                "[interaction] refusing mode-A self-introduction: parsed newcomer %r resolves to engaged person_id=%s; text=%r",
                name,
                engaged_id,
                user_text,
            )
            consciousness.note_relationship_slot_handled(slot_id)
            return None

        first_inc = config.FAMILIARITY_INCREMENTS.get("first_enrollment", 0.0)
        if created and first_inc > 0:
            people_memory.update_familiarity(new_id, first_inc)

        face_enrolled = False
        frame = camera_mod.capture_still()
        if frame is not None:
            face_enrolled = face_mod.enroll_unknown_face(new_id, frame)
            if face_enrolled:
                threading.Thread(
                    target=face_mod.update_appearance,
                    args=(new_id, frame.copy()),
                    daemon=True,
                    name=f"appearance-enroll-{new_id}",
                ).start()

        if face_enrolled:
            _bind_world_state_identity(new_id, name)
        if engaged_id:
            _store_introduction_memories(
                int(engaged_id),
                engaged_name,
                new_id,
                name,
                relationship,
            )

        _log.info(
            "[interaction] mode-A enrolled newcomer %s (person_id=%s) as %s of %s",
            name, new_id, relationship or "acquaintance", engaged_name,
        )
        _episodic_person_enrolled(new_id, name, created=created)
        introducer_for_ack = engaged_id or speaker_person_id
        if introducer_for_ack is None:
            return f"{_first_name_or(name, 'there')}, welcome. Identity filed under 'better than mystery organic.'"
        return _intro_ack_and_followup(
            int(introducer_for_ack),
            engaged_name,
            new_id,
            name,
            relationship,
            visible_newcomer=True,
        )
    except Exception as exc:
        _log.error("relationship enrollment failed: %s", exc)
        return None
    finally:
        consciousness.note_relationship_slot_handled(slot_id)


def _handle_common_first_name_last_name_reply(
    text: str,
    audio_array: Optional[np.ndarray] = None,
) -> tuple[Optional[str], Optional[int], Optional[str]]:
    """
    Complete a deferred identity enrollment after Rex asked for a last name.

    Returns (response_text, enrolled_person_id, full_name). response_text may be
    None when the pending context expired or the reply was not a usable last name.
    """
    global _pending_common_first_name_identity, _pending_common_first_name_introduction

    ctx = _pending_common_first_name_identity
    if not _common_first_name_context_fresh(ctx):
        _pending_common_first_name_identity = None
        return None, None, None

    first_name = str(ctx.get("first_name") or "").strip()
    refused_last_name = _is_last_name_refusal(text, first_name)
    if refused_last_name:
        last_name = None
    else:
        last_name = _extract_last_name_reply(text, first_name)
    if not first_name:
        return None, None, None
    if not last_name and not refused_last_name:
        return None, None, None

    full_name = first_name if refused_last_name else f"{first_name} {last_name}"
    stored_audio = ctx.get("audio")
    if (
        isinstance(stored_audio, np.ndarray)
        and len(stored_audio) > 0
        and isinstance(audio_array, np.ndarray)
        and len(audio_array) > 0
    ):
        enroll_audio = np.concatenate([stored_audio, audio_array])
    elif isinstance(stored_audio, np.ndarray) and len(stored_audio) > 0:
        enroll_audio = stored_audio
    elif isinstance(audio_array, np.ndarray) and len(audio_array) > 0:
        enroll_audio = audio_array
    else:
        enroll_audio = np.zeros(1, dtype=np.float32)

    prior_engagement = ctx.get("prior_engagement")
    enrolled_id = _enroll_new_person(
        full_name,
        enroll_audio,
        enroll_unknown_face=bool(prior_engagement),
    )
    _pending_common_first_name_identity = None
    if enrolled_id is None:
        return None, None, None

    _retire_anonymous_speaker_slot(
        ctx.get("anonymous_speaker_label"),
        person_id=enrolled_id,
        person_name=full_name,
    )

    if prior_engagement and prior_engagement.get("person_id") != enrolled_id:
        _pending_post_greet_relationship[0] = {
            "prior_engaged_id": prior_engagement["person_id"],
            "prior_engaged_name": prior_engagement.get("name"),
            "newcomer_person_id": enrolled_id,
            "newcomer_name": full_name,
        }

    if refused_last_name:
        _remember_last_name_declined(enrolled_id, first_name)
        _log.info(
            "[identity] last-name request declined for %r; filing first name only",
            first_name,
        )
        response = f"Fine, {first_name} it is. First name only — I'll cope."
    else:
        response = f"Got it — {full_name}. Good to actually know you."
    return response, enrolled_id, full_name


def _handle_common_first_name_intro_last_name_reply(text: str) -> Optional[str]:
    """Complete an explicit introduction delayed for a common first name."""
    global _pending_common_first_name_introduction

    ctx = _pending_common_first_name_introduction
    if not _common_first_name_context_fresh(ctx):
        _pending_common_first_name_introduction = None
        return None

    first_name = str(ctx.get("first_name") or "").strip()
    refused_last_name = _is_last_name_refusal(text, first_name)
    if refused_last_name:
        last_name = None
    else:
        last_name = _extract_last_name_reply(text, first_name)
    if not first_name:
        return None
    if not last_name and not refused_last_name:
        return None

    full_name = first_name if refused_last_name else f"{first_name} {last_name}"
    introducer_id = int(ctx["introducer_id"])
    introducer_name = str(ctx.get("introducer_name") or "friend")
    relationship = ctx.get("relationship")
    visible_newcomer = bool(ctx.get("visible_newcomer", True))
    subject_kind = str(ctx.get("subject_kind") or "person")

    new_id = _enroll_introduced_person(
        full_name,
        introducer_id,
        introducer_name,
        relationship,
        enroll_visible_face=visible_newcomer,
    )
    _pending_common_first_name_introduction = None
    if new_id is None:
        return None

    if refused_last_name:
        _remember_last_name_declined(new_id, first_name)
        _log.info(
            "[introduction] last-name request declined for %r; filing first name only",
            first_name,
        )
    else:
        _log.info(
            "[introduction] %s introduced %s as %s (person_id=%s) after last-name disambiguation",
            introducer_name,
            full_name,
            relationship or "acquaintance",
            new_id,
        )
    return _intro_ack_and_followup(
        introducer_id,
        introducer_name,
        new_id,
        full_name,
        relationship,
        subject_kind=subject_kind,
        visible_newcomer=visible_newcomer,
    )


def _handle_existing_common_first_name_last_name_reply(text: str) -> Optional[str]:
    """Complete a last-name prompt for a returning person already in memory."""
    global _pending_existing_common_first_name, _pending_identity_match_confirmation
    global _pending_last_name_confirm

    ctx = _pending_existing_common_first_name
    if not _common_first_name_context_fresh(ctx):
        _pending_existing_common_first_name = None
        return None

    first_name = str(ctx.get("first_name") or "").strip()
    person_id = ctx.get("person_id")
    if not first_name or person_id is None:
        _pending_existing_common_first_name = None
        return None

    refused_last_name = _is_last_name_refusal(text, first_name)
    last_name = None if refused_last_name else _extract_last_name_reply(text, first_name)
    if not refused_last_name and not last_name:
        return None

    _pending_existing_common_first_name = None
    person_id = int(person_id)
    _common_first_name_prompted_this_session.add(person_id)

    if refused_last_name:
        _remember_last_name_declined(person_id, first_name)
        _log.info(
            "[identity] returning person_id=%s declined last-name request; keeping %r",
            person_id,
            first_name,
        )
        return f"Fine. I'll keep you as {first_name}. The filing cabinet is judging both of us."

    # Don't durably rename on a single unusual/low-confidence token (a Whisper
    # mangling like "Bat-tigger"). Confirm it first so one garbled word can't
    # overwrite the canonical name. A clearly-phrased reply ("my last name is
    # Benziger", "Bret Benziger") commits directly.
    if (
        bool(getattr(config, "COMMON_FIRST_NAME_LAST_NAME_REQUIRE_CONFIRM_UNUSUAL", True))
        and _last_name_token_is_unusual(last_name)
        and not _last_name_reply_was_explicit(text, first_name)
    ):
        global _pending_last_name_confirm
        _pending_last_name_confirm = {
            "person_id": person_id,
            "first_name": first_name,
            "last_name": last_name,
            "asked_at": time.monotonic(),
        }
        _log.info(
            "[identity] unusual surname %r for person_id=%s — confirming before rename",
            last_name,
            person_id,
        )
        return _format_last_name_confirm_prompt(f"{first_name} {last_name}")

    full_name = f"{first_name} {last_name}"
    if not people_memory.rename_person(person_id, full_name):
        _log.info(
            "[identity] returning person_id=%s last-name rename blocked target=%r",
            person_id,
            full_name,
        )
        return f"I couldn't safely rename that memory to {full_name}."

    _refresh_world_state_person_name(person_id, full_name)
    _log.info(
        "[identity] returning person_id=%s upgraded common first name %r -> %r",
        person_id,
        first_name,
        full_name,
    )
    return f"There we go — {full_name}. Now I've got the whole picture."


def _format_last_name_confirm_prompt(full_name: str) -> str:
    prompts = list(getattr(config, "COMMON_FIRST_NAME_LAST_NAME_CONFIRM_PROMPTS", []) or [])
    if not prompts:
        prompts = ["{full} — that right?"]
    try:
        return random.choice(prompts).format(full=full_name)
    except Exception:
        return f"{full_name} — that right?"


_LAST_NAME_CONFIRM_NO_RE = re.compile(
    r"^\s*(?:no+|nope|nah|naw|not quite|that'?s not it|wrong|incorrect)\b",
    re.IGNORECASE,
)
# Affirmations a person uses to confirm a name — broader than _AFFIRM_PAT, which
# doesn't cover "correct" / "that's right". Deliberately NO bare "right" (it
# matches inside "that's not right"); use "that's right" instead.
_CONFIRM_YES_RE = re.compile(
    r"\b(?:correct|that'?s (?:right|it|correct)|you got it|got it right|"
    r"exactly|yep|yeah|yes|yup|sure|spot on|nailed it|that works)\b",
    re.IGNORECASE,
)
# Affirmation/negation/filler words that must NEVER be mistaken for a surname
# during a confirm ("yep"/"correct"/"no" are not last names).
_CONFIRM_NON_SURNAME_WORDS = {
    "yes", "yeah", "yep", "yup", "yah", "correct", "right", "sure", "ok", "okay",
    "exactly", "indeed", "totally", "absolutely", "no", "nope", "nah", "naw",
    "not", "wrong", "incorrect", "that", "this", "it", "is", "my", "name",
    "last", "surname",
}
_CONFIRM_LEADIN_SURNAME_RE = re.compile(
    r"\b(?:it'?s|my\s+last\s+name\s+is|last\s+name\s+is|surname\s+is)\s+"
    r"([A-Za-z][A-Za-z'\-]+)\b",
    re.IGNORECASE,
)


def _extract_confirm_surname_correction(text: str, first_name: str) -> Optional[str]:
    """A surname offered while CONFIRMING a misheard one — only an explicit
    correction, never an affirmation/filler word."""
    cleaned = re.sub(r"^\s*(?:no+|nope|nah|naw)[,\s]+", "", (text or "").strip(), flags=re.I)
    m = _CONFIRM_LEADIN_SURNAME_RE.search(cleaned)
    if m:
        cand = _normalize_name(m.group(1))
    else:
        parts = (_normalize_name(cleaned) or "").split()
        cand = parts[0] if len(parts) == 1 else None  # a single bare token only
    if not cand:
        return None
    low = cand.lower()
    if low in _CONFIRM_NON_SURNAME_WORDS or low == (first_name or "").lower():
        return None
    return cand


def _handle_last_name_confirm_reply(text: str) -> Optional[str]:
    """Resolve a 'Bret Bat-tigger — that right?' confirmation before renaming."""
    global _pending_last_name_confirm

    ctx = _pending_last_name_confirm
    if not _common_first_name_context_fresh(ctx):
        _pending_last_name_confirm = None
        return None

    person_id = int(ctx["person_id"])
    first_name = str(ctx.get("first_name") or "").strip()
    last_name = str(ctx.get("last_name") or "").strip()
    cleaned = (text or "").strip()

    def _commit(surname: str) -> Optional[str]:
        full = f"{first_name} {surname}".strip()
        if not people_memory.rename_person(person_id, full):
            return f"I couldn't safely rename that memory to {full}."
        _refresh_world_state_person_name(person_id, full)
        _common_first_name_prompted_this_session.add(person_id)
        _log.info(
            "[identity] confirmed surname — person_id=%s %r -> %r",
            person_id, first_name, full,
        )
        return f"There we go — {full}. Now I've got the whole picture."

    # A correction that EXPLICITLY supplies a different surname ("no, it's
    # Benziger" / "Benziger") overrides the misheard one. Checked before the
    # bare affirmation so a real correction wins, but it must be an explicit
    # surname — never an affirmation/filler word ("yep"/"correct" are NOT
    # surnames, or we'd rename to "Bret Yep").
    corrected = _extract_confirm_surname_correction(cleaned, first_name)
    if corrected and corrected.lower() != last_name.lower():
        _pending_last_name_confirm = None
        return _commit(corrected)

    if _AFFIRM_PAT.search(cleaned) or _CONFIRM_YES_RE.search(cleaned):
        _pending_last_name_confirm = None
        return _commit(last_name)

    if _LAST_NAME_CONFIRM_NO_RE.search(cleaned) or _is_last_name_refusal(cleaned, first_name):
        _pending_last_name_confirm = None
        _log.info(
            "[identity] surname confirm declined for person_id=%s — keeping %r",
            person_id, first_name,
        )
        return f"My mistake — sticking with {first_name} then."

    # Unrelated turn: drop the confirm and let normal routing take it.
    _pending_last_name_confirm = None
    return None


def _should_defer_existing_common_first_name_prompt(
    text: str, *, person_id: Optional[int] = None
) -> bool:
    """Do not hijack a clear command — OR a substantive mid-conversation turn —
    just to ask a known person's last name. The ask belongs at a natural, low-
    content moment (a short reply, a greeting, a lull), never in the middle of a
    real answer like 'It's vodka and orange juice' (live-logged 2026-06-18)."""
    cleaned = (text or "").strip()
    if not cleaned:
        return False
    try:
        match = command_parser.parse(cleaned)
    except Exception:
        match = None
    if match is not None:
        return True
    try:
        intent = intent_classifier._deterministic_label(cleaned)
    except Exception:
        intent = "general"
    if intent != "general":
        return True
    if bool(getattr(config, "COMMON_FIRST_NAME_LAST_NAME_NATURAL_MOMENT_ONLY", True)):
        # Only a short, topic-neutral turn (greeting / ack / brief reply) is a
        # natural place to slip the ask in. A longer utterance is substantive
        # conversational content — don't interrupt it. And if the person is
        # answering a question Rex just asked on another topic, that turn belongs
        # to that thread, not an identity interrogation.
        max_words = int(getattr(config, "COMMON_FIRST_NAME_LAST_NAME_MAX_TURN_WORDS", 4))
        if _word_count(cleaned) > max_words:
            return True
        if person_id is not None and _rex_frame_expects_reply(person_id):
            return True
    return False


def _maybe_prompt_existing_common_first_name(
    person_id: Optional[int],
    person_name: Optional[str],
    current_text: str = "",
) -> Optional[str]:
    """Ask returning single-name-only people for a last name once per session."""
    global _pending_existing_common_first_name, _pending_identity_match_confirmation
    global _pending_last_name_confirm

    if not _known_person_needs_last_name(person_id, person_name):
        return None
    if _should_defer_existing_common_first_name_prompt(current_text, person_id=person_id):
        _log.info(
            "[identity] deferred last-name prompt for person_id=%s name=%r "
            "(command/substantive turn) text=%r",
            person_id,
            person_name,
            current_text,
        )
        return None

    pid = int(person_id)
    min_turns = _last_name_prompt_min_person_turns()
    turn_count = _session_person_turn_counts.get(pid, 0)
    if not _person_ready_for_last_name_prompt(pid):
        _log.info(
            "[identity] deferring last-name prompt for person_id=%s name=%r "
            "until longer conversation turns=%s/%s",
            pid,
            person_name,
            turn_count,
            min_turns,
        )
        return None

    first_name = _normalize_name(person_name or "") or (person_name or "").strip()
    if not first_name:
        return None

    _pending_existing_common_first_name = {
        "person_id": pid,
        "first_name": first_name,
        "asked_at": time.monotonic(),
    }
    _common_first_name_prompted_this_session.add(pid)
    _log.info(
        "[identity] returning common first-name-only person_id=%s name=%r needs last-name disambiguation",
        pid,
        first_name,
    )
    return _format_common_first_name_last_name_prompt(first_name)


def _mark_single_name_for_later_last_name(person_id: Optional[int], person_name: Optional[str]) -> None:
    if person_id is None:
        return
    normalized = _normalize_name(person_name or "")
    if not normalized or _name_word_count(normalized) != 1 or looks_like_initials(normalized):
        return
    _log.info(
        "[identity] person_id=%s filed under single name %r; will ask for last name later",
        person_id,
        normalized,
    )


def _note_session_person_turn(person_id: Optional[int]) -> None:
    pid = _safe_int(person_id)
    if pid is None:
        return
    _session_person_turn_counts[pid] = _session_person_turn_counts.get(pid, 0) + 1


# P2 — warmth from talking ─────────────────────────────────────────────────────
# Genuine laughter in TEXT (transcribed "haha", "lol", "that's funny", 😂). Kept as a
# text heuristic so it needs no extra LLM call on the speech path; the layer-2 sentiment
# pass stays focused on insult/apology/compliment.
_LAUGHTER_RE = re.compile(
    r"(?:^|\b)(?:ha(?:ha)+h?|hah|heh(?:eh)+|hehe|lol|lmao|lmfao|rofl)\b|😂|🤣",
    re.IGNORECASE,
)
_LAUGHTER_PHRASES = (
    "that's funny", "thats funny", "so funny", "too funny", "hilarious",
    "you're funny", "youre funny", "good one", "made me laugh", "cracking me up",
    "cracking up", "you got me",
)


def _text_is_genuine_laughter(text: str) -> bool:
    t = (text or "").strip()
    if not t:
        return False
    if _LAUGHTER_RE.search(t):
        return True
    low = t.lower()
    return any(p in low for p in _LAUGHTER_PHRASES)


def _text_is_engaged_turn(text: str) -> bool:
    """A substantive user turn (not a one-word ack) — the unit of 'time spent talking'."""
    words = re.findall(r"\w+", text or "")
    return len(words) >= int(getattr(config, "WARMTH_FROM_TALKING_MIN_WORDS", 4))


def _note_warmth_from_talking(
    person_id: Optional[int],
    user_text: str,
    *,
    pre_classified_insult: bool = False,
) -> None:
    """Tally engaged turns + shared laughter for a small, capped session-end warmth bump.

    Counting (not awarding) here keeps it cheap and lets _award_warmth_from_talking cap
    the total per session so a long chat can't runaway-inflate warmth. Insulting turns
    don't count as engaged; laughter still counts (you can laugh and rib Rex at once).
    """
    pid = _safe_int(person_id)
    if pid is None:
        return
    sig = _session_warmth_signals.setdefault(pid, {"engaged": 0, "laughs": 0})
    if _text_is_genuine_laughter(user_text):
        sig["laughs"] += 1
    if not pre_classified_insult and _text_is_engaged_turn(user_text):
        sig["engaged"] += 1


def _award_warmth_from_talking(person_id: Optional[int]) -> None:
    """Convert this session's engaged-turn + laughter tally into a capped warmth bump."""
    pid = _safe_int(person_id)
    if pid is None:
        return
    sig = _session_warmth_signals.get(pid)
    if not sig:
        return
    engaged = int(sig.get("engaged", 0))
    laughs = int(sig.get("laughs", 0))
    total = 0.0
    if engaged > 0:
        per = float(config.RELATIONSHIP_INCREMENTS["engaged_turn"][1])
        cap = int(getattr(config, "WARMTH_FROM_TALKING_MAX_ENGAGED_PER_SESSION", 5))
        total += per * min(engaged, cap)
    if laughs > 0:
        per = float(config.RELATIONSHIP_INCREMENTS["genuine_laughter"][1])
        cap = int(getattr(config, "WARMTH_FROM_TALKING_MAX_LAUGHS_PER_SESSION", 3))
        total += per * min(laughs, cap)
    if total > 0:
        people_memory.update_relationship_scores(pid, warmth=total)
        _log.info(
            "[interaction] warmth-from-talking +%.3f for person_id=%s (engaged=%d laughs=%d)",
            total, pid, engaged, laughs,
        )


def _last_name_prompt_min_person_turns() -> int:
    configured = getattr(config, "COMMON_FIRST_NAME_LAST_NAME_MIN_PERSON_TURNS", None)
    if configured is None:
        configured = getattr(config, "LONG_CONVERSATION_MIN_EXCHANGES", 5)
    try:
        return max(0, int(configured))
    except (TypeError, ValueError):
        return 5


def _person_ready_for_last_name_prompt(person_id: Optional[int]) -> bool:
    pid = _safe_int(person_id)
    if pid is None:
        return False
    min_turns = _last_name_prompt_min_person_turns()
    if min_turns <= 0:
        return True
    return _session_person_turn_counts.get(pid, 0) >= min_turns


def _identity_match_confirmation_fresh(ctx: Optional[dict]) -> bool:
    if not ctx:
        return False
    ttl = float(getattr(config, "COMMON_FIRST_NAME_LAST_NAME_WINDOW_SECS", 30.0))
    return (time.monotonic() - float(ctx.get("asked_at", 0.0))) <= max(1.0, ttl)


def _identity_confirmation_affirms(text: str) -> bool:
    plain = _plain_confirmation_text(text)
    return plain in {"yes", "yeah", "yep", "correct", "that is me", "that's me", "thats me"} or bool(
        re.search(r"\b(yes|yeah|yep|correct|that'?s me|that is me)\b", text or "", re.IGNORECASE)
    )


def _identity_confirmation_declines(text: str) -> bool:
    plain = _plain_confirmation_text(text)
    return plain in {"no", "nope", "not me", "someone new", "new person"} or bool(
        re.search(r"\b(no|nope|not me|someone new|new person|different person)\b", text or "", re.IGNORECASE)
    )


def _identity_match_prompt(candidate_name: str, existing_name: str, match_type: str) -> str:
    candidate_first = _first_name_or(candidate_name, "that")
    if match_type == "first_name":
        return (
            f"Wait — are you the same {existing_name} I already know? My optical "
            f"sensors are being dramatic; I almost filed a second {candidate_first}."
        )
    return f"Did you mean {existing_name}, or is {candidate_name} someone new?"


def _maybe_ask_identity_match_confirmation(
    candidate_name: str,
    audio_array: np.ndarray,
    *,
    prior_engagement: Optional[dict] = None,
    anonymous_speaker_label: Optional[str] = None,
    enroll_unknown_face: bool = False,
    defer_face_enrollment: bool = False,
    source: str = "identity",
) -> bool:
    """Ask before binding a weak name candidate to an existing person."""
    global _pending_identity_match_confirmation, _identity_prompt_until, _session_exchange_count

    try:
        match = people_memory.find_potential_person_match(candidate_name)
    except Exception as exc:
        _log.debug("identity match lookup failed for %r: %s", candidate_name, exc)
        return False
    if not match or match.get("match_type") not in {"first_name", "fuzzy", "fuzzy_first_name"}:
        return False

    person = match.get("person") or {}
    existing_id = person.get("id")
    existing_name = str(person.get("name") or "").strip()
    clean_candidate = str(match.get("candidate_name") or candidate_name or "").strip()
    if existing_id is None or not existing_name or not clean_candidate:
        return False

    _pending_identity_match_confirmation = {
        "candidate_name": clean_candidate,
        "existing_person_id": int(existing_id),
        "existing_name": existing_name,
        "match_type": match.get("match_type"),
        "audio": audio_array.copy() if isinstance(audio_array, np.ndarray) else np.zeros(1, dtype=np.float32),
        "prior_engagement": prior_engagement,
        "anonymous_speaker_label": anonymous_speaker_label,
        "enroll_unknown_face": bool(enroll_unknown_face),
        "defer_face_enrollment": bool(defer_face_enrollment),
        "asked_at": time.monotonic(),
        "source": source,
    }
    _identity_prompt_until = max(
        _identity_prompt_until,
        time.monotonic() + float(getattr(config, "COMMON_FIRST_NAME_LAST_NAME_WINDOW_SECS", 30.0)),
    )
    prompt = _identity_match_prompt(clean_candidate, existing_name, str(match.get("match_type") or ""))
    _log.info(
        "[identity] asking match confirmation candidate=%r existing=%r type=%s source=%s",
        clean_candidate,
        existing_name,
        match.get("match_type"),
        source,
    )
    _speak_blocking(prompt, emotion="curious", pre_beat_ms=100, post_beat_ms_override=200)
    conv_memory.add_to_transcript("Rex", prompt)
    conv_log.log_rex(prompt)
    _session_exchange_count += 1
    _register_rex_utterance(prompt)
    return True


def _attach_identity_sample_to_person(
    person_id: int,
    person_name: str,
    audio_array: np.ndarray,
    *,
    enroll_unknown_face: bool = False,
    defer_face_enrollment: bool = False,
) -> None:
    _safe_enroll_voice(
        person_id,
        audio_array,
        source="identity_alias_refresh",
        confirmed=True,
    )

    def _enroll_face_biometric() -> None:
        try:
            from vision import camera as camera_mod
            from vision import face as face_mod

            if defer_face_enrollment or enroll_unknown_face:
                frame = camera_mod.capture_current_gaze(
                    settle_secs=float(
                        getattr(config, "IDENTITY_FACE_ENROLL_CURRENT_GAZE_SETTLE_SECS", 0.25)
                        or 0.0
                    )
                )
            else:
                frame = camera_mod.capture_still()
            if frame is None:
                return
            if enroll_unknown_face:
                face_enrolled = face_mod.enroll_unknown_face(person_id, frame)
            else:
                face_enrolled = face_mod.enroll_face(person_id, frame)
            if face_enrolled:
                threading.Thread(
                    target=face_mod.update_appearance,
                    args=(person_id, frame.copy()),
                    daemon=True,
                    name=f"appearance-enroll-{person_id}",
                ).start()
        except Exception as exc:
            _log.warning("face alias refresh failed for person_id=%s: %s", person_id, exc)

    if defer_face_enrollment:
        threading.Thread(
            target=_enroll_face_biometric,
            daemon=True,
            name=f"face-alias-enroll-{person_id}",
        ).start()
    else:
        _enroll_face_biometric()
    _bind_world_state_identity(person_id, person_name)


def _handle_pending_identity_match_confirmation(
    text: str,
    audio_array: np.ndarray,
) -> tuple[Optional[str], Optional[int], Optional[str]]:
    """Consume yes/no after Rex asks whether a weak name matched an existing person."""
    global _pending_identity_match_confirmation, _pending_common_first_name_identity

    ctx = _pending_identity_match_confirmation
    if not _identity_match_confirmation_fresh(ctx):
        _pending_identity_match_confirmation = None
        return None, None, None

    candidate = str(ctx.get("candidate_name") or "").strip()
    existing_id = ctx.get("existing_person_id")
    existing_name = str(ctx.get("existing_name") or "").strip()
    if not candidate or existing_id is None or not existing_name:
        _pending_identity_match_confirmation = None
        return None, None, None

    if _identity_confirmation_affirms(text):
        person_id = int(existing_id)
        stored_audio = ctx.get("audio")
        if (
            isinstance(stored_audio, np.ndarray)
            and len(stored_audio) > 0
            and isinstance(audio_array, np.ndarray)
            and len(audio_array) > 0
        ):
            enroll_audio = np.concatenate([stored_audio, audio_array])
        elif isinstance(stored_audio, np.ndarray) and len(stored_audio) > 0:
            enroll_audio = stored_audio
        elif isinstance(audio_array, np.ndarray) and len(audio_array) > 0:
            enroll_audio = audio_array
        else:
            enroll_audio = np.zeros(1, dtype=np.float32)

        try:
            people_memory.add_alias(
                person_id,
                candidate,
                source=f"confirmed_{ctx.get('match_type') or 'match'}",
            )
        except Exception as exc:
            _log.debug("confirmed alias save failed: %s", exc)
        _attach_identity_sample_to_person(
            person_id,
            existing_name,
            enroll_audio,
            enroll_unknown_face=bool(ctx.get("enroll_unknown_face")),
            defer_face_enrollment=bool(ctx.get("defer_face_enrollment")),
        )
        _retire_anonymous_speaker_slot(
            ctx.get("anonymous_speaker_label"),
            person_id=person_id,
            person_name=existing_name,
        )
        _pending_identity_match_confirmation = None
        response = (
            f"Ugh — my optical sensors must be on the fritz, I barely recognized you. "
            f"You ARE {existing_name}. Re-syncing your face and voice so it sticks this time."
        )
        return response, person_id, existing_name

    if _identity_confirmation_declines(text):
        _pending_identity_match_confirmation = None
        first_name = _first_name_or(_normalize_name(candidate) or candidate)
        if _name_word_count(candidate) >= 2:
            person_id = _enroll_new_person(
                candidate,
                ctx.get("audio") if isinstance(ctx.get("audio"), np.ndarray) else audio_array,
                enroll_unknown_face=bool(ctx.get("enroll_unknown_face")),
                defer_face_enrollment=bool(ctx.get("defer_face_enrollment")),
            )
            if person_id is not None:
                _mark_single_name_for_later_last_name(person_id, candidate)
                response = f"Got it. I'll save {candidate} as a separate person."
                return response, person_id, candidate
            return None, None, None

        _pending_common_first_name_identity = {
            "first_name": first_name,
            "audio": ctx.get("audio") if isinstance(ctx.get("audio"), np.ndarray) else audio_array.copy(),
            "asked_at": time.monotonic(),
            "prior_engagement": ctx.get("prior_engagement"),
            "anonymous_speaker_label": ctx.get("anonymous_speaker_label"),
        }
        response = (
            f"Got it. What's your last name so I don't mix you up with {existing_name}?"
        )
        return response, None, None

    return None, None, None


def _prompted_name_confirmation_fresh(ctx: Optional[dict]) -> bool:
    if not ctx:
        return False
    ttl = float(getattr(config, "COMMON_FIRST_NAME_LAST_NAME_WINDOW_SECS", 30.0))
    return (time.monotonic() - float(ctx.get("asked_at", 0.0))) <= max(1.0, ttl)


def _maybe_ask_prompted_name_confirmation(
    candidate_name: str,
    audio_array: np.ndarray,
    *,
    raw_text: str,
    prior_engagement: Optional[dict] = None,
    anonymous_speaker_label: Optional[str] = None,
    enroll_unknown_face: bool = False,
    defer_face_enrollment: bool = False,
) -> bool:
    """Ask before saving a prompted name when the transcript looks contaminated."""
    global _pending_prompted_name_confirmation, _identity_prompt_until, _session_exchange_count

    if not _prompted_name_reply_needs_confirmation(raw_text, candidate_name):
        return False

    _pending_prompted_name_confirmation = {
        "candidate_name": candidate_name,
        "raw_text": raw_text,
        "audio": audio_array.copy() if isinstance(audio_array, np.ndarray) else np.zeros(1, dtype=np.float32),
        "prior_engagement": prior_engagement,
        "anonymous_speaker_label": anonymous_speaker_label,
        "enroll_unknown_face": bool(enroll_unknown_face),
        "defer_face_enrollment": bool(defer_face_enrollment),
        "asked_at": time.monotonic(),
    }
    _identity_prompt_until = max(
        _identity_prompt_until,
        time.monotonic() + float(getattr(config, "COMMON_FIRST_NAME_LAST_NAME_WINDOW_SECS", 30.0)),
    )
    prompt = (
        f"I heard {candidate_name}. Do I save that, or did the microphone embarrass itself?"
    )
    _log.info(
        "[identity] asking prompted-name confirmation candidate=%r raw=%r",
        candidate_name,
        raw_text,
    )
    _speak_blocking(prompt, emotion="curious", pre_beat_ms=100, post_beat_ms_override=200)
    conv_memory.add_to_transcript("Rex", prompt)
    conv_log.log_rex(prompt)
    _session_exchange_count += 1
    _register_rex_utterance(prompt)
    return True


def _handle_pending_prompted_name_confirmation(
    text: str,
    audio_array: np.ndarray,
) -> tuple[Optional[str], Optional[int], Optional[str]]:
    """Consume yes/no after confirming a noisy prompted identity transcript."""
    global _pending_prompted_name_confirmation, _identity_prompt_until

    ctx = _pending_prompted_name_confirmation
    if not _prompted_name_confirmation_fresh(ctx):
        _pending_prompted_name_confirmation = None
        return None, None, None

    candidate = str(ctx.get("candidate_name") or "").strip()
    if not candidate:
        _pending_prompted_name_confirmation = None
        return None, None, None

    if _identity_confirmation_affirms(text):
        stored_audio = ctx.get("audio")
        if (
            isinstance(stored_audio, np.ndarray)
            and len(stored_audio) > 0
            and isinstance(audio_array, np.ndarray)
            and len(audio_array) > 0
        ):
            enroll_audio = np.concatenate([stored_audio, audio_array])
        elif isinstance(stored_audio, np.ndarray) and len(stored_audio) > 0:
            enroll_audio = stored_audio
        elif isinstance(audio_array, np.ndarray) and len(audio_array) > 0:
            enroll_audio = audio_array
        else:
            enroll_audio = np.zeros(1, dtype=np.float32)

        person_id = _enroll_new_person(
            candidate,
            enroll_audio,
            enroll_unknown_face=bool(ctx.get("enroll_unknown_face")),
            defer_face_enrollment=bool(ctx.get("defer_face_enrollment")),
        )
        _pending_prompted_name_confirmation = None
        _identity_prompt_until = 0.0
        if person_id is None:
            return None, None, None
        _retire_anonymous_speaker_slot(
            ctx.get("anonymous_speaker_label"),
            person_id=person_id,
            person_name=candidate,
        )
        _mark_single_name_for_later_last_name(person_id, candidate)
        return _identity_enrollment_ack(candidate), person_id, candidate

    if _identity_confirmation_declines(text):
        _pending_prompted_name_confirmation = None
        _identity_prompt_until = time.monotonic() + _IDENTITY_REPLY_WINDOW_SECS
        return (
            "Good. Then give me the name again, cleanly. Apparently the microphone wanted a solo.",
            None,
            None,
        )

    replacement = _extract_introduced_name(text, allow_bare_name=True)
    if replacement and not _prompted_name_reply_needs_confirmation(text, replacement):
        _pending_prompted_name_confirmation = None
        _identity_prompt_until = 0.0
        person_id = _enroll_new_person(
            replacement,
            audio_array,
            enroll_unknown_face=bool(ctx.get("enroll_unknown_face")),
            defer_face_enrollment=bool(ctx.get("defer_face_enrollment")),
        )
        if person_id is None:
            return None, None, None
        _retire_anonymous_speaker_slot(
            ctx.get("anonymous_speaker_label"),
            person_id=person_id,
            person_name=replacement,
        )
        _mark_single_name_for_later_last_name(person_id, replacement)
        return _identity_enrollment_ack(replacement), person_id, replacement

    return None, None, None


def _maybe_auto_refresh_voice(
    person_id: int,
    voice_score: float,
    audio_array: np.ndarray,
    *,
    face_confirmed: bool = False,
    raw_best_id: Optional[int] = None,
    visual_speaker_pid: Optional[int] = None,
) -> None:
    """
    Append the current audio as an additional voice biometric row for this person,
    up to a per-person cap, so the voiceprint improves over time without manual
    re-enrollment.

    Fires on EITHER a high voice score OR a confident FACE confirmation. The
    face-confirmed path is the important one: a returning user's voice scores low
    (~0.55), so the old "voice >= 0.90" gate never captured the exact hard samples
    that would improve the print. When the face is the ground truth, capture the
    sample even at a low voice score.

    TWO anti-pollution guards protect the face-confirmed path (a visible face is NOT
    proof this person is the one SPEAKING):
      1. The VOICE's own best candidate must already BE this person
         (``raw_best_id == person_id``). When someone off-camera or a not-yet-enrolled
         newcomer talks while a known face is in frame, their audio is rejected.
      2. The visual active-speaker latch must positively confirm this person is the
         one talking on camera (``visual_speaker_pid == person_id``), gated by
         ``AUTO_VOICE_REFRESH_REQUIRE_VISUAL_SPEAKER``. This is what stops a 3rd-party
         voice (a TTS/AI voice like ChatGPT, a TV, another person) that merely *scores*
         onto a visible person's print — passing guard 1 because it lands on that
         person — from re-broadening the print. Refresh is opportunistic, so when the
         camera cannot confirm the speaker the turn is simply skipped (a missed refresh
         is harmless; a poisoned print is not).
    Only strengthen a print with audio that BOTH the voice attributes to that person
    AND the camera confirms that person actually spoke.

    Runs asynchronously so re-embedding doesn't delay Rex's response. One refresh
    per person per session — EXCEPT while bootstrapping an empty/thin print (below
    AUTO_VOICE_BOOTSTRAP_MIN_SAMPLES), where Guard 1 is relaxed and the once-per-session
    budget is not consumed, so the print can build across several camera-confirmed turns.
    """
    if person_id is None:
        return
    # SAMPLE-QUALITY gate: a refresh sample becomes part of the centroid FOREVER — a
    # short or quiet VAD shard drags every future score down. Measured 2026-07-05: a
    # print diluted with live shards scored ~0.08 BELOW a fresh clean enroll across
    # every condition (0.742-0.830 vs 0.812-0.921), which is how "90%+ weeks ago"
    # decayed. Only long-enough, loud-enough audio may seed or strengthen a print
    # (applies to bootstrap too — a garbage first sample is the worst outcome).
    try:
        sr = float(getattr(config, "AUDIO_SAMPLE_RATE", 16000) or 16000)
        sample_secs = float(len(audio_array)) / max(sr, 1.0)
        sample_rms = float(np.sqrt(np.mean(np.asarray(audio_array, dtype=np.float64) ** 2)))
    except Exception:
        sample_secs, sample_rms = 0.0, 0.0
    min_secs = float(getattr(config, "AUTO_VOICE_REFRESH_MIN_SECS", 2.5))
    min_rms = float(getattr(config, "AUTO_VOICE_REFRESH_MIN_RMS", 0.008))
    if sample_secs < min_secs or sample_rms < min_rms:
        _log.debug(
            "[interaction] auto-refresh skipped: sample quality too low for a durable "
            "print (secs=%.2f < %.2f or rms=%.4f < %.4f) person_id=%s",
            sample_secs, min_secs, sample_rms, min_rms, person_id,
        )
        return
    max_samples = int(getattr(config, "AUTO_VOICE_REFRESH_MAX_SAMPLES", 5))
    # NATIVE-dimension prints only: after an embedder switch the stale legacy rows
    # (skipped by every matcher) must not eat the cap or mask an empty print —
    # they made the bootstrap unreachable (live-logged 2026-07-06-21-15).
    current = people_memory.count_native_voice_prints(person_id)
    if current >= max_samples:
        _voice_refreshed_this_session.add(person_id)  # don't keep checking
        return
    # BOOTSTRAP: a face+camera-confirmed speaker whose print is empty/thin (freshly wiped or never
    # enrolled) must be allowed to build one even though their voice currently matches SOMEONE ELSE —
    # that near-neighbor mismatch is the whole reason the print is thin (chicken-and-egg). While below
    # the floor we skip Guard 1 (voice-already-matches) but KEEP Guard 2 (camera confirms the talker),
    # and we do NOT consume the once-per-session budget, so a print can form across several turns.
    bootstrapping = bool(
        face_confirmed
        and getattr(config, "AUTO_VOICE_BOOTSTRAP_ENABLED", True)
        and current < int(getattr(config, "AUTO_VOICE_BOOTSTRAP_MIN_SAMPLES", 3))
    )
    if not bootstrapping and person_id in _voice_refreshed_this_session:
        return
    if face_confirmed:
        # Guard 2 — the visible face is not proof of SPEAKING. Require the camera to confirm this
        # person is the active on-camera talker, else a 3rd-party/AI voice that merely scores onto
        # their print would poison it. This is the SOLE protection while bootstrapping, so it always
        # applies (bootstrap included).
        require_visual = bool(
            getattr(config, "AUTO_VOICE_REFRESH_REQUIRE_VISUAL_SPEAKER", True)
        )
        if require_visual and _safe_int(visual_speaker_pid) != _safe_int(person_id):
            _log.debug(
                "[interaction] auto-refresh skipped: visual active-speaker did not "
                "confirm person_id=%s is the on-camera talker (visual_speaker=%s, "
                "score=%.3f, bootstrap=%s) — not seeding/strengthening the print with "
                "unconfirmed audio",
                person_id, visual_speaker_pid, voice_score, bootstrapping,
            )
            return
        # Guard 1 — only trust the SAMPLE if the voice already points at this person, otherwise we'd
        # be teaching their print someone else's voice. Skipped while bootstrapping (see above).
        if (
            not bootstrapping
            and raw_best_id is not None
            and _safe_int(raw_best_id) != _safe_int(person_id)
        ):
            return
    else:
        min_score = float(getattr(config, "AUTO_VOICE_REFRESH_MIN_SCORE", 0.90))
        if voice_score < min_score:
            return

    if not bootstrapping:
        _voice_refreshed_this_session.add(person_id)
    audio_copy = audio_array.copy()

    def _task() -> None:
        try:
            ok = _safe_enroll_voice(
                person_id,
                audio_copy,
                source="auto_voice_refresh",
                confirmed=True,
            )
            if ok:
                new_total = people_memory.count_native_voice_prints(person_id)
                _log.info(
                    "[interaction] auto-refreshed voice biometric for person_id=%s "
                    "(score=%.3f, now %d native sample(s))",
                    person_id, voice_score, new_total,
                )
        except Exception as exc:
            _log.warning("auto-refresh voice enrollment failed: %s", exc)

    threading.Thread(
        target=_task, daemon=True, name=f"auto-voice-refresh-{person_id}"
    ).start()


def _enroll_new_person(
    name: str,
    audio_array: np.ndarray,
    enroll_unknown_face: bool = False,
    defer_face_enrollment: bool = False,
) -> Optional[int]:
    """
    Enroll a brand-new person and attach available voice/face biometrics.
    Returns person_id on success.

    If enroll_unknown_face=True, use face_mod.enroll_unknown_face which picks
    the largest face NOT already matched to an existing known person. Use this
    when a known person is visible alongside the newcomer so we don't rebind
    the known person's face to the new name.

    Refuses outright when the transcript this turn came from was one Whisper was
    guessing at. A misheard name is not a small error: it mints a permanent person
    with a voiceprint and a face attached, and every later sighting of the real
    human keeps colliding with the phantom.
    """
    if not _turn_transcript_trusted():
        _log.warning(
            "[interaction] refusing to enroll %r — the transcript it came from was "
            "low-confidence. Rex will ask again rather than invent a person.", name,
        )
        return None
    person_id, created = people_memory.find_or_create_person(name)
    if person_id is None:
        _log.error("failed to enroll new person row for name=%r", name)
        return None

    first_inc = config.FAMILIARITY_INCREMENTS.get("first_enrollment", 0.0)
    if created and first_inc > 0:
        people_memory.update_familiarity(person_id, first_inc)

    _safe_enroll_voice(
        person_id,
        audio_array,
        source="new_person",
        confirmed=True,
    )

    def _enroll_face_biometric() -> None:
        try:
            from vision import camera as camera_mod
            from vision import face as face_mod

            if defer_face_enrollment or enroll_unknown_face:
                frame = camera_mod.capture_current_gaze(
                    settle_secs=float(
                        getattr(config, "IDENTITY_FACE_ENROLL_CURRENT_GAZE_SETTLE_SECS", 0.25)
                        or 0.0
                    )
                )
            else:
                frame = camera_mod.capture_still()
            if frame is not None:
                if enroll_unknown_face:
                    face_enrolled = face_mod.enroll_unknown_face(person_id, frame)
                else:
                    face_enrolled = face_mod.enroll_face(person_id, frame)
                if face_enrolled:
                    # Appearance extraction is useful but non-blocking.
                    threading.Thread(
                        target=face_mod.update_appearance,
                        args=(person_id, frame.copy()),
                        daemon=True,
                        name=f"appearance-enroll-{person_id}",
                    ).start()
        except Exception as exc:
            _log.warning("face enrollment failed for person_id=%s: %s", person_id, exc)

    if defer_face_enrollment:
        threading.Thread(
            target=_enroll_face_biometric,
            daemon=True,
            name=f"face-enroll-{person_id}",
        ).start()
    else:
        _enroll_face_biometric()

    _bind_world_state_identity(person_id, name)
    _log.info("[interaction] enrolled new person: %s (person_id=%s)", name, person_id)
    _episodic_person_enrolled(person_id, name, created=created)
    # Arm the first-meeting baseline burst (no-op unless ONBOARDING_ENABLED and
    # the person is a brand-new, non-minor, near-empty profile). The opener fires
    # from the idle loop a beat after the enrollment ack.
    try:
        _maybe_begin_onboarding(person_id, name)
    except Exception as exc:
        _log.debug("[onboarding] begin failed: %s", exc)
    return person_id


_INTRO_INVERSE_RELATIONSHIP = {
    "father": "child",
    "mother": "child",
    "parent": "child",
    "dad": "child",
    "mom": "child",
    "aunt": "niece_or_nephew",
    "uncle": "niece_or_nephew",
    "nephew": "aunt_or_uncle",
    "niece": "aunt_or_uncle",
    "boss": "employee",
    "supervisor": "employee",
    "manager": "employee",
    "dog": "owner",
    "cat": "owner",
    "pet": "owner",
}
_INTRO_SYMMETRIC_RELATIONSHIPS = {
    "friend", "best_friend", "partner", "girlfriend", "boyfriend", "wife",
    "husband", "spouse", "sister", "brother", "sibling", "cousin",
    "coworker", "colleague", "roommate", "neighbor", "fiance", "fiancee",
}
_INTRO_SELF_EXPLANATORY_RELATIONSHIPS = {
    "father", "mother", "parent", "dad", "mom", "son", "daughter", "child",
    "aunt", "uncle", "niece", "nephew", "cousin",
    "grandfather", "grandmother", "grandparent",
    "brother", "sister", "sibling", "wife", "husband", "spouse",
    "partner", "girlfriend", "boyfriend", "fiance", "fiancee",
}


def _intro_relationship_self_explanatory(relationship: Optional[str]) -> bool:
    rel = (relationship or "").strip().lower().replace(" ", "_")
    return rel in _INTRO_SELF_EXPLANATORY_RELATIONSHIPS


def _intro_relationship_question_instruction(
    relationship: Optional[str],
    introducer_first: str,
    introduced_first: str,
) -> str:
    # Curiosity goes to the NEWCOMER about THEMSELVES. Rex is meeting a new person and
    # is supposed to get to know THEM — not interview the introducer by proxy (the
    # live "ask about Bret's origin story / cool-uncle-award" miss where Rex never got
    # curious about the nephew). `relationship`/`introducer_first` are kept in the
    # signature for callers but no longer steer the question toward the introducer.
    return (
        f"Then turn genuine curiosity on {introduced_first} and ask THEM exactly one "
        f"easy get-to-know-you question about themselves — what they do, where "
        f"they're from, or what they're into. Make {introduced_first} the subject."
    )


def _intro_inverse_relationship(relationship: Optional[str]) -> str:
    rel = (relationship or "acquaintance").strip().lower()
    if rel in _INTRO_SYMMETRIC_RELATIONSHIPS:
        return rel
    return _INTRO_INVERSE_RELATIONSHIP.get(rel, "acquaintance")


def _store_introduction_memories(
    introducer_id: int,
    introducer_name: str,
    introduced_id: int,
    introduced_name: str,
    relationship: Optional[str],
) -> None:
    if int(introducer_id) == int(introduced_id):
        _log.warning(
            "[introduction] refusing self-relationship for person_id=%s relationship=%r",
            introducer_id,
            relationship,
        )
        return
    rel = (relationship or "acquaintance").strip().lower()
    inverse = _intro_inverse_relationship(rel)
    try:
        from memory import social as social_memory
        social_memory.save_relationship(
            from_person_id=introducer_id,
            to_person_id=introduced_id,
            relationship=rel,
            described_by=introducer_id,
        )
    except Exception as exc:
        _log.warning("introduction relationship save failed: %s", exc)

    try:
        facts_memory.add_fact(
            introducer_id,
            "relationship",
            f"relationship_to_{introduced_id}",
            f"{introduced_name} is {introducer_name}'s {rel}",
            "explicit_introduction",
            confidence=0.95,
        )
        facts_memory.add_fact(
            introduced_id,
            "relationship",
            f"relationship_to_{introducer_id}",
            f"{introducer_name} is {introduced_name}'s {inverse}",
            "explicit_introduction",
            confidence=0.90,
        )
    except Exception as exc:
        _log.debug("introduction fact save failed: %s", exc)


def _enroll_introduced_person(
    name: str,
    introducer_id: int,
    introducer_name: str,
    relationship: Optional[str],
    *,
    enroll_visible_face: bool = True,
) -> Optional[int]:
    try:
        new_id, created = people_memory.find_or_create_person(name)
    except Exception as exc:
        _log.warning("introduction find_or_create_person failed: %s", exc)
        return None
    if new_id is None:
        return None

    first_inc = config.FAMILIARITY_INCREMENTS.get("first_enrollment", 0.0)
    if created and first_inc > 0:
        people_memory.update_familiarity(new_id, first_inc)

    face_enrolled = False
    if enroll_visible_face:
        try:
            from vision import camera as camera_mod
            from vision import face as face_mod
            frame = camera_mod.capture_still()
            if frame is not None:
                face_enrolled = face_mod.enroll_unknown_face(new_id, frame)
                if face_enrolled:
                    threading.Thread(
                        target=face_mod.update_appearance,
                        args=(new_id, frame.copy()),
                        daemon=True,
                        name=f"appearance-enroll-{new_id}",
                    ).start()
        except Exception as exc:
            _log.warning("introduction face enrollment failed: %s", exc)

    if face_enrolled:
        _bind_world_state_identity(new_id, name)
    _store_introduction_memories(
        introducer_id,
        introducer_name,
        new_id,
        name,
        relationship,
    )
    _episodic_person_enrolled(new_id, name, created=created)
    return new_id


def _store_pet_introduction(
    owner_id: int,
    owner_name: str,
    pet_name: Optional[str],
    relationship: Optional[str],
) -> None:
    species = relationship or "pet"
    value = f"{pet_name} ({species})" if pet_name else species
    key = f"pet_{(pet_name or species).lower().replace(' ', '_')}"
    facts_memory.add_fact(
        owner_id,
        "pet",
        key,
        value,
        "explicit_introduction",
        confidence=0.95,
    )
    _log.info(
        "[introduction] stored pet intro for %s: %s",
        owner_name,
        value,
    )


def _intro_ack_and_followup(
    introducer_id: int,
    introducer_name: str,
    introduced_id: Optional[int],
    introduced_name: str,
    relationship: Optional[str],
    *,
    subject_kind: str = "person",
    visible_newcomer: bool = True,
) -> str:
    global _pending_intro_followup, _pending_intro_voice_capture

    introducer_first = _first_name_or(introducer_name, "there")
    introduced_first = _first_name_or(introduced_name, "there")
    rel_clause = f"{relationship}" if relationship else "guest"
    self_explanatory_relationship = _intro_relationship_self_explanatory(relationship)
    followup_kind = (
        "relationship_color" if self_explanatory_relationship else "connection_story"
    )
    special_context = (
        person_specials.special_prompt_context(introduced_name)
        if visible_newcomer
        else None
    )
    if person_specials.is_jt_volleyball_celebrity(introduced_name):
        special_quip_instruction = (
            f"acknowledge {introduced_first} by name as a major volleyball "
            "celebrity with one affectionate joke about getting old, bones, "
            "or muscles."
        )
    elif person_specials.is_rex_creator(introduced_name):
        special_quip_instruction = (
            "acknowledge Bret Benziger by name as Rex's creator and maker. Be "
            "warm, reverent, loyal, and still dryly Rex about being Bret's "
            "high-maintenance droid creation."
        )
    elif person_specials.is_pj_kings_celebrity(introduced_name):
        special_quip_instruction = (
            f"acknowledge {introduced_first} by name as Sacramento Kings "
            "royalty with one affectionate joke about the beam, a cowbell, or "
            "purple loyalty."
        )
    elif person_specials.is_galactic_hair_stylist(introduced_name):
        special_quip_instruction = (
            f"acknowledge {introduced_first} by name as one of the greatest "
            "hair stylists in the galactic quadrant with one affectionate "
            "joke about legendary styling skills, blowouts, bangs, or frizz."
        )
    else:
        special_quip_instruction = f"acknowledge {introduced_first} by name."

    if special_context and self_explanatory_relationship:
        question_instruction = _intro_relationship_question_instruction(
            relationship,
            introducer_first,
            introduced_first,
        )
        prompt = (
            f"{introducer_first} just explicitly introduced {introduced_first} "
            f"as {introducer_first}'s {rel_clause}. {special_context} "
            f"In one or two short in-character Rex sentences, "
            f"{special_quip_instruction} {question_instruction} Address "
            f"{introduced_first}, not {introducer_first}. Do NOT ask how they "
            "know each other."
        )
    elif special_context:
        prompt = (
            f"{introducer_first} just explicitly introduced {introduced_first} "
            f"as their {rel_clause}. {special_context} In ONE short "
            f"in-character Rex line, {special_quip_instruction} Then turn curiosity "
            f"on {introduced_first} and ask THEM one easy get-to-know-you question "
            f"about themselves (what they do, where they're from, or what they're "
            f"into). Address {introduced_first} directly, not {introducer_first}."
        )
    elif visible_newcomer and self_explanatory_relationship:
        question_instruction = _intro_relationship_question_instruction(
            relationship,
            introducer_first,
            introduced_first,
        )
        prompt = (
            f"{introducer_first} just explicitly introduced {introduced_first} "
            f"as {introducer_first}'s {rel_clause}. This already explains their "
            f"relationship. In one or two short in-character Rex sentences, acknowledge "
            f"{introduced_first} by name with a funny but friendly quip about "
            f"their connection to {introducer_first}. {question_instruction} "
            f"Address {introduced_first}, not {introducer_first}. Do NOT ask how "
            f"they know each other. Do NOT imply {introduced_first} is related to Rex."
        )
    elif visible_newcomer:
        prompt = (
            f"{introducer_first} just introduced {introduced_first} as their "
            f"{rel_clause} — someone you are meeting for the FIRST time. You want to "
            f"get to know {introduced_first}. In one or two short in-character Rex "
            f"sentences: greet {introduced_first} by name with a warm, funny beat, "
            f"THEN ask {introduced_first} ONE easy get-to-know-you question about "
            f"THEMSELVES — what they do, where they're from, or what they're into. "
            f"Address {introduced_first} directly. Do NOT make this about Rex, do NOT "
            f"ask a rhetorical question about {introducer_first}, and do NOT merely "
            f"ask how they know each other. Warm and conversational, not mean."
        )
    else:
        prompt = (
            f"{introducer_first} just explicitly introduced {introduced_first} "
            f"as their {rel_clause}, but {introduced_first} is not visible on camera "
            f"right now. In ONE short in-character Rex line, START with exactly "
            f"'Nice to meet you, {introduced_first}.' Then invite {introduced_first} "
            f"to say a quick hello so you can learn their voice. Do not address "
            f"{introducer_first} as if they are the newcomer, and do not ask how "
            f"they know each other yet."
        )
    # If someone pre-briefed Rex on this person before they ever visited
    # ("tell me about my coworker Daniel"), let the welcome acknowledge it.
    heard_from = _told_about_teller_name(introduced_id)
    if heard_from:
        prompt += (
            f" Important: you were already briefed about {introduced_first} by "
            f"{heard_from} before this meeting. Work in ONE light "
            f"'so you're the famous {introduced_first}' beat — but never reveal "
            "specifics from the file and never anything unkind."
        )
    try:
        # Generate AS the newcomer's turn (person_id=introduced_id) so the system
        # prompt frames Wade as the person Rex is meeting and getting to know, rather
        # than person_id=None (which gave a Bret-only cast and a Rex-centric drift).
        text = llm.get_response(prompt, introduced_id) or ""
    except Exception as exc:
        _log.debug("intro ack generation failed: %s", exc)
        text = ""
    if not text:
        special_ack = person_specials.special_intro_ack(introduced_name)
        if special_ack:
            text = f"{special_ack} So what's your story — what do you do?"
        elif self_explanatory_relationship:
            text = (
                f"{introduced_first}, welcome. So you're {introducer_first}'s "
                f"{rel_clause} — that explains a few things. What's your story; "
                f"what do you do when you're not being introduced to droids?"
            )
        else:
            text = (
                f"{introduced_first}, welcome to the frequency. So what's your "
                f"deal — what are you into?"
            )
    if not visible_newcomer and not text.lower().startswith("nice to meet you"):
        text = (
            f"Nice to meet you, {introduced_first}. Give me a quick hello so "
            f"I can file your voice somewhere more useful than 'mystery guest.'"
        )

    if introduced_id is not None and subject_kind == "person":
        pending = {
            "introducer_id": introducer_id,
            "introducer_name": introducer_name,
            "introduced_id": introduced_id,
            "introduced_name": introduced_name,
            "relationship": relationship,
            "followup_kind": followup_kind,
            "asked_at": time.monotonic(),
        }
        if not visible_newcomer:
            _pending_intro_voice_capture = dict(pending)
        else:
            _pending_intro_followup = pending
        try:
            consciousness.note_person_greeted_this_session(introduced_id)
        except Exception:
            pass
    return text


def _intro_voice_capture_fresh(ctx: Optional[dict]) -> bool:
    if not ctx:
        return False
    ttl = float(getattr(config, "INTRO_VOICE_CAPTURE_WINDOW_SECS", 45.0))
    return (time.monotonic() - float(ctx.get("asked_at") or 0.0)) <= ttl


def _intro_capture_window_open() -> bool:
    """True while Rex is actively waiting for a just-introduced NEWCOMER to speak.

    During this window Rex literally asked the new person to say hello, so the
    next voice is expected to be them — NOT the introducer, even if the
    introducer's face is still (or recently) on camera. Callers use this to stop
    a sticky/visible introducer face from capturing the newcomer's turn.
    """
    return _intro_voice_capture_fresh(_pending_intro_voice_capture)


def _intro_voice_text_sounds_like_newcomer(text: str, name: str) -> bool:
    cleaned = (text or "").strip().lower()
    if not cleaned:
        return False
    if re.search(r"\b(no|nope|not now|not here|later|wait|hold on|can't|cannot)\b", cleaned):
        return False
    first = _first_name_or(name).lower()
    if first and re.search(rf"\b(this is|that is|that's)\s+{re.escape(first)}\b", cleaned):
        return False
    if re.search(r"\b(he|she|they)\s+(is|isn't|was|wasn't|can't|cannot|will|won't)\b", cleaned):
        return False
    if re.search(r"\b(hi|hello|hey|yo|nice to meet|what'?s up|i'?m|i am|my name is)\b", cleaned):
        return True
    words = re.findall(r"[a-z']+", cleaned)
    return 0 < len(words) <= 8


def _bind_intro_visible_face_if_present(person_id: int, name: str) -> None:
    if not _has_unknown_visible_person():
        return
    try:
        from vision import camera as _cam_mod
        from vision import face as _face_mod
        frame = _cam_mod.capture_still()
        if frame is None:
            return
        if _face_mod.enroll_unknown_face(person_id, frame):
            threading.Thread(
                target=_face_mod.update_appearance,
                args=(person_id, frame.copy()),
                daemon=True,
                name=f"appearance-enroll-{person_id}",
            ).start()
            _bind_world_state_identity(person_id, name)
    except Exception as exc:
        _log.warning("introduction visible face bind failed: %s", exc)


def _handle_intro_voice_capture(
    text: str,
    audio_array: np.ndarray,
    person_id: Optional[int],
    raw_best_id: Optional[int],
    speaker_score: float,
) -> Optional[str]:
    global _pending_intro_voice_capture, _pending_intro_followup

    ctx = _pending_intro_voice_capture
    if ctx is None:
        return None
    if not _intro_voice_capture_fresh(ctx):
        _log.info("[introduction] voice capture window expired for %s", ctx.get("introduced_name"))
        _pending_intro_voice_capture = None
        return None

    introduced_id = int(ctx["introduced_id"])
    introduced_name = ctx.get("introduced_name") or "the newcomer"
    introducer_id = ctx.get("introducer_id")
    introducer_name = ctx.get("introducer_name") or "the introducer"
    relationship = ctx.get("relationship")
    self_explanatory_relationship = _intro_relationship_self_explanatory(relationship)
    followup_kind = (
        "relationship_color" if self_explanatory_relationship else "connection_story"
    )

    if person_id == introduced_id:
        _pending_intro_voice_capture = None
        followup = dict(ctx)
        followup["followup_kind"] = followup_kind
        followup["asked_at"] = time.monotonic()
        _pending_intro_followup = followup
        return None

    # If the live speaker CONFIDENTLY resolves to the INTRODUCER, this utterance
    # cannot be the newcomer's voice sample — never enroll it onto the newcomer.
    # This closes the [SPEAKER_ID_CONFIDENT_THRESHOLD,
    # INTRO_VOICE_INTRODUCER_CONFIDENT_THRESHOLD) band where identity said
    # "confidently the introducer" (e.g. 0.707 >= 0.70) yet the intro gate's 0.75
    # bar still called it "weak" and enrolled the introducer's voice onto a
    # phantom newcomer (live-logged 2026-06-18: Bret's correction enrolled onto
    # phantom "Leaf"). NOTE: keep INTRO_VOICE_INTRODUCER_CONFIDENT_THRESHOLD >=
    # SPEAKER_ID_CONFIDENT_THRESHOLD or this band reopens.
    # Guard floor is DECOUPLED from SPEAKER_ID_CONFIDENT_THRESHOLD: when that
    # global was raised 0.70 -> 0.75 the [0.70, 0.75) band silently reopened and a
    # 0.707 introducer match again enrolled the INTRODUCER'S voice onto the
    # newcomer — the exact voiceprint-twin poisoning this guard was built against.
    confident_id_threshold = min(
        float(getattr(config, "SPEAKER_ID_CONFIDENT_THRESHOLD", 0.70)),
        float(getattr(config, "INTRO_VOICE_INTRODUCER_GUARD_FLOOR", 0.70)),
    )
    if (
        introducer_id is not None
        and person_id == introducer_id
        and raw_best_id == introducer_id
        and float(speaker_score or 0.0) >= confident_id_threshold
    ):
        _log.info(
            "[introduction] intro voice-capture: live speaker is confidently the "
            "introducer (score=%.3f) — not enrolling onto newcomer %s",
            float(speaker_score or 0.0),
            introduced_name,
        )
        return None

    # Rex just invited the NEWCOMER to speak ("say hi so I can learn your
    # voice"), so the next short hello is overwhelmingly likely to be them — not
    # the introducer. Speaker-ID, hearing an unfamiliar voice with no print yet,
    # tends to land it on the nearest known print (the introducer) at a mediocre
    # score. Only a CONFIDENT introducer match should be believed over the
    # window's expectation; below that, treat the reply as the newcomer and
    # enroll it. Using the bare similarity floor (0.50) here made the window
    # useless — the off-camera newcomer scored ~0.59–0.64 as the introducer and
    # was never enrolled (live-logged 2026-06-15: "hi what's your name" credited
    # to the introducer, who then introduced himself to his own guest).
    confident_introducer_threshold = float(
        getattr(config, "INTRO_VOICE_INTRODUCER_CONFIDENT_THRESHOLD", 0.75)
    )
    looks_like_newcomer = _intro_voice_text_sounds_like_newcomer(text, introduced_name)
    accepted_unknown = person_id is None
    weak_introducer_match = (
        person_id == introducer_id
        and raw_best_id == introducer_id
        and speaker_score < confident_introducer_threshold
        and looks_like_newcomer
    )
    if not accepted_unknown and not weak_introducer_match:
        return None

    if not looks_like_newcomer and not accepted_unknown:
        return None

    ok = _safe_enroll_voice(
        introduced_id,
        audio_array,
        transcript_text=text,
        source="intro_voice_capture",
        confirmed=False,
    )
    if not ok:
        ctx["asked_at"] = time.monotonic()
        first = _first_name_or(introduced_name)
        return (
            f"{first}, my voice scanner got a mouthful of static. Give me one "
            f"more sentence so I can stop calling you theoretical."
        )

    _pending_intro_voice_capture = None
    followup = dict(ctx)
    followup["followup_kind"] = followup_kind
    followup["asked_at"] = time.monotonic()
    _pending_intro_followup = followup
    _bind_intro_visible_face_if_present(introduced_id, introduced_name)
    _log.info(
        "[introduction] enrolled voice for introduced person %r (person_id=%s)",
        introduced_name,
        introduced_id,
    )
    try:
        _session_person_ids.add(introduced_id)
        consciousness.mark_engagement(introduced_id)
        consciousness.note_person_spoke(introduced_id)
    except Exception:
        pass
    try:
        conv_memory.add_to_transcript(introduced_name, text)
        conv_log.log_heard(introduced_name, text)
        print(
            f"[VOICE] Known voice detected: {introduced_name} (person_id={introduced_id})",
            flush=True,
        )
        print(f"[HEARD] {introduced_name}: {text}", flush=True)
        _log.info(
            "[introduction] voice capture speech segment — speaker=%r person_id=%s text=%r",
            introduced_name,
            introduced_id,
            text,
        )
    except Exception as exc:
        _log.debug("intro voice capture transcript log failed: %s", exc)
    try:
        topic_thread.note_user_turn(text, introduced_id)
        user_energy.note_user_turn(text, introduced_id)
    except Exception as exc:
        _log.debug("intro voice capture turn tracking failed: %s", exc)

    intro_first = _first_name_or(introducer_name, "there")
    introduced_first = _first_name_or(introduced_name, "there")
    try:
        if self_explanatory_relationship:
            question_instruction = _intro_relationship_question_instruction(
                relationship,
                intro_first,
                introduced_first,
            )
            return llm.get_response(
                f"{introduced_first} just responded after {intro_first} introduced "
                f"them as {intro_first}'s {relationship}. You successfully stored "
                f"{introduced_first}'s voice print. In one or two short "
                f"in-character Rex sentences, acknowledge {introduced_first} by "
                f"name with a friendly quip. {question_instruction} Do NOT ask "
                f"how they know each other. Do NOT imply they are related to Rex."
            )
        return llm.get_response(
            f"{introduced_first} just responded after {intro_first} introduced them, "
            f"and you successfully stored {introduced_first}'s voice print. In ONE "
            f"short in-character Rex line, acknowledge {introduced_first} by name "
            f"with a light quip, then ask how {introduced_first} and {intro_first} "
            f"know each other."
        )
    except Exception as exc:
        _log.debug("intro voice capture ack generation failed: %s", exc)
    if self_explanatory_relationship:
        return (
            f"Got it, {introduced_first}. Voice filed. What should I know about "
            f"{intro_first} from your side of the evidence locker?"
        )
    return f"Got it, {introduced_first}. Voice filed. So how did you and {intro_first} get tangled up?"


def _handle_intro_followup_answer(text: str) -> Optional[str]:
    global _pending_intro_followup

    ctx = _pending_intro_followup
    if not introductions.followup_fresh(ctx):
        _pending_intro_followup = None
        return None
    if not introductions.should_capture_followup(text):
        return None

    _pending_intro_followup = None
    intro_id = int(ctx["introducer_id"])
    introduced_id = int(ctx["introduced_id"])
    if intro_id == introduced_id:
        _log.warning(
            "[introduction] refusing intro followup for self relationship person_id=%s text=%r",
            intro_id,
            text,
        )
        return None
    intro_name = ctx.get("introducer_name") or "the introducer"
    introduced_name = ctx.get("introduced_name") or "the newcomer"
    relationship = ctx.get("relationship")
    followup_kind = ctx.get("followup_kind") or "connection_story"
    detail = text.strip()

    try:
        if followup_kind == "relationship_color":
            rel_phrase = f" ({relationship})" if relationship else ""
            fact_key_a = f"intro_note_{introduced_id}"
            fact_key_b = f"intro_note_{intro_id}"
            source = "relationship_color_followup"
            value = f"{intro_name} introduced {introduced_name}{rel_phrase}: {detail}"
        else:
            fact_key_a = f"connection_story_{introduced_id}"
            fact_key_b = f"connection_story_{intro_id}"
            source = "introduction_followup"
            value = f"{intro_name} and {introduced_name}: {detail}"
        facts_memory.add_fact(
            intro_id,
            "relationship",
            fact_key_a,
            value,
            source,
            confidence=0.90,
        )
        facts_memory.add_fact(
            introduced_id,
            "relationship",
            fact_key_b,
            value,
            source,
            confidence=0.90,
        )
        _log.info(
            "[introduction] stored intro followup (%s) for person_id=%s and person_id=%s: %r",
            followup_kind,
            intro_id,
            introduced_id,
            detail,
        )
    except Exception as exc:
        _log.debug("intro followup fact save failed: %s", exc)

    try:
        if followup_kind == "relationship_color":
            return llm.get_response(
                f"You asked a light introduction question after learning "
                f"{introduced_name} is {intro_name}'s {relationship or 'person'}. "
                f"They answered: '{detail}'. In ONE short Rex line, acknowledge "
                f"the detail with a light quip. No new question."
            )
        return llm.get_response(
            f"You just learned how {intro_name} and {introduced_name} know each "
            f"other: '{detail}'. In ONE short Rex line, acknowledge the story "
            f"with a light quip. No new question."
        )
    except Exception as exc:
        _log.debug("intro followup ack generation failed: %s", exc)
    return "Noted. Another organic relationship filed under suspicious but charming."


def _resolve_existing_visible_introduced_person(
    name: Optional[str],
    introducer_id: Optional[int],
) -> Optional[tuple[int, str]]:
    """Return a known visible/recent person matching an introduced name."""
    candidate_name = _normalize_name(name or "")
    if not candidate_name:
        return None
    try:
        existing = people_memory.find_person_by_name(candidate_name)
    except Exception as exc:
        _log.debug("introduction existing-person lookup failed: %s", exc)
        return None
    if not existing:
        return None
    try:
        existing_id = int(existing["id"])
    except Exception:
        return None
    if introducer_id is not None and existing_id == int(introducer_id):
        return None
    if not _known_person_visible_recently(existing_id):
        return None
    existing_name = _normalize_name(str(existing.get("name") or "")) or candidate_name
    return existing_id, existing_name


def _handle_introduction_parse(
    parsed: introductions.IntroductionParse,
    *,
    introducer_id: int,
    introducer_name: str,
    visible_newcomer: bool = True,
) -> Optional[str]:
    global _pending_introduction, _pending_common_first_name_introduction

    if parsed.subject_kind == "pet":
        _store_pet_introduction(
            introducer_id,
            introducer_name,
            parsed.name,
            parsed.relationship,
        )
        pet_name = parsed.name or f"your {parsed.relationship or 'pet'}"
        try:
            return llm.get_response(
                f"{introducer_name} just introduced {pet_name}, their "
                f"{parsed.relationship or 'pet'}. In ONE short friendly Rex "
                f"line, acknowledge the pet by name/species with a tiny quip. "
                f"No follow-up question."
            )
        except Exception:
            return f"{pet_name}, welcome. Finally, a civilized member of the party."

    if not parsed.name:
        _pending_introduction = {
            "introducer_id": introducer_id,
            "introducer_name": introducer_name,
            "relationship": parsed.relationship,
            "visible_newcomer": visible_newcomer,
            "created_at": time.monotonic(),
            "asked_at": time.monotonic(),
        }
        introductions.note_introduction()  # stand down the mystery-guest agenda
        rel_hint = f" your {parsed.relationship}" if parsed.relationship else ""
        try:
            if parsed.relationship:
                relationship_label = str(parsed.relationship).replace("_", " ")
                intro_clause = (
                    f"this visible newcomer is {introducer_name}'s {relationship_label}"
                    if visible_newcomer
                    else f"they want you to meet their {relationship_label}"
                )
                return llm.get_response(
                    f"{introducer_name} said {intro_clause}, "
                    f"but did not give the person's name yet. In ONE short "
                    f"in-character Rex line, ask {introducer_name} ONLY for the "
                    f"newcomer's name. Do NOT ask how they are related. Do NOT "
                    f"imply the newcomer is related to Rex."
                )
            return llm.get_response(
                f"{introducer_name} said they want to introduce you to{rel_hint} "
                f"someone, and an unknown face is visible, but you do not have "
                f"the person's name yet. In ONE short in-character Rex line, "
                f"ask {introducer_name} for the newcomer's name and relationship. "
                f"Make it feel like a real introduction, not a form."
            )
        except Exception:
            if parsed.relationship:
                return f"Got the {parsed.relationship} part. What name am I filing for them?"
            return "Fine, I see the mystery organic. What name and relationship am I filing under?"

    existing_intro = _resolve_existing_visible_introduced_person(
        parsed.name,
        introducer_id,
    )
    if existing_intro is not None:
        existing_id, existing_name = existing_intro
        _pending_introduction = None
        _store_introduction_memories(
            introducer_id,
            introducer_name,
            existing_id,
            existing_name,
            parsed.relationship,
        )
        _log.info(
            "[introduction] matched existing visible/recent person %s "
            "(person_id=%s) as %s of %s",
            existing_name,
            existing_id,
            parsed.relationship or "acquaintance",
            introducer_name,
        )
        return _intro_ack_and_followup(
            introducer_id,
            introducer_name,
            existing_id,
            existing_name,
            parsed.relationship,
            subject_kind=parsed.subject_kind,
            visible_newcomer=True,
        )

    new_id = _enroll_introduced_person(
        parsed.name,
        introducer_id,
        introducer_name,
        parsed.relationship,
        enroll_visible_face=visible_newcomer,
    )
    if new_id is None:
        return None
    _pending_introduction = None
    _mark_single_name_for_later_last_name(new_id, parsed.name)
    _log.info(
        "[introduction] %s introduced %s as %s (person_id=%s)",
        introducer_name,
        parsed.name,
        parsed.relationship or "acquaintance",
        new_id,
    )
    return _intro_ack_and_followup(
        introducer_id,
        introducer_name,
        new_id,
        parsed.name,
        parsed.relationship,
        subject_kind=parsed.subject_kind,
        visible_newcomer=visible_newcomer,
    )


# ─────────────────────────────────────────────────────────────────────────────
# "Tell me about someone" pre-briefing flow
# ─────────────────────────────────────────────────────────────────────────────

def tell_about_flow_active() -> bool:
    """True while a 'tell me about someone' briefing is open and fresh.

    speech_engine.can_proactive_speak consults this so NO proactive line —
    salient or not — can barge into an active briefing (live-logged failure:
    idle banter hijacked the flow mid-collection and the re-anchor question
    had to clean up). The re-anchor hook stays as the backstop for reactive
    lines that aren't proactive speech."""
    state = _pending_tell_about
    if state is None:
        return False
    try:
        return tell_me_about.flow_fresh(state)
    except Exception:
        return False


def _maybe_tell_about_timeout() -> bool:
    """Close a stalled briefing OUT LOUD instead of letting it linger.

    If the teller gives no input for TELL_ABOUT_INACTIVITY_TIMEOUT_SECS while
    a briefing is open, Rex says the file is logged and exits the mode (it
    previously sat silent until the 240s step TTL ate the flow — with all
    idle filler now suppressed during the flow, nothing else would break the
    silence). Returns True when it closed the flow and queued the line."""
    global _pending_tell_about
    state = _pending_tell_about
    if state is None:
        return False
    timeout = float(getattr(config, "TELL_ABOUT_INACTIVITY_TIMEOUT_SECS", 30.0))
    if timeout <= 0:
        return False
    last = float(state.get("asked_at") or state.get("created_at") or 0.0)
    if last <= 0 or (time.monotonic() - last) < timeout:
        return False
    try:
        # Don't time the teller out while Rex himself still holds the floor.
        if speech_queue.is_speaking() or output_gate.is_busy():
            return False
    except Exception:
        pass

    subject_first = _first_name_or(state.get("subject_name") or "", "them")
    details = int(state.get("details_count") or 0)
    _pending_tell_about = None
    if state.get("subject_name"):
        line = tell_me_about.closer_line(subject_first, details)
    else:
        line = tell_me_about.cancel_line()
    _log.info(
        "[tell_about] inactivity timeout (%.0fs) — flow closed out loud "
        "subject=%r details=%s",
        timeout, state.get("subject_name"), details,
    )
    try:
        speech_queue.enqueue(line, "neutral", priority=0, tag="tell_about:timeout")
        conv_memory.add_to_transcript("Rex", line)
        conv_log.log_rex(line)
    except Exception as exc:
        _log.debug("[tell_about] timeout close speak failed: %s", exc)
    return True


def _handle_tell_about_turn(
    text: str,
    teller_id: Optional[int],
    teller_name: Optional[str],
) -> Optional[str]:
    """Consume a turn for the tell-about flow, or detect a new one starting.

    Returns Rex's reply when this turn belongs to the flow, else None so the
    turn falls through to normal handling. Returning here also keeps the
    teller's volunteered details out of teller-side memory extraction.
    """
    global _pending_tell_about

    if not getattr(config, "TELL_ABOUT_ENABLED", True):
        return None

    state = _pending_tell_about
    if state is not None and not tell_me_about.flow_fresh(state):
        _log.info("[tell_about] flow expired at step=%s", state.get("step"))
        _pending_tell_about = None
        state = None

    if state is not None:
        expected_id = state.get("teller_id")
        if (
            teller_id is not None
            and expected_id is not None
            and int(teller_id) != int(expected_id)
        ):
            return None
        return _advance_tell_about_flow(state, text)

    parsed = tell_me_about.detect(text)
    if not parsed.is_tell_about:
        return None
    return _start_tell_about_flow(parsed, teller_id, teller_name)


def _start_tell_about_flow(
    parsed: "tell_me_about.TellAboutParse",
    teller_id: Optional[int],
    teller_name: Optional[str],
) -> Optional[str]:
    global _pending_tell_about

    now = time.monotonic()
    default_kind = None
    if parsed.gossip_hint and not parsed.facts_hint:
        default_kind = "gossip"
    elif parsed.facts_hint and not parsed.gossip_hint:
        default_kind = "fact"

    state = {
        "step": "awaiting_name",
        "teller_id": int(teller_id) if teller_id is not None else None,
        "teller_name": teller_name or "friend",
        "subject_id": None,
        "subject_name": None,
        "relationship": parsed.relationship,
        "default_kind": default_kind,
        "details_count": 0,
        "reask_count": 0,
        "pointed_idx": 0,
        "last_pointed": None,
        "created_at": now,
        "asked_at": now,
    }

    if parsed.name:
        subject_id = _create_tell_about_subject(
            parsed.name,
            state["teller_id"],
            state["teller_name"],
            parsed.relationship,
        )
        if subject_id is None:
            response = "I didn't catch a filable name there. What do they go by?"
        else:
            state["subject_id"] = subject_id
            state["subject_name"] = parsed.name
            first = _first_name_or(parsed.name, parsed.name)
            if default_kind is not None:
                # They already labeled it ("got some tea on Daniel") — don't
                # ask gossip-or-facts, go straight to collecting.
                state["step"] = "collecting"
                response = tell_me_about.invite_line(first, default_kind)
            else:
                state["step"] = "awaiting_tone"
                response = tell_me_about.opener_with_name(first)
    else:
        response = tell_me_about.opener_no_name()

    _pending_tell_about = state
    _log.info(
        "[tell_about] flow opened by %s (person_id=%s) step=%s subject=%r relationship=%r kind=%r",
        state["teller_name"],
        state["teller_id"],
        state["step"],
        state["subject_name"],
        state["relationship"],
        state["default_kind"],
    )
    return response


def _create_tell_about_subject(
    name: str,
    teller_id: Optional[int],
    teller_name: str,
    relationship: Optional[str],
) -> Optional[int]:
    """Find or pre-create the absent subject's person row and link the teller."""
    try:
        subject_id, created = people_memory.find_or_create_person(name)
    except Exception as exc:
        _log.warning("[tell_about] find_or_create_person failed: %s", exc)
        return None
    if subject_id is None:
        return None

    if teller_id is not None and int(teller_id) != int(subject_id):
        _store_introduction_memories(
            int(teller_id),
            teller_name,
            int(subject_id),
            name,
            relationship,
        )
    if created:
        try:
            facts_memory.add_fact(
                int(subject_id),
                "identity",
                "pre_met_note",
                f"{teller_name} told Rex about {name} before Rex ever met them",
                "secondhand",
                importance=0.4,
                told_by=teller_id,
            )
        except Exception as exc:
            _log.debug("[tell_about] pre_met_note save failed: %s", exc)
    _log.info(
        "[tell_about] subject %r ready (person_id=%s created=%s) told_by=%s",
        name,
        subject_id,
        created,
        teller_id,
    )
    return int(subject_id)


def _advance_tell_about_flow(state: dict, text: str) -> Optional[str]:
    global _pending_tell_about

    step = state.get("step")
    subject_first = _first_name_or(state.get("subject_name") or "", "them")
    state["asked_at"] = time.monotonic()

    if tell_me_about.is_decline(text) or tell_me_about.is_exit(text):
        _pending_tell_about = None
        if state.get("details_count", 0) > 0:
            return tell_me_about.closer_line(subject_first, state["details_count"])
        return tell_me_about.cancel_line()

    # A request aimed at Rex ("can you give me a recipe...", "what's the
    # weather") is a subject change, not material for the file. Close the
    # flow and release the turn back to normal routing.
    if tell_me_about.looks_like_request_to_rex(text, state.get("subject_name")):
        _pending_tell_about = None
        _log.info(
            "[tell_about] flow closed (subject pivot to a Rex request) "
            "subject=%r details=%s text=%r",
            state.get("subject_name"),
            state.get("details_count"),
            text,
        )
        return None

    if step == "awaiting_name":
        parsed = introductions.parse_pending_answer(
            text,
            default_relationship=state.get("relationship"),
        )
        if parsed.name:
            subject_id = _create_tell_about_subject(
                parsed.name,
                state.get("teller_id"),
                state.get("teller_name") or "friend",
                parsed.relationship or state.get("relationship"),
            )
            if subject_id is not None:
                state["subject_id"] = subject_id
                state["subject_name"] = parsed.name
                if parsed.relationship:
                    state["relationship"] = parsed.relationship
                first = _first_name_or(parsed.name, parsed.name)
                if state.get("default_kind"):
                    state["step"] = "collecting"
                    return tell_me_about.invite_line(first, state["default_kind"])
                state["step"] = "awaiting_tone"
                return tell_me_about.tone_question(first)
        state["reask_count"] = int(state.get("reask_count") or 0) + 1
        if state["reask_count"] > 1:
            _pending_tell_about = None
            return "No name, no file. Tell me again when you remember what they're called."
        return "I still need a name for the file. What do they go by?"

    if step == "awaiting_tone":
        tone = tell_me_about.parse_tone_reply(text)
        if tone:
            state["default_kind"] = tone
            state["step"] = "collecting"
            return tell_me_about.invite_line(subject_first, tone)
        if len((text or "").split()) >= 6:
            # They skipped the label and just started spilling — take it.
            state["default_kind"] = state.get("default_kind") or "fact"
            state["step"] = "collecting"
            return _store_tell_about_detail(state, text)
        state["reask_count"] = int(state.get("reask_count") or 0) + 1
        if state["reask_count"] > 1:
            state["default_kind"] = "fact"
            state["step"] = "collecting"
            return tell_me_about.invite_line(subject_first, "fact")
        return "Gossip or boring facts? I need to label the folder."

    if step == "reanchor":
        # One of Rex's other behaviors barged in and we asked "still telling
        # me about X, or have you moved on?" — route the answer.
        if tell_me_about.mentions_subject(text, state.get("subject_name")):
            # "Yeah, and he also plays drums" — they just kept going.
            state["step"] = "collecting"
            return _store_tell_about_detail(state, text)
        if tell_me_about.is_affirmative(text):
            prior = state.get("step_before_reanchor")
            state["step"] = prior if prior in ("awaiting_tone", "collecting") else "collecting"
            return tell_me_about.resume_line(subject_first)
        if tell_me_about.is_negative(text):
            _pending_tell_about = None
            return tell_me_about.reanchor_close_line(subject_first)
        # Neither a yes/no nor more material — they've moved on. Close the
        # file and release the turn to normal routing.
        _pending_tell_about = None
        _log.info(
            "[tell_about] reanchor unanswered — flow closed, turn released: %r",
            text,
        )
        return None

    # collecting
    if tell_me_about.is_done(text, allow_bare_no=True):
        _pending_tell_about = None
        _log.info(
            "[tell_about] flow closed for %r with %s detail(s)",
            state.get("subject_name"),
            state.get("details_count"),
        )
        return tell_me_about.closer_line(subject_first, int(state.get("details_count") or 0))

    if state.get("last_pointed") == "gender":
        gender = tell_me_about.parse_gender(text)
        if gender is not None:
            state["last_pointed"] = None
            try:
                facts_memory.add_fact(
                    int(state["subject_id"]),
                    "identity",
                    "gender",
                    gender,
                    "secondhand",
                    told_by=state.get("teller_id"),
                )
            except Exception as exc:
                _log.debug("[tell_about] gender fact save failed: %s", exc)
            state["details_count"] = int(state.get("details_count") or 0) + 1
            return tell_me_about.ack_line(
                subject_first,
                state.get("default_kind") or "fact",
                state["details_count"],
            )

    if tell_me_about.is_blank_offer(text) or len((text or "").split()) < 2:
        key, question = tell_me_about.pointed_question(
            int(state.get("pointed_idx") or 0),
            subject_first,
            skip_relationship=bool(state.get("relationship")),
        )
        if question is None:
            _pending_tell_about = None
            return tell_me_about.closer_line(
                subject_first, int(state.get("details_count") or 0)
            )
        state["pointed_idx"] = int(state.get("pointed_idx") or 0) + 1
        state["last_pointed"] = key
        return question

    state["last_pointed"] = None
    return _store_tell_about_detail(state, text)


def _store_tell_about_detail(state: dict, text: str) -> str:
    subject_first = _first_name_or(state.get("subject_name") or "", "them")
    detail = (text or "").strip()
    try:
        cls = tell_me_about.classify_detail(
            detail,
            state.get("subject_name") or "them",
            state.get("default_kind"),
        )
    except Exception as exc:
        _log.debug("[tell_about] classify_detail raised, using defaults: %s", exc)
        cls = {"kind": state.get("default_kind") or "fact", "kindness": 0.0,
               "category": "other", "key": None}

    count = int(state.get("details_count") or 0) + 1
    key = cls.get("key") or f"told_note_{count}"
    kind = cls.get("kind") or "fact"
    try:
        facts_memory.add_fact(
            int(state["subject_id"]),
            cls.get("category") or "other",
            key,
            detail,
            "secondhand",
            confidence=0.5 if kind == "gossip" else None,
            # Gossip ages out; it must never become a permanent "fact".
            decay_rate="normal" if kind == "gossip" else None,
            fact_kind=kind,
            kindness=cls.get("kindness"),
            told_by=state.get("teller_id"),
        )
        _log.info(
            "[tell_about] stored %s about %r key=%r kindness=%.2f told_by=%s",
            kind,
            state.get("subject_name"),
            key,
            float(cls.get("kindness") or 0.0),
            state.get("teller_id"),
        )
    except Exception as exc:
        _log.warning("[tell_about] detail save failed: %s", exc)
    state["details_count"] = count
    return tell_me_about.ack_line(
        subject_first,
        state.get("default_kind") or "fact",
        count,
    )


def tell_about_on_external_rex_line(source: Optional[str]) -> None:
    """A Rex line from another behavior landed during an active briefing.

    Called from consciousness.note_rex_utterance for EVERY Rex utterance;
    no-ops unless a tell-about flow is open and the line came from something
    other than the flow itself (smile reaction, greeting, idle banter...).
    Queues "Still telling me about X, or have you moved on?" right behind the
    barging line so the teller knows the file is still open, and switches the
    flow to the reanchor step so the next reply is routed as yes/no/more.
    """
    state = _pending_tell_about
    if state is None:
        return
    if (source or "") == "tell_about":
        return
    if not tell_me_about.flow_fresh(state):
        return
    if state.get("step") == "reanchor":
        return
    if not state.get("subject_name"):
        return

    subject_first = _first_name_or(state.get("subject_name") or "", "them")
    line = tell_me_about.reanchor_line(subject_first)
    state["step_before_reanchor"] = state.get("step")
    state["step"] = "reanchor"
    state["asked_at"] = time.monotonic()
    try:
        # Priority 0: plays right after the barging line, never preempts it.
        speech_queue.enqueue(line, "curious", priority=0, tag="tell_about:reanchor")
        conv_memory.add_to_transcript("Rex", line)
        conv_log.log_rex(line)
    except Exception as exc:
        _log.debug("[tell_about] reanchor speak failed: %s", exc)
    try:
        # Register the frame directly (NOT via note_rex_utterance — this hook
        # is called from inside it).
        dialogue_act.note_rex_turn(
            line,
            source="tell_about",
            expected_reply_types=["answer"],
        )
    except Exception:
        pass
    _log.info(
        "[tell_about] re-anchor queued after external Rex line (source=%r subject=%r)",
        source,
        state.get("subject_name"),
    )


def _told_about_teller_name(introduced_id: Optional[int]) -> Optional[str]:
    """Return who pre-briefed Rex on this person, if they were told-about
    before ever actually visiting (visit_count still 0)."""
    if introduced_id is None:
        return None
    try:
        person = people_memory.get_person(int(introduced_id)) or {}
        if int(person.get("visit_count") or 0) > 0:
            return None
        rows = facts_memory.get_facts(int(introduced_id))
    except Exception:
        return None
    told = [
        f for f in rows
        if f.get("told_by") is not None or f.get("source") == "secondhand"
    ]
    if not told:
        return None
    teller_ids = {int(f["told_by"]) for f in told if f.get("told_by") is not None}
    if len(teller_ids) == 1:
        try:
            teller = people_memory.get_person(next(iter(teller_ids))) or {}
            name = _first_name_or(str(teller.get("name") or ""), "")
            if name:
                return name
        except Exception:
            pass
    return "someone"


# ─────────────────────────────────────────────────────────────────────────────
# New-person onboarding burst (intelligence/onboarding.py)
# ─────────────────────────────────────────────────────────────────────────────

def onboarding_flow_active() -> bool:
    """True while a first-meeting onboarding burst is open and fresh.

    speech_engine.can_proactive_speak and the idle-filler loop consult this so
    nothing proactive (idle banter, smile reactions) barges into the burst — the
    same protection the 'tell me about someone' briefing gets."""
    state = _pending_onboarding
    if state is None:
        return False
    ttl = float(getattr(config, "ONBOARDING_STEP_TTL_SECS", 240.0))
    return (time.monotonic() - float(state.get("created_at") or 0.0)) <= ttl


def exploration_flow_active() -> bool:
    """True while a room-exploration session owns the floor (running or paused).

    The session/worker state lives in intelligence/exploration.py; this is the thin
    interaction-side predicate the consumption block + idle-filler guard consult, in
    the same slot as onboarding_flow_active() / tell_about_flow_active()."""
    try:
        from intelligence import exploration
        return exploration.active()
    except Exception:
        return False


def _handle_exploration_turn(text: str, speaker_id: Optional[int]) -> Optional[str]:
    """Consume a user turn during an active exploration session (before routers).

    Returns a spoken line (stop-word sign-off / encouragement ack — turn consumed)
    or None (a real question/comment — the walk pauses and the turn is released to
    normal routing)."""
    try:
        from intelligence import exploration
        return exploration.handle_user_turn(text, speaker_id)
    except Exception:
        return None


def _close_onboarding(reason: str) -> None:
    global _pending_onboarding
    state = _pending_onboarding
    _pending_onboarding = None
    if state is not None:
        # Don't pile the separate low-memory idle profile question on right after
        # the burst — onboarding already gathered the baseline (its facts live
        # under categories profile_fact_count excludes, so that path would
        # otherwise re-fire immediately and over-question; live-logged).
        pid = state.get("person_id")
        if pid is not None:
            try:
                _low_memory_idle_questions_spoken.add(int(pid))
            except Exception:
                pass
        _log.info(
            "[onboarding] flow closed (%s) person_id=%s asked=%s answered=%s",
            reason,
            state.get("person_id"),
            state.get("asked_count"),
            state.get("answered_count"),
        )


def _maybe_begin_onboarding(person_id: Optional[int], name: Optional[str]) -> None:
    """Open an onboarding burst for a freshly-enrolled, eligible newcomer.

    Called at the end of _enroll_new_person (the single enrollment choke point).
    Just arms the state; the first question fires from the idle loop a beat after
    the enrollment ack (_maybe_onboarding_question), and answers drive the rest.
    """
    global _pending_onboarding
    if not onboarding.enabled() or person_id is None:
        return
    if _pending_onboarding is not None:
        return
    try:
        if not onboarding.eligible(int(person_id)):
            return
        # Don't open a flow we can't fill (e.g. everything already answered).
        if onboarding.next_question(int(person_id), asked_keys=set(), allow_depth=False) is None:
            return
    except Exception as exc:
        _log.debug("[onboarding] begin check failed: %s", exc)
        return

    now = time.monotonic()
    _pending_onboarding = {
        "person_id": int(person_id),
        "name": name or "there",
        "step": "kickoff",
        "pending_question": None,
        "asked_keys": set(),
        "asked_count": 0,
        "answered_count": 0,
        "soft_streak": 0,
        "since_reveal": 0,
        "last_answer": None,
        "created_at": now,
        "asked_at": now,
    }
    _log.info("[onboarding] flow armed for %s (person_id=%s)", name, person_id)


def _maybe_onboarding_question() -> bool:
    """Fire the first onboarding question a beat after enrollment (kickoff).

    Q2..QN come back as direct replies to each answer (_handle_onboarding_turn);
    only the opener is proactively kicked off here, mirroring the low-memory idle
    question's emission path."""
    global _pending_onboarding
    state = _pending_onboarding
    if state is None or state.get("step") != "kickoff":
        return False
    if not onboarding.enabled():
        _close_onboarding("disabled")
        return False
    if (time.monotonic() - float(state.get("asked_at") or 0.0)) < float(
        getattr(config, "ONBOARDING_KICKOFF_SECS", 1.2)
    ):
        return False
    if speech_queue.is_speaking() or output_gate.is_busy() or echo_cancel.is_suppressed():
        return False
    if _interrupted.is_set():
        return False
    try:
        if end_thread.is_grace_active():
            return False
    except Exception:
        pass

    person_id = int(state["person_id"])
    question = onboarding.next_question(
        person_id, asked_keys=state["asked_keys"], last_answer=None, allow_depth=False
    )
    if not question:
        _close_onboarding("no opener")
        return False
    text = str(question.get("text") or "").strip()
    if not text:
        _close_onboarding("empty opener")
        return False

    spoke = _speak_proactive(text, emotion="curious", priority=1, label="onboarding_question")
    if not spoke:
        return False
    onboarding.note_question_asked(person_id, question)
    state["pending_question"] = question
    state["asked_keys"].add(question.get("key"))
    state["asked_count"] += 1
    state["since_reveal"] += 1
    state["step"] = "awaiting_answer"
    state["asked_at"] = time.monotonic()
    conv_memory.add_to_transcript("Rex", text)
    conv_log.log_rex(text)
    _register_rex_utterance(text, source="onboarding", expected_reply_types=["answer"])
    _log.info(
        "[onboarding] asked opener key=%r person_id=%s text=%r",
        question.get("key"), person_id, text,
    )
    return True


def _handle_onboarding_turn(text: str, speaker_id: Optional[int]) -> Optional[str]:
    """Consume an answer to the pending onboarding question.

    Returns Rex's next line (retort + next question, or a closer) when the turn
    belongs to the burst, or None to release the turn to normal routing (a pivot
    to Rex, a speaker mismatch, or the opener not yet asked).
    """
    global _pending_onboarding
    state = _pending_onboarding
    if state is None or not onboarding.enabled():
        return None
    if not onboarding_flow_active():
        _close_onboarding("ttl")
        return None
    # Another voice cut in — let normal handling deal with it, keep the burst open.
    if (
        speaker_id is not None
        and state.get("person_id") is not None
        and int(speaker_id) != int(state["person_id"])
    ):
        return None
    if state.get("step") != "awaiting_answer" or not state.get("pending_question"):
        # The opener hasn't fired yet (kickoff). Don't treat this turn as an
        # answer; let it route normally and the kickoff retries.
        return None

    person_id = int(state["person_id"])
    answered = (text or "").strip()

    # HARD exits — abort immediately, even before the MIN floor.
    if onboarding.is_hard_decline(answered):
        onboarding.decline_pending(person_id)
        _close_onboarding("hard decline")
        return onboarding.backoff_line()
    if onboarding.is_pivot(answered):
        # A request/question aimed at Rex — close and release so Rex just answers.
        onboarding.decline_pending(person_id)
        _close_onboarding("pivot")
        return None

    # Record the answer (familiarity bump + tidy fact/interest).
    onboarding.record_answer(person_id, state["pending_question"], answered)
    state["answered_count"] += 1
    state["last_answer"] = answered
    soft = onboarding.is_soft_disengage(answered)
    state["soft_streak"] = state["soft_streak"] + 1 if soft else 0

    # Answer-aware reaction: reflect what they ACTUALLY said (real surprise at a
    # remarkable answer, a warm beat at an ordinary one) instead of a flat random
    # bank pick. This is the core fix for the "I created you" -> "Filed away." failure.
    retort = onboarding.react_to_answer(
        answered, question=state["pending_question"], person_id=person_id
    )

    reached_max = state["asked_count"] >= onboarding.max_questions()
    reached_min = state["answered_count"] >= onboarding.min_questions()
    wind_down = reached_min and state["soft_streak"] >= int(
        getattr(config, "ONBOARDING_SOFT_DISENGAGE_LIMIT", 2)
    )
    if reached_max or wind_down:
        _close_onboarding("reached max" if reached_max else "wound down")
        return _join_onboarding_line(retort, "", onboarding.closer_line(state["answered_count"]))

    # Only go a notch deeper when the last answer carried real momentum.
    next_q = onboarding.next_question(
        person_id,
        asked_keys=state["asked_keys"],
        last_answer=answered,
        last_question=str((state.get("pending_question") or {}).get("text") or ""),
        allow_depth=not soft,
    )
    if not next_q:
        _close_onboarding("out of questions")
        return _join_onboarding_line(retort, "", onboarding.closer_line(state["answered_count"]))

    reveal = ""
    every = int(getattr(config, "ONBOARDING_REVEAL_EVERY", 3))
    if every > 0 and state["since_reveal"] >= every:
        reveal = onboarding.reveal_line()
        state["since_reveal"] = 0

    onboarding.note_question_asked(person_id, next_q)
    state["pending_question"] = next_q
    state["asked_keys"].add(next_q.get("key"))
    state["asked_count"] += 1
    state["since_reveal"] += 1
    state["asked_at"] = time.monotonic()
    _log.info(
        "[onboarding] answered -> next key=%r person_id=%s soft=%s",
        next_q.get("key"), person_id, soft,
    )
    return _join_onboarding_line(retort, reveal, str(next_q.get("text") or ""))


def _join_onboarding_line(*parts: str) -> str:
    """Join retort / reveal / question into one tidy spoken line.

    Each part is forced to end with terminal punctuation before joining, so a
    reaction that came back without a period ("A DJ-R3X droid") doesn't run
    straight into the next question ("...droid And how'd you...") and get read by
    TTS as one nonsense run-on sentence.
    """
    chunks = []
    for part in parts:
        cleaned = (part or "").strip()
        if cleaned:
            if cleaned[-1] not in ".!?…":
                cleaned += "."
            chunks.append(cleaned)
    return " ".join(chunks).strip()


def _maybe_onboarding_timeout() -> bool:
    """Close a stalled burst out loud after sustained silence; expire stale flows."""
    state = _pending_onboarding
    if state is None:
        return False
    if not onboarding_flow_active():
        _close_onboarding("ttl")
        return False
    if state.get("step") != "awaiting_answer":
        return False
    timeout = float(getattr(config, "ONBOARDING_INACTIVITY_TIMEOUT_SECS", 30.0))
    if (time.monotonic() - float(state.get("asked_at") or 0.0)) < timeout:
        return False
    if speech_queue.is_speaking():
        return False
    answered_count = int(state.get("answered_count") or 0)
    _close_onboarding("inactivity timeout")
    line = onboarding.closer_line(answered_count)
    try:
        completed = _speak_proactive(line, emotion="neutral", priority=1, label="onboarding_timeout")
        if completed:
            conv_memory.add_to_transcript("Rex", line)
            conv_log.log_rex(line)
            _register_rex_utterance(line, source="onboarding")
    except Exception as exc:
        _log.debug("[onboarding] timeout close speak failed: %s", exc)
    return True


# ─────────────────────────────────────────────────────────────────────────────
# Short-clip continuity: "mmhmm" is whoever was just talking, not a new person
# ─────────────────────────────────────────────────────────────────────────────
# A human identifies a cough or a one-word reply because they already know who
# is in the room and who spoke last — not because the sound itself is distinctive.
# ECAPA has almost nothing to work with under ~1.5 s (Bret's own "Yeah, that's
# Max" scored 0.444 on five of his prints, field log 2026-08-22-20-12), so short
# clips that fall through the normal ladder used to mint a fresh unknown_voice_N
# and fire the who's-that ask. Owner request 2026-08-22: stop that. Short clips
# resolve by continuity — a recently-confident known voice near the top of the
# scoreboard, else an existing anonymous slot, else whoever spoke last — and are
# NEVER print material (the refresh path's own 2.5 s floor already holds that).

# Full per-person scoreboard of the most recent scan: [(pid, name, score, rows)].
_last_scan_ranked: list = []

# Final attribution of the last accepted human turn: who "has the floor".
_last_speaker_turn: Optional[dict] = None


def _note_last_speaker_turn(
    person_id: Optional[int],
    person_name: Optional[str],
    anonymous_label: Optional[str],
) -> None:
    global _last_speaker_turn
    pid = _safe_int(person_id)
    if pid is None and not anonymous_label:
        return
    _last_speaker_turn = {
        "person_id": pid,
        "person_name": person_name,
        "label": anonymous_label if pid is None else None,
        "at": time.monotonic(),
    }


def _is_short_clip(text: str, audio_array: Optional[np.ndarray]) -> bool:
    """A clip too short for the embedder to be trusted: few words OR brief audio.
    Both tests, because the capture buffer pads short replies (a 2-word "yeah,
    yeah" can arrive as 3 s of audio) and a long mumble can be one word."""
    max_words = int(getattr(config, "SHORT_CLIP_MAX_WORDS", 3) or 0)
    max_secs = float(getattr(config, "SHORT_CLIP_MAX_SECS", 1.5) or 0.0)
    words = len([w for w in re.findall(r"[A-Za-z0-9']+", text or "")])
    if max_words > 0 and 0 < words <= max_words:
        return True
    secs = _audio_duration_secs(audio_array)
    return max_secs > 0 and 0.0 < secs < max_secs


def _short_clip_roster_candidate(ranked: list) -> Optional[tuple[int, str, float]]:
    """Among people confidently heard this session within the roster window, the
    best-scoring one that clears the short-clip floor and sits within the margin
    of the scoreboard's top candidate. None when nobody qualifies."""
    if not ranked:
        return None
    window = float(getattr(config, "SHORT_CLIP_ROSTER_WINDOW_SECS", 600.0))
    floor = float(getattr(config, "SHORT_CLIP_ROSTER_FLOOR", 0.40))
    margin = float(getattr(config, "SHORT_CLIP_ROSTER_MARGIN", 0.06))
    now = time.monotonic()
    top_score = float(ranked[0][2])
    best = None
    for row in ranked:
        try:
            pid, name, score = int(row[0]), row[1], float(row[2])
        except (TypeError, ValueError, IndexError):
            continue
        anchor = _last_confident_voice_at.get(pid)
        if anchor is None or (now - anchor) > window:
            continue
        if score < floor or (top_score - score) > margin:
            continue
        if best is None or score > best[2]:
            best = (pid, name, score)
    return best


def _short_clip_last_speaker() -> Optional[dict]:
    last = _last_speaker_turn
    if not isinstance(last, dict):
        return None
    window = float(getattr(config, "SHORT_CLIP_LAST_SPEAKER_SECS", 90.0))
    if (time.monotonic() - float(last.get("at") or 0.0)) > window:
        return None
    if last.get("label") and not any(
        s.label == last.get("label") for s in _anonymous_speaker_slots
    ):
        return None  # the slot was retired/cleared since
    return dict(last)


# ─────────────────────────────────────────────────────────────────────────────
# Concurrent transcription + speaker identification
# ─────────────────────────────────────────────────────────────────────────────

def _process_audio(
    audio_array: np.ndarray,
    pretranscribed: Optional[str] = None,
) -> tuple[str, Optional[int], Optional[str], float, float, float]:
    """
    Run transcription and speaker ID simultaneously in two threads.

    pretranscribed: a transcript already decoded from this same segment (eager
    motion endpointing) — skips the ASR decode but still runs speaker ID, so
    attribution and enrollment behave identically. Passed through as-is (it may
    be a Transcript carrying .confident).

    Returns (transcribed_text, raw_best_id, raw_best_name, raw_best_score,
    raw_best_margin, required_margin). The speaker values are the RAW top
    per-person centroid candidate — NOT threshold-filtered. raw_best_margin is
    the gap to the next DIFFERENT person (large when only one person is
    enrolled). required_margin is the scoreboard-specific ambiguity bar from
    speaker_id.required_ambiguity_margin (base SPEAKER_ID_KNOWN_MARGIN, reduced
    when the runner-up's print set is thin) — callers compare raw_best_margin
    against it instead of the raw config value.
    """
    global _last_scan_ranked
    _last_scan_ranked = []
    default_margin = float(getattr(config, "SPEAKER_ID_KNOWN_MARGIN", 0.07))
    text_box: list[str] = [""]
    # [person_id, name, score, margin, required_margin]
    speaker_box: list = [None, None, 0.0, 0.0, default_margin]

    def _transcribe() -> None:
        if pretranscribed is not None:
            text_box[0] = pretranscribed
        else:
            text_box[0] = transcription.transcribe(audio_array)

    def _identify() -> None:
        global _last_scan_ranked
        ranked = speaker_id.rank_speakers(audio_array)
        _last_scan_ranked = list(ranked or [])
        if not ranked:
            return
        speaker_id._log_scoreboard(ranked)
        pid, name, score, _n = ranked[0]
        second = ranked[1][2] if len(ranked) > 1 else -1.0
        speaker_box[0] = pid
        speaker_box[1] = name
        speaker_box[2] = float(score)
        speaker_box[3] = float(score - second)
        speaker_box[4] = float(speaker_id.required_ambiguity_margin(ranked))

    t1 = threading.Thread(target=_transcribe, daemon=True, name="transcription")
    t2 = threading.Thread(target=_identify, daemon=True, name="speaker-id")
    t1.start()
    t2.start()
    t1.join()
    t2.join()

    return (text_box[0] or "", speaker_box[0], speaker_box[1], speaker_box[2],
            speaker_box[3], speaker_box[4])


# ─────────────────────────────────────────────────────────────────────────────
# Turn completion repair
# ─────────────────────────────────────────────────────────────────────────────

def _maybe_prompt_incomplete_turn() -> bool:
    """Ask a tiny repair question when a held fragment times out."""
    global _session_exchange_count
    if _game_suppresses_conversation():
        turn_completion.clear_stale_prompted()
        return False
    if speech_queue.is_speaking() or output_gate.is_busy() or echo_cancel.is_suppressed():
        return False

    pending = turn_completion.mark_prompt_due()
    if pending is None:
        turn_completion.clear_stale_prompted()
        return False

    prompt = pending.prompt
    if not prompt:
        return False

    speaker_label = "user"
    heard_name: Optional[str] = None
    try:
        if (
            pending.raw_best_name
            and pending.raw_best_score >= float(getattr(config, "SPEAKER_ID_SOFT_THRESHOLD", 0.60))
        ):
            speaker_label = pending.raw_best_name
            heard_name = pending.raw_best_name
    except Exception:
        pass
    try:
        conv_memory.add_to_transcript(speaker_label, pending.text)
        conv_log.log_heard(heard_name, pending.text)
    except Exception as exc:
        _log.debug("turn completion partial transcript log failed: %s", exc)
    print(f"[HEARD] {speaker_label}: {pending.text}", flush=True)
    _log.info(
        "[turn_completion] prompting for completion — speaker=%r text=%r prompt=%r",
        speaker_label,
        pending.text,
        prompt,
    )

    completed = _speak_proactive(
        prompt,
        emotion="neutral",
        pre_beat_ms=100,
        post_beat_ms_override=150,
        label="incomplete_turn_prompt",
    )
    if completed:
        conv_memory.add_to_transcript("Rex", prompt)
        conv_log.log_rex(prompt)
        _session_exchange_count += 1
        try:
            wait_secs = float(
                getattr(config, "INCOMPLETE_TURN_PROMPT_REPLY_WINDOW_SECS", 10.0)
            )
        except Exception:
            wait_secs = 10.0
        _register_rex_utterance(prompt, wait_secs=wait_secs)
    return True


def _arm_visible_unknown_identity_followup(
    person_id: Optional[int],
    *,
    source: str,
) -> None:
    """
    When Rex has just asked about a visible mystery guest from the normal LLM
    path, open the same parsing window used by proactive relationship prompts.

    Without this, a natural bare reply like "Alex" after "who's this?" can fall
    through as ordinary chat instead of enrolling the visible newcomer.
    """
    unknown_slot = None
    try:
        for p in world_state.get("people") or []:
            if p.get("person_db_id") is None:
                unknown_slot = str(p.get("id") or "unknown_visible")
                break
    except Exception:
        unknown_slot = None
    if not unknown_slot:
        return

    if person_id is None:
        global _identity_prompt_until
        _identity_prompt_until = max(
            _identity_prompt_until,
            time.monotonic() + _IDENTITY_REPLY_WINDOW_SECS,
        )
        _log.info(
            "[interaction] armed visible-unknown self-identity followup source=%s slot=%s",
            source,
            unknown_slot,
        )
        return

    engaged_name = None
    try:
        row = people_memory.get_person(person_id)
        engaged_name = row.get("name") if row else None
    except Exception:
        engaged_name = None
    try:
        consciousness.set_relationship_prompt_context({
            "engaged_person_id": person_id,
            "engaged_name": engaged_name,
            "slot_id": unknown_slot,
            "asked_at": time.monotonic(),
        })
        _log.info(
            "[interaction] armed visible-unknown relationship followup "
            "source=%s engaged_id=%s slot=%s",
            source,
            person_id,
            unknown_slot,
        )
    except Exception as exc:
        _log.debug("visible unknown relationship followup arm failed: %s", exc)


# ─────────────────────────────────────────────────────────────────────────────
# Speech accumulation
# ─────────────────────────────────────────────────────────────────────────────

def _speech_preroll_secs() -> float:
    preroll = float(getattr(config, "SPEECH_PREROLL_SECS", 0.45) or 0.0)
    # Far-field robot: the VAD fires later after true onset, so reach further back
    # (see SPEECH_PREROLL_SECS_AEC in config). Safe — _speech_capture_secs clamps
    # to the post-TTS capture floor, so this never pulls Rex's own tail.
    if hardware_aec.is_active():
        preroll = max(
            preroll,
            float(getattr(config, "SPEECH_PREROLL_SECS_AEC", preroll) or 0.0),
        )
    if _response_wait_active():
        preroll = max(
            preroll,
            float(getattr(config, "POST_QUESTION_SPEECH_PREROLL_SECS", preroll) or 0.0),
        )
    return max(0.0, preroll)


def _speech_capture_secs(speech_start_mono: float, finished_mono: Optional[float] = None) -> float:
    """
    Return how much rolling audio to send to Whisper for this speech segment.

    Question answers get extra pre-roll, but never from before the latest
    post-TTS handoff floor. Otherwise Rex's own question can be captured along
    with the human's answer.
    """
    finished = time.monotonic() if finished_mono is None else float(finished_mono)
    preroll = _speech_preroll_secs()
    start_at = float(speech_start_mono) - preroll
    clamped_to_floor = False
    # FAST-REPLY WIDENING (field 2026-08-06 00:10, "I know, am I right?" heard as
    # "Am I right?"): when VAD fires shortly after the capture floor, the human
    # almost certainly started talking the moment Rex went quiet — but the software
    # suppression tail flattens their onset, so VAD triggers a beat late and a
    # preroll-sized reach-back misses the first words. Everything between the floor
    # and VAD onset is post-playback audio already sitting in the rolling buffer,
    # so capture from the FLOOR: worst case is a second of leading room tone, which
    # ASR shrugs off; the first words are what we cannot get back.
    near = float(getattr(config, "CAPTURE_FROM_FLOOR_NEAR_SECS", 2.0) or 0.0)
    if (
        near > 0.0
        and _listen_capture_floor_at > 0.0
        and 0.0 <= (float(speech_start_mono) - _listen_capture_floor_at) <= near
    ):
        start_at = _listen_capture_floor_at
        clamped_to_floor = True
    elif _listen_capture_floor_at > 0.0 and _listen_capture_floor_at > start_at:
        start_at = _listen_capture_floor_at
        clamped_to_floor = True
    duration = max(0.0, finished - start_at)
    # A post-TTS handoff that lands AFTER this utterance began pushes the floor past
    # the speech itself, collapsing the window to ~0s. The caller then gets an empty
    # array and drops the turn — historically in total silence. Say so.
    if duration < float(getattr(config, "CAPTURE_MIN_USABLE_SECS", 0.20)):
        _capture_dropped(
            "capture_window_collapsed" if clamped_to_floor else "capture_window_empty",
            window=f"{duration:.2f}s",
            floor_after_speech_start=(
                f"{_listen_capture_floor_at - float(speech_start_mono):+.2f}s"
                if _listen_capture_floor_at > 0.0 else "n/a"
            ),
            preroll=f"{preroll:.2f}s",
            speech_len=f"{finished - float(speech_start_mono):.2f}s",
        )
    return min(duration, float(config.AUDIO_BUFFER_SECONDS))


def _barge_recovered_speech_start(now: float, onset_at: float) -> float:
    """Effective speech_start when a proactive line just yielded to the user's speech.

    A proactive line spends ~1-2s generating before it yields; the user's opening words spoken in
    that gap are in the rolling buffer but the loop only notices the speech late, so a plain
    now-based speech_start clips them. Reach back to the recorded onset (impulse-decision time),
    bounded by PROACTIVE_YIELD_ONSET_MAX_SECS so a stale marker can't pull in a prior utterance or
    Rex's tail. Returns `now` unchanged when nothing is pending (onset_at <= 0)."""
    if onset_at <= 0.0 or not bool(getattr(config, "PROACTIVE_YIELD_RECOVER_ONSET_ENABLED", True)):
        return now
    earliest = now - max(0.0, float(getattr(config, "PROACTIVE_YIELD_ONSET_MAX_SECS", 3.0)))
    return max(min(now, onset_at), earliest)


def _maybe_recover_post_question_answer() -> Optional[float]:
    """One-shot retrospective VAD scan of the post-question dead window.

    Between the end of Rex's question and the loop's first live mic read there
    are ~0.3-0.7s (echo tail + listen-resume delay + synchronous turn unwind)
    during which no audio is examined. A clipped one-word answer ("no") spoken
    there is in the rolling buffer but never triggers live VAD, so nothing ever
    reaches Whisper (live-logged 2026-07-07: 20 Questions answers vanished until
    the player repeated them). When the last handoff was a QUESTION, scan that
    buffered span once and, if it contains speech, return the effective
    speech_start so the normal capture path (preroll bounded by the capture
    floor) picks the answer up. Returns None when disarmed, stale, or silent.

    The first POST_QUESTION_RETRO_SCAN_SKIP_SECS after the handoff are excluded:
    Rex's room echo is still decaying there, and scanning it raw would let his
    own final word trigger a phantom recovery.
    """
    global _post_question_retro_scan_at
    armed_at = _post_question_retro_scan_at
    if armed_at <= 0.0:
        return None
    _post_question_retro_scan_at = 0.0    # one-shot, whatever the outcome
    now = time.monotonic()
    window = float(getattr(config, "POST_QUESTION_RETRO_SCAN_WINDOW_SECS", 2.5))
    if (now - armed_at) > window:
        return None                       # loop was away too long — span is stale
    skip = float(getattr(config, "POST_QUESTION_RETRO_SCAN_SKIP_SECS", 0.15))
    scan_start = armed_at + skip
    span_secs = now - scan_start
    if span_secs < 0.12:
        return None                       # nothing meaningfully unexamined
    span = stream.get_audio_chunk(span_secs)
    if len(span) == 0:
        return None
    frame_len = max(1, int(_CHUNK_SECS * config.AUDIO_SAMPLE_RATE))
    need = max(1, int(getattr(config, "POST_QUESTION_RETRO_SCAN_MIN_VOICED_FRAMES", 3)))
    voiced = 0
    # Raw frames on purpose: the span was recorded after playback ended, and
    # echo_cancel.filter keys off the CURRENT tail state, which would attenuate
    # exactly the audio we are trying to recover.
    try:
        for i in range(0, len(span) - frame_len + 1, frame_len):
            if vad.is_speech(span[i:i + frame_len]):
                voiced += 1
                if voiced >= need:
                    break
    finally:
        try:
            vad.reset_state()             # don't leak scan context into live detection
        except Exception:
            pass
    if voiced < need:
        return None
    _log.info(
        "[interaction] post-question retro scan recovered speech from the dead "
        "window (span=%.2fs, voiced_frames=%d)", span_secs, voiced,
    )
    return scan_start


# Eager-endpoint handoff: the transcript decoded by a successful motion probe,
# consumed by the caller and passed into _handle_speech_segment so the segment
# is not decoded twice. Set and popped on the interaction thread only.
_eager_endpoint_transcript: Optional[str] = None

# A trailing connective promises another clause ("turn left and ..."): never
# eager-cut it — the person is mid-route.
_EAGER_TRAILING_CONNECTIVE_RE = re.compile(r"\b(?:and|then)[\s.,]*$", re.IGNORECASE)


def _pop_eager_transcript() -> Optional[str]:
    global _eager_endpoint_transcript
    text = _eager_endpoint_transcript
    _eager_endpoint_transcript = None
    return text


def _eager_motion_endpoint_enabled() -> bool:
    if not bool(getattr(config, "MOTION_EAGER_ENDPOINT_ENABLED", True)):
        return False
    if not motion_controller.available():
        return False
    if bool(getattr(config, "MOTION_EAGER_ENDPOINT_REQUIRE_AEC", True)):
        # Endpointing behavior is tuned per-platform: robot only (hardware AEC
        # present); dev-Mac sessions keep stock segmentation.
        try:
            from audio import hardware_aec
            if not hardware_aec.is_active():
                return False
        except Exception:
            return False
    return True


def _eager_motion_transcript_matches(text: str) -> bool:
    """True when the probe transcript is a COMPLETE explicit drive command."""
    cleaned = text.strip()
    if not cleaned or _EAGER_TRAILING_CONNECTIVE_RE.search(cleaned):
        return False
    try:
        if action_router.classify_explicit_motion(cleaned) is not None:
            return True
        sequence = action_router.classify_explicit_motion_sequence(
            cleaned, max_steps=int(getattr(config, "MOTION_SEQUENCE_MAX_STEPS", 8))
        )
        if sequence:
            return True
        # A stop demand while the base is moving — the one case where faster
        # endpointing is a safety improvement, not just comfort. Sentence-level
        # scan, not just the bare token: field stops arrive buried in noisy
        # segments ("... Go. Stop. Stop looking for me.").
        if _errand_stop_demanded(cleaned) and motion_controller.is_moving():
            return True
    except Exception as exc:
        _log.debug("[eager_endpoint] match check failed: %s", exc)
    return False


def _start_eager_motion_probe(speech_start_mono: float) -> dict:
    """Transcribe the segment-so-far in the background; box carries the result."""
    box: dict = {"matched": False, "transcript": None}

    def _run() -> None:
        try:
            capture_secs = _speech_capture_secs(speech_start_mono)
            audio = stream.get_audio_chunk(capture_secs)
            if len(audio) == 0:
                return
            text = transcription.transcribe(audio)
            if str(text or "").strip() and _eager_motion_transcript_matches(str(text)):
                box["transcript"] = text
                box["matched"] = True
        except Exception as exc:
            _log.debug("[eager_endpoint] probe failed: %s", exc)

    threading.Thread(target=_run, daemon=True, name="eager-motion-probe").start()
    return box


def _accumulate_speech(
    speech_start_mono: float,
    *,
    allowed_states: tuple[State, ...] = (State.ACTIVE,),
    raw_vad: bool = False,
) -> Optional[np.ndarray]:
    """
    Poll VAD until config.SILENCE_TIMEOUT_SECS of sustained silence, then
    return the full speech segment captured from the rolling buffer.

    speech_start_mono is the monotonic timestamp when speech was first detected
    in the main loop — used to calculate how much of the buffer to grab.

    raw_vad: skip the echo_cancel software attenuation before VAD. Used by the
    during-DJ command listener — playback holds software suppression for the
    whole track, which would flatten the user's speech to 5% and end the
    segment after the first chunk; the ReSpeaker's HARDWARE AEC (a
    prerequisite of that listener) has already removed the music.
    """
    global _eager_endpoint_transcript
    silence_timeout = config.SILENCE_TIMEOUT_SECS
    silence_elapsed = 0.0
    # Eager motion endpointing: only on the real conversation paths (ACTIVE,
    # normal VAD) — never the during-DJ command ear or the sleep-wake scan.
    eager_enabled = (
        not raw_vad
        and allowed_states == (State.ACTIVE,)
        and _eager_motion_endpoint_enabled()
    )
    eager_silence = float(getattr(config, "MOTION_EAGER_ENDPOINT_SILENCE_SECS", 0.35))
    eager_probe: Optional[dict] = None

    while not _stop_event.is_set():
        if state_module.get_state() not in allowed_states:
            return None

        chunk = stream.get_audio_chunk(_CHUNK_SECS)
        if len(chunk) == 0:
            _stop_event.wait(_CHUNK_SECS)
            continue

        is_speech = vad.is_speech(chunk if raw_vad else _chunk_for_vad(chunk))
        _situation_assessor.set_vad_active(is_speech)
        if is_speech:
            silence_elapsed = 0.0
            # Speech resumed — whatever the in-flight probe decodes is stale.
            eager_probe = None
        else:
            silence_elapsed += _CHUNK_SECS
            elapsed = time.monotonic() - speech_start_mono
            min_duration = getattr(config, "MIN_SPEECH_DURATION_SECS", 0.0)
            if silence_elapsed >= silence_timeout and elapsed >= min_duration:
                break
            if eager_enabled and elapsed >= min_duration and silence_elapsed >= eager_silence:
                if eager_probe is None:
                    # One probe per silence run; a non-match simply waits out
                    # the normal timeout.
                    eager_probe = _start_eager_motion_probe(speech_start_mono)
                elif eager_probe.get("matched"):
                    _eager_endpoint_transcript = eager_probe["transcript"]
                    _log.info(
                        "[eager_endpoint] complete motion command at %.2fs silence "
                        "(vs %.2fs timeout) — ending turn early: %r",
                        silence_elapsed, silence_timeout,
                        str(eager_probe["transcript"]),
                    )
                    break

        _stop_event.wait(_CHUNK_SECS)

    if _stop_event.is_set():
        return None

    # Grab the full segment from the rolling buffer. Add pre-roll so soft starts
    # before the first VAD-positive chunk are not clipped, clamped to the latest
    # post-TTS handoff so Rex's own question is not transcribed as user speech.
    capture_secs = _speech_capture_secs(speech_start_mono)
    return stream.get_audio_chunk(capture_secs)


def _wake_from_sleep_if_transcribed(audio_segment: Optional[np.ndarray]) -> bool:
    """Wake from sleep when a transcribed sleep utterance is an explicit wake phrase."""
    global _last_speech_at
    if audio_segment is None or len(audio_segment) == 0:
        return False
    try:
        text = transcription.transcribe(audio_segment).strip()
    except Exception as exc:
        _log.debug("[sleep_mode] wake transcript failed: %s", exc)
        return False
    if not text:
        return False
    if not _is_sleep_wake_transcript(text):
        _log.info("[sleep_mode] ignored sleeping speech text=%r", text)
        return False
    _log.info("[sleep_mode] waking from transcribed phrase text=%r", text)
    _last_speech_at = time.monotonic()
    _wake_from_sleep()
    return True


# ─────────────────────────────────────────────────────────────────────────────
# LLM streaming to TTS
# ─────────────────────────────────────────────────────────────────────────────

def _extract_primary_purpose(directive: str) -> str:
    """Pull the single 'Primary purpose: …' line the agenda always emits, for the
    Phase 1 slim contract. Returns '' when absent (render_slim_contract then supplies
    a sensible default)."""
    for line in (directive or "").split("\n"):
        stripped = line.strip()
        if stripped.startswith("Primary purpose:"):
            return stripped
    return ""


# A whole reply the model wrote as a TEXT-shaped tool call — "[web_search]\n
# {\"query\": ...}" — instead of a native tool-call delta (field 2026-08-04
# 23:09: it was dropped as an unspeakable stream tail and the turn died silent).
# Parsed and dispatched like the real thing when it names a LIVE action; an
# inline v3 audio tag ("[curious] Hey...") never matches because trailing prose
# fails the anchor, and a bare "[sarcastic]" resolves to no known tool.
_TEXT_TOOL_CALL_RE = re.compile(
    r"^\s*\[([A-Za-z][A-Za-z0-9_.]{2,40})\]\s*(\{.*\})?\s*$", re.S
)


def _parse_text_tool_call(raw: str) -> Optional[tuple]:
    """(action_key, args) when ``raw`` is a text-shaped call on a LIVE tool,
    else None. Never raises."""
    m = _TEXT_TOOL_CALL_RE.match(raw or "")
    if not m:
        return None
    name = m.group(1).strip().replace(".", "_")
    try:
        from intelligence import tool_router
        return tool_router.resolve_tool_call(name, m.group(2) or "{}")
    except Exception as exc:
        _log.debug("[interaction] text tool-call resolve failed: %s", exc)
        return None


def _compose_news_search_input(text: str, story: dict) -> str:
    """Search input for a follow-up about the story Rex just offered: the user's
    words alone ("tell me more about that") carry no topic, so the cached
    headline + summary ride along as the grounding.

    Length/style now live in config.WEB_SEARCH_NEWS_DIGEST_ADDENDUM (the SYSTEM
    contract for this path) rather than here — stating them in the user message
    while the system prompt said "give the COMPLETE answer" produced a ~90-word
    reply (field 2026-08-06 00:29). What stays here is grounding: which story,
    and WHEN its event actually is.
    """
    headline = str(story.get("headline") or "").strip()
    summary = str(story.get("summary") or "").strip()
    detail = f" ({summary})" if summary else ""
    timing = ""
    try:
        from awareness import current_events
        clause = current_events.story_timing_clause(story)
        timing = f" {clause}" if clause else ""
    except Exception:
        timing = ""
    return (
        f"{text}\n\n[They are asking about the news story you just mentioned: "
        f'"{headline}"{detail}.{timing} Search the web for that story and tell '
        "them about it in your own voice.]"
    )


def _maybe_web_search_reply(
    text: str,
    person_id: Optional[int],
    turn_start: Optional[float] = None,
    force: bool = False,
    news_story: Optional[dict] = None,
) -> Optional[str]:
    """If this turn needs CURRENT info, run a web search and speak Rex's answer.

    Triggered explicitly ("look that up") or by the autonomous gate (Rex decides a
    question needs live data). A stall line is spoken immediately and NON-blocking,
    so the multi-second search overlaps with playback instead of leaving Rex silent;
    the hosted web_search then runs and the answer is spoken in character.

    Returns the spoken answer (turn handled — the normal reply is skipped) or None to
    fall through to the normal LLM reply. Fully gated by config.WEB_SEARCH_ENABLED and
    failure-safe: any error returns None so Rex still answers from his own knowledge.
    """
    if not getattr(config, "WEB_SEARCH_ENABLED", False):
        return None
    if _interrupted.is_set() or not _can_speak():
        return None
    try:
        from intelligence import web_search
        if news_story is not None:
            # Follow-up about the story Rex just offered in a lull — always a
            # real search, grounded on the cached headline/summary (the user's
            # own words are just "tell me more about that").
            decision = web_search.SearchDecision(True, True, "news_followup")
        elif force:
            # Live tool-router dispatch: the reply-call LLM already judged this
            # turn needs current data (it beat the phrase triggers AND the
            # autonomous gate to it) — treat like an explicit user request.
            decision = web_search.SearchDecision(True, True, "tool_router")
        else:
            decision = web_search.should_search(text)
    except Exception as exc:
        _log.debug("[web_search] trigger detection failed: %s", exc)
        return None
    if not decision.triggered:
        return None

    try:
        from intelligence import connectivity
        if connectivity.is_offline():
            resp = connectivity.no_internet_reply()
            _log.info("[web_search] offline — refusing in character")
            _speak_blocking(resp)
            return resp
    except ImportError:
        pass

    _log.info("[web_search] triggered (%s) for: %r", decision.reason, text)

    # Stall line — spoken immediately and non-blocking so the search latency overlaps
    # with playback. It is Rex's real first audio this turn, so mark TTFS against it
    # (first-wins: the answer's later enqueue won't steal the credit).
    trace = _current_character_loop_trace.get()
    try:
        stall = web_search.pick_stall_line()
    except Exception:
        stall = ""
    if stall:
        _mark_first_response_queued(trace, text=stall, priority=1)
        speech_queue.enqueue(
            stall,
            "neutral",
            priority=1,
            on_start=(lambda: _mark_first_response_audio_started(trace))
            if trace is not None
            else None,
            log_text=True,
        )

    started = time.monotonic()
    search_text = (
        _compose_news_search_input(text, news_story) if news_story is not None else text
    )
    try:
        result = web_search.answer(
            search_text, person_id, forced=decision.forced,
            # News follow-ups get the short spoken-digest contract; every other
            # search keeps the general "complete answer" one.
            addendum=(
                getattr(config, "WEB_SEARCH_NEWS_DIGEST_ADDENDUM", None)
                if news_story is not None else None
            ),
            # Safety net only: if the model overshoots the digest contract badly,
            # a second call SHORTENS it (never a mid-sentence truncation).
            max_words=(
                int(getattr(config, "WEB_SEARCH_NEWS_MAX_WORDS", 55))
                if news_story is not None else None
            ),
        )
    except Exception as exc:
        _log.warning("[web_search] answer failed: %s", exc)
        return None
    if turn_start is not None:
        _latency_log(turn_start, "web_search", started)

    if not result.ok or not (result.text or "").strip():
        # No usable result — fall through to a normal from-knowledge reply so Rex
        # still answers (a stall line may already have been spoken; that's fine).
        _log.info("[web_search] no usable result (ok=%s); falling through", result.ok)
        return None

    if not decision.forced and not (result.citations or []):
        # AUTONOMOUS search with ZERO citations = the model didn't ground on any
        # actual results — its prose is hallucinated "news" wearing a search badge
        # (field bug 2026-07-06: "what's up today" produced invented GPT-5.5 model
        # announcements). Fall through to a normal reply instead of reciting it.
        # Explicit user-requested searches keep their answer — the user invoked the
        # tool deliberately and can judge it.
        _log.info("[web_search] autonomous result had no citations — discarding as ungrounded")
        return None

    answer_text = result.text.strip()
    _log.info(
        "[web_search] answered in %.2fs (%d citations)",
        time.monotonic() - started,
        len(result.citations or []),
    )
    if result.citations:
        _log.info("[web_search] sources: %s", ", ".join(result.citations[:5]))

    # Write the answer to the transcript + GUI NOW, before a single word is spoken.
    # It used to ride the caller's post-return log, but _speak_blocking returns only
    # after PLAYBACK finishes — so a ~30s news answer sat invisible until Rex stopped
    # talking (owner 2026-08-06). The streaming reply path logs as soon as the text
    # exists; this matches it.
    #
    # NOT conv_log.claim_rex_line(), which exists for exactly this shape: its dedupe
    # is TIME-BOUNDED (_REX_DEDUPE_WINDOW_SECS = 30s) and a long news answer takes
    # about that long to speak, so the caller's later write would land right on the
    # boundary and duplicate roughly half the time. The one-shot marker is
    # time-independent, and also covers add_to_transcript (which claim_rex_line
    # does not touch).
    try:
        conv_memory.add_to_transcript("Rex", answer_text)
        conv_log.log_rex(answer_text)
        _note_prelogged_response(answer_text)
    except Exception as exc:
        _log.debug("[web_search] pre-speak transcript write failed: %s", exc)
    _speak_blocking(answer_text, emotion="neutral", priority=1, log_text=False)
    try:
        _apply_post_tts_handoff(answer_text, source="web_search")
    except Exception as exc:
        _log.debug("[web_search] post-tts handoff skipped: %s", exc)
    # Arm the inquisitive follow-up: if they go quiet now, the proactive loop should
    # ask about the topic ("what got you asking about X?") rather than re-commenting
    # on what was just looked up. Cleared when they next speak (topic_thread).
    try:
        # For a news follow-up, the topic worth being inquisitive about later is
        # the story itself, not the composed search blob.
        web_search.note_search(
            str(news_story.get("headline") or "") if news_story is not None else text
        )
    except Exception as exc:
        _log.debug("[web_search] note_search skipped: %s", exc)
    return answer_text


# One-shot holder: set when a live tool call routed the turn, consumed by the
# caller to stamp final_executed_path="tool_router.<action>" instead of
# "llm.stream" (the report joins on executed paths).
_tool_routed_path: "list[str]" = []

# One-shot holder: a reply this turn already wrote to the transcript + GUI itself.
# The streaming reply path logs when the TEXT is ready and returns immediately, so
# the caller's single log lands fast. _speak_blocking, by contrast, returns only
# after PLAYBACK finishes — so a web-search answer that takes ~30s to speak did not
# reach the GUI until it had finished being spoken (owner 2026-08-06: "the GUI shows
# the text only after TTS has spoken"). Those paths now log up front and park the
# text here so the caller skips its duplicate write.
_prelogged_response: "list[str]" = []


def _note_prelogged_response(text: str) -> None:
    """Record that `text` has ALREADY been written to the transcript + GUI."""
    _prelogged_response.clear()
    if text and text.strip():
        _prelogged_response.append(text)


def _consume_prelogged_response() -> "Optional[str]":
    """Take the pre-logged text (one-shot). None when the caller still owns the log."""
    return _prelogged_response.pop() if _prelogged_response else None


def _consume_tool_routed_path() -> Optional[str]:
    return _tool_routed_path.pop() if _tool_routed_path else None


# Live tool actions (tool_router Phase 1) all map onto intent-classifier
# handlers — the reverse of _INTENT_ACTION_MAP.
_TOOL_ACTION_INTENT_MAP: dict[str, str] = {}


def _tool_router_person_name(person_id: Optional[int]) -> Optional[str]:
    """Best-effort display name for a tool-routed command (None is fine)."""
    if person_id is None:
        return None
    try:
        person = people_memory.get_person(int(person_id)) or {}
        return str(person.get("name") or "").strip() or None
    except Exception:
        return None


def _execute_tool_routed_action(action: str, args: dict, text: str,
                                person_id: Optional[int]) -> str:
    """Run the existing executor for a live tool call from the reply stream.
    Always returns spoken text (falls back to a classic reply so a mapping gap
    can never leave Rex silent)."""
    global _TOOL_ACTION_INTENT_MAP
    if not _TOOL_ACTION_INTENT_MAP:
        _TOOL_ACTION_INTENT_MAP = {v: k for k, v in _INTENT_ACTION_MAP.items()}
    intent = _TOOL_ACTION_INTENT_MAP.get(action)
    _log.info("[tool_router] live route: %s args=%s text=%r", action, args, text)
    resp: Optional[str] = None
    # system.* tools execute via the legacy command executor, not the intent
    # map. The parser backstop keeps the LLM from powering Rex down on
    # object-scoped/negated/hypothetical phrasings — but unlike the
    # deterministic path it ACCEPTS polite requests ("Can you shut down,
    # please?"), which is exactly the phrasing class this live tool exists for.
    if action == "web.search":
        # The LLM judged this turn needs live data (field 2026-08-01: "What's
        # going on with the Iran War?" fell to conversation and Rex refused
        # from stale knowledge while the web_search feature sat unused).
        # Search on the user's own words — they carry the follow-up context —
        # and note the extracted topic only in the log. When the turn is a
        # follow-up about the news story Rex just offered, the cached
        # headline/summary ride along (the user's words alone are "tell me
        # more about that").
        _log.info("[tool_router] web.search query=%r", (args or {}).get("query"))
        try:
            resp = _maybe_web_search_reply(
                text, person_id, force=True, news_story=_news_followup_story(text)
            )
        except Exception as exc:
            _log.error("[tool_router] web.search failed: %s", exc)
            resp = None
        if resp:
            _tool_routed_path.append(f"tool_router.{action}")
            return resp
        # Search declined/empty — answer from knowledge so the turn isn't silent.
        full = llm.get_response(text, person_id, classic=True)
        if full and full.strip():
            _speak_blocking(full)
        return full or ""

    if action == "identity.name_correction":
        # Field 2026-08-02 14:06: "My name's not Brad, it's JT" — the shadow
        # picked this tool with the right arg while the shipped path replied
        # in prose and Rex SAID he'd updated the name without doing it.
        try:
            decision = action_router.ActionDecision(
                action=action, confidence=1.0, args=dict(args or {}),
                requires_confirmation=False, reason="tool_router",
            )
            resp = _handle_router_identity_name_correction(
                text, decision, person_id, _tool_router_person_name(person_id),
            )
        except Exception as exc:
            _log.error("[tool_router] executor failed for %s: %s", action, exc)
            resp = None
        if resp:
            _tool_routed_path.append(f"tool_router.{action}")
            return resp

    if action == "memory.forget_person":
        # Route through the existing forget_me flow (arms the confirmation
        # phrase + same-speaker guard before any deletion). SAFETY: the tool
        # may only target the CURRENT SPEAKER — a named third party never
        # gets deleted off an LLM tool call; that stays a spoken exact
        # command with its own confirmation.
        target = str((args or {}).get("person_name") or "").strip()
        speaker_name = _tool_router_person_name(person_id) or ""
        first = speaker_name.split()[0].lower() if speaker_name else ""
        if target and first and target.lower() not in (
            speaker_name.lower(), first
        ):
            # Also allow the target being the speaker's CLAIMED name this
            # turn (they may have just corrected it) — otherwise decline.
            _log.info(
                "[tool_router] memory.forget_person target %r != speaker %r — "
                "declining to third-party delete", target, speaker_name,
            )
            resp = None
        else:
            try:
                resp = _execute_command(
                    command_parser.CommandMatch("forget_me", "tool_router", {}),
                    person_id,
                    speaker_name or None,
                    text,
                )
            except Exception as exc:
                _log.error("[tool_router] executor failed for %s: %s", action, exc)
                resp = None
        if resp:
            _tool_routed_path.append(f"tool_router.{action}")
            return resp
        full = llm.get_response(text, person_id, classic=True)
        if full and full.strip():
            _speak_blocking(full)
        return full or ""

    if action == "vision.snapshot":
        # Privacy-gated: never captures directly — speaks the confirmation
        # offer and arms the pending slot; the user's next "yes, remember
        # this scene" completes the capture (see _handle_scene_snapshot_
        # confirmation in the speech-segment pending-slot ladder).
        resp = _offer_scene_snapshot(person_id)
        _speak_blocking(resp)
        _tool_routed_path.append(f"tool_router.{action}")
        return resp

    if action in ("memory.forget_specific", "memory.recent_discard",
                  "emotional.boundary"):
        # Phase 2b (2026-08-13). STEP 4 of the migration pattern, and the step that
        # bit aa9acce: none of these three is in _INTENT_ACTION_MAP (verified against
        # the reverse map on this checkout — all three resolve to None), so without
        # this branch flipping the config flag would log "live action ... has no
        # intent mapping" and answer with a classic reply. Rex would SAY he forgot
        # and delete nothing, silently.
        #
        # The guards are GUARDS-ONLY for these actions now
        # (action_router.memory_boundary_refusal_reason), so passing text is both
        # safe and necessary: safe because the positive-pattern ceiling is gone,
        # necessary because a model that picks forget_specific on "Remove the lid
        # before microwaving." has to be stopped by the same code whichever router
        # chose it.
        decision = action_router.ActionDecision(
            action=action, confidence=1.0, args=dict(args or {}),
            requires_confirmation=False, reason="tool_router",
        )
        block = action_router.memory_boundary_refusal_reason(text, action)
        if block:
            _log.info("[tool_router] %s declined: %s args=%s", action, block, args)
        else:
            try:
                if action == "memory.forget_specific":
                    # A DELETE NEVER EXECUTES FROM A TOOL CALL. The tool ARMS the
                    # confirmation and reads back what would go, the same way
                    # memory.forget_person routes into the wipe-confirmation flow
                    # instead of deleting. The user's next "yes" runs the identical
                    # _execute_command("forget_specific") the regex lane ran — the
                    # door changed, not the executor. "statement" is accepted only
                    # because older logged tool calls used that name.
                    target = _router_arg_text(
                        decision, "target", "topic", "memory", "statement"
                    ) or (forgetting.extract_specific_forget_target(text) or "")
                    resp = _offer_specific_forget(person_id, target) if target else None
                    if resp:
                        _speak_blocking(resp, emotion="neutral")
                elif action == "memory.recent_discard":
                    # Speaks for itself (the confusion-grounding branch quotes the
                    # diary), so no _speak_blocking here.
                    resp = _execute_memory_boundary_command(
                        person_id, utterance=str(text or "")
                    )
                else:
                    resp = _handle_router_emotional_boundary(
                        person_id,
                        text,
                        topic_hint=_router_arg_text(decision, "topic") or (
                            _session_router_control_topics.get(int(person_id))
                            if person_id is not None else None
                        ),
                        behavior=_router_arg_text(decision, "behavior"),
                    )
                    if resp:
                        _speak_blocking(resp, emotion="neutral")
            except Exception as exc:
                _log.error("[tool_router] executor failed for %s: %s", action, exc)
                resp = None
        if resp:
            _tool_routed_path.append(f"tool_router.{action}")
            return resp
        # Declined (guard, no resolvable target, nothing recent to discard) — answer
        # as conversation so the turn is never silent, same tail as event.cancel.
        full = llm.get_response(text, person_id, classic=True)
        if full and full.strip():
            _speak_blocking(full)
        return full or ""

    if action in _PLAN_ROUTER_ACTIONS or action == "performance.impersonate":
        # humor.* / performance.* (migrated 2026-08-13). Same executors the regex
        # fast lane calls — only the door changed. Two things this branch has to
        # get right or the migration is worse than not doing it:
        #   * The evidence gate is GUARDS-ONLY for these actions now
        #     (action_router.humor_performance_refusal_reason), so passing text is
        #     both safe and necessary: safe because the positive-pattern ceiling
        #     that used to veto "give me a zinger" is gone, necessary because the
        #     refusal/narration guards from c7ef872 must still stop a model that
        #     decides to roast on "they mock me at school for my accent".
        #   * impersonate is NOT a plan-pipeline action — plan_for_action returns
        #     None for it, so _handle_router_performance_action would reject it as
        #     "unsupported_performance_action" (the trap the fast lane documents
        #     at 2026-07-19). It gets its own executor call.
        # Arg canonicalization stays in _router_execution_block_reason, which
        # rejects an invented beat/pose (unknown_body_beat / unknown_mood_pose)
        # rather than letting performance_plan coerce it to a head tilt.
        decision = action_router.ActionDecision(
            action=action, confidence=1.0, args=dict(args or {}),
            requires_confirmation=False, reason="tool_router",
        )
        block = _router_execution_block_reason(decision, text=text)
        if block:
            _log.info("[tool_router] %s declined: %s args=%s", action, block, args)
        else:
            try:
                if action == "performance.impersonate":
                    resp = _handle_router_impersonation(
                        decision, text, person_id,
                        _tool_router_person_name(person_id),
                        _impersonation_tool_target(decision, text),
                    )
                else:
                    resp = _handle_router_performance_action(decision, text, person_id)
            except Exception as exc:
                _log.error("[tool_router] executor failed for %s: %s", action, exc)
                resp = None
        if resp:
            _tool_routed_path.append(f"tool_router.{action}")
            return resp
        # Declined (refusal guard, unknown pose name, failed generation) — answer
        # as conversation so the turn is never silent, same tail as event.cancel.
        full = llm.get_response(text, person_id, classic=True)
        if full and full.strip():
            _speak_blocking(full)
        return full or ""

    if action == "game.start":
        # Step 4 of the migration checklist: without THIS branch the tail of the
        # function logs "live action game.start has no intent mapping" and answers
        # with a classic reply — Rex would TALK instead of starting the game,
        # silently (the aa9acce failure mode). game.start has no _INTENT_ACTION_MAP
        # entry and never will; the executor is the legacy one, reached through a
        # schema-validated door instead of a regex.
        # Falling back to `text` when the model named no game mirrors
        # _handle_router_takeover_action: games._normalize_game reads its aliases
        # out of the raw sentence, and games.start_game answers an unknown name
        # with the games list rather than failing.
        game = str(
            (args or {}).get("game") or (args or {}).get("game_name") or ""
        ).strip()
        block = action_router.game_request_refusal_reason(text, action)
        if block:
            _log.info("[tool_router] game.start declined: %s args=%s", block, args)
        else:
            try:
                resp = _execute_command(
                    command_parser.CommandMatch(
                        "start_game", "tool_router", {"game": game or text},
                    ),
                    person_id,
                    _tool_router_person_name(person_id),
                    text,
                )
            except Exception as exc:
                _log.error("[tool_router] executor failed for %s: %s", action, exc)
                resp = None
        if resp:
            _tool_routed_path.append(f"tool_router.{action}")
            return resp
        full = llm.get_response(text, person_id, classic=True)
        if full and full.strip():
            _speak_blocking(full)
        return full or ""

    if action == "game.stop":
        # Two executors on purpose. With a game running, use the SAME fast stop the
        # deterministic lane used (games.stop_game_fast, no LLM closing line), so
        # the tool path is never slower than the regex path it replaces. With no
        # game running, go through _execute_command: that branch carries the music
        # salvage ("stop the game" while a track plays stops the track), behavior
        # this migration must not drop on the floor.
        block = action_router.game_request_refusal_reason(text, action)
        if block:
            _log.info("[tool_router] game.stop declined: %s", block)
        else:
            try:
                from features import games as games_mod
                if games_mod.is_active():
                    resp = games_mod.stop_game_fast(person_id)
                    if resp:
                        _speak_blocking(resp, emotion="neutral")
                else:
                    resp = _execute_command(
                        command_parser.CommandMatch("stop_game", "tool_router", {}),
                        person_id,
                        _tool_router_person_name(person_id),
                        text,
                    )
            except Exception as exc:
                _log.error("[tool_router] executor failed for %s: %s", action, exc)
                resp = None
        if resp:
            _tool_routed_path.append(f"tool_router.{action}")
            return resp
        full = llm.get_response(text, person_id, classic=True)
        if full and full.strip():
            _speak_blocking(full)
        return full or ""

    if action == "motion.face":
        # "Turn to face me." Its own branch, NOT a member of _MOTION_ACTIONS: that
        # set dispatches to _handle_router_motion_action, which has no face arm and
        # returns None — Rex would answer with a classic reply and never move (the
        # aa9acce failure this file documents three times now).
        #
        # The evidence gate is the whole guard here, and it earns its keep: "face" is
        # the widest verb in the positive test (bare, no object restriction, because
        # "face me" IS the command), so without the figurative widening that landed
        # with this action, "face your fears" and "face me in chess" both cleared it.
        decision = action_router.ActionDecision(
            action=action, confidence=1.0, args={},
            requires_confirmation=False, reason="tool_router",
        )
        block = _router_execution_block_reason(decision, text=text)
        if block is None and bool(
            getattr(config, "MOTION_FACE_ME_REQUIRE_TRUSTED_TRANSCRIPT", True)
        ) and not _turn_transcript_trusted():
            block = "low_confidence_transcript"
        if block:
            _log.info("[tool_router] motion.face declined: %s", block)
        elif not motion_controller.available():
            lines = list(getattr(config, "MOTION_NO_BASE_DENIAL_LINES", []) or [])
            if lines and bool(getattr(config, "MOTION_NO_BASE_DENIAL_ENABLED", True)):
                resp = random.choice(lines)
                _log.info("[tool_router] motion.face with no base connected -> "
                          "verbal denial: text=%r", text)
                _speak_blocking(resp, emotion="neutral", log_text=False)
        else:
            try:
                resp, _turned = _handle_face_requester(person_id)
            except Exception as exc:
                _log.error("[tool_router] executor failed for %s: %s", action, exc)
                resp = None
            if resp:
                _speak_blocking(resp, emotion="neutral", log_text=False)
        if resp:
            _tool_routed_path.append(f"tool_router.{action}")
            return resp
        # Declined, or nothing to say — answer as conversation so the turn is never
        # silent, same tail as the other motion branches.
        full = llm.get_response(text, person_id, classic=True)
        if full and full.strip():
            _speak_blocking(full)
        return full or ""

    if action == "motion.route":
        # The ORGANIC path (docs/motion_route_tool_plan.md §7 Phase 2): a route
        # phrased as conversation — "back up a little and then face the other way" —
        # that never looked like one to the regex sequence parser, so the rescue arm
        # never sees it. Its own branch rather than a member of _MOTION_ACTIONS,
        # because that set dispatches to _handle_router_motion_action, which has no
        # route arm and would return None: Rex would answer with a classic reply and
        # not move (the aa9acce failure this file documents twice already).
        #
        # Unlike the rescue path this DOES run the evidence gate — the regex never
        # claimed the turn and the model chose motion.route off a persona reply call,
        # so action_router.motion_command_refusal_reason (reached through
        # _router_execution_block_reason, the only call that also applies
        # ACTION_ROUTER_EXECUTE_ACTIONS) is the whole guard against a six-step drive
        # invented out of "we should do a lap sometime".
        decisions, refusal = _motion_route_from_tool_args(args or {})
        drove = False
        decision = action_router.ActionDecision(
            action=action, confidence=1.0,
            args={"steps": len(decisions or [])},
            requires_confirmation=False, reason="tool_router",
        )
        block = _router_execution_block_reason(decision, text=text)
        if block is None and _motion_route_transcript_blocked():
            block = "low_confidence_transcript"
        if block is None and decisions and not _motion_route_legs_executable(decisions):
            block = "leg_not_in_execute_allowlist"
        if block or not decisions:
            _log.info("[tool_router] motion.route declined: %s args=%s",
                      block or refusal, args)
        elif not motion_controller.available():
            # Same rail the single verbs get: with no wheels there is no physical
            # acknowledgment, so Rex says so out loud rather than falling through to
            # a reply that pretends the command landed.
            lines = list(getattr(config, "MOTION_NO_BASE_DENIAL_LINES", []) or [])
            if lines and bool(getattr(config, "MOTION_NO_BASE_DENIAL_ENABLED", True)):
                resp = random.choice(lines)
                _log.info("[tool_router] motion.route with no base connected -> "
                          "verbal denial: text=%r", text)
                _speak_blocking(resp, emotion="neutral", log_text=False)
        else:
            try:
                _clear_motion_continuation()
                resp, drove = _handle_motion_route(
                    decisions, requester_person_id=person_id
                )
            except Exception as exc:
                _log.error("[tool_router] executor failed for %s: %s", action, exc)
                resp, drove = None, False
            if resp:
                _speak_blocking(resp, emotion="neutral", log_text=False)
        if bool(getattr(config, "MOTION_ROUTE_SHADOW_LOG_ENABLED", True)):
            from intelligence import motion_route as _mr
            _mr.log_shadow(text, {"args": args, "secs": 0.0}, decisions,
                           block or refusal, executed=drove)
        if resp:
            _tool_routed_path.append(f"tool_router.{action}")
            return resp
        # Declined (evidence gate, allowlist, shaky transcript, a plan outside the
        # clamps, or the base itself suppressing it) — answer as conversation so the
        # turn is never silent, same tail as the single verbs below.
        full = llm.get_response(text, person_id, classic=True)
        if full and full.strip():
            _speak_blocking(full)
        return full or ""

    if action in _MOTION_ACTIONS:
        # Phase 3 (2026-08-13, docs/tool_router_scope.md §3) — the LAST family, and
        # the only one that did NOT get the detector-not-claim demotion. motion.* is
        # deliberately absent from action_router.TOOL_ROUTER_OWNED_ACTIONS: the regex
        # fast lane still claims a >=0.95 match and executes at today's latency, so
        # this branch only ever sees turns the classifier MISSED. Measured on this
        # checkout, all of these classify as None and became conversation: "rotate
        # ninety degrees", "back yourself up a bit", "scoot a little closer", "get
        # closer", "back it up", "hang a left", "face me", "drive up here", "point
        # yourself at the window", "why don't you scoot forward".
        #
        # STEP 4 of the new-executable-action checklist, and the step that bit
        # aa9acce: no motion.* key exists in _INTENT_ACTION_MAP, so WITHOUT this
        # branch flipping the config flag makes the tail of this function log "live
        # action motion.move has no intent mapping" and answer with a classic reply —
        # Rex would SAY "Rolling forward." and not move.
        decision = action_router.ActionDecision(
            action=action, confidence=1.0,
            args=_motion_args_from_tool(action, args, text),
            requires_confirmation=False, reason="tool_router",
        )
        # _router_execution_block_reason, NOT the bare public guard the other families
        # call, because this one drives a base: it is the single call that also applies
        # config.ACTION_ROUTER_EXECUTE_ACTIONS (the motion kill switch added in
        # c7ef872 — drop a key in user_config.py and that maneuver stops executing)
        # on top of action_router.missing_required_evidence_reason ->
        # motion_command_refusal_reason. The 0.85 confidence floor is passed trivially
        # at 1.0, and that is stated rather than hidden: a tool call carries no
        # self-reported confidence for the floor to judge, so on this path the
        # evidence gate is the whole guard.
        block = _router_execution_block_reason(decision, text=text)
        if block:
            _log.info("[tool_router] %s declined: %s args=%s", action, block, args)
        elif not motion_controller.available():
            # The one safety rail that does NOT come for free with the shared
            # executor: _handle_router_motion_action returns None with no base, which
            # would fall through to a reply that pretends the command landed —
            # silence/pretence read as "he ignores my commands" (field 2026-07-23).
            # _motion_no_base_denial_line is NOT reusable here: its evidence IS
            # classify_explicit_motion, the classifier that by definition missed this
            # turn, so it would always return None. Key the denial on the ACTION.
            lines = list(getattr(config, "MOTION_NO_BASE_DENIAL_LINES", []) or [])
            if lines and action in _MOTION_DRIVE_ACTIONS and bool(
                getattr(config, "MOTION_NO_BASE_DENIAL_ENABLED", True)
            ):
                resp = random.choice(lines)
                _log.info("[tool_router] %s with no base connected -> verbal denial: "
                          "text=%r", action, text)
                _speak_blocking(resp, emotion="neutral", log_text=False)
        else:
            try:
                # Every other downstream rail lives INSIDE this executor and the
                # migration does not touch any of them: motion_controller.charging()
                # (wheels stay locked on the charger), motion_agency.no_drive_room()
                # (the carpet / no-drive rule the owner set by voice, declined with
                # the way out stated), note_user_motion()'s realign standdown,
                # note_user_commanded_motion()'s overlay confirmation and
                # _cancel_motion_sequence's supersede. The firmware ToF gate and the
                # ±10 m / ±360° clamps sit downstream of that.
                resp = _handle_router_motion_action(
                    decision, requester_person_id=person_id
                )
            except Exception as exc:
                _log.error("[tool_router] executor failed for %s: %s", action, exc)
                resp = None
            if resp:
                # The executor returns the line; the FAST lane is what normally speaks
                # it, so the tool path has to.
                _speak_blocking(resp, emotion="neutral", log_text=False)
        if resp:
            _tool_routed_path.append(f"tool_router.{action}")
            return resp
        # Declined (evidence gate, allowlist, no base with denial lines off, or the
        # base itself suppressed the command) — answer as conversation so the turn is
        # never silent, same tail as game.start.
        full = llm.get_response(text, person_id, classic=True)
        if full and full.strip():
            _speak_blocking(full)
        return full or ""

    if action in ("music.stop", "music.skip"):
        key = "dj_stop" if action == "music.stop" else "dj_skip"
        try:
            resp = _execute_command(
                command_parser.CommandMatch(key, "tool_router", {}),
                person_id,
                _tool_router_person_name(person_id),
                text,
            )
        except Exception as exc:
            _log.error("[tool_router] executor failed for %s: %s", action, exc)
            resp = None
        if resp:
            _tool_routed_path.append(f"tool_router.{action}")
            return resp

    if action == "event.cancel":
        # Off-pattern cancellations ("we're not going to Lake Folsom anymore",
        # field 2026-08-02) — mirror the router's event.cancel branch: cancel
        # matching stored events (events_memory.looks_like_cancellation stays
        # as the write guard), resolve open commitments, ack in character.
        resp = None
        try:
            hint = str((args or {}).get("event_hint") or "").strip()
            cancel_pid = person_id
            if cancel_pid is None:
                try:
                    cancel_pid = consciousness.get_last_memory_hint_target()
                except Exception:
                    cancel_pid = None
            labels = _cancel_stale_event_memory(
                cancel_pid, text,
                event_hint={"event_name": hint} if hint else None,
            )
            if not labels:
                events_memory.postpone_matching_events(cancel_pid, text)
            try:
                events_memory.resolve_matching_commitments(cancel_pid, text)
            except Exception as commit_exc:
                _log.debug("[tool_router] commitments resolve failed: %s", commit_exc)
            if not labels and hint and events_memory.looks_like_cancellation(text):
                # LLM-confirmed cancel with no stored row — still acknowledge
                # so the user hears the plan is off (matches router behavior).
                labels = [hint]
            if labels:
                resp = _event_cancellation_ack(labels, cancel_pid)
                _speak_blocking(resp)
        except Exception as exc:
            _log.error("[tool_router] event.cancel failed: %s", exc)
            resp = None
        if resp:
            _tool_routed_path.append(f"tool_router.{action}")
            return resp
        # Nothing matched — treat as conversation (the reply LLM handles it).
        full = llm.get_response(text, person_id, classic=True)
        if full and full.strip():
            _speak_blocking(full)
        return full or ""

    if action in ("system.shutdown", "system.sleep"):
        if action == "system.shutdown":
            key = "shutdown" if command_parser.is_shutdown_request(text) else None
        else:
            key = "sleep" if command_parser.is_sleep_request(text) else None
        if key is None:
            _log.info("[tool_router] %s rejected by parser backstop text=%r",
                      action, text)
        else:
            try:
                resp = _execute_command(
                    command_parser.CommandMatch(key, "tool_router", {}),
                    person_id,
                    _tool_router_person_name(person_id),
                    text,
                )
            except Exception as exc:
                _log.error("[tool_router] executor failed for %s: %s", action, exc)
        if resp:
            _tool_routed_path.append(f"tool_router.{action}")
            return resp
        intent = None
    if intent is not None:
        try:
            if intent == "query_who_is_speaking":
                # This handler answers from BIOMETRIC ground truth, and the tool
                # path was the only caller not passing it: the intent lane and
                # _handle_router_takeover_action both thread raw_best_* through,
                # so a tool-routed "who's speaking?" silently took the no-match
                # branch ("no idea, who's asking?") even on a 0.9 voice score.
                # Live since 2026-08-02, but Stage 1 makes the tool the PRIMARY
                # route for the loose phrasings, so the gap had to close first.
                ev = _current_turn_speaker_evidence or {}
                resp = _handle_classified_intent(
                    intent, text, person_id,
                    raw_best_id=ev.get("raw_best_id"),
                    raw_best_name=ev.get("raw_best_name"),
                    raw_best_score=float(ev.get("raw_best_score") or 0.0),
                )
            else:
                resp = _handle_classified_intent(intent, text, person_id)
        except Exception as exc:
            _log.error("[tool_router] executor failed for %s: %s", action, exc)
    else:
        _log.warning("[tool_router] live action %s has no intent mapping", action)
    if resp:
        _tool_routed_path.append(f"tool_router.{action}")
        return resp
    # Executor declined/failed: answer as plain conversation so the turn is
    # never silent (rare — every live action maps to a handler).
    full = llm.get_response(text, person_id, classic=True)
    if full and full.strip():
        _speak_blocking(full)
    return full or ""


def _reply_frame_why(frame, comedy_mode, cb_claim) -> str:
    """Plain words for how this reply was framed — the ledger's record of a
    normal reply, so 'why did you roast me?' can be answered from the frame."""
    purpose = str(getattr(frame, "purpose", "") or "").replace("_", " ")
    roast = str(getattr(frame, "allow_roast", "") or "")
    stance = str(getattr(comedy_mode, "label", "") or getattr(comedy_mode, "key", "") or "")
    bits = [f"I framed my reply as '{purpose}'" if purpose else "I framed my reply"]
    if stance and stance != "straight":
        bits.append(f"in a '{stance}' comedy stance")
    elif stance == "straight":
        bits.append("played straight, no jokes")
    if roast == "none":
        bits.append("with roasting OFF")
    elif roast in {"sharp", "normal"}:
        bits.append(f"with a {roast} roast allowed")
    if cb_claim is not None:
        prem = " ".join(str(getattr(cb_claim, "premise", "") or "").split())[:80]
        if prem:
            bits.append(f"and called back to an earlier bit ({prem})")
    return " ".join(bits)


def _stream_llm_response(
    text: str,
    person_id: Optional[int],
    answered_question: Optional[dict] = None,
    turn_start: Optional[float] = None,
) -> str:
    """Collect the full LLM response, then speak it in a single TTS call.

    Collecting before speaking keeps AEC suppression as one continuous window
    per response. At max_tokens=150 the added latency is negligible.
    """
    # Queeny-mode trigger (intelligence/pride.py): "are you gay?" arms the overlay
    # BEFORE any reply tokens stream, so the answer itself is already in register.
    # Arming also throws the physical flourish (head down, visor wide, wrist out, held)
    # — async, so it plays over the LLM round trip and is done by the time he answers.
    try:
        from intelligence import pride as _pride
        if _pride.maybe_trigger(text):
            from sequences import animations as _animations
            _animations.pride_flourish()
    except Exception as exc:
        _log.debug("[pride] trigger hook skipped: %s", exc)
    # Homie-mode trigger (intelligence/homie.py): "wassup homie" arms the AAVE
    # overlay BEFORE any reply tokens stream, so the greeting-back is already in
    # register. Voice-only — no flourish.
    try:
        from intelligence import homie as _homie
        _homie.maybe_trigger(text)
    except Exception as exc:
        _log.debug("[homie] trigger hook skipped: %s", exc)
    # Current-info web search branch: when the turn needs live data (explicit ask or
    # autonomous gate), Rex looks it up and speaks the answer here, skipping the normal
    # reply. Failure-safe — on no-trigger / no-result it returns None and we proceed.
    # A follow-up about the news story Rex just offered ("tell me more about that")
    # forces the search, grounded on the cached headline/summary (field 2026-08-04
    # 23:09: the context-free follow-up died silent and the subject changed).
    news_followup = _news_followup_story(text)
    web_answer = _maybe_web_search_reply(
        text, person_id, turn_start=turn_start, news_story=news_followup
    )
    if web_answer is not None:
        return web_answer
    # Fire the surprise classifier in parallel with the main LLM stream so
    # its result is (usually) ready by the time the response text is in hand.
    # If it returns is_surprising=True before we speak, we prepend a brief
    # silent beat — Rex's "...huh, didn't see that coming" pause.
    surprise_result: dict[str, bool] = {"value": False}

    def _classify() -> None:
        try:
            surprise_result["value"] = llm.classify_surprise(text)
        except Exception as exc:
            _log.debug("surprise classify thread error: %s", exc)

    surprise_thread = threading.Thread(
        target=_classify, daemon=True, name="surprise-classify"
    )
    surprise_thread.start()

    cb_claim = None
    cb_settled = False
    lean_callback_directive = ""
    filler_stop = _start_latency_filler_timer()
    try:
        turn_plan = conversation_agenda.build_turn_plan(
            text,
            person_id,
            answered_question=answered_question,
        )
        agenda_directive = turn_plan.directive
        # Cancelled-plan empathy (owner note 2026-08-02: "we're not going
        # anymore" about paddleboarding got "Good, because paddleboarding was
        # already doing the most" — the persona roasts whatever it hears).
        # A called-off plan gets warmth, not a victory lap.
        try:
            if events_memory.looks_like_cancellation(text):
                agenda_directive = (
                    (agenda_directive + " | " if agenda_directive else "")
                    + "They just called OFF a plan or event. Do NOT say 'good', "
                    "celebrate, or roast the plan — be warm: one brief beat of "
                    "sympathy (it sounded fun / that's a shame), then ONE light "
                    "question about what they're doing instead."
                )
        except Exception as exc:
            _log.debug("cancellation empathy directive skipped: %s", exc)
        frame = social_frame.build_frame(
            text,
            person_id,
            answered_question=answered_question,
            agenda_directive=agenda_directive,
            turn_plan=turn_plan,
        )
        comedy_mode = comedy_modes.select_mode(
            text,
            person_id,
            frame=frame,
            agenda_directive=agenda_directive,
        )
        # Banked-callback claim: if every tone/pacing gate clears AND the
        # background relevance judge connected a stored premise to the live
        # topic, this turn's single callback slot is claimed and the premise
        # rides in as the comedy stance (callback_banked mode). Must run BEFORE
        # the directive is rendered. llm._build_person_context sees the claim
        # (callback_engine.turn_claim_active) and stands down its own hook chain
        # (one callback per reply).
        try:
            from intelligence import callback_engine as _cb_engine
            cb_claim = _cb_engine.maybe_claim_reactive(
                person_id,
                text,
                frame=frame,
                comedy_mode=comedy_mode,
                turn_plan=turn_plan,
            )
            if cb_claim is not None:
                lean_callback_directive = _cb_engine.build_callback_directive(cb_claim)
                comedy_mode = comedy_modes.with_banked_premise(
                    comedy_mode,
                    lean_callback_directive,
                )
        except Exception as exc:
            cb_claim = None
            _log.debug("[callback_engine] reactive claim failed: %s", exc)
        # Unprompted impression claim (features/organic_impersonation.py): a
        # famous name in the utterance, or a mock-worthy line in a voice Rex has
        # captured. Prep runs in the background behind THIS reply; the only thing
        # it needs from the reply is a directive so the model doesn't perform the
        # same impression in prose first. Speaks later, from its own thread.
        try:
            from features import organic_impersonation as _organic
            _organic_directive = _organic.maybe_claim(text, person_id, frame=frame) or ""
        except Exception as exc:
            _organic_directive = ""
            _log.debug("[organic_impersonation] claim failed: %s", exc)
        if _organic_directive:
            lean_callback_directive = "\n".join(
                s for s in (lean_callback_directive, _organic_directive) if s
            )
        # Decision ledger (intelligence/decision_ledger.py): the reply's framing
        # is itself a decision the code made — record it — and when the person
        # is asking WHY Rex did something, hand the model the real record.
        try:
            from intelligence import decision_ledger as _ledger
            _why_directive = _ledger.why_directive(text) or ""
            _ledger.record(
                "reply_frame",
                _reply_frame_why(frame, comedy_mode, cb_claim),
                detail={"purpose": getattr(frame, "purpose", ""),
                        "comedy_mode": getattr(comedy_mode, "key", ""),
                        "roast": getattr(frame, "allow_roast", "")},
            )
        except Exception as exc:
            _why_directive = ""
            _log.debug("[decision_ledger] hook failed: %s", exc)
        if _why_directive:
            lean_callback_directive = "\n".join(
                s for s in (lean_callback_directive, _why_directive) if s
            )
        if getattr(config, "TURN_PLANNER_SLIM_CONTRACT", True):
            # Phase 1 / "Bet 2": hand the LLM ONE compact contract instead of the
            # ~40-segment stacked block. frame + comedy_mode were computed from the
            # RICH directive above (so every regex-consumer still sees it); only the
            # LLM-facing string shrinks. govern_response (post-gen) reads the
            # structured frame, so the safety net is unchanged.
            primary_purpose = _extract_primary_purpose(turn_plan.directive)
            agenda_directive = social_frame.render_slim_contract(
                frame, primary_purpose=primary_purpose
            )
            # The slim contract drops the rich comedy block, but the per-turn comedic
            # STANCE still has to reach the LLM or the whole humor stack (premise
            # rotation, self-own lanes, line banks) is dead text. A CLAIMED banked
            # callback takes the richer build_directive() path (it carries the premise
            # text — the only path it travels); every other humor-eligible turn gets
            # the compact build_slim_directive() stance instead. "straight" (care)
            # turns yield "" from both, so they stay clean.
            if cb_claim is not None:
                callback_directive = comedy_modes.build_directive(comedy_mode)
                if callback_directive:
                    agenda_directive = "\n".join([agenda_directive, callback_directive])
            else:
                slim_comedy = comedy_modes.build_slim_directive(comedy_mode)
                if slim_comedy:
                    agenda_directive = "\n".join([agenda_directive, slim_comedy])
        else:
            agenda_directive = "\n".join([
                agenda_directive,
                social_frame.build_directive(frame),
                comedy_modes.build_directive(comedy_mode),
            ])
        if news_followup is not None:
            # The forced search above fell through (disabled / failed / no
            # citations) — ground the normal reply on the cached story so "tell
            # me more" is answered with content, not a subject change. Appended
            # AFTER the slim-contract render so it actually reaches the LLM.
            _nf_headline = str(news_followup.get("headline") or "").strip()
            _nf_summary = str(news_followup.get("summary") or "").strip()
            agenda_directive = "\n".join([
                agenda_directive,
                "They are asking about the news story you brought up: "
                f'"{_nf_headline}" — {_nf_summary} Actually tell them about it: '
                "share those concrete details (what, when, where) in 2-4 "
                "sentences before any joke, and do NOT change the subject. If "
                "they want more than you know, say that's the whole scoop you "
                "picked up.",
            ])
        _log.info("[agenda] %s", agenda_directive.replace("\n", " | "))
        _full_streaming = bool(getattr(config, "LLM_STREAMING_TTS_ENABLED", True))
        _first_split = bool(getattr(config, "TTS_FIRST_SENTENCE_SPLIT_ENABLED", True))
        if (
            (_full_streaming or _first_split)
            and not bool(
                getattr(config, "NO_AUDIO_MODE", False)
                or getattr(config, "AUDIO_OUTPUT_SUPPRESSED", False)
            )
            and not _interrupted.is_set()
        ):
            from intelligence import tool_router as _tr
            try:
                spoken = _stream_and_speak_sentences(
                    text,
                    person_id,
                    frame,
                    comedy_mode,
                    agenda_directive,
                    surprise_result,
                    surprise_thread,
                    turn_start,
                    filler_stop,
                    # Full per-sentence streaming (when explicitly enabled) wins; else the
                    # two-chunk middle path: first sentence early, one seam, rest as one
                    # generation while chunk 1 plays.
                    two_chunk=not _full_streaming,
                    lean_turn_directive=lean_callback_directive,
                )
            except _tr.ToolCallRequested as tc:
                spoken = _execute_tool_routed_action(tc.action, tc.tool_args, text, person_id)
            if cb_claim is not None:
                cb_settled = True
                _settle_callback_claim(spoken)
            return spoken
        llm_started = time.monotonic()
        if bool(getattr(config, "LEAN_BRAIN_ENABLED", False)):
            from intelligence import tool_router as _tr
            try:
                from intelligence import lean_brain
                full_text = lean_brain.respond(
                    text, person_id,
                    transcript=_lean_recent_transcript(text),
                    world=_lean_world(),
                    turn_directive=lean_callback_directive or None,
                ).get("text") or ""
            except _tr.ToolCallRequested as tc:
                # Non-streaming path: same live-tool dispatch as the streaming
                # branch. Executor already spoke; settle any callback claim so
                # it can't leak into later turns, and return without the normal
                # govern/speak tail (nothing left to speak).
                full_text = _execute_tool_routed_action(tc.action, tc.tool_args, text, person_id)
                if cb_claim is not None and not cb_settled:
                    cb_settled = True
                    _settle_callback_claim(full_text or "")
                return full_text
            except Exception as exc:
                _log.error("[lean] non-streaming reply failed, using classic path: %s", exc)
                full_text = llm.get_response(text, person_id, agenda_directive=agenda_directive, classic=True)
        else:
            full_text = llm.get_response(
                text,
                person_id,
                agenda_directive=agenda_directive,
            )
        if turn_start is not None:
            _latency_log(turn_start, "llm_response", llm_started)
    except BaseException:
        # An exception mid-generation must not leak the claim into later turns
        # (turn_claim_active would mute llm.py's hook chain for up to 60s).
        if cb_claim is not None and not cb_settled:
            cb_settled = True
            _settle_callback_claim("")
        raise
    finally:
        filler_stop.set()

    pre_beat_ms = 0
    delivery_emotion = "neutral"
    delivery_post_beat_ms = 0
    delivery_voice_settings: Optional[dict] = None
    if full_text and full_text.strip() and not _interrupted.is_set():
        try:
            governed = social_frame.govern_response(full_text, frame)
            full_text = governed.text
        except Exception as exc:
            _log.debug("social frame governor failed: %s", exc)
        try:
            full_text = comedy_modes.polish_response(
                full_text,
                comedy_mode,
                allow_roast=frame.allow_roast,
            )
        except Exception as exc:
            _log.debug("comedy polish failed: %s", exc)

        # Brief join — classifier usually finishes before or alongside the
        # main response since its prompt is tiny. Cap the wait so a slow
        # classifier never delays Rex perceptibly.
        surprise_thread.join(timeout=0.3)
        if surprise_result["value"]:
            try:
                _play_event_body_beat("emotion.surprise")
            except Exception as exc:
                _log.debug("[interaction] surprise body beat skipped: %s", exc)
            delivery_emotion = "surprised"
            beat_min = getattr(config, "SURPRISE_PAUSE_MS_MIN", 500)
            beat_max = getattr(config, "SURPRISE_PAUSE_MS_MAX", 1000)
            if beat_max >= beat_min > 0:
                pre_beat_ms = random.randint(beat_min, beat_max)
                _log.info("[interaction] surprise beat: %d ms", pre_beat_ms)

        # Empathy-mode delivery shaping: sympathetic posture + pacing for
        # listen/support/etc. without changing the cached TTS audio (cache key
        # is text+voice+model — emotion only drives LEDs and body bias).
        try:
            overrides = empathy.get_delivery_overrides(person_id)
        except Exception as exc:
            _log.debug("empathy.get_delivery_overrides error: %s", exc)
            overrides = None
        if overrides:
            if overrides.get("emotion") and not surprise_result["value"]:
                delivery_emotion = overrides["emotion"]
            extra_pre = int(overrides.get("pre_beat_ms") or 0)
            if extra_pre > 0:
                # Take the larger of surprise-beat vs empathy-mode beat — they
                # serve the same "let it land" purpose and shouldn't stack.
                pre_beat_ms = max(pre_beat_ms, extra_pre)
            delivery_post_beat_ms = int(overrides.get("post_beat_ms") or 0)
            delivery_voice_settings = overrides.get("voice_settings")
            _log.info(
                "[empathy] delivery shaping: mode=%s emotion=%s pre=%dms post=%dms voice=%s",
                overrides.get("mode"), delivery_emotion,
                pre_beat_ms, delivery_post_beat_ms,
                delivery_voice_settings if delivery_voice_settings else "default",
            )

        # Comedic delivery profile — give the chosen comedy STANCE its own timbre
        # (deadpan / smug / ...), but ONLY when empathy left the voice alone.
        # Empathy/grief delivery outranks comedy: a sympathetic mode that already
        # shaped the voice above is never overwritten. "straight" (care) modes
        # carry no profile, so sensitive turns are never comedically shaped.
        if delivery_voice_settings is None:
            try:
                comedy_voice = comedy_modes.voice_settings_for_mode(comedy_mode)
            except Exception as exc:
                _log.debug("[comedy] delivery profile error: %s", exc)
                comedy_voice = None
            if comedy_voice:
                delivery_voice_settings = comedy_voice
                _log.info(
                    "[comedy] delivery profile: mode=%s voice=%s",
                    getattr(comedy_mode, "key", "?"), comedy_voice,
                )

        # Non-streaming path: the whole reply is in hand, so classify Rex's own tone
        # directly and let it drive the delivery emotion (eyes/voice/motion) + a body-
        # mood afterglow. Surprise/empathy keep priority. Skipped with audio suppressed
        # (no speech/LEDs to express, so the local call would be wasted work).
        if (
            delivery_emotion == "neutral"
            and not surprise_result["value"]
            and not bool(
                getattr(config, "NO_AUDIO_MODE", False)
                or getattr(config, "AUDIO_OUTPUT_SUPPRESSED", False)
            )
        ):
            try:
                self_emotion = llm.classify_self_emotion(full_text)
            except Exception as exc:
                _log.debug("[interaction] self-emotion classify error: %s", exc)
                self_emotion = "neutral"
            if self_emotion and self_emotion != "neutral":
                delivery_emotion = self_emotion
                _set_body_mood(
                    self_emotion,
                    source="self_emotion",
                    intensity=float(getattr(config, "SELF_EMOTION_BODY_MOOD_INTENSITY", 0.6)),
                )

        speak_started = time.monotonic()
        completed = _speak_blocking(
            full_text,
            emotion=delivery_emotion,
            pre_beat_ms=pre_beat_ms,
            post_beat_ms_override=delivery_post_beat_ms,
            voice_settings=delivery_voice_settings,
            comedy_mode=getattr(comedy_mode, "key", None),
        )
        if turn_start is not None:
            _latency_log(turn_start, "tts_playback_complete", speak_started)
        if completed and frame.purpose == "identity" and "?" in full_text:
            _arm_visible_unknown_identity_followup(
                person_id,
                source="agenda_llm_identity",
            )
    if cb_claim is not None and not cb_settled:
        cb_settled = True
        _settle_callback_claim(
            full_text if (full_text or "").strip() and not _interrupted.is_set() else ""
        )
    return full_text


def _settle_callback_claim(spoken_text: str) -> None:
    """Spend-or-release the turn's banked-callback claim against what Rex
    actually said (spend-at-speak — never spend at injection)."""
    try:
        from intelligence import callback_engine as _cb_engine
        _cb_engine.settle_turn(spoken_text or "")
    except Exception as exc:
        _log.debug("[callback_engine] settle failed: %s", exc)


# ─────────────────────────────────────────────────────────────────────────────
# Streaming response → TTS (speak sentence-by-sentence as the LLM generates)
# ─────────────────────────────────────────────────────────────────────────────

# A sentence boundary: a run of . ! ? (plus any closing quotes/brackets)
# followed by whitespace. Trailing punctuation at the very end of the buffer is
# treated as still-in-progress, since more tokens may be coming.
_STREAM_SENTENCE_BOUNDARY_RE = re.compile(r'[.!?]+["\')\]’”]*\s')
_STREAM_TAIL_TERMINAL_RE = re.compile(r'[.!?…]["\')\]’”]*$')

# A tail ending in an ellipsis ("…" or "...") — the model trailing off.
_ELLIPSIS_TAIL_RE = re.compile(r'(?:…|\.{2,})["\')\]’”]*\s*$')

# Connector / article / auxiliary words that leave an UNFINISHED thought when an
# ellipsis trail-off ends on them ("…the excitement of…", "…I mean, I've…"). Such
# a tail passes the terminal-punctuation check (… is terminal) but the ellipsis is
# stripped before TTS, so what gets spoken is a bare dangling fragment that lands
# as a hard cut-off. Deliberately excludes words that can legitimately END a
# sentence ("this", "to", "is") so only genuinely-dangling trail-offs are dropped.
_DANGLING_TAIL_WORDS = frozenset({
    "a", "an", "the", "of", "with", "for", "into", "about", "than", "and", "or",
    "but", "my", "your", "his", "her", "their", "its", "our",
    "i'm", "i've", "you're", "we're", "they're", "it's", "he's", "she's",
})


def _tail_is_speakable(tail: str) -> bool:
    """A leftover stream tail is spoken only if it's a finished sentence. An
    unpunctuated remainder means the model was cut mid-sentence ("What's the
    deal", "Glad to") — speaking it would emit a truncated fragment, so drop it.
    A tail the model trailed off on mid-clause with an ELLIPSIS ("…the excitement
    of…") also reads as a hard cut-off once TTS strips the ellipsis, so drop it
    when it ends on a dangling connector word. A '.'/'!'/'?' sentence is a finished
    thought even if it ends on "this"/"to" — keep it."""
    t = (tail or "").strip()
    if not t or not _STREAM_TAIL_TERMINAL_RE.search(t):
        return False
    if _ELLIPSIS_TAIL_RE.search(t):
        words = re.findall(r"[a-z']+", t.lower())
        if words and words[-1] in _DANGLING_TAIL_WORDS:
            return False
    return True


def _split_stream_sentences(buffer: str, min_chars: int) -> tuple[list[str], str]:
    """Pull complete sentences out of a growing stream buffer.

    Returns (complete_sentences, remainder). A finished sentence shorter than
    min_chars is merged into the following one, which keeps tiny fragments,
    initials, abbreviations, and decimals (e.g. "Dr.", "3.") from splitting into
    choppy one-word bursts.
    """
    # Protect abbreviations (Mrs./Dr./St./e.g./U.S.) so the period inside one is not
    # read as a sentence boundary — that split "Mrs. Doubtfire" into "Mrs." + a
    # mangled tail and TTS dropped the title. Reuses social_frame's abbreviation
    # table; offsets are taken against the protected text and restored on the way out.
    protected, replacements = social_frame._protect_abbreviations(buffer or "")
    sentences: list[str] = []
    pending_start = 0
    floor = max(1, int(min_chars or 1))
    for match in _STREAM_SENTENCE_BOUNDARY_RE.finditer(protected):
        candidate = protected[pending_start:match.end()].strip()
        if len(candidate) >= floor:
            sentences.append(candidate)
            pending_start = match.end()
    restore = social_frame._restore_abbreviations
    return (
        [restore(s, replacements) for s in sentences],
        restore(protected[pending_start:], replacements),
    )


def _complete_sentence_prefix(text: str) -> str:
    """Trim `text` to its last COMPLETE sentence, dropping a trailing mid-sentence
    fragment (the model got cut off by max_tokens). Uses min_chars=1 so a short but
    finished sentence ("Wow indeed!") is recognized rather than merged into the
    truncated tail. Returns "" when nothing complete remains. Used by the streaming
    safety-net fallback so it never re-emits a cut-off fragment ("Wow indeed! I")."""
    t = (text or "").strip()
    if not t:
        return ""
    sentences, remainder = _split_stream_sentences(t, 1)
    remainder = remainder.strip()
    if remainder and _tail_is_speakable(remainder):
        sentences.append(remainder)
    return " ".join(s for s in sentences if s).strip()


def _streaming_surprise_beat(surprise_result: dict) -> int:
    """Pre-beat (ms) before the first sentence when the utterance is surprising.

    Reads the in-flight surprise classifier result without blocking — if it has
    not resolved by the time the first sentence is ready, the beat is skipped so
    the first word is never delayed.
    """
    if not surprise_result.get("value"):
        return 0
    beat_min = getattr(config, "SURPRISE_PAUSE_MS_MIN", 500)
    beat_max = getattr(config, "SURPRISE_PAUSE_MS_MAX", 1000)
    if beat_max >= beat_min > 0:
        return random.randint(beat_min, beat_max)
    return 0


def _lean_recent_transcript(user_text: str) -> list[dict]:
    """Recent session turns for the lean brain, EXCLUDING the current user turn (the lean brain
    appends it itself). Empty on any error."""
    try:
        rows = conv_memory.get_session_transcript() or []
    except Exception:
        return []
    turns = [
        {"speaker": r.get("speaker"), "text": r.get("text")}
        for r in rows if str(r.get("text") or "").strip()
    ]
    if turns and str(turns[-1].get("text") or "").strip() == str(user_text or "").strip():
        turns = turns[:-1]
    return turns


def _lean_world() -> Optional[dict]:
    try:
        from world_state import world_state as _ws
        return _ws.snapshot()
    except Exception:
        return None


def _reply_token_stream(
    user_text: str, person_id, agenda_directive, lean_turn_directive: str = ""
):
    """Reply generator: the LEAN brain (one coherent call — persona + small context + recent
    turns) when LEAN_BRAIN_ENABLED, else the classic assembled-prompt path. A lean init error
    falls back to the classic path so a hiccup never breaks a live turn."""
    if bool(getattr(config, "LEAN_BRAIN_ENABLED", False)):
        try:
            from intelligence import lean_brain
            return lean_brain.stream_reply(
                user_text, person_id,
                transcript=_lean_recent_transcript(user_text),
                world=_lean_world(),
                turn_directive=lean_turn_directive or None,
            )
        except Exception as exc:
            _log.error("[lean] live reply init failed, using classic path: %s", exc)
    # classic=True: this is the reply-path fallback — if the lean brain failed, use the classic
    # assembled prompt for resilience, not the one-voice lean directive path.
    return llm.stream_response(user_text, person_id, agenda_directive=agenda_directive, classic=True)


def _prepare_stream_sentence(sentence: str, frame, comedy_mode) -> str:
    """Govern + polish a single streamed sentence; "" means skip it."""
    if bool(getattr(config, "LEAN_BRAIN_ENABLED", False)):
        # The lean brain owns the whole reply — don't let the OLD frame's question/roast/
        # visual/length gates mangle it. Keep ONLY the always-on cruelty scrub + normalize.
        try:
            if social_frame.contains_cruelty(sentence):
                return ""
        except Exception:
            pass
        cleaned = llm.clean_response_text(sentence or "")
        return cleaned.strip() if cleaned else ""
    governed = social_frame.govern_stream_sentence(sentence, frame)
    if not governed:
        return ""
    try:
        governed = comedy_modes.polish_stream_sentence(
            governed, comedy_mode, allow_roast=frame.allow_roast
        )
    except Exception as exc:
        _log.debug("[interaction] stream polish failed: %s", exc)
    governed = llm.clean_response_text(governed or "")
    return governed.strip() if governed else ""


def _prefetch_stream_audio(
    text: str, emotion: str, voice_settings: Optional[dict],
    previous_text: Optional[str] = None,
) -> None:
    """Warm the TTS cache for an upcoming sentence so playback doesn't gap."""
    def _run() -> None:
        try:
            from audio import tts
            # Only 2nd+ sentences of a reply are prefetched, and those suppress the audio tag —
            # match that here (and the stitched previous_text) so the warmed cache key equals what
            # the suppressed enqueue looks up.
            tts.ensure_cached(
                text, voice_settings=voice_settings, emotion=emotion,
                suppress_audio_tag=True, previous_text=previous_text,
            )
        except Exception as exc:
            _log.debug("[interaction] stream prefetch failed: %s", exc)

    threading.Thread(target=_run, daemon=True, name="tts-prefetch").start()


def _await_streamed_speech(
    done_events: list[threading.Event], priority: int
) -> bool:
    """Block until every queued sentence finishes; honor wake-word interruption.

    Mirrors _speak_blocking's interruption handling across multiple queued
    items: on interrupt, cut current playback and drop the remaining sentences.
    Returns True on normal completion, False if cut short.
    """
    for done in done_events:
        while not done.wait(timeout=0.05):
            if _interrupted.is_set():
                try:
                    import sounddevice as sd
                    echo_cancel.request_cancel()
                    sd.stop()
                except Exception:
                    pass
                speech_queue.clear_below_priority(priority + 1)
                done.wait(timeout=0.5)
                return False
    return True


def _stream_and_speak_sentences(
    user_text: str,
    person_id: Optional[int],
    frame,
    comedy_mode,
    agenda_directive: str,
    surprise_result: dict,
    surprise_thread: Optional[threading.Thread],
    turn_start: Optional[float],
    filler_stop: threading.Event,
    two_chunk: bool = False,
    lean_turn_directive: str = "",
) -> str:
    """Stream the LLM reply and speak it sentence-by-sentence.

    The first sentence is queued the instant it is generated (the latency win);
    later sentences queue behind it in order through the single speech queue, so
    Rex never overlaps himself. Returns the full spoken text.

    ``two_chunk`` is the latency/consistency middle path (owner call 2026-07-06):
    the FIRST sentence synthesizes the moment it exists (~1.5-2.5s earlier than
    whole-reply), and everything after it is ONE second generation — a single v3
    voice seam per reply instead of one per sentence (the drift that got full
    streaming disabled) while chunk 2 synthesizes during chunk 1's playback.
    """
    trace = _current_character_loop_trace.get()
    priority = 1
    min_chars = int(getattr(config, "LLM_STREAMING_MIN_SENTENCE_CHARS", 12) or 1)
    prefetch_enabled = bool(getattr(config, "LLM_STREAMING_PREFETCH_ENABLED", True))

    # Person-based delivery shaping — independent of the reply text, so resolve
    # once and apply to every sentence (emotion / voice settings) or to the right
    # edge (pre-beat on the first line, post-beat after the last).
    delivery_emotion = "neutral"
    delivery_voice_settings: Optional[dict] = None
    empathy_pre_beat_ms = 0
    empathy_post_beat_ms = 0
    try:
        overrides = empathy.get_delivery_overrides(person_id)
    except Exception as exc:
        _log.debug("empathy.get_delivery_overrides error: %s", exc)
        overrides = None
    if overrides:
        if overrides.get("emotion"):
            delivery_emotion = overrides["emotion"]
        empathy_pre_beat_ms = int(overrides.get("pre_beat_ms") or 0)
        empathy_post_beat_ms = int(overrides.get("post_beat_ms") or 0)
        delivery_voice_settings = overrides.get("voice_settings")

    # Comedic delivery profile — layer the comedy stance's timbre (deadpan / smug)
    # UNDER empathy: only when empathy supplied no voice_settings of its own (a
    # neutral-empathy turn). Empathy/grief delivery always wins; "straight" care
    # turns carry no profile. Resolved once and applied to every sentence.
    if delivery_voice_settings is None:
        try:
            comedy_voice = comedy_modes.voice_settings_for_mode(comedy_mode)
        except Exception as exc:
            _log.debug("[comedy] delivery profile error: %s", exc)
            comedy_voice = None
        if comedy_voice:
            delivery_voice_settings = comedy_voice
            _log.info(
                "[comedy] delivery profile (stream): mode=%s voice=%s",
                getattr(comedy_mode, "key", "?"), comedy_voice,
            )

    spoken: list[str] = []
    done_events: list[threading.Event] = []
    state = {"first": True, "spoke_question": False, "emotion": delivery_emotion}
    llm_started = time.monotonic()

    # Classify Rex's OWN reply tone (excited/happy/curious) so the body expresses it.
    # Kicked off on the first sentence and run in the background, so it never delays the
    # first word; the result flows into the REST of the reply (voice/eyes/motion) and a
    # short post-reply body-mood afterglow. Surprise/empathy delivery emotions keep
    # priority — this only fills in when delivery is still "neutral".
    self_emo: dict = {"value": None, "started": False, "thread": None}

    def _start_self_emotion_classify(first_sentence: str) -> None:
        if self_emo["started"] or state["emotion"] != "neutral":
            return
        if not bool(getattr(config, "SELF_EMOTION_CLASSIFY_ENABLED", True)):
            return
        self_emo["started"] = True

        def _run() -> None:
            try:
                self_emo["value"] = llm.classify_self_emotion(first_sentence)
            except Exception as exc:
                _log.debug("[interaction] self-emotion classify error: %s", exc)

        thread = threading.Thread(target=_run, daemon=True, name="self-emotion-classify")
        self_emo["thread"] = thread
        thread.start()

    def _consume(raw_sentence: str) -> None:
        prepared = _prepare_stream_sentence(raw_sentence, frame, comedy_mode)
        if not prepared:
            return
        # One-question cap across the whole reply (govern keeps it per sentence).
        if social_frame.is_question_sentence(prepared):
            if state["spoke_question"]:
                return
            state["spoke_question"] = True

        # Read-along: show this sentence in the GUI transcript the MOMENT it is
        # generated (it grows one Rex bubble in place), so the text leads the TTS
        # instead of the whole reply landing after playback. The on-disk transcript
        # is still written once below.
        conv_log.log_rex_stream(prepared)

        # Once the self-emotion read is in, let the rest of the reply carry it.
        if (
            state["emotion"] == "neutral"
            and self_emo["value"]
            and self_emo["value"] != "neutral"
        ):
            state["emotion"] = self_emo["value"]

        pre_beat_ms = empathy_pre_beat_ms
        on_start = None
        # Request stitching: hand this sentence the reply's already-spoken text so v3 continues one
        # performance across the per-sentence API calls (empty for the first sentence). Captured as a
        # string now so the background prefetch thread and the live enqueue below key identically.
        stream_prev_text = " ".join(spoken).strip()
        if state["first"]:
            # Brief join so the surprise classifier can resolve BEFORE the first
            # sentence — the fast first token otherwise wins the race and the
            # "...didn't see that coming" pre-beat never fires on the streaming path
            # (the non-streaming path already joins with a 0.3s timeout). Bounded, so
            # it adds at most this to time-to-first-word, and only when not yet resolved.
            if surprise_thread is not None and not surprise_result.get("value"):
                try:
                    surprise_thread.join(
                        timeout=float(getattr(config, "SURPRISE_STREAM_JOIN_SECS", 0.25) or 0.0)
                    )
                except Exception:
                    pass
            if surprise_result.get("value"):
                state["emotion"] = "surprised"
                surprise_beat = _streaming_surprise_beat(surprise_result)
                if surprise_beat > 0:
                    pre_beat_ms = max(pre_beat_ms, surprise_beat)
                    try:
                        _play_event_body_beat("emotion.surprise")
                    except Exception as exc:
                        _log.debug("[interaction] surprise beat skipped: %s", exc)
            _start_self_emotion_classify(prepared)
            _mark_first_response_queued(trace, text=prepared, priority=priority)
            if trace is not None:
                on_start = lambda: _mark_first_response_audio_started(trace)
            filler_stop.set()
            if turn_start is not None:
                _latency_log(turn_start, "llm_first_sentence", llm_started)
        elif prefetch_enabled:
            _prefetch_stream_audio(
                prepared, state["emotion"], delivery_voice_settings,
                previous_text=stream_prev_text,
            )

        done = speech_queue.enqueue(
            prepared,
            state["emotion"],
            priority=priority,
            pre_beat_ms=pre_beat_ms,
            post_beat_ms=0,
            voice_settings=delivery_voice_settings,
            on_start=on_start,
            log_text=False,  # the whole turn is logged once below
            # One v3 audio tag per reply, on the FIRST sentence only (from the comedy stance +
            # emotion); later sentences suppress it so [sarcastic] doesn't repeat every sentence.
            comedy_mode=getattr(comedy_mode, "key", None),
            suppress_audio_tag=not state["first"],
            previous_text=stream_prev_text,   # stitch onto the reply's prior sentences
        )
        done_events.append(done)
        # `spoken` feeds the canonical full_text (transcript, memory, handoff) and the
        # stitching context — keep it free of inline v3 [audio tags]; the tagged text
        # lives only in the enqueued synthesis line above.
        spoken.append(strip_audio_tags(prepared))
        state["first"] = False

    def _consume_remainder(raw_sentences: list[str]) -> None:
        """Two-chunk mode: everything after the first sentence, spoken as ONE
        generation. Per-sentence governance (cruelty scrub / question cap) still
        applies inside the blob — only the SYNTHESIS is merged."""
        # Let the self-emotion read land so the body of the reply carries it (the
        # per-sentence path picks it up naturally on sentence two).
        th = self_emo.get("thread")
        if th is not None:
            try:
                th.join(timeout=0.4)
            except Exception:
                pass
        parts: list[str] = []
        for raw_sentence in raw_sentences:
            prepared = _prepare_stream_sentence(raw_sentence, frame, comedy_mode)
            if not prepared:
                continue
            if social_frame.is_question_sentence(prepared):
                if state["spoke_question"]:
                    continue
                state["spoke_question"] = True
            parts.append(prepared)
        if not parts:
            return
        blob = " ".join(parts)
        if (
            state["emotion"] == "neutral"
            and self_emo["value"]
            and self_emo["value"] != "neutral"
        ):
            state["emotion"] = self_emo["value"]
        conv_log.log_rex_stream(blob)
        stream_prev_text = " ".join(spoken).strip()
        if prefetch_enabled:
            # Kick synthesis NOW so chunk 2 renders while chunk 1 is playing.
            _prefetch_stream_audio(
                blob, state["emotion"], delivery_voice_settings,
                previous_text=stream_prev_text,
            )
        done = speech_queue.enqueue(
            blob,
            state["emotion"],
            priority=priority,
            pre_beat_ms=0,
            post_beat_ms=0,
            voice_settings=delivery_voice_settings,
            log_text=False,
            comedy_mode=getattr(comedy_mode, "key", None),
            suppress_audio_tag=True,          # the reply's one LEADING tag rode chunk 1
                                              # (inline mid-sentence tags still land)
            previous_text=stream_prev_text,   # harmless on v3 (dropped), stitches on v2
        )
        done_events.append(done)
        spoken.append(strip_audio_tags(blob))

    buffer = ""
    raw_chunks: list[str] = []
    rest_raw: list[str] = []   # two-chunk mode: complete sentences after the first
    try:
        for chunk in _reply_token_stream(
            user_text, person_id, agenda_directive, lean_turn_directive
        ):
            if _interrupted.is_set():
                break
            raw_chunks.append(chunk)
            buffer += chunk
            ready, buffer = _split_stream_sentences(buffer, min_chars)
            for sentence in ready:
                if two_chunk and not state["first"]:
                    rest_raw.append(sentence)
                else:
                    _consume(sentence)
    except Exception as exc:
        # Tool-router cutover: the model chose a LIVE tool instead of prose.
        # Nothing has been spoken (the stream raises only when no content was
        # yielded) — unwind to _stream_llm_response, which dispatches the
        # action's existing executor.
        from intelligence import tool_router as _tr
        if isinstance(exc, _tr.ToolCallRequested):
            filler_stop.set()
            raise
        _log.error("[interaction] streaming LLM error: %s", exc)
    finally:
        filler_stop.set()

    if not _interrupted.is_set():
        tail = buffer.strip()
        if tail and _tail_is_speakable(tail):
            if two_chunk and not state["first"]:
                rest_raw.append(tail)
            else:
                _consume(tail)
        elif tail:
            _log.info(
                "[interaction] dropped incomplete stream tail (mid-sentence cut): %r",
                tail,
            )
    if two_chunk and rest_raw and not _interrupted.is_set():
        _consume_remainder(rest_raw)

    # Safety net: if the model produced text but every sentence was governed away
    # (e.g. an all-questions reply under a no-questions frame), fall back to
    # whole-reply governance — which yields a frame fallback line — so Rex is
    # never left silent. Rare: general frames never drop sentences here.
    if not spoken and not _interrupted.is_set():
        # The model sometimes writes its tool call as TEXT ("[web_search]\n{...}")
        # instead of a native tool-call delta; nothing was spoken, so dispatch it
        # like the real thing rather than dying silent (the caller catches
        # ToolCallRequested and runs the action's executor).
        parsed_call = _parse_text_tool_call("".join(raw_chunks))
        if parsed_call is not None:
            from intelligence import tool_router as _tr
            _log.info(
                "[interaction] text-shaped tool call rescued from stream: %s args=%s",
                parsed_call[0], parsed_call[1],
            )
            raise _tr.ToolCallRequested(parsed_call[0], parsed_call[1])
        # Trim a trailing mid-sentence fragment first — otherwise a max_tokens
        # truncation ("Wow indeed! I") gets re-emitted as a cut-off line. A short
        # finished sentence the splitter's min-chars merge skipped ("Wow indeed!",
        # 11<12 chars) is recovered here; nothing complete → stay silent.
        raw_full = _complete_sentence_prefix("".join(raw_chunks))
        if raw_full:
            fallback = ""
            try:
                fallback = social_frame.govern_response(raw_full, frame).text
                fallback = comedy_modes.polish_response(
                    fallback, comedy_mode, allow_roast=frame.allow_roast
                )
                fallback = llm.clean_response_text(fallback or "")
            except Exception as exc:
                _log.debug("[interaction] stream fallback failed: %s", exc)
            if fallback:
                filler_stop.set()
                _speak_blocking(
                    fallback,
                    emotion=delivery_emotion,
                    voice_settings=delivery_voice_settings,
                )
                return fallback

    full_text = " ".join(part for part in spoken if part).strip()
    if full_text:
        # The GUI bubble was already filled sentence-by-sentence via log_rex_stream
        # (read-along), so write the on-disk transcript once here WITHOUT re-mirroring
        # to the GUI (to_gui=False, else the whole reply re-appears as a duplicate),
        # then finalize the streamed bubble to the canonical text.
        try:
            conv_log.log_rex(full_text, to_gui=False)
            conv_log.finish_rex_stream(full_text)
        except Exception as exc:
            _log.debug("[interaction] stream conversation log failed: %s", exc)
    if turn_start is not None:
        _latency_log(turn_start, "llm_response", llm_started)

    completed = _await_streamed_speech(done_events, priority)

    if full_text:
        if completed:
            post_beat_ms = empathy_post_beat_ms
            if not _assistant_asked_question(full_text):
                beat_min = getattr(config, "POST_PUNCHLINE_BEAT_MS_MIN", 0)
                beat_max = getattr(config, "POST_PUNCHLINE_BEAT_MS_MAX", 0)
                if beat_max > 0 and beat_max >= beat_min:
                    post_beat_ms = max(post_beat_ms, random.randint(beat_min, beat_max))
            if post_beat_ms > 0:
                time.sleep(post_beat_ms / 1000.0)
        _apply_post_tts_handoff(full_text, source="streaming")
        if (
            completed
            and getattr(frame, "purpose", None) == "identity"
            and "?" in full_text
        ):
            _arm_visible_unknown_identity_followup(
                person_id, source="agenda_llm_identity"
            )

    # Carry Rex's own reply mood into the post-reply lull (posture / breathing / idle
    # gesture). Only when the self-emotion classifier owned this turn — surprise and
    # empathy run their own delivery shaping and keep priority. The classifier was
    # kicked off on the first sentence; speech playback above almost always outlasts
    # it, but join briefly so a fast single-sentence reply still gets its mood.
    override_active = (delivery_emotion != "neutral") or bool(surprise_result.get("value"))
    if full_text and not override_active:
        thread = self_emo.get("thread")
        if thread is not None:
            thread.join(timeout=0.4)
        mood = self_emo.get("value")
        if mood and mood != "neutral":
            _set_body_mood(
                mood,
                source="self_emotion",
                intensity=float(getattr(config, "SELF_EMOTION_BODY_MOOD_INTENSITY", 0.6)),
            )

    return full_text


# ─────────────────────────────────────────────────────────────────────────────
# Command execution
# ─────────────────────────────────────────────────────────────────────────────

def _silent_command_response(label: str) -> str:
    return f"{_SILENT_COMMAND_PREFIX}{label}"


def _is_silent_command_response(text: Optional[str]) -> bool:
    return isinstance(text, str) and text.startswith(_SILENT_COMMAND_PREFIX)


def _plain_directed_text(text: str) -> str:
    return " ".join(re.sub(r"[^a-z0-9'\s]", " ", (text or "").lower()).split())


def _directed_context_fresh(now: Optional[float] = None) -> bool:
    now = time.monotonic() if now is None else now
    last_at = float(_directed_look_context.get("last_at") or 0.0)
    ttl = float(getattr(config, "DIRECTED_LOOK_CONTEXT_WINDOW_SECS", 25.0))
    return last_at > 0.0 and (now - last_at) <= ttl


def user_directed_look_active(now: Optional[float] = None) -> bool:
    """True while a look the USER commanded is still the open question.

    Public because consciousness needs it: an animal that walks into frame during
    a commanded look is the ANSWER to that command, not unsolicited chatter, and
    the two are scored very differently. Deliberately NOT
    `consciousness.directed_gaze_hold_active()` — that hold is also taken by
    exploration and motion_agency for gazes nobody asked for. This context is
    written only by the directed-look command handlers, and `found=True` clears
    it, so it goes false the moment Rex has actually answered.
    """
    return _directed_context_fresh(now)


def _reset_directed_look_context() -> None:
    _directed_look_context.update({
        "started_at": 0.0,
        "last_at": 0.0,
        "last_direction": None,
        "bare_count": 0,
        "asked_clarify": False,
        "target_hint": "",
        "target_kind": None,
        "greeted_key": None,
    })


def _note_directed_look_context(
    *,
    direction: str,
    target_hint: str = "",
    target_kind: Optional[str] = None,
    found: bool = False,
) -> None:
    now = time.monotonic()
    if found:
        _reset_directed_look_context()
        return
    if not _directed_context_fresh(now):
        _reset_directed_look_context()
        _directed_look_context["started_at"] = now
    elif not _directed_look_context.get("started_at"):
        _directed_look_context["started_at"] = now
    _directed_look_context["last_at"] = now
    _directed_look_context["last_direction"] = direction
    if target_hint:
        _directed_look_context["target_hint"] = target_hint
    if target_kind:
        _directed_look_context["target_kind"] = target_kind


def _directed_target_kind(target_hint: str) -> str:
    clean = _plain_directed_text(target_hint)
    if not clean:
        return "scene"
    if clean in {"this", "that", "here", "there", "this thing", "that thing"}:
        return "scene"
    if clean in {"me", "me silly", "me obviously", "my face", "myself"}:
        return "person"
    if re.match(r"^(?:the|a|an)\s+", clean):
        return "object"
    if re.match(
        r"^(?:my|your)\s+(?:wife|husband|spouse|partner|girlfriend|boyfriend|"
        r"mother|father|mom|dad|sister|brother|sibling|friend|kid|child|son|daughter)\b",
        clean,
    ):
        return "person"
    if clean in {"person", "face", "someone", "somebody", "human", "people"}:
        return "person"
    if re.match(r"^(?:my|your)\s+", clean):
        return "object"
    maybe_name = _normalize_name(target_hint)
    if maybe_name is not None:
        try:
            if people_memory.find_person_by_name(maybe_name):
                return "person"
        except Exception as exc:
            _log.debug("directed target person lookup failed: %s", exc)
    if maybe_name is not None and _name_word_count(maybe_name) == 1:
        return "person"
    return "object"


def _target_name_from_hint(target_hint: str, person_name: Optional[str]) -> Optional[str]:
    clean = _plain_directed_text(target_hint)
    if clean in {"me", "me silly", "me obviously", "my face", "myself"}:
        return person_name
    return _normalize_name(target_hint)


def _directional_search_sequence(
    start_direction: str,
    *,
    max_attempts: int,
) -> list[str]:
    start = (start_direction or "current").strip().lower()
    if start == "other_way":
        start = "current"
    compound = start if start in {"down_left", "down_right", "up_left", "up_right"} else None
    if compound is None and start not in {"current", "left", "right", "up", "down", "center"}:
        start = "current"

    if compound:
        # The user named a quadrant, so sweep that quadrant first and only then
        # widen to its two axes. Coercing a compound to "current" here threw the
        # quadrant away and restarted the generic room sweep -- the search would
        # have walked right past a dog the user had already localized for us.
        pitch, yaw = compound.split("_")
        base = [compound, yaw, pitch, "center"]
    elif start == "down":
        base = ["down", "left", "right", "center"]
    elif start == "up":
        base = ["up", "left", "right", "center"]
    elif start == "left":
        base = ["left", "right", "down", "up", "center"]
    elif start == "right":
        base = ["right", "left", "down", "up", "center"]
    elif start == "center":
        base = ["center", "left", "right", "down", "up"]
    else:
        base = ["left", "right", "down", "up", "center"]

    ordered: list[str] = []
    for direction in base:
        if direction not in ordered:
            ordered.append(direction)
    return ordered[:max(1, int(max_attempts))]


def _move_and_capture_gaze(
    direction: str,
    *,
    target_hint: str = "",
):
    from sequences import animations
    from vision import camera as camera_mod

    # Hold the photo until the head has stabilized AND the visor is fully open. The
    # visor rests near neutral (below the 6400 lens-clear floor) and the idle
    # breathing/mood loop keeps tugging it back there, so the old 0.06s settle snapped
    # a partly-covered lens mid-turn (logged 2026-06-21). Wait the full
    # DIRECTED_LOOK_CAPTURE_SETTLE_SECS — capture_current_gaze re-asserts the visor open
    # across that window — and suspend face-tracking long enough to cover the head move
    # + that settle + the grab so the tracker can't drag the head off the commanded
    # direction mid-photo (the old 0.72s window expired during a long neck swing).
    settle_secs = max(0.0, float(getattr(config, "DIRECTED_LOOK_CAPTURE_SETTLE_SECS", 1.5)))
    consciousness.suspend_face_tracking(settle_secs + 2.5)
    try:
        actual_direction = animations.directed_look_pose(direction, target=target_hint)
        frame = camera_mod.capture_current_gaze(settle_secs=settle_secs)
    finally:
        try:
            consciousness.resume_face_tracking()
        except Exception:
            pass
    return actual_direction, frame


def _visible_known_face_candidate(target_name: Optional[str] = None) -> Optional[dict]:
    try:
        people = world_state.get("people") or []
    except Exception:
        return None
    candidates: list[dict] = []
    for person in people:
        pid = person.get("person_db_id")
        if pid is None:
            continue
        if person.get("face_visible") is False or person.get("face_missing"):
            continue
        name = str(
            person.get("face_id")
            or person.get("voice_id")
            or person.get("name")
            or ""
        ).strip()
        if target_name and name and not _same_person_name(name, target_name):
            continue
        candidates.append({
            "person_id": pid,
            "name": name,
            "known": True,
        })
    if not candidates:
        return None
    return candidates[0]


def _detect_faces_in_gaze(frame) -> list[dict]:
    if frame is None:
        return []
    try:
        from vision import face as face_mod
        detections = face_mod.detect_faces(frame) or []
    except Exception as exc:
        _log.debug("directed face scan failed: %s", exc)
        return []

    results: list[dict] = []
    for det in detections:
        box = det.get("bounding_box")
        area = 0
        if isinstance(box, (list, tuple)) and len(box) >= 4:
            try:
                area = int(float(box[2]) * float(box[3]))
            except Exception:
                area = 0
        person_record = None
        try:
            from vision import face as face_mod
            person_record = face_mod.identify_face(det.get("encoding"))
        except Exception as exc:
            _log.debug("directed face identify failed: %s", exc)
        results.append({
            "box": box,
            "area": area,
            "person_id": (person_record or {}).get("id"),
            "name": (person_record or {}).get("name"),
            "known": person_record is not None,
        })
    results.sort(key=lambda item: item.get("area") or 0, reverse=True)
    return results


def _face_matches_target(face: dict, target_name: Optional[str]) -> bool:
    if not target_name:
        return True
    face_name = str(face.get("name") or "").strip()
    if not face_name:
        return True
    return _same_person_name(face_name, target_name)


def _directed_face_greeting(face: dict, fallback_name: Optional[str]) -> str:
    name = str(face.get("name") or fallback_name or "").strip()
    first = _first_name_or(name)
    if first:
        return f"Oh hi, {first}."
    return "Oh hi. There you are."


def _greet_directed_face_once(face: dict, fallback_name: Optional[str]) -> Optional[str]:
    key = face.get("person_id") or face.get("name") or fallback_name or "unknown_face"
    if key and _directed_look_context.get("greeted_key") == key:
        return _silent_command_response("directed_look.face_already_found")
    _directed_look_context["greeted_key"] = key
    response = _directed_face_greeting(face, fallback_name)
    _speak_blocking(response, emotion="happy", pre_beat_ms=60, post_beat_ms_override=150)
    _reset_directed_look_context()
    return response


def _scan_for_person(
    *,
    target_name: Optional[str],
    start_direction: str,
    person_name: Optional[str],
) -> str:
    max_attempts = int(getattr(config, "DIRECTED_LOOK_FACE_SEARCH_MAX_ATTEMPTS", 5))
    for direction in _directional_search_sequence(start_direction, max_attempts=max_attempts):
        actual_direction, frame = _move_and_capture_gaze(direction, target_hint=target_name or "person")
        for face in _detect_faces_in_gaze(frame):
            if _face_matches_target(face, target_name):
                _note_directed_look_context(
                    direction=actual_direction,
                    target_hint=target_name or "person",
                    target_kind="person",
                    found=True,
                )
                return _greet_directed_face_once(face, target_name or person_name) or ""
        _log.info(
            "[directed_look] person search miss direction=%s target=%r",
            actual_direction,
            target_name,
        )
    response = (
        f"I am looking for {target_name}, but no face lock yet. "
        "Try another direction before my dignity files a complaint."
        if target_name
        else "I am looking, but no face lock yet. Directional hints accepted, regrettably."
    )
    _speak_blocking(response, emotion="curious")
    return response


def _search_for_object(
    *,
    target_hint: str,
    start_direction: str,
    raw_text: str,
    person_id: Optional[int],
) -> str:
    from vision import scene as vision_scene

    max_attempts = int(getattr(config, "DIRECTED_LOOK_OBJECT_SEARCH_MAX_ATTEMPTS", 5))
    final_analysis: dict = {}
    final_direction = start_direction
    for direction in _directional_search_sequence(start_direction, max_attempts=max_attempts):
        actual_direction, frame = _move_and_capture_gaze(direction, target_hint=target_hint)
        final_direction = actual_direction
        if frame is None:
            continue
        analysis = vision_scene.analyze_directed_attention(
            frame,
            direction=actual_direction,
            utterance=raw_text,
            target_hint=target_hint,
        )
        final_analysis = analysis or final_analysis
        if _analysis_found_target(analysis, target_hint):
            prompt = (
                f"The person asked you to look for {target_hint!r}. "
                f"You found it while looking {_directed_look_label(actual_direction)}. "
                f"Vision analysis:\n{json.dumps(analysis, ensure_ascii=False)}\n\n"
                "Reply as Rex in one concise snarky observation based only on the visible details. "
                "Max 28 words. Do not mention JSON, APIs, cameras, screenshots, or image analysis."
            )
            response = llm.get_response(prompt, person_id) or _fallback_directed_look_response(analysis)
            _speak_blocking(response)
            _reset_directed_look_context()
            return llm.clean_response_text(response)
        _log.info(
            "[directed_look] object search miss target=%r direction=%s",
            target_hint,
            actual_direction,
        )

    if final_analysis:
        _log.info(
            "[directed_look] object search exhausted target=%r last_direction=%s analysis=%r",
            target_hint,
            final_direction,
            final_analysis.get("target_summary"),
        )
    response = _not_found_visual_response(target_hint)
    _speak_blocking(response)
    return response


def _analyze_directed_view_once(
    *,
    frame,
    direction: str,
    target_hint: str,
    raw_text: str,
    person_id: Optional[int],
    person_name: Optional[str],
) -> str:
    if frame is None:
        response = (
            "I looked, but my photoreceptors came back empty. "
            "Very dramatic. Terrible evidence."
        )
        _speak_blocking(response)
        return response
    from vision import scene as vision_scene

    analysis = vision_scene.analyze_directed_attention(
        frame,
        direction=direction,
        utterance=raw_text,
        target_hint=target_hint,
    )
    if not analysis:
        response = "I looked, but the visual intel is thin. Atmospheric, yes. Useful, no."
        _speak_blocking(response)
        return response

    speaker = person_name or "the person"
    prompt = (
        f"{speaker} asked you to physically look {_directed_look_label(direction)}. "
        f"The original request was: {raw_text!r}. "
        "You moved your head/visor, took a fresh look, and got this vision analysis:\n"
        f"{json.dumps(analysis, ensure_ascii=False)}\n\n"
        "Reply as Rex with one concise roast-style observation or opinion based ONLY "
        "on the analysis. Max 35 words. If the target is a person, child, pet, or "
        "possible introduction, acknowledge them warmly with a harmless quip and, "
        "only if useful, ask who they are. Do not mention JSON, APIs, cameras, "
        "screenshots, or image analysis."
    )
    response = llm.get_response(prompt, person_id) or _fallback_directed_look_response(analysis)
    _speak_blocking(response)
    # Rex has now said his piece about this view — so the animal-arrival remark that
    # analyze_directed_attention just caused (it publishes what it saw into
    # world_state["animals"], which is what stages arrivals) would be the same dog
    # announced twice. Marked only here: the two early returns above are "I couldn't
    # see anything", which describes nothing and so duplicates nothing.
    try:
        consciousness.note_directed_look_reported()
    except Exception as exc:
        _log.debug("directed-look report mark failed: %s", exc)
    return llm.clean_response_text(response)


def _clarify_directed_search() -> str:
    _directed_look_context["asked_clarify"] = True
    response = "What am I looking for?"
    _speak_blocking(response, emotion="curious")
    return response


def _pending_directed_search_reply(
    text: str,
    *,
    person_id: Optional[int],
    person_name: Optional[str],
) -> Optional[str]:
    if not _directed_context_fresh():
        return None
    if not _directed_look_context.get("asked_clarify"):
        return None

    clean = _plain_directed_text(text)
    if clean in {"me", "me silly", "me obviously", "me dummy", "me droid"}:
        try:
            recent = consciousness.get_recent_engagement() or {}
        except Exception:
            recent = {}
        target_name = person_name or recent.get("name")
        return _scan_for_person(
            target_name=target_name,
            start_direction=str(_directed_look_context.get("last_direction") or "current"),
            person_name=person_name,
        )

    look_match = command_parser.parse(text)
    if look_match is not None and look_match.command_key == "directed_look":
        args = look_match.args or {}
        target_hint = str(args.get("target_hint") or "").strip()
        if target_hint:
            kind = _directed_target_kind(target_hint)
            if kind == "person":
                return _scan_for_person(
                    target_name=_target_name_from_hint(target_hint, person_name),
                    start_direction=str(args.get("direction") or _directed_look_context.get("last_direction") or "current"),
                    person_name=person_name,
                )
            return _search_for_object(
                target_hint=target_hint,
                start_direction=str(args.get("direction") or _directed_look_context.get("last_direction") or "current"),
                raw_text=text,
                person_id=person_id,
            )
        return None

    kind = _directed_target_kind(text)
    if kind == "object":
        return _search_for_object(
            target_hint=text.strip(),
            start_direction=str(_directed_look_context.get("last_direction") or "current"),
            raw_text=text,
            person_id=person_id,
        )
    if kind == "person":
        maybe_name = _extract_introduced_name(text, allow_bare_name=True)
        return _scan_for_person(
            target_name=maybe_name,
            start_direction=str(_directed_look_context.get("last_direction") or "current"),
            person_name=person_name,
        )

    return None


def _directed_look_label(direction: str) -> str:
    return {
        "left": "to your left",
        "right": "to your right",
        "up": "upward",
        "down": "downward",
        "center": "straight ahead",
        "current": "at what they were showing you",
        # Compound gaze: say the diagonal out loud, or the prompt tells the model
        # Rex looked "at what they were showing you" when he actually tilted down
        # and turned left, and the reply stops matching what he did.
        "down_left": "down and to your left",
        "down_right": "down and to your right",
        "up_left": "up and to your left",
        "up_right": "up and to your right",
    }.get((direction or "current").lower(), "at what they were showing you")


def _fallback_directed_look_response(analysis: dict) -> str:
    summary = (analysis or {}).get("target_summary") or ""
    roast = (analysis or {}).get("roast_angle") or ""
    if summary and roast:
        return f"{summary} {roast}"
    if summary:
        return summary
    return "I looked, but my photoreceptors found mostly mystery and questionable staging."


def _analysis_found_target(analysis: dict, target_hint: str) -> bool:
    if not analysis:
        return False
    if not target_hint:
        return True
    if isinstance(analysis.get("target_visible"), bool):
        return bool(analysis.get("target_visible"))
    confidence = str(analysis.get("confidence") or "").lower()
    subject_type = str(analysis.get("subject_type") or "").lower()
    if confidence == "high" and subject_type not in {"", "unknown"}:
        return True
    haystack = " ".join([
        str(analysis.get("target_summary") or ""),
        str(analysis.get("roast_angle") or ""),
        " ".join(str(x) for x in analysis.get("notable_details") or []),
    ]).lower()
    target_words = [
        word for word in re.findall(r"[a-z0-9']+", target_hint.lower())
        if len(word) > 2 and word not in {"this", "that", "the", "my", "your"}
    ]
    return bool(target_words and any(word in haystack for word in target_words))


def _directed_search_directions(start_direction: str) -> list[str]:
    configured = list(getattr(
        config,
        "DIRECTED_LOOK_SEARCH_DIRECTIONS",
        ["current", "left", "right", "down", "up"],
    ))
    ordered: list[str] = []
    for direction in [start_direction, *configured]:
        direction = (direction or "current").strip().lower()
        if direction == "other_way":
            continue
        if direction not in {"current", "left", "right", "up", "down", "center"}:
            continue
        if direction not in ordered:
            ordered.append(direction)
    max_attempts = int(getattr(config, "DIRECTED_LOOK_MAX_SEARCH_ATTEMPTS", 4))
    return ordered[:max(1, max_attempts)]


def _not_found_visual_response(target_hint: str) -> str:
    target = (target_hint or "that").strip()
    target = re.sub(r"^(?:this|that|the|my|your)\s+", "", target, flags=re.IGNORECASE).strip()
    target = target or "that"
    return (
        f"I don't see the {target} you're talking about. "
        "Either it's hiding, or my vision sensors have entered their tragic poet era."
    )


# A directional gaze cue inside a vision-describe turn whose leading "look" was
# dropped by far-field ASR truncation ("to your right, what do you see"). Requires
# an explicit "look"/"turn" verb OR a "to the/your" prepositional phrase before the
# direction, so a bare direction fragment (the "down" of a clipped "shut down", or
# the "up" in "what's up") can never trigger a silent head-turn.
_COMPOUND_LOOK_DIRECTION_RE = re.compile(
    r"\b(?:"
    r"look\s+(?:to\s+)?(?:the\s+|your\s+)?"
    r"|turn\s+(?:your\s+head\s+)?(?:to\s+)?(?:the\s+|your\s+)?"
    r"|to\s+(?:the|your)\s+"
    r")(?P<direction>left|right|up|down)\b",
    re.IGNORECASE,
)


def _compound_look_direction(text: str) -> Optional[str]:
    """Direction from a vision-describe utterance whose leading 'look' was lost to ASR.

    "Look to your right and tell me what you see" parses cleanly as a directed_look
    and never reaches here. But far-field truncation routinely drops the leading
    "look", leaving "to your right, what do you see" — which routes to a plain scene
    description and makes Rex describe straight ahead without ever turning (logged
    2026-06-21). When a direction survives next to the vision query, return it so the
    caller can turn the head first. The caller gates this to vision-query turns.
    """
    m = _COMPOUND_LOOK_DIRECTION_RE.search(text or "")
    return m.group("direction").lower() if m else None


def _execute_directed_look_command(
    args: dict,
    person_id: Optional[int],
    person_name: Optional[str],
    raw_text: str,
) -> str:
    direction = (args.get("direction") or "current").strip().lower()
    target_hint = (args.get("target_hint") or "").strip()
    search_target = bool(args.get("search_target") and target_hint)
    target_kind = _directed_target_kind(target_hint) if target_hint else None
    bare_directional = not target_hint and not search_target
    search_start_direction = direction
    if (
        direction == "current"
        and target_hint
        and _directed_context_fresh()
        and _directed_look_context.get("last_direction")
    ):
        search_start_direction = str(_directed_look_context.get("last_direction"))

    try:
        if target_hint and (search_target or target_kind in {"person", "object"}):
            if target_kind == "person":
                return _scan_for_person(
                    target_name=_target_name_from_hint(target_hint, person_name),
                    start_direction=search_start_direction,
                    person_name=person_name,
                )
            return _search_for_object(
                target_hint=target_hint,
                start_direction=search_start_direction,
                raw_text=raw_text,
                person_id=person_id,
            )

        actual_direction, frame = _move_and_capture_gaze(direction, target_hint=target_hint)

        # Compound command: "look to your right and tell me what you see". The
        # directional half parses with no target_hint (bare directional), but
        # the utterance also carries an explicit vision question — answer it
        # with a fresh directed view analysis instead of treating the turn as
        # a silent gaze change. Without this, the face-greet branch below
        # could swallow the question entirely (live failure: Rex turned right
        # and just said "Oh hi, Bret").
        if bare_directional and action_router.has_vision_query_evidence(raw_text):
            return _analyze_directed_view_once(
                frame=frame,
                direction=actual_direction,
                target_hint=target_hint,
                raw_text=raw_text,
                person_id=person_id,
                person_name=person_name,
            )

        if target_hint and target_kind == "scene":
            return _analyze_directed_view_once(
                frame=frame,
                direction=actual_direction,
                target_hint=target_hint,
                raw_text=raw_text,
                person_id=person_id,
                person_name=person_name,
            )

        _note_directed_look_context(
            direction=actual_direction,
            target_hint=target_hint,
            target_kind=target_kind,
        )

        if bare_directional:
            # Commit to the gaze he was told to take instead of immediately
            # scanning the room / drifting his head back up to level.
            try:
                consciousness.hold_directed_gaze(actual_direction)
            except Exception as exc:
                _log.debug("directed gaze hold failed: %s", exc)
            _directed_look_context["bare_count"] = int(
                _directed_look_context.get("bare_count") or 0
            ) + 1

            # A bare directional look is an INSPECTION order, not a servo
            # command: the person aimed Rex's head somewhere because something is
            # THERE. _move_and_capture_gaze already took the photo above, and the
            # old code threw it away — so "Look down and to your left", said five
            # different ways at a dog on the floor, produced a silent turn, then
            # "What am I looking for?", then "Oh hi, Bret." while pointed at the
            # dog (field 2026-08-13 21:01:45-21:02:53). Silence WAS the failure.
            # Report the new view: one VISION_MODEL look at a frame whose servo
            # time is already spent. The local COCO detectors deliberately do NOT
            # gate this — that same night the dog scored 0.215/0.246/0.300
            # against the 0.30 accept bar and never confirmed, while a phantom
            # "cat" did, so a local gate would have shipped silence for the exact
            # incident it was meant to fix.
            if frame is not None and bool(
                getattr(config, "DIRECTED_LOOK_REPORT_VIEW", True)
            ):
                _log.info(
                    "[directed_look] reporting view direction=%s bare_count=%d",
                    actual_direction,
                    _directed_look_context["bare_count"],
                )
                return _analyze_directed_view_once(
                    frame=frame,
                    direction=actual_direction,
                    target_hint=target_hint,
                    raw_text=raw_text,
                    person_id=person_id,
                    person_name=person_name,
                )

            # No frame (camera off / capture failed) or reporting disabled. ONLY
            # here does the face-greet earn a turn, and it is last on purpose: its
            # candidate comes from world_state rather than the frame just taken,
            # and _visible_known_face_candidate filters to person_name — the
            # speaker who gave the order — so the only line it can ever produce is
            # "Oh hi, <whoever is talking to me>", which is what hijacked the dog
            # inspection above. A genuinely new person in the new view is served
            # better by the report path, which names people it recognizes.
            visible_face = _visible_known_face_candidate(person_name)
            if visible_face:
                return (
                    _greet_directed_face_once(visible_face, person_name)
                    or _silent_command_response("directed_look.face_found")
                )

            clarify_after = int(getattr(config, "DIRECTED_LOOK_CLARIFY_AFTER_COMMANDS", 3))
            if (
                _directed_look_context["bare_count"] >= max(1, clarify_after)
                and not _directed_look_context.get("asked_clarify")
            ):
                return _clarify_directed_search()
            return _silent_command_response(f"directed_look.{actual_direction}")
    except Exception as exc:
        _log.debug("directed look command failed: %s", exc)
        resp = "I tried to look, but my neck servos and photoreceptors are staging a tiny rebellion."
        _speak_blocking(resp)
        return resp

    resp = "Moved. Give me a target if this is supposed to become detective work."
    _speak_blocking(resp)
    return resp


def _execute_wave_command(
    args: dict,
    person_id: Optional[int],
    person_name: Optional[str],
) -> str:
    target = (args.get("target") or "").strip()
    if not target or target.lower() == "them":
        target = person_name or "them"

    try:
        from sequences import animations
        threading.Thread(
            target=animations.arm_wave,
            daemon=True,
            name="command_wave",
        ).start()
    except Exception as exc:
        _log.debug("wave command motion failed: %s", exc)

    prompt = (
        f"You are physically waving your right arm to {target}. "
        "Give one short Rex-style line, max 16 words. "
        "Do not mention servos unless joking very lightly."
    )
    resp = llm.get_response(prompt, person_id) or f"Fine, {target}, consider yourself waved at."
    _speak_blocking(resp, emotion="happy")
    return llm.clean_response_text(resp)


_MEMORY_SELF_REFS = {"i", "me", "my", "myself"}
_MEMORY_NAME_RE = re.compile(r"^[A-Z][A-Za-z'-]*(?:\s+[A-Z][A-Za-z'-]*){0,3}$")
_MEMORY_PERSON_NAME_CHUNK = r"[A-Z][A-Za-z'-]*(?:\s+[A-Z][A-Za-z'-]*){0,3}"
_MEMORY_RELATION_WORDS = (
    r"best\s+friend|partner|spouse|wife|husband|girlfriend|boyfriend|"
    r"fianc[eé]e?|father|dad|mother|mom|parent|son|daughter|child|"
    r"brother|sister|sibling|friend|boss|manager|supervisor|employee|"
    r"coworker|co[-\s]?worker|colleague|roommate|neighbor|neighbour"
)
_DIRECT_RELATIONSHIP_PATTERNS = (
    re.compile(
        rf"\bmy\s+(?P<rel>{_MEMORY_RELATION_WORDS})\s+"
        rf"(?:is\s+)?(?:named|called)\s+(?P<name>{_MEMORY_PERSON_NAME_CHUNK})\b",
        re.IGNORECASE,
    ),
    re.compile(
        rf"\bmy\s+(?P<rel>{_MEMORY_RELATION_WORDS})'?s\s+name\s+is\s+"
        rf"(?P<name>{_MEMORY_PERSON_NAME_CHUNK})\b",
        re.IGNORECASE,
    ),
    re.compile(
        rf"^\s*(?P<name>{_MEMORY_PERSON_NAME_CHUNK})\s+is\s+my\s+"
        rf"(?P<rel>{_MEMORY_RELATION_WORDS})\b",
        re.IGNORECASE,
    ),
)
_NAMED_PERSON_FACT_STATEMENT_RE = re.compile(
    rf"^\s*(?P<name>{_MEMORY_PERSON_NAME_CHUNK})\s+"
    r"(?P<verb>is|has|works(?:\s+as|\s+in|\s+for)?)\s+"
    r"(?P<detail>[^.?!]{2,160})",
)
_JOB_DETAIL_RE = re.compile(
    r"\b("
    r"administrator|admin|analyst|architect|assistant|developer|director|"
    r"doctor|editor|engineer|manager|nurse|programmer|teacher|technician|"
    r"writer|works?\s+(?:as|in|for)"
    r")\b",
    re.IGNORECASE,
)


def _memory_key(value: str) -> str:
    cleaned = re.sub(r"[^a-z0-9]+", "_", (value or "").strip().lower())
    return re.sub(r"_+", "_", cleaned).strip("_") or "detail"


# A stored fact key is an ATTRIBUTE of a person ("job", "birthday", "his name",
# "favorite band") — never a topical noun phrase. "the most annoying part" is a
# subject in the conversation, not something Rex can hold about Bret.
_FACT_ATTRIBUTE_STOP_LEADERS = re.compile(
    r"^(?:the|a|an|this|that|these|those|it|there|what|which|who|"
    r"one|some|any|all|both|either|neither|another|each|every)\b",
    re.IGNORECASE,
)


def _looks_like_fact_attribute(key_phrase: str, value: str = "") -> bool:
    """Guard the generic "<X> is <Y>" correction write.

    The regex behind it matches ANY clause with an "is" in it, so a correction
    that slipped past the parser used to be filed verbatim: field 2026-08-13
    11:30, "Actually, the most annoying part is figuring out where to mount them
    on your body." → key=`the_most_annoying_part`, and Rex announced "I now have
    Bret Benziger as the most annoying part: ...". A determiner-led or
    clause-length phrase is the conversation's subject, not a person attribute —
    fall through to the elaboration reply below instead of writing a fact.
    """
    phrase = " ".join(str(key_phrase or "").split())
    if not phrase:
        return False
    if _FACT_ATTRIBUTE_STOP_LEADERS.match(phrase):
        return False
    if len(phrase.split()) > 3:
        return False
    # A clause-shaped value ("figuring out where to mount them on your body") is
    # story detail, not a fact value, even under a plausible-looking key.
    if len(str(value or "").split()) > 10:
        return False
    return True


def _clean_memory_person_name(value: str) -> str:
    name = " ".join(str(value or "").strip(" .?!,;:").split())
    name = re.split(
        r"\b(?:and|but|who|that|which|please|thanks|thank\s+you)\b",
        name,
        maxsplit=1,
        flags=re.IGNORECASE,
    )[0].strip(" .?!,;:")
    return name if _MEMORY_NAME_RE.match(name) else ""


def _learn_direct_memory_from_user_text(
    text: str,
    person_id: Optional[int],
) -> None:
    """Store obvious relationship/person facts immediately, without an LLM pass."""
    if person_id is None:
        return
    _learn_direct_relationship_statement(text, int(person_id))
    _learn_named_person_fact_statement(text, int(person_id))


def _learn_direct_relationship_statement(text: str, person_id: int) -> None:
    for pattern in _DIRECT_RELATIONSHIP_PATTERNS:
        match = pattern.search(text or "")
        if not match:
            continue
        rel = _normalize_relationship_word(match.group("rel")) or ""
        name = _clean_memory_person_name(match.group("name"))
        if not rel or not name:
            return
        other_id, _created = people_memory.find_or_create_person(name)
        if other_id is None or int(other_id) == int(person_id):
            return
        social_memory.save_relationship(
            from_person_id=int(person_id),
            to_person_id=int(other_id),
            relationship=rel,
            described_by=int(person_id),
        )
        facts_memory.add_fact(
            int(person_id),
            "family",
            f"{rel}_name",
            name,
            source="explicit",
            confidence=0.98,
            importance=0.9,
            decay_rate="permanent",
        )
        _record_recent_memory_candidate(
            person_id,
            kind="relationship",
            target=f"{rel} {name}",
            label=f"{rel.replace('_', ' ')} {name}",
        )
        _log.info(
            "[memory] learned direct relationship person_id=%s rel=%s name=%r other_id=%s",
            person_id,
            rel,
            name,
            other_id,
        )
        return


def _learn_named_person_fact_statement(text: str, person_id: int) -> None:
    match = _NAMED_PERSON_FACT_STATEMENT_RE.match(text or "")
    if not match:
        return
    name = _clean_memory_person_name(match.group("name"))
    if not name:
        return
    row = people_memory.find_person_by_name(name)
    if not row:
        return
    target_id = int(row["id"])
    if target_id == int(person_id):
        return
    verb = " ".join(str(match.group("verb") or "").lower().split())
    detail = " ".join(str(match.group("detail") or "").strip(" .?!").split())
    if not detail or detail.lower().startswith(("my ", "your ")):
        return
    value = re.sub(r"^(?:a|an|the)\s+", "", detail, flags=re.IGNORECASE).strip()
    category = "job" if verb.startswith("work") or _JOB_DETAIL_RE.search(detail) else "other"
    key = "job_title" if category == "job" else _memory_key(verb)
    facts_memory.add_fact(
        target_id,
        category,
        key,
        value,
        source="explicit",
        confidence=0.95,
        importance=0.8 if category == "job" else 0.55,
    )
    _record_recent_memory_candidate(
        target_id,
        kind="fact",
        target=f"{category} {key} {value}",
        label=f"{name}: {value}",
    )
    _log.info(
        "[memory] learned named-person fact target_id=%s name=%r key=%s value=%r",
        target_id,
        name,
        key,
        value,
    )


def _record_recent_memory_candidate(
    person_id: Optional[int],
    *,
    kind: str,
    target: str,
    label: str,
) -> None:
    if person_id is None or not target:
        return
    _recent_memory_candidates.append({
        "person_id": int(person_id),
        "kind": kind,
        "target": target,
        "label": label or target,
        "ts": time.time(),
    })


def _register_forget_terms(person_id: Optional[int], result: forgetting.ForgetResult) -> None:
    if person_id is None:
        return
    if result.terms:
        _session_forget_terms.setdefault(int(person_id), set()).update(result.terms)


def _extract_memory_statement_target(
    statement: str,
    person_id: Optional[int],
    person_name: Optional[str],
) -> tuple[Optional[int], Optional[str], str, bool]:
    """
    Resolve a spoken memory statement to a person.

    Returns (target_id, target_name, detail, explicitly_named). Self references
    resolve to the engaged person; another person's memory requires a clear name.
    """
    text = (statement or "").strip()
    if not text:
        return None, None, "", False

    if re.match(r"(?i)^(?:i|i'm|im|my|me)\b", text):
        return person_id, person_name, text, False

    possessive = re.match(
        r"^([A-Z][A-Za-z]*(?:\s+[A-Z][A-Za-z]*){0,2})'s\s+(.+)$",
        text,
    )
    if possessive:
        name = possessive.group(1).strip()
        detail = possessive.group(2).strip()
        row = people_memory.find_person_by_name(name)
        return (
            int(row["id"]) if row else None,
            (row.get("name") if row else name),
            detail,
            True,
        )

    subject = re.match(
        r"^([A-Z][A-Za-z]*(?:\s+[A-Z][A-Za-z]*){0,2})\s+"
        r"(likes|loves|hates|dislikes|prefers|avoids|is|has|works|wants|plays|collects)\b\s*(.*)$",
        text,
    )
    if subject:
        name = subject.group(1).strip()
        verb = subject.group(2).strip()
        rest = subject.group(3).strip()
        row = people_memory.find_person_by_name(name)
        return (
            int(row["id"]) if row else None,
            (row.get("name") if row else name),
            f"{verb} {rest}".strip(),
            True,
        )

    return person_id, person_name, text, False


def _resolve_review_target(
    args: dict,
    person_id: Optional[int],
    person_name: Optional[str],
) -> tuple[Optional[int], Optional[str], Optional[str]]:
    target = (args.get("target") or "").strip()
    if args.get("self_ref") or target.lower() in _MEMORY_SELF_REFS:
        if person_id is None:
            return None, None, "I need to know who you are before I can review your memory."
        return person_id, person_name, None

    row = people_memory.find_person_by_name(target)
    if not row:
        return None, None, f"I don't have a clear memory record for {target}."
    return int(row["id"]), row.get("name"), None


def _execute_memory_review_command(
    args: dict,
    person_id: Optional[int],
    person_name: Optional[str],
) -> str:
    target_id, _target_name, error = _resolve_review_target(args, person_id, person_name)
    if error:
        _speak_blocking(error)
        return error
    resp = person_summary.summarize_for_review(
        int(target_id),
        include_sensitive=bool(args.get("include_sensitive")),
    )
    _speak_blocking(resp, emotion="neutral")
    return resp


def _execute_memory_forget_fact_command(
    args: dict,
    person_id: Optional[int],
    person_name: Optional[str],
) -> str:
    statement = (args.get("statement") or "").strip()
    target_id, target_name, detail, named = _extract_memory_statement_target(
        statement,
        person_id,
        person_name,
    )
    if target_id is None:
        who = target_name or "that person"
        resp = f"I need a clearer person match before I delete {who}'s memory."
        _speak_blocking(resp)
        return resp
    if named is False and person_id is None:
        resp = "I need to know whose memory this belongs to before I delete it."
        _speak_blocking(resp)
        return resp

    target = " ".join(part for part in [detail, statement] if part).strip()
    result = forgetting.forget_memory_detail(int(target_id), target)
    _register_forget_terms(target_id, result)
    _log.info(
        "[memory] local forget person_id=%s named=%s statement=%r deleted=%s",
        target_id,
        named,
        statement,
        result.deleted,
    )
    if result.total_deleted <= 0:
        resp = f"I couldn't find a stored fact or preference matching {detail or statement}."
    else:
        resp = f"Deleted that memory for {target_name or 'them'}. Clean, deliberate, logged."
    _speak_blocking(resp, emotion="neutral")
    return resp


def _execute_memory_boundary_command(
    person_id: Optional[int],
    utterance: str = "",
) -> str:
    # "I don't remember saying that" right after Rex referenced a diary open
    # thread is CONFUSION, not a delete request — answer it by quoting the
    # source (what the diary says and when), so the human can either go "oh,
    # right" or recognize a mis-hearing. Field 2026-08-01 12:31: "you mentioned
    # the wheels in the parking lot" → "I don't remember saying what that was"
    # → the old stock line ("Nothing recent to discard") explained nothing.
    # Confusion-shaped only ("don't remember", "what are you talking about") —
    # an explicit "forget that" must still reach the real discard flow below.
    confused = bool(re.search(
        r"don'?t (?:remember|recall|know)|never said|what (?:are you|was that|do you mean)"
        r"|no idea what",
        str(utterance or ""), re.IGNORECASE,
    ))
    global _last_thread_reference
    ref = _last_thread_reference
    if confused and ref and (time.monotonic() - float(ref.get("at") or 0.0)) < 240.0:
        _last_thread_reference = None       # one grounding per reference
        summary = ""
        try:
            from memory import rex_db
            row = rex_db.fetchone(
                "SELECT summary FROM rex_episodes WHERE id = ?",
                (int(ref.get("episode_id") or 0),),
            )
            if row is not None:
                summary = str(row["summary"] or "").strip()
        except Exception as exc:
            _log.debug("[memory] thread-reference lookup failed: %s", exc)
        if len(summary) > 220:
            summary = summary[:217].rstrip() + "..."
        if summary:
            resp = (
                f"Here's what I had: {ref.get('when')}, my notes from our chat say — "
                f"\"{summary}\" — and the loose end I was poking at was "
                f"\"{ref.get('thread')}\". If that's not a real thing, I probably "
                "misheard you, and I won't bring it up again."
            )
        else:
            resp = (
                f"It was a note I made {ref.get('when')}: \"{ref.get('thread')}\". "
                "If that doesn't ring a bell, I probably misheard you — dropping it."
            )
        _speak_blocking(resp, emotion="neutral")
        return resp

    candidate = None
    for item in reversed(_recent_memory_candidates):
        if person_id is None or int(item.get("person_id")) == int(person_id):
            candidate = item
            break
    if not candidate:
        resp = "Nothing recent to discard. My memory banks are innocent this time."
        _speak_blocking(resp)
        return resp

    target_id = int(candidate["person_id"])
    result = forgetting.forget_memory_detail(target_id, candidate.get("target") or "")
    _register_forget_terms(target_id, result)
    try:
        _recent_memory_candidates.remove(candidate)
    except ValueError:
        pass
    _log.info(
        "[memory] discarded recent candidate person_id=%s kind=%s target=%r deleted=%s",
        target_id,
        candidate.get("kind"),
        candidate.get("target"),
        result.deleted,
    )
    resp = f"Understood. I discarded the recent memory about {candidate.get('label') or 'that'}."
    _speak_blocking(resp, emotion="neutral")
    return resp


def _execute_memory_correct_fact_command(
    args: dict,
    person_id: Optional[int],
    person_name: Optional[str],
) -> str:
    correction = (args.get("correction") or "").strip()
    call_me = re.match(r"(?i)^(?:please\s+)?call\s+me\s+(.+)$", correction)
    if call_me:
        new_name = call_me.group(1).strip(" .!?")
        if person_id is None:
            resp = "I need to know who I'm renaming first."
            _speak_blocking(resp)
            return resp
        if not people_memory.rename_person(int(person_id), new_name):
            resp = f"I couldn't safely rename that memory to {new_name}."
            _speak_blocking(resp)
            return resp
        facts_memory.apply_fact_correction(
            int(person_id),
            "name",
            new_name,
            category="identity",
            importance=0.95,
            decay_rate="permanent",
        )
        _refresh_world_state_person_name(int(person_id), new_name)
        _log.info("[memory] corrected name person_id=%s new=%r", person_id, new_name)
        resp = repair_moves.add_better_luck_line(
            f"Corrected. Bret-level bureaucracy complete: I will call you {new_name}."
        )
        _speak_blocking(resp, emotion="happy")
        return resp

    target_id, target_name, detail, named = _extract_memory_statement_target(
        correction,
        person_id,
        person_name,
    )
    last_name = re.match(r"(?i)^last\s+name\s+is\s+([A-Za-z][A-Za-z' -]+)$", detail)
    if last_name and target_id is not None:
        surname = last_name.group(1).strip()
        first = _first_name_or(target_name or correction)
        full_name = f"{first} {surname}".strip()
        if people_memory.rename_person(int(target_id), full_name):
            facts_memory.apply_fact_correction(
                int(target_id),
                "last_name",
                surname,
                category="identity",
                importance=0.95,
                decay_rate="permanent",
            )
            _refresh_world_state_person_name(int(target_id), full_name)
            _log.info("[memory] corrected last name person_id=%s new=%r", target_id, full_name)
            resp = repair_moves.add_better_luck_line(
                f"Corrected. {first}'s last name is {surname}. "
                "Logged with actual confidence for once."
            )
        else:
            resp = f"I couldn't safely update that name to {full_name}."
        _speak_blocking(resp, emotion="neutral")
        return resp

    generic = re.match(r"(?i)^(.+?)\s+is\s+(.+)$", detail)
    if target_id is not None and generic and _looks_like_fact_attribute(
        generic.group(1), generic.group(2)
    ):
        key = _memory_key(generic.group(1))
        value = generic.group(2).strip(" .!?")
        facts_memory.apply_fact_correction(
            int(target_id),
            key,
            value,
            category="other",
            importance=0.75,
        )
        _log.info(
            "[memory] corrected fact person_id=%s key=%r value=%r named=%s",
            target_id,
            key,
            value,
            named,
        )
        resp = repair_moves.add_better_luck_line(
            f"Corrected. I now have {target_name or 'them'} as {generic.group(1)}: {value}."
        )
        _speak_blocking(resp, emotion="neutral")
        return resp

    # No extractable stored-fact target: this is almost never a real memory
    # correction — it's the person ELABORATING their own story ("Actually, they
    # changed the deadline on him because they asked him to get it done by July
    # 29th, and he got it on the 28th", field 2026-08-03 17:58 — which got the
    # canned "I need one clear fact to update" and a dead turn, and the owner's
    # "That was not a correction" pushback). Respond to the CONTENT instead.
    utter = correction or str(args.get("statement") or "")
    reply = ""
    try:
        reply = llm.get_response(
            f"The person just added detail to the story they're telling you: "
            f"{utter!r}. This is NOT a memory correction and NOT about your "
            f"records — react to the content itself in one or two Rex-style "
            f"lines (sympathy, outrage, or dry wit as it fits). Never mention "
            f"updating, correcting, or facts.",
            person_id,
        ) or ""
    except Exception as exc:
        _log.debug("[memory] correction-fallthrough reply failed: %s", exc)
    resp = reply.strip() or "Got it — that's a rougher story than I had it."
    _speak_blocking(resp)
    return resp


def _store_simple_memory_statement(
    target_id: int,
    detail: str,
    *,
    source: str = "explicit",
) -> str:
    text = (detail or "").strip(" .!?")
    called = re.match(r"(?i)^hates\s+being\s+called\s+(.+)$", text)
    if called:
        nickname = called.group(1).strip(" .!?")
        preferences_memory.upsert_preference(
            int(target_id),
            "interaction",
            "boundary",
            f"not_called_{_memory_key(nickname)}",
            f"Do not call them {nickname}.",
            confidence=1.0,
            importance=0.98,
            source=source,
        )
        return f"not being called {nickname}"

    like = re.match(r"(?i)^(likes|loves|hates|dislikes|prefers|avoids)\s+(.+)$", text)
    if like:
        verb = like.group(1).lower()
        thing = like.group(2).strip()
        pref_type = {
            "likes": "likes",
            "loves": "likes",
            "hates": "dislikes",
            "dislikes": "dislikes",
            "prefers": "prefers",
            "avoids": "avoids",
        }[verb]
        domain = "music" if "music" in thing.lower() or thing.lower() in {"country", "country music"} else "general"
        preferences_memory.upsert_preference(
            int(target_id),
            domain,
            pref_type,
            _memory_key(thing),
            thing,
            confidence=0.95,
            importance=0.85 if pref_type in {"dislikes", "avoids"} else 0.7,
            source=source,
        )
        return thing

    generic = re.match(r"(?i)^(.+?)\s+is\s+(.+)$", text)
    if generic:
        key = _memory_key(generic.group(1))
        value = generic.group(2).strip()
        facts_memory.add_fact(
            int(target_id),
            "other",
            key,
            value,
            source=source,
            confidence=0.95,
        )
        return f"{generic.group(1)} is {value}"

    facts_memory.add_fact(
        int(target_id),
        "other",
        _memory_key(text[:40]),
        text,
        source=source,
        confidence=0.95,
        importance=0.35,
        decay_rate="fast",
    )
    return text


def _execute_memory_remember_fact_command(
    args: dict,
    person_id: Optional[int],
    person_name: Optional[str],
) -> str:
    statement = (args.get("statement") or "").strip()
    target_id, target_name, detail, named = _extract_memory_statement_target(
        statement,
        person_id,
        person_name,
    )
    if target_id is None and named and target_name and _MEMORY_NAME_RE.match(target_name):
        target_id, _created = people_memory.find_or_create_person(target_name)
    if target_id is None:
        resp = "I need a clearer person before I store that memory."
        _speak_blocking(resp)
        return resp
    stored_label = _store_simple_memory_statement(int(target_id), detail)
    _log.info(
        "[memory] remembered explicit statement person_id=%s named=%s statement=%r",
        target_id,
        named,
        statement,
    )
    resp = f"Remembered: {target_name or 'they'} - {stored_label}. Trustworthy memory, minimal theatrics."
    _speak_blocking(resp, emotion="happy")
    return resp


def _select_shutdown_tts_line() -> str:
    """Pick a short 'shutting down' sign-off, cycling without back-to-back repeats.
    Returns "" if no canned shutdown lines are configured (caller falls back to LLM)."""
    state_path = (
        str(getattr(config, "SHUTDOWN_TTS_STATE_PATH", "") or "")
        or str(Path(__file__).resolve().parent.parent / "assets" / "state" / "shutdown_tts.json")
    )
    return phrase_cycler.select_cycling_line(
        getattr(config, "SHUTDOWN_TTS_LINES", None), state_path
    )


def _execute_command(
    match: command_parser.CommandMatch,
    person_id: Optional[int],
    person_name: Optional[str],
    raw_text: str,
) -> str:
    """
    Dispatch a locally matched command, speak the response, and return the
    response text for transcript logging.
    """
    key = match.command_key
    args = match.args
    updater = person_name or "unknown"

    def _say(prompt: str, emotion: str = "neutral") -> str:
        resp = llm.get_response(prompt, person_id)
        _speak_blocking(resp, emotion)
        return resp

    def _target_for_user(target: str) -> str:
        cleaned = (target or "").strip()
        if re.match(r"(?i)^my\b", cleaned):
            return re.sub(r"(?i)^my\b", "your", cleaned, count=1)
        return cleaned

    # ── Physical attention / movement ─────────────────────────────────────────
    if key == "directed_look":
        return _execute_directed_look_command(args, person_id, person_name, raw_text)

    if key == "wave_to":
        return _execute_wave_command(args, person_id, person_name)

    if key == "query_play_options":
        resp = "I can play music or games, which would you like?"
        _speak_blocking(resp)
        return resp

    # ── Time & date ────────────────────────────────────────────────────────────
    if key == "time_query":
        resp = _format_current_time_response()
        _speak_blocking(resp)
        return resp

    if key == "date_query":
        resp = _format_current_date_response()
        _speak_blocking(resp)
        return resp

    # ── State transitions ──────────────────────────────────────────────────────
    if key == "sleep":
        return _enter_sleep_mode()

    if key == "wake_up":
        if state_module.get_state() == State.SLEEP:
            return _wake_from_sleep()
        if state_module.get_state() == State.QUIET:
            state_module.set_state(State.ACTIVE)
            return _say(
                "You just exited quiet mode after being told to resume. "
                "One short in-character line."
            )
        state_module.set_state(State.ACTIVE)
        return _say("You just woke up. One short in-character wake-up line.")

    if key == "quiet_mode":
        # "brb" flavor: they asked for a pause mid-conversation ("one sec, be
        # right back") rather than a formal quiet-mode command — ack like a
        # friend, not a system ("Take your time — say the magic words when
        # you're back").
        if (args or {}).get("flavor") == "brb":
            prompt = (
                "They asked you to pause for a moment — stepping away, taking a "
                "call, be right back. Acknowledge in ONE short easygoing line "
                "that you'll wait quietly until they say a wake phrase like "
                "'hey Rex'. No questions."
            )
        else:
            prompt = (
                "You are entering quiet mode and won't speak until told to resume. "
                "One brief in-character acknowledgment."
            )
        resp = llm.get_response(
            prompt,
            person_id,
        )
        _speak_blocking(resp)
        state_module.set_state(State.QUIET)
        return resp

    if key == "shutdown":
        # Use a short canned sign-off (cycled, never consecutively) instead of a
        # full LLM generation, which made shutdown feel sluggish. Falls back to the
        # LLM line only if no canned shutdown lines are configured.
        resp = _select_shutdown_tts_line()
        if not resp:
            resp = llm.get_response(
                "You are powering all the way down now (not just napping). Your "
                "always-listening helper stays awake and will boot you back up when "
                "someone says 'wake up Rex'. Give one final, in-character sign-off "
                "line — a little dramatic, like a pilot powering down the cockpit.",
                person_id,
            )
        _speak_blocking(resp)
        state_module.set_state(State.SHUTDOWN)
        # Drop any proactive/idle line (priority 0–1) that won the race against the
        # state flip and is waiting in the queue, so nothing speaks over the
        # power-down animation. The sign-off above already played (priority ≥2).
        speech_queue.clear_below_priority(2)
        return resp

    # ── Memory ─────────────────────────────────────────────────────────────────
    if key == "memory_review":
        return _execute_memory_review_command(args, person_id, person_name)

    if key == "memory_forget_fact":
        return _execute_memory_forget_fact_command(args, person_id, person_name)

    if key == "memory_boundary":
        return _execute_memory_boundary_command(person_id, utterance=str(args.get("statement") or ""))

    if key == "memory_correct_fact":
        # A correction about a ROOM OBJECT Rex just remarked on ("actually,
        # that's a pillow") belongs to the room model, which has already consumed
        # it — fall through to a normal conversational reply instead of the
        # person-fact machinery (field 2026-07-18: it hijacked the turn and
        # emitted "I heard the correction, but I need one clear fact to update").
        try:
            from intelligence import room_questions
            if room_questions.recently_captured():
                cap = room_questions.last_capture() or {}
                seen_as = cap.get("label") or "something"
                actual = cap.get("name") or "something else"
                return _say(
                    f"Your object detector misread a {actual} as a {seen_as}, and "
                    f"they just corrected you. Own it in ONE short, self-deprecating "
                    f"in-character line — the correction is saved; no need to ask "
                    f"anything back."
                )
        except Exception:
            pass
        return _execute_memory_correct_fact_command(args, person_id, person_name)

    if key == "memory_remember_fact":
        return _execute_memory_remember_fact_command(args, person_id, person_name)

    if key == "forget_specific":
        target = (args.get("target") or "").strip()
        if person_id is None:
            resp = "I need to know who I'm forgetting that for first."
            _speak_blocking(resp)
            return resp
        result = forgetting.forget_specific_memory(person_id, target)
        if result.terms:
            existing = _session_forget_terms.setdefault(int(person_id), set())
            existing.update(result.terms)
        _log.info(
            "[memory] targeted forget person_id=%s target=%r terms=%s deleted=%s",
            person_id,
            target,
            sorted(result.terms),
            result.deleted,
        )
        if result.total_deleted <= 0:
            resp = f"I couldn't find a stored memory matching {_target_for_user(target)}."
        else:
            resp = f"Okay. I forgot the stored memory I found about {_target_for_user(target)}."
        _speak_blocking(resp, emotion="neutral")
        return resp

    if key == "forget_me":
        target_id, target_name = _resolve_forget_me_target(person_id, person_name)
        if target_id is None:
            resp = "I don't have any record of you to forget."
            _speak_blocking(resp)
            return resp
        _arm_memory_wipe_confirmation(
            scope="person",
            person_id=target_id,
            person_name=target_name,
            requester_id=target_id,
        )
        resp = (
            "Memory wipe armed. Are you sure? Say \"yes forget me\" to confirm "
            "and I'll delete your name, face, voice print, and everything I "
            "remember about you. Very dramatic. Very irreversible."
        )
        _speak_blocking(resp, emotion="neutral")
        return resp

    if key == "forget_everyone":
        _arm_memory_wipe_confirmation(
            scope="all",
            requester_id=person_id,
        )
        resp = (
            "Full memory wipe armed. Are you absolutely sure? Say "
            f"{_memory_wipe_confirmation_hint('all')} to delete every person, "
            "face, voice print, relationship, and conversation memory. This is "
            "the big red button, just with worse branding."
        )
        _speak_blocking(resp, emotion="neutral")
        return resp

    if key == "whats_my_name":
        if person_name:
            return _say(
                f"The person you're talking to is named {person_name}. "
                f"Tell them their name in one in-character line."
            )
        return _say(
            "You don't know this person's name. Tell them you don't know who they are, in character."
        )

    if key == "rename_me":
        response = _handle_name_update_request(raw_text, person_id, person_name)
        return response or ""

    # ── Status ─────────────────────────────────────────────────────────────────
    if key == "status_uptime":
        sys_state = interoception.get_system_state()
        up = sys_state.get("uptime_seconds", 0)
        return _say(
            f"Your uptime is {up // 3600}h {(up % 3600) // 60}m. "
            f"State your uptime in one in-character line."
        )

    if key == "status_climate":
        env: dict = {}
        try:
            from hardware import motion
            env = (motion.telemetry() or {}).get("env") or {}
        except Exception:
            env = {}
        if not env.get("ok") or env.get("t") is None:
            return _say(
                "Someone asked about the room temperature, but your climate sensor "
                "isn't reporting right now. Say so in one in-character line."
            )
        t_c = float(env["t"])
        t_f = t_c * 9.0 / 5.0 + 32.0
        facts = f"The air in the room is {t_c:.1f} degrees Celsius ({t_f:.0f} degrees Fahrenheit)"
        rh = env.get("rh")
        if rh is not None:
            facts += f", relative humidity {float(rh):.0f} percent"
        hpa = env.get("hpa")
        if hpa is not None:
            facts += f", barometric pressure {float(hpa):.0f} hectopascals"
        return _say(
            facts + ". Someone asked about the room climate — answer with the "
            "measurement(s) they actually asked about, in one in-character line."
        )

    # ── Personality ────────────────────────────────────────────────────────────
    if key == "set_personality":
        param = args.get("param", "")
        value = args.get("value", 50)
        if not param:
            return ""
        old, new = personality.set_param(param, int(value), updated_by=updater)
        resp = personality.generate_acknowledgment(param, old, new)
        _speak_blocking(resp)
        return resp

    if key == "query_personality":
        param = args.get("param", "")
        if not param:
            return ""
        val = personality.get_param(param)
        return _say(
            f"Someone asked what your {param} level is. It is currently {val}/100. "
            f"Answer in one in-character line."
        )

    # ── DJ controls ────────────────────────────────────────────────────────────
    if key in ("dj_stop", "dj_skip", "volume_up", "volume_down", "dj_play_vibe"):
        try:
            from features import dj as dj_mod
            if key == "dj_stop":
                dj_mod.stop()
                return _say("The music just stopped. One in-character line.")
            if key == "dj_skip":
                dj_mod.skip()
                return _say("Skipping to the next track. One in-character line.")
            if key == "volume_up":
                dj_mod.volume_up()
                return _say("Turning the volume up. One short in-character line.")
            if key == "volume_down":
                dj_mod.volume_down()
                return _say("Turning the volume down. One short in-character line.")
            if key == "dj_play_vibe":
                vibe = args.get("vibe", "")
                track = dj_mod.handle_request(vibe)
                response = _say(
                    f"Playing something with vibe '{vibe}'. Announce it in one in-character line."
                )
                if track is not None:
                    _start_dj_after_response(track)
                return response
        except Exception as exc:
            _log.debug("DJ command error: %s", exc)

    # ── Games ──────────────────────────────────────────────────────────────────
    if key in (
        "start_trivia", "start_i_spy", "start_20_questions",
        "start_jeopardy", "start_word_association", "start_game", "stop_game",
    ):
        try:
            from features import games as games_mod
            if key == "start_trivia":
                resp = games_mod.start_trivia(person_id)
                _speak_blocking(resp)
                return resp
            if key == "start_i_spy":
                resp = games_mod.start_game("i_spy", person_id)
                _speak_blocking(resp)
                return resp
            if key == "start_20_questions":
                resp = games_mod.start_game("20_questions", person_id)
                _speak_blocking(resp)
                return resp
            if key == "start_jeopardy":
                resp = games_mod.start_game("jeopardy", person_id)
                _speak_blocking(resp)
                return resp
            if key == "start_word_association":
                resp = games_mod.start_game("word_association", person_id)
                _speak_blocking(resp)
                return resp
            if key == "start_game":
                game = args.get("game", "")
                resp = games_mod.start_game(game, person_id)
                _speak_blocking(resp)
                return resp
            if key == "stop_game":
                if not games_mod.is_active():
                    try:
                        from features import dj as dj_mod
                        if dj_mod.is_playing():
                            dj_mod.stop()
                            return _say("The music just stopped. One in-character line.")
                    except Exception as exc:
                        _log.debug("DJ fallback for stop_game command failed: %s", exc)
                resp = games_mod.stop_game(person_id)
                _speak_blocking(resp)
                return resp
        except Exception as exc:
            _log.debug("Games command error: %s", exc)

    # ── Vision ─────────────────────────────────────────────────────────────────
    if key == "vision_describe":
        return _say(_vision_question_answer_prompt(raw_text))

    if key == "vision_who_am_i":
        if person_name:
            return _say(
                f"Someone asked if you know who they are. You do — they're {person_name}. "
                f"Confirm in one in-character line."
            )
        return _say(
            "Someone asked if you know who they are. You don't recognize them. "
            "Respond in one in-character line."
        )

    # ── Fallback for any unhandled key ─────────────────────────────────────────
    return _stream_llm_response(raw_text, person_id)


# ─────────────────────────────────────────────────────────────────────────────
# Post-response processing
# ─────────────────────────────────────────────────────────────────────────────

def _forgotten_terms_for_person(person_id: Optional[int]) -> set[str]:
    if person_id is None:
        return set()
    return set(_session_forget_terms.get(int(person_id), set()))


def _filter_forgotten_transcript(
    transcript: list[dict],
    person_id: Optional[int],
) -> list[dict]:
    terms = _forgotten_terms_for_person(person_id)
    if not terms:
        return transcript
    return [
        turn for turn in transcript
        if not forgetting.text_matches_terms(turn.get("text") or "", terms)
    ]


def _extracted_memory_allowed(payload: dict, person_id: Optional[int]) -> bool:
    terms = _forgotten_terms_for_person(person_id)
    if not terms:
        return True
    return not forgetting.fact_or_event_matches(payload, terms)


def _extracted_fact_provenance() -> tuple[str, Optional[float]]:
    """Source/confidence for a fact the LLM EXTRACTED (an inference, not a direct
    statement). When MEMORY_EXTRACTED_FACTS_PROVISIONAL is on it's stored 'inferred'
    (provisional: lower confidence, fast decay, hedged in the prompt) and earns trust
    only through spaced corroboration — instead of faking explicit/0.95 on one passing
    remark. Direct user statements and corrections keep their own explicit/corrected
    source at their call sites; this only governs the extract_facts paths."""
    if bool(getattr(config, "MEMORY_EXTRACTED_FACTS_PROVISIONAL", True)):
        return "inferred", None  # None → add_fact applies the inferred default confidence
    return "explicit", 0.95


def _conversation_exchange_count() -> int:
    """Transcript length so far — the cadence clock (~2 lines per back-and-forth).

    Mirrors how rex_pov / the conversation arc clock themselves; shrinks at a
    session reset, which `_memory_followup_cadence_allows` uses to self-reset."""
    try:
        return len(conv_memory.get_session_transcript() or [])
    except Exception:
        return 0


def _memory_followup_cadence_allows() -> bool:
    """Moderate clamp: may a proactive memory follow-up ("how did X go?") fire now?

    Fires at most one per conversational lull — requires a minimum gap in
    transcript exchanges AND a seconds cooldown since the last follow-up, and
    stays quiet when the arc reads the room as flat. The spacing is also what lets
    Rex's own POV / idle banter occasionally win the proactive slot instead of
    every gap becoming another interview question. Self-resets when the transcript
    shrinks (new session)."""
    global _last_followup_exchange, _last_followup_at, _fired_followup_event_ids
    try:
        import config
        min_gap = int(getattr(config, "FOLLOWUP_MIN_GAP_EXCHANGES", 5) or 0)
        cooldown = float(getattr(config, "FOLLOWUP_COOLDOWN_SECS", 60.0) or 0.0)
        suppress_flat = bool(getattr(config, "FOLLOWUP_SUPPRESS_WHEN_FLAT", True))
    except Exception:
        min_gap, cooldown, suppress_flat = 5, 60.0, True

    now_exchange = _conversation_exchange_count()
    if now_exchange < _last_followup_exchange:  # transcript shrank → new session
        _last_followup_exchange = -(10**9)
        _last_followup_at = 0.0
        _fired_followup_event_ids = set()

    if suppress_flat:
        try:
            if topic_thread.arc_reads_flat():
                return False
        except Exception:
            pass
    if now_exchange - _last_followup_exchange < min_gap:
        return False
    if cooldown > 0.0 and _last_followup_at > 0.0 and (
        time.monotonic() - _last_followup_at < cooldown
    ):
        return False
    return True


def _note_memory_followup_fired(event_id) -> None:
    """Record that a proactive memory follow-up just fired (cadence + anti-repeat)."""
    global _last_followup_exchange, _last_followup_at
    _last_followup_exchange = _conversation_exchange_count()
    _last_followup_at = time.monotonic()
    try:
        if event_id is not None:
            _fired_followup_event_ids.add(int(event_id))
    except Exception:
        pass


def set_awaiting_followup_event(
    person_id: Optional[int], event_id, event_name: str = ""
) -> None:
    """Arm an outstanding event follow-up so the user's NEXT reply resolves it.

    The consciousness STARTUP follow-up ("how did <festival> go?") fires OUTSIDE the
    in-conversation _post_response path that normally arms this. Without it, a reply like
    "I never went" was never tied back to the event, so the passed-date plan stayed
    planned and re-surfaced every run (the festival re-ask bug). Call this only when the
    follow-up was actually SPOKEN and is specifically about this event."""
    global _awaiting_followup_event
    if event_id is None or person_id is None:
        return
    try:
        eid = int(event_id)
    except (TypeError, ValueError):
        return
    _awaiting_followup_event = {
        "person_id": person_id,
        "event_id": eid,
        "event_name": event_name or "",
    }
    _note_memory_followup_fired(eid)


def _resolve_awaiting_followup(text: str, person_id: Optional[int]) -> Optional[str]:
    """If Rex had an outstanding event follow-up, treat this utterance as the outcome and
    close the loop in memory so the event stops re-surfacing. Returns an event-cancellation
    ack line to speak, or None. (Extracted from the turn handler so it's unit-testable.)"""
    global _awaiting_followup_event
    if not _awaiting_followup_event:
        return None
    event_cancellation_ack: Optional[str] = None
    repair_move = repair_moves.detect(text)
    followup_repair = (
        repair_move is not None
        and repair_move.get("kind") in {
            "clarify",
            "factual",
            "misunderstood",
            "bare_negation",
            "repeat",
        }
    )
    pending_pid = _awaiting_followup_event.get("person_id")
    pending_event_id = _awaiting_followup_event.get("event_id")
    pending_event_name = _awaiting_followup_event.get("event_name")
    pid_matches = (
        pending_pid is None
        or person_id is None
        or pending_pid == person_id
    )
    # A reply that the event never happened ("I never went / didn't go") resolves the
    # follow-up even if it parses as a repair — otherwise Rex keeps re-asking about
    # something the user says they didn't do.
    did_not_happen = _followup_event_did_not_happen(text)
    # Don't badger: after a bounded number of unresolved (repair) turns, give up so the
    # follow-up stops being re-injected into the agenda.
    holds = int(_awaiting_followup_event.get("holds") or 0)
    hold_cap = int(getattr(config, "FOLLOWUP_MAX_HELD_OPEN_TURNS", 1) or 0)
    give_up = followup_repair and holds >= hold_cap
    if pending_event_id is not None and pid_matches and (
        did_not_happen or give_up or not followup_repair
    ):
        try:
            if not did_not_happen and events_memory.looks_like_cancellation(text):
                target_pid = person_id if person_id is not None else pending_pid
                event_hint = {
                    "id": int(pending_event_id),
                    "event_name": pending_event_name or "",
                }
                labels = _cancel_stale_event_memory(target_pid, text, event_hint=event_hint)
                if labels:
                    event_cancellation_ack = _event_cancellation_ack(labels, target_pid)
            elif not did_not_happen and events_memory.looks_like_postponement(text):
                # Postponed, not done: keep the event OPEN and re-dated so Rex anticipates
                # it again later, instead of closing the loop and losing the plan.
                events_memory.reschedule_event(int(pending_event_id))
            else:
                # Real answer, an "I didn't go", or a give-up: close the loop in memory so
                # this event stops surfacing.
                events_memory.mark_followed_up(int(pending_event_id), text.strip())
            _awaiting_followup_event = None
            if did_not_happen or give_up:
                _log.info(
                    "[interaction] follow-up resolved without an outcome — "
                    "event_id=%s reason=%s text=%r",
                    pending_event_id,
                    "did_not_happen" if did_not_happen else "gave_up_after_holds",
                    text,
                )
        except Exception as exc:
            _log.debug("follow-up outcome write failed: %s", exc)
    elif followup_repair:
        _awaiting_followup_event["holds"] = holds + 1
        _log.info(
            "[interaction] follow-up outcome held open because user requested repair — "
            "event_id=%s kind=%s holds=%d text=%r",
            pending_event_id,
            repair_move.get("kind"),
            holds + 1,
            text,
        )
    return event_cancellation_ack


def _post_response(
    user_text: str,
    person_id: Optional[int],
    person_name: Optional[str] = None,
    *,
    assistant_asked_question: bool = False,
    pre_classified_insult: bool = False,
    pre_classified_compliment: bool = False,
    suppress_memory_learning: bool = False,
) -> None:
    """
    Run after every response in ACTIVE state. Sentiment, facts, follow-up,
    and interoception are handled here. Sentiment/facts run in a background
    thread; follow-up delivery and interoception run in the calling thread.
    """
    # ── Follow-up delivery (sync — spoken as part of this turn) ───────────────
    global _awaiting_followup_event

    # Tier 2: do not build a profile on a child. A 10-12yo's noisy joke answers
    # ("China", "kebabs") were being stored as permanent facts. Both the direct and
    # background learning paths below honor suppress_memory_learning, so set it.
    if person_id is not None and not suppress_memory_learning:
        try:
            from intelligence import profile_questions
            if profile_questions.person_is_minor(person_id):
                suppress_memory_learning = True
        except Exception:
            pass

    # The human turn was recorded as learnable BEFORE routing decided suppression.
    # Flip it now so the session-end consolidation pass (which re-extracts over the
    # whole transcript) honors the same suppression the per-turn extractor does — a
    # game answer / misheard command / correction must not become a permanent fact at
    # teardown just because per-turn suppression doesn't reach the consolidation input.
    if suppress_memory_learning:
        try:
            conv_memory.mark_last_human_turn_unlearnable()
        except Exception as exc:
            _log.debug("post_response mark-unlearnable error: %s", exc)

    if _game_suppresses_conversation():
        try:
            interoception.record_interaction()
        except Exception as exc:
            _log.debug("post_response interoception error: %s", exc)
        return

    # P2 — warmth grows from talking: tally engaged turns + shared laughter so the
    # relationship deepens with time spent, not only with explicit compliments. Skip
    # for minors (suppress_memory_learning) so a child's chatter doesn't build a bond.
    if person_id is not None and not suppress_memory_learning:
        try:
            _note_warmth_from_talking(
                person_id, user_text, pre_classified_insult=pre_classified_insult
            )
        except Exception as exc:
            _log.debug("post_response warmth-from-talking error: %s", exc)

    suppress_stale_followup = False
    try:
        suppress_stale_followup = events_memory.looks_like_cancellation(user_text)
    except Exception:
        suppress_stale_followup = False
    # A reply that an event didn't happen ("I didn't end up going") shouldn't be
    # answered by immediately pivoting to a follow-up about a DIFFERENT remembered
    # event — that reads as not listening. Hold the queue for this turn.
    if not suppress_stale_followup:
        try:
            if _followup_event_did_not_happen(user_text):
                suppress_stale_followup = True
        except Exception:
            pass
    try:
        visible_known_count = sum(
            1
            for p in (world_state.get("people") or [])
            if p.get("person_db_id") is not None
        )
        if visible_known_count > 1:
            suppress_stale_followup = True
    except Exception:
        pass

    if person_id is not None and not suppress_stale_followup:
        try:
            followups = consciousness.get_pending_followup(person_id)
            if followups:
                # Never follow up twice on the same event in a session. The in-memory
                # queue can get re-seeded from the DB in the window before a "didn't
                # happen" reply is written, which otherwise re-raises a resolved event
                # (e.g. re-asking about a trip the user already said they skipped).
                followups = [
                    event
                    for event in followups
                    if int(event.get("id") or -1) not in _fired_followup_event_ids
                ]
            if not followups:
                pass
            elif assistant_asked_question:
                # If Rex just asked a question, do not immediately ask another one.
                # Re-queue and wait for the person's reply first.
                for event in followups:
                    consciousness.set_pending_followup(person_id, event)
            elif not _memory_followup_cadence_allows():
                # Moderate cadence clamp: at most one follow-up per conversational
                # lull, and none while the room reads flat. Re-queue everything so
                # nothing is lost — it fires in a later lull, which also leaves the
                # proactive slot open for Rex's own POV / idle banter.
                for event in followups:
                    consciousness.set_pending_followup(person_id, event)
            else:
                # Ask one follow-up at a time; keep the rest queued.
                event = followups[0]
                for leftover in followups[1:]:
                    consciousness.set_pending_followup(person_id, leftover)

                event_name = event.get("event_name", "that thing you mentioned")
                resp = llm.get_response(
                    f"You're following up on something this person mentioned before: "
                    f"'{event_name}'. Ask whether it ended up happening and how it "
                    f"went, in one short Rex-style line — a plan is not a fact, so "
                    f"do not assert that it happened.",
                    person_id,
                )
                if resp:
                    conv_memory.add_to_transcript("Rex", resp)
                    conv_log.log_rex(resp)
                    completed = _speak_blocking(resp)
                    if completed:
                        _register_rex_utterance(
                            resp,
                            source="memory_followup",
                            topic=event_name,
                            target_person_id=person_id,
                            target_name=person_name,
                            expected_reply_types=[
                                "status_update",
                                "cancel_event",
                                "dismissal",
                            ],
                            blocked_actions=[
                                "identity.name_correction",
                                "identity.introduce_person",
                            ],
                        )
                        _awaiting_followup_event = None
                        event_id = event.get("id")
                        # Record the fire for cadence spacing + per-session
                        # anti-repeat (so this event is never re-raised).
                        _note_memory_followup_fired(event_id)
                        if event_id is not None:
                            _awaiting_followup_event = {
                                "person_id": person_id,
                                "event_id": int(event_id),
                                "event_name": event_name,
                            }
                        try:
                            consciousness.note_memory_hint(resp, person_id)
                        except Exception as exc:
                            _log.debug("note follow-up memory hint failed: %s", exc)
                    else:
                        consciousness.set_pending_followup(person_id, event)
                else:
                    consciousness.set_pending_followup(person_id, event)
        except Exception as exc:
            _log.debug("post_response follow-up error: %s", exc)

    # ── Interoception (sync — just a counter update, no I/O) ──────────────────
    try:
        interoception.record_interaction()
    except Exception as exc:
        _log.debug("post_response interoception error: %s", exc)

    memory_recent_transcript = None
    if person_id is not None and not suppress_memory_learning:
        try:
            _learn_direct_memory_from_user_text(user_text, person_id)
        except Exception as exc:
            _log.debug("direct memory learning error: %s", exc)
        # Open commitments: file a first-person promise ("I'll fix that sensor") as a
        # status='promised' event so Rex can dryly needle it on a LATER turn. Deterministic
        # (regex, no LLM); skipped on cancel/postpone/done turns (those RESOLVE a promise,
        # handled on the hot path) so a retraction can't immediately re-file a promise.
        if bool(getattr(config, "OPEN_COMMITMENTS_ENABLED", True)):
            try:
                if (
                    events_memory.looks_like_commitment(user_text)
                    and not events_memory.looks_like_cancellation(user_text)
                    and not events_memory.looks_like_postponement(user_text)
                    and not events_memory.looks_like_completion(user_text)
                ):
                    events_memory.add_commitment(person_id, user_text)
            except Exception as exc:
                _log.debug("[commitments] capture failed: %s", exc)
        # Spontaneous outcome report → resolve the matching open plan right now
        # ("I got all the new interns set up" closes the stored intern-training
        # plan with their words as the outcome), so Rex never later asks "so did
        # that happen?" about a thing they already told him. Deterministic
        # (regex + stemmed strong-overlap, no LLM); a non-matching report is a
        # silent no-op.
        try:
            if not events_memory.looks_like_cancellation(user_text):
                events_memory.complete_matching_events(person_id, user_text)
        except Exception as exc:
            _log.debug("[events] spontaneous completion resolve failed: %s", exc)
        try:
            transcript = conv_memory.get_session_transcript()
            recent = transcript[-10:] if len(transcript) >= 10 else transcript
            memory_recent_transcript = list(_filter_forgotten_transcript(recent, person_id))
        except Exception as exc:
            _log.debug("post_response memory transcript snapshot error: %s", exc)
            memory_recent_transcript = []

    # ── Sentiment + facts (async — both are LLM calls) ────────────────────────
    def _background() -> None:
        # Sentiment analysis → anger / relationship updates
        try:
            sentiment = llm.analyze_sentiment(user_text)

            if sentiment.get("is_insult"):
                # Skip if layer 1 already counted this turn so we don't
                # double-bump anger or antagonism for one utterance.
                if not pre_classified_insult:
                    personality.increment_anger(person_id)
                    if person_id is not None:
                        # P3: a jab from a warm friend reads as banter, not antagonism.
                        people_memory.apply_jab(person_id, "insult_mild")
                    try:
                        # Immediate physical reaction: the anger_flash beat drops the
                        # visor DOWN over the eyes (a glower), mirroring the keyword
                        # path — so a subtler LLM-detected insult gets the same drop,
                        # not just the sustained offended posture.
                        _play_event_body_beat("insult.detected")
                    except Exception as exc:
                        _log.debug("[interaction] layer-2 insult beat skipped: %s", exc)
                    _set_body_mood("offended", source="layer2_insult")

            elif sentiment.get("is_apology"):
                personality.decrement_anger()
                if person_id is not None:
                    people_memory.apply_relationship_increment(person_id, "sincere_apology")

            if sentiment.get("is_compliment"):
                if person_id is not None:
                    people_memory.apply_relationship_increment(person_id, "compliment")
                # Layer-2 pleased reaction for subtler praise the keyword pre-check
                # missed; skip when layer 1 already reacted this turn.
                if not pre_classified_compliment:
                    try:
                        _play_event_body_beat("compliment.detected")
                        _set_body_mood("proud", source="layer2_compliment")
                        _flash_chest_compliment()
                    except Exception as exc:
                        _log.debug("[interaction] layer-2 compliment beat skipped: %s", exc)

        except Exception as exc:
            _log.debug("post_response sentiment error: %s", exc)

        if person_id is not None and not suppress_memory_learning:
            try:
                friendship_patterns.learn_from_turn(person_id, user_text)
            except Exception as exc:
                _log.debug("friendship pattern learning error: %s", exc)

        # Fact extraction from recent transcript
        if person_id is not None and memory_recent_transcript is not None:
            try:
                recent = list(memory_recent_transcript)
                new_facts = llm.extract_facts(person_id, recent, person_name=person_name)
                saved_count = 0
                for fact in new_facts:
                    if (
                        fact.get("key")
                        and fact.get("value")
                        and _extracted_memory_allowed(fact, person_id)
                    ):
                        _ext_src, _ext_conf = _extracted_fact_provenance()
                        facts_memory.add_fact(
                            person_id,
                            fact.get("category", "other"),
                            fact["key"],
                            fact["value"],
                            source=_ext_src,
                            confidence=_ext_conf,
                            utterance=fact.get("source_quote", ""),
                        )
                        _record_recent_memory_candidate(
                            person_id,
                            kind="fact",
                            target=" ".join([
                                str(fact.get("category") or ""),
                                str(fact.get("key") or ""),
                                str(fact.get("value") or ""),
                            ]),
                            label=str(fact.get("value") or fact.get("key") or "that fact"),
                        )
                        saved_count += 1
                _log.info(
                    "[interaction] facts extracted=%d saved=%d for person_id=%s",
                    len(new_facts), saved_count, person_id,
                )
            except Exception as exc:
                _log.debug("post_response fact extraction error: %s", exc)

            # Typed preference extraction — supplements generic facts.
            try:
                recent = list(memory_recent_transcript)
                new_preferences = llm.extract_preferences(
                    person_id,
                    recent,
                    person_name=person_name,
                )
                saved_preferences = 0
                for pref in new_preferences:
                    if (
                        pref.get("domain")
                        and pref.get("preference_type")
                        and pref.get("key")
                        and _extracted_memory_allowed(pref, person_id)
                    ):
                        if pref.get("preference_type") == "boundary":
                            pref["importance"] = max(
                                float(pref.get("importance") or 0.0),
                                0.95,
                            )
                        preferences_memory.upsert_preference(
                            person_id,
                            pref["domain"],
                            pref["preference_type"],
                            pref["key"],
                            pref.get("value") or "",
                            confidence=float(pref.get("confidence") or 1.0),
                            importance=float(pref.get("importance") or 0.5),
                            source=pref.get("source") or "explicit",
                        )
                        _record_recent_memory_candidate(
                            person_id,
                            kind="preference",
                            target=" ".join([
                                str(pref.get("domain") or ""),
                                str(pref.get("preference_type") or ""),
                                str(pref.get("key") or ""),
                                str(pref.get("value") or ""),
                            ]),
                            label=str(pref.get("value") or pref.get("key") or "that preference"),
                        )
                        saved_preferences += 1
                _log.info(
                    "[interaction] preferences extracted=%d saved=%d for person_id=%s",
                    len(new_preferences), saved_preferences, person_id,
                )
            except Exception as exc:
                _log.debug("post_response preference extraction error: %s", exc)

            # Typed interest extraction — durable conversation hooks separate
            # from generic facts.
            try:
                recent = list(memory_recent_transcript)
                new_interests = llm.extract_interests(
                    person_id,
                    recent,
                    person_name=person_name,
                )
                saved_interests = 0
                for interest in new_interests:
                    if (
                        interest.get("name")
                        and _extracted_memory_allowed(interest, person_id)
                    ):
                        interests_memory.upsert_interest(
                            person_id,
                            interest["name"],
                            interest.get("category") or "hobby",
                            interest.get("interest_strength") or "medium",
                            confidence=float(interest.get("confidence") or 1.0),
                            source=interest.get("source") or "explicit",
                            notes=interest.get("notes") or "",
                            associated_people=interest.get("associated_people") or "",
                            associated_stories=interest.get("associated_stories") or "",
                        )
                        _record_recent_memory_candidate(
                            person_id,
                            kind="interest",
                            target=" ".join([
                                str(interest.get("name") or ""),
                                str(interest.get("category") or ""),
                                str(interest.get("notes") or ""),
                            ]),
                            label=str(interest.get("name") or "that interest"),
                        )
                        saved_interests += 1
                _log.info(
                    "[interaction] interests extracted=%d saved=%d for person_id=%s",
                    len(new_interests), saved_interests, person_id,
                )
            except Exception as exc:
                _log.debug("post_response interest extraction error: %s", exc)

            # Event extraction → person_events table for follow-ups + small talk
            try:
                recent = list(memory_recent_transcript)
                new_events = llm.extract_events(person_id, recent, person_name=person_name)
                saved_events = 0
                if new_events:
                    existing = events_memory.get_upcoming_events(person_id) or []
                    existing_keys = {
                        ((e.get("event_name") or "").strip().lower(), e.get("event_date"))
                        for e in existing
                    }
                    for ev in new_events:
                        if not _extracted_memory_allowed(ev, person_id):
                            continue
                        key = (ev["event_name"].strip().lower(), ev.get("event_date"))
                        if key in existing_keys:
                            continue
                        events_memory.add_event(
                            person_id,
                            ev["event_name"],
                            ev.get("event_date"),
                            ev.get("event_notes", ""),
                            hedged=bool(ev.get("hedged")) or None,
                        )
                        existing_keys.add(key)
                        saved_events += 1
                if saved_events:
                    _log.info(
                        "[interaction] events extracted=%d saved=%d for person_id=%s",
                        len(new_events), saved_events, person_id,
                    )
            except Exception as exc:
                _log.debug("post_response event extraction error: %s", exc)

        # Callback humor: bank a candidate premise from this turn (gated like
        # the extractors above — suppress_memory_learning empties the
        # transcript snapshot, and a turn scrubbed by the forgotten-terms
        # filter must not be banked), then re-judge which banked premise (if
        # any) connects to the live topic so the NEXT reply can claim it.
        if person_id is not None:
            if memory_recent_transcript:
                try:
                    from intelligence import callback_engine as _cb_engine
                    turn_survived_filter = any(
                        str(entry.get("speaker") or "").lower() != "rex"
                        and str(entry.get("text") or "") == (user_text or "")
                        for entry in memory_recent_transcript
                    )
                    if turn_survived_filter:
                        _cb_engine.bank_from_turn(person_id, user_text)
                except Exception as exc:
                    _log.debug("post_response callback banking error: %s", exc)
            try:
                from intelligence import callback_engine as _cb_engine
                _cb_engine.refresh_relevance(person_id)
            except Exception as exc:
                _log.debug("post_response callback relevance error: %s", exc)

    threading.Thread(target=_background, daemon=True, name="post-response-bg").start()


# ─────────────────────────────────────────────────────────────────────────────
# Session memory consolidation
# ─────────────────────────────────────────────────────────────────────────────

def _clamp_memory_float(value: object, default: float = 0.5) -> float:
    try:
        return max(0.0, min(1.0, float(value)))
    except (TypeError, ValueError):
        return default


def _normalize_memory_source(value: object, default: str = "explicit") -> str:
    source = str(value or default).strip().lower()
    return source if source in {"explicit", "inferred", "observed", "corrected"} else default


def _normalize_decay_rate(value: object, default: str = "normal") -> str:
    decay = str(value or default).strip().lower()
    return decay if decay in {"fast", "normal", "permanent"} else default


def _existing_memory_snapshot(person_id: int) -> dict:
    """Build a compact existing-memory snapshot for consolidation prompts."""
    try:
        person = people_memory.get_person(person_id) or {}
    except Exception:
        person = {}
    try:
        facts = facts_memory.get_prompt_worthy_facts(person_id, limit=16)
    except Exception:
        facts = []
    try:
        preferences = preferences_memory.get_preferences_for_prompt(person_id, limit=16)
    except Exception:
        preferences = []
    try:
        interests = interests_memory.get_interests_for_prompt(person_id, limit=16)
    except Exception:
        interests = []
    try:
        events = events_memory.get_open_events(person_id)
    except Exception:
        events = []
    try:
        relationships = social_memory.get_all_involving(person_id)
    except Exception:
        relationships = []
    try:
        emotional = emotional_events.get_active_events(person_id, limit=8)
    except Exception:
        emotional = []
    return {
        "person": {
            "id": person.get("id"),
            "name": person.get("name"),
            "nickname": person.get("nickname"),
            "friendship_tier": person.get("friendship_tier"),
        },
        "facts": [
            {
                "category": f.get("category"),
                "key": f.get("key"),
                "value": f.get("value"),
                "confidence": f.get("confidence"),
                "source": f.get("source"),
                "importance": f.get("importance"),
                "decay_rate": f.get("decay_rate"),
            }
            for f in facts
        ],
        "preferences": preferences,
        "interests": interests,
        "events": events,
        "relationships": relationships,
        "emotional_events": emotional,
    }


def _payload_allowed_against_terms(payload: dict, terms: set[str]) -> bool:
    if not terms:
        return True
    return not forgetting.fact_or_event_matches(payload, terms)


def _store_consolidated_facts(
    person_id: int,
    items: list,
    terms: set[str],
    counts: dict[str, int],
) -> None:
    for item in items:
        if not isinstance(item, dict):
            counts["requires_review"] += 1
            continue
        key = str(item.get("key") or item.get("name") or "").strip()
        value = str(item.get("value") or "").strip()
        if not key or not value:
            counts["requires_review"] += 1
            continue
        if not _payload_allowed_against_terms(item, terms):
            counts["skipped"] += 1
            continue
        source = _normalize_memory_source(item.get("source"))
        category = str(item.get("category") or "other").strip().lower()
        if source == "corrected":
            facts_memory.apply_fact_correction(
                person_id,
                key,
                value,
                category=category,
                importance=_clamp_memory_float(item.get("importance"), 0.9),
                decay_rate=_normalize_decay_rate(item.get("decay_rate"), "normal"),
            )
            counts["updated"] += 1
        else:
            facts_memory.add_fact(
                person_id,
                category,
                key,
                value,
                source=source,
                confidence=_clamp_memory_float(item.get("confidence"), 0.95),
                importance=_clamp_memory_float(item.get("importance"), 0.5),
                decay_rate=_normalize_decay_rate(item.get("decay_rate"), "normal"),
            )
            counts["stored"] += 1


def _store_consolidated_preferences(
    person_id: int,
    items: list,
    terms: set[str],
    counts: dict[str, int],
) -> None:
    valid_types = {"likes", "dislikes", "prefers", "avoids", "boundary"}
    for item in items:
        if not isinstance(item, dict):
            counts["requires_review"] += 1
            continue
        domain = str(item.get("domain") or item.get("category") or "general").strip().lower()
        pref_type = str(item.get("preference_type") or item.get("type") or "").strip().lower()
        key = str(item.get("key") or item.get("name") or "").strip()
        if pref_type not in valid_types or not key:
            counts["requires_review"] += 1
            continue
        if not _payload_allowed_against_terms(item, terms):
            counts["skipped"] += 1
            continue
        importance = _clamp_memory_float(item.get("importance"), 0.5)
        if pref_type == "boundary":
            importance = max(importance, 0.95)
        preferences_memory.upsert_preference(
            person_id,
            domain,
            pref_type,
            key,
            str(item.get("value") or "").strip(),
            confidence=_clamp_memory_float(item.get("confidence"), 0.95),
            importance=importance,
            source=_normalize_memory_source(item.get("source")),
        )
        counts["stored"] += 1


def _store_consolidated_interests(
    person_id: int,
    items: list,
    terms: set[str],
    counts: dict[str, int],
) -> None:
    for item in items:
        if not isinstance(item, dict):
            counts["requires_review"] += 1
            continue
        name = str(item.get("name") or item.get("key") or "").strip()
        if not name:
            counts["requires_review"] += 1
            continue
        if not _payload_allowed_against_terms(item, terms):
            counts["skipped"] += 1
            continue
        interests_memory.upsert_interest(
            person_id,
            name,
            str(item.get("category") or "hobby").strip().lower(),
            str(item.get("interest_strength") or "medium").strip().lower(),
            confidence=_clamp_memory_float(item.get("confidence"), 0.95),
            source=_normalize_memory_source(item.get("source")),
            notes=str(item.get("notes") or item.get("rationale") or "").strip(),
            associated_people=str(item.get("associated_people") or "").strip(),
            associated_stories=str(item.get("associated_stories") or "").strip(),
        )
        counts["stored"] += 1


def _store_consolidated_events(
    person_id: int,
    items: list,
    terms: set[str],
    counts: dict[str, int],
) -> None:
    try:
        existing = events_memory.get_open_events(person_id) or []
    except Exception:
        existing = []
    existing_keys = {
        ((e.get("event_name") or "").strip().lower(), e.get("event_date"))
        for e in existing
    }
    for item in items:
        if not isinstance(item, dict):
            counts["requires_review"] += 1
            continue
        name = str(item.get("event_name") or item.get("name") or item.get("value") or "").strip()
        if not name:
            counts["requires_review"] += 1
            continue
        if not _payload_allowed_against_terms(item, terms):
            counts["skipped"] += 1
            continue
        event_date = item.get("event_date")
        if event_date in ("", "null", "None"):
            event_date = None
        key = (name.lower(), event_date)
        if key in existing_keys:
            counts["updated"] += 1
            continue
        events_memory.add_event(
            person_id,
            name,
            event_date,
            str(item.get("event_notes") or item.get("rationale") or "").strip(),
            hedged=bool(item.get("hedged")) or None,
        )
        existing_keys.add(key)
        counts["stored"] += 1


def _store_consolidated_relationships(
    person_id: int,
    items: list,
    terms: set[str],
    counts: dict[str, int],
) -> None:
    for item in items:
        if not isinstance(item, dict):
            counts["requires_review"] += 1
            continue
        other_name = str(item.get("other_person_name") or item.get("name") or "").strip()
        relationship = str(item.get("relationship") or item.get("value") or "").strip()
        if not other_name or not relationship:
            counts["requires_review"] += 1
            continue
        if not _payload_allowed_against_terms(item, terms):
            counts["skipped"] += 1
            continue
        other_id, _created = people_memory.find_or_create_person(other_name)
        if other_id is None:
            counts["requires_review"] += 1
            continue
        direction = str(item.get("direction") or "current_to_other").strip().lower()
        if direction == "other_to_current":
            social_memory.save_relationship(int(other_id), person_id, relationship, described_by=person_id)
        else:
            social_memory.save_relationship(person_id, int(other_id), relationship, described_by=person_id)
        counts["stored"] += 1


def _store_consolidated_emotional_events(
    person_id: int,
    items: list,
    terms: set[str],
    counts: dict[str, int],
) -> None:
    for item in items:
        if not isinstance(item, dict):
            counts["requires_review"] += 1
            continue
        desc = str(item.get("description") or item.get("value") or "").strip()
        if not desc:
            counts["requires_review"] += 1
            continue
        if not _payload_allowed_against_terms(item, terms):
            counts["skipped"] += 1
            continue
        sensitivity = item.get("sensitivity_decay_days")
        try:
            sensitivity = int(sensitivity) if sensitivity is not None else None
        except (TypeError, ValueError):
            sensitivity = None
        try:
            valence = max(-1.0, min(1.0, float(item.get("valence") or -0.5)))
        except (TypeError, ValueError):
            valence = -0.5
        # NOTE: consolidation does not resolve event recency (its schema never captures it),
        # so add_event() below records recency='unknown' by default — which the proactive
        # check-in/greeting gates treat as NOT recent. A recency-sensitive check-in therefore
        # relies on the live empathy-path capture, not this session-end consolidation path.
        emotional_events.add_event(
            person_id,
            str(item.get("category") or "other").strip().lower(),
            desc,
            valence=valence,
            sensitivity_decay_days=sensitivity,
            person_invited_topic=bool(item.get("person_invited_topic", True)),
            loss_subject=item.get("loss_subject"),
            loss_subject_kind=item.get("loss_subject_kind"),
            loss_subject_name=item.get("loss_subject_name"),
        )
        counts["stored"] += 1


def _apply_consolidated_corrections(
    person_id: int,
    person_name: Optional[str],
    items: list,
    terms: set[str],
    counts: dict[str, int],
) -> None:
    for item in items:
        if not isinstance(item, dict):
            counts["requires_review"] += 1
            continue
        if not _payload_allowed_against_terms(item, terms):
            counts["skipped"] += 1
            continue
        target = str(item.get("target") or item.get("type") or "fact").strip().lower()
        key = str(item.get("key") or item.get("name") or target).strip()
        value = str(item.get("value") or "").strip()
        if not value:
            counts["requires_review"] += 1
            continue
        if target == "identity" and key in {"name", "display_name", "nickname"}:
            if people_memory.rename_person(person_id, value):
                _refresh_world_state_person_name(person_id, value)
                facts_memory.apply_fact_correction(
                    person_id,
                    "name",
                    value,
                    category="identity",
                    importance=0.95,
                    decay_rate="permanent",
                )
                counts["updated"] += 1
            else:
                counts["requires_review"] += 1
            continue
        if target == "preference":
            _store_consolidated_preferences(person_id, [dict(item, source="corrected")], terms, counts)
            continue
        if target == "interest":
            _store_consolidated_interests(person_id, [dict(item, source="corrected")], terms, counts)
            continue
        facts_memory.apply_fact_correction(
            person_id,
            key,
            value,
            category=str(item.get("category") or "other").strip().lower(),
            importance=_clamp_memory_float(item.get("importance"), 0.9),
            decay_rate=_normalize_decay_rate(item.get("decay_rate"), "normal"),
        )
        counts["updated"] += 1


def _write_consolidated_memory(
    person_id: int,
    person_name: Optional[str],
    consolidated: dict,
    forgotten_terms: set[str],
) -> dict[str, int]:
    counts = {"stored": 0, "updated": 0, "skipped": 0, "requires_review": 0}
    _apply_consolidated_corrections(
        person_id,
        person_name,
        consolidated.get("corrections") or [],
        forgotten_terms,
        counts,
    )
    _store_consolidated_facts(person_id, consolidated.get("stable_facts") or [], forgotten_terms, counts)
    _store_consolidated_preferences(person_id, consolidated.get("preferences") or [], forgotten_terms, counts)
    _store_consolidated_interests(person_id, consolidated.get("interests") or [], forgotten_terms, counts)
    _store_consolidated_relationships(person_id, consolidated.get("relationships") or [], forgotten_terms, counts)
    _store_consolidated_events(person_id, consolidated.get("events") or [], forgotten_terms, counts)
    _store_consolidated_emotional_events(
        person_id,
        consolidated.get("emotional_events") or [],
        forgotten_terms,
        counts,
    )
    discarded = consolidated.get("discarded_noise") or []
    counts["skipped"] += len(discarded) if isinstance(discarded, list) else 0
    return counts


def _consolidate_session_memories(
    person_id: int,
    person_name: Optional[str],
    person_transcript: list[dict],
    forgotten_terms: set[str],
) -> bool:
    """Run bounded session-end memory consolidation. Returns True when completed."""
    if not bool(getattr(config, "MEMORY_CONSOLIDATION_ENABLED", True)):
        return False
    min_exchanges = int(getattr(config, "MEMORY_CONSOLIDATION_MIN_SESSION_EXCHANGES", 3))
    human_turns = [
        t for t in person_transcript
        if str(t.get("speaker") or "").lower() not in {"rex", "dj-r3x", "djr3x"}
    ]
    if _session_exchange_count < min_exchanges and len(human_turns) < min_exchanges:
        _log.info(
            "[memory_consolidation] skipped person_id=%s exchanges=%s human_turns=%s min=%s",
            person_id,
            _session_exchange_count,
            len(human_turns),
            min_exchanges,
        )
        return True

    result_box: dict[str, object] = {"completed": False}

    def _run() -> None:
        try:
            existing = _existing_memory_snapshot(person_id)
            consolidated = llm.consolidate_session_memories(
                person_id,
                person_transcript,
                person_name=person_name,
                existing_memories=existing,
                now_iso=datetime.now(timezone.utc).isoformat(),
            )
            counts = _write_consolidated_memory(
                person_id,
                person_name,
                consolidated,
                forgotten_terms,
            )
            result_box["completed"] = True
            result_box["counts"] = counts
            _log.info(
                "[memory_consolidation] person_id=%s stored=%d updated=%d "
                "skipped_as_noise=%d requires_review=%d",
                person_id,
                counts["stored"],
                counts["updated"],
                counts["skipped"],
                counts["requires_review"],
            )
        except Exception as exc:
            result_box["completed"] = True
            result_box["error"] = str(exc)
            _log.error(
                "[memory_consolidation] failed person_id=%s: %s",
                person_id,
                exc,
                exc_info=True,
            )

    worker = threading.Thread(
        target=_run,
        daemon=True,
        name=f"memory-consolidation-{person_id}",
    )
    worker.start()
    timeout = float(getattr(config, "MEMORY_CONSOLIDATION_TIMEOUT_SECS", 12.0))
    worker.join(timeout=max(1.0, timeout))
    if worker.is_alive():
        _log.warning(
            "[memory_consolidation] timed out after %.1fs for person_id=%s; continuing teardown",
            timeout,
            person_id,
        )
        return True
    return bool(result_box.get("completed"))


# ─────────────────────────────────────────────────────────────────────────────
# Session teardown
# ─────────────────────────────────────────────────────────────────────────────

def _end_session(*, include_consolidation: bool = True) -> None:
    """
    Called on ACTIVE → IDLE transition. Generates and persists a session summary,
    updates visit records and familiarity, then clears in-memory session state.

    include_consolidation=False is the SHUTDOWN profile (see
    persist_session_memories_at_shutdown): the summary row and visit/warmth updates
    still land, but the session-end consolidation + extraction fallbacks are skipped —
    the rolling per-exchange extractors already ran all session, and power-off must
    not wait on a chain of LLM calls.
    """
    global _session_exchange_count, _identity_prompt_until, _awaiting_followup_event
    global _idle_outro_spoken, _lean_memory_mused_this_session
    global _lean_mood_shared_this_session
    global _lean_news_mentioned_this_session, _last_news_story_offered
    global _pending_introduction, _pending_intro_followup, _pending_intro_voice_capture
    global _pending_common_first_name_identity, _pending_common_first_name_introduction
    global _pending_existing_common_first_name, _pending_identity_match_confirmation
    global _pending_last_name_confirm
    global _pending_prompted_name_confirmation

    transcript = conv_memory.get_session_transcript()

    # "Why was he quiet?" — one summary line per session of lull-consult outcomes.
    try:
        _log_impulse_session_summary()
    except Exception:
        pass

    # "Why didn't he hear me?" — heard vs silently-dropped utterances, and why.
    try:
        _log_capture_session_summary()
    except Exception:
        pass

    # A conversation with real back-and-forth in it leaves Rex in a better mood for
    # the rest of the day; an empty session doesn't count. Persist the mood here too —
    # the day's accumulated drift should survive a restart, not just a clean shutdown.
    try:
        from intelligence import rex_mood
        if len(transcript or []) >= int(
            getattr(config, "REX_MOOD_GOOD_CONVERSATION_TURNS", 6)
        ):
            rex_mood.note("good_conversation")
        rex_mood.persist()
    except Exception as exc:
        _log.debug("[interaction] day-mood session-end update skipped: %s", exc)

    if not transcript:
        _session_exchange_count = 0
        _session_person_ids.clear()
        _session_person_turn_counts.clear()
        _session_warmth_signals.clear()
        _session_forget_terms.clear()
        _session_router_control_topics.clear()
        _interest_idle_followups_spoken.clear()
        _low_memory_idle_questions_spoken.clear()
        _idle_plans_asked.clear()
        _recently_banned_topics.clear()
        _recent_rex_questions.clear()
        _close_onboarding("session reset")
        _recent_memory_candidates.clear()
        _clear_anonymous_speaker_slots()
        _idle_outro_spoken = False
        _lean_memory_mused_this_session = False
        _lean_mood_shared_this_session = False
        _lean_news_mentioned_this_session = False
        _last_news_story_offered = None
        _lean_impulse_spoken_times.clear()
        try:
            topic_thread.clear()
        except Exception:
            pass
        try:
            premise_memory.clear()
        except Exception:
            pass
        try:
            # New session token + per-session no-repeat set + volume ledger.
            from intelligence import callback_engine as _cb_engine
            _cb_engine.clear_session()
            llm.clear_session()  # nostalgia / stale-fact / episodic-callback dedup
        except Exception:
            pass
        try:
            # Persist the preoccupation (+ anti-repeat set) BEFORE wiping it, so it
            # carries across visits; the next session restores it via load_persisted().
            rex_pov.persist()
            rex_pov.clear()
        except Exception:
            pass
        try:
            dialogue_act.clear()
        except Exception:
            pass
        try:
            user_energy.clear()
        except Exception:
            pass
        try:
            question_budget.clear()
        except Exception:
            pass
        try:
            repair_moves.clear()
        except Exception:
            pass
        try:
            end_thread.clear()
        except Exception:
            pass
        try:
            turn_completion.clear()
        except Exception:
            pass
        _identity_prompt_until = 0.0
        _awaiting_followup_event = None
        _pending_introduction = None
        _pending_intro_followup = None
        _pending_intro_voice_capture = None
        _pending_common_first_name_identity = None
        _pending_common_first_name_introduction = None
        _pending_existing_common_first_name = None
        _pending_identity_match_confirmation = None
        _pending_prompted_name_confirmation = None
        _clear_pending_memory_wipe()
        _common_first_name_prompted_this_session.clear()
        try:
            consciousness.clear_response_wait()
            consciousness.clear_engagement()
        except Exception:
            pass
        return

    for person_id in list(_session_person_ids):
        try:
            person_row = people_memory.get_person(person_id)
            person_name = person_row.get("name") if person_row else None
            person_transcript = _filter_forgotten_transcript(transcript, person_id)

            if person_transcript:
                # Prefer the conversation arc — it's already computed each turn,
                # richer (mood/landed-flopped/open threads), and reusing it saves an
                # extra session-summary OpenAI call. Guards: only a 1:1 session (the
                # arc summarizes the whole conversation, not per-person), AND only
                # when the arc's recent-window actually covered the session — for a
                # long session the windowed arc would drop early content, so fall
                # back to the full-transcript generate_session_summary.
                arc_window = int(getattr(config, "CONVERSATION_ARC_CONTEXT_LINES", 12))
                arc_fields = (
                    topic_thread.arc_persistence_fields()
                    if len(_session_person_ids) == 1 and len(transcript) <= arc_window
                    else None
                )
                if arc_fields:
                    summary, emotion_tone, topics = arc_fields
                else:
                    summary = llm.generate_session_summary(person_id, person_transcript)
                    emotion_tone, topics = "neutral", ""
                    # Long / multi-person sessions used to persist topics="" — starving the
                    # cross-session trends layer (memory/trends.py recurring topics) for
                    # exactly the sessions that matter most. The arc's topic tags are
                    # already computed each turn; reuse them for the structured columns
                    # even when its windowed summary can't replace the full-transcript one.
                    try:
                        arc_tail = topic_thread.arc_persistence_fields()
                        if arc_tail:
                            emotion_tone, topics = arc_tail[1], arc_tail[2]
                    except Exception as exc:
                        _log.debug("arc topic fallback skipped: %s", exc)
                if summary:
                    conv_memory.save_conversation(
                        person_id,
                        summary,
                        emotion_tone=emotion_tone,
                        topics=topics,
                    )
                    # Claim this person so the shutdown fallback (which runs when
                    # this worker blows its join budget) does not write a second,
                    # worse row for the same session.
                    with _session_row_lock:
                        _session_rows_written.add(int(person_id))

            forgotten_terms = _forgotten_terms_for_person(person_id)
            # Only LEARNABLE turns feed durable memory extraction. Turns marked
            # unlearnable (commands, games, corrections, general-knowledge Q&A,
            # minors) were already suppressed per-turn; excluding them here closes
            # the session-end re-extraction hole. The session SUMMARY above still
            # uses the full person_transcript (it's a narrative recap, not durable
            # facts).
            learnable_transcript = [
                t for t in person_transcript if t.get("learnable", True)
            ]
            consolidation_completed = False
            if learnable_transcript and include_consolidation:
                consolidation_completed = _consolidate_session_memories(
                    person_id,
                    person_name,
                    learnable_transcript,
                    forgotten_terms,
                )

            # Full-transcript extraction fallback — catches facts the
            # per-exchange rolling window may have missed when consolidation is
            # disabled, below threshold, or times out/fails before writing.
            if learnable_transcript and include_consolidation and not consolidation_completed:
                try:
                    end_facts = llm.extract_facts(person_id, learnable_transcript, person_name=person_name)
                    saved = 0
                    for fact in end_facts:
                        if (
                            fact.get("key")
                            and fact.get("value")
                            and _extracted_memory_allowed(fact, person_id)
                        ):
                            _ext_src, _ext_conf = _extracted_fact_provenance()
                            facts_memory.add_fact(
                                person_id,
                                fact.get("category", "other"),
                                fact["key"],
                                fact["value"],
                                source=_ext_src,
                                confidence=_ext_conf,
                                utterance=fact.get("source_quote", ""),
                            )
                            _record_recent_memory_candidate(
                                person_id,
                                kind="fact",
                                target=" ".join([
                                    str(fact.get("category") or ""),
                                    str(fact.get("key") or ""),
                                    str(fact.get("value") or ""),
                                ]),
                                label=str(fact.get("value") or fact.get("key") or "that fact"),
                            )
                            saved += 1
                    _log.info(
                        "[interaction] session-end facts extracted=%d saved=%d for person_id=%s (%s)",
                        len(end_facts), saved, person_id, person_name,
                    )
                except Exception as exc:
                    _log.error("session-end fact extraction error for person_id=%s: %s", person_id, exc)

                try:
                    end_preferences = llm.extract_preferences(
                        person_id,
                        learnable_transcript,
                        person_name=person_name,
                    )
                    saved_preferences = 0
                    for pref in end_preferences:
                        if (
                            pref.get("domain")
                            and pref.get("preference_type")
                            and pref.get("key")
                            and _extracted_memory_allowed(pref, person_id)
                        ):
                            if pref.get("preference_type") == "boundary":
                                pref["importance"] = max(
                                    float(pref.get("importance") or 0.0),
                                    0.95,
                                )
                            preferences_memory.upsert_preference(
                                person_id,
                                pref["domain"],
                                pref["preference_type"],
                                pref["key"],
                                pref.get("value") or "",
                                confidence=float(pref.get("confidence") or 1.0),
                                importance=float(pref.get("importance") or 0.5),
                                source=pref.get("source") or "explicit",
                            )
                            _record_recent_memory_candidate(
                                person_id,
                                kind="preference",
                                target=" ".join([
                                    str(pref.get("domain") or ""),
                                    str(pref.get("preference_type") or ""),
                                    str(pref.get("key") or ""),
                                    str(pref.get("value") or ""),
                                ]),
                                label=str(pref.get("value") or pref.get("key") or "that preference"),
                            )
                            saved_preferences += 1
                    _log.info(
                        "[interaction] session-end preferences extracted=%d saved=%d for person_id=%s (%s)",
                        len(end_preferences), saved_preferences, person_id, person_name,
                    )
                except Exception as exc:
                    _log.error("session-end preference extraction error for person_id=%s: %s", person_id, exc)

                try:
                    end_interests = llm.extract_interests(
                        person_id,
                        learnable_transcript,
                        person_name=person_name,
                    )
                    saved_interests = 0
                    for interest in end_interests:
                        if (
                            interest.get("name")
                            and _extracted_memory_allowed(interest, person_id)
                        ):
                            interests_memory.upsert_interest(
                                person_id,
                                interest["name"],
                                interest.get("category") or "hobby",
                                interest.get("interest_strength") or "medium",
                                confidence=float(interest.get("confidence") or 1.0),
                                source=interest.get("source") or "explicit",
                                notes=interest.get("notes") or "",
                                associated_people=interest.get("associated_people") or "",
                                associated_stories=interest.get("associated_stories") or "",
                            )
                            _record_recent_memory_candidate(
                                person_id,
                                kind="interest",
                                target=" ".join([
                                    str(interest.get("name") or ""),
                                    str(interest.get("category") or ""),
                                    str(interest.get("notes") or ""),
                                ]),
                                label=str(interest.get("name") or "that interest"),
                            )
                            saved_interests += 1
                    _log.info(
                        "[interaction] session-end interests extracted=%d saved=%d for person_id=%s (%s)",
                        len(end_interests), saved_interests, person_id, person_name,
                    )
                except Exception as exc:
                    _log.error("session-end interest extraction error for person_id=%s: %s", person_id, exc)

            # update_visit increments visit_count, last_seen, and applies the
            # return_visit familiarity increment defined in config.
            people_memory.update_visit(person_id)

            # Extra familiarity increment for a sufficiently long conversation
            if _session_exchange_count >= config.LONG_CONVERSATION_MIN_EXCHANGES:
                people_memory.update_familiarity(
                    person_id,
                    config.FAMILIARITY_INCREMENTS.get("long_conversation", 0.02),
                )

            # P2: warmth from talking — convert this session's engaged-turn + shared-
            # laughter tally into a small, capped warmth bump for this person.
            _award_warmth_from_talking(person_id)
        except Exception as exc:
            _log.error("session end error for person_id=%s: %s", person_id, exc)

    conv_memory.clear_transcript()
    _session_forget_terms.clear()
    _session_router_control_topics.clear()
    _interest_idle_followups_spoken.clear()
    _low_memory_idle_questions_spoken.clear()
    _close_onboarding("session end")
    _recent_memory_candidates.clear()
    _clear_anonymous_speaker_slots()
    _idle_outro_spoken = False
    _lean_memory_mused_this_session = False
    _lean_mood_shared_this_session = False
    _lean_news_mentioned_this_session = False
    _last_news_story_offered = None
    _lean_impulse_spoken_times.clear()
    try:
        topic_thread.clear()
    except Exception:
        pass
    try:
        premise_memory.clear()
    except Exception:
        pass
    try:
        from intelligence import callback_engine as _cb_engine
        _cb_engine.clear_session()
        llm.clear_session()  # nostalgia / stale-fact / episodic-callback dedup
    except Exception:
        pass
    try:
        dialogue_act.clear()
    except Exception:
        pass
    try:
        user_energy.clear()
    except Exception:
        pass
    try:
        question_budget.clear()
    except Exception:
        pass
    try:
        repair_moves.clear()
    except Exception:
        pass
    try:
        end_thread.clear()
    except Exception:
        pass
    try:
        turn_completion.clear()
    except Exception:
        pass
    _session_exchange_count = 0
    _session_person_ids.clear()
    _session_person_turn_counts.clear()
    _session_warmth_signals.clear()
    _identity_prompt_until = 0.0
    _awaiting_followup_event = None
    _pending_introduction = None
    _pending_intro_followup = None
    _pending_intro_voice_capture = None
    _pending_common_first_name_identity = None
    _pending_common_first_name_introduction = None
    _pending_existing_common_first_name = None
    _pending_last_name_confirm = None
    _pending_identity_match_confirmation = None
    _pending_prompted_name_confirmation = None
    _clear_pending_memory_wipe()
    _common_first_name_prompted_this_session.clear()
    _voice_refreshed_this_session.clear()
    _face_reveal_declined.clear()
    _grief_flow_state.clear()
    _idle_plans_asked.clear()
    _recently_banned_topics.clear()
    _recent_rex_questions.clear()
    try:
        consciousness.clear_response_wait()
        consciousness.clear_engagement()
    except Exception:
        pass
    _log.info("[interaction] session ended — summary saved, transcript cleared")


def persist_session_memories_at_shutdown() -> None:
    """Run the people.db session-end persistence for the SHUTDOWN path.

    _end_session only ever fires on the idle timeout — but every real session ends
    in a spoken/GUI shutdown, so after five weeks of daily use the conversations
    table had ZERO rows: "last time you talked", nostalgia callbacks, and
    cross-session trends were all reading from an empty table. This wrapper runs
    _end_session in its shutdown profile (summary row + visit/familiarity/warmth;
    no consolidation — the rolling extractors already ran per-exchange) on a worker
    thread joined with a timeout, so a slow summary call can never stall power-off.

    Substance gate: a session needs SESSION_SUMMARY_MIN_HUMAN_TURNS human turns
    before it earns a summary row — a lone "hey Rex, shut down" visit should not
    burn an LLM call or leave a junk recap. Call BEFORE the transcript is needed
    by nothing else (it clears session state); in main._shutdown it runs after the
    diary summary, which reads the same transcript. No-op if the idle timeout
    already ended the session. Never raises.
    """
    if not bool(getattr(config, "SESSION_SUMMARY_ON_SHUTDOWN_ENABLED", True)):
        return
    try:
        transcript = conv_memory.get_session_transcript() or []
    except Exception:
        return
    if not transcript or not _session_person_ids:
        return
    rex_labels = {"rex", "dj-r3x", "djr3x", "dj r3x", "r3x", "dj-rex", "assistant"}
    human_turns = sum(
        1 for t in transcript
        if str(t.get("speaker") or "").strip().lower() not in rex_labels
    )
    min_turns = int(getattr(config, "SESSION_SUMMARY_MIN_HUMAN_TURNS", 2))
    if human_turns < min_turns:
        _log.info(
            "[interaction] shutdown session below substance gate (%d/%d human turns) "
            "— no summary row", human_turns, min_turns,
        )
        return
    timeout = float(getattr(config, "SESSION_SUMMARY_SHUTDOWN_TIMEOUT_SECS", 10.0))
    # Snapshot BEFORE the worker starts: _end_session clears _session_person_ids on
    # its way out, so reading it after the join would see an empty set exactly when
    # the worker got far enough to matter.
    persons = [int(p) for p in _session_person_ids]
    with _session_row_lock:
        _session_rows_written.clear()
    worker = threading.Thread(
        target=lambda: _end_session(include_consolidation=False),
        daemon=True,
        name="session-persist-shutdown",
    )
    worker.start()
    worker.join(timeout)
    if not worker.is_alive():
        return

    # The worker is a DAEMON and teardown continues without it, so the process
    # exits and kills it mid-flight — silently. Field 2026-08-20 20:33: the summary
    # LLM call was in flight during a network outage, the join expired, and an
    # 8-minute 20-turn conversation left NO conversations row at all. That table is
    # what "last time you talked", nostalgia callbacks and cross-session trends
    # read from, so the loss is invisible until weeks later.
    #
    # Degrade instead of vanishing: write a deterministic, LLM-free recap for every
    # person the worker did not already claim. A plain row beats no row, and the
    # next real session overwrites nothing (rows are per-session inserts).
    salvaged = _salvage_session_rows(persons, transcript)
    _log.error(
        "[interaction] shutdown session persistence still running after %.1fs — "
        "continuing teardown. %s",
        timeout,
        (f"Salvaged plain-text summaries for person_id(s) {salvaged} "
         f"({human_turns} human turns) — the LLM recap was lost."
         if salvaged else
         "All session rows were already written; nothing lost."),
    )


def _salvage_session_rows(person_ids: list[int], transcript: list[dict]) -> list[int]:
    """Write an LLM-free session row for each person that has none yet.

    Used only on the shutdown timeout path. The text is a plain recap of what was
    actually said, which is worse than the model's but is real, attributable, and
    keeps the conversations table honest about the session having happened.
    Never raises — this runs during teardown."""
    salvaged: list[int] = []
    for person_id in person_ids:
        try:
            with _session_row_lock:
                if person_id in _session_rows_written:
                    continue
                _session_rows_written.add(person_id)
            person_transcript = _filter_forgotten_transcript(transcript, person_id)
            summary = _plain_transcript_recap(person_transcript)
            if not summary:
                continue
            conv_memory.save_conversation(
                person_id, summary, emotion_tone="unknown", topics="",
            )
            salvaged.append(person_id)
        except Exception as exc:
            _log.debug("[interaction] session salvage failed for %s: %s", person_id, exc)
    return salvaged


def _plain_transcript_recap(transcript: list[dict]) -> str:
    """A deterministic recap built from the transcript alone — no model call.

    Marked so a later reader (and the trends layer) can tell it apart from a real
    summary rather than treating a mechanical join as Rex's recollection."""
    if not transcript:
        return ""
    rex_labels = {"rex", "dj-r3x", "djr3x", "dj r3x", "r3x", "dj-rex", "assistant"}
    lines: list[str] = []
    for turn in transcript:
        text = str(turn.get("text") or "").strip()
        if not text:
            continue
        speaker = str(turn.get("speaker") or "").strip()
        who = "Rex" if speaker.lower() in rex_labels else (speaker or "They")
        lines.append(f"{who}: {text}")
    if not lines:
        return ""
    cap = int(getattr(config, "SESSION_SUMMARY_SALVAGE_MAX_CHARS", 1500))
    body = " | ".join(lines)
    if len(body) > cap:
        body = body[:cap].rsplit(" | ", 1)[0] + " | ..."
    return f"[unsummarized — saved at shutdown] {body}"


