# Round-robin cursor so a rapid "tell me a joke" chain rotates through distinct
# comedic lanes instead of recycling the same DJ/bad-pilot self-own every time.
_joke_angle_cursor = 0


def _roast_targets_speaker(
    decision: action_router.ActionDecision, person_id: Optional[int]
) -> bool:
    """True when an explicit roast is aimed at the speaker themselves or their room (a
    CONSENT self-roast) rather than a named third party. `_clean_roast_target` maps
    'me'/'myself' -> 'speaker' and 'us'/'the room' -> 'room', so those are the eligible
    vision-roast targets; a named person ('roast Dave') or 'rex' is not."""
    target = str((decision.args or {}).get("target") or "").strip().lower()
    if target in ("", "speaker", "room"):
        return True
    if person_id is not None:
        try:
            from memory import people as _people
            person = _people.get_person(person_id)
            name = str((person or {}).get("name") or "").strip().lower()
            if name and (target == name or target == name.split()[0]):
                return True
        except Exception:
            pass
    return False


def _roast_visual_material(
    decision: action_router.ActionDecision, person_id: Optional[int]
) -> str:
    """For a consent self/room roast, take a cheap gpt-4o-mini look at the speaker +
    room so Rex roasts what he SEES instead of what they said. Returns "" — Rex falls
    back to the gentler VERBAL roast — for everything that must NOT get a body-roast:
    the feature off, a non-consenting third-party target, an UNIDENTIFIED speaker (no
    person_id — could be a minor the camera sees), a known minor, an unresolved age
    (fail-safe), a tender/empathetic/boundary moment, or no camera frame. Every age/
    context gate fails SAFE: lack of proof of a consenting adult → no vision body-roast."""
    if not bool(getattr(config, "ROAST_VISION_ENABLED", True)):
        return ""
    if not _roast_targets_speaker(decision, person_id):
        return ""
    # A vision BODY-roast requires a CONFIRMED adult. An unidentified speaker (no
    # person_id) or any error resolving age fails SAFE to the verbal roast — never
    # assume adult. The camera can see a minor we have no record for.
    if person_id is None:
        return ""
    try:
        if profile_questions.person_is_minor(person_id):
            return ""
    except Exception:
        return ""
    # Don't body-roast someone who is in a tender / empathetic / boundary moment, even
    # on an explicit "roast me" — fall back to the verbal roast. The performance roast
    # path skips the social-frame governor, so this contextual gate lives here for the
    # loosened roast (the empathy mode is the recent-affect signal already in hand).
    try:
        empathy_mode = (empathy.get_delivery_overrides(person_id) or {}).get("mode") or "default"
        if empathy_mode not in ("default", ""):
            return ""
    except Exception:
        pass
    try:
        from vision import camera as camera_mod
        from vision import scene as vision_scene
        from vision import face as face_mod
        frame = camera_mod.get_frame()
        if frame is None:
            return ""
        try:
            names = face_mod.visible_known_names() or None
        except Exception:
            names = None
        material = vision_scene.describe_for_roast(frame, known_names=names)
        if material:
            _log.info("[roast] vision material: %s", material)
        return material or ""
    except Exception as exc:
        _log.debug("[roast] visual material failed: %s", exc)
        return ""


# ── Impersonation (performance.impersonate + live voice capture) ──────────────

def _impersonation_capture_fresh(ctx: Optional[dict]) -> bool:
    if not ctx:
        return False
    ttl = float(getattr(config, "IMPERSONATION_CAPTURE_TIMEOUT_SECS", 45.0))
    return (time.monotonic() - float(ctx.get("asked_at") or 0.0)) <= ttl


def _impersonation_tool_target(
    decision: "action_router.ActionDecision", text: str
) -> str:
    """Who to impersonate for a TOOL-ROUTED request: the model decides THAT this is
    an impersonation, the utterance decides WHO.

    The reply call carries the whole transcript, and on 2026-08-14 it answered
    "Impersonate Barack Obama." with target='speaker' — the argument it had used one
    turn earlier — so Rex performed the speaker instead. When the utterance names a
    target outright, that name wins; the model's argument only stands for the softer
    phrasings the classifier does not read ("talk like a pirate", "do him").

    _explicit_impersonation_takeover already claims the named-target turns before
    the reply call happens, so this is the backstop for the paths that skip it:
    offline, the kill switch, and a decision that reaches the dispatcher some other
    way."""
    model_target = _router_arg_text(decision, "target", "person", "who", "name")
    said = _router_arg_text(action_router.classify_explicit_impersonation(text), "target")
    if not said or said.strip().lower() == model_target.strip().lower():
        return model_target
    _log.info(
        "[impersonation] tool target %r overridden by the utterance: %r",
        model_target, said,
    )
    return said


def _handle_router_impersonation(
    decision: "action_router.ActionDecision",
    text: str,
    person_id: Optional[int],
    person_name: Optional[str],
    target: str,
) -> Optional[str]:
    """Execute performance.impersonate: resolve who to imitate, then either perform
    the parody in the cloned voice, open a live voice-capture slot, or refuse in
    character. Speaks internally; returns the spoken text for the caller to log."""
    global _pending_impersonation_capture, _pending_impersonation_target
    try:
        from features import impersonation
    except Exception as exc:
        _log.warning("[impersonation] module import failed: %s", exc)
        return None

    # Nobody named — "Impersonate." on its own, usually a sentence cut short.
    # Ask who and hold a slot for the answer, rather than letting the turn fall
    # through to the LLM (which answered a bare "impersonate" by declining).
    if not (target or "").strip():
        _pending_impersonation_target = {
            "person_id": person_id,
            "person_name": person_name,
            "asked_at": time.monotonic(),
        }
        ask = impersonation.who_line()
        _log.info("[impersonation] no target named — opened who-slot")
        _speak_blocking(ask, emotion="curious", pre_beat_ms=100, log_text=False)
        return ask

    resolution = impersonation.resolve_target(target, person_id, person_name)

    if resolution.kind == "refuse":
        _speak_blocking(resolution.line, emotion="amused", log_text=False)
        return resolution.line

    if resolution.kind == "capture":
        _pending_impersonation_capture = {
            "person_id": resolution.person_id,
            "name": resolution.name,
            "expected_text": resolution.line,
            "is_self": resolution.is_self,
            "asked_at": time.monotonic(),
        }
        _log.info(
            "[impersonation] opened capture slot person_id=%s name=%r",
            resolution.person_id, resolution.name,
        )
        # Speak the FRAMED ask ("repeat after me: <phrase>") — the bare phrase gave
        # the guest no clue what to do (field 2026-07-23). expected_text stays the
        # phrase alone so the recitation match compares against the right words.
        prompt = impersonation.capture_prompt(resolution.name, resolution.line)
        _speak_blocking(prompt, emotion="curious", pre_beat_ms=100, log_text=False)
        return prompt

    # perform
    _log.info(
        "[impersonation] performing person_id=%s name=%r label=%s",
        resolution.person_id, resolution.name,
        getattr(resolution.ref, "label", "?"),
    )
    return impersonation.perform(
        resolution.ref, resolution.name, resolution.person_id, is_self=resolution.is_self
    )


def _impersonation_target_fresh(ctx: Optional[dict]) -> bool:
    if not ctx:
        return False
    ttl = float(getattr(config, "IMPERSONATION_WHO_TIMEOUT_SECS", 30.0))
    return (time.monotonic() - float(ctx.get("asked_at") or 0.0)) <= ttl


def _handle_impersonation_target_prompt(text: str) -> Optional[tuple[str, bool]]:
    """Resolve the answer to "impersonate who?".

    Returns (spoken_text, already_spoken) when this turn was the answer, else
    None. The whole utterance is the target — the reply to "who?" is a name
    ("Obama", "me"), not a fresh command — so it is handed to resolve_target
    verbatim after stripping a leading verb the user may have repeated.
    """
    global _pending_impersonation_target
    ctx = _pending_impersonation_target
    if ctx is None:
        return None
    if not _impersonation_target_fresh(ctx):
        _pending_impersonation_target = None
        return None

    try:
        from features import impersonation
    except Exception:
        _pending_impersonation_target = None
        return None

    said = " ".join((text or "").strip().split())
    if not said:
        return None
    if impersonation.sounds_like_cancel(said):
        _pending_impersonation_target = None
        line = "Fine. Another time."
        _speak_blocking(line, emotion="amused", log_text=False)
        return (line, True)

    # "impersonate Obama" as the ANSWER — drop the repeated verb, keep the name.
    target = re.sub(
        r"^(?:(?:do|give\s+(?:me|us)|perform)\s+(?:an?\s+|your\s+(?:best\s+)?)?"
        r"(?:impersonation|impression)\s+of\s+"
        # ASR inflections of the same audio — see action_router's verb list.
        r"|(?:impersonate|impersonates|impersonating"
        r"|imitate|imitates|imitating|mimic|mimics|mimicking)\s+)",
        "", said, flags=re.IGNORECASE,
    ).strip()
    target = re.sub(r"[.!?,;:]+$", "", target).strip() or said
    _pending_impersonation_target = None
    _log.info("[impersonation] who-slot answered with %r", target)

    decision = action_router.ActionDecision(
        action="performance.impersonate", confidence=0.95,
        args={"target": target}, reason="answer to impersonate-who prompt",
    )
    spoken = _handle_router_impersonation(
        decision, text, ctx.get("person_id"), ctx.get("person_name"), target,
    )
    if spoken is None:
        return None
    return (spoken, True)


def _handle_impersonation_capture(
    text: str,
    audio_array: Optional[np.ndarray],
    person_id: Optional[int],
    raw_best_id: Optional[int],
    speaker_score: float,
) -> Optional[tuple[str, bool]]:
    """Consume a pending impersonation voice-capture. Returns (line, already_spoken)
    or None to fall through the pending-slot ladder. already_spoken=True means the
    parody was already voiced by perform() and the caller should only LOG the text.
    """
    global _pending_impersonation_capture
    ctx = _pending_impersonation_capture
    if ctx is None:
        return None
    if not _impersonation_capture_fresh(ctx):
        _pending_impersonation_capture = None
        return None

    try:
        from features import impersonation
    except Exception:
        _pending_impersonation_capture = None
        return None

    if impersonation.sounds_like_cancel(text):
        _pending_impersonation_capture = None
        return ("No worries — no impression today.", False)

    # RECITATION MATCH: the turn's transcript closely matches the exact phrase Rex
    # asked the target to repeat. Whoever is speaking IS performing the capture —
    # identity attribution must not veto it (field 2026-07-23: the guest's reply was
    # misattributed to a junk voiceprint twin, the strict person gate skipped it,
    # and the slot silently expired). The phrase is a fixed nursery line Rex just
    # requested; a bystander coincidentally reciting it is not a real risk.
    expected_norm = _normalize_echo_text(ctx.get("expected_text"))
    text_norm = _normalize_echo_text(text)
    recites = bool(
        expected_norm and text_norm
        and difflib.SequenceMatcher(None, text_norm, expected_norm).ratio()
        >= float(getattr(config, "IMPERSONATION_CAPTURE_MATCH_RATIO", 0.6))
    )

    # Otherwise the clip must come from the target, not a bystander: if the live
    # turn confidently resolves to someone ELSE, leave the slot for the real
    # target. An ANONYMOUS slot (person_id=None — a guest Rex doesn't know) is the
    # mirror image: only an UNKNOWN voice may fill it; a known person speaking
    # in the gap must not have their voice captured as the guest's.
    expected_id = ctx.get("person_id")
    if not recites:
        if expected_id is not None and person_id is not None and person_id != expected_id:
            return None
        if expected_id is None and person_id is not None:
            return None

    min_secs = float(getattr(config, "IMPERSONATION_CAPTURE_MIN_SECS", 4.0))
    if audio_array is None or _audio_duration_secs(audio_array) < min_secs:
        ctx["asked_at"] = time.monotonic()
        first = _first_name_or(ctx.get("name"), "hey")
        return (
            f"{first}, that was a blink — give me one more full sentence so I have "
            "something to work with.",
            False,
        )

    ref = impersonation.save_person_capture(expected_id, audio_array, text)
    if ref is None:
        ctx["asked_at"] = time.monotonic()
        return ("My voice scanner hiccupped — run that line by me one more time?", False)

    name = ctx.get("name") or ("my mystery guest" if expected_id is None else "you")
    is_self = bool(ctx.get("is_self"))
    _pending_impersonation_capture = None
    _log.info("[impersonation] captured reference for person_id=%s — performing", expected_id)
    parody = impersonation.perform(ref, name, expected_id, is_self=is_self)
    return (parody, True)


# ── Scene snapshot ("take a picture / remember this scene") ──────────────────
# vision.snapshot is privacy-gated: storing a scene memory always requires an
# explicit spoken confirmation. The offer arms a short-lived pending slot
# (mirroring the impersonation capture slot); the next user turn resolves it —
# yes → capture + caption + episodic record, no → nothing saved, anything
# else → the slot drops silently and the turn proceeds as normal conversation.

_SCENE_SNAPSHOT_YES_RE = re.compile(
    r"^\s*(?:yes|yeah|yep|yup|sure|okay|ok|please|absolutely|"
    r"do it|go ahead|go for it)\b|"
    r"\b(?:remember|save|store|keep)\s+(?:this|that|the)\s+"
    r"(?:scene|view|room|picture|image|moment)\b",
    re.IGNORECASE,
)
_SCENE_SNAPSHOT_NO_RE = re.compile(
    r"^\s*(?:no|nope|nah|naw|never\s*mind|nevermind|don'?t|do\s+not|"
    r"cancel|skip|forget)\b",
    re.IGNORECASE,
)
# Targeted-forget confirmation. Anchored at the START and deliberately narrow:
# this is the last thing between an utterance and an irreversible multi-table
# delete, so anything that is not a clear yes lets the offer lapse. "forget it" is
# NOT a yes here — it is the single most likely way to mean the opposite.
_SPECIFIC_FORGET_YES_RE = re.compile(
    r"^\s*(?:yes|yeah|yep|yup|sure|okay|ok|correct|confirm(?:ed|\s+it)?|"
    r"do\s+it|go\s+ahead|delete\s+it|that'?s\s+right)\b",
    re.IGNORECASE,
)
_SPECIFIC_FORGET_NO_RE = re.compile(
    r"^\s*(?:no|nope|nah|naw|never\s*mind|nevermind|don'?t|do\s+not|cancel|"
    r"stop|wait|hold\s+on|keep\s+it|leave\s+it)\b",
    re.IGNORECASE,
)


def _specific_forget_confirm_timeout() -> float:
    return float(getattr(config, "SPECIFIC_FORGET_CONFIRM_TIMEOUT_SECS", 30.0))


def _offer_specific_forget(person_id: Optional[int], target: str) -> str:
    """Arm the targeted-forget confirmation and return the spoken offer line.

    memory.forget_specific is a DELETE across person_facts, person_events,
    person_emotional_events, conversations, person_qa, person_preferences,
    person_interests, person_callback_material, person_relationships and the rex.db
    diary, matched by SUBSTRING (memory.forgetting.text_matches_terms is a plain
    `term in haystack`), and until 2026-08-13 it ran with no confirmation of any
    kind. memory.forget_person has had an armed confirmation since it shipped; a
    one-topic delete is smaller in scope but identical in kind — irreversible, no
    undo — and the measured blast radius says the scope claim is not even reliable:
    "Forget it, I'll do it myself." yielded the search term "i'll", which
    substring-matches nearly every stored conversation summary.

    Deliberately NOT routed through _arm_memory_wipe_confirmation. That flow owns
    person/all wipes, demands a fixed pass phrase plus FULL_MEMORY_WIPE_ACCESS_CODE,
    and is the last line for the most destructive thing Rex can do; widening it to
    take a third scope would weaken it. This is its own lighter slot, in the shape
    _offer_scene_snapshot already uses. Nothing about the wipe flow changes.
    """
    global _pending_specific_forget
    _pending_specific_forget = {
        "person_id": person_id,
        "target": (target or "").strip(),
        "asked_at": time.monotonic(),
    }
    try:
        consciousness.begin_response_wait(_specific_forget_confirm_timeout())
    except Exception:
        pass
    _log.info(
        "[memory] targeted-forget confirmation offered person_id=%s target=%r",
        person_id, target,
    )
    said = (target or "").strip()
    if re.match(r"(?i)^my\b", said):
        said = re.sub(r"(?i)^my\b", "your", said, count=1)
    return (
        f"Before I do that — I'd be deleting everything I have about {said}: "
        "facts, events, conversations, the lot. There's no undo. Say yes and it's gone."
    )


def _handle_specific_forget_confirmation(
    text: str, person_id: Optional[int]
) -> Optional[str]:
    """Consume a pending targeted-forget confirmation, or let the offer lapse.

    Same shape as _handle_scene_snapshot_confirmation: an unrelated turn drops the
    slot quietly and falls through to conversation. A delete never happens on
    silence, on a timeout, or on anything ambiguous — only on an explicit yes from
    the identity that asked.
    """
    global _pending_specific_forget
    ctx = _pending_specific_forget
    if ctx is None:
        return None
    if (time.monotonic() - float(ctx.get("asked_at") or 0.0)
            > _specific_forget_confirm_timeout()):
        _pending_specific_forget = None
        _log.info("[memory] targeted-forget confirmation expired")
        return None
    cleaned = (text or "").strip()
    if _SPECIFIC_FORGET_NO_RE.match(cleaned):
        _pending_specific_forget = None
        _log.info("[memory] targeted forget declined: %r", text)
        return "Kept it, then. Nothing deleted."
    if _SPECIFIC_FORGET_YES_RE.match(cleaned):
        pid = ctx.get("person_id")
        # Same rule the wipe flow enforces: the confirmation has to come from the
        # identity that asked. A second person in the room saying "yes" must not
        # delete this person's memories.
        if _confirmation_speaker_mismatch(
            {"person_id": pid, "requester_id": pid}, person_id
        ):
            _pending_specific_forget = None
            _log.info("[memory] targeted forget rejected: speaker mismatch")
            return (
                "Confirmation rejected. That did not come from the same identity. "
                "Nothing deleted."
            )
        _pending_specific_forget = None
        return _execute_command(
            command_parser.CommandMatch(
                "forget_specific", "confirmed", {"target": ctx.get("target") or ""}
            ),
            pid,
            _tool_router_person_name(pid),
            text,
        )
    _pending_specific_forget = None
    _log.info("[memory] targeted-forget offer lapsed (unrelated turn): %r", text)
    return None


def _scene_snapshot_confirm_timeout() -> float:
    return float(getattr(config, "SCENE_SNAPSHOT_CONFIRM_TIMEOUT_SECS", 30.0))


def _offer_scene_snapshot(person_id: Optional[int]) -> str:
    """Arm the pending confirmation slot and return the spoken offer line."""
    global _pending_scene_snapshot
    _pending_scene_snapshot = {
        "person_id": person_id,
        "asked_at": time.monotonic(),
    }
    try:
        consciousness.begin_response_wait(_scene_snapshot_confirm_timeout())
    except Exception:
        pass
    _log.info("[scene_snapshot] confirmation offered (person_id=%s)", person_id)
    return (
        "I can take a look, but I won't store a scene memory without explicit "
        "confirmation. Say yes, remember this scene if you want that."
    )


def _execute_scene_snapshot(person_id: Optional[int]) -> str:
    """Capture the current view, caption it, store it as a scene episode.
    Always returns a spoken line; failures are honest, never silent."""
    frame = None
    try:
        from vision import camera
        frame = camera.capture_current_gaze()
        if frame is None:
            frame = camera.get_frame()
    except Exception as exc:
        _log.debug("[scene_snapshot] frame capture failed: %s", exc)
    if frame is None:
        return "My camera's giving me static right now — no scene saved."

    known: list[str] = []
    try:
        from vision import face
        known = face.visible_known_names()
    except Exception:
        known = []

    caption = ""
    try:
        from vision import scene as scene_mod
        caption = scene_mod.quick_caption(frame, known_people=known)
    except Exception as exc:
        _log.warning("[scene_snapshot] caption failed: %s", exc)
    if not caption:
        return (
            "I looked, but my vision processor came back empty-handed — "
            "nothing saved. Try me again in a beat."
        )

    person_name = _tool_router_person_name(person_id)
    try:
        from memory import episodes
        episodes.record_scene(
            f"I was asked to remember this scene: {caption}",
            detail={"source": "scene_snapshot", "caption": caption},
            person_id=person_id,
            person_name=person_name,
        )
    except Exception as exc:
        _log.error("[scene_snapshot] episodic save failed: %s", exc)
        return "I saw it, but my memory banks fumbled the save. Run that by me again."
    _log.info(
        "[scene_snapshot] saved (person=%s): %r", person_name or "none", caption
    )
    return f"Locked in. For the record: {caption}"


def _handle_scene_snapshot_confirmation(
    text: str, person_id: Optional[int]
) -> Optional[str]:
    """Consume a pending scene-snapshot confirmation. Returns the line to speak,
    or None when no fresh slot exists / the turn isn't about the offer (the
    slot drops and the turn falls through as normal conversation)."""
    global _pending_scene_snapshot
    ctx = _pending_scene_snapshot
    if ctx is None:
        return None
    if (time.monotonic() - float(ctx.get("asked_at") or 0.0)
            > _scene_snapshot_confirm_timeout()):
        _pending_scene_snapshot = None
        return None
    cleaned = (text or "").strip()
    if _SCENE_SNAPSHOT_NO_RE.match(cleaned):
        _pending_scene_snapshot = None
        _log.info("[scene_snapshot] declined: %r", text)
        return "No worries — nothing saved."
    if _SCENE_SNAPSHOT_YES_RE.search(cleaned):
        _pending_scene_snapshot = None
        pid = person_id if person_id is not None else ctx.get("person_id")
        return _execute_scene_snapshot(pid)
    # They said something unrelated — the offer lapses quietly.
    _pending_scene_snapshot = None
    _log.info("[scene_snapshot] offer lapsed (unrelated turn): %r", text)
    return None


def _settle_response_wait_after_action() -> None:
    """Turn-epilogue response-wait handling for executed actions.

    Normally an executed command clears the response wait (nothing is owed). But
    when the impersonation capture slot is open, Rex has just ASKED the user to
    repeat a line — he is waiting, not done. Arm the wait for the capture window
    so the whole proactive family (smile reactions, presence beats, env snark,
    musings) holds off instead of barging in — live-logged 2026-07-19 21:20: a
    canned smile-reaction line played ONE second after 'Repeat after me…' because
    the epilogue cleared the wait and the camera caught the user grinning."""
    try:
        if _pending_impersonation_capture is not None:
            consciousness.begin_response_wait(
                float(getattr(config, "IMPERSONATION_CAPTURE_TIMEOUT_SECS", 45.0))
            )
        elif _pending_impersonation_target is not None:
            # Rex just asked "impersonate who?" — same rule: he is waiting on a
            # name, so proactive beats must not talk over the answer.
            consciousness.begin_response_wait(
                float(getattr(config, "IMPERSONATION_WHO_TIMEOUT_SECS", 30.0))
            )
        elif _pending_scene_snapshot is not None:
            # Rex just asked "say yes, remember this scene" — hold proactive
            # beats for the confirmation window, same rule as the capture slot.
            consciousness.begin_response_wait(_scene_snapshot_confirm_timeout())
        else:
            consciousness.clear_response_wait()
    except Exception:
        pass


def _explicit_impersonation_takeover(
    text: str,
    *,
    person_id: Optional[int],
    person_name: Optional[str],
    router_audit: Optional["_RouterDecisionAudit"] = None,
) -> Optional[str]:
    """Explicit impersonation request, run BEFORE the dialogue-act gate.

    A deterministic "impersonate me" / "do an impression of X" is a COMMAND, not
    an answer to Rex's last question — so it must execute even inside an
    answer_to_rex frame, which sets skip_action_router and bypasses the whole fast
    lane. Same treatment as _explicit_motion_takeover (same failure mode,
    live-logged twice: 2026-06-23 for motion, 2026-07-19 21:09 for impersonation —
    Rex asked "what's up?", the user said "impersonate me", and the turn was
    swallowed as conversation). Returns the spoken line, or None when the text is
    not an explicit impersonation request or the gate blocks it."""
    decision = action_router.classify_explicit_impersonation(text)
    if decision is None:
        return None
    target = _router_arg_text(decision, "target")
    if action_router.tool_router_owns(decision.action) and not target:
        # performance.impersonate went live on the tool router 2026-08-13, and this
        # lane stood down for it completely. It stands down only for the NO-TARGET
        # case now — a bare "Impersonate." where the model can read a subject out of
        # the conversation that this classifier cannot see.
        #
        # When the utterance NAMES someone, the deterministic lane keeps the claim,
        # for the same reason game.stop keeps it mid-game
        # (action_router.tool_router_owns_turn): the reply call is free to answer in
        # prose, and when it does the tool is dropped entirely
        # (lean_brain: "model emitted prose AND tool -- prose wins"). Field
        # 2026-08-14, eight explicit requests in one sitting: the reply call routed
        # 3, answered 4 by doing the impression itself IN REX'S OWN VOICE, and on
        # "Impersonate Barack Obama." called the tool with target='speaker' — the
        # previous turn's argument — so Rex performed BRET, from Bret's memory, in
        # Bret's cloned voice. The shadow router, asked to route that same utterance
        # on its own, returned target='Barack Obama' every single time. Routing an
        # unambiguous imperative through a persona-loaded reply call was the whole
        # bug; softer phrasings ("talk like a pirate") match no pattern here and
        # still belong to the model.
        _log.info(
            "[impersonation] no target named — handed to the tool router text=%r",
            text,
        )
        return None
    _router_audit_note_decision(router_audit, decision)
    if not _router_decision_executable(decision, text=text):
        return None
    _log.info(
        "[impersonation] explicit request (pre-dialogue-gate) person_id=%s target=%r",
        person_id, target,
    )
    result = _handle_router_impersonation(decision, text, person_id, person_name, target)
    if result is not None:
        _router_audit_note_fast_local_action(
            router_audit, decision.action, reason=decision.reason
        )
    return result


def _handle_router_performance_action(
    decision: action_router.ActionDecision,
    text: str,
    person_id: Optional[int],
    router_audit: Optional[_RouterDecisionAudit] = None,
) -> Optional[str]:
    if decision.action not in _PLAN_ROUTER_ACTIONS:
        _router_audit_note_result(
            router_audit,
            handler_error="unsupported_performance_action",
        )
        return None
    joke_rotation: Optional[int] = None
    joke_avoid_directive = ""
    if decision.action == "humor.tell_joke":
        global _joke_angle_cursor
        joke_rotation = _joke_angle_cursor
        _joke_angle_cursor += 1
        # Steer away from premises Rex has already spent this conversation (shared
        # with the main reply path so a joke and a normal line can't echo).
        joke_avoid_directive = premise_memory.build_avoid_directive()
    # "Roast me" → roast what Rex SEES: a cheap gpt-4o-mini look at the consenting
    # speaker + room (self/room roasts of a non-minor only; "" otherwise → verbal roast).
    visual_material = ""
    if decision.action == "humor.roast":
        visual_material = _roast_visual_material(decision, person_id)
    plan = performance_plan.plan_for_action(
        decision.action,
        user_text=text,
        args=decision.args,
        joke_rotation=joke_rotation,
        joke_avoid_directive=joke_avoid_directive,
        visual_material=visual_material,
    )
    if plan is None:
        _router_audit_note_result(
            router_audit,
            handler_error="missing_performance_plan",
        )
        return None
    output = performance_output.execute_plan(
        plan,
        generate_text=lambda prompt: llm.get_response(prompt, person_id),
        speak_text=_speak_blocking,
        play_body_beat=_play_performance_body_beat,
        play_landing_body_beat=_fire_post_line_body_beat,
        clean_text=llm.clean_response_text,
        # Show the line in the GUI the instant it's generated (read-along), before the
        # blocking speak — otherwise the caller only logs it AFTER playback finishes.
        # The caller's later conv_log.log_rex of the returned text dedupes against this.
        on_text=conv_log.log_rex,
    )
    if decision.action == "humor.tell_joke" and output.text:
        # Record the delivered joke so the next joke (and the next reply) avoid it.
        premise_memory.note_line(output.text)
    if decision.action == "humor.roast" and output.completed and output.text:
        # Rex just landed a deliberate roast — let him bask. 'smug' resolves to the
        # 'proud' chin-up posture via body_mood's alias (the affective mirror of the
        # compliment -> proud reaction) and decays over the mood TTL.
        _set_body_mood("smug", source="roast_landed")
    if output.generation_failed:
        _log.debug("performance action generation failed; used fallback text")
    if output.body_beat_failed:
        _log.debug("performance action body beat failed; speech still delivered")
    result_errors = []
    if output.generation_failed:
        result_errors.append("generation_failed")
    if output.body_beat_failed:
        result_errors.append("body_beat_failed")
    _router_audit_note_result(
        router_audit,
        completed=output.completed,
        handler_error=",".join(result_errors) if result_errors else None,
        spoken_text=output.text,
    )
    _log.info(
        "[action_router] executed %s person_id=%s delivery=%s memory_policy=%s text=%r",
        output.action,
        person_id,
        output.delivery_style,
        output.memory_policy,
        text,
    )
    return output.text


def _negation_is_answer(repair_move: Optional[dict], dialogue_decision) -> bool:
    """A bare "no/nope" that ANSWERS a question Rex just asked is CONTENT, not a
    conversational correction — the dialogue act already bound the turn as
    answer_to_rex. Without this, "What's one gadget that earns its keep?" → "nope"
    fired the canned repair line ("Fair enough — let me reset and try that
    again."), a total non-sequitur (live-logged 2026-07-06-22-17). The reply path
    should riff on the refusal instead."""
    return bool(
        repair_move
        and repair_move.get("kind") == "bare_negation"
        and dialogue_decision is not None
        and getattr(dialogue_decision, "label", "") == "answer_to_rex"
    )


def _router_repair_move(
    text: str,
    decision: action_router.ActionDecision,
) -> dict:
    repair = repair_moves.detect(text)
    if repair is not None:
        return repair
    repair_kind = (
        _router_arg_text(decision, "repair_kind", "kind", "type")
        or "misunderstood"
    )
    correction = _router_arg_text(decision, "correction", "corrected_text", "clarification")
    return {
        "kind": repair_kind,
        "severity": "medium",
        "correction": correction,
        "user_text": text,
    }


def _handle_router_identity_name_correction(
    text: str,
    decision: action_router.ActionDecision,
    person_id: Optional[int],
    person_name: Optional[str],
) -> str:
    """Execute a current-speaker name correction, or ask for the missing name."""
    response = _handle_name_update_request(text, person_id, person_name)
    if response:
        return response

    new_name = _normalize_name(
        _router_arg_text(decision, "name", "new_name", "person_name")
    )
    if new_name:
        response = _handle_name_update_request(
            f"call me {new_name}",
            person_id,
            person_name,
        )
        if response:
            return response

    resp = repair_moves.add_better_luck_line(
        "I caught the identity correction, but I need the right name."
    )
    _speak_blocking(resp, emotion="neutral")
    return resp


# motion.route is deliberately ABSENT from _MOTION_ACTIONS: every dispatcher that
# tests this set hands the decision to _handle_router_motion_action, which has no
# route arm and returns None — the aa9acce failure, where Rex SAYS the command
# landed and the wheels never move. Routes get their own branch (_handle_motion_route).
_MOTION_ACTIONS = {"motion.turn", "motion.move", "motion.come", "motion.stop", "motion.arc"}
# Drive intents that need a physically-connected base. Bare "stop"/"halt" (motion.stop) is
# deliberately excluded: with no base there is nothing to halt, and the word must stay free
# to mean stop-music / stop-game.
_MOTION_DRIVE_ACTIONS = {"motion.turn", "motion.move", "motion.come", "motion.arc",
                         "motion.route", "motion.face"}
# Bare standalone "stop" only counts as a drive-base stop while the base is moving.
_BARE_MOTION_STOP_RE = re.compile(
    r"^\s*(?:stop|halt|freeze|whoa|hold on|hold up|wait|stop it)\s*[.!]*\s*$", re.I
)
# Stop imperatives scanned PER SENTENCE while the base is moving or a come-here
# errand is running. A real field "stop" rarely arrives as a clean bare token: it
# rides inside a noisy multi-sentence segment ("... Go. Stop. Stop looking for me.
# Just stop.") that the whole-utterance regex can't match and the router shrugs
# off as conversation — Rex SAID "Stopping." and kept driving (field 2026-08-11).
# Only consulted while an errand owns the base, so conversational "stop" ("I
# can't stop laughing") stays free — and those don't full-match a fragment anyway.
_MOTION_STOP_FRAGMENT_RE = re.compile(
    r"^\s*(?:please\s+|just\s+|no[,\s]+)*"
    r"(?:stop|halt|freeze|"
    r"stay(?:\s+(?:there|put|right\s+there))?|"
    r"don'?t\s+move|"
    r"(?:stop|quit)\s+(?:moving|driving|turning|spinning|circling|"
    r"looking|searching|hunting|chasing)"
    r"(?:\s+(?:for|at|around|after)\s+me)?"
    r")\s*[.!]*\s*$",
    re.IGNORECASE,
)


def _errand_stop_demanded(text: str) -> bool:
    """True when any sentence of the utterance is a stop imperative. Callers gate
    this on an active drive (base moving / come-here errand) before acting."""
    cleaned = (text or "").strip()
    if not cleaned:
        return False
    if _BARE_MOTION_STOP_RE.match(cleaned):
        return True
    return any(
        _MOTION_STOP_FRAGMENT_RE.match(frag)
        for frag in re.split(r"[.!?;,]+", cleaned)
        if frag.strip()
    )

_motion_continuation_lock = threading.Lock()
_motion_continuation: Optional[dict[str, Any]] = None


def _clear_motion_continuation() -> None:
    global _motion_continuation
    with _motion_continuation_lock:
        _motion_continuation = None


def _remember_motion_continuation(decision: action_router.ActionDecision) -> None:
    """Remember only a successfully issued repeatable maneuver."""
    if decision.action not in {"motion.turn", "motion.move", "motion.arc"}:
        return
    global _motion_continuation
    remembered = action_router.ActionDecision(
        action=decision.action,
        confidence=decision.confidence,
        args=dict(decision.args or {}),
        reason=decision.reason,
    )
    with _motion_continuation_lock:
        _motion_continuation = {"decision": remembered, "at": time.monotonic()}


def _resolve_motion_continuation(text: str) -> Optional[action_router.ActionDecision]:
    global _motion_continuation
    ttl = float(getattr(config, "MOTION_CONTINUATION_TTL_SECS", 45.0))
    with _motion_continuation_lock:
        context = _motion_continuation
        if context is None:
            return None
        if time.monotonic() - float(context.get("at") or 0.0) > ttl:
            _motion_continuation = None
            return None
        previous = context.get("decision")
    return action_router.classify_motion_continuation(
        text,
        previous,
        small_turn_deg=float(getattr(config, "MOTION_CONTINUATION_SMALL_TURN_DEG", 15.0)),
        small_move_m=float(getattr(config, "MOTION_CONTINUATION_SMALL_MOVE_M", 0.15)),
    )


def _cancel_motion_sequence(reason: str, *, stop_base: bool = False) -> None:
    try:
        from intelligence import motion_sequence
        motion_sequence.cancel(reason, stop_base=stop_base)
    except Exception:
        pass


def _start_motion_sequence(decisions: list[action_router.ActionDecision]) -> bool:
    try:
        from intelligence import motion_sequence
        return motion_sequence.start(decisions, on_issued=_remember_motion_continuation)
    except Exception as exc:
        _log.warning("[motion_sequence] failed to start: %s", exc)
        return False


# The operator telling Rex the charge cable's state ("you're unplugged" /
# "I plugged you in") — the escape hatch for charger states the battery gauge
# cannot measure (a finished supply at ~0 mA on a full pack reads identical to
# unplugged; field 2026-08-07, the flinch-on-the-cord rollback). Deterministic
# captures like the drive-rule declarations: standing statements about the
# hardware, never routed to the LLM.
_CHG_UNPLUGGED_RE = re.compile(
    r"\b(?:you(?:'re| are)\s+(?:unplugged|off\s+the\s+(?:charger|cord|cable))|"
    r"i(?:'ve| have)?\s+(?:just\s+)?unplugged\s+you|"
    r"(?:the\s+)?(?:cable|cord|charger)(?:'s| is)\s+"
    r"(?:off|out|unplugged|disconnected))\b",
    re.IGNORECASE,
)
_CHG_PLUGGED_RE = re.compile(
    r"\b(?:you(?:'re| are)\s+(?:plugged\s+(?:in|back\s+in)|"
    r"(?:back\s+)?on\s+the\s+(?:charger|cord)|charging\s+now)|"
    r"i(?:'ve| have)?\s+(?:just\s+)?plugged\s+you\s+(?:back\s+)?in)\b",
    re.IGNORECASE,
)


def _charging_declaration(text: str) -> "Optional[bool]":
    """True = they say he's plugged in, False = unplugged, None = not about that."""
    cleaned = (text or "").strip()
    if not cleaned:
        return None
    if _CHG_UNPLUGGED_RE.search(cleaned):
        return False
    if _CHG_PLUGGED_RE.search(cleaned):
        return True
    return None


def _handle_charging_declaration(plugged: bool) -> str:
    """Relay the operator's word to the firmware; return the spoken ack."""
    if not motion_controller.available():
        return "Noted, but my drive base isn't even connected right now."
    if not plugged:
        # If the meter can SEE charge current, the cable is demonstrably still
        # attached — say so instead of pretending to unlock (the firmware would
        # refuse the assert anyway).
        try:
            snapshot = motion_controller.status() or {}
            ma = float(snapshot.get("batt_ma"))
            if ma <= -float(getattr(config, "MOTION_CHARGE_CURRENT_VISIBLE_MA", 250.0)):
                return ("My meter says current's still flowing into me — "
                        "check the cable before I trust my wheels.")
        except (TypeError, ValueError):
            pass
        motion_controller.charge_assert(False)
        return "Copy, cable's off — wheels back online."
    motion_controller.charge_assert(True)
    return "Copy, I'm on the cord — wheels locked."


def _MOTION_DEFAULT_TURN_DEG() -> float:
    try:
        return float(getattr(config, "MOTION_DEFAULT_TURN_DEG", 90.0))
    except (TypeError, ValueError):
        return 90.0


def _MOTION_DEFAULT_MOVE_DIST_M() -> float:
    try:
        return float(getattr(config, "MOTION_DEFAULT_MOVE_DIST_M", 0.30))
    except (TypeError, ValueError):
        return 0.30


def _no_drive_room_decline_line() -> Optional[str]:
    """The spoken decline for a room the owner told Rex not to drive in, or None.

    "this room has carpet" / "don't move in the workshop" — they said not to move AT
    ALL in there, so a SPOKEN command is declined too, with the way out stated: the
    rule was set by voice and has to be liftable by voice.

    Pulled out of _handle_router_motion_action so a multi-step route is declined by
    the same rule and in the same words. It wasn't, before: the regex route lane
    checked the charger but never this, so "turn left then move forward" drove in a
    room where "turn left" alone was refused.
    """
    try:
        from intelligence import motion_agency
        no_drive = motion_agency.no_drive_room()
    except Exception:
        return None
    if no_drive is None:
        return None
    room, why = no_drive
    because = " — carpet eats my wheels" if why == "carpet" else ""
    return (f"You told me not to drive in the {room}{because}. "
            "Say \"you can drive in here\" if that's changed.")


def _handle_router_motion_action(
    decision: Optional[action_router.ActionDecision],
    requester_person_id: Optional[int] = None,
) -> Optional[str]:
    """Drive the base for a motion.* decision; returns a short spoken line or None.

    Fire-and-forget: the command is sent and a brief confirmation returned; the
    ESP32 reports completion (`done`) asynchronously. No-op (None) when no base is
    connected or the command was suppressed (paused / manual override)."""
    if decision is None or not motion_controller.available():
        return None
    action = decision.action
    args = decision.args or {}

    if action != "motion.stop" and motion_controller.charging():
        return "I'm plugged in and charging. Wheels stay locked."

    if action != "motion.stop":
        _no_drive_line = _no_drive_room_decline_line()
        if _no_drive_line is not None:
            return _no_drive_line

    if action in {"motion.turn", "motion.move", "motion.arc"}:
        # The human is steering by voice: the social realign behavior must not
        # rotate the body back toward their face for a while (field 2026-07-23,
        # "turn right" undone by a realign left turn 13 s later). EXCEPT "I'm
        # behind you" / "I'm to your left": those turns point him TOWARD the
        # speaker, and realign finishing the job afterward is exactly what they
        # asked for.
        if not (args.get("behind") or args.get("bearing")):
            try:
                from intelligence import motion_agency
                motion_agency.note_user_motion()
            except Exception:
                pass
    elif action == "motion.stop":
        # "Don't move" is a STANDING instruction, not a brief pause — it latches
        # until he's told to move again. Sharing the 45 s steering window meant he
        # was turning again 49 s after saying "Stopping." (field 2026-07-25).
        try:
            from intelligence import motion_agency
            motion_agency.note_user_hold("user said stop")
        except Exception:
            pass
    if action in {"motion.turn", "motion.move", "motion.arc", "motion.come"}:
        # Commanded moves speak a confirmation that would otherwise win the race
        # for the speaker and mute the drive sound — play it in overlay mode.
        motion_controller.note_user_commanded_motion()

    # A fresh single command supersedes any queued route. Its own command will
    # supersede the in-flight firmware finite command; stop/come need an explicit
    # controlled stop because they may not immediately issue another finite step.
    _cancel_motion_sequence(
        f"superseded by {action}", stop_base=(action == "motion.come")
    )

    if action == "motion.stop":
        _clear_motion_continuation()
        try:
            from intelligence import motion_agency
            motion_agency.cancel_requested_come("stopped by user")
        except Exception:
            pass
        motion_controller.stop()
        return "Stopping."

    if action == "motion.come":
        _clear_motion_continuation()
        try:
            from intelligence import motion_agency
            # The voice-identified speaker is the target: with two people in the
            # room, "come here" must go to whoever SAID it, not to the first known
            # face the search happens across (owner spec 2026-08-11).
            behind = bool(args.get("behind"))
            side = args.get("side")
            try:
                side_deg = float(args["side_deg"]) if args.get("side_deg") else None
            except (TypeError, ValueError):
                side_deg = None
            started = motion_agency.request_come_here(
                person_id=requester_person_id, behind=behind, side_deg=side_deg
            )
            if not started:
                return None
            if behind:
                return "Turning around — on my way."
            if side:
                return f"Swinging {side} — on my way."
            return "On my way."
        except Exception as exc:
            _log.debug("requested come start failed: %s", exc)
            return None

    def _f(key: str) -> Optional[float]:
        try:
            return float(args[key]) if args.get(key) is not None else None
        except (TypeError, ValueError):
            return None

    if action == "motion.turn":
        if args.get("compass"):
            # "Turn north" — rotate to the true compass heading (calibrated QMC5883).
            card = str(args["compass"])
            seq = motion_controller.turn_to_compass(float(args.get("compass_deg") or 0.0))
            if seq is None:
                return ("My compass isn't giving me a heading right now, so I "
                        "couldn't tell you which way {} is.".format(card))
            if seq == 0:
                return f"Already facing {card}."
            _remember_motion_continuation(decision)
            return f"Turning {card}."
        direction = str(args.get("direction") or "left").lower()
        deg = _f("deg")
        # `rate` reaches here only from a ONE-STEP motion.route the speaker asked to
        # take slowly. The voice-friendly turn_left/turn_right wrappers take no rate,
        # so a paced turn goes to the signed primitive — same command, same clamps,
        # same swing check. Without this a one-step plan silently dropped the pace
        # while the identical step inside a two-step route honoured it, because only
        # motion_sequence._issue was reading the key.
        rate = _f("rate")
        if direction == "around":
            seq = (motion_controller.turn(180.0 if deg is None else deg, rate=rate)
                   if rate else motion_controller.turn(180.0 if deg is None else deg))
            line = "Spinning around."
            if seq is not None and args.get("behind"):
                # "I'm behind you" mid-come-search: the search adopts this turn
                # as its own leg (dwell + neck sweep at the new heading).
                line = "Ah — behind me. Turning around."
                try:
                    from intelligence import motion_agency
                    motion_agency.note_behind_turn(seq)
                except Exception:
                    pass
        elif direction == "right":
            seq = (motion_controller.turn(-abs(deg or _MOTION_DEFAULT_TURN_DEG()),
                                          rate=rate)
                   if rate else motion_controller.turn_right(deg))
            line = "Turning right."
        else:
            seq = (motion_controller.turn(abs(deg or _MOTION_DEFAULT_TURN_DEG()),
                                          rate=rate)
                   if rate else motion_controller.turn_left(deg))
            line = "Turning left."
        if seq is not None and args.get("bearing"):
            # "I'm to your left" mid-come-search: the search adopts this swing
            # as its own leg, exactly like the behind about-face.
            line = f"Ah — off to my {direction}. Coming around."
            try:
                from intelligence import motion_agency
                motion_agency.note_side_turn(seq, direction)
            except Exception:
                pass
        if seq is not None:
            _remember_motion_continuation(decision)
            return line
        return None

    if action == "motion.move":
        if args.get("compass"):
            # "Go north two feet" — face the true heading, then advance. Runs through
            # motion_sequence so the move waits for the turn to complete.
            card = str(args["compass"])
            if motion_controller.compass_turn_delta(float(args.get("compass_deg") or 0.0)) is None:
                return ("My compass isn't giving me a heading right now, so I "
                        "can't find {} for you.".format(card))
            from intelligence import motion_sequence
            steps = [
                action_router.ActionDecision(
                    action="motion.turn", confidence=0.95,
                    args={"compass": card, "compass_deg": args.get("compass_deg")},
                    reason="compass move: face the heading",
                ),
                action_router.ActionDecision(
                    action="motion.move", confidence=0.95,
                    args={"direction": "forward", "dist_m": _f("dist_m")},
                    reason="compass move: advance",
                ),
            ]
            if motion_sequence.start(steps):
                return f"Heading {card}."
            return None
        direction = str(args.get("direction") or "forward").lower()
        dist = _f("dist_m")
        speed = _f("speed")          # one-step motion.route pace; see the turn branch
        amount = abs(dist or _MOTION_DEFAULT_MOVE_DIST_M())
        if direction == "back":
            seq = (motion_controller.move(-amount, speed=speed) if speed
                   else motion_controller.move_back(dist))
            line = "Backing up."
        else:
            seq = (motion_controller.move(amount, speed=speed) if speed
                   else motion_controller.move_forward(dist))
            line = "Rolling forward."
        if seq is not None:
            # A spoken move that the firmware cuts on an obstacle must SAY so —
            # silence read as "he ignores my commands" (field 2026-07-23).
            motion_controller.announce_if_blocked(seq)
            _remember_motion_continuation(decision)
            return line
        return None

    if action == "motion.arc":
        # Compound "move forward and to your right" — a brief simultaneous curve that
        # auto-stops (motion_controller refreshes the drive setpoint, then stops).
        forward = str(args.get("lin_dir") or "forward").lower() != "back"
        left = str(args.get("ang_dir") or "left").lower() == "left"
        seq = motion_controller.arc_move(forward, left, small=bool(args.get("small")))
        line = "Curving {} and {}.".format(
            "forward" if forward else "back", "left" if left else "right")
        if seq is not None:
            _remember_motion_continuation(decision)
            return line
        return None

    return None


# ── motion.route: model-planned multi-step routes ───────────────────────────────
# docs/motion_route_tool_plan.md. Reached two ways, and they differ ONLY in how the
# route args are obtained and what policy runs first:
#   * the RESCUE path — _explicit_motion_takeover's tri-state None arm, where the
#     sequence classifier has already said "this IS an attempted route and I can't
#     parse it" and today speaks a flat refusal;
#   * the ORGANIC path — the reply call choosing motion.route (Phase 2, gated on
#     config.MOTION_ROUTE_ORGANIC_ENABLED).
# Everything physical below is shared, so the two cannot drift apart on safety.


def _motion_route_legs_executable(
    decisions: list[action_router.ActionDecision],
) -> bool:
    """The execute policy, applied PER LEG as well as to the composite key.

    A route is only as executable as its legs: without this, switching motion.turn
    off in ACTION_ROUTER_EXECUTE_ACTIONS would stop "turn left" and still drive a
    route whose first step is a turn. The composite motion.route key is checked
    separately by the caller — checking only the legs would make that allowlist
    entry a switch that does nothing, which is exactly the c7ef872 failure (203
    audited "not_in_execute_allowlist" events logged while the wheels turned)."""
    return all(_motion_takeover_executable(step) for step in decisions or [])


def _handle_motion_route(
    decisions: list[action_router.ActionDecision],
    *,
    requester_person_id: Optional[int] = None,
) -> "tuple[Optional[str], bool]":
    """Drive a validated route. Returns (spoken line or None, whether it drove).

    Physical gates only — the allowlist/evidence policy belongs to the caller, which
    knows which evidence applies to its path. Order matters: every check that can
    refuse in WORDS runs before anything is issued, so a refused route is heard
    rather than silently doing nothing.

    The second element exists because a refusal is ALSO a line: "I'm plugged in and
    charging" is spoken, and returning it alone would make every caller's audit and
    shadow log say a route executed when the wheels never turned. That is the class
    of untruth c7ef872 was written to end.
    """
    if not decisions or not motion_controller.available():
        return None, False
    if motion_controller.charging():
        return "I'm plugged in and charging. Wheels stay locked.", False
    no_drive_line = _no_drive_room_decline_line()
    if no_drive_line is not None:
        return no_drive_line, False
    try:
        from intelligence import motion_sequence
        spin_block = motion_sequence.spin_clearance_reason(decisions)
    except Exception as exc:
        _log.debug("[motion_route] spin clearance check unavailable: %s", exc)
        spin_block = None
    if spin_block:
        return (str(getattr(config, "MOTION_ROUTE_SPIN_DENIAL_LINE", "")
                    or "Not enough elbow room for a full spin in here."), False)
    if len(decisions) == 1:
        # motion_sequence.start() refuses anything under two steps and returns False,
        # which would leave the turn silent. A one-step "route" is just a command —
        # hand it to the single-verb executor rather than dropping it on the floor.
        # It re-runs the charging and no-drive checks and can decline in words too,
        # which would make a line an unreliable proof of motion — except that this
        # function just ran both of them, so the only way to reach its refusals from
        # here is for the charger to be plugged in between two statements. It reports
        # a suppressed command as None, and that is the case worth being right about.
        line = _handle_router_motion_action(
            decisions[0], requester_person_id=requester_person_id
        )
        return line, bool(line)
    if not _start_motion_sequence(decisions):
        return None, False
    return "On it — {} moves.".format(len(decisions)), True


def _handle_face_requester(
    person_id: Optional[int] = None,
) -> "tuple[Optional[str], bool]":
    """"Turn to face me" — one base turn onto the requester's bearing, then stop.

    Returns (spoken line or None, whether it turned), the same contract
    _handle_motion_route uses and for the same reason: a refusal is also a line, and
    a caller that reads "returned a string" as "the wheels moved" writes an audit
    that says a maneuver executed while the base sat still.

    The physical gates run HERE, in the shared order every commanded maneuver uses,
    because they are the ones that can refuse in words. motion_agency owns the
    bearing and the turn; this function owns the conversation.
    """
    if not motion_controller.available():
        return None, False
    if motion_controller.charging():
        return "I'm plugged in and charging. Wheels stay locked.", False
    no_drive_line = _no_drive_room_decline_line()
    if no_drive_line is not None:
        return no_drive_line, False
    try:
        from intelligence import motion_agency
        deg, reason = motion_agency.face_requester(person_id)
    except Exception as exc:
        _log.error("[motion_face] face_requester failed: %s", exc)
        return None, False

    def _line(key: str, fallback: str) -> str:
        pool = [str(x).strip() for x in (getattr(config, key, []) or []) if str(x).strip()]
        return random.choice(pool) if pool else fallback

    if reason == "turned":
        _log.info("[motion_face] turning %+.0f deg to face person_id=%s", deg, person_id)
        return _line("MOTION_FACE_ME_TURNING_LINES", "Turning to face you."), True
    if reason == "already_facing":
        return _line("MOTION_FACE_ME_ALREADY_LINES", "I'm already pointed right at you."), False
    if reason == "ambiguous":
        # Radar saw more than one body and cannot say which is the requester. Naming
        # the ambiguity is a recoverable answer; a confident turn to the furniture
        # is not (field 2026-08-19: three 60 deg chases of a rear return, each
        # spinning him away from where the owner actually sat).
        return _line("MOTION_FACE_ME_AMBIGUOUS_LINES",
                     "I've got a couple of somethings in the room and no idea which one is you."), False
    if reason == "no_bearing":
        return _line("MOTION_FACE_ME_NO_BEARING_LINES",
                     "I can't work out where you are from here."), False
    if reason == "come_active":
        return "Already on my way.", False
    # busy / traction / suppressed / disabled — the base said no, or something else
    # owns it. Say nothing and let the turn fall through to conversation rather than
    # narrating an internal state nobody asked about.
    _log.info("[motion_face] declined: %s (person_id=%s)", reason, person_id)
    return None, False


def _motion_route_from_tool_args(
    args: dict,
) -> "tuple[list[action_router.ActionDecision] | None, Optional[str]]":
    """Tool args -> ordered decisions, or (None, reason). Never raises."""
    try:
        return action_router.route_tool_to_decisions(args)
    except Exception as exc:
        _log.error("[motion_route] translator failed: %s", exc)
        return None, f"translator_error:{type(exc).__name__}"


def _motion_route_transcript_blocked() -> bool:
    """True when this turn's transcript is too shaky to drive a model-planned route.

    Model-initiated motion only (plan §4.3.1). Low-confidence turns already refuse to
    write memory — a fabricated FACT is recoverable and a fabricated DRIVE is not,
    and ASR fabrication is a documented failure class here. The regex fast lane's own
    bar is deliberately unchanged: its rigidity was the accidental guard, and this is
    what the LLM lane gives up in exchange for understanding the sentence."""
    if not bool(getattr(config, "MOTION_ROUTE_REQUIRE_TRUSTED_TRANSCRIPT", True)):
        return False
    return not _turn_transcript_trusted()


def _speak_motion_route_ack() -> None:
    """Queue a cached 'working on it' to play WHILE the interpreter thinks (~0.8 s).

    speech_queue.enqueue, not _speak_blocking, and the difference is the whole point.
    _speak_blocking returns only after playback finishes AND after the 800-1500 ms
    post-punchline beat a priority-1 line draws, so speaking the ack that way would
    ADD ~2 s ahead of a call it was supposed to cover — time-to-wheels 2.5-3.7 s
    against the plan's 1.2 s budget. Enqueued, it overlaps the call it is hiding and
    the drive confirmation simply queues behind it.

    Same guards as _try_slow_path_ack, for the same reasons: never speak over
    something already playing, never fetch TTS at speak time (the prefill thread
    warms these at startup), and stay silent in a no-audio build.
    """
    if not bool(getattr(config, "MOTION_ROUTE_ENABLED", True)):
        return
    lines = [str(line).strip() for line in
             (getattr(config, "MOTION_ROUTE_ACK_LINES", []) or []) if str(line).strip()]
    if not lines:
        return
    if bool(getattr(config, "NO_AUDIO_MODE", False)
            or getattr(config, "AUDIO_OUTPUT_SUPPRESSED", False)):
        return
    try:
        if speech_queue.is_speaking() or output_gate.is_busy() or _interrupted.is_set():
            return
        chosen = random.choice(lines)
        from audio import tts
        if not tts.is_cached(chosen):
            _log.debug("[motion_route] ack skipped, TTS not cached: %r", chosen)
            return
        _mark_first_response_queued(_current_character_loop_trace.get(),
                                    text=chosen, priority=1)
        speech_queue.enqueue(chosen, "neutral", priority=1, tag="motion_route_ack")
    except Exception as exc:
        _log.debug("[motion_route] ack failed: %s", exc)


def _rescue_motion_route(
    text: str,
    *,
    person_id: Optional[int] = None,
    router_audit: Optional["_RouterDecisionAudit"] = None,
) -> Optional[str]:
    """The rescue path: plan an unparseable-but-route-shaped utterance with the LLM.

    Returns the spoken line when a route ran (or was refused in character), or None
    to let the caller speak today's "I couldn't safely parse that whole route."

    The evidence gate (action_router.motion_command_refusal_reason) is NOT re-run
    here, on purpose (plan §4.3.2). The tri-state None arm has already run the
    sequence parser's own negation and figurative checks over this utterance and
    positively identified it as an attempted route; the gate is a SENTENCE-anchored
    imperative test, and the disfluent real commands this path exists for are exactly
    the ones it refuses ("Three feet, and turn a little bit right." leads with a noun
    phrase). What stands in its place: the interpreter's own decline tool, the
    translator's clamps, and every physical gate in _handle_motion_route.
    """
    from intelligence import motion_route

    if not motion_route.available():
        # Offline, or the master switch is off — the deterministic denial stands
        # (plan §4.4: the local reply model gets no tool surface, so with the link
        # down the classifiers are the whole story).
        return None
    if _motion_route_transcript_blocked():
        _log.info("[motion_route] rescue skipped — low-confidence transcript: %r", text)
        return None

    _speak_motion_route_ack()
    result = motion_route.interpret(text)
    decisions, refusal = (None, None)
    if result.get("args") is not None:
        decisions, refusal = _motion_route_from_tool_args(result["args"])

    line: Optional[str] = None
    drove = False
    if decisions:
        route_decision = action_router.ActionDecision(
            action="motion.route", confidence=0.95,
            args={"steps": len(decisions)},
            reason="motion.route rescue of an unparseable spoken route",
        )
        _router_audit_note_decision(router_audit, route_decision)
        if not _router_decision_executable(route_decision):
            _log.info("[motion_route] rescue blocked by execute policy: text=%r", text)
            refusal = refusal or "not_in_execute_allowlist"
            decisions = None
        elif not _motion_route_legs_executable(decisions):
            _log.info("[motion_route] rescue blocked by per-leg execute policy: "
                      "text=%r", text)
            refusal = refusal or "leg_not_in_execute_allowlist"
            decisions = None
        else:
            _clear_motion_continuation()
            line, drove = _handle_motion_route(
                decisions, requester_person_id=person_id
            )

    if bool(getattr(config, "MOTION_ROUTE_SHADOW_LOG_ENABLED", True)):
        motion_route.log_shadow(text, result, decisions, refusal, executed=drove)
    if line is None:
        return None
    if drove:
        _router_audit_note_fast_local_action(
            router_audit, "motion.route", args={"steps": len(decisions or [])},
            reason="motion.route rescue of an unparseable spoken route",
        )
    _speak_blocking(line, emotion="neutral", log_text=False)
    return line


# ── Phase 3 motion tool path (docs/tool_router_scope.md §3) ──────────────────────
# One room-crossing, deliberately well inside motion_controller.move()'s own ±10 m
# clamp: that clamp exists to stop a firmware-level absurdity, not to make a
# hallucinated "50" safe indoors. The angle cap matches the controller's ±360.
_MOTION_TOOL_MAX_DIST_M = 3.0
_MOTION_TOOL_MAX_DEG = 360.0


def _motion_args_from_tool(action: str, args: dict, text: str) -> dict[str, Any]:
    """Tool arguments -> the exact keys _handle_router_motion_action reads.

    Arg-name drift is this migration's most-repeated bug (performance.impersonate
    who->target, memory.forget_specific statement->target) and motion shipped with
    THREE instances of it, every one failing SILENTLY: `degrees` where the executor
    reads `deg` (a commanded angle became the default 90), `distance`+`unit` where it
    reads `dist_m` (a commanded distance became the default 0.30 m nudge), and
    motion.arc's lone `direction` where it reads `ang_dir`/`lin_dir` (every arc
    curved forward-and-LEFT regardless). The move enum also said "backward" while the
    executor tests `== "back"` and otherwise falls through to move_forward — "back
    up" would have driven him FORWARD.

    tool_router._TOOL_DEFS now speaks the executor's keys, so this function is the
    belt: it accepts the old names as aliases (the same accepted-alias shape
    _router_arg_text uses for impersonate) and CLAMPS, so a stale name never falls on
    the floor as "the default" again.
    """
    src = dict(args or {})

    def _word(*keys: str) -> str:
        for key in keys:
            value = str(src.get(key) or "").strip().lower()
            if value:
                return value
        return ""

    def _num(*keys: str) -> Optional[float]:
        for key in keys:
            if src.get(key) is None:
                continue
            try:
                return float(src[key])
            except (TypeError, ValueError):
                return None
        return None

    out: dict[str, Any] = {}
    if action == "motion.turn":
        direction = _word("direction", "dir", "side")
        if direction in ("around", "about", "180", "backward", "backwards"):
            out["direction"] = "around"
        elif direction.startswith("r") or direction == "clockwise":
            out["direction"] = "right"
        else:
            out["direction"] = "left"
        deg = _num("deg", "degrees", "angle", "amount")
        if deg is None and out["direction"] == "around":
            deg = 180.0
        if deg is not None:
            out["deg"] = min(abs(deg), _MOTION_TOOL_MAX_DEG)
    elif action == "motion.move":
        direction = _word("direction", "dir")
        out["direction"] = (
            "back" if direction.startswith("back") or direction == "reverse"
            else "forward"
        )
        # The user's OWN WORDS are the authority on magnitude: motion_distance_m is
        # the same imperial/metric parser the regex lane uses, so "back up two feet"
        # is 0.6096 m whether or not the model did the conversion — and asking an LLM
        # to do unit arithmetic for a drive base is exactly the class of mistake this
        # avoids. The model's number is the fallback for phrasings that parser misses
        # ("go a couple feet forward").
        dist = action_router.motion_distance_m(text)
        if dist is None:
            dist = _num("dist_m", "distance", "dist", "meters", "metres")
        if dist is not None:
            out["dist_m"] = min(abs(dist), _MOTION_TOOL_MAX_DIST_M)
    elif action == "motion.arc":
        lateral = _word("ang_dir", "direction", "side", "dir")
        out["ang_dir"] = "right" if lateral.startswith("r") else "left"
        linear = _word("lin_dir", "linear")
        out["lin_dir"] = (
            "back" if linear.startswith("back") or linear == "reverse" else "forward"
        )
        out["small"] = bool(src.get("small"))
    # motion.come deliberately takes NO args. behind / side / side_deg are bearing
    # hints the regex lane SYNTHESIZES from "I'm behind you" / "I'm to your left"
    # (owner spec 2026-08-11) — a model asserting a bearing it cannot observe would
    # send the search sweeping the wrong hemisphere. With none set,
    # motion_agency.request_come_here runs its normal search.
    return out


def _motion_no_base_denial_line(text: str) -> Optional[str]:
    """A pre-canned, in-character refusal for an explicit DRIVE command spoken while no
    ESP32 drive base is connected. Returns None for non-drive / bare-stop text (so those
    fall through to normal routing) or when the behavior is disabled."""
    if not bool(getattr(config, "MOTION_NO_BASE_DENIAL_ENABLED", True)):
        return None
    decision = action_router.classify_explicit_motion(text)
    if decision is None or decision.action not in _MOTION_DRIVE_ACTIONS:
        return None
    lines = list(getattr(config, "MOTION_NO_BASE_DENIAL_LINES", []) or [])
    if not lines:
        return None
    return random.choice(lines)


def _motion_takeover_executable(
    decision: Optional[action_router.ActionDecision],
    *,
    text: Optional[str] = None,
) -> bool:
    """Execute policy for the two pre-dialogue-gate motion takeovers.

    Field 2026-08-13: every one of the 203 audited "not_in_execute_allowlist"
    events logged final_executed_path=fast_local_takeover.motion.* — the takeovers
    drove the base straight off the deterministic classifier without ever asking
    the policy, so the wheels turned while the audit line said the action was
    blocked. This turns the two OVERSIGHT guards back on: the
    config.ACTION_ROUTER_EXECUTE_ACTIONS allowlist (which now carries the motion.*
    keys, making it a real kill switch) and the confidence floor — regex motion
    emits 0.95-0.97 and the explore invite 0.93, all clear of the 0.85 bar, so
    genuine commands pass exactly as they do today.

    dialogue_decision is deliberately NOT passed. Running ahead of the dialogue-act
    gate is the entire reason these takeovers exist: ccd839e (2026-06-23) shipped
    because "move forward." / "Move backwards" were labelled answer_to_rex and the
    motion fast path was skipped, and the field logs still show "Turn around.",
    "Back up two feet." and "Stop moving." binding as answer frames. A physical
    command is never the answer to Rex's last question, and
    _dialogue_allows_action_breakout has no motion escape hatch — handing the
    dialogue decision in here would re-swallow exactly those turns.

    text is withheld on the motion side for the same reason: the deterministic
    classifier IS the evidence there, and the continuation ("more" after a turn)
    and errand-stop decisions are synthesized from live base state rather than from
    re-matchable words, so an evidence re-match would block valid commands. The
    explore takeover does pass it — motion.explore's evidence check is the same
    imperative-invite classifier that produced the decision, so it is a free
    re-verification.
    """
    return _router_decision_executable(decision, text=text)


def _explicit_motion_takeover(
    text: str,
    *,
    person_id: Optional[int] = None,
    router_audit: Optional["_RouterDecisionAudit"] = None,
) -> Optional[str]:
    """Explicit drive-base motion, run BEFORE the dialogue-act gate.

    A deterministic "turn left" / "move forward" / "move backwards" is a PHYSICAL
    command, not an answer to Rex's last question — so it must execute even inside an
    answer_to_rex frame (which otherwise skips the whole router). Returns a short spoken
    confirmation, or None when it's not an explicit motion command or the command was
    suppressed (paused / gamepad owns the base). Bare "stop" routes here only while the
    base is actually moving (so it never steals stop-music/game/talk).

    When NO base is connected, an explicit DRIVE command (turn/move/come/arc) gets a
    spoken in-character denial instead of silently falling through to conversation — with
    no wheels there's no physical acknowledgment, so Rex says so out loud. Bare
    "stop"/"halt" still no-ops here (nothing to halt)."""
    if not motion_controller.available():
        denial = _motion_no_base_denial_line(text)
        if denial is None:
            return None
        _log.info(
            "[motion] drive command with no base connected -> verbal denial: text=%r",
            text,
        )
        _speak_blocking(denial, emotion="neutral", log_text=False)
        _router_audit_note_fast_local_action(
            router_audit, "motion.denied_no_base", reason="drive base not connected"
        )
        return denial
    sequence = action_router.classify_explicit_motion_sequence(
        text, max_steps=int(getattr(config, "MOTION_SEQUENCE_MAX_STEPS", 8))
    )
    if sequence is None:
        _clear_motion_continuation()
        # The tri-state None arm: route-SHAPED, and the regex could not parse it.
        # This is the cleanest entry point in the stack for an interpreter — the
        # utterance has already been positively identified as an attempted route
        # command, so the only thing missing is someone who can read it. Owner,
        # 2026-08-19: "instead of a regex failure where he says 'I can't parse that
        # route' the LLM could plan out the moves." Everything below stays as the
        # fallback for offline, a declined interpretation, or a refused plan.
        rescued = _rescue_motion_route(
            text, person_id=person_id, router_audit=router_audit
        )
        if rescued is not None:
            return rescued
        rejected = action_router.ActionDecision(
            action="motion.sequence", confidence=0.98,
            args={"accepted": False},
            reason="motion sequence contained an invalid or unsupported clause",
        )
        _router_audit_note_decision(router_audit, rejected)
        _router_audit_note_fast_local_action(
            router_audit, "motion.sequence_rejected", reason=rejected.reason
        )
        line = "I couldn't safely parse that whole route."
        _speak_blocking(line, emotion="neutral", log_text=False)
        return line
    if sequence:
        _clear_motion_continuation()
        decision = action_router.ActionDecision(
            action="motion.sequence", confidence=0.98,
            args={"steps": len(sequence)},
            reason="explicit ordered motion sequence",
        )
        _router_audit_note_decision(router_audit, decision)
        if not _motion_route_legs_executable(sequence):
            # A route is only as executable as its legs. Without this, switching a
            # motion key off in ACTION_ROUTER_EXECUTE_ACTIONS would stop "turn left"
            # but still drive "turn left then move forward" — the composite
            # motion.sequence decision is a local audit label, not a catalog action,
            # so the policy has to be applied per leg.
            _log.info(
                "[motion] route blocked by execute policy (allowlist/confidence): text=%r",
                text,
            )
            return None
        # Shared with the model-planned routes so the two lanes cannot drift apart on
        # the physical gates. This lane GAINED the no-drive-room decline here: it had
        # only ever checked the charger, so "turn left then move forward" drove in a
        # room where "turn left" on its own was declined.
        line, drove = _handle_motion_route(sequence, requester_person_id=person_id)
        if line is None:
            return None
        if drove:
            # A refusal is also a line ("I'm plugged in and charging"), and the audit
            # must not call one an executed route — the charging arm returned before
            # this note before the refactor, and it still does not reach it.
            _router_audit_note_fast_local_action(
                router_audit, "motion.sequence", reason=decision.reason
            )
        _speak_blocking(line, emotion="neutral", log_text=False)
        return line

    motion_decision = action_router.classify_explicit_motion(text)
    if motion_decision is None:
        motion_decision = _resolve_motion_continuation(text)
    requested_come_active = False
    if motion_decision is None and _errand_stop_demanded(text or ""):
        try:
            from intelligence import motion_agency
            requested_come_active = motion_agency.requested_come_active()
        except Exception:
            pass
    if (
        motion_decision is None
        and (motion_controller.is_moving() or requested_come_active)
        and _errand_stop_demanded(text or "")
    ):
        motion_decision = action_router.ActionDecision(
            action="motion.stop", confidence=0.95, args={},
            reason="stop demanded while base moving",
        )
    if motion_decision is None:
        # Continuations are adjacency-sensitive. Any intervening non-motion turn
        # retires the context, while TTL also handles a long silent gap.
        _clear_motion_continuation()
        return None
    _router_audit_note_decision(router_audit, motion_decision)
    if not _motion_takeover_executable(motion_decision):
        # Allowlist + confidence oversight only — see _motion_takeover_executable
        # for why the dialogue-act gate stays off this path (ccd839e, 2026-06-23).
        _log.info(
            "[motion] command blocked by execute policy: action=%s conf=%.2f text=%r",
            motion_decision.action,
            float(motion_decision.confidence or 0.0),
            text,
        )
        return None
    result = _handle_router_motion_action(motion_decision, requester_person_id=person_id)
    if result is not None:
        _router_audit_note_fast_local_action(
            router_audit, motion_decision.action, reason=motion_decision.reason
        )
        _speak_blocking(result, emotion="neutral", log_text=False)
    return result


def _handle_explore_invite(
    text: str,
    *,
    person_id: Optional[int],
    person_name: Optional[str],
    router_audit: Optional["_RouterDecisionAudit"] = None,
    source: str = "invite",
) -> Optional[str]:
    """Start a room-exploration session for an invitation, or speak the no-base quip.

    Returns a SILENT-command sentinel when the session started (the exploration
    worker speaks its own ack line, so the interaction layer stays quiet but still
    consumes the turn), the spoken denial when no base is connected, or None when
    exploration is disabled / refused (game/DJ/battery/already-active) so the turn
    falls through to normal routing.
    """
    try:
        from intelligence import exploration
    except Exception:
        return None
    if not exploration.enabled():
        return None
    can_drive = exploration.base_available() or bool(
        getattr(config, "EXPLORE_HEADONLY_FALLBACK_ENABLED", False)
    )
    if not can_drive:
        lines = list(getattr(config, "EXPLORE_NO_BASE_LINES", []) or [])
        if not lines:
            return None
        denial = random.choice(lines)
        _log.info("[explore] invite with no base connected -> verbal quip: text=%r", text)
        _speak_blocking(denial, emotion="neutral", log_text=False)
        _router_audit_note_fast_local_action(
            router_audit, "motion.explore_denied_no_base", reason="no drive base"
        )
        return denial
    if exploration.base_available():
        # The owner told him not to drive in this room ("this room has carpet") —
        # an exploration invite is a drive request like any other, so it gets the
        # same decline as spoken motion commands, with the voice-liftable way out.
        _no_drive = exploration.no_drive_room()
        if _no_drive is not None:
            _room, _why = _no_drive
            _because = " — carpet eats my wheels" if _why == "carpet" else ""
            denial = (f"I'd love a wander, but you told me not to drive in the "
                      f"{_room}{_because}. Say \"you can drive in here\" if that's changed.")
            _log.info("[explore] invite refused: room %r is flagged no-drive (%s)",
                      _room, _why or "owner's rule")
            _speak_blocking(denial, emotion="neutral", log_text=False)
            _router_audit_note_fast_local_action(
                router_audit, "motion.explore_denied_no_drive_room", reason="no-drive room"
            )
            return denial
    started = exploration.start(person_id, person_name, source=source)
    if not started:
        return None
    _clear_motion_continuation()
    _log.info("[explore] invite accepted (person_id=%s source=%s)", person_id, source)
    _router_audit_note_fast_local_action(
        router_audit, "motion.explore", reason="room-exploration invitation"
    )
    # The worker speaks the ack + narration itself; interaction stays silent.
    return _silent_command_response("motion.explore")


def _explore_invite_takeover(
    text: str,
    *,
    person_id: Optional[int],
    person_name: Optional[str],
    router_audit: Optional["_RouterDecisionAudit"] = None,
) -> Optional[str]:
    """Deterministic room-exploration INVITE, run alongside the motion takeover.

    Like _explicit_motion_takeover this fires BEFORE the dialogue-act gate (an
    invitation to explore is a command, not an answer to Rex's last turn). Runs
    AFTER the motion takeover so 'turn around' is already claimed as a turn.
    """
    decision = action_router.classify_explicit_exploration(text)
    if decision is None or decision.action != "motion.explore":
        return None
    _router_audit_note_decision(router_audit, decision)
    if not _motion_takeover_executable(decision, text=text):
        # Same oversight as the motion takeover: allowlist + the 0.85 confidence
        # floor (the invite classifier emits 0.93) plus motion.explore's own invite
        # evidence check — but no dialogue-act gate, because "look around a little"
        # spoken right after Rex talks is still a command, not an answer.
        _log.info("[explore] invite blocked by execute policy: text=%r", text)
        return None
    return _handle_explore_invite(
        text, person_id=person_id, person_name=person_name, router_audit=router_audit
    )


def _handle_router_takeover_action(
    decision: Optional[action_router.ActionDecision],
    text: str,
    *,
    person_id: Optional[int],
    person_name: Optional[str],
    raw_best_id: Optional[int],
    raw_best_name: Optional[str],
    raw_best_score: float,
    router_context: Optional[dict[str, Any]] = None,
    dialogue_decision: Optional[dialogue_act.DialogueActDecision] = None,
    router_audit: Optional[_RouterDecisionAudit] = None,
) -> Optional[str]:
    """Execute router-owned actions that map to stable local handlers."""
    if not _router_decision_executable(
        decision,
        text=text,
        context=router_context,
        dialogue_decision=dialogue_decision,
    ):
        return None

    action = decision.action
    if action == "conversation.reply":
        return None

    if action == "conversation.repair":
        repair = _router_repair_move(text, decision)
        _log.info(
            "[action_router] executing conversation.repair kind=%s person_id=%s text=%r",
            repair.get("kind"),
            person_id,
            text,
        )
        return _generate_repair_response(person_id, text, repair)

    if action == "identity.name_correction":
        _log.info(
            "[action_router] executing identity.name_correction person_id=%s text=%r",
            person_id,
            text,
        )
        return _handle_router_identity_name_correction(
            text,
            decision,
            person_id,
            person_name,
        )

    if action in _PLAN_ROUTER_ACTIONS:
        return _handle_router_performance_action(
            decision,
            text,
            person_id,
            router_audit=router_audit,
        )

    if action == "performance.impersonate":
        target = _router_arg_text(decision, "target", "person", "who", "name")
        _log.info(
            "[action_router] executing performance.impersonate person_id=%s target=%r text=%r",
            person_id, target, text,
        )
        return _handle_router_impersonation(decision, text, person_id, person_name, target)

    if action == "memory.forget_specific":
        target = _router_arg_text(decision, "target", "topic", "memory")
        if not target:
            target = forgetting.extract_specific_forget_target(text)
        if not target:
            return None
        _log.info(
            "[action_router] executing memory.forget_specific person_id=%s target=%r text=%r",
            person_id,
            target,
            text,
        )
        return _execute_command(
            command_parser.CommandMatch(
                "forget_specific",
                "action_router",
                {"target": target},
            ),
            person_id,
            person_name,
            text,
        )

    if action == "memory.recent_discard":
        _log.info(
            "[action_router] executing memory.recent_discard person_id=%s text=%r",
            person_id,
            text,
        )
        return _execute_memory_boundary_command(person_id, utterance=str(text or ""))

    if action == "identity.who_is_speaking":
        _log.info(
            "[action_router] executing identity.who_is_speaking person_id=%s text=%r",
            person_id,
            text,
        )
        return _handle_classified_intent(
            "query_who_is_speaking",
            text,
            person_id,
            raw_best_id=raw_best_id,
            raw_best_name=raw_best_name,
            raw_best_score=raw_best_score,
            visible_known_name=_visible_known_name_for_intent(),
        )

    if action == "game.start":
        game = _router_arg_text(decision, "game", "game_name", "target")
        _log.info(
            "[action_router] executing game.start person_id=%s game=%r text=%r",
            person_id,
            game,
            text,
        )
        return _execute_command(
            command_parser.CommandMatch(
                "start_game",
                "action_router",
                {"game": game or text},
            ),
            person_id,
            person_name,
            text,
        )

    if action == "game.stop":
        _log.info(
            "[action_router] executing game.stop person_id=%s text=%r",
            person_id,
            text,
        )
        return _execute_command(
            command_parser.CommandMatch("stop_game", "action_router", {}),
            person_id,
            person_name,
            text,
        )

    if action == "game.answer":
        try:
            from features import games as games_mod
            if not games_mod.is_active():
                return None
            _log.info(
                "[action_router] executing game.answer person_id=%s text=%r",
                person_id,
                text,
            )
            resp = games_mod.handle_input(text, person_id)
            completed = _speak_blocking(resp)
            if completed:
                games_mod.on_response_spoken()
                after_audio = games_mod.consume_pending_audio_after_response()
                if after_audio and not _interrupted.is_set():
                    speech_queue.enqueue_audio_file(
                        after_audio,
                        priority=1,
                        tag="game:after_audio",
                    )
            return resp
        except Exception as exc:
            _log.debug("router game.answer failed: %s", exc)
            _router_audit_note_result(
                router_audit,
                handler_error=f"game_answer_failed:{type(exc).__name__}",
            )
            return None

    if action == "music.play":
        _log.info(
            "[action_router] executing music.play person_id=%s text=%r",
            person_id,
            text,
        )
        return _handle_classified_intent("play_music", text, person_id)

    if action == "music.stop":
        _log.info(
            "[action_router] executing music.stop person_id=%s text=%r",
            person_id,
            text,
        )
        return _execute_command(
            command_parser.CommandMatch("dj_stop", "action_router", {}),
            person_id,
            person_name,
            text,
        )

    if action == "music.skip":
        _log.info(
            "[action_router] executing music.skip person_id=%s text=%r",
            person_id,
            text,
        )
        return _execute_command(
            command_parser.CommandMatch("dj_skip", "action_router", {}),
            person_id,
            person_name,
            text,
        )

    if action == "music.options":
        _log.info(
            "[action_router] executing music.options person_id=%s text=%r",
            person_id,
            text,
        )
        return _handle_classified_intent("query_music_options", text, person_id)

    if action == "vision.describe_scene":
        _log.info(
            "[action_router] executing vision.describe_scene person_id=%s text=%r",
            person_id,
            text,
        )
        return _handle_classified_intent("query_what_do_you_see", text, person_id)

    if action == "memory.query":
        _log.info(
            "[action_router] executing memory.query person_id=%s text=%r",
            person_id,
            text,
        )
        return _handle_classified_intent(
            "query_memory",
            text,
            person_id,
            raw_best_id=raw_best_id,
            raw_best_name=raw_best_name,
            raw_best_score=raw_best_score,
            visible_known_name=_visible_known_name_for_intent(),
        )

    if action == "time.query":
        _log.info(
            "[action_router] executing time.query person_id=%s text=%r",
            person_id,
            text,
        )
        if _looks_like_date_query(text):
            return _handle_classified_intent("query_date", text, person_id)
        return _handle_classified_intent("query_time", text, person_id)

    if action == "date.query":
        _log.info(
            "[action_router] executing date.query person_id=%s text=%r",
            person_id,
            text,
        )
        return _handle_classified_intent("query_date", text, person_id)

    if action == "weather.query":
        _log.info(
            "[action_router] executing weather.query person_id=%s text=%r",
            person_id,
            text,
        )
        return _handle_classified_intent("query_weather", text, person_id)

    if action == "status.capabilities":
        _log.info(
            "[action_router] executing status.capabilities person_id=%s text=%r",
            person_id,
            text,
        )
        return _handle_classified_intent("query_capabilities", text, person_id)

    if action == "status.uptime":
        _log.info(
            "[action_router] executing status.uptime person_id=%s text=%r",
            person_id,
            text,
        )
        return _handle_classified_intent("query_uptime", text, person_id)

    if action == "status.battery":
        _log.info(
            "[action_router] executing status.battery person_id=%s text=%r",
            person_id,
            text,
        )
        return _handle_classified_intent("query_battery", text, person_id)

    if action == "system.shutdown":
        # is_shutdown_request (not the standalone form): the parser still owns
        # the safety guards (negation, object-scoped, hypothetical), but a
        # polite/desire-form directive ("Can you shut down, please?", "I would
        # like you to shut down") embedded in a farewell must execute — field
        # 2026-08-03 00:05: the standalone guard bounced the compound farewell
        # and Rex spoke "Powering down." without powering down.
        if not command_parser.is_shutdown_request(text):
            _log.info(
                "[action_router] ignored unverified system.shutdown candidate person_id=%s text=%r",
                person_id,
                text,
            )
            return None
        _log.info(
            "[action_router] executing system.shutdown person_id=%s text=%r",
            person_id,
            text,
        )
        return _execute_command(
            command_parser.CommandMatch("shutdown", "action_router", {}),
            person_id,
            person_name,
            text,
        )

    if action == "system.sleep":
        key = _router_system_command(text, decision)
        if key is None:
            _log.info(
                "[action_router] ignored non-standalone system.sleep candidate person_id=%s text=%r",
                person_id,
                text,
            )
            return None
        _log.info(
            "[action_router] executing system.sleep mapped_key=%s person_id=%s text=%r",
            key,
            person_id,
            text,
        )
        return _execute_command(
            command_parser.CommandMatch(key, "action_router", {}),
            person_id,
            person_name,
            text,
        )

    if action == "motion.explore":
        _log.info(
            "[action_router] executing motion.explore person_id=%s text=%r",
            person_id, text,
        )
        return _handle_explore_invite(
            text, person_id=person_id, person_name=person_name,
            router_audit=router_audit, source="router",
        )

    if action == "motion.face":
        _log.info("[action_router] executing motion.face person_id=%s text=%r",
                  person_id, text)
        return _handle_face_requester(person_id)[0]

    if action == "motion.route":
        # The retired JSON-prose router (ACTION_ROUTER_LLM_FALLBACK_ENABLED, off since
        # 2026-08-13) is the only thing that reaches this branch today, but a takeover
        # with no arm falls OPEN into conversation with no error — the failure mode
        # the new-executable-action checklist exists for — so it is wired anyway.
        decisions, refusal = _motion_route_from_tool_args(decision.args or {})
        if not decisions:
            _log.info("[action_router] motion.route rejected: %s args=%s",
                      refusal, decision.args)
            return None
        if _motion_route_transcript_blocked() or not _motion_route_legs_executable(decisions):
            _log.info("[action_router] motion.route blocked by policy text=%r", text)
            return None
        _log.info(
            "[action_router] executing motion.route person_id=%s steps=%d text=%r",
            person_id, len(decisions), text,
        )
        _clear_motion_continuation()
        return _handle_motion_route(decisions, requester_person_id=person_id)[0]

    if action in _MOTION_ACTIONS:
        _log.info(
            "[action_router] executing %s person_id=%s args=%s text=%r",
            action, person_id, decision.args, text,
        )
        return _handle_router_motion_action(decision, requester_person_id=person_id)

    return None


def _handle_fast_local_takeover(
    text: str,
    *,
    person_id: Optional[int],
    person_name: Optional[str],
    router_context: Optional[dict[str, Any]] = None,
    dialogue_decision: Optional[dialogue_act.DialogueActDecision] = None,
    router_audit: Optional[_RouterDecisionAudit] = None,
) -> Optional[str]:
    """Handle obvious local control commands before the blocking router call."""
    humor_decision = action_router.classify_explicit_humor(text)
    if humor_decision is not None and action_router.tool_router_owns(
        humor_decision.action
    ):
        # Migrated to the live tool router 2026-08-13: online the bit belongs to
        # the reply call this turn is about to make anyway, so this lane stands
        # down and lets the turn fall through to conversation. Nulling the
        # decision (rather than skipping the classifier call) keeps the guards it
        # carries — negation, narration, the roast food stoplist — as the thing
        # that decides there is no bit here at all. Offline, or with the kill
        # switch off, tool_router_owns is False and this lane performs exactly as
        # before: the local reply model gets no tools, so nothing downstream
        # would catch the handoff.
        humor_decision = None
    if humor_decision is not None:
        _router_audit_note_decision(router_audit, humor_decision)
    if _router_decision_executable(humor_decision):
        return _handle_router_performance_action(
            humor_decision,
            text,
            person_id,
            router_audit=router_audit,
        )
    performance_decision = action_router.classify_explicit_performance(text)
    if performance_decision is not None and action_router.tool_router_owns(
        performance_decision.action
    ):
        # Same handoff as humor above — covers dj_bit / body_beat / mood_pose AND
        # the performance.impersonate branch below.
        performance_decision = None
    if performance_decision is not None:
        _router_audit_note_decision(router_audit, performance_decision)
    if _router_decision_executable(performance_decision):
        if performance_decision.action == "performance.impersonate":
            # Impersonate is NOT a plan-pipeline action — _handle_router_performance_action
            # would silently reject it. Dispatch to its own handler. Running here (the
            # fast lane, BEFORE the dialogue-act gate) is what lets an explicit
            # "impersonate me" win even when it also reads as an answer to Rex's
            # last question — the dev-mac failure mode (2026-07-19 log).
            target = _router_arg_text(performance_decision, "target")
            _log.info(
                "[impersonation] fast-lane explicit request person_id=%s target=%r",
                person_id, target,
            )
            return _handle_router_impersonation(
                performance_decision, text, person_id, person_name, target
            )
        return _handle_router_performance_action(
            performance_decision,
            text,
            person_id,
            router_audit=router_audit,
        )

    # Drive-base motion runs BEFORE the dialogue-act gate (see _explicit_motion_takeover),
    # so an explicit "turn left" / "move forward" isn't swallowed as an answer_to_rex reply
    # when Rex has just spoken. Nothing to do here.

    directed_followup = _pending_directed_search_reply(
        text,
        person_id=person_id,
        person_name=person_name,
    )
    if directed_followup is not None:
        _router_audit_note_fast_local_action(
            router_audit,
            "vision.directed_search",
            reason="pending directed-look search follow-up",
        )
        return directed_followup

    try:
        match = command_parser.parse(text)
    except Exception as exc:
        _log.debug("fast local command parse failed: %s", exc)
        match = None
    if match is None:
        return None
    _router_audit_note_legacy_command(router_audit, match)
    legacy_block_reason = _legacy_command_execution_block_reason(
        match,
        text=text,
        context=router_context,
        dialogue_decision=dialogue_decision,
    )
    if legacy_block_reason:
        _log.info(
            "[turn_policy] blocked fast legacy command=%s reason=%s text=%r",
            match.command_key,
            legacy_block_reason,
            text,
        )
        _router_audit_clear_legacy_command(router_audit)
        return None

    key = match.command_key
    if key == "directed_look":
        _log.info(
            "[action_router] fast_lane legacy_command=directed_look "
            "person_id=%s text=%r",
            person_id,
            text,
        )
        return _execute_command(match, person_id, person_name, text)

    if key == "forget_specific":
        target = str((match.args or {}).get("target") or "").strip()
        if not target:
            return None
        _router_audit_note_fast_local_action(
            router_audit,
            "memory.forget_specific",
            args={"target": target},
            reason="legacy fast local forget command",
        )
        _log.info(
            "[action_router] fast_lane action=memory.forget_specific "
            "person_id=%s target=%r text=%r",
            person_id,
            target,
            text,
        )
        return _execute_command(match, person_id, person_name, text)

    if key == "memory_boundary":
        _router_audit_note_fast_local_action(
            router_audit,
            "memory.recent_discard",
            args={"scope": "recent"},
            reason="legacy fast local recent-memory discard command",
        )
        _log.info(
            "[action_router] fast_lane action=memory.recent_discard "
            "person_id=%s text=%r",
            person_id,
            text,
        )
        return _execute_memory_boundary_command(person_id)

    if key == "rename_me":
        _router_audit_note_fast_local_action(
            router_audit,
            "identity.name_correction",
            args=match.args or {},
            reason="legacy fast local current-speaker name correction",
        )
        _log.info(
            "[action_router] fast_lane action=identity.name_correction "
            "person_id=%s text=%r",
            person_id,
            text,
        )
        return _execute_command(match, person_id, person_name, text)

    if key == "stop_game":
        _router_audit_note_fast_local_action(
            router_audit,
            "game.stop",
            reason="legacy fast local stop-game command",
        )
        try:
            from features import games as games_mod
            resp = games_mod.stop_game_fast(person_id)
        except Exception as exc:
            _log.debug("fast game stop failed: %s", exc)
            return None
        _log.info(
            "[action_router] fast_lane action=game.stop person_id=%s text=%r",
            person_id,
            text,
        )
        _speak_blocking(resp, emotion="neutral")
        return resp

    if key == "dj_stop":
        _router_audit_note_fast_local_action(
            router_audit,
            "music.stop",
            reason="legacy fast local stop-music command",
        )
        try:
            from features import dj as dj_mod
            was_playing = bool(dj_mod.is_playing())
            dj_mod.stop()
        except Exception as exc:
            _log.debug("fast music stop failed: %s", exc)
            return None
        resp = "Music stopped." if was_playing else "No music is playing."
        _log.info(
            "[action_router] fast_lane action=music.stop person_id=%s "
            "active_music=%s text=%r",
            person_id,
            was_playing,
            text,
        )
        _speak_blocking(resp, emotion="neutral")
        return resp

    if key in {"time_query", "date_query"}:
        action = "time.query" if key == "time_query" else "date.query"
        _router_audit_note_fast_local_action(
            router_audit,
            action,
            reason=f"legacy fast local {key} command",
        )
        resp = (
            _format_current_time_response()
            if key == "time_query"
            else _format_current_date_response()
        )
        _log.info(
            "[action_router] fast_lane action=%s person_id=%s text=%r",
            action,
            person_id,
            text,
        )
        _speak_blocking(resp, emotion="neutral")
        return resp

    return None


_MEMORY_HINT_PAT = re.compile(
    r"\b(remember|told me|you said|plan|planned|schedule|trip|congrats|"
    r"how'?s|how is|how did|did .* go|survive|ready for)\b",
    re.IGNORECASE,
)
_CANCEL_CONTEXT_STOPWORDS = {
    "any", "anymore", "going", "gonna", "not", "now", "more", "the", "this",
    "that", "there", "where", "what", "when", "with", "you", "your", "i'm",
    "im",
}


def _recent_rex_memory_hint() -> str:
    """Return Rex's recent memory-callback line, for anchoring a generic
    cancellation ("we're not going anymore") to the event he just raised.

    The consciousness hint is consulted FIRST and trusted WITHOUT the keyword
    pattern: it is purpose-tagged at speak time (memory_followup / check-ins),
    which is ground truth. Field 2026-08-02 13:05: the paddleboarding
    anticipation line ("today's the day for your little aquatic dignity
    test...") carried no pattern keyword, the old transcript-first check
    early-returned "", and the cancellation matched nothing — the plan
    survived to be re-anticipated next boot."""
    try:
        text = consciousness.get_last_memory_hint()
    except Exception:
        text = ""
    if text:
        return text
    try:
        transcript = conv_memory.get_session_transcript()
    except Exception:
        return ""
    for turn in reversed(transcript[-8:]):
        if (turn.get("speaker") or "").lower() != "rex":
            continue
        text = (turn.get("text") or "").strip()
        if text and _MEMORY_HINT_PAT.search(text):
            return text
        return ""
    return ""


def _has_specific_memory_token(text: str) -> bool:
    tokens = [
        t.lower().strip("'")
        for t in re.findall(r"[A-Za-z0-9']+", text or "")
    ]
    return any(len(t) >= 3 and t not in _CANCEL_CONTEXT_STOPWORDS for t in tokens)


def _cancel_stale_event_memory(
    person_id: Optional[int],
    text: str,
    *,
    event_hint: Optional[dict] = None,
) -> list[str]:
    """
    Apply corrections like "I'm not going anymore" to planned/social memories.

    Returns short labels for canceled or muted memories. Empty means the text
    did not look like a cancellation or nothing matched safely.
    """
    if person_id is None:
        try:
            person_id = consciousness.get_last_memory_hint_target()
        except Exception:
            person_id = None
    if person_id is None or not events_memory.looks_like_cancellation(text):
        return []

    labels: list[str] = []
    event_hint_name = ""
    effective_event_hint = event_hint
    if event_hint:
        event_hint_name = (event_hint.get("event_name") or "").strip()
    elif not _has_specific_memory_token(text):  # generic "I'm not going anymore"
        event_hint_name = _recent_rex_memory_hint()
        if event_hint_name:
            effective_event_hint = {"event_name": event_hint_name}

    try:
        canceled = events_memory.cancel_matching_events(
            int(person_id),
            text,
            event_hint=effective_event_hint,
        )
    except Exception as exc:
        _log.debug("event cancellation matching failed: %s", exc)
        canceled = []

    # Token matching found nothing but Rex JUST raised an event — a garbled
    # decode of the event name defeats exact-token overlap (field 2026-08-02
    # 10:53: "We're not going to like falsum anymore" right after the Lake
    # Folsom greeting shared no token with the stored plan, so it survived to
    # be re-anticipated at 13:05). The cancellation almost certainly targets
    # the thing Rex brought up seconds ago; retry with that line as the hint.
    if not canceled and effective_event_hint is None:
        hint = _recent_rex_memory_hint()
        if hint:
            event_hint_name = hint
            try:
                canceled = events_memory.cancel_matching_events(
                    int(person_id),
                    text,
                    event_hint={"event_name": hint},
                )
                if canceled:
                    _log.info(
                        "[events] cancellation matched via recent Rex memory "
                        "hint (garbled/no token overlap): %r", hint,
                    )
            except Exception as exc:
                _log.debug("hint-fallback cancellation matching failed: %s", exc)

    if canceled:
        try:
            ids = {int(ev["id"]) for ev in canceled if ev.get("id") is not None}
            consciousness.drop_pending_followups(int(person_id), ids)
        except Exception as exc:
            _log.debug("drop canceled pending followups failed: %s", exc)
        for ev in canceled:
            name = (ev.get("event_name") or "").strip()
            if name:
                labels.append(name)

    try:
        muted = emotional_events.mute_matching_positive_events(
            int(person_id),
            text,
            reason=text,
            event_hint=event_hint_name,
        )
    except Exception as exc:
        _log.debug("positive emotional event mute failed: %s", exc)
        muted = []
    for ev in muted:
        desc = (ev.get("description") or "").strip()
        if desc:
            labels.append(desc)

    # Keep order but remove duplicates.
    seen: set[str] = set()
    unique: list[str] = []
    for label in labels:
        key = label.lower()
        if key in seen:
            continue
        seen.add(key)
        unique.append(label)
    if unique:
        _log.info(
            "[memory] canceled/staled event memory for person_id=%s: %s",
            person_id,
            "; ".join(unique),
        )
    return unique


def _event_cancellation_ack(labels: list[str], person_id: Optional[int]) -> str:
    """Warm, not smug (owner note 2026-08-02: 'good, because paddleboarding was
    already doing the most' is the wrong energy for a cancelled fun plan —
    sympathize, then ask what they're doing instead)."""
    del person_id
    label = labels[0] if labels else "that plan"
    return (
        f"Ah, that's a shame — {label} sounded like fun. "
        "You lining up something else instead?"
    )


# "That was JT speaking" / "that wasn't me, that was JT" — a speaker-attribution
# correction. Tight on purpose: the name must end the sentence or be followed by
# speaking/talking, so "that was JT's idea" or "that was great" never match.
_SPEAKER_CORRECTION_PAT = re.compile(
    r"^\s*(?:no[,.\s]+)?"
    # Either the full denial lead ("that wasn't me, that was ") or a plain lead
    # ("that was " / "that's " / "it was ").
    r"(?:that\s+was(?:n'?t|\s+not)\s+me[,.\s]+(?:that\s+was|it\s+was)\s+"
    r"|(?:that\s+(?:was|is)|that'?s|it\s+was)\s+)"
    # Lazy optional second word: under IGNORECASE a [A-Z] class can't fence off
    # "speaking"/"talking", so keep the name minimal and let the tail claim those.
    r"(?P<name>[A-Za-z][\w'.-]*(?:\s+[A-Za-z][\w'.-]*)??)"
    r"\s*(?:speaking|talking|who\s+(?:said|was\s+speaking)\s+that)?\s*[.!]?\s*$",
    re.IGNORECASE,
)
_SPEAKER_CORRECTION_PREFIX_PAT = re.compile(
    r"^\s*(?:no[,.\s]+)?that\s+was(?:n'?t|\s+not)\s+me\b", re.IGNORECASE
)
# Words that positively signal a correction even without the wasn't-me prefix.
_SPEAKER_CORRECTION_TAIL_PAT = re.compile(r"\b(speaking|talking)\s*[.!]?\s*$", re.IGNORECASE)
_CORRECTION_NON_NAMES = {
    "me", "you", "him", "her", "them", "it", "rex", "r3x", "great", "good", "funny",
    "loud", "weird", "nothing", "nobody", "someone", "somebody", "wrong", "right",
}


def _handle_speaker_correction(
    text: str, person_id: Optional[int], person_name: Optional[str]
) -> Optional[str]:
    """Handle "that was <Name> (speaking)" / "that wasn't me, that was <Name>".

    Field log 2026-07-05: JT's line was credited to Bret; Bret said "That was JT
    speaking" and Rex just bantered — the transcript (and therefore session-end
    memory extraction) kept the wrong attribution. Now the correction MOVES the
    previous turn's speaker label and acks it. Returns the ack line, or None if the
    utterance isn't a correction."""
    cleaned = (text or "").strip()
    if not cleaned:
        return None
    m = _SPEAKER_CORRECTION_PAT.match(cleaned)
    if not m:
        return None
    # Require a positive correction signal: either the "that wasn't me" prefix or a
    # speaking/talking tail — a bare "that was Jeff" is too ambiguous mid-conversation.
    if not (_SPEAKER_CORRECTION_PREFIX_PAT.match(cleaned)
            or _SPEAKER_CORRECTION_TAIL_PAT.search(cleaned)):
        return None
    name = (m.group("name") or "").strip().rstrip(".!,")
    if not name or name.lower() in _CORRECTION_NON_NAMES:
        return None
    # Canonicalize against known people when possible (keeps transcript labels stable).
    display = name
    try:
        from memory import people as people_db_mod
        row = people_db_mod.find_person_by_name(name)
        if row and row.get("name"):
            display = str(row["name"])
            # Human-confirmed attribution → anchor voice continuity for that person.
            if row.get("id") is not None:
                _last_confident_voice_at[int(row["id"])] = time.monotonic()
    except Exception:
        pass
    moved = False
    if person_name:
        try:
            moved = conv_memory.relabel_prior_turn(person_name, display, skip_text=cleaned)
        except Exception as exc:
            _log.debug("speaker-correction relabel failed: %s", exc)
    _log.info(
        "[interaction] speaker correction: previous turn reattributed %r -> %r (moved=%s)",
        person_name, display, moved,
    )
    first = display.split()[0]
    if moved:
        return f"Ah — that was {first} talking. Logged to the right organic this time."
    return f"Got it — {first} said that, not you. I'll keep my wires straight."


def _handle_conversation_boundary(
    person_id: Optional[int],
    text: str,
) -> Optional[str]:
    """Store durable conversational boundaries like "don't ask about work"."""
    if person_id is None or not text:
        return None
    try:
        detected = boundary_memory.detect_boundary(
            text,
            fallback_topic=_boundary_fallback_topic(exclude_text=text),
        )
        if not detected:
            return None
        # A durable add whose topic never resolved past the placeholder (pronoun
        # form + no usable live thread) must not store a junk "current topic" row —
        # treat it as the transient steer it effectively is.
        if (
            detected.get("action") == "add"
            and detected.get("kind") == "boundary"
            and str(detected.get("topic") or "") == "current topic"
        ):
            detected = dict(detected, kind="subject_change")
        if action_router.tool_router_owns("emotional.boundary"):
            # Phase 2b (2026-08-13): this function stops CONSUMING the turn. It ran
            # before the LLM ever saw the utterance, wrote a durable
            # person_conversation_boundaries row, muted matching check-in events,
            # retired callback premises and answered with a canned sentence — all
            # from a regex. Measured against this checkout, that meant
            # "Don't ask me how I got it, long story." (an INVITATION) stored a
            # permanent never-ask row, and "Let's talk about the topic of my
            # dissertation." tripped the change-the-subject family and steered Rex
            # AWAY from the one topic just requested.
            #
            # The split is deliberate, and it is the same one 6267d38 drew: the
            # REVERSIBLE half stays deterministic, the DURABLE half goes to the
            # model. _apply_topic_boundary_side_effects still fires here — a 90s
            # in-memory proactive ban plus clearing steering/topic-thread — so Rex
            # stops raising the topic THIS turn even if the model declines the tool.
            # The durable row is written by the emotional_boundary tool call, and
            # the context the model needs is already in front of it: lean_brain.
            # _person_lines renders boundaries.summarize_for_prompt AND the
            # recently_banned_topics directive, so no new plumbing is required.
            #
            # Returning None hands the turn to the reply call, which is what stops
            # the canned "Understood. I won't bring up X unless you do." from being
            # the whole answer. Offline, or with the kill switch off, everything
            # below runs exactly as it did before.
            topic = str(detected.get("topic") or "").strip()
            _apply_topic_boundary_side_effects(
                person_id, text,
                banned_topic=topic if topic not in {"", "current topic", "anything"} else None,
            )
            _log.info(
                "[boundaries] detected %s topic=%r handed to the tool router",
                detected.get("kind"), topic,
            )
            return None
        if detected.get("kind") == "subject_change":
            # "Can we talk about something else?" is a TRANSIENT steer, not a durable
            # consent rule — don't persist a boundary (the old path stored garbage like
            # topic='can / talk' scraped from the request itself and answered with the
            # robotic "I won't bring up can / talk"). Ban the CURRENT thread from
            # proactive lines briefly, then actually CHANGE THE SUBJECT.
            topic = str(detected.get("topic") or "").strip()
            if topic and topic not in {"current topic", "anything"}:
                _apply_topic_boundary_side_effects(person_id, text, banned_topic=topic)
            try:
                from intelligence import lean_brain as _lb
                angle = random.choice(_lb._FRESH_ANGLES)
            except Exception:
                angle = "something they're genuinely into lately"
            return llm.get_response(
                "The user just asked to change the subject — they're a little tired of "
                "the current one. Do it gracefully: a TINY acknowledgment (a few words, "
                "no apology tour), then open ONE genuinely new thread in your own voice. "
                f"Suggested fresh angle (use it only if it fits): {angle}. Do NOT return "
                "to the old topic. Two short Rex-style sentences max, ending with an "
                "easy question.",
                person_id,
            )
        applied = boundary_memory.apply_detected_boundary(person_id, detected)
        if not applied:
            return None
        topic = applied.get("topic") or "that"
        topic_phrase = "how you're doing" if topic == "how are you" else topic
        action = applied.get("action")
        behavior = applied.get("behavior") or "mention"
        if action == "clear":
            return f"Got it. {topic_phrase} is back on the table, cautiously."
        _apply_topic_boundary_side_effects(person_id, text, banned_topic=topic)
        if behavior == "roast":
            return f"Noted. I won't roast you about {topic_phrase}."
        if behavior == "ask":
            return f"Got it. I won't ask about {topic_phrase} unless you bring it up."
        return f"Understood. I won't bring up {topic_phrase} unless you do."
    except Exception as exc:
        _log.debug("conversation boundary handler failed: %s", exc)
        return None


_TOPIC_BAN_STOPWORDS = {
    # articles / preps / conjunctions
    "the", "a", "an", "and", "or", "of", "to", "in", "on", "at", "for", "with",
    "from", "into", "about", "but", "so", "as", "by",
    # pronouns / possessives
    "my", "your", "you", "yours", "me", "we", "us", "our", "they", "them",
    "their", "he", "she", "him", "her", "his", "its", "i",
    # question / aux / filler words
    "what", "who", "whom", "whose", "when", "where", "why", "how", "which",
    "is", "are", "am", "was", "were", "be", "been", "being", "do", "does",
    "did", "can", "could", "would", "will", "shall", "should", "have", "has",
    "had", "get", "got", "want", "like", "really", "just", "one", "some",
    "any", "thing", "things", "stuff", "topic", "subject", "current", "exchange",
    "that", "this", "it", "there", "here", "right", "now", "yeah", "okay",
}


def _topic_ban_tokens(topic) -> set[str]:
    # Coerce defensively: callers may hand us a transcript list[dict] or other
    # non-string. Pull text out rather than crashing the turn.
    if isinstance(topic, (list, tuple)):
        topic = " ".join(
            str(e.get("text", "") if isinstance(e, dict) else e) for e in topic
        )
    elif not isinstance(topic, str):
        topic = str(topic or "")
    return {
        w
        for w in re.findall(r"[a-z]+", topic.lower())
        if len(w) > 2 and w not in _TOPIC_BAN_STOPWORDS
    }


def _record_banned_topic(topic: Optional[str]) -> None:
    """Mark a just-dropped topic so proactive lines stop re-raising it."""
    if not topic:
        return
    label = str(topic).strip()
    tokens = _topic_ban_tokens(label)
    if not tokens:
        return  # generic 'that'/'this' carries nothing to match against
    cooldown = float(getattr(config, "TOPIC_BAN_COOLDOWN_SECS", 90.0) or 0.0)
    now = time.monotonic()
    # Prune expired entries here (write side) so the cross-thread read stays a
    # pure filter, and keep the list bounded.
    fresh = [b for b in _recently_banned_topics if b.get("banned_until", 0.0) > now]
    fresh.append({"topic": label, "tokens": tokens, "banned_until": now + cooldown})
    _recently_banned_topics[:] = fresh[-8:]
    _log.info("[topic_ban] %r banned from proactive for %.0fs", label, cooldown)


def recently_banned_topics() -> list[dict]:
    """Active topic bans (filters out expired entries). Read by the proactive/idle
    layer AND the LLM prompt assembly (another thread), so this is a pure read —
    no slice-assign back — to avoid a read-modify-write race. Pruning happens at
    write time in _record_banned_topic and on session reset."""
    now = time.monotonic()
    return [b for b in list(_recently_banned_topics) if b.get("banned_until", 0.0) > now]


def _topic_is_recently_banned(text: str) -> bool:
    """True when the given text/topic overlaps an active proactive topic ban."""
    bans = recently_banned_topics()
    if not bans:
        return False
    toks = _topic_ban_tokens(text or "")
    if not toks:
        return False
    return any(toks & b.get("tokens", set()) for b in bans)


def _apply_topic_boundary_side_effects(
    person_id: Optional[int], text: str, *, banned_topic: Optional[str] = None
) -> None:
    """Stop proactive continuation when the human closes or rejects a topic."""
    # Capture the live topic BEFORE clearing so the ban carries the real subject.
    # exclude_text=text: never let the ban label be derived from the ban request's
    # own words (field 2026-08-03 20:03: the thread label had become "don't / need"
    # — the request's keywords — so the ban protected nothing while the website
    # stayed fair game).
    if banned_topic is None:
        try:
            banned_topic = _boundary_fallback_topic(exclude_text=text)
        except Exception:
            banned_topic = None
    _record_banned_topic(banned_topic)
    try:
        conversation_steering.clear(person_id)
    except Exception as exc:
        _log.debug("clear conversation steering after boundary failed: %s", exc)
    try:
        topic_thread.clear()
    except Exception as exc:
        _log.debug("clear topic thread after boundary failed: %s", exc)
    try:
        premise_memory.clear()
    except Exception as exc:
        _log.debug("clear premise memory after boundary failed: %s", exc)
    try:
        end_thread.note_user_turn(text, person_id)
    except Exception as exc:
        _log.debug("end-thread boundary grace failed: %s", exc)


def _boundary_fallback_topic(exclude_text: Optional[str] = None) -> Optional[str]:
    """Best current topic for generic boundaries like 'don't ask me that again'.

    exclude_text (the boundary request itself, when the caller has it) rejects any
    candidate whose ban tokens ALL come from that request — a thread label scraped
    from "we don't need to bring it up" names no real topic, and banning it lets
    the actual subject sail on unbanned."""
    def _derived_from_request(candidate: Optional[str]) -> bool:
        if not candidate or not exclude_text:
            return False
        cand_toks = _topic_ban_tokens(candidate)
        if not cand_toks:
            return True   # nothing bannable in it anyway
        return cand_toks <= _topic_ban_tokens(exclude_text)
    if _pending_face_reveal_confirm is not None:
        return "face"
    if _pending_offscreen_identify is not None:
        return "identity"
    if (
        _pending_introduction is not None
        or _pending_dual_intro is not None
        or _pending_intro_followup is not None
        or _pending_intro_voice_capture is not None
        or _pending_common_first_name_identity is not None
        or _pending_common_first_name_introduction is not None
        or _pending_existing_common_first_name is not None
        or _pending_identity_match_confirmation is not None
        or _pending_prompted_name_confirmation is not None
    ):
        return "introductions"
    try:
        pending_rel = consciousness.get_pending_relationship_context()
        if pending_rel:
            return "relationships"
    except Exception:
        pass
    try:
        thread = topic_thread.snapshot() or {}
        label = str(thread.get("label") or "").strip()
        if label and label.lower() not in {
            "current exchange", "current topic", "the current exchange",
        } and not _derived_from_request(label):
            return label
    except Exception:
        pass
    try:
        # Normalize the candidates through the ban tokenizer too — raw thread
        # tokens can carry steering words ("subject", "don't") that must never
        # become the banned "topic".
        toks = _topic_ban_tokens(" ".join(topic_thread.topic_tokens()))
        if exclude_text:
            toks = toks - _topic_ban_tokens(exclude_text)
        if toks:
            return max(toks, key=len)  # best-effort topic word
    except Exception:
        pass
    return None


def _dismiss_pending_consent_prompts(person_id: Optional[int], reason: str) -> None:
    """Close optional pending prompts when a person sets a boundary or declines."""
    global _pending_face_reveal_confirm, _pending_offscreen_identify
    global _pending_introduction, _pending_intro_followup, _pending_intro_voice_capture
    global _pending_common_first_name_identity, _pending_common_first_name_introduction
    global _pending_existing_common_first_name, _pending_identity_match_confirmation
    global _pending_last_name_confirm
    global _pending_prompted_name_confirmation

    if person_id is not None:
        try:
            declined = rel_memory.decline_latest_pending_question(person_id, reason=reason)
            if declined:
                _log.info(
                    "[boundaries] declined pending Q&A person_id=%s key=%r reason=%r",
                    person_id,
                    declined.get("question_key"),
                    reason,
                )
        except Exception as exc:
            _log.debug("decline pending Q&A failed: %s", exc)

    if _pending_face_reveal_confirm is not None:
        if person_id is None or _pending_face_reveal_confirm.get("person_id") == person_id:
            _face_reveal_declined.add(_pending_face_reveal_confirm["person_id"])
            _pending_face_reveal_confirm = None
    if _pending_offscreen_identify is not None:
        _pending_offscreen_identify = None
    global _pending_dual_intro
    if _pending_dual_intro is not None:
        _pending_dual_intro = None
    if _pending_introduction is not None:
        _pending_introduction = None
    if _pending_intro_followup is not None:
        _pending_intro_followup = None
    if _pending_intro_voice_capture is not None:
        _pending_intro_voice_capture = None
    if _pending_common_first_name_identity is not None:
        _pending_common_first_name_identity = None
    if _pending_common_first_name_introduction is not None:
        _pending_common_first_name_introduction = None
    if _pending_existing_common_first_name is not None:
        if (
            person_id is None
            or _pending_existing_common_first_name.get("person_id") == person_id
        ):
            try:
                _common_first_name_prompted_this_session.add(
                    int(_pending_existing_common_first_name["person_id"])
                )
            except Exception:
                pass
            _pending_existing_common_first_name = None
    if _pending_identity_match_confirmation is not None:
        _pending_identity_match_confirmation = None
    if _pending_prompted_name_confirmation is not None:
        _pending_prompted_name_confirmation = None


def _correction_routes_to_query(correction: Optional[str]) -> bool:
    """True when a repair CORRECTION restates a routable query/command (weather, time, capabilities,
    memory, …). Lets 'no I said what's the weather' re-run the weather query instead of firing a
    repair-ack and stranding the user (field bug: they had to ask a third time). Reuses the
    deterministic intent classifier — no duplicated pattern list, and it stays 'general' (→ False)
    for plain restated statements like 'no I said I went to my dad's', which correctly keep the ack."""
    text = (correction or "").strip()
    if not text or not getattr(config, "INTENT_CLASSIFIER_ENABLED", False):
        return False
    try:
        intent = intent_classifier.classify_deterministic(text)
    except Exception:
        return False
    return bool(intent) and intent != "general"


def _generate_repair_response(person_id: Optional[int], text: str, repair: dict) -> str:
    """Generate one concise recovery when the human flags a conversational miss."""
    kind = repair.get("kind")
    if kind == "pronoun":
        _maybe_store_pronoun_repair(person_id, text)
    # ASR / comprehension miss with NO corrected words supplied: the human is telling us
    # we got it wrong but hasn't re-said it, so save face with a quick circuit-glitch joke
    # and invite them to repeat (varied) instead of 'owning it and moving on'.
    if kind in {"misheard", "misunderstood"} and not repair_moves.correction_has_content(
        repair.get("correction")
    ):
        response = repair_moves.misheard_recovery_response()
    else:
        prompt = repair_moves.build_prompt(repair)
        try:
            response = llm.get_response(prompt, person_id)
        except Exception as exc:
            _log.debug("repair response generation failed: %s", exc)
            response = ""
        response = (response or "").strip()
        if not response:
            response = repair_moves.fallback_response(repair)
        if repair_moves.should_use_better_luck_line(repair):
            response = repair_moves.add_better_luck_line(
                response, repair.get("recovery_line")
            )
    _play_event_body_beat("repair", repair_kind=str(repair.get("kind") or ""))
    _speak_blocking(
        response,
        emotion="neutral",
        pre_beat_ms=150,
        post_beat_ms_override=300,
    )
    repair_moves.mark_handled(repair.get("kind") or "")
    _log.info(
        "[repair] handled kind=%s severity=%s correction=%r user=%r response=%r",
        repair.get("kind"),
        repair.get("severity"),
        repair.get("correction"),
        text,
        response,
    )
    return response


def _maybe_store_pronoun_repair(person_id: Optional[int], text: str) -> None:
    """Persist explicit pronoun corrections for future group-cast prompts."""
    cleaned = (text or "").strip()
    if not cleaned:
        return

    target_id = None
    pronouns = None

    self_match = _PRONOUN_SELF_RE.search(cleaned)
    if self_match and person_id is not None:
        target_id = person_id
        pronouns = self_match.group(1)

    if target_id is None:
        named_match = _PRONOUN_NAMED_RE.search(cleaned)
        if named_match:
            name = named_match.group(1)
            if name.lower() not in {"he", "she", "they", "i", "my"}:
                try:
                    row = people_memory.find_person_by_name(name)
                    if row and row.get("id") is not None:
                        target_id = int(row["id"])
                        pronouns = named_match.group(2)
                except Exception as exc:
                    _log.debug("pronoun repair name lookup failed: %s", exc)

    if target_id is None:
        third_match = _PRONOUN_THIRD_PERSON_RE.search(cleaned)
        if third_match:
            candidates = []
            try:
                for p in world_state.get("people") or []:
                    pid = p.get("person_db_id")
                    if pid is not None and pid != person_id:
                        candidates.append(int(pid))
            except Exception:
                candidates = []
            if len(candidates) == 1:
                target_id = candidates[0]
                pronouns = third_match.group(1)

    if target_id is None or not pronouns:
        return

    normalized = pronouns.lower()
    if not _PRONOUN_VALUE_RE.fullmatch(normalized):
        return
    try:
        facts_memory.apply_fact_correction(
            int(target_id),
            "pronouns",
            normalized,
            category="identity",
        )
        _log.info(
            "[repair] stored pronoun correction person_id=%s pronouns=%s",
            target_id,
            normalized,
        )
    except Exception as exc:
        _log.debug("pronoun repair fact save failed: %s", exc)


def _apply_local_sensitive_topic_prepass(
    person_id: Optional[int],
    text: str,
) -> Optional[dict]:
    """Cache a same-turn safety mode before the async empathy classifier returns."""
    result = empathy.classify_local_sensitivity(text)
    if not result:
        return None

    # Arm the callback engine's sober-room window: after a heavy disclosure,
    # banked-callback humor stays off for CALLBACK_SUPPRESS_AFTER_HEAVY_SECS —
    # this hook runs on every turn (including grief-flow turns that never
    # reach the callback claim seam).
    try:
        from intelligence import callback_engine as _cb_engine
        _cb_engine.note_heavy_moment()
    except Exception:
        pass

    person_row = None
    if person_id is not None:
        try:
            person_row = people_memory.get_person(person_id)
        except Exception:
            person_row = None

    child_in_scene = False
    try:
        ws_people = world_state.get("people") or []
        child_in_scene = any(
            p.get("age_estimate") == "child" for p in ws_people
        )
    except Exception:
        pass

    mode_pack = empathy.select_mode(
        result,
        person=person_row,
        child_in_scene=child_in_scene,
        person_id=person_id,
    )
    empathy.record(person_id, result, mode_pack)
    _log.info(
        "[empathy] local sensitive prepass affect=%s sens=%s crisis=%s "
        "event=%s → mode=%s",
        result.get("affect"),
        result.get("topic_sensitivity"),
        result.get("crisis"),
        (result.get("event") or {}).get("category"),
        mode_pack.get("mode"),
    )
    return result


def _merge_with_local_sensitive_prepass(
    result: Optional[dict],
    local_result: Optional[dict],
) -> Optional[dict]:
    """Preserve same-turn safety if the slower classifier comes back weaker."""
    if not result or not local_result:
        return result

    rank = {"none": 0, "mild": 1, "heavy": 2}
    result_rank = rank.get((result.get("topic_sensitivity") or "none").lower(), 0)
    local_rank = rank.get((local_result.get("topic_sensitivity") or "none").lower(), 0)
    if bool(local_result.get("crisis")) and not bool(result.get("crisis")):
        return local_result
    if result_rank < local_rank:
        return local_result

    local_event = local_result.get("event")
    if local_event and not result.get("event"):
        merged = dict(result)
        merged["event"] = local_event
        merged["source"] = result.get("source") or "llm_with_local_sensitive_event"
        return merged
    return result


def _maybe_start_grief_flow(
    person_id: Optional[int],
    empathy_event: Optional[dict],
) -> Optional[str]:
    """Return Rex's first-line response if a grief flow should kick off, else None.

    Conditions: person_id known, no active flow already, empathy classified
    a fresh event whose category indicates loss AND has an identifiable
    loss_subject. The structured response replaces the LLM-streamed one for
    this turn; subsequent turns from the same person are routed through
    _continue_grief_flow until the flow closes.
    """
    if person_id is None or empathy_event is None:
        return None
    if _grief_flow_active(person_id):
        return None
    category = (empathy_event.get("category") or "").lower()
    if category not in _GRIEF_FLOW_KEYWORDS:
        return None
    subject = (empathy_event.get("loss_subject") or "").strip().lower()
    if not subject:
        return None
    subject_kind = (empathy_event.get("loss_subject_kind") or "other").lower()
    name = (empathy_event.get("loss_subject_name") or "").strip() or None

    _grief_flow_state[person_id] = {
        "step": "awaiting_consent",
        "subject": subject,
        "subject_kind": subject_kind,
        "name": name,
        "started_at": time.monotonic(),
    }
    _force_grief_empathy(person_id, "grief flow started")

    your_subject = f"your {subject}"
    if name:
        return (
            f"I'm so sorry to hear about {name}. That's a lot. "
            f"Would you like to talk about {'them' if subject_kind != 'pet' else 'them'}?"
        )
    return (
        f"I'm sorry to hear about {your_subject}. "
        f"Would you like to talk about {'them' if subject_kind != 'pet' else 'them'}?"
    )


def _continue_grief_flow(person_id: int, text: str) -> Optional[str]:
    """Advance the grief flow one step. Returns Rex's response or None to fall
    back to the normal LLM path (with empathy directive still applied)."""
    state = _grief_flow_state.get(person_id)
    if not state:
        return None
    step = state.get("step")
    subject = state["subject"]
    subject_kind = state["subject_kind"]
    _force_grief_empathy(person_id, f"grief flow active: {step}")

    if step == "awaiting_consent":
        consent = _classify_consent(text)
        if consent is False:
            _grief_flow_clear(person_id)
            return (
                "Of course. I'm not going anywhere — say the word "
                "if you ever want to."
            )
        if consent is True:
            if state.get("name"):
                # Name was already in the original utterance — skip the name
                # ask, go straight to an open question that invites them to
                # share. The "I'm sorry" condolence already happened on the
                # first turn, so don't repeat it.
                state["step"] = "awaiting_description"
                return f"What were they like?"
            state["step"] = "awaiting_name"
            return f"What was your {subject}'s name?"
        # Ambiguous — don't push. Treat as decline-soft.
        _grief_flow_clear(person_id)
        return (
            "No pressure. I'm here if you want to circle back to it."
        )

    if step == "awaiting_name":
        try:
            name = llm.extract_name_from_reply(text)
        except Exception as exc:
            _log.debug("extract_name_from_reply failed: %s", exc)
            name = None
        if name:
            state["name"] = name
            state["step"] = "awaiting_description"
            # Persist the name onto the most recent emotional event so future
            # sessions and the system-prompt recall layer can use it.
            try:
                rows = _db_fetch_latest_emo_event(person_id)
                if rows:
                    new_desc = rows[0]["description"]
                    if name.lower() not in (new_desc or "").lower():
                        new_desc = f"{new_desc} (name: {name})"
                        _db_update_emo_description(rows[0]["id"], new_desc)
            except Exception as exc:
                _log.debug("emotional event name persist failed: %s", exc)
            return (
                f"I'm so sorry to hear {name} passed. That's got to be "
                f"difficult. What were they like?"
            )
        # No name extracted — gracefully proceed without one.
        state["step"] = "awaiting_description"
        return (
            "I'm so sorry. What were they like?"
        )

    if step == "awaiting_description":
        # Hand back to the normal LLM with the empathy directive intact —
        # the response now has rich context (name, transcript, mode=listen)
        # so the LLM can naturally validate and stay present.
        _grief_flow_clear(person_id)
        return None

    # Unknown step → bail safely.
    _grief_flow_clear(person_id)
    return None


def _db_fetch_latest_emo_event(person_id: int) -> list[dict]:
    from memory import database as _db
    rows = _db.fetchall(
        "SELECT id, description FROM person_emotional_events "
        "WHERE person_id = ? ORDER BY id DESC LIMIT 1",
        (person_id,),
    )
    return [dict(r) for r in rows]


def _db_update_emo_description(event_id: int, new_description: str) -> None:
    from memory import database as _db
    _db.execute(
        "UPDATE person_emotional_events SET description = ? WHERE id = ?",
        (new_description, int(event_id)),
    )


def _curiosity_check(
    response_text: str,
    user_text: str,
    person_id: Optional[int],
    person_name: Optional[str],
) -> Optional[str]:
    """
    After Rex gives a response with no question mark, optionally ask a follow-up.

    Priority:
      1. If the response already contains '?', do nothing.
      2. Roll against CURIOSITY_QUESTION_PROBABILITY — skip on failure.
      3. Try the depth-appropriate question pool for this person.
      4. Fall back to a short contextual LLM question.

    Speaks the question as a separate TTS line (within the caller's AEC sequence)
    and returns the text, or None if nothing was spoken.
    """
    if "?" in response_text:
        if person_id is not None:
            _record_pool_topics_in_response(response_text, person_id)
        return None

    # Empathy gate — never fire a separate snarky follow-up question when the
    # active mode is sympathetic. The curiosity step uses a stand-alone LLM
    # call with no system-prompt scaffolding, so left ungated it produces
    # tone-deaf lines like "guess you'll need a new best friend" right after
    # someone mentions their pet died. Only allow curiosity in modes where
    # snark is appropriate.
    _CURIOSITY_OK_MODES = {"default", "amplify", "lift", "gentle_probe"}
    try:
        cached = empathy.peek(person_id)
    except Exception:
        cached = None
    if cached:
        active_mode = (cached.get("mode") or {}).get("mode", "default")
        if active_mode not in _CURIOSITY_OK_MODES:
            _log.info(
                "[interaction] curiosity_check suppressed — empathy mode=%s "
                "(person_id=%s)",
                active_mode, person_id,
            )
            return None

    try:
        if end_thread.is_grace_active():
            _log.info(
                "[interaction] curiosity_check suppressed — end-of-thread grace "
                "(person_id=%s)",
                person_id,
            )
            return None
    except Exception as exc:
        _log.debug("end-of-thread curiosity check failed: %s", exc)

    try:
        if not question_budget.can_ask("curiosity_followup"):
            _log.info(
                "[interaction] curiosity_check suppressed — question budget full "
                "(person_id=%s)",
                person_id,
            )
            return None
    except Exception as exc:
        _log.debug("question budget curiosity check failed: %s", exc)

    if random.random() >= config.CURIOSITY_QUESTION_PROBABILITY:
        return None

    question_text: Optional[str] = None
    pool_question: Optional[dict] = None

    # Interest steering wins over the generic question pool. If someone just
    # opened a hobby/skill thread, the add-on question should deepen *that*
    # instead of suddenly asking where they are from like a clipboard with LEDs.
    if person_id is not None:
        try:
            steering = conversation_steering.build_context(person_id)
        except Exception as exc:
            _log.debug("curiosity_check steering context failed: %s", exc)
            steering = None
        if steering:
            try:
                question_text = llm.get_response(
                    "Generate ONE short DJ-R3X follow-up question about this "
                    f"person's interest in {steering.topic!r}. It should ask "
                    "about their skill, process, tools, taste, or favorite part. "
                    "Optional: include one tiny subject-specific tidbit if you "
                    "are confident. Funny and snarky is fine, but do not roast "
                    "their competence. Return only the line.",
                    person_id,
                )
                if question_text:
                    pool_question = {
                        "key": f"{steering.fact_key}_followup",
                        "text": question_text,
                        "depth": 1,
                    }
                    try:
                        interests_memory.mark_interest_asked(
                            person_id,
                            steering.topic,
                        )
                    except Exception as exc:
                        _log.debug("curiosity_check mark active interest asked failed: %s", exc)
            except Exception as exc:
                _log.debug("curiosity_check steering question error: %s", exc)

    # Known durable interests are deeper hooks, not basic intake questions.
    if person_id is not None and not question_text:
        try:
            hooks = interests_memory.get_interest_hooks(person_id)
        except Exception as exc:
            _log.debug("curiosity_check interest hooks load error: %s", exc)
            hooks = []
        if hooks:
            hook = hooks[0]
            interest_name = hook.get("name") or ""
            note = hook.get("notes") or hook.get("associated_stories") or ""
            try:
                question_text = llm.get_response(
                    "Generate ONE short DJ-R3X follow-up question about this "
                    f"known interest: {interest_name!r}. "
                    f"Known context: {note!r}. "
                    "Do not ask whether they like it; Rex already knows that. "
                    "Ask a deeper, specific follow-up about what they are making, "
                    "playing, practicing, learning, comparing, or what changed "
                    "since they last mentioned it. Funny and snarky is fine, "
                    "but do not roast their competence. Return only the line.",
                    person_id,
                )
                if question_text:
                    pool_question = {
                        "key": f"interest_{re.sub(r'[^a-z0-9]+', '_', interest_name.lower()).strip('_')}_deep_followup",
                        "text": question_text,
                        "depth": 1,
                    }
                    interests_memory.mark_interest_asked(person_id, interest_name)
            except Exception as exc:
                _log.debug("curiosity_check known interest question error: %s", exc)

    # Try question pool first — structured, depth-gated, no extra LLM call
    if person_id is not None and not question_text:
        try:
            person = people_memory.get_person(person_id)
            tier = (person.get("friendship_tier", "stranger") if person else "stranger")
            max_depth = config.TIER_MAX_DEPTH.get(tier, 1)
            asked = rel_memory.get_asked_question_keys(person_id)

            # Load all known facts once so we can skip questions whose topic is
            # already covered — e.g. don't ask about job if a job fact exists.
            known_fact_keys: set[str] = set()
            known_fact_categories: set[str] = set()
            try:
                for fact in facts_memory.get_facts(person_id):
                    known_fact_keys.add(fact["key"])
                    known_fact_categories.add(fact["category"])
            except Exception as exc:
                _log.debug("curiosity_check facts load error: %s", exc)

            for candidate in config.QUESTION_POOL:
                if candidate["depth"] > max_depth:
                    continue
                if candidate["key"] in asked:
                    continue
                # Skip if Rex already knows something about this topic
                q_key = candidate["key"]
                if q_key in known_fact_keys or q_key in known_fact_categories:
                    _log.debug(
                        "curiosity_check: skipping %r — fact already recorded", q_key
                    )
                    continue
                if q_key in {"hobbies", "favorite_music", "favorite_movie"}:
                    try:
                        if interests_memory.get_interests_for_prompt(person_id, limit=1):
                            _log.debug(
                                "curiosity_check: skipping %r — interests already recorded",
                                q_key,
                            )
                            continue
                    except Exception as exc:
                        _log.debug("curiosity_check interest skip failed: %s", exc)
                if _question_blocked_by_boundary(person_id, candidate):
                    _log.info(
                        "[boundaries] curiosity_check suppressed question=%r for person_id=%s",
                        q_key,
                        person_id,
                    )
                    continue
                question_text = candidate.get("text", "")
                pool_question = candidate
                break
        except Exception as exc:
            _log.debug("curiosity_check pool error: %s", exc)

    # LLM fallback — contextual question when pool is empty or person is unknown
    if not question_text:
        if person_id is not None:
            try:
                if boundary_memory.is_blocked(person_id, "ask", "questions"):
                    _log.info(
                        "[boundaries] curiosity_check LLM fallback suppressed — questions blocked person_id=%s",
                        person_id,
                    )
                    return None
            except Exception as exc:
                _log.debug("curiosity fallback boundary check failed: %s", exc)
        try:
            question_text = llm.generate_curiosity_question(response_text, user_text, person_id)
        except Exception as exc:
            _log.debug("curiosity_check LLM error: %s", exc)

    if not question_text or not question_text.strip():
        return None

    _speak_blocking(question_text)
    _log.info("[interaction] curiosity question spoken: %r", question_text)

    # Record pool question as asked immediately so get_next_question() won't
    # return it again in this session. Answer is empty — updated later if the
    # person responds; what matters now is the key is in the DB.
    if pool_question is not None and person_id is not None:
        try:
            rel_memory.save_question_asked(
                person_id,
                pool_question["key"],
                question_text,
                pool_question.get("depth", 1),
            )
        except Exception as exc:
            _log.debug("curiosity_check save_qa error: %s", exc)

    return question_text


def _maybe_capture_pending_qa(
    person_id: Optional[int],
    text: str,
    *,
    identity_prompt_active: bool = False,
) -> Optional[dict]:
    """
    If Rex asked this person a curiosity question on the previous turn, treat
    this utterance as the answer and store it before generating the next reply.
    """
    if person_id is None:
        return None
    cleaned = (text or "").strip()
    if not cleaned:
        return None
    if identity_prompt_active:
        return None
    if _pending_offscreen_identify is not None or _pending_face_reveal_confirm is not None:
        return None
    if _awaiting_followup_event is not None:
        return None
    if command_parser.parse(cleaned) is not None:
        return None
    if _EMOTIONAL_BOUNDARY_PAT.search(cleaned):
        return None
    if _looks_like_incomplete_pending_answer(cleaned):
        _log.info(
            "[interaction] pending Q&A capture held — incomplete fragment %r",
            cleaned,
        )
        return None
    # If the user is asking a new question instead of answering Rex's last one,
    # leave the pending question open. Real conversations branch sometimes.
    if "?" in cleaned:
        return None
    # A compliment ("you're a nice droid") is about Rex, not an answer to his
    # question — don't swallow it as the pending Q&A answer, so the compliment
    # reaction (proud body mood + chest white→blue flash) still fires downstream.
    if personality.is_obvious_compliment(cleaned):
        _log.info(
            "[interaction] pending Q&A capture held — utterance is a compliment %r",
            cleaned,
        )
        return None
    try:
        answered = rel_memory.answer_latest_pending_question(person_id, cleaned)
        if answered:
            _log.info(
                "[interaction] captured answer to pending Q&A — person_id=%s "
                "key=%r answer=%r",
                person_id,
                answered.get("question_key"),
                cleaned[:160],
            )
            if answered.get("question_key") == "startup_conversation_steering":
                try:
                    conversation_steering.note_bare_interest_answer(
                        person_id,
                        cleaned,
                        source="startup_steering_answer",
                    )
                except Exception as exc:
                    _log.debug("startup steering answer capture failed: %s", exc)
            elif conversation_steering.is_interest_seed_question(
                answered.get("question_key")
            ):
                # Answer to a profile interest question (obsession/hobbies/music/
                # …) — seed it as the active topic so Rex deepens it with real
                # curiosity instead of a throwaway quip.
                try:
                    conversation_steering.seed_from_answer(
                        person_id,
                        cleaned,
                        answered.get("question_key"),
                    )
                except Exception as exc:
                    _log.debug("interest-seed answer capture failed: %s", exc)
        return answered
    except Exception as exc:
        _log.debug("pending Q&A capture failed: %s", exc)
        return None


_INCOMPLETE_PENDING_ANSWER_PAT = re.compile(
    r"^\s*(?:"
    r"i\s+(?:like|love|want|think|mean|prefer|would|was|am|have|had|feel)|"
    r"i'?d\s+(?:like|love|rather)|"
    r"my|the|it(?:'?s| is)?|because|when|what i"
    r")\s*$",
    re.IGNORECASE,
)


def _looks_like_incomplete_pending_answer(text: str) -> bool:
    cleaned = (text or "").strip()
    if not cleaned:
        return False
    return bool(_INCOMPLETE_PENDING_ANSWER_PAT.match(cleaned))


def _looks_like_startup_steering_question(question: str) -> bool:
    q = (question or "").lower()
    return any(
        phrase in q
        for phrase in (
            "what topic",
            "what corner",
            "what mission",
            "what problem",
            "what are you up to",
            "what do you want to talk",
            "what should we talk",
            "what are we discussing",
            "discussing first",
            "what's been rolling around",
            "what’s been rolling around",
            "been rolling around in your mind",
            "in your mind today",
            "what's on your mind",
            "what’s on your mind",
            "what is on your mind",
        )
    )


def _maybe_capture_topic_thread_answer(
    person_id: Optional[int],
    text: str,
    *,
    identity_prompt_active: bool = False,
) -> Optional[dict]:
    """Fallback answer capture when Rex's latest question lives only in thread state."""
    if person_id is None or identity_prompt_active:
        return None
    cleaned = (text or "").strip()
    if not cleaned or "?" in cleaned:
        return None
    if command_parser.parse(cleaned) is not None:
        return None
    try:
        snap = topic_thread.snapshot() or {}
        question = str(snap.get("unresolved_question") or "").strip()
    except Exception:
        question = ""
    if not question or not _looks_like_startup_steering_question(question):
        return None
    try:
        ctx = conversation_steering.note_bare_interest_answer(
            person_id,
            cleaned,
            source="startup_thread_answer",
        )
    except Exception as exc:
        _log.debug("topic-thread steering answer capture failed: %s", exc)
        ctx = None
    if ctx is None:
        answered = {
            "question_key": "startup_conversation_steering_reply",
            "question_text": question,
            "answer_text": cleaned,
            "depth_level": 1,
            "source": "topic_thread",
        }
        _log.info(
            "[interaction] captured topic-thread reply without storing interest — "
            "person_id=%s key=%r answer=%r",
            person_id,
            answered["question_key"],
            cleaned[:160],
        )
        return answered
    answered = {
        "question_key": "startup_conversation_steering",
        "question_text": question,
        "answer_text": cleaned,
        "depth_level": 1,
        "source": "topic_thread",
    }
    _log.info(
        "[interaction] captured topic-thread answer — person_id=%s "
        "key=%r answer=%r",
        person_id,
        answered["question_key"],
        cleaned[:160],
    )
    return answered


def _latest_pending_question(person_id: Optional[int]) -> Optional[dict]:
    if person_id is None:
        return None
    try:
        return rel_memory.get_latest_pending_question(person_id)
    except Exception as exc:
        _log.debug("pending Q&A lookup failed: %s", exc)
        return None


def _store_music_preference_fact(person_id: Optional[int], preference: str) -> None:
    if person_id is None:
        return
    cleaned = (preference or "").strip()
    if not cleaned:
        return
    try:
        facts_memory.add_fact(
            person_id,
            "preference",
            "favorite_music",
            cleaned,
            "pending_qa:favorite_music",
            confidence=0.95,
        )
    except Exception as exc:
        _log.debug("favorite_music fact save failed: %s", exc)


_MUSIC_PREFERENCE_LEADING_PATTERNS = (
    re.compile(
        r"^\s*i\s+(?:really\s+|kind\s+of\s+|sort\s+of\s+)?"
        r"(?:like|love|enjoy|prefer|am\s+into|am\s+interested\s+in|listen\s+to)\s+",
        re.IGNORECASE,
    ),
    re.compile(
        r"^\s*i['’]?m\s+(?:really\s+|kind\s+of\s+|sort\s+of\s+)?"
        r"(?:into|a\s+fan\s+of)\s+",
        re.IGNORECASE,
    ),
    re.compile(
        r"^\s*my\s+(?:favorite|favourite)\s+"
        r"(?:kind|type|style|genre)?\s*(?:of\s+)?music\s+(?:is|would\s+be|has\s+to\s+be)\s+",
        re.IGNORECASE,
    ),
    re.compile(
        r"^\s*(?:probably|mostly|usually|mainly|generally)?\s*"
        r"(?:i\s+)?(?:would\s+say|guess|think)\s+",
        re.IGNORECASE,
    ),
)


def _normalize_music_preference_answer(text: str) -> str:
    cleaned = (text or "").strip()
    if not cleaned:
        return ""
    cleaned = cleaned.strip(" \t\r\n\"'“”‘’")
    cleaned = re.sub(r"\s+", " ", cleaned)
    cleaned = re.sub(r"[.!?]+$", "", cleaned).strip()

    changed = True
    while changed:
        changed = False
        for pattern in _MUSIC_PREFERENCE_LEADING_PATTERNS:
            updated = pattern.sub("", cleaned, count=1).strip()
            if updated != cleaned:
                cleaned = updated
                changed = True

    cleaned = re.sub(r"^(?:some|the|a|an)\s+", "", cleaned, flags=re.IGNORECASE).strip()
    cleaned = re.sub(r"\s+(?:music|stuff|songs|tracks|artists|bands)$", "", cleaned, flags=re.IGNORECASE).strip()
    cleaned = re.sub(r"\s+", " ", cleaned).strip(" ,;:-")
    return cleaned or (text or "").strip().rstrip(".!?")


def _music_offer_reply(preference: str) -> str:
    cleaned = (preference or "").strip().rstrip(".!?")
    if not cleaned:
        cleaned = "that"
    return f"Good to know. Want me to play some {cleaned}, or keep the jukebox muzzled?"


def _music_offer_play_response(track, preference: str) -> str:
    name = getattr(track, "name", "") or preference
    return f"Yes detected. Spinning {name} now."


def _handle_pending_music_offer_reply(
    person_id: Optional[int],
    text: str,
) -> Optional[str]:
    """Handle yes/no replies to Rex's follow-up music offer."""
    global _pending_music_offer
    offer = _pending_music_offer
    if not offer:
        return None

    ttl = float(getattr(config, "MUSIC_OFFER_REPLY_WINDOW_SECS", 25.0))
    if time.monotonic() - float(offer.get("asked_at") or 0.0) > ttl:
        _pending_music_offer = None
        return None

    if offer.get("person_id") is not None and person_id != offer.get("person_id"):
        return None

    consent = _classify_consent(text)
    if consent is None:
        return None

    preference = str(offer.get("music_query") or "").strip()
    _pending_music_offer = None

    if consent is False:
        resp = "Got it. I logged the taste and spared the room a soundtrack ambush."
        _speak_blocking(resp, emotion="neutral")
        return resp

    try:
        from features import dj as dj_mod
        track = dj_mod.handle_request(preference)
    except Exception as exc:
        _log.debug("pending music offer lookup failed: %s", exc)
        track = None

    if track is None:
        resp = f"I logged {preference} as your taste, but I can't find a station for it yet."
        _speak_blocking(resp, emotion="neutral")
        return resp

    resp = _music_offer_play_response(track, preference)
    _speak_blocking(resp, emotion="happy")
    _start_dj_after_response(track)
    return resp


def _handle_pending_music_preference_answer(
    person_id: Optional[int],
    text: str,
    *,
    pending_question: Optional[dict],
    identity_prompt_active: bool = False,
) -> tuple[Optional[str], Optional[dict]]:
    """
    Consume answers to Rex's music-preference question before the action router.

    A bare genre/artist/style is a memory answer. Rex asks for explicit consent
    before starting playback, so "classical music" cannot accidentally become
    a DJ command.
    """
    global _pending_music_offer
    if person_id is None or not pending_question:
        return None, None
    if pending_question.get("question_key") != "favorite_music":
        return None, None
    if identity_prompt_active:
        return None, None

    cleaned = (text or "").strip()
    if not cleaned or "?" in cleaned:
        return None, None
    preference = _normalize_music_preference_answer(cleaned)
    if not preference:
        return None, None

    answered = _maybe_capture_pending_qa(
        person_id,
        preference,
        identity_prompt_active=identity_prompt_active,
    )
    if not answered:
        return None, None

    _store_music_preference_fact(person_id, preference)

    if _MUSIC_PLAY_REQUEST_PAT.search(cleaned):
        return None, answered

    _pending_music_offer = {
        "person_id": person_id,
        "music_query": preference,
        "asked_at": time.monotonic(),
    }
    resp = _music_offer_reply(preference)
    _speak_blocking(resp, emotion="neutral")
    return resp, answered


# ─────────────────────────────────────────────────────────────────────────────
# Intent-routed local responses (LLM fallback path)
# ─────────────────────────────────────────────────────────────────────────────

def _vision_question_target_hint(text: str) -> str:
    """Extract a target hint from a visual question for the vision prompt."""
    cleaned = " ".join((text or "").lower().split())
    if re.search(r"\b(?:holding|in my hand|showing)\b", cleaned):
        return "the object the person is holding up or showing to the camera"
    if re.search(r"\b(?:wearing|outfit|my shirt|my hat)\b", cleaned):
        return "what the person is wearing"
    m = re.search(
        r"\b(?:see|look(?:ing)? at|check out)\s+"
        r"(?:my|this|that|the|these|those|his|her|their)\s+"
        r"([a-z0-9' -]{2,40})",
        cleaned,
    )
    if m:
        return m.group(1).strip(" ?!.")
    return ""


def _update_scene_description(text: Optional[str]) -> None:
    """Write a fresh visual observation into world_state.environment["description"]
    so the GUI's vision panel reflects what Rex just looked at.

    The GUI reads its scene description from world_state.environment, which is
    otherwise only refreshed by the slow periodic environment scan. A user asking
    "what do you see?" triggers a fresh directed look that never touched that
    field — so the panel appeared frozen. This bridges that gap. No-op on blank
    text; never raises.
    """
    summary = str(text or "").strip()
    if not summary:
        return
    try:
        def _set_desc(env):
            env = dict(env or {})
            env["description"] = summary
            env["last_updated"] = time.time()
            return env
        world_state.mutate("environment", _set_desc)
    except Exception as exc:
        _log.debug("scene-description update failed: %s", exc)


def _vision_question_answer_prompt(raw_text: str) -> str:
    """Take a fresh camera look at the user's visual question and build a
    grounded LLM prompt for the in-character answer.

    This is the path behind "what do you see", "can you see what I'm holding",
    "look at my X", etc. It makes ONE GPT vision call carrying the user's
    actual question (analyze_directed_attention), so the answer is grounded in
    what the camera genuinely shows — including an honest miss — instead of
    the cached room-level summary (which can't see a held-up object) or, worse,
    a pure-text hallucinated "I see it". Only runs on explicit user vision
    queries, so the vision spend is strictly user-initiated.
    """
    analysis: dict = {}
    frame = None
    try:
        from vision import camera
        frame = camera.get_frame()
    except Exception as exc:
        _log.debug("vision question frame grab failed: %s", exc)
    if frame is not None:
        try:
            from vision import scene as vision_scene
            analysis = vision_scene.analyze_directed_attention(
                frame,
                direction="current",
                utterance=raw_text,
                target_hint=_vision_question_target_hint(raw_text),
            ) or {}
        except Exception as exc:
            _log.debug("vision question analyze error: %s", exc)
    if analysis:
        _log.info(
            "[interaction] vision query fresh look target_visible=%s subject=%s summary=%r",
            analysis.get("target_visible"),
            analysis.get("subject_type"),
            (analysis.get("target_summary") or "")[:120],
        )
        # Push the fresh look into the shared scene description so the GUI's vision
        # panel reflects what Rex just looked at — otherwise the panel only ever
        # updates on the slow periodic environment scan, never when asked.
        _update_scene_description(analysis.get("target_summary"))
        return (
            f"The user asked a visual question: {raw_text!r}. You took a fresh "
            f"look through your camera and got this vision analysis:\n"
            f"{json.dumps(analysis, ensure_ascii=False)}\n\n"
            "Answer their question as Rex in one or two lines, grounded ONLY in "
            "the analysis. If target_visible is true, name the target concretely "
            "using target_summary and notable_details. If the analysis names a "
            "person you recognize, refer to them BY NAME (e.g. the person at the "
            "desk is Bret — say 'you' or 'Bret', not 'a man'). If target_visible "
            "is false, say honestly that you can't make it out and suggest holding "
            "it closer or pointing — never claim to see something the analysis "
            "doesn't show. Do not mention JSON, APIs, screenshots, or image "
            "analysis."
        )
    # No frame or the vision call failed — fall back to the cached world-state
    # summary rather than inventing detail.
    desc = ""
    try:
        from vision import scene as vision_scene
        desc = vision_scene.describe_scene()
    except Exception as exc:
        _log.debug("vision describe fallback error: %s", exc)
    return (
        f"You were asked what you see. Scene analysis: '{desc or 'nothing notable'}'. "
        f"Describe it in character in one or two lines. If the analysis is "
        f"empty, admit your view is coming up empty rather than inventing detail."
    )


def _handle_classified_intent(
    intent: str,
    raw_text: str,
    person_id: Optional[int],
    *,
    raw_best_id: Optional[int] = None,
    raw_best_name: Optional[str] = None,
    raw_best_score: float = 0.0,
    visible_known_name: Optional[str] = None,
) -> Optional[str]:
    """Answer a classified intent locally with real data, in Rex's voice.

    Returns the spoken response text, or None if the intent should fall
    through to the normal LLM path (i.e. 'general' or unhandled).

    The raw_best_* kwargs carry the UNFILTERED top voice-ID candidate for
    this utterance (no threshold applied). Used by query_who_is_speaking to
    produce confidence-aware responses. visible_known_name is the name of a
    currently-visible identified face if any.
    """
    def _say(prompt: str) -> str:
        resp = llm.get_response(prompt, person_id)
        _speak_blocking(resp)
        return resp

    tool_scope = (
        "Stay strictly on the user's requested tool answer. Do not mention "
        "unrelated memories, grief, death, sensitive events, visual observations, "
        "or personal facts unless the user asked for them in this turn."
    )

    if intent == "query_what_do_you_see":
        _try_slow_path_ack("vision")
    elif intent == "query_memory":
        _try_slow_path_ack("memory")

    if intent == "query_time":
        resp = _format_current_time_response()
        _speak_blocking(resp)
        return resp

    if intent == "query_date":
        resp = _format_current_date_response()
        _speak_blocking(resp)
        return resp

    if intent == "query_weather":
        # INDOOR phrasing ("inside", "in here", "in the room") means the BME280
        # climate sensor on the drive base, not the outdoor weather feed — the
        # classifier files both under query_weather (field bug 2026-07-16: asking
        # for the temperature inside got Sacramento's forecast).
        lowered = (raw_text or "").lower()
        if any(k in lowered for k in ("inside", "in here", "indoor", "in the room",
                                      "in this room", "in the house")):
            env: dict = {}
            try:
                from hardware import motion
                env = (motion.telemetry() or {}).get("env") or {}
            except Exception:
                env = {}
            if env.get("ok") and env.get("t") is not None:
                t_f = float(env["t"]) * 9.0 / 5.0 + 32.0
                facts = f"{t_f:.0f}°F"
                if env.get("rh") is not None:
                    facts += f", {float(env['rh']):.0f} percent humidity"
                if "pressure" in lowered and env.get("hpa") is not None:
                    facts += f", {float(env['hpa']) * 0.029530:.2f} inHg barometric pressure"
                return _say(
                    f"Your own onboard climate sensor reads the room at exactly {facts}. "
                    "Tell the user the indoor reading in one Rex-style line. You MUST "
                    f"state the numbers exactly as given — do not round or invent. {tool_scope}"
                )
            return _say(
                "The user asked about the temperature inside, but your onboard climate "
                "sensor isn't reporting right now. Say so in one Rex-style line. Do NOT "
                f"make up a number. {tool_scope}"
            )

        from awareness.chronoception import refresh_weather
        w = refresh_weather()
        temp = w.get("temp_f")
        desc = w.get("description") or w.get("condition") or "unknown"
        location = getattr(config, "WEATHER_LOCATION", "the local area")
        _log.info("[interaction] weather fetched for %r: %s", location, w)
        if temp is None:
            return _say(
                "The user asked about the weather but your weather feed is offline "
                "right now. Tell them you can't reach the weather service in one "
                f"Rex-style line. Do NOT make up a temperature or conditions. {tool_scope}"
            )
        # Build the full fact sheet (current + forecast) and let the model
        # answer the user's ACTUAL question from it. Field 2026-08-02: "what
        # will the high be for the day?" got the current-conditions line
        # re-spoken because the prompt only ever carried current temp/desc.
        facts = [f"current conditions: {temp}°F and {desc}"]
        if w.get("today_high_f") is not None:
            today_part = f"today's forecast high: {w['today_high_f']}°F"
            if w.get("today_low_f") is not None:
                today_part += f", low: {w['today_low_f']}°F"
            facts.append(today_part)
        if "tomorrow" in lowered and w.get("tomorrow_high_f") is not None:
            tomorrow_part = f"tomorrow: high {w['tomorrow_high_f']}°F"
            if w.get("tomorrow_low_f") is not None:
                tomorrow_part += f", low {w['tomorrow_low_f']}°F"
            if w.get("tomorrow_description"):
                tomorrow_part += f", {w['tomorrow_description']}"
            facts.append(tomorrow_part)
        if ("humid" in lowered or "muggy" in lowered) and w.get("humidity") is not None:
            facts.append(f"humidity: {w['humidity']} percent")
        fact_sheet = "; ".join(facts)
        return _say(
            f"The real weather facts for {location}: {fact_sheet}. The user asked: "
            f"{(raw_text or '').strip()!r} — answer THAT question in one Rex-style "
            "line using ONLY these facts (if they asked for the high, give the "
            "forecast high, not the current temperature). You MUST state numbers "
            "exactly as given — do not round, do not invent numbers or conditions, "
            f"and do not answer with a fact they didn't ask about. {tool_scope}"
        )

    if intent == "query_games":
        from features import games as games_mod
        game_list = ", ".join(games_mod.available_game_names()) or "none right now"
        return _say(
            f"The user asked what games you can play. Your actual game list: {game_list}. "
            f"Tell them in one Rex-style line. Be brief. {tool_scope}"
        )

    if intent == "query_capabilities":
        capabilities = (
            "hold a real conversation and remember people across visits; "
            "recognize faces and voices; describe what you see through your camera; "
            "play games (Trivia, Jeopardy, I Spy, 20 Questions, Word Association); "
            "DJ music with skip / stop / volume control; "
            "tell time, date, and weather; "
            "report your own battery state; "
            "track your own mood, anger, and uptime"
        )
        return _say(
            f"The user asked what you can do. Your real capabilities: {capabilities}. "
            f"Summarize in one or two Rex-style lines. Be brief. {tool_scope}"
        )

    if intent == "query_uptime":
        try:
            self_state = world_state.get("self_state")
            up = int(self_state.get("uptime_seconds", 0) or 0)
        except Exception:
            up = 0
        hours = up // 3600
        minutes = (up % 3600) // 60
        return _say(
            f"Tell the user your uptime is exactly {hours} hours and {minutes} minutes "
            f"in Rex character. Be brief. {tool_scope}"
        )

    if intent == "query_battery":
        # Real pack telemetry from the drive base (battery_awareness). LiFePO4's
        # flat curve can't give an honest percentage, so Rex reports what the
        # voltage actually supports: the band, plus the number itself.
        from intelligence import battery_awareness
        mv = battery_awareness.current_mv()
        if mv <= 0:
            return _say(
                "The user asked about your battery / state of charge. You have "
                "no battery telemetry right now — the battery sensor rides on "
                "your drive base, which isn't connected. Say exactly that in one "
                f"honest Rex-style line; do NOT invent a number or claim you "
                f"lack a battery meter in general. {tool_scope}"
            )
        tier = battery_awareness.tier_for_mv(mv) or "unknown"
        volts = mv / 1000.0
        if tier == "charging":
            # On the charger the terminals read CHARGER voltage, not fill
            # state — reciting it as the answer is what the owner heard as
            # "he kept saying the charging voltage" (field 2026-08-03 17:59).
            # The honest answer while charging: can't measure the fill, and a
            # long stint on the charger means effectively full.
            return _say(
                "The user asked about your battery. You are ON THE CHARGER "
                "right now, and while charging the voltage reads the charger, "
                "not your fill level — you cannot measure how full you are "
                "mid-charge. If you've been plugged in for hours you are "
                "effectively full. Say that plainly in one Rex-style line — "
                "lead with 'charging / effectively full', not with a voltage "
                f"number, and NEVER invent a percentage. {tool_scope}"
            )
        tier_desc = {
            "nominal": "the long healthy plateau (LiFePO4 sits flat from "
                       "roughly 90% down to 25%)",
            "low": "the knee of the curve — roughly 10-25% left",
            "critical": "nearly empty; the BMS cutoff is not far away",
        }.get(tier, "an unknown band")
        return _say(
            f"The user asked about your battery. Real telemetry: pack voltage "
            f"{volts:.2f} volts, band '{tier}' ({tier_desc}). Your chemistry "
            f"cannot honestly give a precise percentage — report the voltage "
            f"and the band in one Rex-style line, numbers exactly as given. "
            f"{tool_scope}"
        )

    if intent == "query_what_do_you_see":
        # Compound "<look> <dir> and tell me what you see" where far-field ASR
        # dropped the leading "look", so the directional half never parsed as a
        # directed_look and the turn arrives here as a plain scene description.
        # When a direction survives next to a real vision query, physically turn
        # the head and describe the NEW view instead of whatever is straight
        # ahead (logged 2026-06-21: "to your right, what do you see?" → Rex
        # listed what was in front of him without ever turning right). Gated on
        # has_vision_query_evidence so the directed-look path is guaranteed to
        # take its analyze branch rather than falling back to a silent gaze.
        look_dir = _compound_look_direction(raw_text)
        if look_dir and action_router.has_vision_query_evidence(raw_text):
            try:
                _look_row = people_memory.get_person(person_id) if person_id else None
            except Exception:
                _look_row = None
            return _execute_directed_look_command(
                {
                    "direction": look_dir,
                    "target_hint": "",
                    "search_target": False,
                    "utterance": raw_text,
                },
                person_id,
                _look_row.get("name") if _look_row else None,
                raw_text,
            )
        return _say(_vision_question_answer_prompt(raw_text))

    if intent == "query_music_options":
        try:
            stations = getattr(config, "RADIO_STATIONS", []) or []
            seen: list[str] = []
            for s in stations:
                vibes = s.get("vibes") or []
                if vibes:
                    primary = str(vibes[0]).strip().lower()
                    if primary and primary not in seen:
                        seen.append(primary)
            genre_list = ", ".join(seen) if seen else "a variety of genres"
        except Exception as exc:
            _log.debug("query_music_options enumeration error: %s", exc)
            genre_list = "a variety of genres"
        return _say(
            f"The user asked what kind of music you can play. Your real radio "
            f"genre buckets are: {genre_list}. You can also play local tracks by "
            f"title, artist, or vibe. Answer in ONE short Rex-style line — list "
            f"the genres tersely (comma-separated is fine), no preamble, no fluff."
        )

    if intent == "query_memory":
        try:
            target = memory_query.resolve_target(raw_text, person_id)
            if target.ambiguous_names:
                names = ", ".join(target.ambiguous_names[:5])
                return _say(
                    f"The user asked a memory question ({raw_text!r}), but their "
                    f"relationship phrase matched multiple people: {names}. Ask "
                    f"which one they mean in ONE short Rex-style line. Do not guess."
                )
            if not target.resolved:
                if target.detail == "relationship_query_without_current_person":
                    rel = target.relation_label or "relationship"
                    return _say(
                        f"The user asked about their {rel}, but you do not know who "
                        f"is speaking with enough confidence. In ONE short Rex-style "
                        f"line, say you need to know who they are first before pulling "
                        f"that relationship memory. Do not invent a name."
                    )
                if target.detail == "no_relationship_match":
                    rel = target.relation_label or "relationship"
                    return _say(
                        f"The user asked about their {rel}, but no matching "
                        f"relationship is stored in memory. In ONE short Rex-style "
                        f"line, say you do not have that relationship saved yet. "
                        f"Do not invent a person."
                    )
                if target.detail == "no_person_match" and target.name:
                    # Not someone in people.db — so this is almost certainly a
                    # GENERAL-KNOWLEDGE subject that merely looked person-shaped
                    # ("tell me about your friend R2D2", "tell me about Star Tours").
                    # Fall through to the normal LLM path so Rex answers from
                    # knowledge instead of dead-ending with "no memory for them"
                    # (mirrors how "search the web for ..." falls through).
                    _log.info(
                        "[interaction] query_memory: %r not in people.db — falling "
                        "through to the general LLM path",
                        target.name,
                    )
                    return None
                if target.detail == "no_person_subject":
                    # A memory question with no PERSON in it, from someone we have
                    # identified — almost always a reference to the live
                    # conversation, which this handler cannot see. Field 2026-08-13
                    # 20:32: "Do you remember what I said that they were gonna let
                    # you do?" ("they" = the radar sensors, Rex's own topic 19
                    # seconds earlier) hit the catch-all below and Rex asked
                    # "Who's 'they,' Bret?" — the dossier lookup had discarded the
                    # transcript that held the answer. Fall through to the normal
                    # LLM path, which carries the recent turns, exactly as the
                    # no_person_match branch above does.
                    _log.info(
                        "[interaction] query_memory: no person subject in %r — "
                        "falling through to the conversational path",
                        raw_text,
                    )
                    return None
                return _say(
                    f"The user asked a memory question ({raw_text!r}), but you "
                    f"cannot resolve who it is about. In ONE short Rex-style line, "
                    f"ask them to name the person. Do not invent."
                )

            context = memory_query.build_context(target, person_id)
            if not context.has_memory:
                return _say(
                    f"The user asked a memory question ({raw_text!r}). You resolved "
                    f"the target as {target.name or 'that person'}, but only the "
                    f"person record exists and no facts, relationships, events, or "
                    f"conversation summaries were found. Say that honestly in ONE "
                    f"short Rex-style line."
                )
            return _say(memory_query.build_response_prompt(raw_text, context))
        except Exception as exc:
            _log.debug("query_memory intent failed: %s", exc)
            return _say(
                "The user asked a memory question, but your memory lookup errored. "
                "Tell them briefly in one Rex-style line that the memory banks "
                "hiccuped and you cannot pull it up right now."
            )

    if intent == "play_music":
        try:
            from features import dj as dj_mod
            track = dj_mod.handle_request(raw_text)
        except Exception as exc:
            _log.debug("play_music intent dj error: %s", exc)
            track = None
        if track is None:
            return _say(
                f"The user asked you to play music ('{raw_text}') but no matching "
                f"track or station was found. Tell them you couldn't find anything "
                f"matching that in one in-character Rex line."
            )
        response = _say(
            f"You're about to play '{track.name}' ({track.description}) in response "
            f"to: '{raw_text}'. Announce it in one short in-character Rex line."
        )
        _start_dj_after_response(track)
        return response

    if intent == "query_who_is_speaking":
        # Build a confidence-aware prompt. Priority order:
        #   1. Face visible + identified → confident by face
        #   2. Voice score >= hard threshold → confident by voice
        #   3. Voice score >= a "maybe" floor with a plausible candidate →
        #      Rex expresses uncertainty with the candidate name
        #   4. Nothing above the floor → Rex honestly says he doesn't know
        hard = float(config.SPEAKER_ID_SIMILARITY_THRESHOLD)
        # "Maybe" floor: voice scores in [0.50, hard) deserve a tentative guess.
        maybe_floor = float(getattr(config, "SPEAKER_ID_MAYBE_FLOOR", 0.50))

        candidate_name = raw_best_name
        candidate_score = raw_best_score

        if visible_known_name:
            # Face wins — tell them with confidence.
            return _say(
                f"Someone asked who's speaking. You can actually SEE them on "
                f"camera and you recognize them as {visible_known_name}. "
                f"In one short in-character Rex line, confirm their identity — "
                f"warm but dry. Address them by name. One line only."
            )

        if candidate_name and candidate_score >= hard:
            return _say(
                f"Someone asked who's speaking. You recognize the voice with high "
                f"confidence (score {candidate_score:.2f}) as {candidate_name}. "
                f"In ONE short in-character Rex line, confirm their identity. "
                f"Be direct, address them by name."
            )

        if candidate_name and candidate_score >= maybe_floor:
            return _say(
                f"Someone asked who's speaking. You have a PARTIAL voice match "
                f"(confidence score {candidate_score:.2f} out of 1.0) for "
                f"{candidate_name} — it might be them, but you're not sure. "
                f"In ONE short in-character Rex line, voice that uncertainty out "
                f"loud: say you're not sure but it could be {candidate_name}. "
                f"Keep the hedging audible — 'I'm not positive' / 'could be' / "
                f"'pretty sure but my sensors aren't certain'. One line only."
            )

        # No name, but Rex may still recognize the VOICE as one he's heard before —
        # either recurring in this conversation or persisted from a past session.
        anon = _current_turn_anonymous or {}
        if anon.get("recognized"):
            return _say(
                "Someone asked who's speaking. You don't have their NAME, but their "
                "voice matches one your memory banks logged in an EARLIER session — "
                "you've heard this person before, just never got a name. In ONE short "
                "in-character Rex line, say exactly that: familiar voice, no name on "
                "file yet, and ask who they are. One line only."
            )
        if int(anon.get("turns") or 0) >= 2:
            return _say(
                "Someone asked who's speaking. You don't recognize them as anyone "
                "named, but it's the SAME unknown voice you've heard a few times "
                "already this conversation. In ONE short in-character Rex line, say "
                "you keep hearing this voice but still don't have a name for it, and "
                "ask who they are. One line only."
            )

        # Nothing plausible — honest unknown.
        return _say(
            f"Someone asked who's speaking but no voice print matched (top "
            f"similarity was only {candidate_score:.2f}) and you don't see their "
            f"face. In ONE short in-character Rex line, admit honestly that you "
            f"don't recognize the voice — NO guessing, NO roast about forget"
            f"tability unless it comes naturally. Just 'no idea, who's asking?' "
            f"in Rex's voice. One line only."
        )

    return None


# ─────────────────────────────────────────────────────────────────────────────
# Crosstalk / addressee triage
# ─────────────────────────────────────────────────────────────────────────────
# With an always-on mic, Rex overhears people talking to each OTHER (a partner in
# another room, the user answering someone else). Perfect addressee detection is
# impossible, so this is deliberately HIGH PRECISION: only the clearest
# "talking to another person" cues, and never when Rex is addressed — so it can
# never make Rex ignore plausibly-directed speech.

_REX_ADDRESS_TOKEN_RE = re.compile(
    r"\b(rex|r3x|r-?3x|dj|droid|robot|jukebox)\b",
    re.IGNORECASE,
)
# "love you" / "love you too" at a clause edge — affection aimed at a person, not
# a DJ droid. The edge anchor avoids requests like "I'd love you to play music".
_AFFECTION_TO_PERSON_RE = re.compile(
    r"\blove\s+(?:you|ya|u)(?:\s+too)?\s*(?:[,.!?]|$)",
    re.IGNORECASE,
)
# "babe" is essentially never a common noun in a living room → partner vocative
# anywhere in the line.
_PARTNER_VOCATIVE_ANYWHERE_RE = re.compile(r"\bbabe\b", re.IGNORECASE)
# Other endearments only count as vocatives when comma-set-off or at a sentence
# edge, so "pass the honey" / "what a sweetheart of a deal" don't trip it.
_PARTNER_VOCATIVE_EDGE_RE = re.compile(
    r"(?:^|,)\s*(?:honey|hon|sweetie|sweetheart|darling)\s*(?:[,.!?]|$)",
    re.IGNORECASE,
)


def _looks_like_third_party_crosstalk(text: str) -> bool:
    """Best-effort: True when an utterance clearly addresses another person, not
    Rex (partner endearments, "love you too"). High precision, low recall — it
    must never fire on plausibly Rex-directed speech, so unsure cases return False.
    """
    cleaned = (text or "").strip()
    if not cleaned:
        return False
    if _REX_ADDRESS_TOKEN_RE.search(cleaned):
        return False
    if _AFFECTION_TO_PERSON_RE.search(cleaned):
        return True
    if _PARTNER_VOCATIVE_ANYWHERE_RE.search(cleaned):
        return True
    if _PARTNER_VOCATIVE_EDGE_RE.search(cleaned):
        return True
    return False


def _crosstalk_second_person_evidence(raw_best_id: Optional[int] = None) -> bool:
    """True when someone besides the (raw-candidate) speaker is plausibly around
    for an endearment to be aimed at — the ONLY situation the third-party filter
    exists for. A sole-person room returns False, so a lone owner saying
    "I love you" to Rex's face gets answered, never eaten (field 2026-08-08
    11:19: exactly that line, voice-matched to the only person present two
    seconds after Rex's own turn, matched the endearment regex and vanished
    without a sound — the owner read the next minute as total deafness).

    The off-camera partner (the case the filter was built for) stays covered by
    the recent-second-voice signal: a partner talking in another room leaves an
    anonymous speaker slot or a second known voice in the session within the
    CROSSTALK_SECOND_VOICE_RECENT_SECS window.
    """
    try:
        people = world_state.get("people") or []
    except Exception:
        people = []
    if len(people) >= 2:
        return True
    if _has_unknown_visible_or_recent():
        return True
    # Another KNOWN face besides the presumed speaker just visible — only
    # meaningful when the voice actually matched someone, otherwise the one
    # visible known face is most likely the speaker themselves.
    if raw_best_id is not None and _other_known_visible_recently(raw_best_id):
        return True
    window = float(getattr(config, "CROSSTALK_SECOND_VOICE_RECENT_SECS", 180.0))
    if window > 0.0:
        now = time.monotonic()
        try:
            if any(
                (now - float(slot.last_seen_at)) <= window
                for slot in _anonymous_speaker_slots
            ):
                return True
        except Exception:
            pass
    return False


def _crosstalk_suppression_context_ok(raw_best_id: Optional[int] = None) -> bool:
    """Context gate for the third-party crosstalk filter — True only when
    suppressing this turn is actually defensible. Two vetoes:

    1. Reply window: a line landing within CROSSTALK_REPLY_WINDOW_SECS of Rex
       finishing his own line is plausibly a reply to HIM whatever its shape.
    2. Second person: with CROSSTALK_REQUIRE_SECOND_PERSON, the room must show
       evidence of someone else to address (see _crosstalk_second_person_evidence).
    """
    reply_window = float(getattr(config, "CROSSTALK_REPLY_WINDOW_SECS", 10.0))
    if reply_window > 0.0:
        try:
            if speech_queue.seconds_since_last_speech() <= reply_window:
                return False
        except Exception:
            pass
    if not bool(getattr(config, "CROSSTALK_REQUIRE_SECOND_PERSON", True)):
        return True
    return _crosstalk_second_person_evidence(raw_best_id)


# ─────────────────────────────────────────────────────────────────────────────
# Low-trust reprompt — handle a garbled decode the way a human would
# ─────────────────────────────────────────────────────────────────────────────
# When ASR trust is below the floor and the utterance carries real content,
# replying to the guess is bluffing (field 2026-08-01: "I'm not a cat." at
# logprob -1.88 got a quip about mystery voices; "You kill everybody." got a
# line about ethics). A person who half-hears a sentence says "sorry, what?"
# and gets the real one. Plain human phrasings on purpose — a save-face circuit
# joke here would bury the actual request to repeat.

_LOW_TRUST_REPROMPT_LINES = [
    "Sorry — what was that?",
    "I didn't catch that. Say it again?",
    "What was that?",
    "Sorry, one more time?",
    "Hm? Run that by me again.",
    "I only caught about half of that — say it again?",
]
_last_low_trust_reprompt_at: float = 0.0
_last_low_trust_reprompt_line: str = ""


def _low_trust_reprompt_line() -> str:
    """A reprompt line differing from the previous one (anti-repeat)."""
    global _last_low_trust_reprompt_line
    choices = [
        line for line in _LOW_TRUST_REPROMPT_LINES
        if line != _last_low_trust_reprompt_line
    ] or list(_LOW_TRUST_REPROMPT_LINES)
    line = random.choice(choices)
    _last_low_trust_reprompt_line = line
    return line


def _arm_low_trust_reprompt_cooldown() -> None:
    global _last_low_trust_reprompt_at
    _last_low_trust_reprompt_at = time.monotonic()


def _should_reprompt_low_trust(text: str, *, trusted: bool, text_input: bool) -> bool:
    """True when the human move for THIS turn is asking to repeat, not replying.

    Gates, in order of intent:
      * only genuine low-trust AUDIO turns (typed text is never garbled);
      * 3+ words — short backchannels ("Okay.", "Yeah.") routinely score under
        the floor and a reprompt there is worse than a nod;
      * once per exchange — if the repeat ALSO scores low, engage best-effort
        rather than looping "what?" at them (memory learning stays suppressed);
      * never during a game (the game flow owns its own answer handling);
      * never on an explicit drive/stop command — acting on a probable "stop"
        beats asking a clarifying question about it.
    """
    if trusted or text_input:
        return False
    if not bool(getattr(config, "LOW_TRUST_REPROMPT_ENABLED", True)):
        return False
    words = re.findall(r"[A-Za-z0-9']+", text or "")
    if len(words) < int(getattr(config, "LOW_TRUST_REPROMPT_MIN_WORDS", 3)):
        return False
    cooldown = float(getattr(config, "LOW_TRUST_REPROMPT_COOLDOWN_SECS", 120.0))
    if (time.monotonic() - _last_low_trust_reprompt_at) < cooldown:
        return False
    try:
        if _game_suppresses_conversation():
            return False
    except Exception:
        pass
    try:
        cleaned = (text or "").strip()
        # Any short utterance carrying a stop-word skips the reprompt — the field
        # shape is repeated ("Stop moving. Stop moving."), which the bare-stop
        # regex (single token only) and the drive classifier both miss.
        if len(words) <= 5 and re.search(
            r"\b(?:stop|halt|freeze|whoa)\b", cleaned, re.IGNORECASE
        ):
            return False
        if _BARE_MOTION_STOP_RE.match(cleaned) or _eager_motion_transcript_matches(cleaned):
            return False
    except Exception:
        pass
    return True


# ─────────────────────────────────────────────────────────────────────────────
# Speech segment processing
# ─────────────────────────────────────────────────────────────────────────────

def _handle_speech_segment(
    audio_array: np.ndarray,
    *,
    from_idle_activation: bool = False,
    transcribed_text: Optional[str] = None,
    raw_best_id_override: Optional[int] = None,
    raw_best_name_override: Optional[str] = None,
    speaker_score_override: float = 0.0,
    text_input: bool = False,
    eager_transcript: Optional[str] = None,
) -> None:
    """Full processing pipeline for one detected speech segment in ACTIVE state."""
    global _session_exchange_count, _identity_prompt_until, _awaiting_followup_event
    global _pending_introduction, _pending_intro_followup, _pending_intro_voice_capture
    global _pending_common_first_name_identity, _pending_common_first_name_introduction
    global _pending_existing_common_first_name, _pending_identity_match_confirmation
    global _pending_last_name_confirm
    global _pending_offscreen_identify, _pending_face_reveal_confirm
    global _identity_reask_count

    turn_start = time.monotonic()
    answered_question: Optional[dict] = None
    assistant_asked_question = False
    game_after_audio_path: Optional[str] = None
    event_cancellation_ack: Optional[str] = None
    repair_move: Optional[dict] = None
    router_decision: Optional[action_router.ActionDecision] = None
    router_audit: Optional[_RouterDecisionAudit] = None
    router_block_reason: Optional[str] = None
    dialogue_decision: Optional[dialogue_act.DialogueActDecision] = None
    character_trace: Optional[_CharacterLoopTrace] = None
    match: Optional[command_parser.CommandMatch] = None
    response_text: Optional[str] = None
    intent: Optional[str] = None
    completed: Optional[bool] = None
    handler_error: Optional[str] = None
    final_executed_path: Optional[str] = None
    suppress_memory_learning = False
    handled_active_game_turn = False
    # (set for real once the transcript exists — see the transcript_trusted note)
    used_agenda_llm = False
    used_classified_intent = False
    trace_context_token: Optional[contextvars.Token] = None

    if _shutdown_requested():
        return

    # Randomised pre-response pause — prevents Rex from feeling instant/robotic.
    # Absorbed by transcription: ASR (~0.6-0.9s) dwarfs the 0-80ms pause, so
    # sleeping it serially BEFORE processing was pure added latency on every
    # audio turn. Only the remainder (if any) is slept once the transcript is
    # ready — which still paces the GUI text path, where there is no ASR.
    delay_ms = random.randint(config.REACTION_DELAY_MS_MIN, config.REACTION_DELAY_MS_MAX)
    delay_deadline = time.monotonic() + delay_ms / 1000.0
    if _shutdown_requested():
        return

    # Once Rex starts speaking in response, hold AEC suppression open across any
    # related output as one continuous window. Do not start it before
    # transcription; that made the logs look like user speech was captured
    # while playback suppression was active and encouraged premature filler.
    sequence_started = False
    try:
        # Concurrent transcription + speaker identification, unless the GUI
        # supplied text directly.
        process_started = time.monotonic()
        # Whisper's own decode confidence for THIS turn. Captured here, once, into a
        # plain local: `text` is a Transcript (a str subclass) but every .strip() /
        # .lower() downstream returns a bare str and silently drops the attribute.
        # False means Rex answers normally but must not LEARN from the turn — no
        # stored facts, no person names, no room names. See audio/transcription.py.
        transcript_trusted = True
        # Publish the default before the branch, not only on the audio path. The
        # context var lives on the interaction-loop thread and is never reset per
        # turn, so a typed-text turn used to INHERIT the previous audio turn's
        # verdict — an untrusted mumble followed by a typed command left the command
        # marked untrusted. Harmless while the only consumer was memory-learning;
        # not harmless now that MOTION_ROUTE_REQUIRE_TRUSTED_TRANSCRIPT gates wheels.
        _transcript_trusted.set(True)
        if transcribed_text is not None:
            text = str(transcribed_text or "").strip()
            raw_best_id = raw_best_id_override
            raw_best_name = raw_best_name_override
            speaker_score = float(speaker_score_override or 0.0)
            speaker_margin = 1.0  # explicit override — not a voice scoreboard, trust it
            required_margin = float(getattr(config, "SPEAKER_ID_KNOWN_MARGIN", 0.07))
            transcript_ready_at = time.monotonic()
            _latency_log(turn_start, "text_input", process_started)
        else:
            (text, raw_best_id, raw_best_name, speaker_score, speaker_margin,
             required_margin) = _process_audio(audio_array, pretranscribed=eager_transcript)
            transcript_trusted = bool(getattr(text, "confident", True))
            _transcript_trusted.set(transcript_trusted)
            if not transcript_trusted:
                # Whisper was guessing. Answer the human normally — being briefly
                # forgetful is recoverable, mishearing them into a permanent "fact"
                # is not (field 2026-07-25: "wine" -> "I'm going to split it.", which
                # became an episode and then a proactive question).
                suppress_memory_learning = True
                _log.info("[interaction] low-confidence transcript — replying but not "
                          "learning from this turn: %r", str(text))
            transcript_ready_at = time.monotonic()
            _latency_log(turn_start, "transcribe_and_speaker_id", process_started)

        # Residual reaction pause — normally 0.000s (ASR outlasts the deadline);
        # only the no-ASR GUI text path sleeps a meaningful remainder.
        delay_started = time.monotonic()
        remaining = delay_deadline - delay_started
        if remaining > 0:
            time.sleep(remaining)
        _latency_log(turn_start, "reaction_delay", delay_started)

        if _shutdown_requested():
            final_executed_path = "ignored.shutdown"
            completed = False
            return
        if not text:
            # Empty/blank transcript — a false VAD trigger or fully-filtered audio
            # (e.g. a Whisper hallucination loop). Nothing was actually said to Rex.
            # If we only flipped to ACTIVE because of this segment, drop straight back
            # to IDLE instead of camping in ACTIVE until the 45s conversation idle
            # timeout. Mirrors the crosstalk path below.
            final_executed_path = "ignored.empty_transcript"
            completed = False
            if from_idle_activation:
                try:
                    state_module.set_state(State.IDLE)
                except Exception:
                    pass
            return

        character_trace = _new_character_loop_trace(
            text,
            from_idle_activation=from_idle_activation,
            turn_start=turn_start,
            raw_best_id=raw_best_id,
            raw_best_name=raw_best_name,
            speaker_score=speaker_score,
        )
        character_trace.transcript_ready_at = transcript_ready_at
        trace_context_token = _current_character_loop_trace.set(character_trace)

        heard_log_text = text

        # Best-effort crosstalk suppression: if this utterance clearly addresses
        # another person (partner endearment, "love you too") and never names Rex,
        # treat it as overheard couple-talk, not a turn directed at Rex.
        if (
            not text_input
            and bool(getattr(config, "CROSSTALK_SUPPRESSION_ENABLED", True))
            and not _game_suppresses_conversation()
            and _looks_like_third_party_crosstalk(text)
        ):
            if not _crosstalk_suppression_context_ok(raw_best_id):
                # Nobody else around to say it to, and/or it landed right after
                # Rex's own line: treat it as directed at HIM and answer it
                # (field 2026-08-08 11:19: a solo "I love you." was eaten here).
                _log.info(
                    "[interaction] crosstalk-shaped line KEPT — no second-person "
                    "context / inside Rex's reply window: %r",
                    text,
                )
            else:
                _log.info(
                    "[interaction] suppressed overheard crosstalk (not addressed to Rex): %r",
                    text,
                )
                # Being deliberately ignored must never be indistinguishable from
                # deafness — leave a soft audible tell that Rex noticed the voice.
                if bool(getattr(config, "CROSSTALK_SUPPRESS_TELL_ENABLED", True)):
                    try:
                        from audio import sound_effects
                        sound_effects.play("curious", concurrent=True)
                    except Exception:
                        pass
                final_executed_path = "ignored.crosstalk"
                completed = False
                if from_idle_activation:
                    # Don't camp in ACTIVE on speech that was not even meant for Rex.
                    try:
                        state_module.set_state(State.IDLE)
                    except Exception:
                        pass
                return

        # Own-echo rejection: the transcript near-matches a line Rex JUST spoke —
        # his AEC residual crossed the VAD during/after playback and Whisper heard
        # him verbatim (field 2026-07-23: "Something's in my way" came back as
        # unknown_voice_2 and got a full reply). Drop it before it can mint an
        # anonymous speaker or reach the LLM.
        if (
            not text_input
            # A fresh impersonation capture slot EXPECTS the human to recite Rex's
            # own words back — never eat their recitation as echo.
            and not _impersonation_capture_fresh(_pending_impersonation_capture)
            # A CONFIDENT voiceprint match to a known human overrides the text
            # match: Rex's AEC residual is his own TTS voice, which comes back as
            # unknown_voice_N (field 2026-07-23), never as a strong human match.
            # Humans, meanwhile, echo Rex's words back at him on purpose — the
            # field case (2026-08-05 21:19) was Bret repeating "An AWS outage?"
            # as a follow-up question, voice-scored 0.868, and the echo rejector
            # ate it: Rex's next line then read as ignoring him.
            and not (
                isinstance(speaker_score, (int, float))
                and float(speaker_score)
                >= float(getattr(config, "OWN_ECHO_VOICE_OVERRIDE_SCORE", 0.80))
            )
            and _looks_like_own_echo(text)
        ):
            _log.info(
                "[interaction] rejected own-echo transcript (matches a recent Rex line): %r",
                text,
            )
            final_executed_path = "ignored.own_echo"
            completed = False
            if from_idle_activation:
                try:
                    state_module.set_state(State.IDLE)
                except Exception:
                    pass
            return

        if not _game_suppresses_conversation():
            completion = turn_completion.consume_continuation(
                text=text,
                audio_array=audio_array,
                raw_best_id=raw_best_id,
                raw_best_name=raw_best_name,
                raw_best_score=speaker_score,
            )
            if completion and completion.get("action") == "merge":
                text = completion["text"]
                transcript_trusted = transcript_trusted and bool(
                    completion.get("trusted", True))
                merged_audio = completion.get("audio_array")
                if merged_audio is not None:
                    audio_array = merged_audio
                raw_best_id = completion.get("raw_best_id")
                raw_best_name = completion.get("raw_best_name")
                speaker_score = float(completion.get("raw_best_score") or 0.0)
                if completion.get("was_prompted"):
                    heard_log_text = completion.get("continuation_text") or heard_log_text
                else:
                    heard_log_text = text
            else:
                signal = turn_completion.classify(text)
                if signal is not None:
                    pending = turn_completion.hold(
                        text=text,
                        audio_array=audio_array,
                        raw_best_id=raw_best_id,
                        raw_best_name=raw_best_name,
                        raw_best_score=speaker_score,
                        signal=signal,
                    )
                    try:
                        consciousness.begin_response_wait(
                            max(0.5, pending.hold_until - time.monotonic()) + 0.5
                        )
                    except Exception as exc:
                        _log.debug("turn completion response-wait failed: %s", exc)
                    final_executed_path = "turn_completion.hold"
                    completed = False
                    return
        else:
            try:
                turn_completion.clear_stale_prompted()
            except Exception:
                pass

        # Low-trust human-style reprompt: the decode fell below the trust floor
        # and carries real content — ask them to say it again instead of replying
        # to a guess. Runs AFTER turn-completion so held fragments still merge
        # (the merged turn re-checks with its combined trust). One re-ask per
        # exchange; the repeat gets engaged best-effort even if it's also low.
        if _should_reprompt_low_trust(
            text, trusted=transcript_trusted, text_input=text_input
        ) and not _impersonation_capture_fresh(_pending_impersonation_capture):
            line = _low_trust_reprompt_line()
            _log.info(
                "[interaction] low-trust transcript %r — asking to repeat "
                "instead of replying to a guess", str(text),
            )
            _speak_blocking(line, emotion="curious")
            _arm_low_trust_reprompt_cooldown()
            try:
                consciousness.begin_response_wait(10.0)
            except Exception:
                pass
            final_executed_path = "repair.low_trust_reprompt"
            completed = True
            return

        if character_trace is not None:
            character_trace.utterance = str(text or "")
            character_trace.heard_text = str(heard_log_text or "")
            character_trace.raw_best_id = _safe_int(raw_best_id)
            character_trace.raw_best_name = raw_best_name
            character_trace.speaker_score = _safe_round_score(speaker_score)

        specific_forget_target_for_turn = forgetting.extract_specific_forget_target(text)

        echo_cancel.start_sequence()
        sequence_started = True

        # ── Voice acceptance: hard + session-sticky soft threshold ─────────────
        # Short/noisy utterances cause wild score variance (0.60–0.85 for the
        # same person within a single conversation). Mirror human identity
        # continuity: once someone is confirmed this session, accept subsequent
        # low-score utterances from the same person as long as they clear the
        # softer floor. New speakers still need the hard threshold because
        # their voice won't match the engaged person.
        hard_threshold = float(config.SPEAKER_ID_SIMILARITY_THRESHOLD)
        soft_threshold = float(getattr(config, "SPEAKER_ID_SOFT_THRESHOLD", 0.60))
        known_floor = float(getattr(config, "SPEAKER_ID_KNOWN_SPEAKER_FLOOR", 0.45))
        # Scoreboard-specific ambiguity bar (thin-challenger relief) computed at scan
        # time by speaker_id.required_ambiguity_margin — NOT the raw config value.
        known_margin = float(required_margin)
        try:
            _recent_engaged = consciousness.get_recent_engagement()
        except Exception:
            _recent_engaged = None

        person_id: Optional[int] = None
        person_name: Optional[str] = None
        sticky_accepted = False
        identity_resolution_override: Optional[str] = None
        if (
            raw_best_id is not None
            and speaker_score >= hard_threshold
            and speaker_margin >= known_margin
        ):
            # Hard accept, margin-guarded: the threshold sits low (0.50, where a real
            # returning speaker actually scores), so require the winner to clearly beat
            # the next different person before trusting voice alone.
            person_id = raw_best_id
            person_name = raw_best_name
        elif (
            raw_best_id is not None
            and speaker_score >= known_floor
            and speaker_margin >= known_margin
        ):
            # Engagement-FREE known-speaker soft-accept: a returning known person who
            # just started speaking — even off-camera / not the engaged person — is
            # recognized by voice when their match is unambiguous (clears the floor AND
            # beats the runner-up by the margin). This is what lets the off-camera
            # "what can you tell about me?" identify Bret without him saying his name.
            person_id = raw_best_id
            person_name = raw_best_name
            _log.info(
                "[interaction] voice known-speaker soft-accept — person_id=%s name=%r "
                "score=%.3f margin=%.3f (floor=%.2f, margin>=%.2f)",
                person_id, person_name, speaker_score, speaker_margin, known_floor, known_margin,
            )
        elif (
            raw_best_id is not None
            and speaker_score >= soft_threshold
            and _recent_engaged is not None
            and raw_best_id == _recent_engaged.get("person_id")
        ):
            # Legacy session-sticky continuity for the engaged person (no margin needed —
            # face/engagement context backs it).
            person_id = raw_best_id
            person_name = raw_best_name or _recent_engaged.get("name")
            sticky_accepted = True
            _log.info(
                "[interaction] voice soft-accept under session stickiness — "
                "person_id=%s name=%r score=%.3f (hard=%.2f, soft=%.2f)",
                person_id, person_name, speaker_score, hard_threshold, soft_threshold,
            )
        # else: person_id stays None — truly unknown voice.

        # ── World-state person resolution ──────────────────────────────────────
        # Consciousness runs face ID independently; if speaker ID missed or is absent,
        # fall back to whoever consciousness already identified in world_state.people.
        # Only use this when exactly one identified person is visible (unambiguous).
        ws_identified = []
        try:
            ws_people = world_state.get("people")
            ws_identified = [p for p in ws_people if p.get("person_db_id") is not None]
            ws_person = ws_identified[0] if len(ws_identified) == 1 else None
        except Exception:
            ws_identified = []
            ws_person = None

        # While an introduction is actively expecting the newcomer to speak, do
        # NOT let the introducer's still-visible / recently-seen face drive
        # attribution or refresh their voiceprint. The single-visible-face rule
        # ("a visible face wins regardless of voice") is correct in normal turns,
        # but here Rex just asked a NEW person to say hello — the camera may even
        # have been turned to them — so the introducer's lingering face must not
        # capture the newcomer's first words (which also got their audio appended
        # to the introducer's print). Attribution falls to voice + the intro
        # voice-capture handler instead. Live-logged 2026-06-15 (Exudica run).
        if ws_person is not None and _intro_capture_window_open():
            _log.info(
                "[interaction] person resolution: introduction in progress — "
                "suppressing sticky/visible face %r so the newcomer's turn isn't "
                "bound to (or refreshing) the introducer",
                ws_person.get("face_id") or ws_person.get("voice_id"),
            )
            ws_person = None

        # Detect "off-camera unknown voice": speaker-ID found no match AND nobody
        # unknown is visible AND the visible engaged person isn't the speaker
        # (because their voice print would have matched). Treat person_id=None
        # as genuinely unknown rather than mis-attributing to the visible engaged
        # person — this is the hook for Rex's "who's that speaking?" behavior.
        off_camera_unknown = False
        voice_challenge_fired = False   # set when the marginal-match challenge rejects a voice attribution
        recent_engagement = None
        try:
            recent_engagement = consciousness.get_recent_engagement()
        except Exception:
            recent_engagement = None

        visible_known_by_id = {}
        try:
            visible_known_by_id = {
                int(p["person_db_id"]): p
                for p in ws_identified
                if p.get("person_db_id") is not None
            }
        except Exception:
            visible_known_by_id = {}

        if text_input and person_id is None:
            recent_id = _safe_int((recent_engagement or {}).get("person_id"))
            if (
                recent_id is not None
                and (not visible_known_by_id or recent_id in visible_known_by_id)
            ):
                vis = visible_known_by_id.get(recent_id, {})
                person_id = recent_id
                person_name = (
                    (recent_engagement or {}).get("name")
                    or vis.get("face_id")
                    or vis.get("voice_id")
                )
                _log.info(
                    "[interaction] person resolution: GUI text input recent engagement — "
                    "person_id=%s name=%r",
                    person_id,
                    person_name,
                )
            elif len(visible_known_by_id) == 1:
                person_id, vis = next(iter(visible_known_by_id.items()))
                person_name = vis.get("face_id") or vis.get("voice_id")
                _log.info(
                    "[interaction] person resolution: GUI text input single visible person — "
                    "person_id=%s name=%r",
                    person_id,
                    person_name,
                )

        pending_qa_recent_attribution = False
        if person_id is None and not text_input:
            person_id, person_name, pending_qa_recent_attribution = (
                _pending_question_recent_attribution(
                    person_id=person_id,
                    person_name=person_name,
                    recent_engagement=recent_engagement,
                    raw_best_id=raw_best_id,
                    speaker_score=speaker_score,
                    text=text,
                )
            )

        # Multi-person scenes need a gentler fallback than "unseen stranger."
        # If the top voice candidate is one of the visible known faces, accept
        # it at a weaker floor. If not, keep conversational continuity with the
        # recently engaged visible person instead of derailing into "who said
        # that?" when two known faces are already in frame.
        if person_id is None and len(visible_known_by_id) >= 2:
            multi_floor = float(getattr(config, "SPEAKER_ID_MULTI_VISIBLE_FLOOR", 0.50))
            recent_floor = float(getattr(config, "SPEAKER_ID_MULTI_VISIBLE_RECENT_FLOOR", 0.45))
            speaking_floor = float(getattr(config, "SPEAKER_ID_MULTI_VISIBLE_SPEAKING_FLOOR", 0.35))
            # Visual active-speaker corroboration: the LATCHED recent speaker
            # (the live is_speaking has already cleared by the time a turn is
            # resolved — see active_speaker.recent_visual_speaker docs).
            _visual_pid = None
            try:
                from vision import active_speaker as _asp
                _visual_pid = (_asp.recent_visual_speaker() or {}).get("person_db_id")
            except Exception as exc:
                _log.debug("active-speaker recent lookup failed: %s", exc)
            _visual_corroborated = _visual_corroborated_speaker(
                raw_best_id=raw_best_id,
                speaker_score=speaker_score,
                visible_known_ids=set(visible_known_by_id.keys()),
                visual_speaker_pid=_visual_pid,
                floor=speaking_floor,
            )
            if raw_best_id in visible_known_by_id and speaker_score >= multi_floor:
                vis = visible_known_by_id[int(raw_best_id)]
                person_id = int(raw_best_id)
                person_name = raw_best_name or vis.get("face_id") or vis.get("voice_id")
                _log.info(
                    "[interaction] person resolution: multi-visible voice+face attribution — "
                    "person_id=%s name=%r voice_score=%.3f (floor=%.2f)",
                    person_id, person_name, speaker_score, multi_floor,
                )
            elif _visual_corroborated is not None:
                vis = visible_known_by_id[int(_visual_corroborated)]
                person_id = int(_visual_corroborated)
                person_name = raw_best_name or vis.get("face_id") or vis.get("voice_id")
                identity_resolution_override = "voice_corroborated_by_visual_speaker"
                _log.info(
                    "[interaction] person resolution: multi-visible weak voice (%.3f) confirmed "
                    "by active-speaker visual — person_id=%s name=%r (floor=%.2f)",
                    speaker_score, person_id, person_name, speaking_floor,
                )
            else:
                recent_id = (recent_engagement or {}).get("person_id")
                if (
                    recent_id in visible_known_by_id
                    and not _has_unknown_visible_or_recent()
                    and not _other_known_visible_recently(recent_id)
                    # Require the weak voice match to actually point at the recent
                    # person before pinning the turn on them.
                    and _safe_int(raw_best_id) == _safe_int(recent_id)
                    and speaker_score >= recent_floor
                ):
                    vis = visible_known_by_id[int(recent_id)]
                    person_id = int(recent_id)
                    person_name = (
                        (recent_engagement or {}).get("name")
                        or vis.get("face_id")
                        or vis.get("voice_id")
                    )
                    _log.info(
                        "[interaction] person resolution: multi-visible recent speaker fallback — "
                        "person_id=%s name=%r voice_score=%.3f (floor=%.2f, raw_best=%s)",
                        person_id, person_name, speaker_score, recent_floor, raw_best_id,
                    )

        # ── Voice-primary attribution ───────────────────────────────────────
        # WHO is speaking is decided by the VOICE. The accept tiers above already
        # produced a voice-led person_id (all margin-guarded). Here the visible
        # face only CORROBORATES a weak/absent voice match — it never OVERRIDES a
        # voice that points elsewhere, and never captures the turn for a person the
        # voice does not point at. An unrecognized voice becomes an off-screen /
        # anonymous identity, not "whoever is on camera." Set
        # VOICE_PRIMARY_IDENTITY_ENABLED=False to restore the legacy face-wins path.
        voice_primary = bool(getattr(config, "VOICE_PRIMARY_IDENTITY_ENABLED", True))
        if ws_person is not None and voice_primary:
            ws_pid = _safe_int(ws_person.get("person_db_id"))
            ws_name = ws_person.get("face_id") or ws_person.get("voice_id")
            # Latched recent visual active-speaker (the live is_speaking has already
            # cleared by the time a turn resolves — see active_speaker docs). Used
            # only to let the camera VETO a marginal off-camera voice match against
            # the visible face, or confirm the visible face is not the talker.
            _voice_dec_visual_pid = None
            _voice_dec_mouth_still = False
            try:
                from vision import active_speaker as _asp
                _voice_dec_visual_pid = (_asp.recent_visual_speaker() or {}).get("person_db_id")
                # POSITIVE absence: the detector is running and its latch is
                # empty — nobody visible articulated near end-of-turn, so the
                # visible face's mouth was still while the voice arrived
                # (field 2026-08-02 12:37: JT spoke from ~20ft, scored 0.455
                # on Bret's print, silently-on-camera Bret got the credit).
                _voice_dec_mouth_still = (
                    bool(getattr(config, "SPEAKER_ID_MOUTH_STILL_VETO_ENABLED", True))
                    and _asp.enabled()
                    and _voice_dec_visual_pid is None
                )
            except Exception as exc:
                _log.debug("active-speaker recent lookup (single-visible) failed: %s", exc)
            decision = _voice_primary_face_decision(
                person_id=person_id,
                raw_best_id=raw_best_id,
                speaker_score=speaker_score,
                ws_pid=ws_pid,
                single_visible=(len(visible_known_by_id) == 1),
                engaged_is_visible=(
                    recent_engagement is not None
                    and _safe_int(recent_engagement.get("person_id")) == ws_pid
                ),
                unknown_visible=_has_unknown_visible_or_recent(),
                other_known_recently=_other_known_visible_recently(ws_pid),
                visual_speaker_pid=_voice_dec_visual_pid,
                visual_mouth_still=_voice_dec_mouth_still,
                voice_continuity=_voice_continuity_active(person_id),
                score_genuine_band=_ecapa_genuine_band(
                    speaker_score,
                    float(getattr(config, "SPEAKER_ID_ECAPA_TRUST_FLOOR_FACE", 0.50)),
                ),
                # `text`, NOT `transcribed_text`: the latter is the optional
                # caller-supplied override and is None on every real voice turn, so
                # passing it silently disabled the word-count backstop and left only
                # the padding-fooled duration check (field 2026-07-24: "Come here."
                # scored 0.232, was ruled off-camera, and the gaze search that
                # followed broke the face lock come-here depends on).
                short_utterance=_is_short_utterance(audio_array, text),
                non_speech_vocalization=_is_non_speech_vocalization(text),
            )
            if decision == "voice_agrees":
                _note_confident_voice(person_id, speaker_score)
                _log.info(
                    "[interaction] person resolution: voice+face agree — person_id=%s name=%r score=%.3f",
                    person_id, person_name, speaker_score,
                )
                try:
                    _maybe_auto_refresh_voice(
                        person_id, speaker_score, audio_array,
                        face_confirmed=True, raw_best_id=raw_best_id,
                        visual_speaker_pid=_voice_dec_visual_pid,
                    )
                except Exception as exc:
                    _log.debug("auto voice-refresh skip: %s", exc)
            elif decision == "voice_agrees_no_refresh":
                # Marginal match on the visible face, backed by recent CONFIDENT voice
                # continuity (their own voice trailing into a short/mumbled turn).
                # Attribute, but never let a marginal sample near the print.
                _log.info(
                    "[interaction] person resolution: marginal voice (%.3f) on visible face "
                    "accepted via voice continuity — person_id=%s name=%r (no print refresh)",
                    speaker_score, person_id, person_name,
                )
            elif decision == "challenge_identity":
                # Marginal match on the visible face with NO voice credibility — the
                # exact "JT says happy-4th, silently-on-camera Bret gets credit" shape.
                # Voice is primary: the camera never upgrades a marginal score. Reply
                # handles content + asks who's speaking; the answer enrolls the voice.
                _log.info(
                    "[interaction] person resolution: marginal voice (%.3f) matched the "
                    "visible face %r but no recent confident voice backs it — challenging "
                    "identity instead of assuming the face is the speaker",
                    speaker_score, ws_name,
                )
                person_id = None
                person_name = None
                off_camera_unknown = True
                voice_challenge_fired = True
            elif decision == "voice_over_face":
                _note_confident_voice(person_id, speaker_score)
                # Voice matched someone OTHER than the visible face. Voice is
                # primary: keep the voice result — the visible person is simply
                # also present, and the speaker the voice matched is talking off
                # the one identified face (beside/behind the camera, across a room).
                _log.info(
                    "[interaction] person resolution: voice over visible face — "
                    "person_id=%s name=%r (visible ws_pid=%s) score=%.3f",
                    person_id, person_name, ws_pid, speaker_score,
                )
            elif decision == "voice_weak_face_wins":
                # A marginal (<confident) voice match pointed at someone OTHER than
                # the visible known face, and the camera did not contradict the face
                # (it confirmed the face is talking, or had no usable speaker signal).
                # The present, clearly-visible known face anchors identity — a
                # near-neighbor acoustic match (typical of an absent/poor voiceprint)
                # must not override it. Do NOT refresh the print: the voice did not
                # actually agree, so the audio would pollute it.
                voice_lost_name = person_name
                voice_lost_pid = person_id
                person_id = ws_pid
                person_name = ws_name
                identity_resolution_override = "voice_weak_face_wins"
                _log.info(
                    "[interaction] person resolution: marginal off-camera voice (%.3f) "
                    "did NOT override visible known face — person_id=%s name=%r "
                    "(rejected voice match=%s/%r, visual_speaker=%s)",
                    speaker_score, person_id, person_name,
                    voice_lost_pid, voice_lost_name, _voice_dec_visual_pid,
                )
                # The voice matched the WRONG person only because this person's print is empty/thin
                # (that mismatch IS the symptom). If the camera confirms they are the on-camera
                # talker, this face-confirmed audio is exactly what BOOTSTRAPS their print — the only
                # way out of the deadlock. _maybe_auto_refresh_voice bootstraps only below the sample
                # floor and only with visual-speaker confirmation, so an established print is never
                # polluted by this branch.
                try:
                    _maybe_auto_refresh_voice(
                        person_id, speaker_score, audio_array,
                        face_confirmed=True, raw_best_id=raw_best_id,
                        visual_speaker_pid=_voice_dec_visual_pid,
                    )
                except Exception as exc:
                    _log.debug("auto voice-bootstrap skip: %s", exc)
            elif decision == "corroborate":
                # Voice weakly leans toward the one visible person — their own
                # (weak) print, corroborated by their face.
                person_id = ws_pid
                person_name = ws_name
                _log.info(
                    "[interaction] person resolution: weak voice corroborated by visible "
                    "face — person_id=%s name=%r score=%.3f",
                    person_id, person_name, speaker_score,
                )
                try:
                    _maybe_auto_refresh_voice(
                        person_id, speaker_score, audio_array,
                        face_confirmed=True, raw_best_id=raw_best_id,
                        visual_speaker_pid=_voice_dec_visual_pid,
                    )
                except Exception as exc:
                    _log.debug("auto voice-refresh skip: %s", exc)
            elif decision == "face_only_continuity":
                # No voice candidate at all (no enrolled prints / clip too short to
                # score) in a clean 1:1 — engagement continuity or the camera's
                # active-speaker latch backs the face. Attribute, and hand the audio
                # to the auto-refresh BOOTSTRAP: after an embedder migration this is
                # the only way the person's print gets rebuilt without the CLI tool
                # (refresh's own guards still apply — quality gates, camera-confirmed
                # talker, bootstrap floor — so an established print is never touched
                # from here and unconfirmed audio is simply skipped).
                person_id = ws_pid
                person_name = ws_name
                _log.info(
                    "[interaction] person resolution: no voice signal, single known "
                    "face — person_id=%s name=%r (face-only continuity)",
                    person_id, person_name,
                )
                try:
                    _maybe_auto_refresh_voice(
                        person_id, speaker_score, audio_array,
                        face_confirmed=True, raw_best_id=raw_best_id,
                        visual_speaker_pid=_voice_dec_visual_pid,
                    )
                except Exception as exc:
                    _log.debug("auto voice-bootstrap skip: %s", exc)
            elif decision == "short_face_wins":
                # Clip too short to score; voice doesn't point elsewhere; one
                # known face on camera → that face is the speaker. NO voice
                # refresh — a sub-2s clip is bad print material.
                person_id = ws_pid
                person_name = ws_name
                _log.info(
                    "[interaction] person resolution: short utterance (%.2fs) — voice "
                    "uninformative, sole visible face wins — person_id=%s name=%r "
                    "(raw_best=%s score=%.3f)",
                    _audio_duration_secs(audio_array), person_id, person_name,
                    raw_best_id, speaker_score,
                )
            elif decision == "unknown_intro_path":
                # Voice unrecognized while an unknown face is/was visible — leave the
                # speaker unresolved for the intro/identify path (NOT off-screen).
                _log.info(
                    "[interaction] person resolution: voice unrecognized while an unknown "
                    "face is/was visible — leaving speaker unknown (intro/identify path)",
                )
            else:  # off_screen_unknown
                off_camera_unknown = True
                _log.info(
                    "[interaction] person resolution: voice points away from visible face "
                    "%r (raw_best=%s score=%.3f) — off-screen/unknown speaker",
                    ws_name, raw_best_id, speaker_score,
                )
                if person_id is not None:
                    # The match that pointed away was MARGINAL (a confident one took
                    # voice_over_face above). "Unknown speaker" must not keep the
                    # near-neighbour's name: field 2026-08-21 23:30, Bret alone at
                    # 6 ft, face locked, scored 0.593 on JT's one-sample print, and
                    # this branch flagged him unknown yet the turn still carried
                    # person_id=4 — so the reply greeted "JT". Same shape as the
                    # who's-that path below: unknown means unnamed.
                    _log.info(
                        "[interaction] person resolution: dropping marginal off-camera "
                        "name %r (%.3f) — unknown speaker stays unnamed",
                        person_name, speaker_score,
                    )
                    person_id = None
                    person_name = None
        elif ws_person is not None:
            # Legacy face-wins path (voice-primary disabled).
            ws_pid = _safe_int(ws_person.get("person_db_id"))
            ws_name = ws_person.get("face_id") or ws_person.get("voice_id")
            if person_id is None:
                person_id, person_name = ws_pid, ws_name
            elif person_id != ws_pid:
                face_override = _single_visible_face_voice_override(
                    resolved_person_id=person_id,
                    ws_person=ws_person,
                    visible_known_by_id=visible_known_by_id,
                    has_unknown_visible_or_recent=_has_unknown_visible_or_recent(),
                    speaker_score=speaker_score,
                    hard_threshold=hard_threshold,
                )
                if face_override is not None:
                    person_id, person_name = face_override
                    sticky_accepted = False
                    identity_resolution_override = "visible_face_over_voice_conflict"
        elif person_id is not None:
            if _voice_only_attribution_suspect(person_id, speaker_score):
                # Marginal voice match, matched person not seen on camera, and a body
                # IS visible that we can't identify — the JT-reads-as-Bret shape. Ask
                # who's speaking (the off-camera identify flow below) instead of
                # silently crediting the voice match.
                _log.info(
                    "[interaction] person resolution: marginal voice match %r (%.3f) but "
                    "they haven't been on camera and someone ELSE is visible — treating "
                    "as unknown speaker (who's-that path)",
                    person_name, speaker_score,
                )
                person_id = None
                person_name = None
                off_camera_unknown = True
                voice_challenge_fired = True
            else:
                _note_confident_voice(person_id, speaker_score)
                _log.info(
                    "[interaction] person resolution: voice match — person_id=%s name=%r score=%.3f",
                    person_id, person_name, speaker_score,
                )
        else:
            # No single identified face and no voice match. Track as an off-screen
            # / unknown voice so group and crowded-room speakers are NOT dropped —
            # we do NOT require that nobody else is visible (the old rule suppressed
            # unknown voices in groups, the exact case we need to get right). The
            # anonymous speaker slot below gives this voice session continuity.
            off_camera_unknown = True
            _log.info(
                "[interaction] person resolution: no voice match, no single visible face — "
                "off-screen/unknown voice (recent=%r, visible_known=%d)",
                (recent_engagement or {}).get("name"), len(visible_known_by_id),
            )

        pending_last_name_target = _pending_existing_common_first_name_reply_target(text)
        if pending_last_name_target is not None:
            pending_person_id, pending_first_name = pending_last_name_target
            if person_id != pending_person_id:
                _log.info(
                    "[interaction] person resolution: pending last-name reply attributed "
                    "to person_id=%s name=%r despite voice candidate=%s/%r score=%.3f "
                    "prior_person_id=%s",
                    pending_person_id,
                    pending_first_name,
                    raw_best_id,
                    raw_best_name,
                    speaker_score,
                    person_id,
                )
            person_id = pending_person_id
            person_name = pending_first_name
            off_camera_unknown = False
            identity_resolution_override = "pending_last_name_reply"

        game_conversation_lock = _game_suppresses_conversation()
        identity_prompt_consumed = False
        if not game_conversation_lock:
            try:
                identity_prompt_consumed = bool(consciousness.consume_identity_prompt_request())
            except Exception as exc:
                _log.debug("identity prompt request consume failed: %s", exc)
        if identity_prompt_consumed:
            _identity_prompt_until = max(
                _identity_prompt_until,
                time.monotonic() + _IDENTITY_REPLY_WINDOW_SECS,
            )
        identity_prompt_active = bool(
            identity_prompt_consumed or time.monotonic() <= _identity_prompt_until
        )
        has_unknown_visible_now = _has_unknown_visible_person()
        has_unknown_visible_or_recent = has_unknown_visible_now or _has_unknown_visible_or_recent()
        anonymous_speaker_label: Optional[str] = None
        anonymous_speaker_match_score: Optional[float] = None
        speaker_label_for_turn = person_name or anonymous_speaker_label or "user"
        identity_resolution_for_turn = (
            identity_resolution_override
            or _infer_identity_resolution_strategy(
                person_id=person_id,
                raw_best_id=raw_best_id,
                speaker_score=speaker_score,
                hard_threshold=hard_threshold,
                soft_threshold=soft_threshold,
                sticky_accepted=sticky_accepted,
                ws_identified=ws_identified,
                recent_engagement=recent_engagement,
                off_camera_unknown=off_camera_unknown,
            )
        )
        _character_loop_note_speaker(
            character_trace,
            person_id=person_id,
            person_name=person_name,
            speaker_label=speaker_label_for_turn,
            identity_resolution=identity_resolution_for_turn,
            off_camera_unknown=off_camera_unknown,
            visible_known_count=len(visible_known_by_id),
            has_unknown_visible_or_recent=has_unknown_visible_or_recent,
            anonymous_speaker_label=anonymous_speaker_label,
            anonymous_speaker_match_score=anonymous_speaker_match_score,
        )
        voice_group_chatter = _note_voice_turn_for_group_chatter(
            person_id=person_id,
            raw_best_id=raw_best_id,
            raw_best_score=speaker_score,
        )
        group_chatter_active = voice_group_chatter or _audio_group_chatter_active()
        if _should_ignore_idle_background_speech(
            from_idle_activation=from_idle_activation,
            person_id=person_id,
            has_unknown_visible=has_unknown_visible_now,
            identity_prompt_active=identity_prompt_active,
            text_input=text_input,
            text=text,
        ) and not game_conversation_lock:
            _log.info(
                "[interaction] ignoring no-wake IDLE speech from unrecognized/off-camera "
                "source text=%r raw_best=%s score=%.3f visible_known=%d",
                text,
                raw_best_id,
                speaker_score,
                len(visible_known_by_id),
            )
            try:
                state_module.set_state(State.IDLE)
            except Exception:
                pass
            final_executed_path = "ignored.idle_background_speech"
            completed = False
            return

        if (
            group_chatter_active
            and person_id is None
            and not identity_prompt_active
            and command_parser.parse(text) is None
            and not game_conversation_lock
        ):
            _log.info(
                "[interaction] ignoring unknown speech during group chatter "
                "text=%r raw_best=%s score=%.3f",
                text,
                raw_best_id,
                speaker_score,
            )
            final_executed_path = "ignored.group_chatter"
            completed = False
            return

        # Pet-directed speech ("Come here, Max" / "Lay down. Lay down.") is not
        # for Rex — field 2026-08-02 13:55: the robot drove at Brad off a dog
        # command. Checked before every reply/command/motion path.
        pet_reason = _pet_directed_speech(text)
        if pet_reason and not game_conversation_lock:
            _log.info(
                "[interaction] ignoring pet-directed speech (%s): %r",
                pet_reason, text,
            )
            final_executed_path = "ignored.pet_directed"
            completed = False
            return

        # KNOWN speakers get gated during group chatter too (field 2026-08-02
        # 13:48: a 3-person room — once Brad was enrolled, Rex answered every
        # human-to-human exchange, political banter, and literal self-talk).
        # A recognized person's cross-talk is still cross-talk: with 2+ humans
        # trading turns, Rex replies only on DIRECTED evidence and otherwise
        # listens (the lean impulse still interjects on its own governed
        # cadence, so he participates by choice, not reflex).
        if (
            group_chatter_active
            and person_id is not None
            and not identity_prompt_active
            and not game_conversation_lock
            and bool(getattr(config, "GROUP_CHATTER_KNOWN_SPEAKER_GATE_ENABLED", True))
        ):
            directed = _group_chatter_directed_evidence(text)
            if directed is None:
                _log.info(
                    "[interaction] listening (not replying) — group chatter, no "
                    "directed evidence, speaker=%r text=%r",
                    person_name, text,
                )
                final_executed_path = "ignored.group_chatter_undirected"
                completed = False
                return
            _log.info(
                "[interaction] group chatter reply allowed (%s) text=%r",
                directed, text,
            )

        if not text_input:
            try:
                consciousness.note_speaker_gaze_intent(
                    person_id,
                    unknown_voice=(person_id is None or off_camera_unknown),
                    reason="off_camera_unknown" if off_camera_unknown else "speech",
                )
            except Exception as exc:
                _log.debug("speaker gaze intent note failed: %s", exc)

        global _current_turn_anonymous, _current_turn_speaker_evidence
        _current_turn_anonymous = None
        _current_turn_speaker_evidence = {
            "raw_best_id": raw_best_id,
            "raw_best_name": raw_best_name,
            "raw_best_score": float(speaker_score or 0.0),
        }
        short_clip = (
            bool(getattr(config, "SHORT_CLIP_CONTINUITY_ENABLED", True))
            and transcribed_text is None
            and _is_short_clip(text, audio_array)
        )
        short_clip_resolution: Optional[str] = None
        if short_clip and person_id is None:
            roster_pick = _short_clip_roster_candidate(_last_scan_ranked)
            if roster_pick is not None:
                person_id, person_name, _roster_score = roster_pick
                off_camera_unknown = False
                short_clip_resolution = "short_clip_roster"
                _log.info(
                    "[interaction] person resolution: short clip — roster continuity "
                    "person_id=%s name=%r score=%.3f (raw_best=%s/%r %.3f)",
                    person_id, person_name, _roster_score,
                    raw_best_id, raw_best_name, float(speaker_score or 0.0),
                )
        anonymous_speaker_label, anonymous_speaker_match_score, resolved_voice_person = (
            _resolve_anonymous_speaker_slot(
                audio_array,
                person_id=person_id,
                raw_best_id=raw_best_id,
                raw_best_name=raw_best_name,
                raw_best_score=speaker_score,
                short_clip=short_clip,
            )
        )
        if (
            short_clip
            and person_id is None
            and resolved_voice_person is None
            and not anonymous_speaker_label
        ):
            last = _short_clip_last_speaker()
            if last is not None and last.get("person_id") is not None:
                person_id = last.get("person_id")
                person_name = last.get("person_name")
                short_clip_resolution = "short_clip_last_speaker"
                _log.info(
                    "[interaction] person resolution: short clip — attributed to the "
                    "last speaker person_id=%s name=%r",
                    person_id, person_name,
                )
            elif last is not None and last.get("label"):
                anonymous_speaker_label = last.get("label")
                short_clip_resolution = "short_clip_last_speaker"
                _log.info(
                    "[interaction] person resolution: short clip — attributed to the "
                    "last speaker %s", anonymous_speaker_label,
                )
            else:
                short_clip_resolution = "short_clip_unattributed"
                _log.info(
                    "[interaction] person resolution: short clip from nobody recent — "
                    "leaving it unattributed, no who's-that ask text=%r", text,
                )
            off_camera_unknown = False
        if short_clip_resolution is not None:
            identity_resolution_for_turn = short_clip_resolution
        if resolved_voice_person is not None:
            # Cross-session voice memory: this voice matched a signature already
            # linked to a known person. Treat the turn as that known speaker (the
            # rest of the pipeline keys off person_id/person_name).
            person_id = resolved_voice_person.get("person_id")
            person_name = resolved_voice_person.get("person_name")
            identity_resolution_for_turn = "voice_signature_cross_session"
            if person_id is not None:
                _session_person_ids.add(person_id)
            _log.info(
                "[interaction] cross-session voice recognized person_id=%s name=%r",
                person_id, person_name,
            )
        if anonymous_speaker_label:
            slot = next(
                (s for s in _anonymous_speaker_slots if s.label == anonymous_speaker_label),
                None,
            )
            _current_turn_anonymous = {
                "label": anonymous_speaker_label,
                "turns": int(getattr(slot, "turns", 1) or 1),
                "recognized": bool(getattr(slot, "recognized_across_sessions", False)),
            }
            speaker_label_for_turn = anonymous_speaker_label
            _character_loop_note_speaker(
                character_trace,
                person_id=person_id,
                person_name=person_name,
                speaker_label=speaker_label_for_turn,
                identity_resolution=identity_resolution_for_turn,
                off_camera_unknown=off_camera_unknown,
                visible_known_count=len(visible_known_by_id),
                has_unknown_visible_or_recent=has_unknown_visible_or_recent,
                anonymous_speaker_label=anonymous_speaker_label,
                anonymous_speaker_match_score=anonymous_speaker_match_score,
            )

        # Any non-empty user utterance means we should stop waiting for a reply.
        try:
            consciousness.clear_response_wait()
        except Exception:
            pass

        # User spoke — any queued presence reaction about this person is now stale.
        # Drop it so Rex doesn't narrate someone's "departure" immediately after they spoke.
        try:
            ws_people_now = world_state.get("people")
            for p in ws_people_now:
                pid = p.get("person_db_id")
                if pid is not None:
                    speech_queue.drop_by_tag(f"presence:{pid}")
                slot_id = p.get("id")
                if slot_id:
                    speech_queue.drop_by_tag(f"presence:{slot_id}")
        except Exception:
            pass

        # Consciousness asked an unknown person for their name. Its reply request
        # is consumed before the no-wake IDLE filter above so immediate name
        # replies are not mistaken for background speech.

        relationship_prompt_consumed = False
        prompted_identity_ack_text: Optional[str] = None
        heard_turn_recorded = False

        def _record_heard_turn_once() -> None:
            nonlocal heard_turn_recorded
            if heard_turn_recorded:
                return
            heard_turn_recorded = True
            speaker_label = person_name or anonymous_speaker_label or "user"
            heard_speaker_name = person_name or anonymous_speaker_label
            conv_memory.add_to_transcript(speaker_label, heard_log_text)
            conv_log.log_heard(heard_speaker_name, heard_log_text)
            print(f"[HEARD] {speaker_label}: {heard_log_text}", flush=True)
            _log.info(
                "[interaction] speech segment — speaker=%r person_id=%s text=%r",
                speaker_label, person_id, text,
            )
            _note_session_person_turn(person_id)
            _note_last_speaker_turn(person_id, person_name, anonymous_speaker_label)
            # Anchor for the lean-impulse flow gate: REAL accepted speech only. The
            # VAD-level _begin_user_turn also fires for Whisper hallucinations
            # ("and the"), which must not read as "the conversation is flowing".
            global _last_user_content_at
            _last_user_content_at = time.monotonic()
            # Disengagement protocol: real speech resumes the conversation —
            # clear any pending probe/snooze; then a deferral ("give me a few
            # minutes") re-arms a short snooze so Rex waits and checks back.
            _note_user_speech_for_engagement()
            try:
                _maybe_capture_engagement_deferral(text)
            except Exception as exc:
                _log.debug("[lean] deferral capture failed: %s", exc)

        name_merge_response, name_merge_person_id, name_merge_name = (None, None, None)
        if not game_conversation_lock:
            name_merge_response, name_merge_person_id, name_merge_name = (
                _handle_pending_name_merge_confirmation(text)
            )
        if name_merge_response:
            if name_merge_person_id is not None:
                person_id = name_merge_person_id
                person_name = name_merge_name
                _session_person_ids.add(name_merge_person_id)
                _retire_anonymous_speaker_slot(
                    anonymous_speaker_label,
                    person_id=person_id,
                    person_name=person_name,
                )
            _identity_prompt_until = 0.0
            _record_heard_turn_once()
            response_text = name_merge_response
            final_executed_path = "identity.name_merge_confirmation"
            _speak_blocking(
                name_merge_response,
                emotion="happy",
                pre_beat_ms=100,
                post_beat_ms_override=200,
            )
            conv_memory.add_to_transcript("Rex", name_merge_response)
            conv_log.log_rex(name_merge_response)
            _session_exchange_count += 1
            _register_rex_utterance(name_merge_response)
            return

        if _turn_should_defer_identity_prompts(text):
            _clear_pending_identity_prompts("direct_turn")

        identity_match_response, identity_match_person_id, identity_match_name = (None, None, None)
        if not game_conversation_lock:
            identity_match_response, identity_match_person_id, identity_match_name = (
                _handle_pending_identity_match_confirmation(text, audio_array)
            )
        if identity_match_response:
            if identity_match_person_id is not None:
                person_id = identity_match_person_id
                person_name = identity_match_name
                _session_person_ids.add(identity_match_person_id)
                _retire_anonymous_speaker_slot(
                    anonymous_speaker_label,
                    person_id=person_id,
                    person_name=person_name,
                )
                _character_loop_note_speaker(
                    character_trace,
                    person_id=person_id,
                    person_name=person_name,
                    speaker_label=person_name or "user",
                    identity_resolution="identity_match_confirmation",
                    off_camera_unknown=False,
                    visible_known_count=len(visible_known_by_id),
                    has_unknown_visible_or_recent=has_unknown_visible_or_recent,
                )
            _identity_prompt_until = 0.0
            _record_heard_turn_once()
            response_text = identity_match_response
            final_executed_path = "identity.match_confirmation"
            _speak_blocking(
                identity_match_response,
                emotion="happy",
                pre_beat_ms=100,
                post_beat_ms_override=200,
            )
            conv_memory.add_to_transcript("Rex", identity_match_response)
            conv_log.log_rex(identity_match_response)
            _session_exchange_count += 1
            _register_rex_utterance(identity_match_response)
            return

        prompted_name_confirm_response, prompted_name_confirm_id, prompted_name_confirm_name = (None, None, None)
        if not game_conversation_lock:
            prompted_name_confirm_response, prompted_name_confirm_id, prompted_name_confirm_name = (
                _handle_pending_prompted_name_confirmation(text, audio_array)
            )
        if prompted_name_confirm_response:
            if prompted_name_confirm_id is not None:
                person_id = prompted_name_confirm_id
                person_name = prompted_name_confirm_name
                _session_person_ids.add(prompted_name_confirm_id)
                _character_loop_note_speaker(
                    character_trace,
                    person_id=person_id,
                    person_name=person_name,
                    speaker_label=person_name or "user",
                    identity_resolution="prompted_identity_confirmation",
                    off_camera_unknown=False,
                    visible_known_count=len(visible_known_by_id),
                    has_unknown_visible_or_recent=has_unknown_visible_or_recent,
                )
            _record_heard_turn_once()
            response_text = prompted_name_confirm_response
            final_executed_path = "identity.prompted_name_confirmation"
            _speak_blocking(
                prompted_name_confirm_response,
                emotion="happy" if prompted_name_confirm_id is not None else "curious",
                pre_beat_ms=100,
                post_beat_ms_override=200,
            )
            conv_memory.add_to_transcript("Rex", prompted_name_confirm_response)
            conv_log.log_rex(prompted_name_confirm_response)
            _session_exchange_count += 1
            _register_rex_utterance(prompted_name_confirm_response)
            return

        common_name_response, common_name_person_id, common_name_full = (None, None, None)
        if not game_conversation_lock:
            common_name_response, common_name_person_id, common_name_full = (
                _handle_common_first_name_last_name_reply(text, audio_array)
            )
        if common_name_response:
            if common_name_person_id is not None:
                person_id = common_name_person_id
                person_name = common_name_full
                _session_person_ids.add(common_name_person_id)
                _retire_anonymous_speaker_slot(
                    anonymous_speaker_label,
                    person_id=person_id,
                    person_name=person_name,
                )
                _character_loop_note_speaker(
                    character_trace,
                    person_id=person_id,
                    person_name=person_name,
                    speaker_label=person_name or "user",
                    identity_resolution="common_first_name_disambiguation",
                    off_camera_unknown=False,
                    visible_known_count=len(visible_known_by_id),
                    has_unknown_visible_or_recent=has_unknown_visible_or_recent,
                )
            _identity_prompt_until = 0.0
            _record_heard_turn_once()
            response_text = common_name_response
            final_executed_path = "identity.common_first_name_reply"
            _speak_blocking(
                common_name_response,
                emotion="happy",
                pre_beat_ms=100,
                post_beat_ms_override=200,
            )
            conv_memory.add_to_transcript("Rex", common_name_response)
            conv_log.log_rex(common_name_response)
            _session_exchange_count += 1
            _register_rex_utterance(common_name_response)
            return

        common_intro_response = (
            _handle_common_first_name_intro_last_name_reply(text)
            if not game_conversation_lock
            else None
        )
        if common_intro_response:
            _record_heard_turn_once()
            response_text = common_intro_response
            final_executed_path = "identity.common_intro_reply"
            _speak_blocking(
                common_intro_response,
                emotion="happy",
                pre_beat_ms=150,
                post_beat_ms_override=300,
            )
            conv_memory.add_to_transcript("Rex", common_intro_response)
            conv_log.log_rex(common_intro_response)
            _session_exchange_count += 1
            _register_rex_utterance(common_intro_response)
            return

        last_name_confirm_response = (
            _handle_last_name_confirm_reply(text)
            if (not game_conversation_lock and _pending_last_name_confirm is not None)
            else None
        )
        if last_name_confirm_response:
            _record_heard_turn_once()
            response_text = last_name_confirm_response
            final_executed_path = "identity.last_name_confirm"
            _speak_blocking(
                last_name_confirm_response,
                emotion="happy",
                pre_beat_ms=100,
                post_beat_ms_override=200,
            )
            conv_memory.add_to_transcript("Rex", last_name_confirm_response)
            conv_log.log_rex(last_name_confirm_response)
            _session_exchange_count += 1
            _register_rex_utterance(last_name_confirm_response)
            return

        existing_common_name_response = (
            _handle_existing_common_first_name_last_name_reply(text)
            if not game_conversation_lock
            else None
        )
        if existing_common_name_response:
            _record_heard_turn_once()
            response_text = existing_common_name_response
            final_executed_path = "identity.existing_common_first_name_reply"
            _speak_blocking(
                existing_common_name_response,
                emotion="happy",
                pre_beat_ms=100,
                post_beat_ms_override=200,
            )
            conv_memory.add_to_transcript("Rex", existing_common_name_response)
            conv_log.log_rex(existing_common_name_response)
            _session_exchange_count += 1
            _register_rex_utterance(existing_common_name_response)
            return

        self_identified_name = _extract_self_identified_name(text)
        if (
            self_identified_name
            and person_id is not None
            and has_unknown_visible_or_recent
            and not _same_person_name(self_identified_name, person_name)
            and not game_conversation_lock
        ):
            _log.info(
                "[identity] explicit self-introduction %r conflicts with weak/current "
                "speaker label %r while newcomer is visible/recent — treating as newcomer",
                self_identified_name,
                person_name,
            )
            person_id = None
            person_name = None
            off_camera_unknown = False

        if (
            self_identified_name
            and person_id is None
            and has_unknown_visible_or_recent
            and not game_conversation_lock
        ):
            prior_engagement = recent_engagement
            if _maybe_ask_identity_match_confirmation(
                self_identified_name,
                audio_array,
                prior_engagement=prior_engagement,
                anonymous_speaker_label=anonymous_speaker_label,
                enroll_unknown_face=has_unknown_visible_now or bool(prior_engagement),
                source="self_introduction",
            ):
                return

            enrolled_id = _enroll_new_person(
                self_identified_name,
                audio_array,
                enroll_unknown_face=has_unknown_visible_now or bool(prior_engagement),
            )
            if enrolled_id is not None:
                person_id = enrolled_id
                person_name = self_identified_name
                _retire_anonymous_speaker_slot(
                    anonymous_speaker_label,
                    person_id=person_id,
                    person_name=person_name,
                )
                _character_loop_note_speaker(
                    character_trace,
                    person_id=person_id,
                    person_name=person_name,
                    speaker_label=person_name or "user",
                    identity_resolution="self_identified_enrollment",
                    off_camera_unknown=False,
                    visible_known_count=len(visible_known_by_id),
                    has_unknown_visible_or_recent=has_unknown_visible_or_recent,
                )
                _identity_prompt_until = 0.0
                _pending_offscreen_identify = None
                try:
                    rel_ctx = consciousness.consume_relationship_prompt_request()
                    if rel_ctx is not None:
                        consciousness.note_relationship_slot_handled(str(rel_ctx.get("slot_id") or ""))
                except Exception:
                    pass

                relationship = _extract_self_relationship_to_engaged(
                    text,
                    (prior_engagement or {}).get("name"),
                )
                if relationship and prior_engagement and prior_engagement.get("person_id") != enrolled_id:
                    try:
                        from memory import social as social_memory
                        social_memory.save_relationship(
                            from_person_id=enrolled_id,
                            to_person_id=int(prior_engagement["person_id"]),
                            relationship=relationship,
                            described_by=enrolled_id,
                        )
                    except Exception as exc:
                        _log.warning("self-intro relationship save failed: %s", exc)
                elif prior_engagement and prior_engagement.get("person_id") != enrolled_id:
                    _pending_post_greet_relationship[0] = {
                        "prior_engaged_id": prior_engagement["person_id"],
                        "prior_engaged_name": prior_engagement.get("name"),
                        "newcomer_person_id": enrolled_id,
                        "newcomer_name": self_identified_name,
                    }
                _mark_single_name_for_later_last_name(enrolled_id, self_identified_name)

                try:
                    consciousness.mark_engagement(enrolled_id)
                    consciousness.note_person_spoke(enrolled_id)
                    consciousness.note_person_greeted_this_session(enrolled_id)
                except Exception:
                    pass

                speaker_label = person_name or "user"
                conv_memory.add_to_transcript(speaker_label, text)
                conv_log.log_heard(person_name, text)
                print(f"[HEARD] {speaker_label}: {text}", flush=True)
                _log.info(
                    "[interaction] visible newcomer self-introduction — speaker=%r person_id=%s text=%r relationship_to_prior=%r",
                    speaker_label,
                    person_id,
                    text,
                    relationship,
                )

                first = _first_name_or(self_identified_name, self_identified_name)
                prior_first = _first_name_or((prior_engagement or {}).get("name"))
                special_intro_ack = person_specials.special_intro_ack(
                    self_identified_name
                )
                if special_intro_ack:
                    ack_text = special_intro_ack
                elif relationship and prior_first:
                    rel_words = relationship.replace("_", " ")
                    ack_text = (
                        f"{first}. Filed. Relationship to {prior_first}: {rel_words}. That explains at least "
                        "three suspicious data points."
                    )
                else:
                    ack_text = f"{first}. Filed under 'new biological, probably trouble.'"
                try:
                    special_prompt = _special_intro_prompt(self_identified_name)
                    ack_text = llm.get_response(
                        special_prompt
                        or (
                            f"You just learned a visible newcomer's name is {self_identified_name}. "
                            f"{('They said their relationship to ' + prior_first + ' is ' + relationship + '.') if relationship and prior_first else ''} "
                            f"In ONE short in-character Rex line, acknowledge them by name. "
                            f"Do not ask another question."
                        )
                    ) or ack_text
                except Exception as exc:
                    _log.debug("self-intro ack generation failed: %s", exc)
                _speak_blocking(ack_text, emotion="happy", pre_beat_ms=100, post_beat_ms_override=200)
                conv_memory.add_to_transcript("Rex", ack_text)
                conv_log.log_rex(ack_text)
                _session_exchange_count += 1
                _register_rex_utterance(ack_text)
                return

        # Learn-by-being-told: "this is the living room" (volunteered) or a bare answer
        # to Rex's own "what room is this?" NAMES + enrolls the room. Handled here — before
        # the routers and the introduction flow — so a room declaration is acknowledged
        # directly and never misrouted as a person introduction. Conservative: an
        # unprompted line only enrolls when it names a known room word (place_questions).
        if not game_conversation_lock:
            # A CHARGE-CABLE declaration ("you're unplugged" / "I plugged you in")
            # is a standing statement about the hardware, handled deterministically —
            # it releases/sets the firmware charging latch, so it must never drift
            # into the LLM as chit-chat.
            _chg_decl = _charging_declaration(text)
            if _chg_decl is not None:
                _record_heard_turn_once()
                line = _handle_charging_declaration(_chg_decl)
                _log.info("[interaction] charge-cable declaration: plugged=%s (%r)",
                          _chg_decl, text)
                _speak_blocking(line, emotion="neutral", pre_beat_ms=100,
                                post_beat_ms_override=200)
                conv_memory.add_to_transcript("Rex", line)
                conv_log.log_rex(line)
                _session_exchange_count += 1
                _register_rex_utterance(line, source="charging_declaration")
                return
            # A DENIAL runs first: "this is not the workshop" must drop the belief, not
            # be mined for a room name. Field 2026-07-24: Rex answered a correction with
            # "Yep, the workshop. I recognize it." — a person standing in the room
            # outranks a cosine score, and doubling down is the worst possible reply.
            try:
                from intelligence import place_questions
                _place_denial = place_questions.maybe_capture_denial(text)
            except Exception as exc:
                _log.debug("[interaction] place denial check failed: %s", exc)
                _place_denial = None
            if _place_denial:
                _record_heard_turn_once()
                line = place_questions.denial_ack_line(_place_denial)
                _log.info("[interaction] believed room denied by %s: %r",
                          person_name or "the user", _place_denial.get("was"))
                _speak_blocking(line, emotion="curious", pre_beat_ms=100,
                                post_beat_ms_override=200)
                conv_memory.add_to_transcript("Rex", line)
                conv_log.log_rex(line)
                _session_exchange_count += 1
                _register_rex_utterance(line, source="place_denial")
                return
            # A DRIVE RULE next: "this room has carpet" / "don't move in the
            # workshop" is a standing instruction about the FLOOR, not a room name to
            # enroll and not a one-off stop. It has to run before maybe_capture_answer,
            # which would otherwise mine "this room has carpet" for a room word.
            try:
                _drive_rule = place_questions.maybe_capture_drive_rule(text)
            except Exception as exc:
                _log.debug("[interaction] drive-rule check failed: %s", exc)
                _drive_rule = None
            if _drive_rule:
                _record_heard_turn_once()
                line = place_questions.drive_rule_ack_line(_drive_rule)
                try:
                    from intelligence import motion_agency
                    # Only act on the wheels when the rule is about the room he is
                    # actually in — "don't drive in the nursery", said from the
                    # kitchen, files a rule and nothing more.
                    if not _drive_rule.get("current"):
                        pass
                    elif _drive_rule.get("no_drive"):
                        motion_controller.stop()
                        motion_agency.cancel_requested_come("room is flagged no-drive")
                        # Filed against a room, the belief gates every tick on its own.
                        # Un-filable (view unrecognized / room not enrolled) still has to
                        # stop him NOW, so fall back to the session-wide hold.
                        if not _drive_rule.get("applied"):
                            motion_agency.note_user_hold("no-drive room, unfiled")
                    else:
                        motion_agency.release_user_hold("owner cleared the floor")
                except Exception as exc:
                    _log.debug("[interaction] drive-rule motion update failed: %s", exc)
                _log.info("[interaction] drive rule for %r: no_drive=%s applied=%s",
                          _drive_rule.get("name"), _drive_rule.get("no_drive"),
                          _drive_rule.get("applied"))
                _speak_blocking(line, emotion="neutral", pre_beat_ms=100,
                                post_beat_ms_override=200)
                conv_memory.add_to_transcript("Rex", line)
                conv_log.log_rex(line)
                _session_exchange_count += 1
                _register_rex_utterance(line, source="place_drive_rule")
                return
            try:
                _place_capture = place_questions.maybe_capture_answer(text)
            except Exception as exc:
                _log.debug("[interaction] place-name capture failed: %s", exc)
                _place_capture = None
            if _place_capture:
                _record_heard_turn_once()
                place_ack = place_questions.ack_line(_place_capture)
                _log.info("[interaction] room named by voice: %r", _place_capture.get("name"))
                _speak_blocking(place_ack, emotion="happy", pre_beat_ms=100,
                                post_beat_ms_override=200)
                conv_memory.add_to_transcript("Rex", place_ack)
                conv_log.log_rex(place_ack)
                _session_exchange_count += 1
                _register_rex_utterance(place_ack, source="place_enrollment")
                return

        # Room-exploration session: while Rex is wandering / surveying / narrating,
        # a user turn is a stop-word (end the walk), encouragement (keep going), or a
        # real question/comment (pause the walk + release the turn to normal routing).
        # Consume it here before routers so a "stop" ends the whole mode, not just the
        # current leg, and encouragement doesn't get misrouted.
        # Passive object-answer capture (never consumes the turn). Two ledgers:
        # room_questions extracts an object IDENTITY ("that's my sourdough
        # starter"); object_qa stores the raw ANSWER to any object question
        # ("what's in the bowl?" → "frosted mini wheats"). This used to run only
        # during a room-exploration walk, so answers to lull/lean-cue/visual-
        # curiosity object questions were never captured and Rex re-asked
        # (field 2026-08-08: the bowl, twice in three minutes).
        if not game_conversation_lock:
            try:
                from intelligence import room_questions
                room_questions.maybe_capture_answer(text)
            except Exception:
                pass
            try:
                from intelligence import object_qa
                object_qa.maybe_capture_answer(text)
            except Exception:
                pass

        if not game_conversation_lock and exploration_flow_active():
            exploration_response = _handle_exploration_turn(text, person_id)
            if exploration_response:
                _record_heard_turn_once()
                _speak_blocking(
                    exploration_response,
                    emotion="neutral",
                    pre_beat_ms=100,
                    post_beat_ms_override=200,
                )
                conv_memory.add_to_transcript("Rex", exploration_response)
                conv_log.log_rex(exploration_response)
                _session_exchange_count += 1
                _register_rex_utterance(exploration_response, source="exploration")
                return

        # First-meeting onboarding burst: while a freshly-enrolled newcomer's
        # baseline burst is open, their turn is the answer to Rex's last
        # question. Consume it here (before routers) so the answer drives the
        # retort->next-question loop and is written as a baseline fact instead of
        # being misrouted. A pivot/decline returns None and releases the turn.
        if not game_conversation_lock and onboarding_flow_active():
            onboarding_response = _handle_onboarding_turn(text, person_id)
            if onboarding_response:
                _record_heard_turn_once()
                _speak_blocking(
                    onboarding_response,
                    emotion="curious",
                    pre_beat_ms=100,
                    post_beat_ms_override=200,
                )
                conv_memory.add_to_transcript("Rex", onboarding_response)
                conv_log.log_rex(onboarding_response)
                _session_exchange_count += 1
                _register_rex_utterance(
                    onboarding_response,
                    source="onboarding",
                    expected_reply_types=["answer", "statement"],
                )
                return

        # "Let me tell you about my coworker Daniel" — a pre-briefing about
        # someone who is NOT here. Runs its own short flow (name → gossip-or-
        # facts → details) and pre-populates the person DB so the dossier is
        # warm before the subject ever shows up. Active-flow turns are consumed
        # here so volunteered details never reach routers or get extracted as
        # facts about the TELLER. Falls back to recent engagement for the
        # teller identity, same as the introduction flow below.
        if not game_conversation_lock:
            tell_about_teller_id = person_id
            tell_about_teller_name = person_name
            if tell_about_teller_id is None and recent_engagement is not None:
                recent_id = recent_engagement.get("person_id")
                try:
                    tell_about_teller_id = int(recent_id) if recent_id is not None else None
                except (TypeError, ValueError):
                    tell_about_teller_id = None
                tell_about_teller_name = recent_engagement.get("name")
            tell_about_response = _handle_tell_about_turn(
                text,
                tell_about_teller_id,
                tell_about_teller_name,
            )
            if tell_about_response:
                _record_heard_turn_once()
                _speak_blocking(
                    tell_about_response,
                    emotion="happy",
                    pre_beat_ms=100,
                    post_beat_ms_override=200,
                )
                conv_memory.add_to_transcript("Rex", tell_about_response)
                conv_log.log_rex(tell_about_response)
                _session_exchange_count += 1
                _register_rex_utterance(
                    tell_about_response,
                    source="tell_about",
                    expected_reply_types=["answer", "statement"],
                )
                return

        # If the engaged person answers an unknown-face/off-camera moment with
        # an actual introduction ("this is my dad, Jeff"), let the dedicated
        # introduction flow consume it before generic identity handling. Speaker
        # ID often misses the introducer here, so fall back to recent engagement.
        intro_introducer_id = person_id
        intro_introducer_name = person_name
        if intro_introducer_id is None and recent_engagement is not None:
            recent_id = recent_engagement.get("person_id")
            try:
                intro_introducer_id = int(recent_id) if recent_id is not None else None
            except (TypeError, ValueError):
                intro_introducer_id = None
            intro_introducer_name = recent_engagement.get("name")
        # The speaker Rex is currently asking "who are you?" answering with a
        # name-only "This is X" is ANSWERING, not introducing a third party. With
        # person_id=None the introducer above is borrowed from recent engagement,
        # so without this guard the answer becomes "<friend> introduced X" and the
        # unknown voice is never enrolled or retired (field log 2026-08-22-20-12:
        # Joy answered the ask and stayed unknown_voice_1 for the whole visit).
        # The pending off-camera reply handler below consumes it instead.
        if (
            intro_introducer_id is not None
            and person_id is None
            and _challenged_voice_is_answering_whos_that(text, anonymous_speaker_label)
        ):
            _log.info(
                "[introduction] challenged unknown voice is answering the who's-that "
                "ask itself — not treating %r as an introduction by %r",
                text, intro_introducer_name,
            )
            intro_introducer_id = None
        if intro_introducer_id is not None and not game_conversation_lock:
            has_unknown_for_intro = has_unknown_visible_now
            parsed_intro = introductions.detect(
                text,
                has_unknown_face=has_unknown_for_intro,
            )
            if parsed_intro.is_introduction:
                introductions.note_introduction()  # stand down the mystery-guest agenda
            if parsed_intro.is_introduction and (
                parsed_intro.subject_kind == "pet"
                or has_unknown_for_intro
                # A relationship intro ("this is my brother Wade") is always an
                # introduction, never an answer — don't let a stale dialogue frame
                # suppress it. Only NAME-ONLY intros get the answer/mint check.
                or bool(parsed_intro.relationship)
                or (
                    bool(parsed_intro.name)
                    and not _intro_is_answer_to_rex_question(
                        has_unknown_for_intro, person_id=intro_introducer_id
                    )
                    and not _intro_would_mint_unknown_name(
                        parsed_intro,
                        person_id=intro_introducer_id,
                        off_camera_unknown=off_camera_unknown,
                        has_unknown_for_intro=has_unknown_for_intro,
                    )
                )
            ):
                intro_response = _handle_introduction_parse(
                    parsed_intro,
                    introducer_id=intro_introducer_id,
                    introducer_name=intro_introducer_name or f"person_{intro_introducer_id}",
                    visible_newcomer=has_unknown_for_intro,
                )
                off_camera_unknown = False
                rel_ctx_for_intro = consciousness.consume_relationship_prompt_request()
                if rel_ctx_for_intro is not None:
                    relationship_prompt_consumed = True
                    consciousness.note_relationship_slot_handled(
                        str(rel_ctx_for_intro.get("slot_id") or "")
                    )
                if intro_response:
                    _record_heard_turn_once()
                    _speak_blocking(
                        intro_response,
                        emotion="happy",
                        pre_beat_ms=150,
                        post_beat_ms_override=300,
                    )
                    conv_memory.add_to_transcript("Rex", intro_response)
                    conv_log.log_rex(intro_response)
                    _session_exchange_count += 1
                    _register_rex_utterance(intro_response)
                    return

        # Consciousness asked the ENGAGED person about an unknown newcomer.
        # Try to extract {name, relationship}, enroll the newcomer using the
        # current unknown face, and save the relationship edge.
        rel_ctx = (
            consciousness.consume_relationship_prompt_request()
            if not game_conversation_lock
            else None
        )
        relationship_prompt_consumed = relationship_prompt_consumed or rel_ctx is not None
        if rel_ctx is not None:
            relationship_response = _handle_relationship_reply(
                rel_ctx, text, person_id, person_name
            )
            if relationship_response:
                _record_heard_turn_once()
                _speak_blocking(
                    relationship_response,
                    emotion="happy",
                    pre_beat_ms=150,
                    post_beat_ms_override=300,
                )
                conv_memory.add_to_transcript("Rex", relationship_response)
                conv_log.log_rex(relationship_response)
                _session_exchange_count += 1
                _register_rex_utterance(relationship_response)
                return

        intro_voice_response = _handle_intro_voice_capture(
            text,
            audio_array,
            person_id,
            raw_best_id,
            speaker_score,
        )
        if intro_voice_response:
            _record_heard_turn_once()
            _speak_blocking(
                intro_voice_response,
                emotion="happy",
                pre_beat_ms=100,
                post_beat_ms_override=200,
            )
            conv_memory.add_to_transcript("Rex", intro_voice_response)
            conv_log.log_rex(intro_voice_response)
            _session_exchange_count += 1
            _register_rex_utterance(intro_voice_response)
            return

        # Targeted-forget confirmation, in the same pending-slot ladder as the scene
        # snapshot and ahead of it: this slot is only ever open for one turn after
        # Rex reads back what he would delete, and a bare "yes" must land here, not
        # in a general reply.
        forget_confirm_line = _handle_specific_forget_confirmation(text, person_id)
        if forget_confirm_line is not None:
            _record_heard_turn_once()
            _speak_blocking(forget_confirm_line, emotion="neutral")
            conv_memory.add_to_transcript("Rex", forget_confirm_line)
            conv_log.log_rex(forget_confirm_line)
            _session_exchange_count += 1
            _register_rex_utterance(forget_confirm_line)
            try:
                consciousness.clear_response_wait()
            except Exception:
                pass
            return

        scene_confirm_line = _handle_scene_snapshot_confirmation(text, person_id)
        if scene_confirm_line is not None:
            _record_heard_turn_once()
            _speak_blocking(scene_confirm_line, emotion="neutral")
            conv_memory.add_to_transcript("Rex", scene_confirm_line)
            conv_log.log_rex(scene_confirm_line)
            _session_exchange_count += 1
            _register_rex_utterance(scene_confirm_line)
            try:
                consciousness.clear_response_wait()
            except Exception:
                pass
            return

        # "Impersonate who?" was asked last turn — this turn is the name. Runs
        # BEFORE the capture handler: answering "me" opens the capture slot, so
        # the two must not both claim the same turn.
        impersonation_target = _handle_impersonation_target_prompt(text)
        if impersonation_target is not None:
            imp_line, imp_already_spoken = impersonation_target
            _record_heard_turn_once()
            if not imp_already_spoken:
                _speak_blocking(imp_line, emotion="curious", pre_beat_ms=100)
            _settle_response_wait_after_action()
            conv_memory.add_to_transcript("Rex", imp_line)
            conv_log.log_rex(imp_line)
            _session_exchange_count += 1
            _register_rex_utterance(imp_line)
            return

        impersonation_capture = _handle_impersonation_capture(
            text,
            audio_array,
            person_id,
            raw_best_id,
            speaker_score,
        )
        if impersonation_capture is not None:
            imp_line, imp_already_spoken = impersonation_capture
            _record_heard_turn_once()
            # already_spoken → perform() voiced the bit (intro/clone/outro); just log.
            if not imp_already_spoken:
                _speak_blocking(imp_line, emotion="curious", pre_beat_ms=100)
            # Slot still open (a too-short-clip re-ask) → re-arm the response wait
            # so proactive beats keep holding; slot closed (performed/canceled) →
            # clear it. Same settle rule as the takeover epilogue.
            _settle_response_wait_after_action()
            conv_memory.add_to_transcript("Rex", imp_line)
            conv_log.log_rex(imp_line)
            _session_exchange_count += 1
            _register_rex_utterance(imp_line)
            return

        # A standalone shutdown/sleep command outranks an opportunistic
        # intro-followup capture — should_capture_followup() would otherwise eat
        # "shut up, shut down" as a relationship story before the command lane.
        if command_parser.is_standalone_shutdown_command(text) or (
            command_parser.is_standalone_sleep_command(text)
        ):
            intro_followup_response = None
        else:
            intro_followup_response = _handle_intro_followup_answer(text)
        if intro_followup_response:
            _record_heard_turn_once()
            _speak_blocking(
                intro_followup_response,
                emotion="happy",
                pre_beat_ms=100,
                post_beat_ms_override=200,
            )
            conv_memory.add_to_transcript("Rex", intro_followup_response)
            conv_log.log_rex(intro_followup_response)
            _session_exchange_count += 1
            _register_rex_utterance(intro_followup_response)
            return

        if (
            _pending_introduction is not None
            # A standalone system command (shutdown/sleep) outranks a pending
            # introduction answer — never let "shut up, shut down" be eaten as
            # an introduction reply.
            and command_parser.parse(text) is None
        ):
            if introductions.context_fresh(_pending_introduction):
                expected_id = _pending_introduction.get("introducer_id")
                if person_id is None or expected_id is None or person_id == expected_id:
                    parsed_intro = introductions.parse_pending_answer(
                        text,
                        default_relationship=_pending_introduction.get("relationship"),
                    )
                    if parsed_intro.is_introduction:
                        intro_response = _handle_introduction_parse(
                            parsed_intro,
                            introducer_id=int(_pending_introduction["introducer_id"]),
                            introducer_name=_pending_introduction.get("introducer_name") or (person_name or "friend"),
                            visible_newcomer=bool(_pending_introduction.get("visible_newcomer", True)),
                        )
                        if intro_response:
                            _record_heard_turn_once()
                            _speak_blocking(
                                intro_response,
                                emotion="happy",
                                pre_beat_ms=150,
                                post_beat_ms_override=300,
                            )
                            conv_memory.add_to_transcript("Rex", intro_response)
                            conv_log.log_rex(intro_response)
                            _session_exchange_count += 1
                            _register_rex_utterance(intro_response)
                            return
            else:
                _pending_introduction = None

        if person_id is not None and not relationship_prompt_consumed:
            has_unknown_for_intro = has_unknown_visible_now
            parsed_intro = introductions.detect(
                text,
                has_unknown_face=has_unknown_for_intro,
            )
            if parsed_intro.is_introduction:
                introductions.note_introduction()  # stand down the mystery-guest agenda
            if parsed_intro.is_introduction and (
                parsed_intro.subject_kind == "pet"
                or has_unknown_for_intro
                # Relationship intros always introduce (see the other gate site).
                or bool(parsed_intro.relationship)
                or (
                    bool(parsed_intro.name)
                    and not _intro_is_answer_to_rex_question(
                        has_unknown_for_intro, person_id=person_id
                    )
                    and not _intro_would_mint_unknown_name(
                        parsed_intro,
                        person_id=person_id,
                        off_camera_unknown=off_camera_unknown,
                        has_unknown_for_intro=has_unknown_for_intro,
                    )
                )
            ):
                intro_response = _handle_introduction_parse(
                    parsed_intro,
                    introducer_id=person_id,
                    introducer_name=person_name or f"person_{person_id}",
                    visible_newcomer=has_unknown_for_intro,
                )
                if intro_response:
                    _record_heard_turn_once()
                    _speak_blocking(
                        intro_response,
                        emotion="happy",
                        pre_beat_ms=150,
                        post_beat_ms_override=300,
                    )
                    conv_memory.add_to_transcript("Rex", intro_response)
                    conv_log.log_rex(intro_response)
                    _session_exchange_count += 1
                    _register_rex_utterance(intro_response)
                    return

        existing_common_name_prompt = _maybe_prompt_existing_common_first_name(
            person_id,
            person_name,
            current_text=text,
        )
        if existing_common_name_prompt:
            _record_heard_turn_once()
            _speak_blocking(
                existing_common_name_prompt,
                emotion="curious",
                pre_beat_ms=100,
                post_beat_ms_override=200,
            )
            conv_memory.add_to_transcript("Rex", existing_common_name_prompt)
            conv_log.log_rex(existing_common_name_prompt)
            _session_exchange_count += 1
            _register_rex_utterance(existing_common_name_prompt)
            return

        # ── Address-mode classification ────────────────────────────────────────
        # If the utterance MENTIONS Rex but is not addressed TO him (e.g.
        # "say hi to Rex", "Rex is so fun"), do not generate a reply. Record
        # the mention to world_state.social.being_discussed so the consciousness
        # loop can decide whether to chime in. Skipped when Rex is in a pending
        # identity / face-reveal flow (those handlers expect this turn's text
        # as the user's reply).
        try:
            _addr_identity_window_active = identity_prompt_active
            if (
                getattr(config, "ADDRESS_MODE_ENABLED", True)
                and address_mode.contains_rex_keyword(text)
                and _pending_offscreen_identify is None
                and _pending_face_reveal_confirm is None
                and not _addr_identity_window_active
                # parser handles obvious commands directly; treat as direct.
                and command_parser.parse(text) is None
            ):
                ctx_bits: list[str] = []
                try:
                    crowd = world_state.get("crowd") or {}
                    cnt = crowd.get("count")
                    if isinstance(cnt, int):
                        ctx_bits.append(f"{cnt} people present")
                    dom = crowd.get("dominant_speaker")
                    if dom:
                        ctx_bits.append(f"dominant speaker slot {dom}")
                except Exception:
                    pass
                if person_name:
                    ctx_bits.append(f"speaker is {person_name}")
                # A fresh Rex-turn frame means we're mid-exchange with this
                # speaker — their "you/your robot" reply is aimed at Rex, not a
                # third party, so classify() skips the LLM guess (hard rules
                # still run: an explicit "say hi to Rex" keeps its
                # instructional read). Field failure 2026-08-12: the answer to
                # "New sensors for me?" — "…adding three radar sensors to your
                # body… your robot body" — was LLM-labeled instructional and
                # dropped without a HEARD line.
                reply_frame = None
                try:
                    reply_frame = dialogue_act.active_frame(person_id=person_id)
                except Exception:
                    pass
                in_active_exchange = False
                if reply_frame is not None:
                    if reply_frame.text:
                        ctx_bits.append(
                            "Rex's most recent line to this speaker: "
                            f'"{reply_frame.text[:160]}"'
                        )
                    frame_age = time.monotonic() - reply_frame.created_at
                    in_active_exchange = frame_age <= float(
                        getattr(config, "ADDRESS_MODE_EXCHANGE_FRESH_SECS", 45.0)
                    )
                addr = address_mode.classify(
                    text,
                    context="; ".join(ctx_bits),
                    in_active_exchange=in_active_exchange,
                )
                _log.info(
                    "[interaction] address_mode=%s sentiment=%s rule=%s exchange=%s text=%r",
                    addr.label, addr.sentiment, addr.rule, in_active_exchange, text[:120],
                )
                if addr.label in (
                    address_mode.ADDRESS_REFERENTIAL,
                    address_mode.ADDRESS_INSTRUCTIONAL,
                ):
                    _record_being_discussed(
                        text=text,
                        label=addr.label,
                        sentiment=addr.sentiment,
                        speaker_id=person_id,
                        speaker_name=person_name,
                    )
                    return
                # ADDRESS_UNRELATED → fall through to LLM; the model will
                # handle the coincidental reference naturally.
        except Exception as exc:
            _log.debug("[interaction] address_mode error (continuing): %s", exc)

        # Rex previously asked "who's that speaking?" about an off-camera unknown
        # voice. If this reply came from the engaged person and names the
        # off-camera speaker, enroll their voice (using the STORED audio of the
        # original utterance, not this engaged-person audio) and save a
        # relationship edge if the engaged person also stated one. The
        # off-camera person may also answer directly with a bare name like "JT".
        pending_offscreen_snapshot = (
            dict(_pending_offscreen_identify)
            if isinstance(_pending_offscreen_identify, dict)
            else {}
        )
        had_pending_offscreen_identify = bool(pending_offscreen_snapshot)
        if had_pending_offscreen_identify:
            _record_heard_turn_once()
        consumed_offscreen_identify, _offscreen_ack = _handle_pending_offscreen_identify_reply(
            text,
            person_id=person_id,
            person_name=person_name,
            audio_array=audio_array,
            anonymous_speaker_label=anonymous_speaker_label,
        )
        if consumed_offscreen_identify:
            answered_offscreen_question = {
                "question_key": "off_camera_identity",
                "question_text": str(
                    pending_offscreen_snapshot.get("question_text")
                    or "Who was that off-camera?"
                ),
                "answer_text": text,
                "depth_level": 1,
                "source": "offscreen_identify",
            }
            try:
                topic_thread.note_user_turn(
                    text,
                    person_id,
                    answered_question=answered_offscreen_question,
                )
            except Exception as exc:
                _log.debug("topic thread off-camera reply update failed: %s", exc)
            try:
                question_budget.note_user_turn(
                    text,
                    person_id,
                    answered_question=answered_offscreen_question,
                )
            except Exception as exc:
                _log.debug("question budget off-camera reply update failed: %s", exc)
            try:
                end_thread.note_user_turn(
                    text,
                    person_id,
                    answered_question=answered_offscreen_question,
                )
            except Exception as exc:
                _log.debug("end-thread off-camera reply update failed: %s", exc)
            response_text = _offscreen_ack
            completed = bool(_offscreen_ack)
            final_executed_path = "identity.offscreen_identify_reply"
            return

        # Dual-unknown intro handler: Rex asked the two unknown faces for names,
        # left first. Each answer binds name + face-at-position + the answer's voice.
        if _pending_dual_intro is not None:
            dual_consumed, dual_spoken = _handle_pending_dual_intro_reply(
                text, audio_array, anonymous_speaker_label
            )
            if dual_consumed:
                response_text = dual_spoken
                final_executed_path = "identity.dual_intro_reply"
                return

        # Face-reveal confirmation handler: Rex asked "is that you, X?" or
        # "are you on my left or my right?" — parse this reply and, if the
        # person (or the engaged person) confirms, bind the face to X and fire
        # the surprise+roast reaction.
        if _pending_face_reveal_confirm is not None:
            pending_fr = _pending_face_reveal_confirm
            now_mono = time.monotonic()
            fr_ttl = float(getattr(config, "FACE_REVEAL_CONFIRM_WINDOW_SECS", 30.0))
            if (now_mono - pending_fr["asked_at"]) > fr_ttl:
                _log.info("[interaction] face-reveal confirm window expired — clearing")
                _pending_face_reveal_confirm = None
            else:
                try:
                    fr_parsed = llm.extract_face_reveal_answer(text)
                except Exception as exc:
                    _log.debug("face-reveal extract error: %s", exc)
                    fr_parsed = {"intent": None}
                fr_intent = fr_parsed.get("intent")
                candidate_slots = pending_fr.get("candidates", [])

                chosen_encoding = None
                if pending_fr.get("mode") == "binary" and fr_intent in ("yes", "no"):
                    if fr_intent == "yes" and candidate_slots:
                        chosen_encoding = candidate_slots[0]["encoding"]
                    elif fr_intent == "no":
                        _face_reveal_declined.add(pending_fr["person_id"])
                        _log.info(
                            "[interaction] face-reveal declined for person_id=%s — won't re-ask this session",
                            pending_fr["person_id"],
                        )
                        _pending_face_reveal_confirm = None
                elif pending_fr.get("mode") == "lateral" and fr_intent in ("left", "right"):
                    # "left" from Rex's POV = smaller x in camera frame.
                    sorted_by_x = sorted(candidate_slots, key=lambda c: c["x"])
                    if fr_intent == "left" and sorted_by_x:
                        chosen_encoding = sorted_by_x[0]["encoding"]
                    elif fr_intent == "right" and sorted_by_x:
                        chosen_encoding = sorted_by_x[-1]["encoding"]

                if chosen_encoding is not None:
                    try:
                        people_memory.add_biometric(
                            pending_fr["person_id"], "face", chosen_encoding
                        )
                        _log.info(
                            "[interaction] face-reveal: bound face to person_id=%s name=%r (mode=%s intent=%s)",
                            pending_fr["person_id"], pending_fr["name"],
                            pending_fr["mode"], fr_intent,
                        )
                        # Fire the surprise+roast reaction asynchronously via
                        # the normal response path: skip normal response for
                        # this turn and speak a custom reveal line instead.
                        reveal_name = pending_fr["name"] or "you"
                        first_reveal = _first_name_or(reveal_name, "you")
                        try:
                            reveal_text = llm.get_response(
                                f"You just confirmed the face of someone you previously only "
                                f"knew by voice. Their name is {first_reveal}. You are seeing "
                                f"their face for the FIRST time. In ONE short in-character "
                                f"Rex line, react with surprise at what they look like compared "
                                f"to the mental picture you had from their voice — AND slip in "
                                f"a light roast about the mismatch. Address {first_reveal} by "
                                f"name. One line only."
                            )
                            if reveal_text:
                                _speak_blocking(reveal_text)
                                conv_memory.add_to_transcript("Rex", reveal_text)
                                conv_log.log_rex(reveal_text)
                                _register_rex_utterance(reveal_text)
                                _log.info(
                                    "[interaction] face-reveal reaction: %r", reveal_text,
                                )
                        except Exception as exc:
                            _log.debug("face-reveal reaction error: %s", exc)
                    except Exception as exc:
                        _log.error("face-reveal binding failed: %s", exc)
                    _pending_face_reveal_confirm = None
                    # Skip normal LLM response; the reveal line IS the response.
                    return

        # If we don't recognize the speaker but there is an unknown person visible,
        # attempt self-identification enrollment from this utterance.
        #
        # Also: when Rex has *just asked* an unknown person for their name
        # (_identity_prompt_until > now) and an unknown face is visible, force
        # the enrollment path even if speaker-ID wrongly matched the voice to
        # an existing known person. Without this, a newcomer whose voice is not
        # yet enrolled gets collapsed into the nearest known voice print and
        # their reply never triggers enrollment.
        now_mono = time.monotonic()
        identity_prompt_active = now_mono <= _identity_prompt_until
        has_unknown = _has_unknown_visible_or_recent()
        should_attempt_enroll = (
            (person_id is None and (has_unknown or identity_prompt_active))
            or (identity_prompt_active and has_unknown)
        )
        if should_attempt_enroll:
            allow_bare = identity_prompt_active
            intro_name = _extract_introduced_name(text, allow_bare_name=allow_bare)
            if intro_name:
                # Distinguish "newcomer self-introducing" from "known person
                # describing the newcomer." When the speaker already resolves
                # to a known person AND an unknown face is visible, the
                # utterance is the known person telling Rex who the new face
                # is — so we must NOT bind the speaker's voice to the new
                # person's identity and we must NOT reattribute this turn's
                # speech to the newcomer.
                describing_newcomer = (
                    person_id is not None and has_unknown
                )
                prior_engagement = None
                try:
                    prior_engagement = consciousness.get_recent_engagement()
                except Exception:
                    prior_engagement = None

                if describing_newcomer:
                    # Face-only enrollment for the unknown face. Try to extract
                    # a relationship label from the same utterance; save an
                    # edge if found. Speaker identity (person_id/person_name)
                    # is preserved.
                    parsed_name = intro_name
                    relationship: Optional[str] = None
                    try:
                        parsed = llm.extract_relationship_introduction(
                            text, person_name or "friend"
                        )
                        parsed_name_from_llm, relationship = (
                            _filter_relationship_introduction_evidence(
                                parsed,
                                text,
                                person_name or "friend",
                                source="describe_newcomer",
                            )
                        )
                        parsed_name = parsed_name_from_llm or intro_name
                    except Exception as exc:
                        _log.debug("describe-newcomer extract error: %s", exc)

                    new_id: Optional[int] = None
                    try:
                        new_id, created = people_memory.find_or_create_person(parsed_name)
                    except Exception as exc:
                        _log.warning("describe-newcomer find_or_create_person failed: %s", exc)

                    if new_id is not None:
                        first_inc = config.FAMILIARITY_INCREMENTS.get(
                            "first_enrollment", 0.0
                        )
                        if created and first_inc > 0:
                            people_memory.update_familiarity(new_id, first_inc)
                        try:
                            from vision import camera as _cam_mod
                            from vision import face as _face_mod
                            frame = _cam_mod.capture_still()
                            if frame is not None:
                                if _face_mod.enroll_unknown_face(new_id, frame):
                                    threading.Thread(
                                        target=_face_mod.update_appearance,
                                        args=(new_id, frame.copy()),
                                        daemon=True,
                                        name=f"appearance-enroll-{new_id}",
                                    ).start()
                        except Exception as exc:
                            _log.warning(
                                "describe-newcomer face enroll failed: %s", exc
                            )
                        if relationship:
                            try:
                                from memory import social as social_memory
                                social_memory.save_relationship(
                                    from_person_id=person_id,
                                    to_person_id=new_id,
                                    relationship=relationship,
                                    described_by=person_id,
                                )
                            except Exception as exc:
                                _log.warning(
                                    "describe-newcomer save_relationship failed: %s",
                                    exc,
                                )
                        _log.info(
                            "[interaction] describe-newcomer enrollment: "
                            "speaker=%r (person_id=%s) named the unknown face "
                            "as %r (person_id=%s, relationship=%s); voice NOT "
                            "rebound to newcomer.",
                            person_name, person_id, parsed_name, new_id,
                            relationship or "—",
                        )
                        _episodic_person_enrolled(new_id, parsed_name, created=created)
                        _identity_prompt_until = 0.0
                else:
                    if _maybe_ask_prompted_name_confirmation(
                        intro_name,
                        audio_array,
                        raw_text=text,
                        prior_engagement=prior_engagement,
                        anonymous_speaker_label=anonymous_speaker_label,
                        enroll_unknown_face=bool(prior_engagement),
                        defer_face_enrollment=identity_prompt_active,
                    ):
                        return

                    if _maybe_ask_identity_match_confirmation(
                        intro_name,
                        audio_array,
                        prior_engagement=prior_engagement,
                        anonymous_speaker_label=anonymous_speaker_label,
                        enroll_unknown_face=bool(prior_engagement),
                        defer_face_enrollment=identity_prompt_active,
                        source="prompted_identity",
                    ):
                        return

                    # Newcomer self-introduction. Existing flow.
                    enrolled_id = _enroll_new_person(
                        intro_name,
                        audio_array,
                        enroll_unknown_face=bool(prior_engagement),
                        defer_face_enrollment=identity_prompt_active,
                    )
                    if enrolled_id is not None:
                        if person_id is not None and person_id != enrolled_id:
                            _log.info(
                                "[interaction] enrollment overrode speaker-ID mismatch: "
                                "speaker_id said person_id=%s, identity prompt replied %r → new person_id=%s",
                                person_id, intro_name, enrolled_id,
                            )
                        person_id = enrolled_id
                        person_name = intro_name
                        _retire_anonymous_speaker_slot(
                            anonymous_speaker_label,
                            person_id=person_id,
                            person_name=person_name,
                        )
                        _character_loop_note_speaker(
                            character_trace,
                            person_id=person_id,
                            person_name=person_name,
                            speaker_label=person_name or "user",
                            identity_resolution="prompted_identity_enrollment",
                            off_camera_unknown=False,
                            visible_known_count=len(visible_known_by_id),
                            has_unknown_visible_or_recent=has_unknown_visible_or_recent,
                        )
                        _identity_prompt_until = 0.0
                        _identity_reask_count = 0
                        prompted_identity_ack_text = _identity_enrollment_ack(intro_name)

                        # Chain into a relationship follow-up if we were just
                        # engaged with someone else — set a flag for the post-
                        # response hook to ask "how do you know <name>?"
                        if prior_engagement and prior_engagement.get("person_id") != enrolled_id:
                            _pending_post_greet_relationship[0] = {
                                "prior_engaged_id": prior_engagement["person_id"],
                                "prior_engaged_name": prior_engagement.get("name"),
                                "newcomer_person_id": enrolled_id,
                                "newcomer_name": intro_name,
                            }
                        _mark_single_name_for_later_last_name(enrolled_id, intro_name)
            else:
                # Rex had just asked an unidentified speaker their name
                # (identity_prompt_active; the direct-turn deferral above already
                # let this through as a name reply), but the transcript yielded no
                # usable name — typically Rex's own question tail bleeding into the
                # mic ("...save for you?" → "for you, Bret."). Gently re-ask instead
                # of routing to the open-ended LLM, which would otherwise be handed
                # BOTH this name-bearing transcript AND the "ask their name" agenda
                # and answer with the contradictory "Bret, got it… what do I call
                # you?" (live-logged 2026-06-18). Bounded so garble can't loop.
                reask_cap = int(getattr(config, "IDENTITY_PROMPT_REASK_MAX", 2))
                if (
                    identity_prompt_active
                    and person_id is None
                    and command_parser.parse(text) is None
                    and _identity_reask_count < reask_cap
                ):
                    _identity_reask_count += 1
                    reask_text = _identity_reask_line()
                    _record_heard_turn_once()
                    _speak_blocking(
                        reask_text,
                        emotion="neutral",
                        pre_beat_ms=100,
                        post_beat_ms_override=200,
                    )
                    conv_memory.add_to_transcript("Rex", reask_text)
                    conv_log.log_rex(reask_text)
                    _session_exchange_count += 1
                    _register_rex_utterance(reask_text)
                    # Keep the bare-name window open for their next try; do NOT
                    # re-arm a proactive consciousness prompt — that, with the
                    # counter, is what bounds the loop.
                    _identity_prompt_until = time.monotonic() + _IDENTITY_REPLY_WINDOW_SECS
                    final_executed_path = "identity_prompt.reask_unparsed"
                    _log.info(
                        "[interaction] identity prompt reply unparsable — gently "
                        "re-asking (attempt %d/%d) text=%r",
                        _identity_reask_count,
                        reask_cap,
                        text,
                    )
                    return
                if identity_prompt_active and _identity_reask_count >= reask_cap:
                    # Tried enough times; stop badgering and let the turn flow
                    # normally so Rex doesn't become a broken record.
                    _identity_prompt_until = 0.0
                    _identity_reask_count = 0
                    _log.info(
                        "[interaction] identity prompt re-ask cap reached — "
                        "dropping prompt, turn flows normally text=%r",
                        text,
                    )

        # If Rex had an outstanding event follow-up question, treat this utterance
        # as the outcome and close the loop in memory.
        _followup_ack = _resolve_awaiting_followup(text, person_id)
        if _followup_ack:
            event_cancellation_ack = _followup_ack

        if person_id is not None:
            _session_person_ids.add(person_id)
            voice_name = person_name or f"person_{person_id}"
            print(f"[VOICE] Known voice detected: {voice_name} (person_id={person_id})", flush=True)
            # Mark this person as Rex's current conversational partner. Consciousness
            # uses this to suppress presence reactions about them while engaged.
            try:
                consciousness.mark_engagement(person_id)
                consciousness.note_person_spoke(person_id)
            except Exception:
                pass
        else:
            unknown_voice_label = anonymous_speaker_label or "unknown"
            print(f"[VOICE] Unknown voice detected: {unknown_voice_label}", flush=True)

        _record_heard_turn_once()

        if prompted_identity_ack_text:
            try:
                consciousness.note_person_greeted_this_session(person_id)
            except Exception:
                pass
            completed = _speak_blocking(
                prompted_identity_ack_text,
                emotion="happy",
                pre_beat_ms=100,
                post_beat_ms_override=200,
            )
            response_text = prompted_identity_ack_text
            final_executed_path = "identity.prompted_enrollment_ack"
            suppress_memory_learning = True
            _dismiss_pending_consent_prompts(person_id, text)
            try:
                consciousness.clear_response_wait()
            except Exception:
                pass
            conv_memory.add_to_transcript("Rex", prompted_identity_ack_text)
            conv_log.log_rex(prompted_identity_ack_text)
            _session_exchange_count += 1
            _register_rex_utterance(prompted_identity_ack_text)
            return

        memory_wipe_response = _handle_pending_memory_wipe_confirmation(text, person_id)
        if memory_wipe_response:
            response_text = memory_wipe_response
            final_executed_path = "memory.pending_wipe_confirmation"
            try:
                consciousness.clear_response_wait()
            except Exception:
                pass
            conv_memory.add_to_transcript("Rex", memory_wipe_response)
            conv_log.log_rex(memory_wipe_response)
            _session_exchange_count += 1
            _register_rex_utterance(memory_wipe_response)
            return

        if _is_bare_wake_address(text):
            if _bare_wake_should_ask_visible_unknown_identity(
                person_id=person_id,
                identity_prompt_active=(time.monotonic() <= _identity_prompt_until),
                has_unknown_visible_or_recent=has_unknown_visible_or_recent,
                game_conversation_lock=game_conversation_lock,
            ):
                identity_question = _ask_visible_unknown_identity_question(
                    text,
                    recent_engagement=recent_engagement,
                    group_chatter_active=group_chatter_active,
                    source="bare_wake_address",
                )
                if identity_question:
                    final_executed_path = "identity_prompt.visible_unknown_wake"
                    completed = True
                    response_text = identity_question
                    return

            _log.info("[wake_word] transcribed wake address fast-ack text=%r", text)
            _wake_ack()
            final_executed_path = "wake_address.ack"
            completed = True
            response_text = "(wake acknowledgment)"
            try:
                consciousness.clear_response_wait()
            except Exception:
                pass
            return

        name_update_decision = None
        try:
            explicit_name_decision = action_router.classify_explicit_control(text)
            if (
                explicit_name_decision is not None
                and explicit_name_decision.action == "identity.name_correction"
            ):
                name_update_decision = explicit_name_decision
        except Exception as exc:
            _log.debug("pre-router identity correction classification failed: %s", exc)

        name_update_response = _handle_name_update_request(
            text,
            person_id,
            person_name,
        )
        if name_update_response:
            if name_update_decision is not None:
                try:
                    name_update_context = _action_router_context(
                        text,
                        person_id=person_id,
                        person_name=person_name,
                        raw_best_id=raw_best_id,
                        raw_best_name=raw_best_name,
                        speaker_score=speaker_score,
                        recent_engagement=recent_engagement,
                        off_camera_unknown=off_camera_unknown,
                        identity_prompt_active=identity_prompt_active,
                    )
                    name_update_audit = _new_router_audit(text, name_update_context)
                    _router_audit_note_decision(name_update_audit, name_update_decision)
                    _log_router_audit(
                        name_update_audit,
                        "fast_local_takeover.identity.name_correction",
                        spoken_text=name_update_response,
                    )
                    router_audit = name_update_audit
                except Exception as exc:
                    _log.debug("pre-router identity correction audit failed: %s", exc)
            response_text = name_update_response
            final_executed_path = "fast_local_takeover.identity.name_correction"
            _dismiss_pending_consent_prompts(person_id, text)
            try:
                consciousness.clear_response_wait()
            except Exception:
                pass
            conv_memory.add_to_transcript("Rex", name_update_response)
            conv_log.log_rex(name_update_response)
            _session_exchange_count += 1
            _register_rex_utterance(name_update_response)
            return

        # Active games get first claim on ordinary utterances after explicit
        # corrections/stop commands. Identity prompts otherwise steal roster
        # answers like "Will, Jen, Daniel, and Bret" as mystery voices.
        try:
            from features import games as games_mod
            if games_mod.is_active():
                # This is the EARLY claim and it returns, so it is the one that
                # decides who owns a mid-game turn. Its bare-word set used to be a
                # near-copy of the later site's and had drifted (see
                # _game_escape_command).
                game_escape = _game_escape_command(text)
                if game_escape is None:
                    game_response = games_mod.handle_input(text, person_id, audio_array)
                    completed = _speak_blocking(game_response)
                    response_text = game_response
                    final_executed_path = "game.active_turn.early"
                    suppress_memory_learning = True
                    if completed:
                        games_mod.on_response_spoken()
                        game_after_audio_path = games_mod.consume_pending_audio_after_response()
                    conv_memory.add_to_transcript("Rex", game_response)
                    conv_log.log_rex(game_response)
                    _session_exchange_count += 1
                    _register_rex_utterance(game_response)
                    assistant_asked_question = _assistant_asked_question(game_response)
                    if sequence_started:
                        echo_cancel.end_sequence(
                            flush=False,
                            tail_secs=_reply_playback_tail_secs(assistant_asked_question),
                        )
                        sequence_started = False
                        if game_after_audio_path and not _interrupted.is_set():
                            speech_queue.enqueue_audio_file(
                                game_after_audio_path,
                                priority=1,
                                tag="game:after_audio",
                            )
                    try:
                        interoception.record_interaction()
                    except Exception as exc:
                        _log.debug("active game interoception error: %s", exc)
                    return
        except Exception as exc:
            _log.debug("early active game routing failed: %s", exc)

        music_offer_response = _handle_pending_music_offer_reply(person_id, text)
        if music_offer_response:
            response_text = music_offer_response
            final_executed_path = "music.pending_offer_reply"
            _dismiss_pending_consent_prompts(person_id, text)
            try:
                consciousness.clear_response_wait()
            except Exception:
                pass
            conv_memory.add_to_transcript("Rex", music_offer_response)
            conv_log.log_rex(music_offer_response)
            _session_exchange_count += 1
            _register_rex_utterance(music_offer_response)
            return

        pending_question_for_turn = _latest_pending_question(person_id)
        music_pref_response, answered_question = _handle_pending_music_preference_answer(
            person_id,
            text,
            pending_question=pending_question_for_turn,
            identity_prompt_active=identity_prompt_active,
        )
        if music_pref_response:
            response_text = music_pref_response
            final_executed_path = "music.pending_preference_answer"
            try:
                if answered_question:
                    topic_thread.note_answered_question(answered_question)
            except Exception as exc:
                _log.debug("topic thread music preference answer update failed: %s", exc)
            try:
                question_budget.note_user_turn(
                    text,
                    person_id,
                    answered_question=answered_question,
                )
            except Exception as exc:
                _log.debug("question budget music preference update failed: %s", exc)
            try:
                end_thread.note_user_turn(
                    text,
                    person_id,
                    answered_question=answered_question,
                )
            except Exception as exc:
                _log.debug("end thread music preference update failed: %s", exc)
            _dismiss_pending_consent_prompts(person_id, text)
            try:
                consciousness.clear_response_wait()
            except Exception:
                pass
            conv_memory.add_to_transcript("Rex", music_pref_response)
            conv_log.log_rex(music_pref_response)
            _session_exchange_count += 1
            _register_rex_utterance(music_pref_response)
            return

        if answered_question is None and pending_question_for_turn:
            answered_question = _maybe_capture_pending_qa(
                person_id,
                text,
                identity_prompt_active=identity_prompt_active,
            )
        if answered_question is None:
            answered_question = _maybe_capture_topic_thread_answer(
                person_id,
                text,
                identity_prompt_active=identity_prompt_active,
            )

        router_context = None
        try:
            router_context = _action_router_context(
                text,
                person_id=person_id,
                person_name=person_name,
                raw_best_id=raw_best_id,
                raw_best_name=raw_best_name,
                speaker_score=speaker_score,
                recent_engagement=recent_engagement,
                off_camera_unknown=off_camera_unknown,
                identity_prompt_active=identity_prompt_active,
            )
            router_audit = _new_router_audit(text, router_context)
            dialogue_decision = dialogue_act.classify(
                text,
                router_context,
                person_id=person_id,
            )
            router_context["dialogue_act"] = dialogue_decision.as_context()
            _log.info(
                "[dialogue_act] label=%s conf=%.2f reason=%s frame_source=%s "
                "frame_topic=%r skip_router=%s",
                dialogue_decision.label,
                float(dialogue_decision.confidence or 0.0),
                dialogue_decision.reason,
                dialogue_decision.frame.source if dialogue_decision.frame else None,
                dialogue_decision.frame.topic if dialogue_decision.frame else "",
                dialogue_decision.skip_action_router,
            )

            # If the dialogue gate bound this turn as an ANSWER to a Rex question (e.g. a
            # remembered-event memory_followup like "how did the festival go?") but none
            # of the tracked-QA captures above claimed it, synthesize answered_question
            # from the frame so the agenda gives the strong "they just answered Q: …"
            # directive. Without it the generic "react to what they said" directive lets
            # the LLM misread a terse answer like "That was good" as praise OF Rex —
            # live-logged 2026-06-20: it replied "I appreciate a clean compliment" and
            # then re-asked the festival question.
            if (
                answered_question is None
                and dialogue_decision.label == "answer_to_rex"
                and dialogue_decision.frame is not None
                and (getattr(dialogue_decision.frame, "text", "") or "").strip()
                # An explicit motion imperative ("move forward") is a PHYSICAL command,
                # never the answer to Rex's question — don't record it as one, even if the
                # base is suppressed (manual/paused) and the command falls through to chat.
                and action_router.classify_explicit_motion(text) is None
            ):
                answered_question = {
                    "question_text": dialogue_decision.frame.text.strip(),
                    "answer_text": text,
                }

            # A pet-guess answer settles the animal's name for the session:
            # "Yeah, it's Max" answering "Bret, is that Max?" must retire every
            # later hedge ("Still calling it Max until Bret tells me otherwise"
            # was spoken TO Bret two minutes AFTER he confirmed — field
            # 2026-08-19 22:25).
            if (
                dialogue_decision.label == "answer_to_rex"
                and dialogue_decision.frame is not None
                and getattr(dialogue_decision.frame, "source", "")
                == "world.animal_arrival"
            ):
                try:
                    from intelligence import consciousness as _consc
                    _consc.note_pet_guess_answer(text)
                except Exception:
                    pass

            # Explicit drive-base motion is a PHYSICAL command, not an answer to Rex — run
            # it even when the dialogue gate would skip the router, else commands spoken
            # right after Rex speaks get swallowed as conversation (live-logged 2026-06-23:
            # "move forward." / "Move backwards" -> conversation.reply).
            fast_takeover_response = _explicit_motion_takeover(
                text, person_id=person_id, router_audit=router_audit
            )
            # An INVITE to explore the room ("look around a little", "make yourself at
            # home") is likewise a command, not an answer — start the self-directed
            # wander before the dialogue gate. Runs after the motion takeover so a
            # "turn around" is still a turn.
            if fast_takeover_response is None:
                fast_takeover_response = _explore_invite_takeover(
                    text,
                    person_id=person_id,
                    person_name=person_name,
                    router_audit=router_audit,
                )
            # An explicit "impersonate me" is likewise a command, not an answer —
            # it must run even when the dialogue gate would skip the router
            # (answer_to_rex sets skip_action_router; live-logged 2026-07-19 21:09:
            # Rex asked "what's up?" and "impersonate me" was swallowed as chat).
            if fast_takeover_response is None:
                fast_takeover_response = _explicit_impersonation_takeover(
                    text,
                    person_id=person_id,
                    person_name=person_name,
                    router_audit=router_audit,
                )
            if fast_takeover_response is None and not dialogue_decision.skip_action_router:
                fast_takeover_response = _handle_fast_local_takeover(
                    text,
                    person_id=person_id,
                    person_name=person_name,
                    router_context=router_context,
                    dialogue_decision=dialogue_decision,
                    router_audit=router_audit,
                )
            if fast_takeover_response is not None:
                silent_command = _is_silent_command_response(fast_takeover_response)
                response_text = None if silent_command else fast_takeover_response
                final_executed_path = _router_audit_fast_local_final_path(router_audit)
                _log_router_audit(
                    router_audit,
                    final_executed_path,
                    completed=True,
                    spoken_text=None if silent_command else fast_takeover_response,
                    spoken_text_present=False if silent_command else None,
                )
                if final_executed_path and (
                    "directed_look" in final_executed_path
                    or "vision.directed_search" in final_executed_path
                ):
                    suppress_memory_learning = True
                _dismiss_pending_consent_prompts(person_id, text)
                _settle_response_wait_after_action()
                if not silent_command:
                    conv_memory.add_to_transcript("Rex", fast_takeover_response)
                    conv_log.log_rex(fast_takeover_response)
                    _session_exchange_count += 1
                    _register_rex_utterance(fast_takeover_response)
                return
            if dialogue_decision.skip_action_router:
                router_decision = action_router.ActionDecision(
                    action="conversation.reply",
                    confidence=dialogue_decision.confidence,
                    args={"dialogue_act": dialogue_decision.label},
                    reason=f"{dialogue_decision.reason}; conversation owns ambiguity",
                )
                _router_audit_note_decision(
                    router_audit,
                    router_decision,
                    text=text,
                    context=router_context,
                    dialogue_decision=dialogue_decision,
                )
                _log.info(
                    "[action_router] skipped blocking router — dialogue_act=%s reason=%s",
                    dialogue_decision.label,
                    dialogue_decision.reason,
                )
            elif bool(getattr(config, "ACTION_ROUTER_EXECUTE_ENABLED", False)):
                router_started = time.monotonic()
                router_decision = action_router.decide(text, router_context)
                _latency_log(turn_start, "action_router", router_started)
                action_router.log_decision(router_decision, router_context, mode="execute")
                # Phase 0 tool-router shadow: fire-and-forget comparison of the
                # conversation model's tool choice vs the shipped decision
                # (docs/tool_router_scope.md). No-op unless enabled in config.
                try:
                    from intelligence import tool_router
                    tool_router.start_shadow(text, router_context, router_decision.action)
                except Exception as exc:
                    _log.debug("[tool_router] shadow launch failed: %s", exc)
                _router_audit_note_decision(
                    router_audit,
                    router_decision,
                    text=text,
                    context=router_context,
                    dialogue_decision=dialogue_decision,
                )
            else:
                _router_audit_note_execute_disabled(router_audit)
                action_router.start_shadow_decision(text, router_context)
            router_block_reason = _router_execution_block_reason(
                router_decision,
                text=text,
                context=router_context,
                dialogue_decision=dialogue_decision,
            )
            if router_block_reason is None:
                suppress_memory_learning = True
            elif _conversation_reply_should_skip_memory_learning(text, router_decision):
                suppress_memory_learning = True
                _log.info(
                    "[memory] suppressing extraction for general-knowledge router reply text=%r",
                    text,
                )
            elif _router_nonexecuted_should_suppress_memory_learning(router_decision):
                suppress_memory_learning = True
                _log.info(
                    "[action_router] not executing action=%s confidence=%.2f reason=%s",
                    router_decision.action,
                    float(router_decision.confidence or 0.0),
                    router_block_reason,
                )
        except Exception as exc:
            _log.debug("action router shadow start failed: %s", exc)
        blocked_router_response = _router_blocked_confirmation_response(
            router_decision,
            router_block_reason,
            person_id=person_id,
        )
        if blocked_router_response:
            completed = _speak_blocking(blocked_router_response, emotion="neutral")
            response_text = blocked_router_response
            final_executed_path = (
                f"router_confirmation.{router_decision.action if router_decision else 'unknown'}"
            )
            _log_router_audit(
                router_audit,
                final_executed_path,
                completed=completed,
                spoken_text=blocked_router_response,
            )
            _dismiss_pending_consent_prompts(person_id, text)
            try:
                consciousness.clear_response_wait()
            except Exception:
                pass
            conv_memory.add_to_transcript("Rex", blocked_router_response)
            conv_log.log_rex(blocked_router_response)
            _session_exchange_count += 1
            _register_rex_utterance(blocked_router_response)
            return
        try:
            topic_thread.note_user_turn(
                text, person_id, answered_question=answered_question
            )
        except Exception as exc:
            _log.debug("topic thread user update failed: %s", exc)
        try:
            user_energy.note_user_turn(
                text, person_id, answered_question=answered_question
            )
        except Exception as exc:
            _log.debug("user energy text update failed: %s", exc)

        boundary_person_id = person_id
        if boundary_person_id is None and _EMOTIONAL_BOUNDARY_PAT.search(text):
            try:
                boundary_person_id = consciousness.get_last_memory_hint_target()
            except Exception:
                boundary_person_id = None
            if boundary_person_id is None and recent_engagement and not _has_unknown_visible_or_recent():
                try:
                    boundary_person_id = int(recent_engagement.get("person_id"))
                except (TypeError, ValueError):
                    boundary_person_id = None
            if boundary_person_id is not None:
                _log.info(
                    "[interaction] emotional boundary attributed to recent memory target "
                    "person_id=%s despite uncertain speaker",
                    boundary_person_id,
                )

        boundary_response = _handle_emotional_checkin_boundary(boundary_person_id, text)
        if boundary_response:
            _dismiss_pending_consent_prompts(boundary_person_id, text)
            try:
                consciousness.clear_response_wait()
            except Exception:
                pass
            completed = _speak_blocking(
                boundary_response,
                emotion="neutral",
                pre_beat_ms=200,
                post_beat_ms_override=300,
            )
            response_text = boundary_response
            final_executed_path = "legacy.emotional_checkin_boundary"
            _log_router_audit(
                router_audit,
                final_executed_path,
                completed=completed,
                spoken_text=boundary_response,
            )
            conv_memory.add_to_transcript("Rex", boundary_response)
            conv_log.log_rex(boundary_response)
            _session_exchange_count += 1
            _register_rex_utterance(boundary_response)
            return

        speaker_correction_ack = _handle_speaker_correction(text, person_id, person_name)
        if speaker_correction_ack:
            try:
                consciousness.clear_response_wait()
            except Exception:
                pass
            # The correction utterance itself teaches nothing durable about the speaker.
            conv_memory.mark_last_human_turn_unlearnable()
            completed = _speak_blocking(
                speaker_correction_ack,
                emotion="neutral",
                pre_beat_ms=100,
                post_beat_ms_override=200,
            )
            response_text = speaker_correction_ack
            final_executed_path = "legacy.speaker_correction"
            _log_router_audit(
                router_audit,
                final_executed_path,
                completed=completed,
                spoken_text=speaker_correction_ack,
            )
            conv_memory.add_to_transcript("Rex", speaker_correction_ack)
            conv_log.log_rex(speaker_correction_ack)
            _session_exchange_count += 1
            _register_rex_utterance(speaker_correction_ack)
            return

        preference_response = _handle_conversation_boundary(person_id, text)
        if preference_response:
            _dismiss_pending_consent_prompts(person_id, text)
            try:
                consciousness.clear_response_wait()
            except Exception:
                pass
            completed = _speak_blocking(
                preference_response,
                emotion="neutral",
                pre_beat_ms=100,
                post_beat_ms_override=200,
            )
            response_text = preference_response
            final_executed_path = "legacy.conversation_boundary"
            _log_router_audit(
                router_audit,
                final_executed_path,
                completed=completed,
                spoken_text=preference_response,
            )
            conv_memory.add_to_transcript("Rex", preference_response)
            conv_log.log_rex(preference_response)
            _session_exchange_count += 1
            _register_rex_utterance(preference_response)
            return

        router_takeover_response = _handle_router_takeover_action(
            router_decision,
            text,
            person_id=person_id,
            person_name=person_name,
            raw_best_id=raw_best_id,
            raw_best_name=raw_best_name,
            raw_best_score=speaker_score,
            router_context=router_context,
            dialogue_decision=dialogue_decision,
            router_audit=router_audit,
        )
        if router_takeover_response:
            response_text = router_takeover_response
            final_executed_path = (
                f"router_takeover.{router_decision.action if router_decision else 'unknown'}"
            )
            _log_router_audit(
                router_audit,
                final_executed_path,
                spoken_text=router_takeover_response,
            )
            _dismiss_pending_consent_prompts(person_id, text)
            _settle_response_wait_after_action()
            conv_memory.add_to_transcript("Rex", router_takeover_response)
            conv_log.log_rex(router_takeover_response)
            _session_exchange_count += 1
            _register_rex_utterance(router_takeover_response)
            return
        if (
            _router_decision_executable(
                router_decision,
                text=text,
                context=router_context,
                dialogue_decision=dialogue_decision,
            )
            and router_decision.action not in {"conversation.reply", "emotional.boundary"}
        ):
            _router_audit_note_result(
                router_audit,
                handler_error="router_takeover_no_response",
            )

        if (
            _router_decision_executable(
                router_decision,
                text=text,
                context=router_context,
                dialogue_decision=dialogue_decision,
            )
            and router_decision.action == "emotional.boundary"
        ):
            router_boundary_person_id = boundary_person_id or person_id
            if router_boundary_person_id is None and recent_engagement and not _has_unknown_visible_or_recent():
                try:
                    router_boundary_person_id = int(recent_engagement.get("person_id"))
                except (TypeError, ValueError):
                    router_boundary_person_id = None
            boundary_response = _handle_router_emotional_boundary(
                router_boundary_person_id,
                text,
                topic_hint=(
                    _session_router_control_topics.get(int(router_boundary_person_id))
                    if router_boundary_person_id is not None
                    else None
                ),
            )
            if boundary_response:
                _dismiss_pending_consent_prompts(router_boundary_person_id, text)
                try:
                    consciousness.clear_response_wait()
                except Exception:
                    pass
                completed = _speak_blocking(
                    boundary_response,
                    emotion="neutral",
                    pre_beat_ms=200,
                    post_beat_ms_override=300,
                )
                response_text = boundary_response
                final_executed_path = "router_takeover.emotional.boundary"
                _log_router_audit(
                    router_audit,
                    final_executed_path,
                    completed=completed,
                    spoken_text=boundary_response,
                )
                conv_memory.add_to_transcript("Rex", boundary_response)
                conv_log.log_rex(boundary_response)
                _session_exchange_count += 1
                _register_rex_utterance(boundary_response)
                return

        if answered_question is None:
            answered_question = _maybe_capture_pending_qa(
                person_id,
                text,
                identity_prompt_active=identity_prompt_active,
            )
        if answered_question is None:
            answered_question = _maybe_capture_topic_thread_answer(
                person_id,
                text,
                identity_prompt_active=identity_prompt_active,
            )
        try:
            if answered_question:
                topic_thread.note_answered_question(answered_question)
        except Exception as exc:
            _log.debug("topic thread answer update failed: %s", exc)
        try:
            question_budget.note_user_turn(
                text,
                person_id,
                answered_question=answered_question,
            )
        except Exception as exc:
            _log.debug("question budget user update failed: %s", exc)
        try:
            closure = end_thread.note_user_turn(
                text,
                person_id,
                answered_question=answered_question,
            )
            if closure:
                _log.info(
                    "[end_thread] closure cue detected — reason=%s text=%r",
                    closure.get("reason"),
                    text,
                )
        except Exception as exc:
            _log.debug("end-of-thread user update failed: %s", exc)

        # Face-reveal prompt: speaker-ID matched a known person with HIGH
        # confidence, they have NO face biometric yet (voice-only enrollment),
        # and at least one unknown face is visible. Rex asks confirmation
        # instead of auto-binding — yes/no for one unknown, left/right for two.
        if (
            person_id is not None
            and person_id != (recent_engagement or {}).get("person_id")
            and person_id not in _face_reveal_declined
            and _pending_face_reveal_confirm is None
            and speaker_score >= float(getattr(config, "FACE_REVEAL_MIN_SCORE", 0.80))
            and not people_memory.has_face_biometric(person_id)
        ):
            face_reveal_blocked = False
            try:
                if (
                    boundary_memory.is_blocked(person_id, "ask", "face")
                    or boundary_memory.is_blocked(person_id, "ask", "identity")
                ):
                    face_reveal_blocked = True
                    _face_reveal_declined.add(person_id)
                    _log.info(
                        "[boundaries] face-reveal skipped — face/identity ask blocked for person_id=%s",
                        person_id,
                    )
            except Exception as exc:
                _log.debug("face-reveal boundary check failed: %s", exc)
            if face_reveal_blocked:
                pass
            else:
                # Collect unknown faces currently visible with x-position and encoding.
                try:
                    from vision import camera as _cam_mod
                    from vision import face as _face_mod
                    frame = _cam_mod.get_frame()
                    unknown_candidates: list[dict] = []
                    if frame is not None:
                        detected = _face_mod.detect_faces(frame)
                        for det in detected:
                            if _face_mod.identify_face(det["encoding"]) is None:
                                x, _y, w, _h = det["bounding_box"]
                                unknown_candidates.append({
                                    "slot_id": f"face_{x}_{_y}",
                                    "encoding": det["encoding"],
                                    "x": x + w // 2,
                                })
                except Exception as exc:
                    _log.debug("face-reveal candidate capture error: %s", exc)
                    unknown_candidates = []

                if len(unknown_candidates) == 1:
                    mode = "binary"
                    name_for_prompt = _first_name_or(person_name, "you")
                    ask_prompt = (
                        f"You recognize this speaker's VOICE as '{name_for_prompt}' — but "
                        f"you've never seen their face before. Now there's one unfamiliar "
                        f"face in view and it's almost certainly them. In ONE short "
                        f"in-character Rex line, ask {name_for_prompt} to confirm that "
                        f"IS them — express surprise at what they look like compared to "
                        f"the voice you'd imagined. End with a clear yes/no question."
                    )
                elif len(unknown_candidates) == 2:
                    mode = "lateral"
                    name_for_prompt = _first_name_or(person_name, "you")
                    ask_prompt = (
                        f"You recognize this speaker's VOICE as '{name_for_prompt}' but "
                        f"two unfamiliar faces are in view and you can't tell which is "
                        f"{name_for_prompt}. In ONE short in-character Rex line, ask "
                        f"{name_for_prompt} whether they are the one on YOUR LEFT or on "
                        f"YOUR RIGHT — phrase it from your perspective. End with a clear "
                        f"'left or right?' question."
                    )
                else:
                    mode = None
                    _log.info(
                        "[interaction] face-reveal skipped — %d unknown candidates (need 1 or 2)",
                        len(unknown_candidates),
                    )

                if mode is not None:
                    _pending_face_reveal_confirm = {
                        "person_id": person_id,
                        "name": person_name,
                        "mode": mode,
                        "candidates": unknown_candidates,
                        "asked_at": time.monotonic(),
                    }
                    try:
                        q_text = llm.get_response(ask_prompt)
                        if q_text:
                            _speak_blocking(q_text)
                            conv_memory.add_to_transcript("Rex", q_text)
                            conv_log.log_rex(q_text)
                            _register_rex_utterance(q_text)
                            _log.info(
                                "[interaction] face-reveal asked (mode=%s, person_id=%s): %r",
                                mode, person_id, q_text,
                            )
                            # Skip normal LLM response — this turn IS the reveal question.
                            return
                        else:
                            _pending_face_reveal_confirm = None
                    except Exception as exc:
                        _log.debug("face-reveal ask error: %s", exc)
                        _pending_face_reveal_confirm = None

        # Background cross-talk gate (Tier 2): even when a person was ATTRIBUTED (e.g.
        # by the single-visible face from Tier 1), clear non-Rex chatter — a device/UI
        # readout ("that's definitely 30 FPS"), a line aimed at someone else — must NOT
        # be answered or profiled. High precision: _looks_like_background_crosstalk
        # already returns False for commands, Rex-directed speech, and self/intro names,
        # so plausibly-directed speech still gets a normal turn. Don't fire mid identity
        # prompt or while an offscreen-identify reply is pending.
        if (
            _looks_like_background_crosstalk(text)
            and not identity_prompt_active
            and _pending_offscreen_identify is None
            and not _is_engaged_partner_turn(person_id, speaker_score)
            # A turn the dialogue-act classifier already claimed as an ANSWER to
            # Rex's own question is by definition directed at Rex — never chatter.
            # Field bug 2026-07-06: "as good as a Womp Rat stuck in the engines"
            # (the answer to Rex's greeting; voice 0.850, face agreeing, dialogue
            # act answer_to_rex 0.90) was dropped by the 10-words-no-pronoun rule,
            # and the engaged-partner exemption didn't apply because it was the
            # session's FIRST exchange.
            and not (
                dialogue_decision is not None
                and getattr(dialogue_decision, "label", "") == "answer_to_rex"
            )
        ):
            _log.info(
                "[interaction] ignoring background cross-talk — text=%r "
                "(attributed person_id=%s, voice_score=%.3f)",
                text, person_id, speaker_score,
            )
            final_executed_path = "ignored.background_crosstalk"
            completed = False
            return

        # Off-camera unknown voice: if the person-resolution pass flagged this
        # utterance as coming from someone we can neither see nor voice-ID, fire
        # Rex's "who's that speaking?" question and store the audio so the
        # engaged person's next reply can enroll the unknown's voice.
        # Skip if a pending identify is already in flight or this is a local command.
        if (
            off_camera_unknown
            and _pending_offscreen_identify is None
            and command_parser.parse(text) is None
        ):
            if _looks_like_background_crosstalk(text):
                _log.info(
                    "[interaction] ignoring off-camera background chatter "
                    "text=%r raw_best=%s score=%.3f",
                    text,
                    raw_best_id,
                    speaker_score,
                )
                final_executed_path = "ignored.off_camera_background_chatter"
                completed = False
                return
            # Ambiguous-between-knowns escalation: the margin guard refused because
            # TWO enrolled voices are near-tied — someone real and known-adjacent is
            # talking. Upgrade to a challenge so the ask fires (it would otherwise be
            # deferred as chatter and each utterance would mint a fresh Guest slot).
            if (
                off_camera_unknown
                and not voice_challenge_fired
                and _voice_ambiguous_between_knowns(
                    speaker_score, speaker_margin, required_margin)
            ):
                voice_challenge_fired = True
                _log.info(
                    "[interaction] ambiguous between enrolled voices (top=%r %.3f, "
                    "margin=%.3f) — escalating to who's-that ask",
                    raw_best_name, speaker_score, speaker_margin,
                )
            if not _utterance_invites_identity_question(text) and not voice_challenge_fired:
                # The invite gate keeps Rex from interrogating background chatter — but
                # a CHALLENGED voice (marginal match on an unseen person, body in frame
                # or empty room) is not chatter: someone real is talking to him and the
                # match is untrustworthy. Ask regardless of the utterance's shape, so an
                # unenrolled housemate gets named-and-enrolled instead of impersonating
                # the nearest print (owner request 2026-07-05).
                _log.info(
                    "[interaction] deferring off-camera identity ask; turn should get "
                    "normal handling text=%r raw_best=%s score=%.3f",
                    text,
                    raw_best_id,
                    speaker_score,
                )
                off_camera_unknown = False
            if not off_camera_unknown:
                pass
            elif group_chatter_active:
                _log.info(
                    "[interaction] suppressing off-camera identity ask during "
                    "group chatter; treating utterance as background text=%r",
                    text,
                )
                return
            elif person_id is not None:
                try:
                    if boundary_memory.is_blocked(person_id, "ask", "identity"):
                        _log.info(
                            "[boundaries] off-camera identity ask skipped for person_id=%s",
                            person_id,
                        )
                        off_camera_unknown = False
                except Exception as exc:
                    _log.debug("off-camera identity boundary check failed: %s", exc)
            if not off_camera_unknown:
                pass
            else:
                engaged_name_local = (
                    recent_engagement.get("name") if recent_engagement else None
                ) or ""
                first_name_local = _first_name_or(engaged_name_local, "friend")
                # SELF-IDENTIFYING utterance ("This is JT", "I'm JT"): the overheard
                # line already ANSWERS the who's-that question — asking it back is
                # absurd (field log 2026-07-05-02-51: "Nice to meet you, JT — who's
                # speaking?"). Arm the pending state and consume THIS utterance as
                # the self-answer immediately: name resolved, voice enrolled from
                # this very clip, celebrity intro ack spoken. Falls through to the
                # normal ask only if the inline resolution doesn't consume it.
                self_id_name = _challenged_self_identified_name(text)
                if self_id_name:
                    _pending_offscreen_identify = {
                        "audio": None,   # this utterance IS the audio; don't double it
                        "asked_at": time.monotonic(),
                        "prior_engaged_id": (recent_engagement or {}).get("person_id"),
                        "prior_engaged_name": engaged_name_local,
                        "overheard_text": "",
                        "anonymous_speaker_label": anonymous_speaker_label,
                    }
                    try:
                        consumed, _ack = _handle_pending_offscreen_identify_reply(
                            text,
                            person_id=None,
                            person_name=None,
                            audio_array=audio_array,
                            anonymous_speaker_label=anonymous_speaker_label,
                        )
                    except Exception as exc:
                        _log.debug("inline self-identify resolution failed: %s", exc)
                        consumed = False
                    if consumed:
                        _log.info(
                            "[interaction] off-camera self-identification resolved "
                            "inline (no redundant who's-that ask): %r", text,
                        )
                        return
                    _pending_offscreen_identify = None   # fall through to the ask
                _pending_offscreen_identify = {
                    "audio": audio_array.copy(),
                    "asked_at": time.monotonic(),
                    "prior_engaged_id": (recent_engagement or {}).get("person_id"),
                    "prior_engaged_name": engaged_name_local,
                    "overheard_text": text,
                    "anonymous_speaker_label": anonymous_speaker_label,
                }
                try:
                    q_text = llm.get_response(
                        f"You just heard a voice you don't recognize. They said: '{text}'. "
                        f"Your friend '{first_name_local}' is here with you. In ONE short "
                        f"in-character Rex line: if what they said merits a quick reaction "
                        f"(a greeting, a joke, a holiday wish), give ONE brief beat "
                        f"responding to it FIRST, then ask who's speaking — curious, "
                        f"slightly wary, never hostile. Examples: "
                        f"'Happy Fourth to you too — but who said that? I don't recognize "
                        f"the voice.', "
                        f"'Hold up — who just chimed in back there?', "
                        f"'Nice line, mystery voice. Who are you, exactly?' "
                        f"One line ending in a question mark."
                    )
                    if q_text:
                        _pending_offscreen_identify["question_text"] = q_text
                        _speak_blocking(q_text)
                        conv_memory.add_to_transcript("Rex", q_text)
                        conv_log.log_rex(q_text)
                        _register_rex_utterance(q_text)
                        _log.info(
                            "[interaction] off-camera unknown — Rex asked: %r (overheard: %r)",
                            q_text, text,
                        )
                except Exception as exc:
                    _log.debug("off-camera identify ask error: %s", exc)
                # Skip normal LLM response — we don't want to treat the unknown
                # utterance as something Rex should respond to directly. The engaged
                # person's next reply gets consumed by the _pending_offscreen_identify
                # handler above.
                return
        # Newcomer-on-camera: an unknown face is visible AND the speaker's voice
        # didn't match anyone AND this utterance didn't already enroll them via
        # the self-introduction path above. Covers the "camera handoff" case
        # (e.g. Bret hands the device to a friend who says "Hi Rex"): without
        # this branch, the intent classifier hijacks the utterance into
        # query_who_is_speaking and Rex says "no idea, who's asking?" with no
        # follow-up. Here we proactively ask their name (and how they know the
        # recently-engaged person, if any) and open the identity-reply window
        # so the next utterance triggers enrollment + the post-greet
        # relationship chain.
        if (
            person_id is None
            and not identity_prompt_active
            and _has_unknown_visible_person()
            and _pending_face_reveal_confirm is None
            and command_parser.parse(text) is None
        ):
            if _looks_like_background_crosstalk(text):
                _log.info(
                    "[interaction] ignoring visible-unknown background chatter "
                    "text=%r raw_best=%s score=%.3f",
                    text,
                    raw_best_id,
                    speaker_score,
                )
                final_executed_path = "ignored.visible_unknown_background_chatter"
                completed = False
                return
            # TWO unknown faces on camera: the positional dual intro replaces the
            # generic single-unknown ask, and it fires on ANY non-chatter utterance
            # (two strangers addressing the robot is strong evidence this isn't
            # background TV — the greeting-shape invite gate doesn't apply).
            if (
                bool(getattr(config, "DUAL_INTRO_ENABLED", True))
                and _pending_dual_intro is None
                and not group_chatter_active
            ):
                dual_faces = _capture_unknown_face_candidates()
                if len(dual_faces) >= 2:
                    if _ask_dual_unknown_intro(text, dual_faces):
                        final_executed_path = "identity.dual_intro_ask"
                        return
            if not _utterance_invites_identity_question(text):
                _log.info(
                    "[interaction] deferring visible-unknown identity ask; turn should "
                    "get normal handling text=%r raw_best=%s score=%.3f",
                    text,
                    raw_best_id,
                    speaker_score,
                )
            else:
                q_text = _ask_visible_unknown_identity_question(
                    text,
                    recent_engagement=recent_engagement,
                    group_chatter_active=group_chatter_active,
                    source="newcomer_on_camera",
                )
                if group_chatter_active:
                    return
                if q_text:
                    return

        # Empathy classification — kicked off in parallel so the affect/mode
        # directive is ready by the time the LLM-fallback path assembles its
        # system prompt. Result is cached per-person for future turns even if
        # this turn is handled deterministically by the command parser.
        _empathy_thread = None
        active_grief_for_turn = person_id is not None and _grief_flow_active(person_id)
        local_sensitive_result = None
        if getattr(config, "EMPATHY_ENABLED", True) and not active_grief_for_turn:
            local_sensitive_result = _apply_local_sensitive_topic_prepass(person_id, text)
            _audio_for_prosody = audio_array
            def _run_empathy() -> None:
                try:
                    prosody_features = None
                    if getattr(config, "EMPATHY_PROSODY_ENABLED", True):
                        try:
                            prosody_features = prosody.analyze(
                                _audio_for_prosody,
                                sample_rate=config.AUDIO_SAMPLE_RATE,
                                transcript_text=text,
                            )
                        except Exception as exc:
                            _log.debug("prosody.analyze failed: %s", exc)
                            prosody_features = None
                    face_mood = None
                    if person_id is not None and getattr(config, "EMPATHY_FACE_MOOD_MISMATCH_ENABLED", True):
                        try:
                            face_mood = consciousness.get_cached_mood(
                                person_id,
                                max_age_secs=float(
                                    getattr(config, "EMPATHY_FACE_MOOD_CACHE_MAX_AGE_SECS", 180.0)
                                ),
                            )
                        except Exception as exc:
                            _log.debug("cached face mood lookup failed: %s", exc)
                            face_mood = None
                    # A pending "how long ago was that?" probe from a prior
                    # heavy disclosure: if this utterance carries a time
                    # marker ("13 years ago", "last week"), persist it to the
                    # stored event so check-in eligibility reflects reality.
                    try:
                        empathy.consume_recency_answer(person_id, text)
                    except Exception as exc:
                        _log.debug("recency answer consume failed: %s", exc)
                    result = empathy.classify_affect(
                        text,
                        prosody_features=prosody_features,
                        face_mood=face_mood,
                    )
                    if not result:
                        return
                    result = _merge_with_local_sensitive_prepass(
                        result,
                        local_sensitive_result,
                    )
                    try:
                        user_energy.note_user_turn(
                            text,
                            person_id,
                            prosody_features=prosody_features,
                            affect_result=result,
                        )
                    except Exception as exc:
                        _log.debug("user energy prosody/empathy update failed: %s", exc)
                    person_row = None
                    if person_id is not None:
                        try:
                            person_row = people_memory.get_person(person_id)
                        except Exception:
                            person_row = None
                    child_in_scene = False
                    try:
                        ws_people = world_state.get("people") or []
                        child_in_scene = any(
                            p.get("age_estimate") == "child" for p in ws_people
                        )
                    except Exception:
                        pass
                    mode_pack = empathy.select_mode(
                        result, person=person_row, child_in_scene=child_in_scene,
                        person_id=person_id,
                    )
                    # Heavy disclosure with no timeframe ("my mother passed
                    # away"): have the acknowledgment tactfully ask how long
                    # ago it was instead of assuming fresh grief.
                    mode_pack = empathy.augment_mode_for_recency_probe(result, mode_pack)
                    empathy.record(person_id, result, mode_pack)
                    _prosody = result.get("prosody") or {}
                    _log.info(
                        "[empathy] affect=%s needs=%s sens=%s invite=%s "
                        "conf=%.2f prosody=%s → mode=%s (%s)",
                        result.get("affect"), result.get("needs"),
                        result.get("topic_sensitivity"),
                        result.get("invitation"), result.get("confidence", 0.0),
                        _prosody.get("tag") or "—",
                        mode_pack.get("mode"), mode_pack.get("reason"),
                    )
                    ev = result.get("event")
                    if ev and person_id is not None:
                        if specific_forget_target_for_turn:
                            _log.info(
                                "[empathy] skipped emotional memory write for targeted "
                                "forget request person_id=%s target=%r",
                                person_id,
                                specific_forget_target_for_turn,
                            )
                            return
                        if suppress_memory_learning:
                            _log.info(
                                "[empathy] skipped emotional memory write because "
                                "this turn was handled as memory/control intent "
                                "person_id=%s: %s",
                                person_id,
                                ev.get("description"),
                            )
                            return
                        if not _extracted_memory_allowed(ev, person_id):
                            _log.info(
                                "[empathy] skipped emotional memory write matching "
                                "forgotten terms for person_id=%s: %s",
                                person_id,
                                ev.get("description"),
                            )
                            return
                        try:
                            ev_recency = str(ev.get("recency") or "unknown")
                            row_id = emotional_events.add_event(
                                person_id,
                                category=ev.get("category", "other"),
                                description=ev.get("description", ""),
                                valence=ev.get("valence", -0.5),
                                person_invited_topic=bool(result.get("invitation")),
                                loss_subject=ev.get("loss_subject"),
                                loss_subject_kind=ev.get("loss_subject_kind"),
                                loss_subject_name=ev.get("loss_subject_name"),
                                recency=ev_recency,
                            )
                            if row_id:
                                _log.info(
                                    "[empathy] stored emotional event id=%s "
                                    "category=%s recency=%s for person_id=%s: %s",
                                    row_id, ev.get("category"), ev_recency,
                                    person_id, ev.get("description"),
                                )
                                # No timeframe on a heavy disclosure: arm the
                                # how-long-ago probe so the person's answer on
                                # a following turn can settle check-in
                                # eligibility (historical → never; recent → ok).
                                if (
                                    ev_recency == "unknown"
                                    and emotional_events.is_heavy_event(ev)
                                ):
                                    empathy.note_recency_probe(person_id, row_id)
                        except Exception as exc:
                            _log.debug("emotional_events.add_event failed: %s", exc)
                except Exception as exc:
                    _log.warning("empathy classification thread error: %s", exc, exc_info=True)

            _empathy_thread = threading.Thread(
                target=_run_empathy, daemon=True, name="empathy-classify",
            )
            _empathy_thread.start()

        match = None
        response_text = None
        used_agenda_llm = False
        used_classified_intent = False
        routing_text = text

        if response_text is None:
            if event_cancellation_ack is None:
                cancel_person_id = person_id
                if cancel_person_id is None:
                    try:
                        cancel_person_id = consciousness.get_last_memory_hint_target()
                    except Exception:
                        cancel_person_id = None
                labels = _cancel_stale_event_memory(cancel_person_id, text)
                if not labels:
                    # A postponement isn't a cancellation — reschedule (keep open) any
                    # matching plan so it survives. No-op unless looks_like_postponement.
                    events_memory.postpone_matching_events(cancel_person_id, text)
                # Open commitments: a cancel/never-mind or a "did it" also resolves a
                # still-open promise (→ canceled / completed). Scoped to the 'promised' pool,
                # so it never cross-clears a planned event. No-op unless one matches.
                try:
                    events_memory.resolve_matching_commitments(cancel_person_id, text)
                except Exception as _commit_exc:
                    _log.debug("[commitments] resolve failed: %s", _commit_exc)
                if (
                    not labels
                    and _router_decision_executable(
                        router_decision,
                        text=text,
                        context=router_context,
                        dialogue_decision=dialogue_decision,
                    )
                    and router_decision.action == "event.cancel"
                ):
                    event_hint = (
                        router_decision.args.get("event_hint")
                        or router_decision.args.get("target")
                        or router_decision.args.get("plan")
                        or ""
                    )
                    if event_hint:
                        labels = _cancel_stale_event_memory(
                            cancel_person_id,
                            text,
                            event_hint={"event_name": str(event_hint)},
                        )
                    if not labels:
                        labels = [str(event_hint).strip() or "that plan"]
                        _log.info(
                            "[action_router] executed event.cancel without matching "
                            "stored row person_id=%s label=%r text=%r",
                            cancel_person_id,
                            labels[0],
                            text,
                        )
                if labels:
                    if cancel_person_id is not None:
                        try:
                            _session_router_control_topics[int(cancel_person_id)] = labels[0]
                        except (TypeError, ValueError):
                            pass
                    event_cancellation_ack = _event_cancellation_ack(labels, cancel_person_id)
            if event_cancellation_ack:
                suppress_memory_learning = True
                completed = _speak_blocking(event_cancellation_ack, emotion="neutral")
                _router_audit_note_result(
                    router_audit,
                    completed=completed,
                    spoken_text=event_cancellation_ack,
                )
                response_text = event_cancellation_ack
                used_agenda_llm = True
                final_executed_path = "router.event_cancel_ack"

        if repair_move is None:
            repair_move = repair_moves.detect(text)
        if _negation_is_answer(repair_move, dialogue_decision):
            _log.info(
                "[repair] bare negation is an ANSWER to Rex's question "
                "(dialogue_act=answer_to_rex) — replying normally, no repair"
            )
            repair_move = None
        # Re-route the CORRECTION text to the normal reply path (respond to it) instead of
        # firing the repair-ack echo when: (a) a grief flow is active (existing behavior), or
        # (b) the turn is a BARE restatement of real content ("I said I watch a lot of Netflix
        # specials") — the user repeating their turn after a mishear wants an answer, not
        # "We'll get there — recalibrating. <their words>." back (the field bug).
        _reroute_correction = bool(
            repair_move
            and repair_move.get("kind") in {"misheard", "misunderstood"}
            and repair_move.get("correction")
            and (
                active_grief_for_turn
                or (
                    bool(getattr(config, "REPAIR_RESTATEMENT_AS_REPLY_ENABLED", True))
                    and repair_moves.is_bare_restatement(text)
                )
                # A correction that restates a routable QUERY ("no I said what's the weather") must
                # re-run that query, not get a repair-ack — even though "no …" isn't a bare
                # restatement. is_bare_restatement stays the gate for restated *content*; this covers
                # restated *commands/queries*.
                or _correction_routes_to_query(repair_move["correction"])
            )
        )
        if _reroute_correction:
            routing_text = repair_move["correction"]
            repair_moves.mark_handled(repair_move.get("kind") or "")
            _log.info(
                "[repair] re-routing restated content to a normal reply: %r",
                routing_text,
            )
        elif repair_move:
            response_text = _generate_repair_response(person_id, text, repair_move)
            used_agenda_llm = True
            final_executed_path = f"repair.{repair_move.get('kind') or 'unknown'}"

        # Layer-1 insult pre-check: keyword match → bump anger BEFORE the LLM
        # call so this turn's system prompt reflects the new escalation level.
        # Layer 2 (llm.analyze_sentiment in _post_response) skips its own
        # increment when this flag is set so we never double-count.
        pre_classified_insult = False
        pre_classified_compliment = False
        # A turn the dialogue-act gate already bound as an ANSWER to Rex's question
        # (e.g. "That was good" answering "how did the festival go?") is about the TOPIC,
        # not praise/insult OF Rex — so the keyword-based layer-1 compliment/insult
        # pre-pass must stand down, or it hijacks the reply. Live-logged 2026-06-20:
        # "That was good" read as a compliment ("I appreciate a clean compliment,
        # Bret…"), derailing the festival answer and re-asking it.
        _turn_is_answer_to_rex = bool(
            dialogue_decision is not None
            and getattr(dialogue_decision, "label", None) == "answer_to_rex"
        )
        if (
            response_text is None
            and not _turn_is_answer_to_rex
            and personality.is_obvious_insult(text)
        ):
            new_level = personality.increment_anger(person_id)
            pre_classified_insult = True
            try:
                _play_event_body_beat("insult.detected")
                _set_body_mood("offended", source="layer1_insult")
            except Exception as exc:
                _log.debug("[interaction] insult body beat skipped: %s", exc)
            if person_id is not None:
                # P3: a jab from a warm friend reads as banter, not antagonism.
                people_memory.apply_jab(person_id, "insult_mild")
            _log.info(
                "[interaction] layer-1 insult detected — anger now %d", new_level,
            )
            _note_day_mood("insulted")
        elif (
            response_text is None
            and not _turn_is_answer_to_rex
            and personality.is_obvious_compliment(text)
        ):
            # Layer-1 compliment pre-check: immediate pleased body language on this turn.
            # Layer 2 (llm.analyze_sentiment) skips its own beat when this flag is set so
            # we never double-react; subtle praise still gets caught there.
            pre_classified_compliment = True
            try:
                _play_event_body_beat("compliment.detected")
                _set_body_mood("proud", source="layer1_compliment")
                _flash_chest_compliment()
            except Exception as exc:
                _log.debug("[interaction] compliment body beat skipped: %s", exc)
            _log.info("[interaction] layer-1 compliment detected")
            _note_day_mood("complimented")

        # Active grief flow must consume short replies before command/intent
        # routing. A name like "Tom Foster" can otherwise be misclassified as
        # "who is speaking?" and fall back to roast-first Rex.
        if response_text is None and active_grief_for_turn:
            grief_response = _continue_grief_flow(person_id, routing_text)
            if grief_response:
                _log.info(
                    "[interaction] grief flow → person_id=%s step=%s text=%r",
                    person_id,
                    (_grief_flow_state.get(person_id) or {}).get("step"),
                    grief_response,
                )
                grief_emotion = "sad"
                grief_pre_ms = 600
                grief_post_ms = 600
                grief_voice = None
                try:
                    ov = empathy.get_delivery_overrides(person_id)
                    if ov:
                        if ov.get("emotion"):
                            grief_emotion = ov["emotion"]
                        grief_pre_ms = max(grief_pre_ms, int(ov.get("pre_beat_ms") or 0))
                        grief_post_ms = max(grief_post_ms, int(ov.get("post_beat_ms") or 0))
                        grief_voice = ov.get("voice_settings")
                except Exception as exc:
                    _log.debug("grief flow delivery override error: %s", exc)
                completed = _speak_blocking(
                    grief_response,
                    emotion=grief_emotion,
                    pre_beat_ms=grief_pre_ms,
                    post_beat_ms_override=grief_post_ms,
                    voice_settings=grief_voice,
                )
                _router_audit_note_result(
                    router_audit,
                    completed=completed,
                    spoken_text=grief_response,
                )
                response_text = grief_response
                final_executed_path = "grief_flow.active_turn"

        # Command parser → local dispatch or LLM fallback. Skip local routing
        # for active grief flow turns, including the open-ended description
        # reply where _continue_grief_flow returns None and hands off to LLM.
        if response_text is None and not active_grief_for_turn:
            match = command_parser.parse(text)
            try:
                from features import games as games_mod
                if games_mod.is_active():
                    # Same decision as the early claim above, from the same helper —
                    # these two blocks are the pair that drifted.
                    game_escape = _game_escape_command(text)
                    match = game_escape
                    if game_escape is None:
                        response_text = games_mod.handle_input(text, person_id, audio_array)
                        completed = _speak_blocking(response_text)
                        _router_audit_note_result(
                            router_audit,
                            completed=completed,
                            spoken_text=response_text,
                        )
                        if completed:
                            games_mod.on_response_spoken()
                            after_audio = games_mod.consume_pending_audio_after_response()
                            if after_audio and not _interrupted.is_set():
                                game_after_audio_path = after_audio
                        used_agenda_llm = True
                        handled_active_game_turn = True
                        suppress_memory_learning = True
                        final_executed_path = "game.active_turn"
                        match = None
            except Exception as exc:
                _log.debug("active game routing failed: %s", exc)
                _router_audit_note_result(
                    router_audit,
                    handler_error=f"active_game_routing_failed:{type(exc).__name__}",
                )
            legacy_block_reason = _legacy_command_execution_block_reason(
                match,
                text=text,
                context=router_context,
                dialogue_decision=dialogue_decision,
            )
            if legacy_block_reason:
                _log.info(
                    "[turn_policy] blocked legacy command=%s reason=%s text=%r",
                    match.command_key,
                    legacy_block_reason,
                    text,
                )
                _router_audit_clear_legacy_command(router_audit)
                match = None
            else:
                _router_audit_note_legacy_command(router_audit, match)
        if match is not None:
            _router_audit_note_legacy_command(router_audit, match)
            response_text = _execute_command(match, person_id, person_name, text)
            final_executed_path = f"legacy_command.{match.command_key}"
            if match.command_key in {
                "forget_specific",
                "forget_me",
                "forget_everyone",
                "memory_review",
                "memory_forget_fact",
                "memory_correct_fact",
                "memory_remember_fact",
                "memory_boundary",
            }:
                suppress_memory_learning = True
        elif response_text is None:
            if getattr(config, "INTENT_CLASSIFIER_ENABLED", False) and not active_grief_for_turn:
                try:
                    intent_started = time.monotonic()
                    # routing_text == text normally; for a re-routed correction it's the corrected
                    # words, so 'no I said what's the weather' classifies as its query, not the wrapper.
                    intent = intent_classifier.classify_deterministic(routing_text)
                    _latency_log(turn_start, "intent_classifier", intent_started)
                except Exception as exc:
                    _log.debug("intent classification error: %s", exc)
                    intent = "general"
                intent_block_reason = _intent_execution_block_reason(
                    intent,
                    text=routing_text,
                    context=router_context,
                    dialogue_decision=dialogue_decision,
                    router_action=(
                        router_decision.action if router_decision is not None else None
                    ),
                )
                if intent_block_reason:
                    # "tool_router_owns_action" is a HANDOFF, not a block — the
                    # turn is about to be answered by the reply call's tool. Say
                    # so, or every weather/vision/memory turn reads as a rejection
                    # in the field logs.
                    _log.info(
                        "[turn_policy] %s intent=%s reason=%s text=%r",
                        "handed to tool router"
                        if intent_block_reason == "tool_router_owns_action"
                        else "blocked",
                        intent,
                        intent_block_reason,
                        text,
                    )
                    intent = "general"
                _log.info("[interaction] intent classifier: %s", intent)
                if intent != "general":
                    used_classified_intent = True
                    # Pass raw voice-match data and currently-visible identified
                    # face so handlers like query_who_is_speaking can answer with
                    # real biometric ground truth instead of LLM hallucination.
                    _visible_name = None
                    try:
                        for p in world_state.get("people") or []:
                            if p.get("person_db_id") is not None and p.get("face_id"):
                                _visible_name = p["face_id"]
                                break
                    except Exception:
                        pass
                    response_text = _handle_classified_intent(
                        intent, routing_text, person_id,
                        raw_best_id=raw_best_id,
                        raw_best_name=raw_best_name,
                        raw_best_score=speaker_score,
                        visible_known_name=_visible_name,
                    )
                    if response_text is not None:
                        final_executed_path = f"intent_classifier.{intent}"
            if response_text is None:
                if _empathy_thread is not None:
                    # Deliberately tight TTFS budget: the affect classifier
                    # (prosody + LLM) routinely does NOT finish in time, by design.
                    # When it doesn't, this turn uses the synchronous local-
                    # sensitivity read (regex crisis/grief/illness) or the prior
                    # turn's cached mode, and the fresh read lands for the NEXT
                    # turn. Default mirrors config so the real budget is visible.
                    _empathy_join_timeout = float(getattr(
                        config, "EMPATHY_CLASSIFY_JOIN_TIMEOUT_SECS", 0.20,
                    ))
                    empathy_wait_started = time.monotonic()
                    _empathy_thread.join(timeout=_empathy_join_timeout)
                    _latency_log(turn_start, "empathy_join", empathy_wait_started)
                    if _empathy_thread.is_alive():
                        # Expected on most turns — not a warning. Only flag the
                        # genuinely-blind case: no synchronous safety read AND no
                        # cached mode to fall back on (cold cache, turn 1).
                        have_same_turn_mode = local_sensitive_result is not None
                        have_fallback_mode = empathy.peek(person_id) is not None
                        if not have_same_turn_mode and not have_fallback_mode:
                            _log.info(
                                "[empathy] no same-turn affect (classifier still "
                                "running, cold cache) — proceeding neutral"
                            )
                        else:
                            _log.debug(
                                "[empathy] classifier still running; using %s",
                                "synchronous local read" if have_same_turn_mode
                                else "prior cached mode",
                            )
                # Grief flow — intercept the LLM path with a structured
                # condolence/consent/name walk when the empathy classifier
                # has detected (or is mid-conversation about) a loss.
                grief_response = None
                if person_id is not None:
                    if _grief_flow_active(person_id):
                        grief_response = _continue_grief_flow(person_id, text)
                    else:
                        cached = empathy.peek(person_id)
                        ev = (
                            (cached.get("result") or {}).get("event")
                            if cached else None
                        )
                        grief_response = _maybe_start_grief_flow(person_id, ev)
                if grief_response:
                    _log.info(
                        "[interaction] grief flow → person_id=%s step=%s text=%r",
                        person_id,
                        (_grief_flow_state.get(person_id) or {}).get("step"),
                        grief_response,
                    )
                    # Speak the structured response with the empathy delivery
                    # envelope (sympathetic LEDs/voice, longer pre/post beats).
                    grief_emotion = "sad"
                    grief_pre_ms = 600
                    grief_post_ms = 600
                    grief_voice = None
                    try:
                        ov = empathy.get_delivery_overrides(person_id)
                        if ov:
                            if ov.get("emotion"):
                                grief_emotion = ov["emotion"]
                            grief_pre_ms = max(grief_pre_ms, int(ov.get("pre_beat_ms") or 0))
                            grief_post_ms = max(grief_post_ms, int(ov.get("post_beat_ms") or 0))
                            grief_voice = ov.get("voice_settings")
                    except Exception as exc:
                        _log.debug("grief flow delivery override error: %s", exc)
                    completed = _speak_blocking(
                        grief_response,
                        emotion=grief_emotion,
                        pre_beat_ms=grief_pre_ms,
                        post_beat_ms_override=grief_post_ms,
                        voice_settings=grief_voice,
                    )
                    _router_audit_note_result(
                        router_audit,
                        completed=completed,
                        spoken_text=grief_response,
                    )
                    response_text = grief_response
                    final_executed_path = "grief_flow.llm_intercept"
                # If the grief flow handled this turn, do NOT also fire the
                # LLM streaming path — that would speak a second response on
                # top of the grief line. Fall through to LLM only when grief
                # didn't intercept.
                if response_text is None:
                    # If there are unacknowledged emotional events for this
                    # person the system prompt is about to fire the
                    # ACKNOWLEDGE-ON-RETURN directive — mark them acknowledged
                    # now so it doesn't repeat across this person's subsequent
                    # turns this session.
                    if person_id is not None:
                        try:
                            try:
                                ws_now = world_state.snapshot()
                                crowd_count = int((ws_now.get("crowd") or {}).get("count", 1) or 1)
                            except Exception:
                                crowd_count = 1
                            suppress_in_crowd = bool(getattr(config, "EMPATHY_DISCRETION_IN_CROWD", True))
                            unack = [
                                ev for ev in emotional_events.get_active_events(person_id, limit=3)
                                if not ev.get("last_acknowledged_at")
                                and emotional_events.can_surface_event(ev)
                                and not (
                                    suppress_in_crowd
                                    and crowd_count > 1
                                    and emotional_events.is_heavy_event(ev)
                                )
                            ]
                            if unack:
                                for ev in unack:
                                    emotional_events.mark_acknowledged(int(ev["id"]))
                                _log.info(
                                    "[empathy] marked %d emotional event(s) acknowledged "
                                    "for person_id=%s on this turn",
                                    len(unack), person_id,
                                )
                        except Exception as exc:
                            _log.debug("emotional event ack error: %s", exc)
                    _try_slow_path_ack(
                        "general",
                        text=text,
                        dialogue_decision=dialogue_decision,
                    )
                    response_text = _stream_llm_response(
                        text,
                        person_id,
                        answered_question=answered_question,
                        turn_start=turn_start,
                    )
                    used_agenda_llm = True
                    final_executed_path = _consume_tool_routed_path() or "llm.stream"

        if response_text:
            _log_router_audit(
                router_audit,
                final_executed_path or "response_text.unknown",
                spoken_text=response_text,
            )
            if _consume_prelogged_response() != response_text:
                conv_memory.add_to_transcript("Rex", response_text)
                conv_log.log_rex(response_text)
            _session_exchange_count += 1
            _register_rex_utterance(response_text)
            assistant_asked_question = _assistant_asked_question(response_text)
            question_recovery_text = response_text if assistant_asked_question else ""
            try:
                end_thread.mark_closure_spoken()
            except Exception:
                pass
        else:
            question_recovery_text = ""
        # The reply this turn produced (if any) has been spoken: an unprompted
        # impression claimed against it may now look for its moment.
        try:
            from features import organic_impersonation as _organic
            _organic.note_reply_done()
        except Exception:
            pass

        # Post-greeting relationship hook: we just enrolled a newcomer while a
        # different known person was recently engaged. Ask them how they know
        # each other, and open a relationship-prompt window so the next reply
        # gets parsed and saved as an edge.
        post_greet_fired = False
        pending_rel = _pending_post_greet_relationship[0]
        if pending_rel and not _interrupted.is_set() and person_id == pending_rel.get("newcomer_person_id"):
            _pending_post_greet_relationship[0] = None
            prior_name = pending_rel.get("prior_engaged_name") or "the other person"
            newcomer_name = pending_rel.get("newcomer_name") or "you"
            prior_first = _first_name_or(prior_name, "them")
            newcomer_first = _first_name_or(newcomer_name, "there")
            try:
                q_text = llm.get_response(
                    f"You just learned a new person named '{newcomer_first}' is here. "
                    f"Your friend '{prior_first}' is also present (you were just talking "
                    f"with them). In ONE short in-character Rex line, ask {newcomer_first} "
                    f"how they know {prior_first}. Warm, curious, one line ending in a "
                    f"question mark. Use names naturally."
                )
                if q_text:
                    _speak_blocking(q_text)
                    conv_memory.add_to_transcript("Rex", q_text)
                    conv_log.log_rex(q_text)
                    _register_rex_utterance(q_text)
                    assistant_asked_question = True
                    question_recovery_text = q_text
                    post_greet_fired = True
                    try:
                        consciousness.set_relationship_prompt_context({
                            "engaged_person_id": pending_rel["prior_engaged_id"],
                            "engaged_name": pending_rel.get("prior_engaged_name"),
                            "newcomer_person_id": pending_rel["newcomer_person_id"],
                            "slot_id": f"post_greet_{pending_rel['newcomer_person_id']}",
                            "asked_at": time.monotonic(),
                        })
                    except Exception as exc:
                        _log.debug("set_relationship_prompt_context failed: %s", exc)
                    _log.info(
                        "[interaction] post-greet relationship ask fired for "
                        "newcomer=%s prior=%s",
                        newcomer_name, prior_name,
                    )
            except Exception as exc:
                _log.debug("post-greet relationship ask error: %s", exc)

        # Curiosity routine — skip if we just asked a relationship question.
        if (
            match is None
            and response_text
            and not _interrupted.is_set()
            and not post_greet_fired
            and not used_agenda_llm
            and not used_classified_intent
        ):
            curiosity_q = _curiosity_check(response_text, text, person_id, person_name)
            if curiosity_q:
                conv_memory.add_to_transcript("Rex", curiosity_q)
                conv_log.log_rex(curiosity_q)
                _register_rex_utterance(curiosity_q)
                assistant_asked_question = True
                question_recovery_text = curiosity_q
        elif (
            used_agenda_llm
            and response_text
            and person_id is not None
            and "?" in response_text
        ):
            _record_pool_topics_in_response(response_text, person_id)

        # Release playback suppression before slower post-response memory work.
        # Otherwise an immediate human reply can land in the rolling buffer and
        # then get flushed when the API-backed fact/sentiment pass finishes.
        if sequence_started:
            echo_cancel.end_sequence(
                flush=False,
                tail_secs=_reply_playback_tail_secs(assistant_asked_question),
            )
            sequence_started = False
            if game_after_audio_path and not _interrupted.is_set():
                speech_queue.enqueue_audio_file(
                    game_after_audio_path,
                    priority=1,
                    tag="game:after_audio",
                )
                game_after_audio_path = None

        if assistant_asked_question and question_recovery_text and not handled_active_game_turn:
            _arm_no_response_recovery(question_recovery_text, person_id)

        if handled_active_game_turn:
            try:
                interoception.record_interaction()
            except Exception as exc:
                _log.debug("active game interoception error: %s", exc)
        else:
            _post_response(
                text,
                person_id,
                person_name,
                assistant_asked_question=assistant_asked_question,
                pre_classified_insult=pre_classified_insult,
                pre_classified_compliment=pre_classified_compliment,
                suppress_memory_learning=suppress_memory_learning,
            )
    except Exception as exc:
        handler_error = f"unhandled:{type(exc).__name__}"
        final_executed_path = final_executed_path or "exception.unhandled"
        raise
    finally:
        if sequence_started:
            _end_response_sequence_for_text(response_text)
        try:
            _log_character_loop_trace(
                character_trace,
                router_audit=router_audit,
                final_executed_path=final_executed_path,
                completed=completed,
                handler_error=handler_error,
                spoken_text=response_text,
                assistant_asked_question=assistant_asked_question,
                suppress_memory_learning=suppress_memory_learning,
                repair_move=repair_move,
                intent=intent,
            )
        finally:
            if trace_context_token is not None:
                _current_character_loop_trace.reset(trace_context_token)


def submit_text(
    text: str,
    *,
    person_id: Optional[int] = None,
    person_name: Optional[str] = None,
) -> bool:
    """Process GUI/CLI text input through the normal interaction pipeline."""
    cleaned = (text or "").strip()
    if not cleaned:
        return False

    # Honor the global pause (Memory Banks editor open). The voice loop halts the whole
    # conversation engine while paused — no responses, no memory writes — but the typed-
    # input path bypassed it, so a message typed during a pause still replied AND persisted
    # memory (junecodereview #8). Drop it silently here too; the user re-submits on resume.
    if getattr(config, "INTERACTION_PAUSED", False):
        return False

    with _text_input_lock:
        current_state = state_module.get_state()
        if current_state in (State.SLEEP, State.SHUTDOWN):
            return False
        from_idle_activation = current_state != State.ACTIVE
        if current_state == State.IDLE:
            state_module.set_state(State.ACTIVE)

        global _last_speech_at
        _last_speech_at = time.monotonic()
        _begin_user_turn()
        try:
            _handle_speech_segment(
                np.zeros(1, dtype=np.float32),
                from_idle_activation=from_idle_activation,
                transcribed_text=cleaned,
                raw_best_id_override=person_id,
                raw_best_name_override=person_name,
                speaker_score_override=1.0 if person_id is not None else 0.0,
                text_input=True,
            )
            _last_speech_at = time.monotonic()
            return True
        finally:
            _end_user_turn()


# ─────────────────────────────────────────────────────────────────────────────
# Main loop
# ─────────────────────────────────────────────────────────────────────────────

def _loop() -> None:
    global _last_speech_at, _listen_resume_at, _post_tts_flush_needed, _barge_yield_onset_at

    idle_timeout = config.CONVERSATION_IDLE_TIMEOUT_SECS
    _last_speech_at = time.monotonic()

    while not _stop_event.is_set():
        current_state = state_module.get_state()

        # ── SHUTDOWN ────────────────────────────────────────────────────────────
        if current_state == State.SHUTDOWN:
            break

        # ── PAUSED — Memory Banks editor is open. Halt the whole conversation
        # engine: no audio capture, no transcription, no responses, no idle/proactive
        # re-engagement. Keep the idle clock fresh so resuming doesn't immediately fire
        # an "are you there?" line. (consciousness._can_speak() blocks proactive too.)
        if getattr(config, "INTERACTION_PAUSED", False):
            _last_speech_at = time.monotonic()
            _stop_event.wait(0.2)
            continue

        # ── QUIET — stay silent until an explicit wake word exits quiet mode ───
        if current_state == State.QUIET:
            if _wake_word_fired.is_set():
                _wake_word_fired.clear()
                _last_speech_at = time.monotonic()
                _wake_from_quiet()
            _stop_event.wait(0.1)
            continue

        # ── SLEEP — any active wake model can bring Rex back online ───────────
        if current_state == State.SLEEP:
            try:
                _situation_assessor.set_vad_active(False)
            except Exception:
                pass
            if _wake_word_fired.is_set():
                _wake_word_fired.clear()
                with _wake_lock:
                    model = _last_wake_word
                if model:
                    _log.info("[wake_word] waking from sleep via model=%s", model)
                    _last_speech_at = time.monotonic()
                    _wake_from_sleep()
                    continue
            if bool(getattr(config, "SLEEP_ONNX_ONLY_WAKE", True)) or not bool(
                getattr(config, "SLEEP_TRANSCRIBED_WAKE_FALLBACK_ENABLED", False)
            ):
                _stop_event.wait(0.05)
                continue
            if time.monotonic() < _listen_resume_at:
                _stop_event.wait(_CHUNK_SECS)
                continue
            chunk = stream.get_audio_chunk(_CHUNK_SECS)
            if len(chunk) == 0:
                _stop_event.wait(_CHUNK_SECS)
                continue
            _sleep_speech = vad.is_speech(_chunk_for_vad(chunk))
            _situation_assessor.set_vad_active(_sleep_speech)
            if not _sleep_speech:
                _stop_event.wait(_CHUNK_SECS)
                continue
            _log.info("[sleep_mode] speech detected while asleep — checking wake phrase")
            speech_start = time.monotonic()
            audio_segment = _accumulate_speech(
                speech_start,
                allowed_states=(State.SLEEP,),
            )
            _wake_from_sleep_if_transcribed(audio_segment)
            _stop_event.wait(0.05)
            continue

        # ── IDLE — wake word first; optional direct speech activation ──────────
        if current_state == State.IDLE:
            if _wake_word_fired.is_set():
                _wake_word_fired.clear()
                # A wake word during music is a deliberate barge-in: stop the
                # track so Rex can hear and answer, then go ACTIVE and ack.
                if _dj_suppresses_conversation():
                    _stop_dj_for_wake()
                state_module.set_state(State.ACTIVE)
                _last_speech_at = time.monotonic()
                _wake_ack()
                continue

            # Never let Rex's own playback in IDLE self-trigger the interaction
            # loop into ACTIVE.
            listen_during_dj = (
                bool(getattr(config, "IDLE_LISTEN_DURING_DJ_PLAYBACK", True))
                and _dj_is_playing()
            )
            if _dj_suppresses_conversation() and not listen_during_dj:
                try:
                    _situation_assessor.set_vad_active(False)
                except Exception:
                    pass
                _last_speech_at = time.monotonic()
                # Same narrow music-command ear as the ACTIVE loop: "stop the
                # music" must work from IDLE too, radio chatter stays dropped.
                if _dj_command_listen_available():
                    _dj_command_listen_step(allowed_states=(State.IDLE,))
                else:
                    _stop_event.wait(0.1)
                continue
            if (
                speech_queue.is_speaking()
                or output_gate.is_busy()
                or (echo_cancel.is_suppressed() and not listen_during_dj)
            ):
                _stop_event.wait(0.05)
                continue

            # Presence-driven engagement (owner 2026-07-18: "R3X knows I'm in
            # front of him — if I don't respond to what he says ... it would be
            # good if he still tried to engage"). The lean impulse machinery
            # used to run only in the ACTIVE loop, so a visible-but-silent
            # person got the greeting and then nothing but sparse consciousness
            # steps. Run the same impulse from IDLE: _primary_session_person_id
            # falls back to the single visible known face, and all the existing
            # discipline (greeting-first, quiet threshold, cooldowns, rolling
            # rate cap, MAX_UNANSWERED, low-energy read) still applies, so he
            # engages without badgering. IDLE has no conversation timeout —
            # pass an infinite horizon so the outro-headroom gate is a no-op.
            if bool(getattr(config, "LEAN_BRAIN_ENABLED", False)) and bool(
                getattr(config, "IDLE_PRESENCE_IMPULSE_ENABLED", True)
            ):
                try:
                    _identity_inflight = consciousness.is_identity_prompt_in_flight()
                except Exception:
                    _identity_inflight = False
                if not _identity_inflight and _maybe_lean_impulse(
                    idle_for=0.0,
                    effective_idle_timeout=float("inf"),
                ):
                    _stop_event.wait(0.05)
                    continue

            # Optional hands-free behavior: allow normal speech to activate Rex
            # directly from IDLE without a wake word.
            if not getattr(config, "IDLE_LISTEN_WITHOUT_WAKE_WORD", False):
                _stop_event.wait(0.05)
                continue
            try:
                if consciousness.is_identity_prompt_in_flight():
                    _stop_event.wait(0.05)
                    continue
            except Exception:
                pass

            if time.monotonic() < _listen_resume_at:
                _stop_event.wait(_CHUNK_SECS)
                continue

            chunk = stream.get_audio_chunk(_CHUNK_SECS)
            if len(chunk) == 0:
                _stop_event.wait(_CHUNK_SECS)
                continue
            _idle_speech = vad.is_speech(_chunk_for_vad(chunk))
            _situation_assessor.set_vad_active(_idle_speech)
            if not _idle_speech:
                _stop_event.wait(_CHUNK_SECS)
                continue

            # First detected speech after the post-TTS window may be the human's
            # immediate answer to Rex's question. If cleanup already happened,
            # just clear the marker; do not discard this VAD-positive chunk.
            global _post_tts_flush_needed
            if _post_tts_flush_needed:
                _post_tts_flush_needed = False

            _log.info("[interaction] speech detected in IDLE — activating without wake word")
            state_module.set_state(State.ACTIVE)
            speech_start = time.monotonic()
            _last_speech_at = speech_start
            _begin_user_turn()
            _dj_restore_volume = _duck_dj_for_speech()
            try:
                audio_segment = _accumulate_speech(speech_start)
                eager_text = _pop_eager_transcript()
                if audio_segment is None or len(audio_segment) == 0:
                    continue

                _last_speech_at = time.monotonic()
                try:
                    _handle_speech_segment(
                        audio_segment, from_idle_activation=True,
                        eager_transcript=eager_text,
                    )
                except Exception:
                    # Same containment as the ACTIVE path: a handler bug costs
                    # one turn, never the listening loop (field 2026-08-03).
                    _log.exception(
                        "[interaction] speech-segment handler crashed — "
                        "dropping this turn, listening loop continues"
                    )
            finally:
                _restore_dj_volume(_dj_restore_volume)
                _end_user_turn()
            continue

        # ── ACTIVE — full continuous listening ─────────────────────────────────

        if _wake_word_fired.is_set():
            _wake_word_fired.clear()
            _last_speech_at = time.monotonic()
            # A wake word during music is a deliberate barge-in: stop the track
            # so Rex can hear the follow-up command instead of swallowing the
            # wake word (which left the user no way to shut the music off).
            if _dj_suppresses_conversation():
                _stop_dj_for_wake()
            if _should_play_active_wake_ack():
                _wake_ack()
            else:
                _log.info(
                    "[wake_word] active wake ack suppressed — busy or waiting for response"
                )
            continue

        if _dj_suppresses_conversation():
            try:
                _situation_assessor.set_vad_active(False)
            except Exception:
                pass
            _last_speech_at = time.monotonic()
            # Keep a narrow ear open for music-control/shutdown commands
            # ("stop the music") — everything else stays suppressed. Falls
            # back to deaf + wake-word barge-in without hardware AEC.
            if _dj_command_listen_available():
                _dj_command_listen_step(allowed_states=(State.ACTIVE,))
            else:
                _stop_event.wait(0.1)
            continue

        # Idle timeout → end session and return to IDLE
        effective_idle_timeout = idle_timeout
        try:
            from features import games as games_mod
            if games_mod.is_active():
                effective_idle_timeout = max(
                    effective_idle_timeout,
                    float(getattr(config, "ACTIVE_GAME_IDLE_TIMEOUT_SECS", effective_idle_timeout)),
                )
        except Exception:
            pass
        # Stay engaged longer while the user is PRESENT (on camera) but quiet, so a few spaced,
        # varied re-engagement attempts actually land before the give-up outro (the base 45s
        # timeout structurally allowed only ~1). Presence-gated: when nobody known is visible,
        # _primary_session_person_id() is None, the timeout snaps back to the base value, and a
        # departed/empty room times out promptly — never nudged.
        try:
            if (
                bool(getattr(config, "PRESENT_REENGAGE_ENABLED", True))
                and _primary_session_person_id() is not None
            ):
                effective_idle_timeout = max(
                    effective_idle_timeout,
                    float(getattr(config, "PRESENT_REENGAGE_IDLE_TIMEOUT_SECS", 90.0)),
                )
        except Exception:
            pass
        idle_for = time.monotonic() - _last_speech_at
        # An open "tell me about someone" briefing owns the floor: time it out
        # politely after 30s of silence, and never run idle filler over it
        # (live-logged: idle banter hijacked a briefing mid-collection).
        if _maybe_tell_about_timeout():
            continue
        # A first-meeting onboarding burst owns the floor like a briefing: fire
        # its opener / time it out, and never run idle filler over it.
        if _maybe_onboarding_timeout():
            continue
        if _maybe_onboarding_question():
            continue
        if (
            not tell_about_flow_active()
            and not onboarding_flow_active()
            and not exploration_flow_active()
        ):
            if bool(getattr(config, "LEAN_BRAIN_ENABLED", False)):
                # Lean agency owns the quiet: ONE motivated impulse (or silence) replaces the
                # old silence-fill trio (interest / low-memory / idle-banter interview questions).
                if _maybe_lean_impulse(
                    idle_for=idle_for,
                    effective_idle_timeout=effective_idle_timeout,
                ):
                    continue
            else:
                if _maybe_interest_idle_followup(
                    idle_for=idle_for,
                    effective_idle_timeout=effective_idle_timeout,
                ):
                    continue
                if _maybe_low_memory_idle_question(
                    idle_for=idle_for,
                    effective_idle_timeout=effective_idle_timeout,
                ):
                    continue
                if _maybe_idle_banter(
                    idle_for=idle_for,
                    effective_idle_timeout=effective_idle_timeout,
                ):
                    continue

        if time.monotonic() < _listen_resume_at:
            # Mic not read at all this tick. Counted so a reply spoken into this
            # window is explainable afterwards instead of vanishing (field
            # 2026-08-05: three marked repeats, and the capture telemetry proved
            # the loss was upstream of capture — i.e. right here).
            _capture_outcome("mic_skip_listen_resume")
            _situation_assessor.set_vad_active(False)
            _stop_event.wait(_CHUNK_SECS)
            continue

        direct_audio_path = None
        try:
            direct_audio_path = speech_queue.current_audio_path()
        except Exception:
            direct_audio_path = None
        if speech_queue.is_speaking() or output_gate.is_busy():
            interruptible_audio = (
                direct_audio_path is not None
                and _is_interruptible_game_audio_path(direct_audio_path)
            )
            if (not interruptible_audio and not _vad_barge_in_enabled()
                    and not _effect_allows_listening()):
                # Rex (or a sound effect / servo chirp) is producing audio, so the
                # mic is not read. A servo sfx landing in the human's reply window
                # mutes exactly the words they are speaking.
                _capture_outcome(
                    "mic_skip_output_busy_sfx"
                    if not speech_queue.is_speaking() else "mic_skip_rex_speaking"
                )
                _situation_assessor.set_vad_active(False)
                _stop_event.wait(_CHUNK_SECS)
                continue

        if idle_for >= effective_idle_timeout:
            _log.info("[interaction] conversation idle timeout — returning to IDLE")
            _maybe_idle_outro()
            _end_session()
            state_module.set_state(State.IDLE)
            continue

        # A question handoff arms a one-shot retro scan: an answer spoken in the
        # dead window before this first live read is in the buffer but would
        # never trigger live VAD — look back for it before polling live chunks.
        retro_speech_start = _maybe_recover_post_question_answer()

        if retro_speech_start is None:
            # Read a small audio chunk and run VAD
            chunk = stream.get_audio_chunk(_CHUNK_SECS)
            if len(chunk) == 0:
                _stop_event.wait(_CHUNK_SECS)
                continue

            _active_speech = vad.is_speech(_chunk_for_vad(chunk))
            _situation_assessor.set_vad_active(_active_speech)
            if not _active_speech:
                # A pending barge-yield onset is only valid for the speech that immediately follows the
                # yield; if silence intervenes it's stale — drop it so a later turn can't reach back
                # through a Rex line that played in between.
                _barge_yield_onset_at = 0.0
                if _maybe_prompt_incomplete_turn():
                    _last_speech_at = time.monotonic()
                _stop_event.wait(_CHUNK_SECS)
                continue
        else:
            _situation_assessor.set_vad_active(True)

        # First detected speech after the post-TTS window may be the human's
        # immediate answer. If cleanup already happened, just clear the marker;
        # keep this chunk and start accumulating.
        if _post_tts_flush_needed:
            _post_tts_flush_needed = False

        # ── Speech detected ────────────────────────────────────────────────────
        speech_start = retro_speech_start or time.monotonic()
        # If a proactive line just yielded because the user began talking during its generation gap,
        # reach the capture back to that onset so their opening words (spoken while this loop was
        # blocked generating the line) aren't clipped. Safe: Rex wasn't playing during that window.
        if _barge_yield_onset_at > 0.0:
            speech_start = _barge_recovered_speech_start(speech_start, _barge_yield_onset_at)
            _barge_yield_onset_at = 0.0
        _last_speech_at = speech_start
        _begin_user_turn()
        try:
            from features import games as games_mod
            if games_mod.is_active():
                speech_queue.drop_by_tag("game:after_audio")
        except Exception:
            pass

        # Mid-speech interruption: stop TTS, acknowledge, flush the mic buffer of
        # Rex's voice tail, then WAIT for a fresh VAD rising edge before
        # accumulating. Without this, the rolling buffer still holds ~seconds of
        # Rex's own voice which Whisper concatenates onto the user's utterance.
        if speech_queue.is_speaking() or output_gate.is_busy():
            if _is_interruptible_game_audio_path(direct_audio_path):
                _interrupted.set()
                try:
                    import sounddevice as sd
                    echo_cancel.request_cancel()
                    sd.stop()
                except Exception:
                    pass
                time.sleep(0.1)
                try:
                    echo_cancel.clear_suppression_tail()
                except Exception:
                    pass
                _interrupted.clear()
                speech_start = time.monotonic()
                _last_speech_at = speech_start
                _log.info(
                    "[interaction] interrupted game audio for player speech: %s",
                    direct_audio_path,
                )
            elif not _vad_barge_in_enabled():
                global _last_vad_barge_in_suppressed_log_at
                now = time.monotonic()
                if now - _last_vad_barge_in_suppressed_log_at >= 2.0:
                    _last_vad_barge_in_suppressed_log_at = now
                    _log.info(
                        "[interaction] VAD barge-in suppressed while Rex is speaking; use wake word to interrupt"
                    )
                _end_user_turn()
                _stop_event.wait(_CHUNK_SECS)
                continue
            _interrupted.set()
            try:
                import sounddevice as sd
                echo_cancel.request_cancel()
                sd.stop()
            except Exception:
                pass
            # Brief settle so the worker can clean up its finally block
            time.sleep(0.1)
            _interrupted.clear()
            if direct_audio_path:
                # Non-speech clips/music beds are interruptible: keep the user's
                # current utterance instead of saying "yeah?" and forcing a repeat.
                _log.info("[interaction] direct audio interrupted by user speech: %s", direct_audio_path)
            else:
                _interrupt_ack()

                # Drop the polluted buffer and re-arm. The next user utterance must
                # trigger VAD again; the original speech_start is discarded.
                stream.flush()
                _listen_resume_at = time.monotonic() + config.POST_SPEECH_LISTEN_DELAY_SECS
                _post_tts_flush_needed = True
                _end_user_turn()
                continue

        _dj_restore_volume = _duck_dj_for_speech()
        try:
            # Accumulate the full utterance
            audio_segment = _accumulate_speech(speech_start)
            eager_text = _pop_eager_transcript()
            if audio_segment is None or len(audio_segment) == 0:
                # THE invisible drop (owner 2026-08-05: "he's not hearing my first
                # line"). VAD accepted this turn and the loop committed to it, then
                # it vanished here without a single log line — indistinguishable
                # from the user never speaking. _speech_capture_secs already logs
                # the window-collapse case with numbers; this catches the rest.
                _capture_dropped(
                    "accumulate_returned_none" if audio_segment is None
                    else "accumulate_returned_empty",
                    held_for=f"{time.monotonic() - speech_start:.2f}s",
                    state=str(state_module.get_state()),
                )
                continue

            _capture_outcome("captured")
            _last_speech_at = time.monotonic()
            try:
                _handle_speech_segment(audio_segment, eager_transcript=eager_text)
            except Exception:
                # A turn-handler bug must cost ONE turn, never the ears. Field
                # 2026-08-03 18:00: an AttributeError in the live web.search
                # dispatch propagated here, killed this loop thread, and Rex
                # went stone deaf — repeated queries, "hey R3X", and "shut
                # down" all ignored until a manual GUI shutdown. The wake-word
                # and consciousness threads kept running, which made the
                # failure look like selective hearing instead of a crash.
                _log.exception(
                    "[interaction] speech-segment handler crashed — dropping "
                    "this turn, listening loop continues"
                )
        finally:
            _restore_dj_volume(_dj_restore_volume)
            _end_user_turn()


# ─────────────────────────────────────────────────────────────────────────────
# Lifecycle
# ─────────────────────────────────────────────────────────────────────────────

def start(*, text_only: bool = False) -> None:
    """Start the wake word detector and the continuous interaction loop."""
    global _thread, _identity_prompt_until, _awaiting_followup_event
    global _listen_resume_at, _listen_capture_floor_at, _post_tts_flush_needed
    global _post_question_retro_scan_at
    global _pending_common_first_name_identity, _pending_common_first_name_introduction
    global _pending_existing_common_first_name, _pending_identity_match_confirmation
    global _pending_last_name_confirm
    global _pending_prompted_name_confirmation
    global _text_only_mode, _last_speech_at, _identity_reask_count
    global _last_rex_line_was_question

    if _thread and _thread.is_alive():
        _log.warning("[interaction] already running")
        return

    _text_only_mode = bool(text_only)
    _stop_event.clear()
    _wake_word_fired.clear()
    _interrupted.clear()
    _session_person_ids.clear()
    _session_person_turn_counts.clear()
    _session_warmth_signals.clear()
    _session_router_control_topics.clear()
    _clear_anonymous_speaker_slots()
    _interest_idle_followups_spoken.clear()
    _recently_banned_topics.clear()
    _recent_rex_questions.clear()
    _last_rex_line_was_question = False
    _identity_prompt_until = 0.0
    _identity_reask_count = 0
    _listen_resume_at = 0.0
    _listen_capture_floor_at = 0.0
    _post_tts_flush_needed = False
    _post_question_retro_scan_at = 0.0
    _awaiting_followup_event = None
    _pending_common_first_name_identity = None
    _pending_common_first_name_introduction = None
    _pending_existing_common_first_name = None
    _pending_last_name_confirm = None
    _pending_identity_match_confirmation = None
    _pending_prompted_name_confirmation = None
    _clear_pending_memory_wipe()
    _common_first_name_prompted_this_session.clear()
    topic_thread.clear()
    premise_memory.clear()
    dialogue_act.clear()
    user_energy.clear()
    question_budget.clear()
    repair_moves.clear()
    try:
        conversation_agenda.reset_plans_state()
    except Exception:
        pass
    try:
        from intelligence import callback_engine as _cb_engine
        _cb_engine.clear_session()
        llm.clear_session()  # nostalgia / stale-fact / episodic-callback dedup
    except Exception:
        pass
    end_thread.clear()
    try:
        consciousness.clear_response_wait()
    except Exception:
        pass

    speech_queue.register_on_item_done(_arm_post_tts_window)
    # Note every spoken line at playback START for own-echo rejection — the echo
    # is captured DURING playback, so noting only at item end can lose the race.
    speech_queue.register_on_item_start(_note_rex_spoke_item)
    if _text_only_mode:
        _log.info("[interaction] started in text-only mode; wake word and mic loop disabled")
        return

    wake_word.start(_on_wake_word)
    threading.Thread(
        target=_prefill_wake_ack_cache,
        daemon=True,
        name="wake-ack-cache-prefill",
    ).start()
    threading.Thread(
        target=_prefill_slow_path_ack_cache,
        daemon=True,
        name="slow-path-ack-cache-prefill",
    ).start()
    threading.Thread(
        target=_prefill_motion_route_ack_cache,
        daemon=True,
        name="motion-route-ack-cache-prefill",
    ).start()
    if not wake_word.is_ready():
        _log.warning(
            "[interaction] wake word unavailable — entering ACTIVE fallback so speech can still be processed"
        )
        if state_module.get_state() == State.IDLE:
            state_module.set_state(State.ACTIVE)

    # Starting (or waking) Rex IS activating him — begin in ACTIVE so the conversation
    # loop, and its short re-engagement of a present-but-quiet person, runs from the
    # start instead of sitting in IDLE waiting for a wake word. Empty-room startup
    # self-corrects: with no one present the re-engagement no-ops and the session times
    # out back to IDLE. Seed _last_speech_at so the idle timer starts fresh (no nudge at
    # t=0). Toggle with STARTUP_STATE_ACTIVE.
    if bool(getattr(config, "STARTUP_STATE_ACTIVE", True)) and state_module.get_state() == State.IDLE:
        state_module.set_state(State.ACTIVE)
    _last_speech_at = time.monotonic()

    _thread = threading.Thread(
        target=_loop, daemon=True, name="interaction-loop"
    )
    _thread.start()
    _log.info("[interaction] started")


def stop() -> None:
    """Stop the interaction loop and wake word detector, waiting for clean exit."""
    global _thread, _awaiting_followup_event, _identity_prompt_until
    global _listen_resume_at, _listen_capture_floor_at, _post_tts_flush_needed
    global _post_question_retro_scan_at
    global _pending_introduction, _pending_intro_followup, _pending_intro_voice_capture
    global _pending_common_first_name_identity, _pending_common_first_name_introduction
    global _pending_existing_common_first_name, _pending_identity_match_confirmation
    global _pending_last_name_confirm
    global _pending_prompted_name_confirmation
    global _text_only_mode, _identity_reask_count

    _stop_event.set()
    if not _text_only_mode:
        wake_word.stop()

    if _thread:
        _thread.join(timeout=3.0)
        if _thread.is_alive():
            _log.warning("[interaction] loop thread did not stop cleanly")
        _thread = None

    _awaiting_followup_event = None
    _identity_prompt_until = 0.0
    _identity_reask_count = 0
    _listen_resume_at = 0.0
    _listen_capture_floor_at = 0.0
    _post_tts_flush_needed = False
    _post_question_retro_scan_at = 0.0
    _session_person_turn_counts.clear()
    _session_warmth_signals.clear()
    _recently_banned_topics.clear()
    _recent_rex_questions.clear()
    _pending_introduction = None
    _pending_intro_followup = None
    _pending_intro_voice_capture = None
    _pending_common_first_name_identity = None
    _pending_common_first_name_introduction = None
    _pending_existing_common_first_name = None
    _pending_last_name_confirm = None
    _pending_identity_match_confirmation = None
    _pending_prompted_name_confirmation = None
    _clear_pending_memory_wipe()
    _common_first_name_prompted_this_session.clear()
    _recent_voice_turns.clear()
    _clear_anonymous_speaker_slots()
    topic_thread.clear()
    premise_memory.clear()
    user_energy.clear()
    question_budget.clear()
    repair_moves.clear()
    end_thread.clear()
    try:
        consciousness.clear_response_wait()
    except Exception:
        pass

    _text_only_mode = False
    _log.info("[interaction] stopped")
